-- First shared forward migration: 186.

BEGIN;

DO $gate11$
BEGIN
  IF current_setting('server_version_num')::integer < 170000 THEN
    RAISE EXCEPTION 'GATE11_POSTGRES_17_REQUIRED';
  END IF;
  IF to_regnamespace('auth') IS NULL OR to_regnamespace('storage') IS NULL OR to_regnamespace('extensions') IS NULL THEN
    RAISE EXCEPTION 'GATE11_SUPABASE_PLATFORM_SCHEMAS_REQUIRED';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated')
     OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    RAISE EXCEPTION 'GATE11_SUPABASE_API_ROLES_REQUIRED';
  END IF;
  IF EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind IN ('r','p','v','m','S')
  ) OR EXISTS (SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace WHERE n.nspname='public' AND t.typtype IN ('e','d','c') AND t.typrelid=0) THEN
    RAISE EXCEPTION 'GATE11_BASELINE_ALREADY_PRESENT';
  END IF;
END
$gate11$;

CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA "extensions";
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA "extensions";

-- Neutralize platform creation-time ACL defaults. The approved object ACLs and
-- future-object defaults are restored explicitly by the captured catalog below.
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON TABLES FROM "anon", "authenticated", "service_role";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON SEQUENCES FROM "anon", "authenticated", "service_role";
ALTER DEFAULT PRIVILEGES FOR ROLE "postgres" IN SCHEMA "public" REVOKE ALL ON FUNCTIONS FROM "anon", "authenticated", "service_role";

