CREATE OR REPLACE FUNCTION "public"."accept_evidence_bridge_submission"("p_bridge_link_id" "uuid", "p_collection_request_id" "uuid", "p_evidence_id" "uuid", "p_actor_user_id" "uuid", "p_review_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_review_id uuid;
begin
  v_review_id := public.review_evidence_bridge_submission(p_bridge_link_id, p_collection_request_id, p_evidence_id, 'accepted', p_actor_user_id, p_review_notes);
  update public.evidence_bridge_links set evidence_id = coalesce(p_evidence_id, evidence_id), evidence_status = 'accepted', freshness_status = case when valid_until is not null and valid_until < current_date then 'expired' else 'current' end, updated_by = p_actor_user_id, updated_at = now() where id = p_bridge_link_id;
  update public.evidence_collection_requests set status = 'accepted', completed_at = now(), submitted_evidence_id = coalesce(p_evidence_id, submitted_evidence_id) where id = p_collection_request_id;
  perform public.record_evidence_bridge_event('evidence_bridge_review', v_review_id, 'submission_accepted', coalesce(p_review_notes, 'Evidence bridge submission accepted.'), p_actor_user_id);
  return v_review_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."acknowledge_accreditation_escalation"("p_escalation_id" "uuid", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_clause_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then raise exception 'PATCH35_ESCALATION_ACK_AUTHORITY_REQUIRED'; end if;
  select clause_id into v_clause_id from public.accreditation_workflow_escalations where id = p_escalation_id;
  update public.accreditation_workflow_escalations set escalation_status = 'acknowledged', resolution_notes = coalesce(p_notes, resolution_notes) where id = p_escalation_id;
  perform public.record_accreditation_workflow_event('workflow_escalation', p_escalation_id, v_clause_id, 'escalation_acknowledged', coalesce(p_notes, 'Accreditation workflow escalation acknowledged.'), p_actor_user_id);
  return jsonb_build_object('status','acknowledged','escalation_id',p_escalation_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."acknowledge_clinical_governance_escalation"("p_escalation_id" "uuid", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_target uuid;
begin
  perform public.patch37_service_role_required();
  select escalated_to_user_id into v_target from public.clinical_governance_escalations where id = p_escalation_id;
  if v_target is distinct from p_actor_user_id and not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_ESCALATION_ACK_AUTHORITY_REQUIRED'; end if;
  update public.clinical_governance_escalations set escalation_status = 'acknowledged', acknowledged_at = now(), resolution_notes = coalesce(p_notes, resolution_notes) where id = p_escalation_id;
  perform public.record_clinical_governance_event('clinical_governance_escalation', p_escalation_id, 'clinical_governance_escalation_acknowledged', coalesce(p_notes, 'Clinical governance escalation acknowledged.'), p_actor_user_id);
  return jsonb_build_object('status','acknowledged','escalation_id',p_escalation_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."acknowledge_escalation_event"("p_event_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update public.escalation_events
  set status = 'acknowledged',
      acknowledged_by = auth.uid(),
      acknowledged_at = now(),
      resolution_note = coalesce(p_note, resolution_note)
  where id = p_event_id
    and status = 'open'
    and (public.can_manage_grc() or owner_id = auth.uid());
end;
$$;

CREATE OR REPLACE FUNCTION "public"."acknowledge_training_assignment"("p_assignment_id" "uuid", "p_acknowledgment_text" "text", "p_ip_address" "text", "p_user_agent" "text", "p_evidence_id" "uuid", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ack_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  -- 1. Create the acknowledgment record
  insert into public.training_acknowledgments (assignment_id, user_id, acknowledgment_text, ip_address, user_agent, evidence_id)
  values (p_assignment_id, p_actor_id, p_acknowledgment_text, p_ip_address, p_user_agent, p_evidence_id)
  returning id into v_ack_id;

  -- 2. Mark the parent assignment as completed
  update public.training_assignments
  set status = 'completed', completed_at = now(), completion_evidence_id = p_evidence_id
  where id = p_assignment_id;

  perform public.log_training_event(
    'training_acknowledgments', v_ack_id, 'acknowledged',
    'User acknowledged compliance/SOP program.',
    p_actor_id
  );

  return v_ack_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."activate_document_version"("p_document_id" "uuid", "p_version_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
  v_effective_date date;
  v_expiry_date date;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;

  select document_status into v_old_status
  from public.controlled_documents
  where id = p_document_id
  for update;

  if not found then
    raise exception 'PATCH26_DOCUMENT_NOT_FOUND';
  end if;

  select effective_date, expiry_date into v_effective_date, v_expiry_date
  from public.document_versions
  where id = p_version_id
    and document_id = p_document_id;

  if not found then
    raise exception 'PATCH26_VERSION_NOT_FOUND';
  end if;

  update public.document_versions
  set is_current_version = false
  where document_id = p_document_id
    and id <> p_version_id;

  update public.document_versions
  set is_current_version = true,
      locked_at = coalesce(locked_at, now()),
      locked_by = coalesce(locked_by, p_actor_id)
  where id = p_version_id;

  update public.controlled_documents
  set current_version_id = p_version_id,
      document_status = 'active',
      workflow_stage = 'active',
      effective_date = coalesce(v_effective_date, current_date),
      expiry_date = v_expiry_date,
      active_flag = true,
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_document_id;

  perform public.patch26_write_document_event(p_document_id, p_version_id, 'activated', v_old_status, 'active', p_actor_id, p_note, null);
  return jsonb_build_object('status', 'ok', 'document_id', p_document_id, 'current_version_id', p_version_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."apply_department_import_batch"("p_actor_id" "uuid", "p_organization_id" "uuid", "p_source_filename" "text", "p_import_mode" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_row jsonb;
  v_row_index integer;
  v_row_number integer;
  v_code text;
  v_department_type text;
  v_department_id uuid;
  v_type_errors jsonb := '[]'::jsonb;
  v_type_failed_count integer := 0;
  v_sanitized_rows jsonb;
  v_result jsonb;
begin
  -- The browser cannot call this RPC directly. The authenticated Edge bridge
  -- invokes it with the service-role client after verifying the user.
  if auth.role() <> 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  if p_rows is null or pg_catalog.jsonb_typeof(p_rows) <> 'array' then
    raise exception 'INVALID_ROWS_PAYLOAD';
  end if;

  -- Validate the Excel classification server-side before calling the existing
  -- all-row validation and mutation engine.
  for v_row, v_row_index in
    select item.value, item.ordinality::integer
    from pg_catalog.jsonb_array_elements(p_rows)
      with ordinality as item(value, ordinality)
  loop
    if pg_catalog.jsonb_typeof(v_row) = 'object'
       and pg_catalog.jsonb_typeof(v_row->'raw_data') = 'object' then
      if coalesce(v_row->>'row_number', '') ~ '^[1-9][0-9]*$' then
        v_row_number := (v_row->>'row_number')::integer;
      else
        v_row_number := v_row_index;
      end if;

      v_department_type := pg_catalog.lower(
        pg_catalog.btrim(v_row->'raw_data'->>'department_type')
      );

      if v_department_type is null or v_department_type = '' then
        v_type_errors := v_type_errors || pg_catalog.jsonb_build_object(
          'row_number', v_row_number,
          'errors', pg_catalog.jsonb_build_array('department_type required')
        );
        v_type_failed_count := v_type_failed_count + 1;
      elsif v_department_type not in ('clinical', 'administrative', 'support') then
        v_type_errors := v_type_errors || pg_catalog.jsonb_build_object(
          'row_number', v_row_number,
          'errors', pg_catalog.jsonb_build_array(
            'unsupported department_type: ' || v_department_type
          )
        );
        v_type_failed_count := v_type_failed_count + 1;
      end if;
    end if;
  end loop;

  if v_type_failed_count > 0 then
    return pg_catalog.jsonb_build_object(
      'status', 'rejected',
      'total_rows', pg_catalog.jsonb_array_length(p_rows),
      'failed_count', v_type_failed_count,
      'created_count', 0,
      'updated_count', 0,
      'row_errors', v_type_errors
    );
  end if;

  -- Migration 169 rejected every nonblank department_type because the original
  -- departments schema had no destination column. Remove only that field before
  -- invoking the verified engine; all other row validation remains unchanged.
  select pg_catalog.jsonb_agg(
    case
      when pg_catalog.jsonb_typeof(item.value) = 'object'
       and pg_catalog.jsonb_typeof(item.value->'raw_data') = 'object'
      then pg_catalog.jsonb_set(
        item.value,
        '{raw_data}',
        (item.value->'raw_data') - 'department_type',
        true
      )
      else item.value
    end
    order by item.ordinality
  )
  into v_sanitized_rows
  from pg_catalog.jsonb_array_elements(p_rows)
    with ordinality as item(value, ordinality);

  v_result := public.apply_department_import_batch_v169(
    p_actor_id,
    p_organization_id,
    p_source_filename,
    p_import_mode,
    v_sanitized_rows
  );

  -- A rejected result means the verified engine performed no persistent writes.
  if coalesce(v_result->>'status', '') <> 'success' then
    return v_result;
  end if;

  -- Persist the approved classification in the same transaction. Any error here
  -- rolls back the base import, batch history, role mapping, and audit writes.
  for v_row in
    select item.value
    from pg_catalog.jsonb_array_elements(p_rows) as item(value)
  loop
    v_code := pg_catalog.lower(
      pg_catalog.btrim(v_row->'raw_data'->>'department_code')
    );
    v_department_type := pg_catalog.lower(
      pg_catalog.btrim(v_row->'raw_data'->>'department_type')
    );
    v_department_id := null;

    update public.departments d
    set department_type = v_department_type,
        updated_at = pg_catalog.now()
    where d.organization_id = p_organization_id
      and pg_catalog.lower(pg_catalog.btrim(d.code)) = v_code
    returning d.id into v_department_id;

    if v_department_id is null then
      raise exception 'PATCH83S1_IMPORTED_DEPARTMENT_NOT_FOUND';
    end if;

    insert into public.audit_logs (
      action,
      table_name,
      record_id,
      actor_id,
      organization_id,
      new_data
    ) values (
      'DEPARTMENT_IMPORT_TYPE_SET',
      'departments',
      v_department_id,
      p_actor_id,
      p_organization_id,
      pg_catalog.jsonb_build_object(
        'batch_id', v_result->>'batch_id',
        'source', 'department_import',
        'department_type', v_department_type
      )
    );
  end loop;

  return v_result || pg_catalog.jsonb_build_object(
    'department_type_count',
    pg_catalog.jsonb_array_length(p_rows)
  );
end
$_$;

CREATE OR REPLACE FUNCTION "public"."apply_department_import_batch_v169"("p_actor_id" "uuid", "p_organization_id" "uuid", "p_source_filename" "text", "p_import_mode" "text", "p_rows" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_has_access boolean := false;
  v_mode public.department_import_mode;
  v_row jsonb;
  v_row_index integer;
  v_row_number integer;
  v_code text;
  v_name_en text;
  v_name_ar text;
  v_department_type text;
  v_status text;
  v_manager_email text;
  v_division_code text;
  v_division_id uuid;
  v_manager_id uuid;
  v_manager_ids uuid[];
  v_manager_org_id uuid;
  v_manager_status text;
  v_manager_is_active boolean;
  v_existing_department_id uuid;
  v_existing_department_ids uuid[];
  v_department_created boolean;
  v_manager_role_id uuid;
  v_manager_role_changed boolean;
  v_total_rows integer := 0;
  v_created_count integer := 0;
  v_updated_count integer := 0;
  v_failed_count integer := 0;
  v_affected_ids uuid[] := '{}'::uuid[];
  v_errors text[];
  v_row_errors jsonb := '[]'::jsonb;
  v_batch_id uuid;
  v_seen_codes text[] := '{}'::text[];
begin
  -- The Edge Function is the only supported caller and supplies the validated actor id.
  if auth.role() <> 'service_role' then
    raise exception 'SERVICE_ROLE_REQUIRED';
  end if;

  if p_actor_id is null then
    raise exception 'ACTIVE_ACTOR_REQUIRED';
  end if;

  if p_organization_id is null then
    raise exception 'ORGANIZATION_SCOPE_DENIED';
  end if;

  select exists (
    select 1
    from public.profiles p
    join public.user_roles ur
      on ur.user_id = p.id
     and ur.is_active = true
    where p.id = p_actor_id
      and p.is_active = true
      and p.user_status = 'active'
      and p.organization_id = p_organization_id
      and ur.role in (
        'super_admin'::public.app_role,
        'governance_admin'::public.app_role
      )
      and ur.scope = 'global'::public.access_scope
      and (
        ur.organization_id is null
        or ur.organization_id = p_organization_id
      )
  ) into v_has_access;

  if not v_has_access then
    raise exception 'UNAUTHORIZED_DEPARTMENT_IMPORT';
  end if;

  if p_source_filename is null or pg_catalog.btrim(p_source_filename) = '' then
    raise exception 'SOURCE_FILENAME_REQUIRED';
  end if;

  if p_rows is null or pg_catalog.jsonb_typeof(p_rows) <> 'array' then
    raise exception 'INVALID_ROWS_PAYLOAD';
  end if;

  v_total_rows := pg_catalog.jsonb_array_length(p_rows);
  if v_total_rows = 0 then
    raise exception 'BATCH_EMPTY';
  end if;
  if v_total_rows > 5000 then
    raise exception 'BATCH_EXCEEDS_MAX_ROWS';
  end if;

  begin
    v_mode := p_import_mode::public.department_import_mode;
  exception when others then
    raise exception 'INVALID_IMPORT_MODE';
  end;

  -- Phase A: validate every row without persisting raw input or changing data.
  for v_row, v_row_index in
    select item.value, item.ordinality::integer
    from pg_catalog.jsonb_array_elements(p_rows) with ordinality as item(value, ordinality)
  loop
    v_errors := '{}'::text[];
    v_division_id := null;
    v_manager_id := null;
    v_manager_ids := null;
    v_existing_department_id := null;
    v_existing_department_ids := null;

    if pg_catalog.jsonb_typeof(v_row) is distinct from 'object' then
      v_row_number := v_row_index;
      v_errors := pg_catalog.array_append(v_errors, 'row must be an object');
      v_code := null;
      v_name_en := null;
      v_name_ar := null;
      v_department_type := null;
      v_status := null;
      v_manager_email := null;
      v_division_code := null;
    else
      if coalesce(v_row->>'row_number', '') ~ '^[1-9][0-9]*$' then
        v_row_number := (v_row->>'row_number')::integer;
      else
        v_row_number := v_row_index;
        v_errors := pg_catalog.array_append(v_errors, 'row_number must be a positive integer');
      end if;

      if pg_catalog.jsonb_typeof(v_row->'raw_data') is distinct from 'object' then
        v_errors := pg_catalog.array_append(v_errors, 'raw_data must be an object');
      end if;

      v_code := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'department_code'));
      v_name_en := pg_catalog.btrim(v_row->'raw_data'->>'department_name_en');
      v_name_ar := pg_catalog.btrim(v_row->'raw_data'->>'department_name_ar');
      v_department_type := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'department_type'));
      v_status := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'status'));
      v_manager_email := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'manager_email'));
      v_division_code := pg_catalog.btrim(v_row->'raw_data'->>'division_code');
    end if;

    if v_code is null or v_code = '' then
      v_errors := pg_catalog.array_append(v_errors, 'department_code required');
    end if;
    if v_name_en is null or v_name_en = '' then
      v_errors := pg_catalog.array_append(v_errors, 'department_name_en required');
    end if;
    if v_status is not null and v_status <> '' and v_status not in ('active', 'inactive') then
      v_errors := pg_catalog.array_append(v_errors, 'invalid status');
    end if;

    -- Core departments has no type column or verified type relation.
    if v_department_type is not null and v_department_type <> '' then
      v_errors := pg_catalog.array_append(v_errors, 'department_type unsupported by canonical departments schema');
    end if;

    if v_code is not null and v_code <> '' then
      if v_code = any(v_seen_codes) then
        v_errors := pg_catalog.array_append(v_errors, 'duplicate code in batch');
      else
        v_seen_codes := pg_catalog.array_append(v_seen_codes, v_code);
      end if;

      select pg_catalog.array_agg(d.id order by d.is_active desc, d.created_at, d.id)
      into v_existing_department_ids
      from public.departments d
      where d.organization_id = p_organization_id
        and pg_catalog.lower(pg_catalog.btrim(d.code)) = v_code;

      if coalesce(pg_catalog.cardinality(v_existing_department_ids), 0) > 1 then
        v_errors := pg_catalog.array_append(v_errors, 'ambiguous department identity');
      elsif pg_catalog.cardinality(v_existing_department_ids) = 1 then
        v_existing_department_id := v_existing_department_ids[1];
        if v_mode = 'create_only' then
          v_errors := pg_catalog.array_append(v_errors, 'department already exists (create_only mode)');
        end if;
      end if;
    end if;

    if v_division_code is not null and v_division_code <> '' then
      select d.id
      into v_division_id
      from public.divisions d
      where d.organization_id = p_organization_id
        and pg_catalog.lower(pg_catalog.btrim(d.code)) = pg_catalog.lower(v_division_code)
        and d.is_active = true
      limit 1;

      if v_division_id is null then
        v_errors := pg_catalog.array_append(v_errors, 'invalid division');
      end if;
    end if;

    -- Manager authority is represented by a department-scoped user_roles row.
    if v_manager_email is not null and v_manager_email <> '' then
      select pg_catalog.array_agg(p.id order by p.id)
      into v_manager_ids
      from public.profiles p
      where pg_catalog.lower(p.email) = v_manager_email;

      if coalesce(pg_catalog.cardinality(v_manager_ids), 0) = 0 then
        v_errors := pg_catalog.array_append(v_errors, 'manager not found');
      elsif pg_catalog.cardinality(v_manager_ids) > 1 then
        v_errors := pg_catalog.array_append(v_errors, 'manager email ambiguous');
      else
        v_manager_id := v_manager_ids[1];
        select p.organization_id, p.user_status, p.is_active
        into v_manager_org_id, v_manager_status, v_manager_is_active
        from public.profiles p
        where p.id = v_manager_id;

        if v_manager_org_id is distinct from p_organization_id then
          v_errors := pg_catalog.array_append(v_errors, 'manager outside organization');
        elsif v_manager_status <> 'active' or v_manager_is_active <> true then
          v_errors := pg_catalog.array_append(v_errors, 'manager inactive');
        end if;
      end if;
    end if;

    if pg_catalog.cardinality(v_errors) > 0 then
      v_row_errors := v_row_errors || pg_catalog.jsonb_build_object(
        'row_number', v_row_number,
        'errors', pg_catalog.to_jsonb(v_errors)
      );
      v_failed_count := v_failed_count + 1;
    end if;
  end loop;

  if v_failed_count > 0 then
    return pg_catalog.jsonb_build_object(
      'status', 'rejected',
      'total_rows', v_total_rows,
      'failed_count', v_failed_count,
      'created_count', 0,
      'updated_count', 0,
      'row_errors', v_row_errors
    );
  end if;

  -- Phase B: all rows are valid; subsequent errors roll back the whole function call.
  insert into public.department_import_batches (
    organization_id,
    initiated_by,
    source_filename,
    import_mode,
    status,
    total_rows
  ) values (
    p_organization_id,
    p_actor_id,
    pg_catalog.left(pg_catalog.btrim(p_source_filename), 255),
    v_mode,
    'processing',
    v_total_rows
  ) returning id into v_batch_id;

  for v_row in select item.value from pg_catalog.jsonb_array_elements(p_rows) as item(value)
  loop
    v_code := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'department_code'));
    v_name_en := pg_catalog.btrim(v_row->'raw_data'->>'department_name_en');
    v_name_ar := pg_catalog.btrim(v_row->'raw_data'->>'department_name_ar');
    v_status := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'status'));
    v_manager_email := pg_catalog.lower(pg_catalog.btrim(v_row->'raw_data'->>'manager_email'));
    v_division_code := pg_catalog.btrim(v_row->'raw_data'->>'division_code');
    v_division_id := null;
    v_manager_id := null;
    v_existing_department_id := null;
    v_department_created := false;
    v_manager_role_id := null;
    v_manager_role_changed := false;

    select d.id
    into v_existing_department_id
    from public.departments d
    where d.organization_id = p_organization_id
      and pg_catalog.lower(pg_catalog.btrim(d.code)) = v_code
    order by d.is_active desc, d.created_at, d.id
    limit 1
    for update;

    if v_existing_department_id is not null then
      update public.departments
      set name_en = coalesce(nullif(v_name_en, ''), name_en),
          name_ar = coalesce(nullif(v_name_ar, ''), name_ar),
          is_active = case
            when v_status = 'active' then true
            when v_status = 'inactive' then false
            else is_active
          end,
          updated_at = pg_catalog.now()
      where id = v_existing_department_id;

      v_updated_count := v_updated_count + 1;
    else
      if v_division_code is not null and v_division_code <> '' then
        select d.id
        into v_division_id
        from public.divisions d
        where d.organization_id = p_organization_id
          and pg_catalog.lower(pg_catalog.btrim(d.code)) = pg_catalog.lower(v_division_code)
          and d.is_active = true
        limit 1;
      end if;

      insert into public.departments (
        organization_id,
        division_id,
        code,
        name_en,
        name_ar,
        is_active
      ) values (
        p_organization_id,
        v_division_id,
        v_code,
        v_name_en,
        nullif(v_name_ar, ''),
        v_status is distinct from 'inactive'
      ) returning id into v_existing_department_id;

      v_created_count := v_created_count + 1;
      v_department_created := true;
    end if;

    v_affected_ids := pg_catalog.array_append(v_affected_ids, v_existing_department_id);

    if v_manager_email is not null and v_manager_email <> '' then
      select p.id
      into v_manager_id
      from public.profiles p
      where pg_catalog.lower(p.email) = v_manager_email;

      select ur.id
      into v_manager_role_id
      from public.user_roles ur
      where ur.user_id = v_manager_id
        and ur.role = 'department_manager'::public.app_role
        and ur.department_id = v_existing_department_id
        and ur.is_active = true
        and (ur.organization_id is null or ur.organization_id = p_organization_id)
      order by ur.assigned_at desc, ur.id
      limit 1;

      if v_manager_role_id is null then
        select ur.id
        into v_manager_role_id
        from public.user_roles ur
        where ur.user_id = v_manager_id
          and ur.role = 'department_manager'::public.app_role
          and ur.scope = 'department'::public.access_scope
          and ur.organization_id = p_organization_id
          and ur.department_id = v_existing_department_id
          and ur.division_id is null
          and ur.unit_id is null
          and ur.is_active = false
        order by ur.assigned_at desc, ur.id
        limit 1
        for update;

        if v_manager_role_id is not null then
          update public.user_roles
          set is_active = true,
              assigned_by = p_actor_id,
              assigned_at = pg_catalog.now()
          where id = v_manager_role_id;
        else
          insert into public.user_roles (
            user_id,
            role,
            scope,
            organization_id,
            division_id,
            department_id,
            unit_id,
            is_active,
            assigned_by
          ) values (
            v_manager_id,
            'department_manager'::public.app_role,
            'department'::public.access_scope,
            p_organization_id,
            null,
            v_existing_department_id,
            null,
            true,
            p_actor_id
          ) returning id into v_manager_role_id;
        end if;

        v_manager_role_changed := true;
      end if;
    end if;

    insert into public.audit_logs (
      action,
      table_name,
      record_id,
      actor_id,
      organization_id,
      new_data
    ) values (
      case
        when v_department_created then 'DEPARTMENT_IMPORTED_CREATE'
        else 'DEPARTMENT_IMPORTED_UPDATE'
      end,
      'departments',
      v_existing_department_id,
      p_actor_id,
      p_organization_id,
      pg_catalog.jsonb_build_object(
        'batch_id', v_batch_id,
        'source', 'department_import',
        'code', v_code
      )
    );

    if v_manager_role_changed then
      insert into public.audit_logs (
        action,
        table_name,
        record_id,
        actor_id,
        organization_id,
        new_data
      ) values (
        'DEPARTMENT_MANAGER_ROLE_ASSIGNED',
        'user_roles',
        v_manager_role_id,
        p_actor_id,
        p_organization_id,
        pg_catalog.jsonb_build_object(
          'batch_id', v_batch_id,
          'department_id', v_existing_department_id,
          'manager_user_id', v_manager_id
        )
      );
    end if;
  end loop;

  update public.department_import_batches
  set status = 'completed',
      created_count = v_created_count,
      updated_count = v_updated_count,
      failed_count = 0,
      affected_department_ids = v_affected_ids,
      completed_at = pg_catalog.now()
  where id = v_batch_id;

  return pg_catalog.jsonb_build_object(
    'status', 'success',
    'batch_id', v_batch_id,
    'total_rows', v_total_rows,
    'created_count', v_created_count,
    'updated_count', v_updated_count,
    'failed_count', 0,
    'affected_department_ids', v_affected_ids
  );
end;
$_$;

CREATE OR REPLACE FUNCTION "public"."approve_accreditation_clause_task"("p_task_id" "uuid", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_clause_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then raise exception 'PATCH35_REVIEW_AUTHORITY_REQUIRED'; end if;
  select clause_id into v_clause_id from public.accreditation_clause_review_tasks where id = p_task_id;
  update public.accreditation_clause_review_tasks set status = 'approved', reviewed_at = now(), reviewed_by = p_actor_user_id, outcome_notes = coalesce(p_notes, outcome_notes) where id = p_task_id;
  perform public.record_accreditation_workflow_event('review_task', p_task_id, v_clause_id, 'task_approved', coalesce(p_notes, 'Accreditation clause task approved.'), p_actor_user_id);
  return jsonb_build_object('status','approved','task_id',p_task_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."approve_capa_action_plan"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'action_plan_approved', workflow_stage = 'approved', approver_id = coalesce(approver_id, p_actor_id), updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'action_plan_approved', v_old, 'action_plan_approved', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."approve_capa_closure"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text; v_blocker text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select blocker_reason into v_blocker from public.v_patch28_capa_closure_blockers where capa_id = p_capa_id and can_close = false limit 1;
  if v_blocker is not null then
    update public.capa_action_plans set closure_blocker = v_blocker, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
    raise exception 'PATCH28_CAPA_CLOSURE_BLOCKED: %', v_blocker;
  end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'closed', workflow_stage = 'closed', completed_at = coalesce(completed_at, now()), closure_approved_at = now(), closure_approved_by = p_actor_id, closed_at = now(), closure_blocker = null, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'closure_approved', v_old, 'closed', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id,'capa_status','closed');
end $$;

CREATE OR REPLACE FUNCTION "public"."approve_capa_due_date_extension"("p_extension_id" "uuid", "p_actor_id" "uuid", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_capa_id uuid; v_due date;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  update public.capa_due_date_extensions set extension_status = 'approved', reviewed_by = p_actor_id, reviewed_at = now(), review_note = p_review_note where id = p_extension_id returning capa_id, requested_due_date into v_capa_id, v_due;
  if not found then raise exception 'PATCH28_EXTENSION_NOT_FOUND'; end if;
  update public.capa_action_plans set revised_due_date = v_due, due_date = v_due, updated_by = p_actor_id, updated_at = now() where id = v_capa_id;
  perform public.patch28_write_capa_event(v_capa_id, null, 'extension_approved', null, 'approved', p_actor_id, p_review_note, null);
  return jsonb_build_object('status','ok','extension_id',p_extension_id,'due_date',v_due);
end $$;

CREATE OR REPLACE FUNCTION "public"."approve_document_version"("p_document_id" "uuid", "p_version_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;

  select document_status into v_old_status
  from public.controlled_documents
  where id = p_document_id
  for update;

  if not found then
    raise exception 'PATCH26_DOCUMENT_NOT_FOUND';
  end if;

  update public.document_versions
  set approved_by = p_actor_id,
      approved_at = now()
  where id = p_version_id
    and document_id = p_document_id;

  if not found then
    raise exception 'PATCH26_VERSION_NOT_FOUND';
  end if;

  update public.controlled_documents
  set document_status = 'approved',
      workflow_stage = 'approval',
      approver_id = coalesce(approver_id, p_actor_id),
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_document_id;

  perform public.patch26_write_document_event(p_document_id, p_version_id, 'approved', v_old_status, 'approved', p_actor_id, p_note, null);
  return jsonb_build_object('status', 'ok', 'document_id', p_document_id, 'document_status', 'approved');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."approve_evidence_gate_waiver"("p_waiver_id" "uuid", "p_actor_user_id" "uuid", "p_audit_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_entity_type text;
  v_entity_id uuid;
begin
  perform public.patch43_service_role_required();
  if not public.patch43_actor_has_authority(p_actor_user_id) then
    raise exception 'Actor is not authorized to approve evidence gate waivers';
  end if;

  update public.evidence_gate_waivers
  set waiver_status = 'approved',
      status = 'approved',
      approved_by = p_actor_user_id,
      approved_at = now(),
      audit_note = coalesce(p_audit_note, audit_note)
  where id = p_waiver_id
  returning coalesce(entity_type, linked_item_type), coalesce(entity_id, linked_item_id)
  into v_entity_type, v_entity_id;

  insert into public.survey_readiness_events(entity_type, entity_id, event_type, event_summary, event_payload, actor_user_id)
  values (v_entity_type, v_entity_id, 'waiver_approved', coalesce(p_audit_note, 'Evidence gate waiver approved.'), jsonb_build_object('waiver_id', p_waiver_id), p_actor_user_id);

  return p_waiver_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."approve_runtime_rpc_for_production"("p_rpc_name" "text", "p_actor_user_id" "uuid", "p_signoff_notes" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH31_SERVICE_ROLE_REQUIRED';
  end if;
  if not public.patch31_actor_has_security_authority(p_actor_user_id) then
    raise exception 'PATCH31_SECURITY_AUTHORITY_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_signoff_notes, '')), '') is null then
    raise exception 'PATCH31_SIGNOFF_NOTES_REQUIRED';
  end if;
  update public.runtime_rpc_classifications
  set signoff_status = 'approved_for_production',
      allowed_frontend_use = true,
      reviewed_by = p_actor_user_id,
      reviewed_at = now(),
      signoff_notes = p_signoff_notes,
      bridge_validation_status = case
        when frontend_transport = 'authenticated_edge_bridge' then 'authenticated_bridge_present'
        when frontend_transport = 'direct_browser_rpc' and requires_authenticated_bridge = false then 'not_required'
        else bridge_validation_status
      end,
      updated_at = now()
  where rpc_name = p_rpc_name
    and not (service_role_only = true and frontend_transport = 'direct_browser_rpc')
    and not (requires_authenticated_bridge = true and frontend_transport <> 'authenticated_edge_bridge');
  if not found then raise exception 'PATCH31_RPC_APPROVAL_BLOCKED_OR_NOT_FOUND'; end if;
  perform public.record_runtime_rpc_signoff_event(p_rpc_name, 'approved', 'Runtime RPC approved for production.', p_actor_user_id);
  return jsonb_build_object('status','ok','rpc_name',p_rpc_name,'signoff_status','approved_for_production');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."assess_accreditation_clause"("p_clause_id" "uuid", "p_assessment_status" "text", "p_evidence_status" "text", "p_readiness_score" numeric, "p_actor_user_id" "uuid", "p_assessment_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assessment_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  insert into public.accreditation_clause_assessments (clause_id, assessment_status, readiness_score, evidence_status, assessment_notes, assessed_by)
  values (p_clause_id, p_assessment_status, p_readiness_score, p_evidence_status, p_assessment_notes, p_actor_user_id)
  returning id into v_assessment_id;
  perform public.record_accreditation_traceability_event(p_clause_id, 'accreditation_clause_assessment', v_assessment_id, 'clause_assessed', coalesce(p_assessment_notes, 'Accreditation clause assessed.'), p_actor_user_id);
  return v_assessment_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."assign_accreditation_clause_owner"("p_clause_id" "uuid", "p_owner_user_id" "uuid", "p_owner_department_id" "uuid", "p_reviewer_user_id" "uuid", "p_reviewer_department_id" "uuid", "p_due_date" "date", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_ACCREDITATION_WORKFLOW_AUTHORITY_REQUIRED';
  end if;

  update public.accreditation_clause_owner_assignments
  set active = false, assignment_status = 'transferred'
  where clause_id = p_clause_id and active = true;

  insert into public.accreditation_clause_owner_assignments (
    clause_id, owner_user_id, owner_department_id, reviewer_user_id, reviewer_department_id,
    assigned_by, due_date, notes
  ) values (
    p_clause_id, p_owner_user_id, p_owner_department_id, p_reviewer_user_id, p_reviewer_department_id,
    p_actor_user_id, p_due_date, p_notes
  )
  returning id into v_assignment_id;

  perform public.record_accreditation_workflow_event('owner_assignment', v_assignment_id, p_clause_id, 'owner_assigned', 'Accreditation clause owner assigned.', p_actor_user_id);
  return v_assignment_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."assign_capa_action_plan"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_owner_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'assigned', workflow_stage = 'assigned', capa_owner_id = p_owner_id, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'assigned', v_old, 'assigned', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id,'capa_status','assigned');
end $$;

CREATE OR REPLACE FUNCTION "public"."assign_ovr_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.ovr_number is null or trim(new.ovr_number) = '' then
    new.ovr_number := 'OVR-' || to_char(now(), 'YYYY') || '-' || lpad(nextval('public.ovr_number_seq')::text, 5, '0');
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."assign_ovr_number"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."assign_training_program_to_department"("p_program_id" "uuid", "p_department_id" "uuid", "p_due_date" "date", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_count integer := 0;
  v_user_row record;
  v_assignment_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  for v_user_row in
    select id from public.profiles where department_id = p_department_id and is_active = true
  loop
    insert into public.training_assignments (program_id, assigned_to_user_id, assigned_to_department_id, due_date, assigned_by)
    values (p_program_id, v_user_row.id, p_department_id, p_due_date, p_actor_id)
    returning id into v_assignment_id;

    perform public.log_training_event(
      'training_assignments', v_assignment_id, 'assigned',
      'Training assignment created via department ' || p_department_id || ' rollout.',
      p_actor_id
    );

    v_count := v_count + 1;
  end loop;

  return jsonb_build_object('status', 'ok', 'assigned_count', v_count);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."assign_training_program_to_user"("p_program_id" "uuid", "p_user_id" "uuid", "p_due_date" "date", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assignment_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.training_assignments (program_id, assigned_to_user_id, due_date, assigned_by)
  values (p_program_id, p_user_id, p_due_date, p_actor_id)
  returning id into v_assignment_id;

  perform public.log_training_event(
    'training_assignments', v_assignment_id, 'assigned',
    'Training assignment created for user ' || p_user_id || '.',
    p_actor_id
  );

  return v_assignment_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."assign_user_role"("p_user_id" "uuid", "p_role" "public"."app_role", "p_scope" "public"."access_scope" DEFAULT 'assigned_only'::"public"."access_scope", "p_organization_id" "uuid" DEFAULT NULL::"uuid", "p_division_id" "uuid" DEFAULT NULL::"uuid", "p_department_id" "uuid" DEFAULT NULL::"uuid", "p_unit_id" "uuid" DEFAULT NULL::"uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing_id uuid;
  v_role_id uuid;
  v_org_id uuid;
begin
  if not can_manage_roles() then
    raise exception 'Not allowed to manage user roles';
  end if;

  select organization_id into v_org_id
  from profiles
  where id = p_user_id;

  v_org_id := coalesce(p_organization_id, v_org_id);

  if p_scope = 'global' and p_organization_id is null and v_org_id is null then
    raise exception 'Global role requires organization_id when user profile has no organization';
  end if;

  if p_scope = 'division' and p_division_id is null then
    raise exception 'Division scoped role requires division_id';
  end if;

  if p_scope = 'department' and p_department_id is null then
    raise exception 'Department scoped role requires department_id';
  end if;

  if p_scope = 'unit' and p_unit_id is null then
    raise exception 'Unit scoped role requires unit_id';
  end if;

  select id into v_existing_id
  from user_roles
  where user_id = p_user_id
    and role = p_role
    and scope = p_scope
    and coalesce(organization_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(v_org_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and coalesce(division_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(p_division_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and coalesce(department_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(p_department_id, '00000000-0000-0000-0000-000000000000'::uuid)
    and coalesce(unit_id, '00000000-0000-0000-0000-000000000000'::uuid) = coalesce(p_unit_id, '00000000-0000-0000-0000-000000000000'::uuid)
  limit 1;

  if v_existing_id is not null then
    update user_roles
    set is_active = true,
        assigned_by = auth.uid(),
        assigned_at = now()
    where id = v_existing_id
    returning id into v_role_id;

    insert into role_change_audit (organization_id, target_user_id, user_role_id, action, new_data, reason, changed_by)
    select v_org_id, p_user_id, v_role_id, 'reactivated', to_jsonb(ur), p_reason, auth.uid()
    from user_roles ur
    where ur.id = v_role_id;

    return v_role_id;
  end if;

  insert into user_roles (
    user_id,
    role,
    scope,
    organization_id,
    division_id,
    department_id,
    unit_id,
    is_active,
    assigned_by
  ) values (
    p_user_id,
    p_role,
    p_scope,
    v_org_id,
    p_division_id,
    p_department_id,
    p_unit_id,
    true,
    auth.uid()
  )
  returning id into v_role_id;

  insert into role_change_audit (organization_id, target_user_id, user_role_id, action, new_data, reason, changed_by)
  select v_org_id, p_user_id, v_role_id, 'assigned', to_jsonb(ur), p_reason, auth.uid()
  from user_roles ur
  where ur.id = v_role_id;

  return v_role_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."audit_log_row_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  org_id uuid;
begin
  org_id := coalesce((to_jsonb(new)->>'organization_id')::uuid, (to_jsonb(old)->>'organization_id')::uuid);

  insert into public.audit_logs (
    organization_id,
    actor_id,
    action,
    table_name,
    record_id,
    old_data,
    new_data
  ) values (
    org_id,
    auth.uid(),
    tg_op,
    tg_table_name,
    coalesce((to_jsonb(new)->>'id')::uuid, (to_jsonb(old)->>'id')::uuid),
    case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end,
    case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end
  );

  return coalesce(new, old);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."calculate_kri_breach_level"("p_direction" "public"."kri_direction", "p_value" numeric, "p_watch" numeric, "p_warning" numeric, "p_critical" numeric, "p_lower" numeric, "p_upper" numeric) RETURNS "public"."breach_level"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if p_direction = 'higher_is_worse' then
    if p_critical is not null and p_value >= p_critical then return 'critical'; end if;
    if p_warning is not null and p_value >= p_warning then return 'warning'; end if;
    if p_watch is not null and p_value >= p_watch then return 'watch'; end if;
    return 'normal';
  elsif p_direction = 'lower_is_worse' then
    if p_critical is not null and p_value <= p_critical then return 'critical'; end if;
    if p_warning is not null and p_value <= p_warning then return 'warning'; end if;
    if p_watch is not null and p_value <= p_watch then return 'watch'; end if;
    return 'normal';
  else
    if (p_lower is not null and p_value < p_lower) or (p_upper is not null and p_value > p_upper) then
      return 'warning';
    end if;
    return 'normal';
  end if;
end;
$$;

COMMENT ON FUNCTION "public"."calculate_kri_breach_level"("p_direction" "public"."kri_direction", "p_value" numeric, "p_watch" numeric, "p_warning" numeric, "p_critical" numeric, "p_lower" numeric, "p_upper" numeric) IS 'Gate 9R category B: SECURITY INVOKER authenticated read/helper surface; fixed search_path; anon/PUBLIC denied.';

CREATE OR REPLACE FUNCTION "public"."can_access_org"("target_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select target_org_id = public.current_user_org_id()
     or public.has_global_role(array['super_admin','executive','governance_admin','auditor','compliance_officer']::public.app_role[]);
$$;

CREATE OR REPLACE FUNCTION "public"."can_access_scope"("target_org_id" "uuid", "target_division_id" "uuid", "target_department_id" "uuid", "target_unit_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = auth.uid()
      and ur.is_active = true
      and (
        ur.scope = 'global'
        or (ur.scope = 'division' and ur.division_id is not distinct from target_division_id)
        or (ur.scope = 'department' and ur.department_id is not distinct from target_department_id)
        or (ur.scope = 'unit' and ur.unit_id is not distinct from target_unit_id)
      )
      and (
        ur.organization_id is null
        or ur.organization_id is not distinct from target_org_id
        or target_org_id = public.current_user_org_id()
      )
  );
$$;

CREATE OR REPLACE FUNCTION "public"."can_close_ovr"("p_ovr_report_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.ovr_reports o
    where o.id = p_ovr_report_id
      and (
        o.evidence_required = false
        or exists (
          select 1
          from public.evidence_files e
          where e.ovr_report_id = o.id
            and e.status = 'accepted'
        )
        or exists (
          select 1
          from public.projects p
          where p.id = o.linked_project_id
            and p.status = 'closed'
        )
      )
  );
$$;

CREATE OR REPLACE FUNCTION "public"."can_manage_grc"() RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select public.has_any_role(array['super_admin','executive','governance_admin','auditor','compliance_officer']::public.app_role[]);
$$;

CREATE OR REPLACE FUNCTION "public"."can_manage_roles"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select has_active_role('super_admin'::app_role)
      or has_active_role('executive'::app_role)
      or has_active_role('governance_admin'::app_role);
$$;

CREATE OR REPLACE FUNCTION "public"."can_read_organization"("target_org_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select public.can_access_org(target_org_id);
$$;

CREATE OR REPLACE FUNCTION "public"."cancel_approval_request"("p_approval_request_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
  v_rule_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;

  select request_status, authority_rule_id into v_old_status, v_rule_id
  from public.approval_requests
  where id = p_approval_request_id
  for update;

  if not found then
    raise exception 'PATCH27_APPROVAL_REQUEST_NOT_FOUND';
  end if;

  update public.approval_requests
  set request_status = 'cancelled',
      final_decision = 'cancelled',
      final_decision_by = p_actor_id,
      final_decision_at = now(),
      final_decision_note = p_note,
      updated_at = now()
  where id = p_approval_request_id;

  perform public.patch27_write_authority_event(p_approval_request_id, v_rule_id, 'cancelled', v_old_status, 'cancelled', p_actor_id, p_note);
  return jsonb_build_object('status', 'ok', 'approval_request_id', p_approval_request_id, 'request_status', 'cancelled');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."cancel_capa_with_reason"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_cancel_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  if nullif(trim(coalesce(p_cancel_reason,'')), '') is null then raise exception 'PATCH28_CANCEL_REASON_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'cancelled', workflow_stage = 'cancelled', cancelled_at = now(), cancelled_by = p_actor_id, cancel_reason = p_cancel_reason, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'cancelled', v_old, 'cancelled', p_actor_id, p_cancel_reason, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."cancel_training_assignment_with_reason"("p_assignment_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.training_assignments
  set status = 'cancelled'
  where id = p_assignment_id;

  if not found then
    raise exception 'PATCH29_ASSIGNMENT_NOT_CANCELLABLE';
  end if;

  perform public.log_training_event(
    'training_assignments', p_assignment_id, 'cancelled',
    'Assignment cancelled with reason: ' || p_reason,
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."check_user_approval_authority"("p_user_id" "uuid", "p_organization_id" "uuid", "p_workflow_type" "text", "p_action_type" "text", "p_department_id" "uuid" DEFAULT NULL::"uuid", "p_role_name" "text" DEFAULT NULL::"text") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.approval_authority_rules r
    where r.organization_id = p_organization_id
      and r.active_flag = true
      and r.workflow_type = p_workflow_type
      and r.action_type = p_action_type
      and (r.effective_date is null or r.effective_date <= current_date)
      and (r.expiry_date is null or r.expiry_date >= current_date)
      and (r.department_id is null or r.department_id is not distinct from p_department_id)
      and (
        r.approver_user_id = p_user_id
        or (r.approver_role is not null and exists (
          select 1
          from public.user_roles ur
          where ur.user_id = p_user_id
            and ur.is_active = true
            and ur.role::text = r.approver_role
            and (ur.organization_id is null or ur.organization_id is not distinct from p_organization_id)
        ))
        or (r.approver_role is null and r.role_name is not null and r.role_name = p_role_name)
        or exists (
          select 1
          from public.approval_delegations d
          where d.organization_id = p_organization_id
            and d.delegate_id = p_user_id
            and d.active_flag = true
            and d.effective_from <= now()
            and d.effective_to >= now()
            and (d.workflow_type is null or d.workflow_type = p_workflow_type)
            and (d.action_type is null or d.action_type = p_action_type)
            and (d.department_id is null or d.department_id is not distinct from p_department_id)
            and (
              d.delegator_id = r.approver_user_id
              or exists (
                select 1
                from public.user_roles ur2
                where ur2.user_id = d.delegator_id
                  and ur2.is_active = true
                  and ur2.role::text = r.approver_role
                  and (ur2.organization_id is null or ur2.organization_id is not distinct from p_organization_id)
              )
            )
        )
      )
  );
$$;

CREATE OR REPLACE FUNCTION "public"."classify_runtime_rpc"("p_rpc_name" "text", "p_frontend_transport" "text", "p_classification" "text", "p_risk_level" "text", "p_allowed_frontend_use" boolean, "p_requires_authenticated_bridge" boolean, "p_service_role_only" boolean, "p_actor_user_id" "uuid", "p_signoff_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH31_SERVICE_ROLE_REQUIRED';
  end if;
  if not public.patch31_actor_has_security_authority(p_actor_user_id) then
    raise exception 'PATCH31_SECURITY_AUTHORITY_REQUIRED';
  end if;
  insert into public.runtime_rpc_classifications (
    rpc_name,
    frontend_transport,
    classification,
    risk_level,
    allowed_frontend_use,
    requires_authenticated_bridge,
    service_role_only,
    reviewed_by,
    reviewed_at,
    signoff_status,
    signoff_notes,
    bridge_validation_status
  )
  values (
    p_rpc_name,
    p_frontend_transport,
    p_classification,
    p_risk_level,
    p_allowed_frontend_use,
    p_requires_authenticated_bridge,
    p_service_role_only,
    p_actor_user_id,
    now(),
    case
      when p_classification = 'privileged_admin_review' then 'privileged_admin_review'
      when p_classification = 'workflow_runtime_review' then 'workflow_runtime_review'
      when p_classification = 'pending_security_review' then 'pending_security_review'
      else 'pending_review'
    end,
    p_signoff_notes,
    case
      when p_frontend_transport = 'authenticated_edge_bridge' then 'authenticated_bridge_present'
      when p_frontend_transport = 'direct_browser_rpc' and not p_requires_authenticated_bridge then 'not_required'
      else 'pending_validation'
    end
  )
  on conflict (rpc_name) do update set
    frontend_transport = excluded.frontend_transport,
    classification = excluded.classification,
    risk_level = excluded.risk_level,
    allowed_frontend_use = excluded.allowed_frontend_use,
    requires_authenticated_bridge = excluded.requires_authenticated_bridge,
    service_role_only = excluded.service_role_only,
    reviewed_by = excluded.reviewed_by,
    reviewed_at = excluded.reviewed_at,
    signoff_status = excluded.signoff_status,
    signoff_notes = excluded.signoff_notes,
    bridge_validation_status = excluded.bridge_validation_status,
    updated_at = now();
  perform public.record_runtime_rpc_signoff_event(p_rpc_name, 'classified', 'Runtime RPC classification updated.', p_actor_user_id);
  return jsonb_build_object('status','ok','rpc_name',p_rpc_name);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."close_audit_execution_engagement"("p_engagement_id" "uuid", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_AUTHORITY_REQUIRED'; end if;
  update public.audit_execution_engagements set status = 'closed', closed_at = now() where id = p_engagement_id;
  perform public.record_clinical_governance_event('audit_engagement', p_engagement_id, 'audit_engagement_closed', coalesce(p_notes, 'Audit execution engagement closed.'), p_actor_user_id);
  return jsonb_build_object('status','closed','engagement_id',p_engagement_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."close_infection_control_event"("p_event_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  update public.infection_control_surveillance_events set status = 'closed', closed_at = now() where id = p_event_id;
  perform public.record_hospital_governance_event('infection_control_event', p_event_id, 'infection_control_event_closed', 'Infection control event closed.', p_actor_user_id); return jsonb_build_object('status','closed','id',p_event_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."close_ovr_rca_case"("p_rca_case_id" "uuid", "p_actor_user_id" "uuid", "p_root_cause_summary" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_RCA_CLOSE_AUTHORITY_REQUIRED'; end if;
  update public.ovr_rca_cases set rca_status = 'closed', root_cause_summary = p_root_cause_summary, closed_at = now() where id = p_rca_case_id;
  perform public.record_clinical_governance_event('ovr_rca_case', p_rca_case_id, 'ovr_rca_case_closed', coalesce(p_root_cause_summary, 'OVR RCA case closed.'), p_actor_user_id);
  return jsonb_build_object('status','closed','rca_case_id',p_rca_case_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."complete_accreditation_review_cycle"("p_cycle_id" "uuid", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_ACCREDITATION_WORKFLOW_AUTHORITY_REQUIRED';
  end if;
  update public.accreditation_review_cycles set status = 'completed', completed_at = now(), notes = coalesce(p_notes, notes) where id = p_cycle_id;
  perform public.record_accreditation_workflow_event('review_cycle', p_cycle_id, null, 'review_cycle_completed', coalesce(p_notes, 'Accreditation review cycle completed.'), p_actor_user_id);
  return jsonb_build_object('status','completed','cycle_id',p_cycle_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."complete_capa_effectiveness_review"("p_review_id" "uuid", "p_actor_id" "uuid", "p_review_result" "text", "p_review_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_capa_id uuid; v_event text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  v_event := case when p_review_result in ('effective','needs_more_time') then 'effectiveness_review_passed' else 'effectiveness_review_failed' end;
  update public.capa_effectiveness_reviews set review_result = p_review_result, review_note = p_review_note, completed_at = now(), completed_by = p_actor_id where id = p_review_id returning capa_id into v_capa_id;
  if not found then raise exception 'PATCH28_EFFECTIVENESS_REVIEW_NOT_FOUND'; end if;
  update public.capa_action_plans set effectiveness_review_status = case when p_review_result = 'effective' then 'passed' else p_review_result end, effectiveness_review_completed_at = now(), capa_status = case when p_review_result = 'effective' then 'effectiveness_review_passed' else 'effectiveness_review_failed' end, repeat_issue_flag = case when p_review_result = 'repeated_issue_detected' then true else repeat_issue_flag end, updated_by = p_actor_id, updated_at = now() where id = v_capa_id;
  perform public.patch28_write_capa_event(v_capa_id, null, v_event, null, p_review_result, p_actor_id, p_review_note, null);
  return jsonb_build_object('status','ok','review_id',p_review_id,'review_result',p_review_result);
end $$;

CREATE OR REPLACE FUNCTION "public"."complete_committee_action"("p_action_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  update public.hospital_committee_actions set status = 'completed', completed_at = now() where id = p_action_id;
  perform public.record_hospital_governance_event('hospital_committee_action', p_action_id, 'committee_action_completed', 'Hospital committee action completed.', p_actor_user_id); return jsonb_build_object('status','completed','id',p_action_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."complete_training_assignment"("p_assignment_id" "uuid", "p_evidence_id" "uuid", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.training_assignments
  set status = 'completed', completed_at = now(), completion_evidence_id = p_evidence_id
  where id = p_assignment_id and status in ('assigned', 'in_progress', 'overdue');

  if not found then
    raise exception 'PATCH29_ASSIGNMENT_NOT_COMPLETABLE';
  end if;

  perform public.log_training_event(
    'training_assignments', p_assignment_id, 'completed',
    'Training completed successfully with evidence ' || coalesce(p_evidence_id::text, 'none') || '.',
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_accreditation_clause"("p_standard_id" "uuid", "p_clause_code" "text", "p_clause_title" "text", "p_actor_user_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_clause_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  insert into public.accreditation_clauses (
    standard_id, clause_code, clause_title, clause_title_ar, clause_description, clause_category,
    department_id, owner_user_id, criticality, active, created_by
  )
  values (
    p_standard_id, p_clause_code, p_clause_title, p_payload->>'clause_title_ar', p_payload->>'clause_description',
    nullif(p_payload->>'clause_category',''), nullif(p_payload->>'department_id','')::uuid, nullif(p_payload->>'owner_user_id','')::uuid,
    coalesce(nullif(p_payload->>'criticality',''), 'medium'), coalesce(nullif(p_payload->>'active','')::boolean, true), p_actor_user_id
  )
  on conflict (standard_id, clause_code) do update set
    clause_title = excluded.clause_title,
    clause_title_ar = excluded.clause_title_ar,
    clause_description = excluded.clause_description,
    clause_category = excluded.clause_category,
    department_id = excluded.department_id,
    owner_user_id = excluded.owner_user_id,
    criticality = excluded.criticality,
    active = excluded.active
  returning id into v_clause_id;
  perform public.record_accreditation_traceability_event(v_clause_id, 'accreditation_clause', v_clause_id, 'clause_created', 'Accreditation clause created or updated.', p_actor_user_id);
  return v_clause_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_accreditation_clause_review_task"("p_cycle_id" "uuid", "p_clause_id" "uuid", "p_owner_assignment_id" "uuid", "p_task_type" "text", "p_assigned_to_user_id" "uuid", "p_assigned_to_department_id" "uuid", "p_priority" "text", "p_due_date" "date", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_task_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_ACCREDITATION_WORKFLOW_AUTHORITY_REQUIRED';
  end if;

  insert into public.accreditation_clause_review_tasks (
    cycle_id, clause_id, owner_assignment_id, task_type, assigned_to_user_id,
    assigned_to_department_id, priority, due_date, created_by, outcome_notes
  ) values (
    p_cycle_id, p_clause_id, p_owner_assignment_id, coalesce(nullif(p_task_type, ''), 'owner_review'), p_assigned_to_user_id,
    p_assigned_to_department_id, coalesce(nullif(p_priority, ''), 'medium'), p_due_date, p_actor_user_id, p_notes
  )
  returning id into v_task_id;

  perform public.record_accreditation_workflow_event('review_task', v_task_id, p_clause_id, 'task_created', 'Accreditation clause review task created.', p_actor_user_id);
  return v_task_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_accreditation_review_cycle"("p_cycle_name" "text", "p_cycle_type" "text", "p_starts_on" "date", "p_ends_on" "date", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_cycle_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_ACCREDITATION_WORKFLOW_AUTHORITY_REQUIRED';
  end if;

  insert into public.accreditation_review_cycles (cycle_name, cycle_type, starts_on, ends_on, created_by, notes)
  values (p_cycle_name, coalesce(nullif(p_cycle_type, ''), 'accreditation_readiness'), p_starts_on, p_ends_on, p_actor_user_id, p_notes)
  returning id into v_cycle_id;

  perform public.record_accreditation_workflow_event('review_cycle', v_cycle_id, null, 'review_cycle_created', 'Accreditation review cycle created.', p_actor_user_id);
  return v_cycle_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_accreditation_standard"("p_standard_code" "text", "p_standard_name" "text", "p_framework" "text", "p_actor_user_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_standard_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  insert into public.accreditation_standards (standard_code, standard_name, standard_name_ar, framework, version, active, created_by)
  values (p_standard_code, p_standard_name, p_payload->>'standard_name_ar', coalesce(nullif(p_framework,''),'CBAHI'), nullif(p_payload->>'version',''), coalesce(nullif(p_payload->>'active','')::boolean, true), p_actor_user_id)
  on conflict (standard_code) do update set
    standard_name = excluded.standard_name,
    standard_name_ar = excluded.standard_name_ar,
    framework = excluded.framework,
    version = excluded.version,
    active = excluded.active
  returning id into v_standard_id;
  perform public.record_accreditation_traceability_event(null, 'accreditation_standard', v_standard_id, 'standard_created', 'Accreditation standard created or updated.', p_actor_user_id);
  return v_standard_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_accreditation_war_room_snapshot"("p_snapshot_title" "text", "p_actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_row record;
  v_id uuid;
begin
  perform public.patch43_service_role_required();
  if not public.patch43_actor_has_authority(p_actor_user_id) then
    raise exception 'Actor is not authorized to create accreditation war room snapshots';
  end if;

  select * into v_row from public.v_patch43_accreditation_war_room limit 1;

  insert into public.accreditation_war_room_snapshots(
    snapshot_title, readiness_signal, overall_readiness_score, open_blocker_count,
    evidence_gap_count, gate_failure_count, active_waiver_count, snapshot_payload, created_by
  )
  values (
    p_snapshot_title,
    coalesce(v_row.readiness_signal, 'watch'),
    v_row.overall_readiness_score,
    coalesce(v_row.total_blocker_count, 0),
    coalesce(v_row.evidence_gap_count, 0),
    coalesce(v_row.gate_failure_count, 0),
    coalesce(v_row.active_waiver_count, 0),
    to_jsonb(v_row),
    p_actor_user_id
  )
  returning id into v_id;

  return v_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_approval_authority_rule"("p_organization_id" "uuid", "p_rule_code" "text", "p_rule_name" "text", "p_workflow_type" "text", "p_action_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.approval_authority_rules (
    organization_id,
    rule_code,
    rule_name,
    rule_description,
    workflow_type,
    action_type,
    linked_item_type,
    department_id,
    role_name,
    approver_user_id,
    approver_role,
    min_amount,
    max_amount,
    risk_level,
    severity_level,
    criticality_level,
    document_type,
    escalation_level,
    required_approval_count,
    requires_dual_approval,
    requires_executive_approval,
    allow_self_approval,
    conflict_of_interest_block,
    effective_date,
    expiry_date,
    created_by,
    updated_by
  )
  values (
    p_organization_id,
    p_rule_code,
    p_rule_name,
    p_payload->>'rule_description',
    p_workflow_type,
    p_action_type,
    nullif(p_payload->>'linked_item_type', ''),
    nullif(p_payload->>'department_id', '')::uuid,
    nullif(p_payload->>'role_name', ''),
    nullif(p_payload->>'approver_user_id', '')::uuid,
    nullif(p_payload->>'approver_role', ''),
    nullif(p_payload->>'min_amount', '')::numeric,
    nullif(p_payload->>'max_amount', '')::numeric,
    nullif(p_payload->>'risk_level', ''),
    nullif(p_payload->>'severity_level', ''),
    nullif(p_payload->>'criticality_level', ''),
    nullif(p_payload->>'document_type', ''),
    nullif(p_payload->>'escalation_level', ''),
    coalesce(nullif(p_payload->>'required_approval_count', '')::integer, case when coalesce((p_payload->>'requires_dual_approval')::boolean, false) then 2 else 1 end),
    coalesce((p_payload->>'requires_dual_approval')::boolean, false),
    coalesce((p_payload->>'requires_executive_approval')::boolean, false),
    coalesce((p_payload->>'allow_self_approval')::boolean, false),
    coalesce((p_payload->>'conflict_of_interest_block')::boolean, true),
    nullif(p_payload->>'effective_date', '')::date,
    nullif(p_payload->>'expiry_date', '')::date,
    p_actor_id,
    p_actor_id
  )
  returning id into v_rule_id;

  perform public.patch27_write_authority_event(null, v_rule_id, 'rule_created', null, 'active', p_actor_id, p_rule_name);
  return v_rule_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_approval_delegation"("p_organization_id" "uuid", "p_delegator_id" "uuid", "p_delegate_id" "uuid", "p_effective_from" timestamp with time zone, "p_effective_to" timestamp with time zone, "p_actor_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_delegation_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;
  if p_effective_from >= p_effective_to then
    raise exception 'PATCH27_INVALID_DELEGATION_DATES';
  end if;

  insert into public.approval_delegations (
    organization_id,
    delegator_id,
    delegate_id,
    workflow_type,
    action_type,
    department_id,
    effective_from,
    effective_to,
    delegation_reason,
    created_by
  )
  values (
    p_organization_id,
    p_delegator_id,
    p_delegate_id,
    nullif(p_payload->>'workflow_type', ''),
    nullif(p_payload->>'action_type', ''),
    nullif(p_payload->>'department_id', '')::uuid,
    p_effective_from,
    p_effective_to,
    nullif(p_payload->>'delegation_reason', ''),
    p_actor_id
  )
  returning id into v_delegation_id;

  return v_delegation_id;
end;
$$;

