CREATE OR REPLACE FUNCTION "public"."create_controlled_production_cutover_decision"("p_actor_id" "uuid", "p_decision_state" "text", "p_decision_title" "text", "p_decision_summary" "text" DEFAULT NULL::"text", "p_critical_blockers_count" integer DEFAULT 0, "p_limitations_count" integer DEFAULT 0, "p_limitations_reviewed" boolean DEFAULT false, "p_cutover_checklist_complete" boolean DEFAULT false, "p_evidence_gate_snapshot" "jsonb" DEFAULT '{}'::"jsonb", "p_decision_rationale" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_decision_id uuid;
begin
  perform public.patch76_service_role_required();
  v_org_id := public.patch76_actor_authorized(p_actor_id);
  perform public.patch76_validate_cutover_decision(
    p_decision_state,
    coalesce(p_critical_blockers_count, 0),
    coalesce(p_limitations_count, 0),
    coalesce(p_limitations_reviewed, false),
    coalesce(p_cutover_checklist_complete, false),
    p_decision_rationale
  );

  if nullif(btrim(coalesce(p_decision_title, '')), '') is null then
    raise exception 'Controlled cutover decision title is required.';
  end if;

  insert into public.controlled_production_cutover_decisions (
    organization_id,
    decision_state,
    decision_title,
    decision_summary,
    critical_blockers_count,
    limitations_count,
    limitations_reviewed,
    cutover_checklist_complete,
    evidence_gate_snapshot,
    decision_rationale,
    decided_by
  ) values (
    v_org_id,
    p_decision_state,
    btrim(p_decision_title),
    nullif(btrim(coalesce(p_decision_summary, '')), ''),
    coalesce(p_critical_blockers_count, 0),
    coalesce(p_limitations_count, 0),
    coalesce(p_limitations_reviewed, false),
    coalesce(p_cutover_checklist_complete, false),
    coalesce(p_evidence_gate_snapshot, '{}'::jsonb)
      || jsonb_build_object(
        'decision_record_only', true,
        'does_not_automatically_launch_system', true,
        'live_transition_requires_separate_operational_execution', true
      ),
    btrim(p_decision_rationale),
    p_actor_id
  )
  returning id into v_decision_id;

  insert into public.controlled_production_cutover_decision_events (
    decision_id,
    organization_id,
    event_type,
    event_summary,
    event_payload,
    actor_id
  ) values (
    v_decision_id,
    v_org_id,
    'decision_recorded',
    'Controlled cutover decision recorded.',
    jsonb_build_object(
      'decision_state', p_decision_state,
      'critical_blockers_count', coalesce(p_critical_blockers_count, 0),
      'limitations_count', coalesce(p_limitations_count, 0),
      'limitations_reviewed', coalesce(p_limitations_reviewed, false),
      'cutover_checklist_complete', coalesce(p_cutover_checklist_complete, false),
      'does_not_automatically_launch_system', true
    ),
    p_actor_id
  );

  return jsonb_build_object(
    'id', v_decision_id,
    'decision_state', p_decision_state,
    'message', 'Controlled cutover decision recorded. This decision record does not automatically launch the system.'
  );
end;
$$;

COMMENT ON FUNCTION "public"."create_controlled_production_cutover_decision"("p_actor_id" "uuid", "p_decision_state" "text", "p_decision_title" "text", "p_decision_summary" "text", "p_critical_blockers_count" integer, "p_limitations_count" integer, "p_limitations_reviewed" boolean, "p_cutover_checklist_complete" boolean, "p_evidence_gate_snapshot" "jsonb", "p_decision_rationale" "text") IS 'Records a controlled cutover decision through the authenticated privileged bridge with server-side approval guardrails.';

CREATE OR REPLACE FUNCTION "public"."create_escalation_if_missing"("p_organization_id" "uuid", "p_item_type" "text", "p_item_id" "uuid", "p_title" "text", "p_department_id" "uuid", "p_owner_id" "uuid", "p_due_date" "date", "p_risk_level" "public"."risk_level", "p_escalation_level" "text", "p_reason" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not exists (
    select 1
    from public.escalation_events ee
    where ee.organization_id = p_organization_id
      and ee.item_type = p_item_type
      and ee.item_id = p_item_id
      and ee.escalation_level = p_escalation_level
      and ee.status in ('open','acknowledged')
  ) then
    insert into public.escalation_events (
      organization_id,
      item_type,
      item_id,
      title,
      department_id,
      owner_id,
      due_date,
      risk_level,
      escalation_level,
      reason
    ) values (
      p_organization_id,
      p_item_type,
      p_item_id,
      p_title,
      p_department_id,
      p_owner_id,
      p_due_date,
      coalesce(p_risk_level, 'medium'::public.risk_level),
      p_escalation_level,
      p_reason
    );
  end if;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_evidence_bridge_link"("p_linked_entity_type" "text", "p_linked_entity_id" "uuid", "p_actor_user_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_bridge_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_has_evidence_bridge_authority(p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_BRIDGE_AUTHORITY_REQUIRED'; end if;
  insert into public.evidence_bridge_links (
    clause_id, control_id, evidence_id, document_id, sop_id, linked_entity_type, linked_entity_id,
    bridge_role, evidence_status, freshness_status, valid_from, valid_until, owner_user_id,
    department_id, active, created_by, updated_by
  )
  values (
    nullif(p_payload->>'clause_id','')::uuid,
    nullif(p_payload->>'control_id','')::uuid,
    nullif(p_payload->>'evidence_id','')::uuid,
    nullif(p_payload->>'document_id','')::uuid,
    nullif(p_payload->>'sop_id','')::uuid,
    p_linked_entity_type,
    p_linked_entity_id,
    coalesce(nullif(p_payload->>'bridge_role',''), 'supporting'),
    coalesce(nullif(p_payload->>'evidence_status',''), 'pending_review'),
    coalesce(nullif(p_payload->>'freshness_status',''), 'unknown'),
    nullif(p_payload->>'valid_from','')::date,
    nullif(p_payload->>'valid_until','')::date,
    nullif(p_payload->>'owner_user_id','')::uuid,
    nullif(p_payload->>'department_id','')::uuid,
    coalesce(nullif(p_payload->>'active','')::boolean, true),
    p_actor_user_id,
    p_actor_user_id
  )
  returning id into v_bridge_id;
  perform public.record_evidence_bridge_event('evidence_bridge_link', v_bridge_id, 'bridge_link_created', 'Evidence bridge link created.', p_actor_user_id);
  return v_bridge_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_evidence_collection_request"("p_request_title" "text", "p_requested_entity_type" "text", "p_actor_user_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_request_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_has_evidence_bridge_authority(p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_BRIDGE_AUTHORITY_REQUIRED'; end if;
  insert into public.evidence_collection_requests (
    bridge_link_id, clause_id, requested_entity_type, requested_entity_id, request_title,
    request_description, assigned_to_user_id, assigned_to_department_id, due_date, priority,
    status, requested_by
  )
  values (
    nullif(p_payload->>'bridge_link_id','')::uuid,
    nullif(p_payload->>'clause_id','')::uuid,
    p_requested_entity_type,
    nullif(p_payload->>'requested_entity_id','')::uuid,
    p_request_title,
    p_payload->>'request_description',
    nullif(p_payload->>'assigned_to_user_id','')::uuid,
    nullif(p_payload->>'assigned_to_department_id','')::uuid,
    nullif(p_payload->>'due_date','')::date,
    coalesce(nullif(p_payload->>'priority',''), 'medium'),
    coalesce(nullif(p_payload->>'status',''), 'open'),
    p_actor_user_id
  )
  returning id into v_request_id;
  perform public.record_evidence_bridge_event('evidence_collection_request', v_request_id, 'collection_request_created', 'Evidence collection request created.', p_actor_user_id);
  return v_request_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_executive_governance_board_pack"("p_actor_id" "uuid", "p_pack_title" "text", "p_reporting_period" "text", "p_hypercare_window_id" "uuid" DEFAULT NULL::"uuid", "p_executive_summary" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_pack_id uuid;
begin
  perform public.patch79_service_role_required();
  v_org_id := public.patch79_actor_authorized(p_actor_id);

  if p_hypercare_window_id is not null and not exists (select 1 from public.production_hypercare_windows where id = p_hypercare_window_id and organization_id = v_org_id) then
    raise exception 'Hypercare command center record is not available for this organization.';
  end if;
  if nullif(btrim(coalesce(p_pack_title, '')), '') is null then
    raise exception 'Board closure pack title is required.';
  end if;
  if nullif(btrim(coalesce(p_reporting_period, '')), '') is null then
    raise exception 'Executive monthly governance report period is required.';
  end if;

  insert into public.executive_governance_board_packs (
    organization_id,
    hypercare_window_id,
    pack_title,
    reporting_period,
    executive_summary,
    prepared_by
  ) values (
    v_org_id,
    p_hypercare_window_id,
    btrim(p_pack_title),
    btrim(p_reporting_period),
    nullif(btrim(coalesce(p_executive_summary, '')), ''),
    p_actor_id
  ) returning id into v_pack_id;

  return jsonb_build_object('id', v_pack_id, 'message', 'Executive monthly governance report and board closure pack recorded.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_executive_truth_snapshot"("p_title" "text", "p_notes" "text", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_snapshot_id uuid;
  v_summary_data jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH30_TRUTH_SERVICE_ROLE_REQUIRED';
  end if;

  -- Gather GRC state snapshot data
  select jsonb_build_object(
    'active_risks_count', active_risks_count,
    'compliant_items_count', compliant_items_count,
    'non_compliant_items_count', non_compliant_items_count,
    'open_audit_findings_count', open_audit_findings_count,
    'pending_approvals_count', pending_approvals_count,
    'total_evidence_files_count', total_evidence_files_count
  ) into v_summary_data
  from public.v_patch30_executive_truth_summary;

  insert into public.executive_truth_snapshots (title, snapshot_data, notes, captured_by)
  values (p_title, v_summary_data, p_notes, p_actor_id)
  returning id into v_snapshot_id;

  perform public.log_executive_truth_event(
    'snapshot_created',
    'Executive truth snapshot "' || p_title || '" was captured successfully.',
    v_snapshot_id,
    p_actor_id
  );

  return v_snapshot_id;
end;
$$;

