CREATE OR REPLACE FUNCTION "public"."create_hospital_committee_action"("p_actor_user_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
