  v_id uuid;
begin
  perform public.patch45_service_role_required();

  insert into public.runtime_action_reviews(
    action_name, action_transport, module_name, classification, risk_level,
    required_access_level, owner_role, review_notes, created_by
  )
  values (
    p_action_name, p_action_transport, p_module_name, p_classification, p_risk_level,
    p_required_access_level, p_owner_role, p_review_notes, p_actor_user_id
  )
  on conflict (action_name) do update set
    action_transport = excluded.action_transport,
    module_name = excluded.module_name,
    classification = excluded.classification,
    risk_level = excluded.risk_level,
    required_access_level = excluded.required_access_level,
    owner_role = excluded.owner_role,
    review_notes = excluded.review_notes
  returning id into v_id;

  perform public.record_runtime_action_review_event(v_id, p_action_name, 'review_created_or_updated', 'Runtime action review registry entry created or updated.', p_actor_user_id);
  return v_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_runtime_action_review_signoff"("p_action_name" "text", "p_reviewer_role" "text", "p_reviewer_user_id" "uuid" DEFAULT NULL::"uuid", "p_due_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_risk_acceptance_required" boolean DEFAULT false, "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  perform public.patch46_service_role_required();

  if nullif(p_action_name, '') is null or nullif(p_reviewer_role, '') is null then
    raise exception 'Action name and reviewer role are required for runtime access review signoff.';
  end if;

  insert into public.runtime_action_review_signoffs(
    action_name,
    reviewer_role,
    reviewer_user_id,
    due_at,
    risk_acceptance_required,
    created_by
  )
  values (
    p_action_name,
    p_reviewer_role,
    p_reviewer_user_id,
    p_due_at,
    coalesce(p_risk_acceptance_required, false),
    p_created_by
  )
  returning id into v_id;

  perform public.record_runtime_action_review_signoff_event(
    v_id,
    p_action_name,
    'signoff_created',
    'Runtime action access-review signoff created and left pending.',
    p_created_by
  );

  return v_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_staging_migration_evidence_run"("p_run_label" "text", "p_environment_type" "text" DEFAULT 'local_clean'::"text", "p_evidence_path" "text" DEFAULT NULL::"text", "p_run_notes" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_id uuid;
begin
  perform public.patch47_service_role_required();

  if nullif(p_run_label, '') is null then
    raise exception 'Run label is required for staging migration evidence run.';
  end if;

  if p_environment_type not in ('local_clean', 'staging', 'production_shadow') then
    raise exception 'Invalid staging evidence environment type: %', p_environment_type;
  end if;

  insert into public.staging_migration_evidence_runs(
    run_label,
    run_status,
    environment_type,
    evidence_path,
    run_notes,
    started_at,
    created_by
  )
  values (
    p_run_label,
    'pending',
    p_environment_type,
    p_evidence_path,
    p_run_notes,
    now(),
    p_actor_user_id
  )
  returning id into v_id;

  perform public.record_staging_migration_evidence_event(
    v_id,
    'run_created',
    'Staging migration/persona evidence run created and awaiting proof execution.',
    p_evidence_path,
    p_actor_user_id
  );

  return v_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_system_health_snapshot"("p_organization_id" "uuid", "p_created_by" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_id uuid;
  v_data jsonb;
  v_critical integer;
  v_high integer;
  v_medium integer;
  v_low integer;
begin
  select coalesce(jsonb_agg(to_jsonb(h)), '[]'::jsonb)
  into v_data
  from v_backup_health_check h
  where h.organization_id = p_organization_id;

  select
    coalesce(sum(case when severity = 'critical' and record_count > 0 then 1 else 0 end),0),
    coalesce(sum(case when severity = 'high' and record_count > 0 then 1 else 0 end),0),
    coalesce(sum(case when severity = 'medium' and record_count > 0 then 1 else 0 end),0),
    coalesce(sum(case when severity = 'low' and record_count > 0 then 1 else 0 end),0)
  into v_critical, v_high, v_medium, v_low
  from v_backup_health_check
  where organization_id = p_organization_id;

  insert into system_health_snapshots (
    organization_id, snapshot_type, total_critical, total_high, total_medium, total_low, snapshot_data, created_by
  ) values (
    p_organization_id, 'pre_backup', v_critical, v_high, v_medium, v_low, v_data, p_created_by
  ) returning id into v_id;

  return v_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."create_training_program"("p_title" "text", "p_title_ar" "text", "p_description" "text", "p_training_type" "text", "p_linked_document_id" "uuid", "p_linked_sop_id" "uuid", "p_linked_compliance_obligation_id" "uuid", "p_linked_capa_id" "uuid", "p_linked_risk_id" "uuid", "p_linked_audit_finding_id" "uuid", "p_owner_user_id" "uuid", "p_department_id" "uuid", "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_program_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.training_programs (
    title, title_ar, description, training_type, linked_document_id, linked_sop_id,
    linked_compliance_obligation_id, linked_capa_id, linked_risk_id, linked_audit_finding_id,
    owner_user_id, department_id, created_by
  )
  values (
    p_title, p_title_ar, p_description, p_training_type, p_linked_document_id, p_linked_sop_id,
    p_linked_compliance_obligation_id, p_linked_capa_id, p_linked_risk_id, p_linked_audit_finding_id,
    p_owner_user_id, p_department_id, p_actor_id
  )
  returning id into v_program_id;

  perform public.log_training_event(
    'training_programs', v_program_id, 'created',
    'Training program "' || p_title || '" of type ' || p_training_type || ' was created.',
    p_actor_id
  );

  return v_program_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."current_user_org_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_org_id uuid := null;
begin
  if v_uid is null then
    return null;
  end if;

  -- Shape 1: public.profiles(id, organization_id)
  if to_regclass('public.profiles') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'profiles' and column_name = 'id'
     )
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'profiles' and column_name = 'organization_id'
     )
  then
    execute 'select organization_id from public.profiles where id = $1 limit 1'
    into v_org_id
    using v_uid;

    if v_org_id is not null then
      return v_org_id;
    end if;
  end if;

  -- Shape 2: public.organization_members(user_id, organization_id)
  if to_regclass('public.organization_members') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'organization_members' and column_name = 'user_id'
     )
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'organization_members' and column_name = 'organization_id'
     )
  then
    execute 'select organization_id from public.organization_members where user_id = $1 limit 1'
    into v_org_id
    using v_uid;

    if v_org_id is not null then
      return v_org_id;
    end if;
  end if;

  return null;
end
$_$;

COMMENT ON FUNCTION "public"."current_user_org_id"() IS 'Gate 9R category A: auth.uid()-scoped SECURITY INVOKER RLS helper; authenticated/service_role only; fixed search_path.';

CREATE OR REPLACE FUNCTION "public"."deactivate_hospital_ownership_mapping"("p_mapping_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch38_service_role_required(); if not public.patch38_actor_has_master_data_authority(p_actor_user_id) then raise exception 'PATCH38_MASTER_DATA_AUTHORITY_REQUIRED'; end if;
  update public.hospital_master_ownership_mappings set active = false where id = p_mapping_id;
  perform public.record_unified_work_queue_event('hospital_master_ownership_mapping', p_mapping_id, 'hospital_ownership_mapping_deactivated', 'Hospital ownership mapping deactivated.', p_actor_user_id); return jsonb_build_object('status','deactivated','id',p_mapping_id); end; $$;

CREATE OR REPLACE FUNCTION "public"."deactivate_user_role"("p_user_role_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_old jsonb;
  v_target_user_id uuid;
  v_org_id uuid;
begin
  if not can_manage_roles() then
    raise exception 'Not allowed to manage user roles';
  end if;

  select to_jsonb(ur), ur.user_id, ur.organization_id
  into v_old, v_target_user_id, v_org_id
  from user_roles ur
  where ur.id = p_user_role_id;

  if v_old is null then
    raise exception 'Role assignment not found';
  end if;

  update user_roles
  set is_active = false
  where id = p_user_role_id;

  insert into role_change_audit (organization_id, target_user_id, user_role_id, action, old_data, reason, changed_by)
  values (v_org_id, v_target_user_id, p_user_role_id, 'deactivated', v_old, p_reason, auth.uid());
end;
$$;

CREATE OR REPLACE FUNCTION "public"."department_lifecycle_archive"("p_actor_id" "uuid", "p_department_id" "uuid", "p_archive_reason" "text", "p_successor_department_id" "uuid" DEFAULT NULL::"uuid", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_actor_org uuid;
  v_department public.departments%rowtype;
  v_successor public.departments%rowtype;
  v_reason text := pg_catalog.btrim(coalesce(p_archive_reason, ''));
  v_active_users integer;
  v_reassigned integer := 0;
  v_roles_deactivated integer := 0;
  v_impact jsonb;
begin
  if auth.role() <> 'service_role' then raise exception 'PATCH83R_SERVICE_ROLE_REQUIRED'; end if;
  if v_reason = '' then raise exception 'PATCH83R_ARCHIVE_REASON_REQUIRED'; end if;
  if pg_catalog.length(v_reason) > 1000 then raise exception 'PATCH83R_ARCHIVE_REASON_TOO_LONG'; end if;
  select p.organization_id into v_actor_org from public.profiles p
  where p.id = p_actor_id and p.is_active = true and coalesce(p.user_status, 'active') = 'active';
  if v_actor_org is null or not exists (
    select 1 from public.user_roles ur where ur.user_id = p_actor_id and ur.is_active = true
      and ur.role in ('super_admin'::public.app_role, 'governance_admin'::public.app_role)
      and ur.scope = 'global'::public.access_scope
      and (ur.organization_id is null or ur.organization_id = v_actor_org)
  ) then raise exception 'PATCH83R_ADMIN_ROLE_REQUIRED'; end if;

  select * into v_department from public.departments d
  where d.id = p_department_id and d.organization_id = v_actor_org for update;
  if not found then raise exception 'PATCH83R_DEPARTMENT_NOT_FOUND'; end if;
  if not v_department.is_active or v_department.archived_at is not null then raise exception 'PATCH83R_DEPARTMENT_ALREADY_ARCHIVED'; end if;
  if p_successor_department_id = p_department_id then raise exception 'PATCH83R_SUCCESSOR_SELF_DENIED'; end if;

  select count(*)::integer into v_active_users from public.profiles p
  where p.organization_id = v_actor_org and p.department_id = p_department_id
    and p.is_active = true and coalesce(p.user_status, 'active') = 'active';
  if v_active_users > 0 and p_successor_department_id is null then raise exception 'PATCH83R_ACTIVE_USERS_REQUIRE_SUCCESSOR'; end if;
  if p_successor_department_id is not null then
    select * into v_successor from public.departments d
    where d.id = p_successor_department_id and d.organization_id = v_actor_org
      and d.is_active = true and d.archived_at is null for update;
    if not found then raise exception 'PATCH83R_ACTIVE_SUCCESSOR_REQUIRED'; end if;
  end if;

  v_impact := public.department_lifecycle_preview(p_actor_id, p_department_id)->'impact';
  if p_successor_department_id is not null then
    update public.profiles
    set department_id = p_successor_department_id, division_id = v_successor.division_id, unit_id = null, last_reviewed_at = pg_catalog.now()
    where organization_id = v_actor_org and department_id = p_department_id
      and is_active = true and coalesce(user_status, 'active') = 'active';
    get diagnostics v_reassigned = row_count;
    if v_reassigned <> v_active_users then raise exception 'PATCH83R_USER_REASSIGNMENT_INCOMPLETE'; end if;
  end if;

  update public.user_roles set is_active = false
  where department_id = p_department_id and is_active = true
    and (organization_id is null or organization_id = v_actor_org);
  get diagnostics v_roles_deactivated = row_count;

  perform pg_catalog.set_config('patch83r.lifecycle_action', 'archive', true);
  update public.departments
  set is_active = false, archived_at = pg_catalog.now(), archived_by = p_actor_id,
      archive_reason = v_reason, successor_department_id = p_successor_department_id
  where id = p_department_id;

  insert into public.audit_logs (organization_id, actor_id, action, table_name, record_id, old_data, new_data)
  values (v_actor_org, p_actor_id, 'DEPARTMENT_ARCHIVED', 'departments', p_department_id,
    pg_catalog.jsonb_build_object('is_active', true, 'name_en', v_department.name_en, 'name_ar', v_department.name_ar, 'code', v_department.code),
    pg_catalog.jsonb_build_object('is_active', false, 'archive_reason', v_reason,
      'successor_department_id', p_successor_department_id, 'reassigned_user_count', v_reassigned,
      'deactivated_role_count', v_roles_deactivated, 'impact', v_impact,
      'request_id', nullif(pg_catalog.btrim(p_request_id), '')));
  return pg_catalog.jsonb_build_object('department_id', p_department_id, 'archived', true,
    'successor_department_id', p_successor_department_id, 'reassigned_user_count', v_reassigned,
    'deactivated_role_count', v_roles_deactivated, 'impact', v_impact);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."department_lifecycle_preview"("p_actor_id" "uuid", "p_department_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_actor_org uuid;
  v_department public.departments%rowtype;
  v_active_users integer := 0;
  v_open_work integer := 0;
  v_policies integer := 0;
  v_sops integer := 0;
  v_training integer := 0;
  v_evidence integer := 0;
  v_risks integer := 0;
  v_audits integer := 0;
  v_other integer := 0;
begin
  if auth.role() <> 'service_role' then raise exception 'PATCH83R_SERVICE_ROLE_REQUIRED'; end if;

  select p.organization_id into v_actor_org
  from public.profiles p
  where p.id = p_actor_id and p.is_active = true and coalesce(p.user_status, 'active') = 'active';

  if v_actor_org is null or not exists (
    select 1 from public.user_roles ur
    where ur.user_id = p_actor_id and ur.is_active = true
      and ur.role in ('super_admin'::public.app_role, 'governance_admin'::public.app_role)
      and ur.scope = 'global'::public.access_scope
      and (ur.organization_id is null or ur.organization_id = v_actor_org)
  ) then raise exception 'PATCH83R_ADMIN_ROLE_REQUIRED'; end if;

  select * into v_department from public.departments d
  where d.id = p_department_id and d.organization_id = v_actor_org;
  if not found then raise exception 'PATCH83R_DEPARTMENT_NOT_FOUND'; end if;

  select count(*)::integer into v_active_users from public.profiles p
  where p.organization_id = v_actor_org and p.department_id = p_department_id
    and p.is_active = true and coalesce(p.user_status, 'active') = 'active';

  select (
    (select count(*) from public.projects p where p.department_id = p_department_id and p.status::text not in ('closed','cancelled'))
    + (select count(*) from public.tasks t join public.projects p on p.id = t.project_id
       where p.department_id = p_department_id and t.status::text not in ('closed','approved','cancelled'))
  )::integer into v_open_work;
  select count(*)::integer into v_policies from public.policies p
  where p.department_id = p_department_id and p.status::text not in ('archived','cancelled');
  select count(*)::integer into v_risks from public.risks r
  where r.department_id = p_department_id and r.status::text not in ('closed','cancelled');
  select count(*)::integer into v_audits from public.audit_findings a
  where (a.department_id = p_department_id or a.responsible_department_id = p_department_id)
    and a.status::text not in ('closed','cancelled');

  if pg_catalog.to_regclass('public.controlled_documents') is not null then
    execute 'select count(*)::integer from public.controlled_documents where department_id = $1 and document_type = ''sop'' and document_status not in (''retired'',''cancelled'')'
      into v_sops using p_department_id;
  end if;
  if pg_catalog.to_regclass('public.training_programs') is not null then
    execute 'select count(*)::integer from public.training_programs where department_id = $1 and coalesce(active, true) = true'
      into v_training using p_department_id;
  end if;
  if pg_catalog.to_regclass('public.evidence_bridge_links') is not null then
    execute 'select count(*)::integer from public.evidence_bridge_links where department_id = $1 and active = true'
      into v_evidence using p_department_id;
  end if;
  select (
    (select count(*) from public.units u where u.department_id = p_department_id and u.is_active = true)
    + (select count(*) from public.compliance_items c where c.department_id = p_department_id and c.status::text not in ('closed','cancelled'))
  )::integer into v_other;

  return pg_catalog.jsonb_build_object(
    'department_id', v_department.id,
    'organization_id', v_department.organization_id,
    'code', v_department.code,
    'name_en', v_department.name_en,
    'name_ar', v_department.name_ar,
    'is_active', v_department.is_active,
    'archived_at', v_department.archived_at,
    'archived_by', v_department.archived_by,
    'archive_reason', v_department.archive_reason,
    'successor_department_id', v_department.successor_department_id,
    'impact', pg_catalog.jsonb_build_object(
      'active_users', v_active_users,
      'open_assignments_work_items', v_open_work,
      'policies', v_policies,
      'sops', v_sops,
      'training_items', v_training,
      'evidence', v_evidence,
      'risks', v_risks,
      'audits', v_audits,
      'other_active_references', v_other
    )
  );
end;
$_$;

CREATE OR REPLACE FUNCTION "public"."department_lifecycle_rename"("p_actor_id" "uuid", "p_department_id" "uuid", "p_name_en" "text", "p_name_ar" "text", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_actor_org uuid;
  v_department public.departments%rowtype;
  v_old jsonb;
  v_name_en text := pg_catalog.btrim(coalesce(p_name_en, ''));
  v_name_ar text := pg_catalog.btrim(coalesce(p_name_ar, ''));
begin
  if auth.role() <> 'service_role' then raise exception 'PATCH83R_SERVICE_ROLE_REQUIRED'; end if;
  select p.organization_id into v_actor_org from public.profiles p
  where p.id = p_actor_id and p.is_active = true and coalesce(p.user_status, 'active') = 'active';
  if v_actor_org is null or not exists (
    select 1 from public.user_roles ur where ur.user_id = p_actor_id and ur.is_active = true
      and ur.role in ('super_admin'::public.app_role, 'governance_admin'::public.app_role)
      and ur.scope = 'global'::public.access_scope
      and (ur.organization_id is null or ur.organization_id = v_actor_org)
  ) then raise exception 'PATCH83R_ADMIN_ROLE_REQUIRED'; end if;
  if v_name_en = '' and v_name_ar = '' then raise exception 'PATCH83R_DEPARTMENT_NAME_REQUIRED'; end if;
  if pg_catalog.length(v_name_en) > 180 or pg_catalog.length(v_name_ar) > 180 then
    raise exception 'PATCH83R_DEPARTMENT_NAME_TOO_LONG';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor_org::text, 83));
  select * into v_department from public.departments d
  where d.id = p_department_id and d.organization_id = v_actor_org for update;
  if not found then raise exception 'PATCH83R_DEPARTMENT_NOT_FOUND'; end if;
  if not v_department.is_active or v_department.archived_at is not null then
    raise exception 'PATCH83R_ARCHIVED_DEPARTMENT_RENAME_DENIED';
  end if;
  if exists (
    select 1 from public.departments d
    where d.organization_id = v_actor_org and d.id <> p_department_id and d.is_active = true
      and (
        (v_name_en <> '' and pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(d.name_en), '\s+', ' ', 'g'))
          = pg_catalog.lower(pg_catalog.regexp_replace(v_name_en, '\s+', ' ', 'g')))
        or (v_name_ar <> '' and pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(coalesce(d.name_ar, '')), '\s+', ' ', 'g'))
          = pg_catalog.lower(pg_catalog.regexp_replace(v_name_ar, '\s+', ' ', 'g')))
      )
  ) then raise exception 'PATCH83R_ACTIVE_DEPARTMENT_NAME_CONFLICT'; end if;

  v_old := pg_catalog.jsonb_build_object('code', v_department.code, 'name_en', v_department.name_en, 'name_ar', v_department.name_ar);
  perform pg_catalog.set_config('patch83r.lifecycle_action', 'rename', true);
  update public.departments set name_en = v_name_en, name_ar = nullif(v_name_ar, '') where id = p_department_id;
  insert into public.audit_logs (organization_id, actor_id, action, table_name, record_id, old_data, new_data)
  values (v_actor_org, p_actor_id, 'DEPARTMENT_RENAMED', 'departments', p_department_id, v_old,
    pg_catalog.jsonb_build_object('code', v_department.code, 'name_en', v_name_en, 'name_ar', nullif(v_name_ar, ''), 'request_id', nullif(pg_catalog.btrim(p_request_id), '')));
  return pg_catalog.jsonb_build_object('department_id', p_department_id, 'code', v_department.code, 'name_en', v_name_en, 'name_ar', nullif(v_name_ar, ''));
end;
$$;

CREATE OR REPLACE FUNCTION "public"."department_lifecycle_restore"("p_actor_id" "uuid", "p_department_id" "uuid", "p_request_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_actor_org uuid;
  v_department public.departments%rowtype;
  v_old jsonb;
begin
  if auth.role() <> 'service_role' then raise exception 'PATCH83R_SERVICE_ROLE_REQUIRED'; end if;
  select p.organization_id into v_actor_org from public.profiles p
  where p.id = p_actor_id and p.is_active = true and coalesce(p.user_status, 'active') = 'active';
  if v_actor_org is null or not exists (
    select 1 from public.user_roles ur where ur.user_id = p_actor_id and ur.is_active = true
      and ur.role in ('super_admin'::public.app_role, 'governance_admin'::public.app_role)
      and ur.scope = 'global'::public.access_scope
      and (ur.organization_id is null or ur.organization_id = v_actor_org)
  ) then raise exception 'PATCH83R_ADMIN_ROLE_REQUIRED'; end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_actor_org::text, 83));
  select * into v_department from public.departments d
  where d.id = p_department_id and d.organization_id = v_actor_org for update;
  if not found then raise exception 'PATCH83R_DEPARTMENT_NOT_FOUND'; end if;
  if v_department.is_active or v_department.archived_at is null then raise exception 'PATCH83R_DEPARTMENT_NOT_ARCHIVED'; end if;
  if exists (
    select 1 from public.departments d
    where d.organization_id = v_actor_org and d.id <> p_department_id and d.is_active = true
      and (
        (nullif(pg_catalog.btrim(v_department.name_en), '') is not null
          and pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(d.name_en), '\s+', ' ', 'g'))
            = pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(v_department.name_en), '\s+', ' ', 'g')))
        or (nullif(pg_catalog.btrim(v_department.name_ar), '') is not null
          and pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(coalesce(d.name_ar, '')), '\s+', ' ', 'g'))
            = pg_catalog.lower(pg_catalog.regexp_replace(pg_catalog.btrim(v_department.name_ar), '\s+', ' ', 'g')))
        or (nullif(pg_catalog.btrim(v_department.code), '') is not null
          and pg_catalog.lower(pg_catalog.btrim(d.code)) = pg_catalog.lower(pg_catalog.btrim(v_department.code)))
      )
  ) then raise exception 'PATCH83R_ACTIVE_DEPARTMENT_NAME_CONFLICT'; end if;

  v_old := pg_catalog.jsonb_build_object('is_active', false, 'archived_at', v_department.archived_at,
    'archived_by', v_department.archived_by, 'archive_reason', v_department.archive_reason,
    'successor_department_id', v_department.successor_department_id, 'code', v_department.code,
    'name_en', v_department.name_en, 'name_ar', v_department.name_ar);
  perform pg_catalog.set_config('patch83r.lifecycle_action', 'restore', true);
  update public.departments set is_active = true, archived_at = null, archived_by = null,
    archive_reason = null, successor_department_id = null where id = p_department_id;
  insert into public.audit_logs (organization_id, actor_id, action, table_name, record_id, old_data, new_data)
  values (v_actor_org, p_actor_id, 'DEPARTMENT_RESTORED', 'departments', p_department_id, v_old,
    pg_catalog.jsonb_build_object('is_active', true, 'code', v_department.code,
      'name_en', v_department.name_en, 'name_ar', v_department.name_ar,
      'request_id', nullif(pg_catalog.btrim(p_request_id), '')));
  return pg_catalog.jsonb_build_object('department_id', p_department_id, 'restored', true,
    'code', v_department.code, 'name_en', v_department.name_en, 'name_ar', v_department.name_ar);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."disable_approval_authority_rule"("p_authority_rule_id" "uuid", "p_actor_id" "uuid", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;

  update public.approval_authority_rules
  set active_flag = false,
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_authority_rule_id;

  if not found then
    raise exception 'PATCH27_AUTHORITY_RULE_NOT_FOUND';
  end if;

  perform public.patch27_write_authority_event(null, p_authority_rule_id, 'rule_disabled', 'active', 'disabled', p_actor_id, p_reason);
  return jsonb_build_object('status', 'ok', 'authority_rule_id', p_authority_rule_id, 'active_flag', false);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."escalate_accreditation_clause_task"("p_task_id" "uuid", "p_escalation_level" "text", "p_reason" "text", "p_escalated_to_user_id" "uuid", "p_escalated_to_department_id" "uuid", "p_actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_escalation_id uuid;
  v_clause_id uuid;
  v_cycle_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then raise exception 'PATCH35_ESCALATION_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'PATCH35_ESCALATION_REASON_REQUIRED'; end if;
  select clause_id, cycle_id into v_clause_id, v_cycle_id from public.accreditation_clause_review_tasks where id = p_task_id;
  insert into public.accreditation_workflow_escalations (clause_id, task_id, cycle_id, escalation_level, escalation_reason, escalated_to_user_id, escalated_to_department_id, escalated_by)
  values (v_clause_id, p_task_id, v_cycle_id, coalesce(nullif(p_escalation_level, ''), 'department'), p_reason, p_escalated_to_user_id, p_escalated_to_department_id, p_actor_user_id)
  returning id into v_escalation_id;
  update public.accreditation_clause_review_tasks set status = 'escalated' where id = p_task_id;
  perform public.record_accreditation_workflow_event('workflow_escalation', v_escalation_id, v_clause_id, 'task_escalated', p_reason, p_actor_user_id);
  return v_escalation_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."escalate_approval_request"("p_approval_request_id" "uuid", "p_actor_id" "uuid", "p_escalation_level" "text", "p_escalated_to" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
  v_rule_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;

  select request_status, authority_rule_id into v_old_status, v_rule_id
  from public.approval_requests
  where id = p_approval_request_id
  for update;

  if not found then
    raise exception 'PATCH27_APPROVAL_REQUEST_NOT_FOUND';
  end if;

  update public.approval_requests
  set request_status = 'escalated',
      escalation_required = true,
      escalation_level_current = p_escalation_level,
      escalated_at = now(),
      escalated_to = p_escalated_to,
      updated_at = now()
  where id = p_approval_request_id;

  perform public.patch27_write_authority_event(p_approval_request_id, v_rule_id, 'escalated', v_old_status, 'escalated', p_actor_id, p_note);
  return jsonb_build_object('status', 'ok', 'approval_request_id', p_approval_request_id, 'request_status', 'escalated');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."escalate_capa"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_escalation_reason" "text", "p_escalation_level" "text" DEFAULT 'management'::"text", "p_escalated_to" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  if nullif(trim(coalesce(p_escalation_reason,'')), '') is null then raise exception 'PATCH28_ESCALATION_REASON_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'escalated', workflow_stage = 'escalation', escalation_required = true, escalation_level = p_escalation_level, escalated_at = now(), escalated_to = p_escalated_to, escalation_reason = p_escalation_reason, executive_visible = true, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'escalated', v_old, 'escalated', p_actor_id, p_escalation_reason, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."escalate_clinical_governance_item"("p_ovr_id" "uuid", "p_rca_case_id" "uuid", "p_audit_finding_id" "uuid", "p_escalation_level" "text", "p_escalation_reason" "text", "p_escalated_to_user_id" "uuid", "p_escalated_to_department_id" "uuid", "p_actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_id uuid;
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_ESCALATION_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(p_escalation_reason), '') is null then raise exception 'PATCH37_ESCALATION_REASON_REQUIRED'; end if;
  insert into public.clinical_governance_escalations(ovr_id, rca_case_id, audit_finding_id, escalation_level, escalation_reason, escalated_to_user_id, escalated_to_department_id, escalated_by)
  values (p_ovr_id, p_rca_case_id, p_audit_finding_id, coalesce(nullif(p_escalation_level, ''), 'department'), p_escalation_reason, p_escalated_to_user_id, p_escalated_to_department_id, p_actor_user_id)
  returning id into v_id;
  perform public.record_clinical_governance_event('clinical_governance_escalation', v_id, 'clinical_governance_item_escalated', p_escalation_reason, p_actor_user_id);
  return v_id;
end; $$;

CREATE OR REPLACE FUNCTION "public"."evaluate_evidence_gate"("p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_rule public.evidence_gate_rules%rowtype;
  v_accepted integer := 0;
  v_rejected integer := 0;
  v_expired integer := 0;
  v_superseded integer := 0;
  v_missing integer := 0;
  v_waiver_id uuid;
  v_status text;
  v_evaluation_id uuid;
begin
  perform public.patch43_service_role_required();
  if p_actor_user_id is not null and not public.patch43_actor_has_authority(p_actor_user_id) then
    raise exception 'Actor is not authorized to evaluate evidence gates';
  end if;

  select * into v_rule
  from public.evidence_gate_rules
  where entity_type = p_entity_type and active = true
  order by severity desc, created_at asc
  limit 1;

  if v_rule.id is null then
    v_status := 'not_required';
  else
    select
      count(*) filter (where b.evidence_status = 'accepted' and b.freshness_status = 'current'),
      count(*) filter (where b.evidence_status = 'rejected'),
      count(*) filter (where b.evidence_status = 'expired' or b.freshness_status = 'expired' or (b.valid_until is not null and b.valid_until < current_date)),
      count(*) filter (where b.evidence_status in ('superseded','stale') or b.freshness_status = 'stale'),
      greatest(v_rule.minimum_accepted_evidence - count(*) filter (where b.evidence_status = 'accepted' and b.freshness_status = 'current'), 0)
    into v_accepted, v_rejected, v_expired, v_superseded, v_missing
    from public.evidence_bridge_links b
    where b.active = true
      and (
        (p_entity_type = 'clause' and b.clause_id = p_entity_id)
        or (b.linked_entity_type = p_entity_type and b.linked_entity_id = p_entity_id)
      );

    select w.id into v_waiver_id
    from public.evidence_gate_waivers w
    where coalesce(w.entity_type, w.linked_item_type) = p_entity_type
      and coalesce(w.entity_id, w.linked_item_id) = p_entity_id
      and coalesce(w.waiver_status, case when w.status = 'requested' then 'pending' else w.status end) = 'approved'
      and coalesce(w.expires_on, w.expiry_date, current_date + interval '1 day')::date >= current_date
    order by coalesce(w.approved_at, w.requested_at) desc
    limit 1;

    v_status := case
      when v_waiver_id is not null then 'waived'
      when v_accepted >= v_rule.minimum_accepted_evidence then 'pass'
      when v_expired > 0 then 'fail_expired_evidence'
      when v_rejected > 0 then 'fail_rejected_evidence'
      when v_superseded > 0 then 'fail_superseded_evidence'
      when v_missing > 0 then 'fail_missing_evidence'
      else 'requires_review'
    end;
  end if;

  insert into public.evidence_gate_evaluations(
    entity_type, entity_id, gate_rule_id, gate_status, accepted_evidence_count,
    rejected_evidence_count, expired_evidence_count, superseded_evidence_count,
    missing_evidence_count, active_waiver_id, evaluated_by, evaluation_context
  )
  values (
    p_entity_type, p_entity_id, v_rule.id, v_status, coalesce(v_accepted,0),
    coalesce(v_rejected,0), coalesce(v_expired,0), coalesce(v_superseded,0),
    coalesce(v_missing,0), v_waiver_id, p_actor_user_id,
    jsonb_build_object('level', 'evaluation', 'source', 'patch43')
  )
  returning id into v_evaluation_id;

  if p_actor_user_id is not null then
    insert into public.survey_readiness_events(entity_type, entity_id, event_type, event_summary, event_payload, actor_user_id)
    values (
      p_entity_type, p_entity_id, 'evidence_gate_evaluated',
      'Evidence gate evaluated as ' || v_status,
      jsonb_build_object('evaluation_id', v_evaluation_id, 'gate_status', v_status),
      p_actor_user_id
    );
  end if;

  return jsonb_build_object(
    'evaluation_id', v_evaluation_id,
    'entity_type', p_entity_type,
    'entity_id', p_entity_id,
    'gate_status', v_status,
    'accepted_evidence_count', coalesce(v_accepted,0),
    'rejected_evidence_count', coalesce(v_rejected,0),
    'expired_evidence_count', coalesce(v_expired,0),
    'superseded_evidence_count', coalesce(v_superseded,0),
    'missing_evidence_count', coalesce(v_missing,0),
    'active_waiver_id', v_waiver_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."evaluate_evidence_gate_for_entity"("p_entity_type" "text", "p_entity_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select public.evaluate_evidence_gate(p_entity_type, p_entity_id, p_actor_user_id);
$$;

CREATE OR REPLACE FUNCTION "public"."generate_due_reminders"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_count integer := 0;
  r record;
begin
  for r in
    select *
    from public.v_due_reminder_queue
    where owner_id is not null
  loop
    insert into public.notifications (organization_id, user_id, title, body, link_path)
    select
      r.organization_id,
      r.owner_id,
      case
        when r.reminder_type = 'overdue' then 'Overdue ' || r.item_type || ': ' || r.title
        when r.reminder_type = 'pending_approval' then 'Pending approval: ' || r.title
        else 'Due soon ' || r.item_type || ': ' || r.title
      end,
      'Status: ' || r.status || '. Due date: ' || coalesce(r.due_date::text, 'not set') || '. Risk: ' || coalesce(r.risk_level, 'medium') || '.',
      r.action_path
    where not exists (
      select 1
      from public.notifications n
      where n.organization_id = r.organization_id
        and n.user_id = r.owner_id
        and n.title = case
          when r.reminder_type = 'overdue' then 'Overdue ' || r.item_type || ': ' || r.title
          when r.reminder_type = 'pending_approval' then 'Pending approval: ' || r.title
          else 'Due soon ' || r.item_type || ': ' || r.title
        end
        and n.created_at::date = current_date
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."get_accreditation_clause_traceability"("p_clause_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'clause', to_jsonb(r),
    'links', coalesce((select jsonb_agg(to_jsonb(l)) from public.accreditation_clause_links l where l.clause_id = p_clause_id and l.active), '[]'::jsonb),
    'assessments', coalesce((select jsonb_agg(to_jsonb(a) order by a.assessed_at desc) from public.accreditation_clause_assessments a where a.clause_id = p_clause_id), '[]'::jsonb),
    'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.created_at desc) from public.accreditation_traceability_events e where e.clause_id = p_clause_id), '[]'::jsonb)
  )
  from public.v_patch32_accreditation_clause_register r
  where r.clause_id = p_clause_id;
$$;

CREATE OR REPLACE FUNCTION "public"."get_accreditation_operations_dashboard"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then raise exception 'PATCH35_DASHBOARD_AUTHORITY_REQUIRED'; end if;
  select to_jsonb(d) into v_result from public.v_patch35_accreditation_operations_dashboard d limit 1;
  perform public.record_accreditation_workflow_event('dashboard', null, null, 'dashboard_viewed', 'Accreditation operations dashboard viewed.', p_actor_user_id);
  return coalesce(v_result, '{}'::jsonb);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."get_accreditation_readiness_summary"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce(jsonb_agg(to_jsonb(s)), '[]'::jsonb)
  from public.v_patch32_accreditation_executive_summary s;
$$;

SET default_tablespace = '';

SET default_table_access_method = "heap";

CREATE TABLE IF NOT EXISTS "public"."accreditation_clause_review_tasks" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "cycle_id" "uuid",
    "clause_id" "uuid" NOT NULL,
    "owner_assignment_id" "uuid",
    "task_type" "text" DEFAULT 'owner_review'::"text" NOT NULL,
    "assigned_to_user_id" "uuid",
    "assigned_to_department_id" "uuid",
    "priority" "text" DEFAULT 'medium'::"text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "due_date" "date",
    "submitted_at" timestamp with time zone,
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "uuid",
    "outcome_notes" "text",
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "accreditation_clause_review_tasks_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "accreditation_clause_review_tasks_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'submitted'::"text", 'under_review'::"text", 'approved'::"text", 'rejected'::"text", 'overdue'::"text", 'reopened'::"text", 'escalated'::"text", 'waived'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "accreditation_clause_review_tasks_task_type_check" CHECK (("task_type" = ANY (ARRAY['owner_review'::"text", 'evidence_collection'::"text", 'sop_update'::"text", 'capa_closure'::"text", 'training_completion'::"text", 'reviewer_signoff'::"text", 'executive_exception_review'::"text"])))
);

COMMENT ON TABLE "public"."accreditation_clause_review_tasks" IS 'Patch 35 operational task queue for clause owners and reviewers.';

CREATE TABLE IF NOT EXISTS "public"."accreditation_clauses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "standard_id" "uuid" NOT NULL,
    "clause_code" "text" NOT NULL,
    "clause_title" "text" NOT NULL,
    "clause_title_ar" "text",
    "clause_description" "text",
    "clause_category" "text",
    "department_id" "uuid",
    "owner_user_id" "uuid",
    "criticality" "text" DEFAULT 'medium'::"text" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"(),
    "created_by" "uuid",
    CONSTRAINT "accreditation_clauses_criticality_check" CHECK (("criticality" = ANY (ARRAY['critical'::"text", 'high'::"text", 'medium'::"text", 'low'::"text"])))
);

