    CONSTRAINT "evidence_bridge_links_evidence_status_check" CHECK (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'accepted'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text", 'not_applicable'::"text"]))),
