    CONSTRAINT "evidence_bridge_links_linked_entity_type_check" CHECK (("linked_entity_type" = ANY (ARRAY['clause'::"text", 'control'::"text", 'document'::"text", 'sop'::"text", 'evidence'::"text", 'capa'::"text", 'risk'::"text", 'audit_finding'::"text", 'training_program'::"text", 'training_assignment'::"text", 'policy'::"text", 'approval_authority'::"text", 'other'::"text"])))
