CREATE OR REPLACE VIEW "public"."v_patch33_clause_control_evidence_bridge" WITH ("security_invoker"='true') AS
 SELECT "b"."id" AS "bridge_link_id",
    "b"."clause_id",
    "c"."clause_code",
    "c"."clause_title",
    "s"."framework",
    "s"."standard_code",
    "b"."control_id",
    "b"."evidence_id",
    "b"."document_id",
    "b"."sop_id",
    "b"."linked_entity_type",
    "b"."linked_entity_id",
    "b"."bridge_role",
    "b"."evidence_status",
    "b"."freshness_status",
    "b"."valid_from",
    "b"."valid_until",
    "b"."owner_user_id",
    COALESCE("p"."full_name_en", "p"."full_name_ar", "p"."email") AS "owner_name",
    "b"."department_id",
    COALESCE("d"."name_en", "d"."name_ar") AS "department_name",
    "b"."active",
    "b"."updated_at"
   FROM (((("public"."evidence_bridge_links" "b"
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "b"."clause_id")))
     LEFT JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "b"."owner_user_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "b"."department_id")))
  WHERE ("b"."active" = true);

CREATE OR REPLACE VIEW "public"."v_patch33_clause_evidence_readiness" WITH ("security_invoker"='true') AS
 SELECT "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "count"(*) AS "bridge_link_count",
    "count"(*) FILTER (WHERE ("bridge_role" = ANY (ARRAY['primary_evidence'::"text", 'control_evidence'::"text"]))) AS "primary_bridge_count",
    "count"(*) FILTER (WHERE (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text"))) AS "accepted_current_count",
    "count"(*) FILTER (WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])))) AS "evidence_gap_count",
        CASE
            WHEN ("count"(*) = 0) THEN 'no_bridge_links'::"text"
            WHEN ("count"(*) FILTER (WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])))) > 0) THEN 'evidence_gaps_open'::"text"
            ELSE 'ready_for_reviewer_signoff'::"text"
        END AS "readiness_status"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  GROUP BY "clause_id", "clause_code", "clause_title", "framework", "standard_code";

CREATE OR REPLACE VIEW "public"."v_patch33_department_evidence_readiness" WITH ("security_invoker"='true') AS
 SELECT "department_id",
    "department_name",
    "count"(*) AS "bridge_link_count",
    "count"(*) FILTER (WHERE (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text"))) AS "ready_evidence_count",
    "count"(*) FILTER (WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])))) AS "gap_count",
    "avg"(
        CASE
            WHEN (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text")) THEN 100
            ELSE 0
        END) AS "evidence_readiness_score"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  GROUP BY "department_id", "department_name";

CREATE OR REPLACE VIEW "public"."v_patch33_live_evidence_gap_register" WITH ("security_invoker"='true') AS
 SELECT "bridge_link_id",
    "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "control_id",
    "evidence_id",
    "document_id",
    "sop_id",
    "linked_entity_type",
    "linked_entity_id",
    "bridge_role",
    "evidence_status",
    "freshness_status",
    "valid_from",
    "valid_until",
    "owner_user_id",
    "owner_name",
    "department_id",
    "department_name",
    "active",
    "updated_at"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch35_clause_blocker_summary" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "clause_id",
    "s"."framework",
    "s"."standard_code",
    "c"."clause_code",
    "c"."clause_title",
    "count"(DISTINCT "t"."id") FILTER (WHERE ("t"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'rejected'::"text", 'reopened'::"text", 'escalated'::"text", 'overdue'::"text"]))) AS "workflow_blocker_count",
    "count"(DISTINCT "eb"."bridge_link_id") FILTER (WHERE (("eb"."evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("eb"."freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])))) AS "evidence_blocker_count",
    "count"(DISTINCT "eb"."bridge_link_id") FILTER (WHERE ("eb"."linked_entity_type" = ANY (ARRAY['sop'::"text", 'document'::"text", 'capa'::"text", 'training_program'::"text", 'training_assignment'::"text", 'risk'::"text", 'audit_finding'::"text"]))) AS "dependency_link_count",
    "count"(DISTINCT "e"."id") FILTER (WHERE ("e"."escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"]))) AS "open_escalation_count"
   FROM (((("public"."accreditation_clauses" "c"
     LEFT JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."accreditation_clause_review_tasks" "t" ON (("t"."clause_id" = "c"."id")))
     LEFT JOIN "public"."v_patch33_clause_control_evidence_bridge" "eb" ON (("eb"."clause_id" = "c"."id")))
     LEFT JOIN "public"."accreditation_workflow_escalations" "e" ON (("e"."clause_id" = "c"."id")))
  WHERE ("c"."active" = true)
  GROUP BY "c"."id", "s"."framework", "s"."standard_code", "c"."clause_code", "c"."clause_title";

CREATE OR REPLACE VIEW "public"."v_patch35_clause_owner_task_queue" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."cycle_id",
    "t"."clause_id",
    "t"."owner_assignment_id",
    "t"."task_type",
    "t"."assigned_to_user_id",
    "t"."assigned_to_department_id",
    "t"."priority",
    "t"."status",
    "t"."due_date",
    "t"."submitted_at",
    "t"."reviewed_at",
    "t"."reviewed_by",
    "t"."outcome_notes",
    "t"."created_by",
    "t"."created_at",
    "t"."updated_at",
    "s"."framework",
    "s"."standard_code",
    "c"."clause_code",
    "c"."clause_title",
    "c"."criticality",
    COALESCE("u"."full_name_en", "u"."full_name_ar", "u"."email") AS "assigned_to_name",
    COALESCE("d"."name_en", "d"."name_ar") AS "assigned_department_name",
    "rc"."cycle_name",
        CASE
            WHEN (("t"."due_date" IS NOT NULL) AND ("t"."due_date" < CURRENT_DATE) AND ("t"."status" <> ALL (ARRAY['approved'::"text", 'waived'::"text", 'cancelled'::"text"]))) THEN true
            ELSE false
        END AS "is_overdue"
   FROM ((((("public"."accreditation_clause_review_tasks" "t"
     JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "t"."clause_id")))
     LEFT JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."profiles" "u" ON (("u"."id" = "t"."assigned_to_user_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "t"."assigned_to_department_id")))
     LEFT JOIN "public"."accreditation_review_cycles" "rc" ON (("rc"."id" = "t"."cycle_id")))
  WHERE ("t"."status" <> ALL (ARRAY['approved'::"text", 'waived'::"text", 'cancelled'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch35_department_accreditation_workload" WITH ("security_invoker"='true') AS
 SELECT "assigned_to_department_id" AS "department_id",
    "assigned_department_name" AS "department_name",
    "count"(*) AS "open_task_count",
    "count"(*) FILTER (WHERE "is_overdue") AS "overdue_task_count",
    "count"(*) FILTER (WHERE ("priority" = ANY (ARRAY['high'::"text", 'critical'::"text"]))) AS "high_priority_task_count",
    "count"(*) FILTER (WHERE ("status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text"]))) AS "pending_review_count",
    "min"("due_date") AS "nearest_due_date"
   FROM "public"."v_patch35_clause_owner_task_queue"
  GROUP BY "assigned_to_department_id", "assigned_department_name";

CREATE OR REPLACE VIEW "public"."v_patch43_clause_readiness_register" WITH ("security_invoker"='true') AS
 SELECT COALESCE("cr"."clause_id", "bs"."clause_id") AS "clause_id",
    COALESCE("cr"."framework", "bs"."framework") AS "framework",
    COALESCE("cr"."standard_code", "bs"."standard_code") AS "standard_code",
    COALESCE("cr"."clause_code", "bs"."clause_code") AS "clause_code",
    COALESCE("cr"."clause_title", "bs"."clause_title") AS "clause_title",
    "cr"."bridge_link_count",
    "cr"."primary_bridge_count",
    "cr"."accepted_current_count",
    "cr"."evidence_gap_count",
    "cr"."readiness_status",
    COALESCE("bs"."workflow_blocker_count", (0)::bigint) AS "workflow_blocker_count",
    COALESCE("bs"."evidence_blocker_count", (0)::bigint) AS "workflow_evidence_blocker_count",
    COALESCE("bs"."dependency_link_count", (0)::bigint) AS "dependency_link_count",
    COALESCE("bs"."open_escalation_count", (0)::bigint) AS "open_escalation_count",
    "ev"."gate_status",
    "ev"."accepted_evidence_count",
    "ev"."missing_evidence_count",
    "ev"."active_waiver_id",
    "ev"."evaluated_at"
   FROM (("public"."v_patch33_clause_evidence_readiness" "cr"
     FULL JOIN "public"."v_patch35_clause_blocker_summary" "bs" ON (("bs"."clause_id" = "cr"."clause_id")))
     LEFT JOIN LATERAL ( SELECT "e"."id",
            "e"."entity_type",
            "e"."entity_id",
            "e"."gate_rule_id",
            "e"."gate_status",
            "e"."accepted_evidence_count",
            "e"."rejected_evidence_count",
            "e"."expired_evidence_count",
            "e"."superseded_evidence_count",
            "e"."missing_evidence_count",
            "e"."active_waiver_id",
            "e"."evaluated_by",
            "e"."evaluated_at",
            "e"."evaluation_context"
           FROM "public"."evidence_gate_evaluations" "e"
          WHERE (("e"."entity_type" = 'clause'::"text") AND ("e"."entity_id" = COALESCE("cr"."clause_id", "bs"."clause_id")))
          ORDER BY "e"."evaluated_at" DESC
         LIMIT 1) "ev" ON (true));

CREATE OR REPLACE VIEW "public"."v_patch43_department_readiness_register" WITH ("security_invoker"='true') AS
 SELECT COALESCE("er"."department_id", "wl"."department_id") AS "department_id",
    COALESCE("er"."department_name", "wl"."department_name") AS "department_name",
    "er"."bridge_link_count",
    "er"."ready_evidence_count",
    "er"."gap_count" AS "evidence_gap_count",
    "er"."evidence_readiness_score",
    "wl"."open_task_count",
    "wl"."overdue_task_count",
    "wl"."high_priority_task_count",
    "wl"."pending_review_count",
    "wl"."nearest_due_date",
        CASE
            WHEN ((COALESCE("wl"."overdue_task_count", (0)::bigint) > 0) OR (COALESCE("er"."gap_count", (0)::bigint) > 0)) THEN 'attention_required'::"text"
            WHEN (COALESCE("wl"."high_priority_task_count", (0)::bigint) > 0) THEN 'watch'::"text"
            ELSE 'on_track'::"text"
        END AS "readiness_signal"
   FROM ("public"."v_patch33_department_evidence_readiness" "er"
     FULL JOIN "public"."v_patch35_department_accreditation_workload" "wl" ON (("wl"."department_id" = "er"."department_id")));

CREATE OR REPLACE VIEW "public"."v_patch43_evidence_gap_register" WITH ("security_invoker"='true') AS
 SELECT "bridge_link_id",
    "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "linked_entity_type",
    "linked_entity_id",
    "evidence_status",
    "freshness_status",
    "valid_until",
    "owner_user_id",
    "owner_name",
    "department_id",
    "department_name",
    "updated_at"
   FROM "public"."v_patch33_live_evidence_gap_register";

CREATE OR REPLACE VIEW "public"."v_patch43_evidence_gate_failure_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."entity_type",
    "e"."entity_id",
    "e"."gate_rule_id",
    "e"."gate_status",
    "e"."accepted_evidence_count",
    "e"."rejected_evidence_count",
    "e"."expired_evidence_count",
    "e"."superseded_evidence_count",
    "e"."missing_evidence_count",
    "e"."active_waiver_id",
    "e"."evaluated_by",
    "e"."evaluated_at",
    "e"."evaluation_context",
    "r"."gate_name",
    "r"."required_evidence_type",
    "r"."severity"
   FROM ("public"."evidence_gate_evaluations" "e"
     LEFT JOIN "public"."evidence_gate_rules" "r" ON (("r"."id" = "e"."gate_rule_id")))
  WHERE ("e"."gate_status" = ANY (ARRAY['fail_missing_evidence'::"text", 'fail_rejected_evidence'::"text", 'fail_expired_evidence'::"text", 'fail_superseded_evidence'::"text", 'requires_review'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch43_evidence_waiver_register" WITH ("security_invoker"='true') AS
 SELECT "w"."id" AS "waiver_id",
    COALESCE("w"."entity_type", "w"."linked_item_type") AS "entity_type",
    COALESCE("w"."entity_id", "w"."linked_item_id") AS "entity_id",
    "w"."waiver_reason",
    COALESCE("w"."waiver_status",
        CASE
            WHEN ("w"."status" = 'requested'::"text") THEN 'pending'::"text"
            ELSE "w"."status"
        END) AS "waiver_status",
    "w"."requested_by",
    COALESCE("requester"."full_name_en", "requester"."full_name_ar", "requester"."email") AS "requested_by_name",
    "w"."requested_at",
    "w"."approved_by",
    COALESCE("approver"."full_name_en", "approver"."full_name_ar", "approver"."email") AS "approved_by_name",
    "w"."approved_at",
    "w"."rejected_by",
    "w"."rejected_at",
    "w"."rejection_reason",
    "w"."revoked_by",
    "w"."revoked_at",
    "w"."revoke_reason",
    COALESCE("w"."expires_on", "w"."expiry_date") AS "expires_on",
    "w"."audit_note"
   FROM (("public"."evidence_gate_waivers" "w"
     LEFT JOIN "public"."profiles" "requester" ON (("requester"."id" = "w"."requested_by")))
     LEFT JOIN "public"."profiles" "approver" ON (("approver"."id" = "w"."approved_by")));

CREATE OR REPLACE VIEW "public"."v_patch43_mock_survey_finding_register" WITH ("security_invoker"='true') AS
 SELECT "id" AS "finding_id",
    'accreditation_task'::"text" AS "source_type",
    "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "priority",
    "status",
    "outcome_notes" AS "finding_summary",
    "assigned_to_user_id",
    "assigned_to_name",
    "assigned_to_department_id",
    "assigned_department_name",
    "due_date",
    "is_overdue",
    "created_at",
    "updated_at"
   FROM "public"."v_patch35_clause_owner_task_queue" "t"
  WHERE (("status" = ANY (ARRAY['rejected'::"text", 'reopened'::"text", 'escalated'::"text"])) OR ("is_overdue" = true));

CREATE OR REPLACE VIEW "public"."v_patch43_survey_blocker_summary" WITH ("security_invoker"='true') AS
 SELECT 'evidence_gate'::"text" AS "blocker_type",
    "v_patch43_evidence_gate_failure_register"."entity_type",
    "v_patch43_evidence_gate_failure_register"."entity_id",
    "v_patch43_evidence_gate_failure_register"."gate_status" AS "blocker_status",
    COALESCE("v_patch43_evidence_gate_failure_register"."gate_status", 'requires_review'::"text") AS "blocker_summary",
    "v_patch43_evidence_gate_failure_register"."evaluated_at" AS "created_at"
   FROM "public"."v_patch43_evidence_gate_failure_register"
UNION ALL
 SELECT 'evidence_gap'::"text" AS "blocker_type",
    COALESCE("v_patch43_evidence_gap_register"."linked_entity_type", 'clause'::"text") AS "entity_type",
    COALESCE("v_patch43_evidence_gap_register"."linked_entity_id", "v_patch43_evidence_gap_register"."clause_id") AS "entity_id",
    "v_patch43_evidence_gap_register"."evidence_status" AS "blocker_status",
    "concat_ws"(' '::"text", "v_patch43_evidence_gap_register"."clause_code", "v_patch43_evidence_gap_register"."evidence_status", "v_patch43_evidence_gap_register"."freshness_status") AS "blocker_summary",
    "v_patch43_evidence_gap_register"."updated_at" AS "created_at"
   FROM "public"."v_patch43_evidence_gap_register"
UNION ALL
 SELECT 'workflow_blocker'::"text" AS "blocker_type",
    'clause'::"text" AS "entity_type",
    "v_patch35_clause_blocker_summary"."clause_id" AS "entity_id",
    'blocked'::"text" AS "blocker_status",
    "concat_ws"(' '::"text", "v_patch35_clause_blocker_summary"."clause_code", 'workflow blockers:', ("v_patch35_clause_blocker_summary"."workflow_blocker_count")::"text", 'evidence blockers:', ("v_patch35_clause_blocker_summary"."evidence_blocker_count")::"text") AS "blocker_summary",
    "now"() AS "created_at"
   FROM "public"."v_patch35_clause_blocker_summary"
  WHERE (("v_patch35_clause_blocker_summary"."workflow_blocker_count" > 0) OR ("v_patch35_clause_blocker_summary"."evidence_blocker_count" > 0) OR ("v_patch35_clause_blocker_summary"."open_escalation_count" > 0));

CREATE OR REPLACE VIEW "public"."v_patch43_executive_survey_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_clause_readiness_register") AS "clause_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_clause_readiness_register"
          WHERE (COALESCE("v_patch43_clause_readiness_register"."readiness_status", ''::"text") = 'ready_for_reviewer_signoff'::"text")) AS "ready_clause_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_evidence_gap_register") AS "evidence_gap_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_evidence_gate_failure_register") AS "gate_failure_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_evidence_waiver_register"
          WHERE (("v_patch43_evidence_waiver_register"."waiver_status" = 'approved'::"text") AND ((COALESCE(("v_patch43_evidence_waiver_register"."expires_on")::timestamp without time zone, (CURRENT_DATE + '1 day'::interval)))::"date" >= CURRENT_DATE))) AS "active_waiver_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_survey_blocker_summary") AS "total_blocker_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch43_mock_survey_finding_register") AS "mock_survey_finding_count",
    ( SELECT "avg"("v_patch43_department_readiness_register"."evidence_readiness_score") AS "avg"
           FROM "public"."v_patch43_department_readiness_register") AS "department_readiness_score",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch43_evidence_gate_failure_register") > 0) THEN 'blocked'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch43_survey_blocker_summary") > 0) THEN 'attention_required'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch43_evidence_gap_register") > 0) THEN 'watch'::"text"
            ELSE 'on_track'::"text"
        END AS "readiness_signal";

CREATE OR REPLACE VIEW "public"."v_patch43_accreditation_war_room" WITH ("security_invoker"='true') AS
 SELECT "clause_count",
    "ready_clause_count",
    "evidence_gap_count",
    "gate_failure_count",
    "active_waiver_count",
    "total_blocker_count",
    "mock_survey_finding_count",
    "department_readiness_score",
    "readiness_signal",
    "round"(
        CASE
            WHEN (COALESCE("clause_count", (0)::bigint) = 0) THEN (0)::numeric
            ELSE ((("ready_clause_count")::numeric / (NULLIF("clause_count", 0))::numeric) * (100)::numeric)
        END, 2) AS "overall_readiness_score",
    ( SELECT "max"("accreditation_war_room_snapshots"."created_at") AS "max"
           FROM "public"."accreditation_war_room_snapshots") AS "latest_snapshot_at"
   FROM "public"."v_patch43_executive_survey_readiness_summary" "s";

CREATE OR REPLACE FUNCTION "public"."get_accreditation_war_room"() RETURNS SETOF "public"."v_patch43_accreditation_war_room"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$ select * from public.v_patch43_accreditation_war_room; $$;

CREATE OR REPLACE FUNCTION "public"."get_audit_execution_summary"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_SUMMARY_AUTHORITY_REQUIRED'; end if;
  select jsonb_build_object(
    'engagements', coalesce((select jsonb_agg(to_jsonb(e)) from public.v_patch37_audit_engagement_register e), '[]'::jsonb),
    'step_queue', coalesce((select jsonb_agg(to_jsonb(q)) from public.v_patch37_audit_test_step_queue q), '[]'::jsonb),
    'findings', coalesce((select jsonb_agg(to_jsonb(f)) from public.v_patch37_audit_finding_register f), '[]'::jsonb)
  ) into v_result;
  perform public.record_clinical_governance_event('audit_execution_summary', null, 'audit_execution_summary_viewed', 'Audit execution summary viewed.', p_actor_user_id);
  return coalesce(v_result, '{}'::jsonb);
end; $$;

CREATE OR REPLACE FUNCTION "public"."get_clause_evidence_bridge"("p_clause_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select jsonb_build_object(
    'clause_id', p_clause_id,
    'bridge_links', coalesce((select jsonb_agg(to_jsonb(b)) from public.v_patch33_clause_control_evidence_bridge b where b.clause_id = p_clause_id), '[]'::jsonb),
    'collection_requests', coalesce((select jsonb_agg(to_jsonb(r)) from public.v_patch33_evidence_collection_queue r where r.clause_id = p_clause_id), '[]'::jsonb),
    'readiness', coalesce((select to_jsonb(c) from public.v_patch33_clause_evidence_readiness c where c.clause_id = p_clause_id), '{}'::jsonb)
  );
$$;

CREATE OR REPLACE FUNCTION "public"."get_clause_owner_workload"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then raise exception 'PATCH35_WORKLOAD_AUTHORITY_REQUIRED'; end if;
  select coalesce(jsonb_agg(to_jsonb(w)), '[]'::jsonb) into v_result
  from public.v_patch35_department_accreditation_workload w;
  perform public.record_accreditation_workflow_event('owner_workload', null, null, 'owner_workload_viewed', 'Accreditation owner workload viewed.', p_actor_user_id);
  return v_result;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."get_clinical_governance_summary"("p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_result jsonb;
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_SUMMARY_AUTHORITY_REQUIRED'; end if;
  select to_jsonb(s) into v_result from public.v_patch37_executive_clinical_governance_summary s limit 1;
  perform public.record_clinical_governance_event('clinical_governance_summary', null, 'clinical_governance_summary_viewed', 'Clinical governance summary viewed.', p_actor_user_id);
  return coalesce(v_result, '{}'::jsonb);
end; $$;

CREATE OR REPLACE FUNCTION "public"."get_controlled_pilot_go_no_go_summary"() RETURNS "jsonb"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  select coalesce((select to_jsonb(v) from public.v_patch49_controlled_pilot_go_no_go_summary v limit 1), '{}'::jsonb);
$$;

CREATE TABLE IF NOT EXISTS "public"."controlled_production_cutover_decision_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "decision_id" "uuid",
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "event_type" "text" NOT NULL,
    "event_summary" "text" NOT NULL,
    "event_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "actor_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patch76_event_summary_required" CHECK ((NULLIF("btrim"("event_summary"), ''::"text") IS NOT NULL)),
    CONSTRAINT "patch76_event_type_required" CHECK ((NULLIF("btrim"("event_type"), ''::"text") IS NOT NULL))
);

COMMENT ON TABLE "public"."controlled_production_cutover_decision_events" IS 'Patch 76 append-only audit events for controlled cutover decision records.';

CREATE OR REPLACE FUNCTION "public"."get_controlled_production_cutover_decision_events"("p_decision_id" "uuid" DEFAULT NULL::"uuid") RETURNS SETOF "public"."controlled_production_cutover_decision_events"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.controlled_production_cutover_decision_events
  where p_decision_id is null or decision_id = p_decision_id
  order by created_at desc
  limit 100;
$$;

CREATE TABLE IF NOT EXISTS "public"."controlled_production_cutover_decisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "decision_state" "text" NOT NULL,
    "decision_scope" "text" DEFAULT 'controlled_pilot_cutover'::"text" NOT NULL,
    "decision_title" "text" NOT NULL,
    "decision_summary" "text",
    "critical_blockers_count" integer DEFAULT 0 NOT NULL,
    "limitations_count" integer DEFAULT 0 NOT NULL,
    "limitations_reviewed" boolean DEFAULT false NOT NULL,
    "cutover_checklist_complete" boolean DEFAULT false NOT NULL,
    "evidence_gate_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "decision_rationale" "text" NOT NULL,
    "decided_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "decided_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "controlled_production_cutover_dec_critical_blockers_count_check" CHECK (("critical_blockers_count" >= 0)),
    CONSTRAINT "controlled_production_cutover_decisions_decision_state_check" CHECK (("decision_state" = ANY (ARRAY['executive_review_required'::"text", 'blocked'::"text", 'deferred'::"text", 'approved_for_controlled_pilot_cutover'::"text", 'approved_with_limitations'::"text"]))),
    CONSTRAINT "controlled_production_cutover_decisions_limitations_count_check" CHECK (("limitations_count" >= 0)),
    CONSTRAINT "patch76_approved_pilot_cutover_guard" CHECK ((("decision_state" <> 'approved_for_controlled_pilot_cutover'::"text") OR (("critical_blockers_count" = 0) AND ("cutover_checklist_complete" = true) AND (NULLIF("btrim"("decision_rationale"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "patch76_approved_with_limitations_guard" CHECK ((("decision_state" <> 'approved_with_limitations'::"text") OR (("critical_blockers_count" = 0) AND ("limitations_count" > 0) AND ("limitations_reviewed" = true) AND ("cutover_checklist_complete" = true) AND (NULLIF("btrim"("decision_rationale"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "patch76_decision_rationale_required" CHECK ((NULLIF("btrim"("decision_rationale"), ''::"text") IS NOT NULL)),
    CONSTRAINT "patch76_decision_title_required" CHECK ((NULLIF("btrim"("decision_title"), ''::"text") IS NOT NULL))
);

COMMENT ON TABLE "public"."controlled_production_cutover_decisions" IS 'Patch 76 governed controlled production authority and cutover decision records. Decision records do not automatically launch the system.';

CREATE OR REPLACE FUNCTION "public"."get_controlled_production_cutover_decisions"() RETURNS SETOF "public"."controlled_production_cutover_decisions"
    LANGUAGE "sql"
    SET "search_path" TO 'public'
    AS $$
  select *
  from public.controlled_production_cutover_decisions
  order by decided_at desc
  limit 50;
$$;

CREATE OR REPLACE FUNCTION "public"."get_daily_operations_landing_summary"() RETURNS json
    LANGUAGE "sql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
    SELECT row_to_json(v) FROM public.v_patch44_daily_operations_landing_summary v LIMIT 1;
$$;

COMMENT ON FUNCTION "public"."get_daily_operations_landing_summary"() IS 'Gate 9R category B: SECURITY INVOKER authenticated read/helper surface; fixed search_path; anon/PUBLIC denied.';

CREATE OR REPLACE FUNCTION "public"."get_department_grc_scorecard"("p_department_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_result jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH30_TRUTH_SERVICE_ROLE_REQUIRED';
  end if;

  select jsonb_build_object(
    'department_id', department_id,
    'department_name_en', department_name_en,
    'department_name_ar', department_name_ar,
    'open_risks', open_risks,
    'non_compliant_obligations', non_compliant_obligations,
    'overdue_tasks', overdue_tasks
  ) into v_result
  from public.v_patch30_department_grc_scorecard
  where department_id = p_department_id;

  return v_result;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."get_department_hospital_governance_scorecard"("p_department_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ declare v_result jsonb; begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  select to_jsonb(s) into v_result from public.v_patch39_department_hospital_governance_scorecard s where s.department_id = p_department_id limit 1;
  perform public.record_hospital_governance_event('department_hospital_governance_scorecard', p_department_id, 'department_hospital_governance_scorecard_viewed', 'Department hospital governance scorecard viewed.', p_actor_user_id);
  return coalesce(v_result, '{}'::jsonb);
end; $$;

CREATE OR REPLACE FUNCTION "public"."get_department_work_queue"("p_department_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ declare v_result jsonb; begin
  perform public.patch38_service_role_required();
  if not public.has_any_role(array['super_admin','executive','governance_admin','auditor','compliance_officer','department_manager']::public.app_role[]) then raise exception 'PATCH38_DEPARTMENT_QUEUE_AUTHORITY_REQUIRED'; end if;
  select coalesce(jsonb_agg(to_jsonb(q)), '[]'::jsonb) into v_result from public.v_patch38_unified_work_queue q where q.department_id = p_department_id;
  perform public.record_unified_work_queue_event('unified_work_queue', null, 'department_work_queue_viewed', 'Department work queue viewed.', p_actor_user_id); return v_result; end; $$;

