CREATE TABLE IF NOT EXISTS "public"."live_pilot_department_acceptances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "pilot_session_id" "uuid" NOT NULL,
    "department_id" "uuid" NOT NULL,
    "acceptance_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "accepted_by" "uuid",
    "accepted_at" timestamp with time zone,
    "acceptance_notes" "text",
    "open_blockers_count" integer DEFAULT 0 NOT NULL,
    "training_confirmed" boolean DEFAULT false NOT NULL,
    "issue_burndown_confirmed" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "live_pilot_department_acceptances_acceptance_status_check" CHECK (("acceptance_status" = ANY (ARRAY['pending'::"text", 'accepted'::"text", 'accepted_with_limitations'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "live_pilot_department_acceptances_open_blockers_count_check" CHECK (("open_blockers_count" >= 0)),
    CONSTRAINT "patch77_department_acceptance_guard" CHECK ((("acceptance_status" <> 'accepted'::"text") OR (("open_blockers_count" = 0) AND ("training_confirmed" = true) AND ("issue_burndown_confirmed" = true))))
);

COMMENT ON TABLE "public"."live_pilot_department_acceptances" IS 'Patch 77 department pilot acceptance register with training and issue burn-down guardrails.';

CREATE OR REPLACE FUNCTION "public"."get_live_pilot_department_acceptances"() RETURNS SETOF "public"."live_pilot_department_acceptances"
