$$;

CREATE TABLE IF NOT EXISTS "public"."live_pilot_issues" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "pilot_session_id" "uuid" NOT NULL,
    "issue_title" "text" NOT NULL,
    "issue_description" "text",
    "severity" "text" DEFAULT 'medium'::"text" NOT NULL,
    "issue_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "owner_id" "uuid",
    "department_id" "uuid",
    "due_date" "date",
    "retest_required" boolean DEFAULT true NOT NULL,
    "retest_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "retest_evidence_summary" "text",
    "closure_summary" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "live_pilot_issues_issue_status_check" CHECK (("issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'retest_required'::"text", 'closed'::"text", 'deferred'::"text", 'accepted_limitation'::"text"]))),
    CONSTRAINT "live_pilot_issues_retest_status_check" CHECK (("retest_status" = ANY (ARRAY['not_started'::"text", 'pending'::"text", 'passed'::"text", 'failed'::"text", 'not_required'::"text"]))),
    CONSTRAINT "live_pilot_issues_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "patch77_issue_title_required" CHECK ((NULLIF("btrim"("issue_title"), ''::"text") IS NOT NULL)),
    CONSTRAINT "patch77_retest_closure_guard" CHECK ((("issue_status" <> 'closed'::"text") OR ("retest_required" = false) OR ("retest_status" = ANY (ARRAY['passed'::"text", 'not_required'::"text"]))))
);

COMMENT ON TABLE "public"."live_pilot_issues" IS 'Patch 77 live pilot issue burn-down and retest evidence register.';

CREATE OR REPLACE FUNCTION "public"."get_live_pilot_issues"() RETURNS SETOF "public"."live_pilot_issues"
