CREATE TABLE IF NOT EXISTS "public"."live_pilot_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "session_title" "text" NOT NULL,
    "session_scope" "text" DEFAULT 'controlled_pilot'::"text" NOT NULL,
    "department_id" "uuid",
    "owner_id" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "session_status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "started_at" timestamp with time zone,
    "completed_at" timestamp with time zone,
    "participant_count" integer DEFAULT 0 NOT NULL,
    "completed_participant_count" integer DEFAULT 0 NOT NULL,
    "critical_issue_count" integer DEFAULT 0 NOT NULL,
    "open_issue_count" integer DEFAULT 0 NOT NULL,
    "retest_required_count" integer DEFAULT 0 NOT NULL,
    "acceptance_required" boolean DEFAULT true NOT NULL,
    "exit_criteria_met" boolean DEFAULT false NOT NULL,
    "exit_review_notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "live_pilot_sessions_completed_participant_count_check" CHECK (("completed_participant_count" >= 0)),
    CONSTRAINT "live_pilot_sessions_critical_issue_count_check" CHECK (("critical_issue_count" >= 0)),
    CONSTRAINT "live_pilot_sessions_open_issue_count_check" CHECK (("open_issue_count" >= 0)),
    CONSTRAINT "live_pilot_sessions_participant_count_check" CHECK (("participant_count" >= 0)),
    CONSTRAINT "live_pilot_sessions_retest_required_count_check" CHECK (("retest_required_count" >= 0)),
    CONSTRAINT "live_pilot_sessions_session_status_check" CHECK (("session_status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'issue_burndown'::"text", 'exit_review_required'::"text", 'accepted'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "patch77_session_acceptance_guard" CHECK ((("session_status" <> 'accepted'::"text") OR (("critical_issue_count" = 0) AND ("open_issue_count" = 0) AND ("retest_required_count" = 0) AND ("exit_criteria_met" = true)))),
    CONSTRAINT "patch77_session_title_required" CHECK ((NULLIF("btrim"("session_title"), ''::"text") IS NOT NULL))
);

COMMENT ON TABLE "public"."live_pilot_sessions" IS 'Patch 77 live pilot execution sessions. Pilot readiness does not approve production launch.';

