CREATE OR REPLACE FUNCTION "public"."get_production_evidence_closure_action_history"("p_actor_id" "uuid", "p_evidence_id" "text") RETURNS TABLE("id" "uuid", "evidence_id" "text", "action_type" "text", "action_reason" "text", "action_note" "text", "previous_state" "text", "next_state" "text", "actor_id" "uuid", "created_at" timestamp with time zone, "metadata" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
begin
  perform public.patch68_service_role_required();
  v_org_id := public.patch68_actor_authorized(p_actor_id);

  return query
  select
    a.id,
    a.evidence_id,
    a.action_type,
    a.action_reason,
    a.action_note,
    a.previous_state,
    a.next_state,
    a.actor_id,
    a.created_at,
    a.metadata
  from public.production_evidence_closure_actions a
  where a.evidence_id = btrim(coalesce(p_evidence_id, ''))
    and (a.organization_id is null or a.organization_id = v_org_id)
  order by a.created_at desc
  limit 25;
end;
$$;

