CREATE OR REPLACE FUNCTION "public"."grc_guard_approval_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status::text = 'approved' and new.approver_id is not null and new.requested_by is not null and new.approver_id = new.requested_by then
    raise exception 'Self-approval is not allowed.';
  end if;

  if new.status::text in ('approved', 'rejected') and new.decided_at is null then
    new.decided_at := now();
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION "public"."grc_guard_approval_update"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."grc_guard_audit_finding_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status::text = 'closed' then
    if coalesce(new.evidence_required, false) = true and not public.patch24_audit_closure_satisfied(new.id) then
      raise exception 'Accepted evidence or approved evidence waiver is required before closing this audit finding.';
    end if;

    if coalesce(new.closure_validated_by, new.reviewed_by) is null then
      raise exception 'Audit validation is required before closing this audit finding.';
    end if;
  end if;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."grc_guard_milestone_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status::text = 'delayed' and coalesce(trim(new.delay_reason), '') = '' then
    raise exception 'Delay reason is required before marking a milestone delayed.';
  end if;

  if new.status::text in ('approved', 'closed') and coalesce(new.evidence_required, false) = true then
    if not grc_has_accepted_evidence('milestone', new.id) then
      raise exception 'Accepted evidence is required before approving or closing this milestone.';
    end if;
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION "public"."grc_guard_milestone_update"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."grc_guard_ovr_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status::text = 'returned_for_clarification'
     and coalesce(
       nullif(trim(new.returned_reason), ''),
       nullif(trim(new.returned_for_clarification_reason), ''),
       nullif(trim(new.rejection_reason), '')
     ) is null then
    raise exception 'Return reason is required before returning an OVR for clarification.';
  end if;

  if new.status::text = 'closed' then
    if coalesce(trim(new.final_verdict), '') = '' then
      raise exception 'Final Quality verdict is required before closing this OVR.';
    end if;

    if not public.can_close_ovr(new.id) then
      raise exception 'Accepted evidence or a closed linked corrective-action project is required before closing this OVR.';
    end if;

    if new.quality_closed_by is null then
      raise exception 'Quality final-review user is required before closing this OVR.';
    end if;

    if new.quality_closed_at is null then
      new.quality_closed_at := now();
    end if;
  end if;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."grc_guard_project_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status::text = 'delayed' and coalesce(trim(new.delay_reason), '') = '' then
    raise exception 'Delay reason is required before marking a project delayed.';
  end if;

  if new.status::text = 'closed' and coalesce(new.evidence_required, false) = true then
    if not grc_has_accepted_evidence('project', new.id) then
      raise exception 'Accepted evidence is required before closing this project.';
    end if;
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION "public"."grc_guard_project_update"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."grc_guard_task_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.status::text = 'delayed' and coalesce(trim(new.delay_reason), '') = '' then
    raise exception 'Delay reason is required before marking a task delayed.';
  end if;

  if new.status::text in ('approved', 'closed') and coalesce(new.evidence_required, false) = true then
    if not grc_has_accepted_evidence('task', new.id) then
      raise exception 'Accepted evidence is required before approving or closing this task.';
    end if;
  end if;

  return new;
end;
$$;

COMMENT ON FUNCTION "public"."grc_guard_task_update"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."grc_has_accepted_evidence"("p_item_type" "text", "p_item_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $_$
declare
  v_exists boolean := false;
begin
  if p_item_id is null then
    return false;
  end if;

  case p_item_type
    when 'project' then
      select exists(select 1 from evidence_files where project_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'milestone' then
      select exists(select 1 from evidence_files where milestone_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'task' then
      select exists(select 1 from evidence_files where task_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'risk' then
      select exists(select 1 from evidence_files where risk_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'compliance' then
      select exists(select 1 from evidence_files where compliance_item_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'audit_finding' then
      select exists(select 1 from evidence_files where audit_finding_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'policy' then
      select exists(select 1 from evidence_files where policy_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'decision' then
      select exists(select 1 from evidence_files where committee_decision_id = p_item_id and status::text = 'accepted') into v_exists;
    when 'ovr' then
      if exists(select 1 from information_schema.columns where table_name='evidence_files' and column_name='ovr_report_id') then
        execute 'select exists(select 1 from evidence_files where ovr_report_id = $1 and status::text = ''accepted'')' into v_exists using p_item_id;
      end if;
    else
      v_exists := false;
  end case;

  return coalesce(v_exists, false);
end;
$_$;

COMMENT ON FUNCTION "public"."grc_has_accepted_evidence"("p_item_type" "text", "p_item_id" "uuid") IS 'Gate 9R category B: SECURITY INVOKER authenticated read/helper surface; fixed search_path; anon/PUBLIC denied.';

CREATE OR REPLACE FUNCTION "public"."has_accepted_evidence"("target_item_type" "text", "target_item_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.evidence_files e
    where e.status = 'accepted'
      and (
        (target_item_type = 'project' and e.project_id = target_item_id)
        or (target_item_type = 'milestone' and e.milestone_id = target_item_id)
        or (target_item_type = 'task' and e.task_id = target_item_id)
        or (target_item_type = 'risk' and e.risk_id = target_item_id)
        or (target_item_type = 'compliance_item' and e.compliance_item_id = target_item_id)
        or (target_item_type = 'audit_finding' and e.audit_finding_id = target_item_id)
        or (target_item_type = 'policy' and e.policy_id = target_item_id)
        or (target_item_type = 'committee_decision' and e.committee_decision_id = target_item_id)
      )
  );
$$;

CREATE OR REPLACE FUNCTION "public"."has_active_role"("p_role" "public"."app_role") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from user_roles ur
    where ur.user_id = auth.uid()
      and ur.role = p_role
      and ur.is_active = true
  );
$$;

CREATE OR REPLACE FUNCTION "public"."has_any_role"("p_roles" "text"[]) RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_roles text[] := array(select lower(x) from unnest(coalesce(p_roles, array[]::text[])) as x);
  v_exists boolean := false;
begin
  if v_uid is null or array_length(v_roles, 1) is null then
    return false;
  end if;

  -- Shape 1: public.user_roles(user_id, role)
  if to_regclass('public.user_roles') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'user_roles' and column_name = 'user_id'
     )
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'user_roles' and column_name = 'role'
     )
  then
    execute 'select exists (
      select 1 from public.user_roles
      where user_id = $1 and lower(role::text) = any($2)
    )'
    into v_exists
    using v_uid, v_roles;

    if v_exists then
      return true;
    end if;
  end if;

  -- Shape 2: public.profiles(id, role)
  if to_regclass('public.profiles') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'profiles' and column_name = 'id'
     )
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'profiles' and column_name = 'role'
     )
  then
    execute 'select exists (
      select 1 from public.profiles
      where id = $1 and lower(role::text) = any($2)
    )'
    into v_exists
    using v_uid, v_roles;

    if v_exists then
      return true;
    end if;
  end if;

  -- Shape 3: public.organization_members(user_id, role)
  if to_regclass('public.organization_members') is not null
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'organization_members' and column_name = 'user_id'
     )
     and exists (
       select 1 from information_schema.columns
       where table_schema = 'public' and table_name = 'organization_members' and column_name = 'role'
     )
  then
    execute 'select exists (
      select 1 from public.organization_members
      where user_id = $1 and lower(role::text) = any($2)
    )'
    into v_exists
    using v_uid, v_roles;

    if v_exists then
      return true;
    end if;
  end if;

  return false;
end
$_$;

COMMENT ON FUNCTION "public"."has_any_role"("p_roles" "text"[]) IS 'Gate 9R category A: auth.uid()-scoped SECURITY INVOKER RLS helper; authenticated/service_role only; fixed search_path.';

