CREATE OR REPLACE FUNCTION "public"."link_accreditation_clause_entity"("p_clause_id" "uuid", "p_linked_entity_type" "text", "p_linked_entity_id" "uuid", "p_actor_user_id" "uuid", "p_link_strength" "text" DEFAULT 'supporting'::"text", "p_link_notes" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_link_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  insert into public.accreditation_clause_links (clause_id, linked_entity_type, linked_entity_id, link_strength, link_notes, active, created_by)
  values (p_clause_id, p_linked_entity_type, p_linked_entity_id, coalesce(nullif(p_link_strength,''),'supporting'), p_link_notes, true, p_actor_user_id)
  on conflict (clause_id, linked_entity_type, linked_entity_id) do update set
    link_strength = excluded.link_strength,
    link_notes = excluded.link_notes,
    active = true
  returning id into v_link_id;
  perform public.record_accreditation_traceability_event(p_clause_id, p_linked_entity_type, p_linked_entity_id, 'entity_linked', 'Accreditation clause entity linked.', p_actor_user_id);
  return v_link_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."link_audit_finding_to_capa"("p_audit_finding_id" "uuid", "p_capa_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_AUTHORITY_REQUIRED'; end if;
  update public.audit_execution_findings set linked_capa_id = p_capa_id, finding_status = 'capa_required' where id = p_audit_finding_id;
  perform public.record_clinical_governance_event('audit_finding', p_audit_finding_id, 'audit_finding_linked_to_capa', 'Audit finding linked to CAPA.', p_actor_user_id);
  return jsonb_build_object('status','linked','audit_finding_id',p_audit_finding_id,'capa_id',p_capa_id);
end; $$;

