CREATE OR REPLACE FUNCTION "public"."link_capa_to_item"("p_capa_id" "uuid", "p_linked_item_type" "text", "p_linked_item_id" "uuid", "p_actor_id" "uuid", "p_link_type" "text" DEFAULT NULL::"text", "p_required_flag" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_link_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  insert into public.capa_links (capa_id, linked_item_type, linked_item_id, link_type, required_flag, created_by) values (p_capa_id, p_linked_item_type, p_linked_item_id, p_link_type, coalesce(p_required_flag, false), p_actor_id) returning id into v_link_id;
  perform public.patch28_write_capa_event(
    p_capa_id,
    null,
    'linked',
    null,
    null,
    p_actor_id,
    'Linked CAPA to ' || p_linked_item_type,
    jsonb_build_object('linked_item_id', p_linked_item_id, 'link_type', p_link_type, 'required_flag', coalesce(p_required_flag, false))::text
  );
  return v_link_id;
end $$;

CREATE OR REPLACE FUNCTION "public"."link_document_to_item"("p_document_id" "uuid", "p_version_id" "uuid", "p_linked_item_type" "text", "p_linked_item_id" "uuid", "p_link_type" "text", "p_required_flag" boolean, "p_actor_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_link_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.document_links (
    document_id,
    version_id,
    linked_item_type,
    linked_item_id,
    link_type,
    required_flag,
    created_by
  )
  values (
    p_document_id,
    p_version_id,
    p_linked_item_type,
    p_linked_item_id,
    p_link_type,
    coalesce(p_required_flag, false),
    p_actor_id
  )
  returning id into v_link_id;

  perform public.patch26_write_document_event(p_document_id, p_version_id, 'linked', null, null, p_actor_id, 'Document linked to ' || p_linked_item_type, null);
