CREATE OR REPLACE FUNCTION "public"."log_production_hardening_event"("p_entity_type" "text", "p_entity_id" "uuid", "p_event_type" "text", "p_event_summary" "text", "p_actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.production_hardening_events (entity_type, entity_id, event_type, event_summary, actor_user_id)
  values (p_entity_type, p_entity_id, p_event_type, p_event_summary, p_actor_user_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."log_training_event"("p_entity_type" "text", "p_entity_id" "uuid", "p_event_type" "text", "p_event_summary" "text", "p_actor_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.training_events (entity_type, entity_id, event_type, event_summary, actor_user_id)
  values (p_entity_type, p_entity_id, p_event_type, p_event_summary, p_actor_user_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."mark_accreditation_clause_not_applicable"("p_clause_id" "uuid", "p_actor_user_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assessment_id uuid;
begin
  if nullif(trim(coalesce(p_reason,'')), '') is null then raise exception 'PATCH32_NOT_APPLICABLE_REASON_REQUIRED'; end if;
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  insert into public.accreditation_clause_assessments (clause_id, assessment_status, readiness_score, evidence_status, assessment_notes, assessed_by)
  values (p_clause_id, 'not_applicable', 100, 'complete', p_reason, p_actor_user_id)
  returning id into v_assessment_id;
  perform public.record_accreditation_traceability_event(p_clause_id, 'accreditation_clause_assessment', v_assessment_id, 'marked_not_applicable', p_reason, p_actor_user_id);
  return v_assessment_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."mark_credentialing_record_reviewed"("p_record_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  update public.clinical_credentialing_records set credential_status = 'active', reviewer_user_id = coalesce(reviewer_user_id, p_actor_user_id) where id = p_record_id;
  perform public.record_hospital_governance_event('clinical_credentialing_record', p_record_id, 'credentialing_record_reviewed', 'Clinical credentialing record reviewed.', p_actor_user_id); return jsonb_build_object('status','reviewed','id',p_record_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."mark_evidence_bridge_not_applicable"("p_bridge_link_id" "uuid", "p_actor_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_has_evidence_bridge_authority(p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_BRIDGE_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(coalesce(p_reason,'')), '') is null then raise exception 'PATCH33_NOT_APPLICABLE_REASON_REQUIRED'; end if;
  update public.evidence_bridge_links set evidence_status = 'not_applicable', freshness_status = 'current', updated_by = p_actor_user_id, updated_at = now() where id = p_bridge_link_id;
  if not found then raise exception 'PATCH33_BRIDGE_LINK_NOT_FOUND'; end if;
  perform public.record_evidence_bridge_event('evidence_bridge_link', p_bridge_link_id, 'bridge_marked_not_applicable', p_reason, p_actor_user_id);
  return jsonb_build_object('status','ok','bridge_link_id',p_bridge_link_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."mark_facility_biomedical_safety_checked"("p_safety_id" "uuid", "p_last_checked_on" "date", "p_next_check_due" "date", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  update public.facility_biomedical_safety_evidence set last_checked_on = p_last_checked_on, next_check_due = p_next_check_due, status = 'compliant' where id = p_safety_id;
  perform public.record_hospital_governance_event('facility_biomedical_safety_evidence', p_safety_id, 'facility_biomedical_safety_checked', 'Facility biomedical safety item checked.', p_actor_user_id); return jsonb_build_object('status','checked','id',p_safety_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."mark_overdue_work_items"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  update projects
  set status = 'delayed', updated_at = now()
  where target_end_date < current_date
    and status not in ('closed','cancelled','delayed')
    and coalesce(trim(delay_reason), '') <> '';

  update milestones
  set status = 'delayed', updated_at = now()
  where due_date < current_date
    and status not in ('closed','approved','cancelled','delayed')
    and coalesce(trim(delay_reason), '') <> '';

  update tasks
  set status = 'delayed', updated_at = now()
  where due_date < current_date
    and status not in ('closed','approved','cancelled','delayed')
    and coalesce(trim(delay_reason), '') <> '';
end;
$$;

CREATE OR REPLACE FUNCTION "public"."mark_repeat_capa"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_repeat_of_capa_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  update public.capa_action_plans set repeat_issue_flag = true, repeat_of_capa_id = p_repeat_of_capa_id, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  perform public.patch28_write_capa_event(p_capa_id, null, 'reopened', null, 'repeat_issue', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id,'repeat_issue_flag',true);
end $$;

CREATE OR REPLACE FUNCTION "public"."mark_runtime_rpc_reviewed"("p_rpc_name" "text", "p_actor_user_id" "uuid", "p_signoff_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH31_SERVICE_ROLE_REQUIRED';
  end if;
  if not public.patch31_actor_has_security_authority(p_actor_user_id) then
    raise exception 'PATCH31_SECURITY_AUTHORITY_REQUIRED';
  end if;
  update public.runtime_rpc_classifications
  set reviewed_by = p_actor_user_id,
      reviewed_at = now(),
      signoff_notes = coalesce(p_signoff_notes, signoff_notes),
      updated_at = now()
  where rpc_name = p_rpc_name;
  if not found then raise exception 'PATCH31_RPC_CLASSIFICATION_NOT_FOUND'; end if;
  perform public.record_runtime_rpc_signoff_event(p_rpc_name, 'reviewed', 'Runtime RPC classification reviewed.', p_actor_user_id);
  return jsonb_build_object('status','ok','rpc_name',p_rpc_name);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."override_approval_request_with_reason"("p_approval_request_id" "uuid", "p_override_by" "uuid", "p_override_decision" "text", "p_override_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
  v_rule_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_override_reason, '')), '') is null then
    raise exception 'PATCH27_OVERRIDE_REASON_REQUIRED';
  end if;
  if p_override_decision not in ('approved','rejected','returned','cancelled') then
    raise exception 'PATCH27_INVALID_OVERRIDE_DECISION';
  end if;

  select request_status, authority_rule_id into v_old_status, v_rule_id
  from public.approval_requests
  where id = p_approval_request_id
  for update;

  if not found then
    raise exception 'PATCH27_APPROVAL_REQUEST_NOT_FOUND';
  end if;

  insert into public.approval_authority_overrides (
    approval_request_id,
    override_by,
    override_reason,
    override_decision
  )
  values (
    p_approval_request_id,
    p_override_by,
    p_override_reason,
    p_override_decision
  );

  update public.approval_requests
  set request_status = case when p_override_decision = 'approved' then 'approved'
                            when p_override_decision = 'rejected' then 'rejected'
                            when p_override_decision = 'returned' then 'returned'
                            else 'cancelled' end,
      final_decision = p_override_decision,
      final_decision_by = p_override_by,
      final_decision_at = now(),
      final_decision_note = p_override_reason,
      updated_at = now()
  where id = p_approval_request_id;

  perform public.patch27_write_authority_event(
    p_approval_request_id,
    v_rule_id,
    case when p_override_decision = 'approved' then 'final_approved' else 'final_rejected' end,
    v_old_status,
    p_override_decision,
    p_override_by,
    p_override_reason
  );

  return jsonb_build_object('status', 'ok', 'approval_request_id', p_approval_request_id, 'override_decision', p_override_decision);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."ovr_severity_weight"("p_severity" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
  select case p_severity
    when 'level_1' then 1
    when 'level_2' then 2
    when 'level_3' then 3
    when 'level_4' then 5
    when 'sentinel' then 8
    else 1
  end;
$$;

COMMENT ON FUNCTION "public"."ovr_severity_weight"("p_severity" "text") IS 'Gate 9R category B: SECURITY INVOKER authenticated read/helper surface; fixed search_path; anon/PUBLIC denied.';

CREATE OR REPLACE FUNCTION "public"."ovr_signal_level"("p_weighted_score" integer, "p_major_or_sentinel" integer, "p_repeated_alerts" integer, "p_overdue_actions" integer) RETURNS "public"."risk_level"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
  select case
    when coalesce(p_major_or_sentinel, 0) >= 1
      or coalesce(p_weighted_score, 0) >= 25
      or coalesce(p_overdue_actions, 0) >= 3 then 'critical'::public.risk_level
    when coalesce(p_weighted_score, 0) >= 15
      or coalesce(p_repeated_alerts, 0) >= 2
      or coalesce(p_overdue_actions, 0) >= 1 then 'high'::public.risk_level
    when coalesce(p_weighted_score, 0) >= 6
      or coalesce(p_repeated_alerts, 0) >= 1 then 'medium'::public.risk_level
    else 'low'::public.risk_level
  end;
$$;

COMMENT ON FUNCTION "public"."ovr_signal_level"("p_weighted_score" integer, "p_major_or_sentinel" integer, "p_repeated_alerts" integer, "p_overdue_actions" integer) IS 'Gate 9R category B: SECURITY INVOKER authenticated read/helper surface; fixed search_path; anon/PUBLIC denied.';

CREATE OR REPLACE FUNCTION "public"."patch19_sync_profile_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.user_status is null or new.user_status not in ('active', 'inactive', 'archived', 'invited', 'locked') then
    new.user_status := 'active';
  end if;
  if new.user_type is null or new.user_type not in ('employee', 'contractor', 'vendor', 'external_auditor', 'service_account') then
    new.user_type := 'employee';
  end if;

  if new.user_status in ('inactive', 'archived', 'locked') then
    new.is_active := false;
    if new.deactivated_at is null then
      new.deactivated_at := now();
    end if;
  else
    new.is_active := true;
    if new.user_status = 'active' then
      new.deactivated_at := null;
      new.deactivated_by := null;
      new.deactivation_reason := null;
    end if;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."patch19_sync_profile_status"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."patch19_user_management_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_actor_org uuid;
  v_actor_is_super_admin boolean;
  v_actor_can_manage_users boolean;
  v_target_user uuid;
  v_target_org uuid;
  v_target_role public.app_role;
  v_result uuid;
  v_department_id uuid;
  v_old_profile jsonb;
  v_new_profile jsonb;
  v_linked_count integer := 0;
  v_batch_id uuid;
  v_rows jsonb;
  v_row jsonb;
  v_email text;
  v_status text;
  v_row_department_id uuid;
  v_row_role public.app_role;
  v_updated_count integer := 0;
  v_pending_count integer := 0;
begin
  if auth.role() <> 'service_role' then
    raise exception 'PATCH19_SERVICE_ROLE_REQUIRED';
  end if;

  select organization_id into v_actor_org
  from public.profiles
  where id = p_actor_id
    and is_active = true
    and coalesce(user_status, 'active') = 'active';

  if v_actor_org is null then
    raise exception 'PATCH19_ACTIVE_ACTOR_REQUIRED';
  end if;

  select exists (
    select 1 from public.user_roles
    where user_id = p_actor_id
      and is_active = true
      and role = 'super_admin'
  ) into v_actor_is_super_admin;

  select exists (
    select 1 from public.user_roles
    where user_id = p_actor_id
      and is_active = true
      and role in ('super_admin', 'governance_admin')
  ) into v_actor_can_manage_users;

  if not v_actor_can_manage_users then
    raise exception 'PATCH19_USER_ADMIN_REQUIRED';
  end if;

  if p_action not in (
    'patch19_update_user_profile',
    'patch19_update_user_department',
    'patch19_assign_user_role',
    'patch19_deactivate_user',
    'patch19_reactivate_user',
    'patch19_archive_user',
    'patch19_unarchive_user',
    'patch19_apply_import_batch'
  ) then
    raise exception 'PATCH19_ACTION_NOT_ALLOWED: %', p_action;
  end if;

  perform set_config('request.jwt.claim.sub', p_actor_id::text, true);
  perform set_config('request.jwt.claim.role', 'authenticated', true);

  if p_action = 'patch19_apply_import_batch' then
    v_rows := coalesce(p_payload->'rows', '[]'::jsonb);
    insert into public.user_management_import_batches (
      organization_id,
      file_name,
      row_count,
      valid_count,
      invalid_count,
      duplicate_email_count,
      unknown_department_count,
      unknown_role_count,
      status,
      validation_summary,
      created_by,
      applied_by,
      applied_at
    ) values (
      v_actor_org,
      nullif(p_payload->>'file_name', ''),
      jsonb_array_length(v_rows),
      coalesce((p_payload->>'valid_count')::integer, 0),
      coalesce((p_payload->>'invalid_count')::integer, 0),
      coalesce((p_payload->>'duplicate_email_count')::integer, 0),
      coalesce((p_payload->>'unknown_department_count')::integer, 0),
      coalesce((p_payload->>'unknown_role_count')::integer, 0),
      'applied',
      coalesce(p_payload->'validation_summary', '{}'::jsonb),
      p_actor_id,
      p_actor_id,
      now()
    )
    returning id into v_batch_id;

    for v_row in select value from jsonb_array_elements(v_rows)
    loop
      v_email := lower(trim(coalesce(v_row->>'email', '')));
      v_target_user := null;
      select id into v_target_user
      from public.profiles
      where organization_id = v_actor_org and lower(email) = v_email
      limit 1;

      insert into public.user_management_import_rows (
        organization_id,
        batch_id,
        row_number,
        raw_data,
        normalized_email,
        validation_status,
        validation_errors,
        validation_warnings,
        action_status,
        matched_user_id
      ) values (
        v_actor_org,
        v_batch_id,
        coalesce((v_row->>'row_number')::integer, 0),
        v_row,
        nullif(v_email, ''),
        coalesce(nullif(v_row->>'validation_status', ''), 'error'),
        coalesce(array(select jsonb_array_elements_text(coalesce(v_row->'validation_errors', '[]'::jsonb))), array[]::text[]),
        coalesce(array(select jsonb_array_elements_text(coalesce(v_row->'validation_warnings', '[]'::jsonb))), array[]::text[]),
        case
          when coalesce(v_row->>'validation_status', 'error') <> 'valid' then 'skipped_invalid'
          when v_target_user is null then 'pending_account_creation'
          else 'updated_existing_user'
        end,
        v_target_user
      );

      if coalesce(v_row->>'validation_status', 'error') = 'valid' and v_target_user is not null then
        v_status := coalesce(nullif(v_row->>'status', ''), 'active');
        v_row_department_id := nullif(v_row->>'department_id', '')::uuid;
        select to_jsonb(p) into v_old_profile from public.profiles p where p.id = v_target_user;

        update public.profiles
        set
          full_name_en = coalesce(nullif(v_row->>'full_name_en', ''), full_name_en),
          full_name_ar = nullif(v_row->>'full_name_ar', ''),
          employee_no = nullif(v_row->>'employee_no', ''),
          job_title = nullif(v_row->>'job_title', ''),
          department_id = v_row_department_id,
          user_type = coalesce(nullif(v_row->>'user_type', ''), user_type),
          user_status = v_status,
          deactivated_by = case when v_status in ('inactive', 'archived', 'locked') then p_actor_id else deactivated_by end,
          deactivation_reason = case when v_status in ('inactive', 'archived', 'locked') then 'Patch 19 CSV import' else deactivation_reason end,
          last_reviewed_at = now()
        where id = v_target_user;

        if v_status in ('inactive', 'archived', 'locked') then
          update public.user_roles set is_active = false where user_id = v_target_user and is_active = true;
        end if;

        if nullif(v_row->>'role', '') is not null and v_status in ('active', 'invited') then
          v_row_role := (v_row->>'role')::public.app_role;
          if v_row_role in ('super_admin', 'executive', 'governance_admin') and not v_actor_is_super_admin then
            raise exception 'PATCH19_PRIVILEGED_ROLE_REQUIRES_SUPER_ADMIN';
          end if;
          perform public.assign_user_role(
            v_target_user,
            v_row_role,
            case when v_row_department_id is null then 'assigned_only'::public.access_scope else 'department'::public.access_scope end,
            v_actor_org,
            null,
            v_row_department_id,
            null,
            'Patch 19 CSV import'
          );
        end if;

        select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
        insert into public.user_management_audit_history (
          organization_id, target_user_id, actor_id, action, reason, old_data, new_data
        ) values (
          v_actor_org, v_target_user, p_actor_id, 'import_applied', 'Patch 19 CSV import', v_old_profile, v_new_profile
        );
        v_updated_count := v_updated_count + 1;
      elsif coalesce(v_row->>'validation_status', 'error') = 'valid' and v_target_user is null then
        v_pending_count := v_pending_count + 1;
      end if;
    end loop;

    return jsonb_build_object('batch_id', v_batch_id, 'updated_count', v_updated_count, 'pending_account_creation_count', v_pending_count);
  end if;

  v_target_user := nullif(p_payload->>'user_id', '')::uuid;
  select p.organization_id, to_jsonb(p)
  into v_target_org, v_old_profile
  from public.profiles p
  where p.id = v_target_user;

  if v_target_user is null or v_target_org is null then
    raise exception 'PATCH19_TARGET_USER_NOT_FOUND';
  end if;

  if v_actor_org is distinct from v_target_org and not v_actor_is_super_admin then
    raise exception 'PATCH19_CROSS_ORG_DENIED';
  end if;

  select
    (
      (select count(*) from public.projects pr where pr.owner_id = v_target_user or pr.sponsor_id = v_target_user) +
      (select count(*) from public.tasks t where t.owner_id = v_target_user or t.assigned_to = v_target_user) +
      (select count(*) from public.approvals a where a.requested_by = v_target_user or a.approver_id = v_target_user) +
      (select count(*) from public.evidence_files e where e.uploaded_by = v_target_user or e.reviewed_by = v_target_user)
    )::integer
  into v_linked_count;

  if p_action in ('patch19_deactivate_user', 'patch19_archive_user') and v_target_user = p_actor_id then
    raise exception 'PATCH19_SELF_DEACTIVATION_DENIED';
  end if;

  if p_action in ('patch19_deactivate_user', 'patch19_archive_user') and exists (
    select 1 from public.user_roles
    where user_id = v_target_user and is_active = true and role = 'super_admin'
  ) and (
    select count(*)
    from public.user_roles
    where is_active = true and role = 'super_admin'
      and organization_id is not distinct from v_target_org
  ) <= 1 then
    raise exception 'PATCH19_LAST_SUPER_ADMIN_DEACTIVATION_DENIED';
  end if;

  if p_action = 'patch19_update_user_profile' then
    update public.profiles
    set
      full_name_en = coalesce(nullif(p_payload->>'full_name_en', ''), full_name_en),
      full_name_ar = nullif(p_payload->>'full_name_ar', ''),
      employee_no = nullif(p_payload->>'employee_no', ''),
      job_title = nullif(p_payload->>'job_title', ''),
      user_type = coalesce(nullif(p_payload->>'user_type', ''), user_type),
      last_reviewed_at = now()
    where id = v_target_user;
    select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org, v_target_user, p_actor_id, 'profile_updated', nullif(p_payload->>'reason', ''), v_old_profile, v_new_profile, v_linked_count
    );
    return jsonb_build_object('updated', true);
  end if;

  if p_action = 'patch19_update_user_department' then
    v_department_id := nullif(p_payload->>'department_id', '')::uuid;
    if v_department_id is not null and not exists (
      select 1 from public.departments
      where id = v_department_id and organization_id = v_target_org and is_active = true
    ) then
      raise exception 'PATCH19_DEPARTMENT_NOT_FOUND';
    end if;
    update public.profiles
    set department_id = v_department_id, last_reviewed_at = now()
    where id = v_target_user;
    select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org, v_target_user, p_actor_id, 'department_updated', nullif(p_payload->>'reason', ''), v_old_profile, v_new_profile, v_linked_count
    );
    return jsonb_build_object('updated', true);
  end if;

  if p_action = 'patch19_assign_user_role' then
    v_target_role := nullif(p_payload->>'role', '')::public.app_role;
    if v_target_role is null then
      raise exception 'PATCH19_ROLE_REQUIRED';
    end if;
    if v_target_role in ('super_admin', 'executive', 'governance_admin') and not v_actor_is_super_admin then
      raise exception 'PATCH19_PRIVILEGED_ROLE_REQUIRES_SUPER_ADMIN';
    end if;
    v_result := public.assign_user_role(
      v_target_user,
      v_target_role,
      coalesce(nullif(p_payload->>'scope', '')::public.access_scope, 'assigned_only'),
      v_target_org,
      nullif(p_payload->>'division_id', '')::uuid,
      nullif(p_payload->>'department_id', '')::uuid,
      nullif(p_payload->>'unit_id', '')::uuid,
      nullif(p_payload->>'reason', '')
    );
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org,
      v_target_user,
      p_actor_id,
      'role_assigned',
      nullif(p_payload->>'reason', ''),
      v_old_profile,
      jsonb_build_object('role_id', v_result, 'role', v_target_role),
      v_linked_count
    );
    return jsonb_build_object('id', v_result);
  end if;

  if p_action = 'patch19_deactivate_user' then
    update public.profiles
    set user_status = 'inactive',
        deactivated_by = p_actor_id,
        deactivation_reason = coalesce(nullif(p_payload->>'reason', ''), 'App-level deactivation'),
        last_reviewed_at = now()
    where id = v_target_user;
    update public.user_roles set is_active = false where user_id = v_target_user and is_active = true;
    select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org, v_target_user, p_actor_id, 'deactivated', nullif(p_payload->>'reason', ''), v_old_profile, v_new_profile, v_linked_count
    );
    return jsonb_build_object('updated', true);
  end if;

  if p_action = 'patch19_reactivate_user' then
    update public.profiles
    set user_status = 'active',
        last_reviewed_at = now()
    where id = v_target_user;
    select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org, v_target_user, p_actor_id, 'reactivated', nullif(p_payload->>'reason', ''), v_old_profile, v_new_profile, v_linked_count
    );
    return jsonb_build_object('updated', true);
  end if;

  if p_action = 'patch19_archive_user' then
    update public.profiles
    set user_status = 'archived',
        deactivated_by = p_actor_id,
        deactivation_reason = coalesce(nullif(p_payload->>'reason', ''), 'App-level archive'),
        last_reviewed_at = now()
    where id = v_target_user;
    update public.user_roles set is_active = false where user_id = v_target_user and is_active = true;
    select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org, v_target_user, p_actor_id, 'archived', nullif(p_payload->>'reason', ''), v_old_profile, v_new_profile, v_linked_count
    );
    return jsonb_build_object('updated', true);
  end if;

  if p_action = 'patch19_unarchive_user' then
    update public.profiles
    set user_status = 'active',
        last_reviewed_at = now()
    where id = v_target_user;
    select to_jsonb(p) into v_new_profile from public.profiles p where p.id = v_target_user;
    insert into public.user_management_audit_history (
      organization_id, target_user_id, actor_id, action, reason, old_data, new_data, linked_record_count
    ) values (
      v_target_org, v_target_user, p_actor_id, 'unarchived', nullif(p_payload->>'reason', ''), v_old_profile, v_new_profile, v_linked_count
    );
    return jsonb_build_object('updated', true);
  end if;

  raise exception 'PATCH19_UNREACHABLE_ACTION';
end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch22_risk_level_from_score"("p_score" integer) RETURNS "public"."risk_level"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select case
    when coalesce(p_score, 0) >= 20 then 'critical'::public.risk_level
    when coalesce(p_score, 0) >= 12 then 'high'::public.risk_level
    when coalesce(p_score, 0) >= 6 then 'medium'::public.risk_level
    else 'low'::public.risk_level
  end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch22_risk_workflow_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_jwt_role text := coalesce(current_setting('request.jwt.claim.role', true), current_user);
  v_actor public.profiles%rowtype;
  v_risk public.risks%rowtype;
  v_action text := lower(coalesce(p_action, ''));
  v_risk_id uuid := nullif(p_payload->>'risk_id', '')::uuid;
  v_can_manage boolean := false;
  v_is_owner boolean := false;
  v_old_status text;
  v_new_status text;
  v_reason text := nullif(trim(coalesce(p_payload->>'reason', p_payload->>'note', p_payload->>'change_reason', '')), '');
  v_likelihood smallint;
  v_impact smallint;
  v_residual_likelihood smallint;
  v_residual_impact smallint;
  v_residual_score integer;
  v_appetite_threshold integer;
  v_blocker text;
begin
  if v_jwt_role <> 'service_role' and current_user <> 'service_role' then
    raise exception 'PATCH22_RISK_SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_actor
  from public.profiles
  where id = p_actor_id and is_active = true;

  if not found or v_actor.organization_id is null then
    raise exception 'PATCH22_RISK_ACTIVE_ACTOR_REQUIRED';
  end if;

  if v_action not in (
    'update_risk_assessment',
    'request_risk_acceptance',
    'approve_risk_acceptance',
    'reject_risk_acceptance',
    'update_risk_treatment',
    'complete_risk_treatment',
    'request_risk_closure',
    'approve_risk_closure',
    'reopen_risk_with_reason',
    'link_risk_source',
    'mark_duplicate_risk'
  ) then
    raise exception 'PATCH22_RISK_UNSUPPORTED_ACTION';
  end if;

  if v_risk_id is null then
    raise exception 'PATCH22_RISK_ID_REQUIRED';
  end if;

  select * into v_risk
  from public.risks
  where id = v_risk_id
  for update;

  if not found then
    raise exception 'PATCH22_RISK_NOT_FOUND';
  end if;

  if v_actor.organization_id is distinct from v_risk.organization_id then
    raise exception 'PATCH22_RISK_CROSS_ORGANIZATION_DENIED';
  end if;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role::text in ('super_admin','executive','governance_admin','division_head','department_manager','compliance_officer','auditor')
      and (ur.organization_id is null or ur.organization_id is not distinct from v_risk.organization_id)
  ) into v_can_manage;

  v_is_owner := p_actor_id in (
    v_risk.owner_id,
    v_risk.risk_owner_id,
    v_risk.control_owner_id,
    v_risk.treatment_owner_id,
    v_risk.executive_sponsor_id
  );

  if not (v_can_manage or v_is_owner) then
    raise exception 'PATCH22_RISK_NOT_AUTHORIZED';
  end if;

  v_old_status := v_risk.status::text;

  if v_action = 'update_risk_assessment' then
    v_likelihood := coalesce(nullif(p_payload->>'inherent_likelihood', '')::smallint, nullif(p_payload->>'likelihood', '')::smallint, v_risk.likelihood);
    v_impact := coalesce(nullif(p_payload->>'inherent_impact', '')::smallint, nullif(p_payload->>'impact', '')::smallint, v_risk.impact);
    v_residual_likelihood := coalesce(nullif(p_payload->>'residual_likelihood', '')::smallint, v_risk.residual_likelihood);
    v_residual_impact := coalesce(nullif(p_payload->>'residual_impact', '')::smallint, v_risk.residual_impact);
    v_residual_score := v_residual_likelihood * v_residual_impact;
    v_appetite_threshold := coalesce(nullif(p_payload->>'appetite_threshold', '')::integer, v_risk.appetite_threshold, 12);

    if v_likelihood not between 1 and 5 or v_impact not between 1 and 5 or v_residual_likelihood not between 1 and 5 or v_residual_impact not between 1 and 5 then
      raise exception 'PATCH22_RISK_SCORE_RANGE_REQUIRED';
    end if;
    if v_reason is null then
      raise exception 'PATCH22_RISK_SCORE_CHANGE_REASON_REQUIRED';
    end if;

    insert into public.risk_reassessment_history (
      organization_id,
      risk_id,
      previous_likelihood,
      previous_impact,
      previous_score,
      new_likelihood,
      new_impact,
      new_score,
      previous_residual_likelihood,
      previous_residual_impact,
      previous_residual_score,
      new_residual_likelihood,
      new_residual_impact,
      new_residual_score,
      change_reason,
      changed_by
    )
    values (
      v_risk.organization_id,
      v_risk.id,
      v_risk.likelihood,
      v_risk.impact,
      v_risk.inherent_score,
      v_likelihood,
      v_impact,
      v_likelihood * v_impact,
      v_risk.residual_likelihood,
      v_risk.residual_impact,
      v_risk.residual_score,
      v_residual_likelihood,
      v_residual_impact,
      v_residual_score,
      v_reason,
      p_actor_id
    );

    update public.risks
    set
      likelihood = v_likelihood,
      impact = v_impact,
      inherent_likelihood = v_likelihood,
      inherent_impact = v_impact,
      residual_likelihood = v_residual_likelihood,
      residual_impact = v_residual_impact,
      risk_level = public.patch22_risk_level_from_score(v_residual_score),
      scoring_method = coalesce(nullif(p_payload->>'scoring_method', ''), scoring_method, 'standard_5x5'),
      score_last_changed_at = now(),
      score_last_changed_by = p_actor_id,
      appetite_threshold = v_appetite_threshold,
      appetite_breached = v_residual_score >= v_appetite_threshold,
      appetite_level = case
        when v_residual_score >= 20 then 'critical_breach'
        when v_residual_score >= v_appetite_threshold then 'above_appetite'
        else 'within_appetite'
      end,
      appetite_breach_reason = case
        when v_residual_score >= v_appetite_threshold then coalesce(nullif(p_payload->>'appetite_breach_reason', ''), v_reason)
        else null
      end,
      treatment_required = (v_residual_score >= 12 and acceptance_status <> 'approved'),
      treatment_status = case
        when v_residual_score >= 12 and treatment_status in ('not_required','completed','accepted') and acceptance_status <> 'approved' then 'required'
        else treatment_status
      end,
      acceptance_required = v_residual_score >= v_appetite_threshold or response_type = 'accept',
      acceptance_status = case
        when v_residual_score >= v_appetite_threshold and acceptance_status in ('not_required','withdrawn') then 'required'
        else acceptance_status
      end,
      escalation_required = v_residual_score >= 12 or risk_level in ('critical','high'),
      escalation_level = case
        when v_residual_score >= 20 then 'executive'
        when v_residual_score >= 12 then 'management'
        else escalation_level
      end,
      executive_visible = case
        when v_residual_score >= 20 then true
        when v_residual_score >= 12 and nullif(trim(coalesce(executive_visibility_override_reason, '')), '') is null then true
        else executive_visible
      end,
      lifecycle_status = case
        when v_residual_score >= 12 then 'treatment_required'
        else 'assessed'
      end,
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, v_old_status, 'update_risk_assessment', v_reason, p_actor_id);

  elsif v_action = 'request_risk_acceptance' then
    if v_reason is null then
      raise exception 'PATCH22_RISK_ACCEPTANCE_REASON_REQUIRED';
    end if;
    if nullif(p_payload->>'acceptance_expiry_date', '') is null then
      raise exception 'PATCH22_RISK_ACCEPTANCE_EXPIRY_REQUIRED';
    end if;

    update public.risks
    set
      acceptance_required = true,
      acceptance_status = 'requested',
      acceptance_requested_by = p_actor_id,
      acceptance_requested_at = now(),
      acceptance_expiry_date = (p_payload->>'acceptance_expiry_date')::date,
      acceptance_reason = v_reason,
      lifecycle_status = 'acceptance_requested',
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, 'acceptance_requested', 'request_risk_acceptance', v_reason, p_actor_id);

  elsif v_action in ('approve_risk_acceptance','reject_risk_acceptance') then
    if not v_can_manage then
      raise exception 'PATCH22_RISK_ACCEPTANCE_APPROVER_REQUIRED';
    end if;
    if v_action = 'approve_risk_acceptance' and (v_risk.acceptance_reason is null or v_risk.acceptance_expiry_date is null) then
      raise exception 'PATCH22_RISK_ACCEPTANCE_REASON_AND_EXPIRY_REQUIRED';
    end if;
    v_new_status := case when v_action = 'approve_risk_acceptance' then 'accepted' else 'under_review' end;

    update public.risks
    set
      status = case when v_action = 'approve_risk_acceptance' then 'accepted'::public.risk_status else 'under_review'::public.risk_status end,
      acceptance_status = case when v_action = 'approve_risk_acceptance' then 'approved' else 'rejected' end,
      accepted_by = case when v_action = 'approve_risk_acceptance' then p_actor_id else accepted_by end,
      accepted_at = case when v_action = 'approve_risk_acceptance' then now() else accepted_at end,
      treatment_required = case when v_action = 'approve_risk_acceptance' then false else treatment_required end,
      treatment_status = case when v_action = 'approve_risk_acceptance' then 'accepted' else treatment_status end,
      lifecycle_status = case when v_action = 'approve_risk_acceptance' then 'accepted' else 'assessed' end,
      next_review_date = case
        when v_action = 'approve_risk_acceptance' then least(coalesce(acceptance_expiry_date, current_date + 90), current_date + 90)
        else next_review_date
      end,
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, v_new_status, v_action, v_reason, p_actor_id);

  elsif v_action = 'update_risk_treatment' then
    update public.risks
    set
      treatment_required = true,
      treatment_status = coalesce(nullif(p_payload->>'treatment_status', ''), 'planned'),
      treatment_plan_summary = coalesce(nullif(p_payload->>'treatment_plan_summary', ''), treatment_plan_summary),
      treatment_due_date = coalesce(nullif(p_payload->>'treatment_due_date', '')::date, treatment_due_date),
      treatment_owner_id = coalesce(nullif(p_payload->>'treatment_owner_id', '')::uuid, treatment_owner_id, p_actor_id),
      lifecycle_status = 'treatment_in_progress',
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, v_old_status, 'update_risk_treatment', v_reason, p_actor_id);

  elsif v_action = 'complete_risk_treatment' then
    update public.risks
    set
      treatment_status = 'completed',
      treatment_completed_at = now(),
      lifecycle_status = 'monitoring',
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, v_old_status, 'complete_risk_treatment', coalesce(v_reason, 'Treatment completed.'), p_actor_id);

  elsif v_action = 'request_risk_closure' then
    if v_reason is null then
      raise exception 'PATCH22_RISK_CLOSURE_REASON_REQUIRED';
    end if;

    update public.risks
    set
      closure_requested_at = now(),
      closure_requested_by = p_actor_id,
      closure_reason = v_reason,
      lifecycle_status = 'closure_requested',
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, 'closure_requested', 'request_risk_closure', v_reason, p_actor_id);

  elsif v_action = 'approve_risk_closure' then
    if not v_can_manage then
      raise exception 'PATCH22_RISK_CLOSURE_APPROVER_REQUIRED';
    end if;

    select blocker_reason into v_blocker
    from public.v_patch22_risk_closure_blockers
    where risk_id = v_risk.id
    limit 1;

    if v_blocker is not null then
      update public.risks set closure_blocker = v_blocker where id = v_risk.id;
      raise exception 'PATCH22_RISK_CLOSURE_BLOCKED: %', v_blocker;
    end if;

    update public.risks
    set
      status = 'closed'::public.risk_status,
      lifecycle_status = 'closed',
      closure_approved_by = p_actor_id,
      closure_approved_at = now(),
      closed_by = p_actor_id,
      closed_at = now(),
      closure_blocker = null,
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, 'closed', 'approve_risk_closure', v_reason, p_actor_id);

  elsif v_action = 'reopen_risk_with_reason' then
    if v_reason is null then
      raise exception 'PATCH22_RISK_REOPEN_REASON_REQUIRED';
    end if;

    update public.risks
    set
      status = 'open'::public.risk_status,
      lifecycle_status = 'reopened',
      closure_requested_at = null,
      closure_approved_by = null,
      closure_approved_at = null,
      closed_by = null,
      closed_at = null,
      closure_blocker = null,
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, 'open', 'reopen_risk_with_reason', v_reason, p_actor_id);

  elsif v_action = 'link_risk_source' then
    update public.risks
    set
      source_ovr_id = coalesce(nullif(p_payload->>'source_ovr_id', '')::uuid, source_ovr_id),
      source_audit_finding_id = coalesce(nullif(p_payload->>'source_audit_finding_id', '')::uuid, source_audit_finding_id),
      source_compliance_id = coalesce(nullif(p_payload->>'source_compliance_id', '')::uuid, source_compliance_id),
      source_project_id = coalesce(nullif(p_payload->>'source_project_id', '')::uuid, source_project_id),
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, v_old_status, 'link_risk_source', v_reason, p_actor_id);

  elsif v_action = 'mark_duplicate_risk' then
    if nullif(p_payload->>'duplicate_of_risk_id', '') is null then
      raise exception 'PATCH22_DUPLICATE_RISK_ID_REQUIRED';
    end if;

    update public.risks
    set
      duplicate_of_risk_id = (p_payload->>'duplicate_of_risk_id')::uuid,
      repeat_signal_flag = true,
      related_risk_ids = array_append(coalesce(related_risk_ids, '{}'), (p_payload->>'duplicate_of_risk_id')::uuid),
      updated_by = p_actor_id
    where id = v_risk.id;

    perform public.patch22_write_risk_event(v_risk.organization_id, v_risk.id, v_old_status, v_old_status, 'mark_duplicate_risk', v_reason, p_actor_id);
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'action', v_action,
    'risk_id', v_risk.id
  );
end;
$$;

COMMENT ON FUNCTION "public"."patch22_risk_workflow_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb") IS 'Patch 22 service-role bridge for governed risk workflow actions. Browser code must call through the authenticated Edge bridge, not service-role credentials.';

CREATE OR REPLACE FUNCTION "public"."patch22_write_risk_event"("p_organization_id" "uuid", "p_risk_id" "uuid", "p_from_status" "text", "p_to_status" "text", "p_action" "text", "p_note" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.risk_workflow_events (
    organization_id, risk_id, from_status, to_status, action, note, actor_id
  )
  values (
    p_organization_id, p_risk_id, p_from_status, p_to_status, p_action, nullif(trim(coalesce(p_note, '')), ''), p_actor_id
  );

  insert into public.audit_logs (
    organization_id, actor_id, action, table_name, record_id, old_data, new_data
  )
  values (
    p_organization_id,
    p_actor_id,
    'patch22_' || p_action,
    'risks',
    p_risk_id,
    jsonb_build_object('from_status', p_from_status),
    jsonb_build_object('to_status', p_to_status, 'note', p_note)
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch23_evidence_governance_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_jwt_role text := coalesce(current_setting('request.jwt.claim.role', true), current_user);
  v_actor public.profiles%rowtype;
  v_action text := lower(coalesce(p_action, ''));
  v_evidence public.evidence_files%rowtype;
  v_requirement public.evidence_requirements%rowtype;
  v_evidence_id uuid := nullif(p_payload->>'evidence_file_id', '')::uuid;
  v_requirement_id uuid := nullif(p_payload->>'requirement_id', '')::uuid;
  v_can_manage boolean := false;
  v_can_review boolean := false;
  v_is_owner boolean := false;
  v_old_status text;
  v_new_status text;
  v_note text := nullif(trim(coalesce(p_payload->>'note', p_payload->>'reason', p_payload->>'review_note', p_payload->>'audit_note', '')), '');
  v_result jsonb := '{}'::jsonb;
  v_linked_item_type text := nullif(p_payload->>'linked_item_type', '');
  v_linked_item_id uuid := nullif(p_payload->>'linked_item_id', '')::uuid;
  v_accepted_count integer;
  v_waiver_active boolean;
begin
  if v_jwt_role <> 'service_role' and current_user <> 'service_role' then
    raise exception 'PATCH23_EVIDENCE_SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_actor
  from public.profiles
  where id = p_actor_id and is_active = true;

  if not found or v_actor.organization_id is null then
    raise exception 'PATCH23_EVIDENCE_ACTIVE_ACTOR_REQUIRED';
  end if;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role::text in ('super_admin','governance_admin','executive','auditor','compliance_officer','department_manager')
      and (ur.organization_id is null or ur.organization_id is not distinct from v_actor.organization_id)
  ) into v_can_manage;

  v_can_review := v_can_manage;

  if v_action not in (
    'create_evidence_requirement',
    'link_evidence_to_item',
    'submit_evidence_for_review',
    'accept_evidence',
    'reject_evidence',
    'request_evidence_revision',
    'supersede_evidence',
    'lock_evidence',
    'request_evidence_gate_waiver',
    'approve_evidence_gate_waiver',
    'reject_evidence_gate_waiver',
    'check_evidence_gate_status',
    'generate_evidence_pack_index'
  ) then
    raise exception 'PATCH23_EVIDENCE_UNSUPPORTED_ACTION';
  end if;

  if v_action = 'create_evidence_requirement' then
    if not v_can_manage then
      raise exception 'PATCH23_EVIDENCE_REQUIREMENT_ADMIN_REQUIRED';
    end if;
    if v_linked_item_type is null or v_linked_item_id is null then
      raise exception 'PATCH23_EVIDENCE_LINKED_ITEM_REQUIRED';
    end if;

    insert into public.evidence_requirements (
      organization_id,
      requirement_code,
      linked_item_type,
      linked_item_id,
      requirement_title,
      requirement_description,
      evidence_type_required,
      minimum_accepted_files,
      sensitivity_required,
      due_date,
      required_for_gate,
      owner_id,
      reviewer_role,
      reviewer_id,
      created_by
    )
    values (
      v_actor.organization_id,
      coalesce(nullif(p_payload->>'requirement_code', ''), 'ER-' || replace(left(gen_random_uuid()::text, 8), '-', '')),
      v_linked_item_type,
      v_linked_item_id,
      coalesce(nullif(p_payload->>'requirement_title', ''), 'Evidence requirement'),
      nullif(p_payload->>'requirement_description', ''),
      nullif(p_payload->>'evidence_type_required', ''),
      coalesce(nullif(p_payload->>'minimum_accepted_files', '')::integer, 1),
      nullif(p_payload->>'sensitivity_required', ''),
      nullif(p_payload->>'due_date', '')::date,
      coalesce(nullif(p_payload->>'required_for_gate', ''), 'closure'),
      coalesce(nullif(p_payload->>'owner_id', '')::uuid, p_actor_id),
      nullif(p_payload->>'reviewer_role', ''),
      nullif(p_payload->>'reviewer_id', '')::uuid,
      p_actor_id
    )
    on conflict (organization_id, requirement_code) do update set
      requirement_title = excluded.requirement_title,
      requirement_description = excluded.requirement_description,
      evidence_type_required = excluded.evidence_type_required,
      minimum_accepted_files = excluded.minimum_accepted_files,
      sensitivity_required = excluded.sensitivity_required,
      due_date = excluded.due_date,
      required_for_gate = excluded.required_for_gate,
      owner_id = excluded.owner_id,
      reviewer_role = excluded.reviewer_role,
      reviewer_id = excluded.reviewer_id,
      updated_at = now(),
      is_active = true
    returning * into v_requirement;

    v_result := jsonb_build_object('requirement_id', v_requirement.id, 'gate_status', v_requirement.gate_status);

  else
    if v_evidence_id is not null then
      select * into v_evidence
      from public.evidence_files
      where id = v_evidence_id
      for update;
      if not found then
        raise exception 'PATCH23_EVIDENCE_NOT_FOUND';
      end if;
      if v_evidence.organization_id is distinct from v_actor.organization_id then
        raise exception 'PATCH23_EVIDENCE_CROSS_ORGANIZATION_DENIED';
      end if;
      v_is_owner := p_actor_id in (v_evidence.uploaded_by, v_evidence.evidence_owner_id, v_evidence.reviewer_id, v_evidence.reviewed_by);
      if v_evidence.locked_at is not null and not v_can_manage and v_action not in ('check_evidence_gate_status','generate_evidence_pack_index') then
        raise exception 'PATCH23_EVIDENCE_LOCKED';
      end if;
    end if;

    if v_requirement_id is not null then
      select * into v_requirement
      from public.evidence_requirements
      where id = v_requirement_id
      for update;
      if not found then
        raise exception 'PATCH23_EVIDENCE_REQUIREMENT_NOT_FOUND';
      end if;
      if v_requirement.organization_id is distinct from v_actor.organization_id then
        raise exception 'PATCH23_EVIDENCE_CROSS_ORGANIZATION_DENIED';
      end if;
    end if;

    if v_action in ('link_evidence_to_item','submit_evidence_for_review','supersede_evidence') and not (v_can_manage or v_is_owner) then
      raise exception 'PATCH23_EVIDENCE_NOT_AUTHORIZED';
    end if;

    if v_action in ('accept_evidence','reject_evidence','request_evidence_revision','lock_evidence') and not v_can_review then
      raise exception 'PATCH23_EVIDENCE_REVIEWER_REQUIRED';
    end if;

    if v_action = 'link_evidence_to_item' then
      if v_evidence_id is null or v_linked_item_type is null or v_linked_item_id is null then
        raise exception 'PATCH23_EVIDENCE_LINK_PAYLOAD_REQUIRED';
      end if;
      insert into public.evidence_links (
        organization_id,
        evidence_file_id,
        linked_item_type,
        linked_item_id,
        linked_item_title,
        link_reason,
        is_primary,
        required_for_closure,
        required_for_acceptance,
        required_for_approval,
        required_for_treatment,
        linked_by
      )
      values (
        v_actor.organization_id,
        v_evidence_id,
        v_linked_item_type,
        v_linked_item_id,
        nullif(p_payload->>'linked_item_title', ''),
        v_note,
        coalesce((p_payload->>'is_primary')::boolean, false),
        coalesce((p_payload->>'required_for_closure')::boolean, false),
        coalesce((p_payload->>'required_for_acceptance')::boolean, false),
        coalesce((p_payload->>'required_for_approval')::boolean, false),
        coalesce((p_payload->>'required_for_treatment')::boolean, false),
        p_actor_id
      )
      on conflict (organization_id, evidence_file_id, linked_item_type, linked_item_id) do update set
        linked_item_title = excluded.linked_item_title,
        link_reason = excluded.link_reason,
        is_primary = excluded.is_primary,
        required_for_closure = excluded.required_for_closure,
        required_for_acceptance = excluded.required_for_acceptance,
        required_for_approval = excluded.required_for_approval,
        required_for_treatment = excluded.required_for_treatment,
        linked_by = excluded.linked_by,
        linked_at = now(),
        is_active = true;

      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'linked', v_evidence.review_status, v_evidence.review_status, p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'linked_item_type', v_linked_item_type, 'linked_item_id', v_linked_item_id);

    elsif v_action = 'submit_evidence_for_review' then
      v_old_status := v_evidence.review_status;
      update public.evidence_files
      set
        review_status = 'pending_review',
        status = 'submitted',
        review_required = true,
        review_due_date = coalesce(nullif(p_payload->>'review_due_date', '')::date, review_due_date, current_date + 7),
        reviewer_id = coalesce(nullif(p_payload->>'reviewer_id', '')::uuid, reviewer_id),
        updated_by = p_actor_id
      where id = v_evidence_id;
      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'submitted_for_review', v_old_status, 'pending_review', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'review_status', 'pending_review');

    elsif v_action = 'accept_evidence' then
      if v_evidence.uploaded_by = p_actor_id and not v_can_manage then
        raise exception 'PATCH23_EVIDENCE_REVIEWER_SEPARATION_REQUIRED';
      end if;
      if v_evidence.sensitivity_level in ('confidential','highly_sensitive','restricted') and nullif(trim(coalesce(v_evidence.classification_reason, '')), '') is null then
        raise exception 'PATCH23_EVIDENCE_CLASSIFICATION_REASON_REQUIRED';
      end if;
      v_old_status := v_evidence.review_status;
      update public.evidence_files
      set
        review_status = 'accepted',
        status = 'accepted',
        reviewer_id = coalesce(reviewer_id, p_actor_id),
        reviewed_by = p_actor_id,
        reviewed_at = now(),
        review_note = v_note,
        rejection_reason = null,
        revision_required = false,
        revision_due_date = null,
        updated_by = p_actor_id
      where id = v_evidence_id;
      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'accepted', v_old_status, 'accepted', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'review_status', 'accepted');

    elsif v_action = 'reject_evidence' then
      if v_note is null then
        raise exception 'PATCH23_EVIDENCE_REJECTION_REASON_REQUIRED';
      end if;
      v_old_status := v_evidence.review_status;
      update public.evidence_files
      set
        review_status = 'rejected',
        status = 'rejected',
        reviewer_id = coalesce(reviewer_id, p_actor_id),
        reviewed_by = p_actor_id,
        reviewed_at = now(),
        review_note = v_note,
        rejection_reason = v_note,
        revision_required = true,
        revision_due_date = coalesce(nullif(p_payload->>'revision_due_date', '')::date, current_date + 7),
        updated_by = p_actor_id
      where id = v_evidence_id;
      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'rejected', v_old_status, 'rejected', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'review_status', 'rejected');

    elsif v_action = 'request_evidence_revision' then
      v_old_status := v_evidence.review_status;
      update public.evidence_files
      set
        review_status = 'needs_revision',
        status = 'needs_revision',
        revision_required = true,
        revision_due_date = coalesce(nullif(p_payload->>'revision_due_date', '')::date, current_date + 7),
        review_note = coalesce(v_note, review_note),
        rejection_reason = coalesce(v_note, rejection_reason),
        updated_by = p_actor_id
      where id = v_evidence_id;
      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'needs_revision', v_old_status, 'needs_revision', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'review_status', 'needs_revision');

    elsif v_action = 'supersede_evidence' then
      if nullif(p_payload->>'superseded_by_evidence_id', '') is null then
        raise exception 'PATCH23_EVIDENCE_SUPERSEDED_BY_REQUIRED';
      end if;
      v_old_status := v_evidence.review_status;
      update public.evidence_files
      set
        review_status = 'superseded',
        is_current_version = false,
        superseded_by_evidence_id = (p_payload->>'superseded_by_evidence_id')::uuid,
        updated_by = p_actor_id
      where id = v_evidence_id;
      update public.evidence_files
      set
        version_number = greatest(version_number, v_evidence.version_number + 1),
        is_current_version = true,
        updated_by = p_actor_id
      where id = (p_payload->>'superseded_by_evidence_id')::uuid
        and organization_id = v_actor.organization_id;
      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'superseded', v_old_status, 'superseded', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'review_status', 'superseded');

    elsif v_action = 'lock_evidence' then
      v_old_status := v_evidence.review_status;
      update public.evidence_files
      set
        locked_at = now(),
        locked_by = p_actor_id,
        review_status = 'locked',
        updated_by = p_actor_id
      where id = v_evidence_id;
      perform public.patch23_write_evidence_event(v_actor.organization_id, v_evidence_id, 'locked', v_old_status, 'locked', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('evidence_file_id', v_evidence_id, 'review_status', 'locked');

    elsif v_action = 'request_evidence_gate_waiver' then
      if v_requirement_id is null or v_note is null then
        raise exception 'PATCH23_EVIDENCE_WAIVER_REASON_REQUIRED';
      end if;
      if not (v_can_manage or v_requirement.owner_id = p_actor_id) then
        raise exception 'PATCH23_EVIDENCE_NOT_AUTHORIZED';
      end if;
      insert into public.evidence_gate_waivers (
        organization_id,
        requirement_id,
        linked_item_type,
        linked_item_id,
        waiver_reason,
        requested_by,
        expiry_date,
        audit_note
      )
      values (
        v_actor.organization_id,
        v_requirement_id,
        v_requirement.linked_item_type,
        v_requirement.linked_item_id,
        v_note,
        p_actor_id,
        nullif(p_payload->>'expiry_date', '')::date,
        nullif(p_payload->>'audit_note', '')
      );
      insert into public.evidence_review_events (organization_id, evidence_file_id, event_type, actor_id, note, metadata)
      values (v_actor.organization_id, null, 'waiver_requested', p_actor_id, v_note, p_payload);
      v_result := jsonb_build_object('requirement_id', v_requirement_id, 'waiver_status', 'requested');

    elsif v_action in ('approve_evidence_gate_waiver','reject_evidence_gate_waiver') then
      if not v_can_manage then
        raise exception 'PATCH23_EVIDENCE_WAIVER_APPROVER_REQUIRED';
      end if;
      if nullif(p_payload->>'waiver_id', '') is null then
        raise exception 'PATCH23_EVIDENCE_WAIVER_ID_REQUIRED';
      end if;
      update public.evidence_gate_waivers
      set
        status = case when v_action = 'approve_evidence_gate_waiver' then 'approved' else 'rejected' end,
        approved_by = case when v_action = 'approve_evidence_gate_waiver' then p_actor_id else approved_by end,
        approved_at = case when v_action = 'approve_evidence_gate_waiver' then now() else approved_at end,
        audit_note = coalesce(v_note, audit_note)
      where id = (p_payload->>'waiver_id')::uuid
        and organization_id = v_actor.organization_id
      returning requirement_id into v_requirement_id;
      if v_requirement_id is null then
        raise exception 'PATCH23_EVIDENCE_WAIVER_NOT_FOUND';
      end if;
      insert into public.evidence_review_events (organization_id, evidence_file_id, event_type, actor_id, note, metadata)
      values (
        v_actor.organization_id,
        null,
        case when v_action = 'approve_evidence_gate_waiver' then 'waiver_approved' else 'waiver_rejected' end,
        p_actor_id,
        v_note,
        p_payload
      );
      v_result := jsonb_build_object('requirement_id', v_requirement_id, 'waiver_status', case when v_action = 'approve_evidence_gate_waiver' then 'approved' else 'rejected' end);

    elsif v_action in ('check_evidence_gate_status','generate_evidence_pack_index') then
      if not v_can_manage and v_linked_item_type is null then
        raise exception 'PATCH23_EVIDENCE_NOT_AUTHORIZED';
      end if;
      if v_requirement_id is not null then
        select accepted_evidence_count, waiver_active
        into v_accepted_count, v_waiver_active
        from public.v_patch23_evidence_closure_gate_status
        where requirement_id = v_requirement_id
        limit 1;
      else
        select coalesce(sum(accepted_evidence_count), 0)::integer, bool_or(waiver_active)
        into v_accepted_count, v_waiver_active
        from public.v_patch23_evidence_closure_gate_status
        where linked_item_type = v_linked_item_type
          and linked_item_id = v_linked_item_id
          and organization_id = v_actor.organization_id;
      end if;
      v_result := jsonb_build_object(
        'accepted_evidence_count', coalesce(v_accepted_count, 0),
        'waiver_active', coalesce(v_waiver_active, false),
        'can_close', coalesce(v_accepted_count, 0) > 0 or coalesce(v_waiver_active, false)
      );
    end if;
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'action', v_action,
    'result', v_result
  );
end;
$$;

COMMENT ON FUNCTION "public"."patch23_evidence_governance_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb") IS 'Patch 23 service-role evidence governance bridge. Browser code must call through the authenticated Edge bridge, not service-role credentials.';

CREATE OR REPLACE FUNCTION "public"."patch23_write_evidence_event"("p_organization_id" "uuid", "p_evidence_file_id" "uuid", "p_event_type" "text", "p_from_status" "text", "p_to_status" "text", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  insert into public.evidence_review_events (
    organization_id,
    evidence_file_id,
    event_type,
    from_status,
    to_status,
    actor_id,
    note,
    metadata
  )
  values (
    p_organization_id,
    p_evidence_file_id,
    p_event_type,
    p_from_status,
    p_to_status,
    p_actor_id,
    p_note,
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch24_audit_closure_satisfied"("p_audit_finding_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce((
    select can_close
    from public.v_patch24_audit_closure_gate_status
    where audit_finding_id = p_audit_finding_id
    limit 1
  ), false);
$$;

CREATE OR REPLACE FUNCTION "public"."patch24_audit_finding_workflow_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_jwt_role text := coalesce(current_setting('request.jwt.claim.role', true), current_user);
  v_actor public.profiles%rowtype;
  v_finding public.audit_findings%rowtype;
  v_action text := lower(coalesce(p_action, ''));
  v_finding_id uuid := coalesce(nullif(p_payload->>'audit_finding_id', '')::uuid, nullif(p_payload->>'finding_id', '')::uuid);
  v_extension_id uuid := nullif(p_payload->>'extension_id', '')::uuid;
  v_can_manage boolean := false;
  v_is_owner boolean := false;
  v_old_status text;
  v_new_status text;
  v_note text := nullif(trim(coalesce(p_payload->>'note', p_payload->>'reason', p_payload->>'audit_note', '')), '');
  v_reason text := nullif(trim(coalesce(p_payload->>'reason', p_payload->>'rejection_reason', p_payload->>'extension_reason', p_payload->>'reopen_reason', p_payload->>'note', '')), '');
  v_response text := nullif(trim(coalesce(p_payload->>'management_response', p_payload->>'response', '')), '');
  v_action_plan text := nullif(trim(coalesce(p_payload->>'corrective_action_plan', p_payload->>'action_plan', '')), '');
  v_due_date date;
  v_blocker text;
  v_pack_reference text;
  v_result jsonb := '{}'::jsonb;
begin
  if v_jwt_role <> 'service_role' and current_user <> 'service_role' then
    raise exception 'PATCH24_AUDIT_SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_actor
  from public.profiles
  where id = p_actor_id and is_active = true;

  if not found or v_actor.organization_id is null then
    raise exception 'PATCH24_AUDIT_ACTIVE_ACTOR_REQUIRED';
  end if;

  if v_action not in (
    'issue_audit_finding',
    'submit_management_response',
    'accept_management_response',
    'reject_management_response',
    'submit_corrective_action_plan',
    'accept_corrective_action_plan',
    'reject_corrective_action_plan',
    'request_audit_finding_extension',
    'approve_audit_finding_extension',
    'reject_audit_finding_extension',
    'request_audit_finding_closure',
    'validate_audit_finding_closure',
    'reject_audit_finding_closure',
    'reopen_audit_finding_with_reason',
    'escalate_audit_finding',
    'mark_repeat_audit_finding',
    'link_audit_finding_to_risk',
    'link_audit_finding_to_compliance',
    'generate_audit_closure_pack_index'
  ) then
    raise exception 'PATCH24_AUDIT_UNSUPPORTED_ACTION';
  end if;

  if v_finding_id is null then
    raise exception 'PATCH24_AUDIT_FINDING_ID_REQUIRED';
  end if;

  select * into v_finding
  from public.audit_findings
  where id = v_finding_id
  for update;

  if not found then
    raise exception 'PATCH24_AUDIT_FINDING_NOT_FOUND';
  end if;

  if v_actor.organization_id is distinct from v_finding.organization_id then
    raise exception 'PATCH24_AUDIT_CROSS_ORGANIZATION_DENIED';
  end if;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role::text in ('super_admin','executive','governance_admin','division_head','department_manager','compliance_officer','auditor')
      and (ur.organization_id is null or ur.organization_id is not distinct from v_finding.organization_id)
  ) into v_can_manage;

  v_is_owner := p_actor_id in (
    v_finding.owner_id,
    v_finding.auditor_id,
    v_finding.finding_owner_id,
    v_finding.audit_manager_id,
    v_finding.responsible_owner_id,
    v_finding.corrective_action_owner_id,
    v_finding.executive_sponsor_id
  );

  if not (v_can_manage or v_is_owner) then
    raise exception 'PATCH24_AUDIT_NOT_AUTHORIZED';
  end if;

  v_old_status := v_finding.finding_status;

  if v_action = 'issue_audit_finding' then
    update public.audit_findings
    set
      status = 'open'::public.audit_finding_status,
      finding_status = 'management_response_required',
      workflow_stage = 'management_response',
      severity_level = coalesce(nullif(p_payload->>'severity_level', ''), severity_level, risk_level::text),
      management_response_required = coalesce((p_payload->>'management_response_required')::boolean, true),
      management_response_status = case when coalesce((p_payload->>'management_response_required')::boolean, true) then 'required' else 'waived' end,
      management_response_due_date = coalesce(nullif(p_payload->>'management_response_due_date', '')::date, management_response_due_date, current_date + 14),
      due_date = coalesce(nullif(p_payload->>'due_date', '')::date, due_date),
      original_due_date = coalesce(original_due_date, due_date, nullif(p_payload->>'due_date', '')::date),
      finding_owner_id = coalesce(nullif(p_payload->>'finding_owner_id', '')::uuid, finding_owner_id, owner_id),
      audit_manager_id = coalesce(nullif(p_payload->>'audit_manager_id', '')::uuid, audit_manager_id, auditor_id, p_actor_id),
      responsible_department_id = coalesce(nullif(p_payload->>'responsible_department_id', '')::uuid, responsible_department_id, department_id),
      responsible_owner_id = coalesce(nullif(p_payload->>'responsible_owner_id', '')::uuid, responsible_owner_id, owner_id, p_actor_id),
      escalation_required = escalation_required or (coalesce(nullif(p_payload->>'severity_level', ''), severity_level, risk_level::text) in ('high','critical') and coalesce(nullif(p_payload->>'due_date', '')::date, due_date, current_date + 30) < current_date),
      executive_visible = executive_visible or (coalesce(nullif(p_payload->>'severity_level', ''), severity_level, risk_level::text) in ('high','critical') and coalesce(nullif(p_payload->>'due_date', '')::date, due_date, current_date + 30) < current_date),
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'finding_issued', v_old_status, 'management_response_required', p_actor_id, coalesce(v_note, 'Finding issued.'), p_payload);
    v_result := jsonb_build_object('audit_finding_id', v_finding.id, 'finding_status', 'management_response_required');

  elsif v_action = 'submit_management_response' then
    if v_response is null then
      raise exception 'PATCH24_MANAGEMENT_RESPONSE_TEXT_REQUIRED';
    end if;

    update public.audit_findings
    set
      management_response = v_response,
      management_response_submitted_by = p_actor_id,
      management_response_submitted_at = now(),
      management_response_status = 'submitted',
      finding_status = 'management_response_submitted',
      workflow_stage = 'management_response_review',
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'management_response_submitted', v_old_status, 'management_response_submitted', p_actor_id, v_note, p_payload);

  elsif v_action in ('accept_management_response','reject_management_response') then
    if not v_can_manage then
      raise exception 'PATCH24_MANAGEMENT_RESPONSE_REVIEWER_REQUIRED';
    end if;
    if v_finding.management_response is null or trim(v_finding.management_response) = '' then
      raise exception 'PATCH24_MANAGEMENT_RESPONSE_TEXT_REQUIRED';
    end if;
    if v_action = 'reject_management_response' and v_reason is null then
      raise exception 'PATCH24_MANAGEMENT_RESPONSE_REJECTION_REASON_REQUIRED';
    end if;

    v_new_status := case when v_action = 'accept_management_response' then 'action_plan_required' else 'management_response_required' end;
    update public.audit_findings
    set
      management_response_status = case when v_action = 'accept_management_response' then 'accepted' else 'rejected' end,
      management_response_rejection_reason = case when v_action = 'reject_management_response' then v_reason else null end,
      finding_status = v_new_status,
      workflow_stage = case when v_action = 'accept_management_response' then 'action_plan' else 'management_response' end,
      corrective_action_status = case when v_action = 'accept_management_response' and corrective_action_required then 'required' else corrective_action_status end,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(
      v_finding.organization_id,
      v_finding.id,
      case when v_action = 'accept_management_response' then 'management_response_accepted' else 'management_response_rejected' end,
      v_old_status,
      v_new_status,
      p_actor_id,
      v_reason,
      p_payload
    );

  elsif v_action = 'submit_corrective_action_plan' then
    if v_action_plan is null then
      raise exception 'PATCH24_CORRECTIVE_ACTION_PLAN_REQUIRED';
    end if;
    if coalesce(nullif(p_payload->>'corrective_action_owner_id', '')::uuid, v_finding.corrective_action_owner_id, v_finding.responsible_owner_id) is null then
      raise exception 'PATCH24_CORRECTIVE_ACTION_OWNER_REQUIRED';
    end if;
    if coalesce(nullif(p_payload->>'corrective_action_due_date', '')::date, v_finding.corrective_action_due_date) is null then
      raise exception 'PATCH24_CORRECTIVE_ACTION_DUE_DATE_REQUIRED';
    end if;

    update public.audit_findings
    set
      corrective_action_required = true,
      corrective_action_plan = v_action_plan,
      corrective_action_owner_id = coalesce(nullif(p_payload->>'corrective_action_owner_id', '')::uuid, corrective_action_owner_id, responsible_owner_id),
      corrective_action_due_date = coalesce(nullif(p_payload->>'corrective_action_due_date', '')::date, corrective_action_due_date),
      corrective_action_status = 'submitted',
      finding_status = 'action_plan_in_progress',
      workflow_stage = 'action_plan_review',
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'action_plan_submitted', v_old_status, 'action_plan_in_progress', p_actor_id, v_note, p_payload);

  elsif v_action in ('accept_corrective_action_plan','reject_corrective_action_plan') then
    if not v_can_manage then
      raise exception 'PATCH24_ACTION_PLAN_REVIEWER_REQUIRED';
    end if;
    if v_action = 'accept_corrective_action_plan' and (v_finding.corrective_action_owner_id is null or v_finding.corrective_action_due_date is null) then
      raise exception 'PATCH24_CORRECTIVE_ACTION_OWNER_AND_DUE_DATE_REQUIRED';
    end if;
    if v_action = 'reject_corrective_action_plan' and v_reason is null then
      raise exception 'PATCH24_ACTION_PLAN_REJECTION_REASON_REQUIRED';
    end if;

    v_new_status := case when v_action = 'accept_corrective_action_plan' then 'evidence_required' else 'action_plan_required' end;
    update public.audit_findings
    set
      corrective_action_status = case when v_action = 'accept_corrective_action_plan' then 'accepted' else 'rejected' end,
      corrective_action_rejection_reason = case when v_action = 'reject_corrective_action_plan' then v_reason else null end,
      finding_status = v_new_status,
      workflow_stage = case when v_action = 'accept_corrective_action_plan' then 'evidence' else 'action_plan' end,
      evidence_gate_status = case when v_action = 'accept_corrective_action_plan' and evidence_required then 'pending' else evidence_gate_status end,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(
      v_finding.organization_id,
      v_finding.id,
      case when v_action = 'accept_corrective_action_plan' then 'action_plan_accepted' else 'action_plan_rejected' end,
      v_old_status,
      v_new_status,
      p_actor_id,
      v_reason,
      p_payload
    );

  elsif v_action = 'request_audit_finding_extension' then
    v_due_date := nullif(p_payload->>'requested_due_date', '')::date;
    if v_due_date is null then
      raise exception 'PATCH24_EXTENSION_REQUESTED_DUE_DATE_REQUIRED';
    end if;
    if v_reason is null then
      raise exception 'PATCH24_EXTENSION_REASON_REQUIRED';
    end if;

    insert into public.audit_finding_due_date_extensions (
      organization_id,
      audit_finding_id,
      previous_due_date,
      requested_due_date,
      extension_reason,
      requested_by
    )
    values (
      v_finding.organization_id,
      v_finding.id,
      v_finding.due_date,
      v_due_date,
      v_reason,
      p_actor_id
    )
    returning id into v_extension_id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'due_date_extension_requested', v_old_status, v_old_status, p_actor_id, v_reason, p_payload || jsonb_build_object('extension_id', v_extension_id));
    v_result := jsonb_build_object('extension_id', v_extension_id);

  elsif v_action in ('approve_audit_finding_extension','reject_audit_finding_extension') then
    if not v_can_manage then
      raise exception 'PATCH24_EXTENSION_APPROVER_REQUIRED';
    end if;
    if v_extension_id is null then
      raise exception 'PATCH24_EXTENSION_ID_REQUIRED';
    end if;

    if v_action = 'approve_audit_finding_extension' then
      update public.audit_finding_due_date_extensions
      set status = 'approved', approved_by = p_actor_id, approved_at = now()
      where id = v_extension_id and audit_finding_id = v_finding.id and status = 'requested'
      returning requested_due_date into v_due_date;

      if v_due_date is null then
        raise exception 'PATCH24_EXTENSION_NOT_FOUND_OR_ALREADY_DECIDED';
      end if;

      update public.audit_findings
      set revised_due_date = v_due_date, due_date = v_due_date, updated_by = p_actor_id
      where id = v_finding.id;

      perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'due_date_extension_approved', v_old_status, v_old_status, p_actor_id, v_note, p_payload);
    else
      if v_reason is null then
        raise exception 'PATCH24_EXTENSION_REJECTION_REASON_REQUIRED';
      end if;
      update public.audit_finding_due_date_extensions
      set status = 'rejected', approved_by = p_actor_id, approved_at = now(), rejection_reason = v_reason
      where id = v_extension_id and audit_finding_id = v_finding.id and status = 'requested';

      perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'due_date_extension_rejected', v_old_status, v_old_status, p_actor_id, v_reason, p_payload);
    end if;

  elsif v_action = 'request_audit_finding_closure' then
    update public.audit_findings
    set
      closure_requested_at = now(),
      closure_requested_by = p_actor_id,
      closure_validation_status = 'requested',
      finding_status = 'closure_requested',
      workflow_stage = 'auditor_validation',
      status = 'under_audit_review'::public.audit_finding_status,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'closure_requested', v_old_status, 'closure_requested', p_actor_id, coalesce(v_note, 'Closure requested.'), p_payload);

  elsif v_action = 'validate_audit_finding_closure' then
    if not v_can_manage then
      raise exception 'PATCH24_CLOSURE_VALIDATOR_REQUIRED';
    end if;

    select closure_blocker into v_blocker
    from public.v_patch24_audit_closure_gate_status
    where audit_finding_id = v_finding.id
      and (can_close = false or closure_blocker is not null)
    limit 1;

    if v_blocker is not null then
      update public.audit_findings
      set closure_validation_status = 'blocked', closure_blocker = v_blocker, evidence_gate_status = 'blocked'
      where id = v_finding.id;
      raise exception 'PATCH24_AUDIT_CLOSURE_BLOCKED: %', v_blocker;
    end if;

    update public.audit_findings
    set
      status = 'closed'::public.audit_finding_status,
      finding_status = 'closed',
      workflow_stage = 'closed',
      closure_validation_status = 'accepted',
      closure_validation_note = coalesce(v_note, closure_validation_note),
      closure_validated_by = p_actor_id,
      closure_validated_at = now(),
      reviewed_by = p_actor_id,
      reviewed_at = now(),
      closed_by = p_actor_id,
      closed_at = now(),
      closure_blocker = null,
      evidence_gate_status = 'satisfied',
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'closure_accepted', v_old_status, 'closed', p_actor_id, v_note, p_payload);

  elsif v_action = 'reject_audit_finding_closure' then
    if not v_can_manage then
      raise exception 'PATCH24_CLOSURE_VALIDATOR_REQUIRED';
    end if;
    if v_reason is null then
      raise exception 'PATCH24_CLOSURE_REJECTION_REASON_REQUIRED';
    end if;

    update public.audit_findings
    set
      status = 'rejected'::public.audit_finding_status,
      finding_status = 'returned_for_correction',
      workflow_stage = 'correction',
      closure_validation_status = 'rejected',
      closure_validation_note = v_reason,
      closure_blocker = v_reason,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'closure_rejected', v_old_status, 'returned_for_correction', p_actor_id, v_reason, p_payload);

  elsif v_action = 'reopen_audit_finding_with_reason' then
    if v_reason is null then
      raise exception 'PATCH24_REOPEN_REASON_REQUIRED';
    end if;

    update public.audit_findings
    set
      status = 'open'::public.audit_finding_status,
      finding_status = 'reopened',
      workflow_stage = 'reopened',
      reopened_at = now(),
      reopened_by = p_actor_id,
      reopen_reason = v_reason,
      closed_by = null,
      closed_at = null,
      closure_validated_by = null,
      closure_validated_at = null,
      closure_validation_status = 'not_requested',
      closure_requested_at = null,
      closure_requested_by = null,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'reopened', v_old_status, 'reopened', p_actor_id, v_reason, p_payload);

  elsif v_action = 'escalate_audit_finding' then
    if v_reason is null then
      raise exception 'PATCH24_ESCALATION_REASON_REQUIRED';
    end if;

    update public.audit_findings
    set
      finding_status = 'escalated',
      workflow_stage = 'escalation',
      escalation_required = true,
      escalation_level = coalesce(nullif(p_payload->>'escalation_level', ''), case when severity_level = 'critical' then 'committee' else 'executive' end),
      escalated_at = now(),
      escalated_to = coalesce(nullif(p_payload->>'escalated_to', '')::uuid, executive_sponsor_id),
      escalation_reason = v_reason,
      executive_visible = true,
      committee_review_required = committee_review_required or severity_level = 'critical' or systemic_issue_flag,
      committee_review_status = case when committee_review_required or severity_level = 'critical' or systemic_issue_flag then 'required' else committee_review_status end,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'escalated', v_old_status, 'escalated', p_actor_id, v_reason, p_payload);

  elsif v_action = 'mark_repeat_audit_finding' then
    update public.audit_findings
    set
      repeat_finding_flag = coalesce((p_payload->>'repeat_finding_flag')::boolean, true),
      repeat_of_finding_id = coalesce(nullif(p_payload->>'repeat_of_finding_id', '')::uuid, repeat_of_finding_id),
      recurrence_count = greatest(coalesce(nullif(p_payload->>'recurrence_count', '')::integer, recurrence_count, 0), 1),
      recurrence_window_days = coalesce(nullif(p_payload->>'recurrence_window_days', '')::integer, recurrence_window_days, 365),
      systemic_issue_flag = coalesce((p_payload->>'systemic_issue_flag')::boolean, systemic_issue_flag),
      executive_visible = true,
      committee_review_required = true,
      committee_review_status = case when committee_review_status = 'not_required' then 'required' else committee_review_status end,
      updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'repeat_marked', v_old_status, v_old_status, p_actor_id, v_note, p_payload);

  elsif v_action = 'link_audit_finding_to_risk' then
    if nullif(p_payload->>'related_risk_id', '') is null then
      raise exception 'PATCH24_RELATED_RISK_ID_REQUIRED';
    end if;

    update public.audit_findings
    set related_risk_id = (p_payload->>'related_risk_id')::uuid, updated_by = p_actor_id
    where id = v_finding.id;

    update public.risks
    set next_review_date = least(coalesce(next_review_date, current_date + 90), current_date + 30),
        review_overdue = true,
        updated_by = p_actor_id
    where id = (p_payload->>'related_risk_id')::uuid
      and organization_id = v_finding.organization_id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'risk_linked', v_old_status, v_old_status, p_actor_id, v_note, p_payload);

  elsif v_action = 'link_audit_finding_to_compliance' then
    if nullif(p_payload->>'related_compliance_id', '') is null then
      raise exception 'PATCH24_RELATED_COMPLIANCE_ID_REQUIRED';
    end if;

    update public.audit_findings
    set related_compliance_id = (p_payload->>'related_compliance_id')::uuid, updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'compliance_linked', v_old_status, v_old_status, p_actor_id, v_note, p_payload);

  elsif v_action = 'generate_audit_closure_pack_index' then
    v_pack_reference := coalesce(nullif(p_payload->>'closure_pack_reference', ''), 'AUDIT-CLOSURE-' || upper(left(v_finding.id::text, 8)) || '-' || to_char(now(), 'YYYYMMDDHH24MISS'));

    update public.audit_findings
    set closure_pack_reference = v_pack_reference,
        closure_pack_generated_at = now(),
        updated_by = p_actor_id
    where id = v_finding.id;

    perform public.patch24_write_audit_event(v_finding.organization_id, v_finding.id, 'closure_pack_generated', v_old_status, v_old_status, p_actor_id, coalesce(v_note, 'Closure pack index generated.'), p_payload || jsonb_build_object('closure_pack_reference', v_pack_reference));
    v_result := jsonb_build_object('closure_pack_reference', v_pack_reference);
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'action', v_action,
    'audit_finding_id', v_finding.id,
    'result', v_result
  );
end;
$$;

COMMENT ON FUNCTION "public"."patch24_audit_finding_workflow_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb") IS 'Patch 24 service-role audit finding workflow bridge. Browser code must call through authenticated Edge privileged-action bridge.';

CREATE OR REPLACE FUNCTION "public"."patch24_write_audit_event"("p_organization_id" "uuid", "p_audit_finding_id" "uuid", "p_validation_type" "text", "p_from_status" "text", "p_to_status" "text", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH24_AUDIT_EVENT_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.audit_finding_validation_events (
    organization_id,
    audit_finding_id,
    validation_type,
    from_status,
    to_status,
    actor_id,
    note,
    metadata
  )
  values (
    p_organization_id,
    p_audit_finding_id,
    p_validation_type,
    p_from_status,
    p_to_status,
    p_actor_id,
    p_note,
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch25_compliance_accepted_evidence_count"("p_obligation_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_count integer := 0;
  v_row_count integer := 0;
begin
  if to_regclass('public.evidence_links') is not null then
    execute $q$
      select count(distinct ef.id)::integer
      from public.evidence_files ef
      left join public.evidence_links el on el.evidence_file_id = ef.id and el.is_active = true
      where (
          ef.compliance_item_id = $1
          or (el.linked_item_type in ('compliance','compliance_item','compliance_obligation') and el.linked_item_id = $1)
        )
        and coalesce(ef.review_status::text, ef.status::text) = 'accepted'
        and coalesce(ef.is_current_version, true) = true
        and (ef.expiry_date is null or ef.expiry_date >= current_date)
    $q$ into v_count using p_obligation_id;
  else
    select count(*)::integer into v_count
    from public.evidence_files ef
    where ef.compliance_item_id = p_obligation_id
      and ef.status::text = 'accepted';
  end if;
  return coalesce(v_count, 0);
end;
$_$;

CREATE OR REPLACE FUNCTION "public"."patch25_compliance_active_waiver_count"("p_obligation_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_count integer := 0;
  v_row_count integer := 0;
begin
  if to_regclass('public.evidence_requirements') is not null and to_regclass('public.evidence_gate_waivers') is not null then
    execute $q$
      select count(distinct egw.id)::integer
      from public.evidence_requirements er
      join public.evidence_gate_waivers egw on egw.requirement_id = er.id
      where er.linked_item_type in ('compliance','compliance_item','compliance_obligation')
        and er.linked_item_id = $1
        and er.is_active = true
        and egw.status = 'approved'
        and (egw.expiry_date is null or egw.expiry_date >= current_date)
    $q$ into v_count using p_obligation_id;
  end if;
  return coalesce(v_count, 0);
end;
$_$;

CREATE OR REPLACE FUNCTION "public"."patch25_compliance_closure_satisfied"("p_obligation_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select coalesce((
    select
      case
        when coalesce(c.evidence_required, false) = false then true
        when public.patch25_compliance_accepted_evidence_count(c.id) >= coalesce(c.minimum_accepted_evidence_count, 1) then true
        when public.patch25_compliance_active_waiver_count(c.id) > 0 then true
        else false
      end
    from public.compliance_items c
    where c.id = p_obligation_id
    limit 1
  ), false);
$$;

CREATE OR REPLACE FUNCTION "public"."patch25_compliance_obligation_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_jwt_role text := coalesce(current_setting('request.jwt.claim.role', true), current_user);
  v_actor public.profiles%rowtype;
  v_obligation public.compliance_items%rowtype;
  v_action text := lower(coalesce(p_action, ''));
  v_obligation_id uuid := coalesce(nullif(p_payload->>'obligation_id', '')::uuid, nullif(p_payload->>'compliance_item_id', '')::uuid);
  v_calendar_event_id uuid := nullif(p_payload->>'calendar_event_id', '')::uuid;
  v_can_manage boolean := false;
  v_is_owner boolean := false;
  v_old_status text;
  v_new_status text;
  v_note text := nullif(trim(coalesce(p_payload->>'note', p_payload->>'reason', '')), '');
  v_reason text := nullif(trim(coalesce(p_payload->>'reason', p_payload->>'rejection_reason', p_payload->>'escalation_reason', p_payload->>'reopen_reason', p_payload->>'note', '')), '');
  v_blocker text;
  v_generated_count integer := 0;
begin
  if v_jwt_role <> 'service_role' and current_user <> 'service_role' then
    raise exception 'PATCH25_COMPLIANCE_SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_actor
  from public.profiles
  where id = p_actor_id and is_active = true;

  if not found or v_actor.organization_id is null then
    raise exception 'PATCH25_COMPLIANCE_ACTIVE_ACTOR_REQUIRED';
  end if;

  if v_action = 'complete_regulatory_calendar_event' and v_obligation_id is null and v_calendar_event_id is not null then
    select obligation_id into v_obligation_id
    from public.compliance_regulatory_calendar
    where id = v_calendar_event_id;
  end if;

  if v_obligation_id is null then
    raise exception 'PATCH25_COMPLIANCE_OBLIGATION_ID_REQUIRED';
  end if;

  select * into v_obligation
  from public.compliance_items
  where id = v_obligation_id
  for update;

  if not found then
    raise exception 'PATCH25_COMPLIANCE_OBLIGATION_NOT_FOUND';
  end if;

  if v_actor.organization_id is distinct from v_obligation.organization_id then
    raise exception 'PATCH25_COMPLIANCE_CROSS_ORGANIZATION_DENIED';
  end if;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role::text in ('super_admin','executive','governance_admin','division_head','department_manager','compliance_officer','auditor')
      and (ur.organization_id is null or ur.organization_id is not distinct from v_obligation.organization_id)
  ) into v_can_manage;

  v_is_owner := p_actor_id in (
    v_obligation.owner_id,
    v_obligation.obligation_owner_id,
    v_obligation.reviewer_id,
    v_obligation.executive_sponsor_id,
    v_obligation.escalation_owner_id,
    v_obligation.escalated_to
  );

  if not (v_can_manage or v_is_owner) then
    raise exception 'PATCH25_COMPLIANCE_NOT_AUTHORIZED';
  end if;

  if v_action not in (
    'activate_compliance_obligation',
    'start_compliance_renewal',
    'submit_compliance_for_review',
    'accept_compliance_obligation',
    'reject_compliance_obligation',
    'request_compliance_closure',
    'approve_compliance_closure',
    'reject_compliance_closure',
    'reopen_compliance_obligation_with_reason',
    'escalate_compliance_obligation',
    'complete_regulatory_calendar_event',
    'generate_compliance_calendar_events'
  ) then
    raise exception 'PATCH25_COMPLIANCE_UNSUPPORTED_ACTION';
  end if;

  v_old_status := v_obligation.obligation_status;

  if v_action = 'activate_compliance_obligation' then
    update public.compliance_items
    set
      status = 'in_progress'::public.compliance_status,
      obligation_status = 'active',
      workflow_stage = 'active',
      obligation_owner_id = coalesce(nullif(p_payload->>'obligation_owner_id', '')::uuid, obligation_owner_id, owner_id),
      reviewer_id = coalesce(nullif(p_payload->>'reviewer_id', '')::uuid, reviewer_id),
      executive_sponsor_id = coalesce(nullif(p_payload->>'executive_sponsor_id', '')::uuid, executive_sponsor_id),
      criticality_level = coalesce(nullif(p_payload->>'criticality_level', ''), criticality_level, risk_level::text),
      next_review_date = coalesce(nullif(p_payload->>'next_review_date', '')::date, next_review_date),
      last_reviewed_at = now(),
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'activated', v_old_status, 'active', p_actor_id, coalesce(v_note, 'Obligation activated.'), null, p_payload);

  elsif v_action = 'start_compliance_renewal' then
    update public.compliance_items
    set
      status = 'in_progress'::public.compliance_status,
      obligation_status = 'renewal_in_progress',
      workflow_stage = 'renewal',
      renewal_required = true,
      renewal_started_at = now(),
      renewal_due_date = coalesce(nullif(p_payload->>'renewal_due_date', '')::date, renewal_due_date, expiry_date),
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'renewal_started', v_old_status, 'renewal_in_progress', p_actor_id, v_note, null, p_payload);

  elsif v_action = 'submit_compliance_for_review' then
    update public.compliance_items
    set
      status = 'pending_approval'::public.compliance_status,
      obligation_status = 'submitted_for_review',
      workflow_stage = 'review',
      last_submitted_at = now(),
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'submitted_for_review', v_old_status, 'submitted_for_review', p_actor_id, coalesce(v_note, 'Submitted for compliance review.'), null, p_payload);

  elsif v_action = 'accept_compliance_obligation' then
    if not v_can_manage then
      raise exception 'PATCH25_COMPLIANCE_REVIEWER_REQUIRED';
    end if;

    update public.compliance_items
    set
      status = 'compliant'::public.compliance_status,
      obligation_status = 'accepted',
      workflow_stage = 'accepted',
      last_reviewed_at = now(),
      reviewer_id = coalesce(reviewer_id, p_actor_id),
      renewal_completed_at = case when obligation_status = 'renewal_in_progress' then now() else renewal_completed_at end,
      evidence_gate_status = case when public.patch25_compliance_closure_satisfied(id) then 'satisfied' else evidence_gate_status end,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'accepted', v_old_status, 'accepted', p_actor_id, v_note, null, p_payload);

  elsif v_action = 'reject_compliance_obligation' then
    if v_reason is null then
      raise exception 'PATCH25_COMPLIANCE_REJECTION_REASON_REQUIRED';
    end if;

    update public.compliance_items
    set
      status = 'non_compliant'::public.compliance_status,
      obligation_status = 'rejected',
      workflow_stage = 'rejected',
      closure_rejection_reason = v_reason,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'rejected', v_old_status, 'rejected', p_actor_id, v_note, v_reason, p_payload);

  elsif v_action = 'request_compliance_closure' then
    update public.compliance_items
    set
      status = 'pending_approval'::public.compliance_status,
      obligation_status = 'submitted_for_review',
      workflow_stage = 'closure_review',
      closure_requested_at = now(),
      closure_requested_by = p_actor_id,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'closure_requested', v_old_status, 'submitted_for_review', p_actor_id, coalesce(v_note, 'Closure requested.'), null, p_payload);

  elsif v_action = 'approve_compliance_closure' then
    if not v_can_manage then
      raise exception 'PATCH25_COMPLIANCE_CLOSURE_APPROVER_REQUIRED';
    end if;

    select blocker_reason into v_blocker
    from public.v_patch25_compliance_closure_blockers
    where obligation_id = v_obligation.id
      and blocker_reason is not null
    limit 1;

    if v_blocker is not null then
      update public.compliance_items
      set closure_blocker = v_blocker,
          evidence_gate_status = case when evidence_required then 'blocked' else evidence_gate_status end
      where id = v_obligation.id;
      raise exception 'PATCH25_COMPLIANCE_CLOSURE_BLOCKED: %', v_blocker;
    end if;

    update public.compliance_items
    set
      status = 'closed'::public.compliance_status,
      obligation_status = 'closed',
      workflow_stage = 'closed',
      closure_approved_at = now(),
      closure_approved_by = p_actor_id,
      closed_at = now(),
      closed_by = p_actor_id,
      closure_blocker = null,
      evidence_gate_status = case when evidence_required then 'satisfied' else 'not_required' end,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'closure_approved', v_old_status, 'closed', p_actor_id, v_note, null, p_payload);

  elsif v_action = 'reject_compliance_closure' then
    if v_reason is null then
      raise exception 'PATCH25_COMPLIANCE_CLOSURE_REJECTION_REASON_REQUIRED';
    end if;

    update public.compliance_items
    set
      status = 'non_compliant'::public.compliance_status,
      obligation_status = 'rejected',
      workflow_stage = 'rejected',
      closure_rejection_reason = v_reason,
      closure_blocker = v_reason,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'closure_rejected', v_old_status, 'rejected', p_actor_id, v_note, v_reason, p_payload);

  elsif v_action = 'reopen_compliance_obligation_with_reason' then
    if v_reason is null then
      raise exception 'PATCH25_COMPLIANCE_REOPEN_REASON_REQUIRED';
    end if;

    update public.compliance_items
    set
      status = 'in_progress'::public.compliance_status,
      obligation_status = 'reopened',
      workflow_stage = 'reopened',
      reopened_at = now(),
      reopened_by = p_actor_id,
      reopen_reason = v_reason,
      closed_at = null,
      closed_by = null,
      closure_approved_at = null,
      closure_approved_by = null,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'reopened', v_old_status, 'reopened', p_actor_id, v_note, v_reason, p_payload);

  elsif v_action = 'escalate_compliance_obligation' then
    if v_reason is null then
      raise exception 'PATCH25_COMPLIANCE_ESCALATION_REASON_REQUIRED';
    end if;

    update public.compliance_items
    set
      status = case when status::text = 'closed' then status else 'non_compliant'::public.compliance_status end,
      obligation_status = 'escalated',
      workflow_stage = 'escalation',
      escalation_required = true,
      escalation_level = coalesce(nullif(p_payload->>'escalation_level', ''), case when criticality_level = 'critical' or risk_level = 'critical' then 'executive' else 'management' end),
      escalated_at = now(),
      escalated_to = coalesce(nullif(p_payload->>'escalated_to', '')::uuid, executive_sponsor_id, escalation_owner_id),
      escalation_reason = v_reason,
      executive_visible = true,
      updated_by = p_actor_id
    where id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'escalated', v_old_status, 'escalated', p_actor_id, v_note, v_reason, p_payload);

  elsif v_action = 'complete_regulatory_calendar_event' then
    if v_calendar_event_id is null then
      raise exception 'PATCH25_CALENDAR_EVENT_ID_REQUIRED';
    end if;

    update public.compliance_regulatory_calendar
    set status = 'completed',
        completed_at = now(),
        completed_by = p_actor_id,
        notes = coalesce(nullif(p_payload->>'notes', ''), notes),
        updated_at = now()
    where id = v_calendar_event_id
      and obligation_id = v_obligation.id;

    perform public.patch25_write_compliance_event(v_obligation.organization_id, v_obligation.id, 'calendar_event_completed', v_old_status, v_old_status, p_actor_id, coalesce(v_note, 'Calendar event completed.'), null, p_payload);

  elsif v_action = 'generate_compliance_calendar_events' then
    v_generated_count := public.patch25_generate_calendar_events(v_obligation.id, p_actor_id, v_note);
  end if;

  return jsonb_build_object(
    'status', 'ok',
    'action', v_action,
    'obligation_id', v_obligation.id,
    'generated_calendar_event_count', v_generated_count
  );
end;
$$;

COMMENT ON FUNCTION "public"."patch25_compliance_obligation_bridge"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb") IS 'Patch 25 service-role compliance obligation workflow bridge. Browser code must call through authenticated Edge privileged-action bridge.';

CREATE OR REPLACE FUNCTION "public"."patch25_generate_calendar_events"("p_obligation_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_obligation public.compliance_items%rowtype;
  v_count integer := 0;
  v_row_count integer := 0;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH25_CALENDAR_SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_obligation
  from public.compliance_items
  where id = p_obligation_id;

  if not found then
    raise exception 'PATCH25_OBLIGATION_NOT_FOUND';
  end if;

  if v_obligation.expiry_date is not null then
    insert into public.compliance_regulatory_calendar (
      organization_id, obligation_id, event_type, event_title, event_description, due_date,
      reminder_start_date, reminder_frequency, owner_id, reviewer_id, status, evidence_required
    )
    values (
      v_obligation.organization_id,
      v_obligation.id,
      case when coalesce(v_obligation.obligation_type, '') ilike '%certificate%' then 'certificate_expiry' else 'license_expiry' end,
      coalesce(v_obligation.obligation_title, v_obligation.title) || ' expiry',
      'Auto-generated Patch 25 expiry calendar event.',
      v_obligation.expiry_date,
      v_obligation.expiry_date - coalesce(v_obligation.reminder_days_before, 30),
      coalesce(v_obligation.review_frequency, 'monthly'),
      coalesce(v_obligation.obligation_owner_id, v_obligation.owner_id),
      v_obligation.reviewer_id,
      case when v_obligation.expiry_date < current_date then 'overdue' else 'scheduled' end,
      coalesce(v_obligation.evidence_required, false)
    )
    on conflict do nothing;
    get diagnostics v_count = row_count;
  end if;

  if v_obligation.renewal_required and v_obligation.renewal_due_date is not null then
    insert into public.compliance_regulatory_calendar (
      organization_id, obligation_id, event_type, event_title, event_description, due_date,
      reminder_start_date, reminder_frequency, owner_id, reviewer_id, status, evidence_required
    )
    values (
      v_obligation.organization_id,
      v_obligation.id,
      'renewal_due',
      coalesce(v_obligation.obligation_title, v_obligation.title) || ' renewal',
      'Auto-generated Patch 25 renewal calendar event.',
      v_obligation.renewal_due_date,
      v_obligation.renewal_due_date - coalesce(v_obligation.reminder_days_before, 30),
      coalesce(v_obligation.renewal_frequency, 'annual'),
      coalesce(v_obligation.obligation_owner_id, v_obligation.owner_id),
      v_obligation.reviewer_id,
      case when v_obligation.renewal_due_date < current_date then 'overdue' else 'scheduled' end,
      coalesce(v_obligation.evidence_required, false)
    )
    on conflict do nothing;
    get diagnostics v_row_count = row_count;
    v_count := v_count + v_row_count;
  end if;

  if v_obligation.next_review_date is not null then
    insert into public.compliance_regulatory_calendar (
      organization_id, obligation_id, event_type, event_title, event_description, due_date,
      reminder_start_date, reminder_frequency, owner_id, reviewer_id, status, evidence_required
    )
    values (
      v_obligation.organization_id,
      v_obligation.id,
      'policy_review',
      coalesce(v_obligation.obligation_title, v_obligation.title) || ' review',
      'Auto-generated Patch 25 review calendar event.',
      v_obligation.next_review_date,
      v_obligation.next_review_date - 14,
      coalesce(v_obligation.review_frequency, 'annual'),
      coalesce(v_obligation.obligation_owner_id, v_obligation.owner_id),
      v_obligation.reviewer_id,
      case when v_obligation.next_review_date < current_date then 'overdue' else 'scheduled' end,
      false
    )
    on conflict do nothing;
    get diagnostics v_row_count = row_count;
    v_count := v_count + v_row_count;
  end if;

  perform public.patch25_write_compliance_event(
    v_obligation.organization_id,
    v_obligation.id,
    'calendar_events_generated',
    v_obligation.obligation_status,
    v_obligation.obligation_status,
    p_actor_id,
    coalesce(p_note, 'Calendar events generated.'),
    null,
    jsonb_build_object('generated_count', v_count)
  );

  return v_count;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch25_write_compliance_event"("p_organization_id" "uuid", "p_obligation_id" "uuid", "p_event_type" "text", "p_from_status" "text", "p_to_status" "text", "p_actor_id" "uuid", "p_event_note" "text" DEFAULT NULL::"text", "p_rejection_reason" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH25_COMPLIANCE_EVENT_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.compliance_obligation_events (
    organization_id,
    obligation_id,
    event_type,
    from_status,
    to_status,
    actor_id,
    event_note,
    rejection_reason,
    metadata
  )
  values (
    p_organization_id,
    p_obligation_id,
    p_event_type,
    p_from_status,
    p_to_status,
    p_actor_id,
    p_event_note,
    p_rejection_reason,
    coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;

