CREATE OR REPLACE FUNCTION "public"."patch28_write_capa_event"("p_capa_id" "uuid", "p_action_item_id" "uuid", "p_event_type" "text", "p_from_status" "text", "p_to_status" "text", "p_actor_id" "uuid", "p_event_note" "text" DEFAULT NULL::"text", "p_rejection_reason" "text" DEFAULT NULL::"text") RETURNS "void"
