  end if;

  insert into public.capa_events (capa_id, action_item_id, event_type, from_status, to_status, actor_id, event_note, rejection_reason)
  values (p_capa_id, p_action_item_id, p_event_type, p_from_status, p_to_status, p_actor_id, p_event_note, p_rejection_reason);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."patch31_actor_has_security_authority"("p_actor_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_user_id
      and ur.is_active = true
      and ur.role in ('super_admin','governance_admin','auditor')
  );
$$;

CREATE OR REPLACE FUNCTION "public"."patch32_actor_has_accreditation_authority"("p_actor_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_user_id
      and ur.is_active = true
      and ur.role in ('super_admin','governance_admin','compliance_officer','auditor')
  );
