CREATE OR REPLACE FUNCTION "public"."patch4_compute_event_hash"("p_previous_hash" "text", "p_event_payload" "jsonb", "p_created_at" timestamp with time zone, "p_actor_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
  select encode(
    extensions.digest(
      coalesce(p_previous_hash, '') || '|' ||
      coalesce(p_event_payload::text, '{}') || '|' ||
      coalesce(p_created_at at time zone 'UTC', timestamp 'epoch')::text || '|' ||
      coalesce(p_actor_id::text, ''),
      'sha256'
    ),
    'hex'
  );
$$;

COMMENT ON FUNCTION "public"."patch4_compute_event_hash"("p_previous_hash" "text", "p_event_payload" "jsonb", "p_created_at" timestamp with time zone, "p_actor_id" "uuid") IS 'Gate 9R category B: SECURITY INVOKER authenticated read/helper surface; fixed search_path; anon/PUBLIC denied.';

CREATE OR REPLACE FUNCTION "public"."patch4_set_immutable_event_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.created_at is null then
    new.created_at := now();
  end if;

  new.event_hash := public.patch4_compute_event_hash(
    new.previous_event_hash,
    new.event_payload,
    new.created_at,
    new.actor_id
  );

  return new;
end;
$$;

COMMENT ON FUNCTION "public"."patch4_set_immutable_event_hash"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

