CREATE OR REPLACE FUNCTION "public"."record_controlled_production_cutover_decision_event"("p_actor_id" "uuid", "p_decision_id" "uuid", "p_event_type" "text", "p_event_summary" "text", "p_event_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_decision_org_id uuid;
  v_event_id uuid;
begin
  perform public.patch76_service_role_required();
  v_org_id := public.patch76_actor_authorized(p_actor_id);

  select organization_id
    into v_decision_org_id
  from public.controlled_production_cutover_decisions
  where id = p_decision_id;

  if v_decision_org_id is null or v_decision_org_id <> v_org_id then
    raise exception 'Controlled cutover decision is not available for this organization.';
  end if;

  if nullif(btrim(coalesce(p_event_type, '')), '') is null then
    raise exception 'Event type is required.';
  end if;

  if nullif(btrim(coalesce(p_event_summary, '')), '') is null then
    raise exception 'Event summary is required.';
  end if;

  insert into public.controlled_production_cutover_decision_events (
    decision_id,
    organization_id,
    event_type,
    event_summary,
    event_payload,
    actor_id
  ) values (
    p_decision_id,
    v_org_id,
    btrim(p_event_type),
    btrim(p_event_summary),
    coalesce(p_event_payload, '{}'::jsonb),
    p_actor_id
  )
  returning id into v_event_id;

  return jsonb_build_object('id', v_event_id, 'message', 'Controlled cutover decision event recorded.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."record_document_acknowledgment"("p_document_id" "uuid", "p_version_id" "uuid", "p_user_id" "uuid", "p_acknowledgment_method" "text" DEFAULT 'manual'::"text", "p_acknowledgment_note" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ack_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;

  insert into public.document_acknowledgments (
    document_id,
    version_id,
    user_id,
    acknowledgment_method,
    acknowledgment_note
  )
  values (
    p_document_id,
    p_version_id,
    p_user_id,
    coalesce(p_acknowledgment_method, 'manual'),
    p_acknowledgment_note
  )
  on conflict (document_id, version_id, user_id) do update
    set acknowledged_at = now(),
        acknowledgment_method = excluded.acknowledgment_method,
        acknowledgment_note = excluded.acknowledgment_note
  returning id into v_ack_id;

  perform public.patch26_write_document_event(p_document_id, p_version_id, 'acknowledged', null, null, p_user_id, p_acknowledgment_note, null);
  return v_ack_id;
end;
$$;

