CREATE OR REPLACE FUNCTION "public"."record_identity_role_integrity_finding"("p_actor_id" "uuid", "p_review_id" "uuid", "p_finding_type" "text", "p_severity" "text", "p_entity_type" "text", "p_finding_title" "text", "p_finding_summary" "text" DEFAULT NULL::"text", "p_entity_id" "uuid" DEFAULT NULL::"uuid", "p_department_id" "uuid" DEFAULT NULL::"uuid", "p_owner_id" "uuid" DEFAULT NULL::"uuid", "p_due_date" "date" DEFAULT NULL::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_finding_id uuid;
begin
  perform public.patch78_service_role_required();
  v_org_id := public.patch78_actor_authorized(p_actor_id);

  if not exists (select 1 from public.identity_role_integrity_reviews where id = p_review_id and organization_id = v_org_id) then
    raise exception 'Access integrity review is not available for this organization.';
  end if;
  if p_finding_type not in ('duplicate_role', 'privileged_role_review', 'dormant_account', 'inactive_account', 'archived_user_access', 'missing_owner', 'missing_reviewer', 'department_accountability_gap', 'station_accountability_gap', 'sso_mfa_readiness_gap', 'access_export_required', 'data_integrity_gap') then
    raise exception 'Unsupported identity, role, or data finding type.';
  end if;
  if p_severity not in ('low', 'medium', 'high', 'critical') then
    raise exception 'Unsupported finding severity.';
  end if;
  if nullif(btrim(coalesce(p_finding_title, '')), '') is null then
    raise exception 'Finding title is required.';
  end if;

  insert into public.identity_role_integrity_findings (
    organization_id,
    review_id,
    finding_type,
    severity,
    entity_type,
    entity_id,
    department_id,
    finding_title,
    finding_summary,
    owner_id,
    due_date,
    created_by
  ) values (
    v_org_id,
    p_review_id,
    p_finding_type,
    p_severity,
    nullif(btrim(coalesce(p_entity_type, '')), ''),
    p_entity_id,
    p_department_id,
    btrim(p_finding_title),
    nullif(btrim(coalesce(p_finding_summary, '')), ''),
    p_owner_id,
    p_due_date,
    p_actor_id
  ) returning id into v_finding_id;

  perform public.patch78_refresh_review_counts(p_review_id);

  return jsonb_build_object('id', v_finding_id, 'message', 'Identity, role, or data integrity finding recorded.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."record_live_pilot_department_acceptance"("p_actor_id" "uuid", "p_pilot_session_id" "uuid", "p_department_id" "uuid", "p_acceptance_status" "text", "p_acceptance_notes" "text" DEFAULT NULL::"text", "p_open_blockers_count" integer DEFAULT 0, "p_training_confirmed" boolean DEFAULT false, "p_issue_burndown_confirmed" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_session_org_id uuid;
  v_acceptance_id uuid;
begin
  perform public.patch77_service_role_required();
  v_org_id := public.patch77_actor_authorized(p_actor_id);

  select organization_id into v_session_org_id
  from public.live_pilot_sessions
  where id = p_pilot_session_id;

  if v_session_org_id is null or v_session_org_id <> v_org_id then
    raise exception 'Pilot session is not available for this organization.';
  end if;

  if p_acceptance_status not in ('pending', 'accepted', 'accepted_with_limitations', 'blocked', 'deferred') then
    raise exception 'Unsupported department pilot acceptance status.';
  end if;

  if p_acceptance_status = 'accepted' then
    if coalesce(p_open_blockers_count, 0) > 0 then
      raise exception 'Pilot blockers remain.';
    end if;
    if coalesce(p_training_confirmed, false) is not true or coalesce(p_issue_burndown_confirmed, false) is not true then
      raise exception 'Department pilot acceptance requires training and issue burn-down confirmation.';
    end if;
  end if;

  insert into public.live_pilot_department_acceptances (
    organization_id,
    pilot_session_id,
    department_id,
    acceptance_status,
    accepted_by,
    accepted_at,
    acceptance_notes,
    open_blockers_count,
    training_confirmed,
    issue_burndown_confirmed
  ) values (
    v_org_id,
    p_pilot_session_id,
    p_department_id,
    p_acceptance_status,
    case when p_acceptance_status in ('accepted', 'accepted_with_limitations') then p_actor_id else null end,
    case when p_acceptance_status in ('accepted', 'accepted_with_limitations') then now() else null end,
    nullif(btrim(coalesce(p_acceptance_notes, '')), ''),
    greatest(coalesce(p_open_blockers_count, 0), 0),
    coalesce(p_training_confirmed, false),
    coalesce(p_issue_burndown_confirmed, false)
  ) returning id into v_acceptance_id;

  return jsonb_build_object('id', v_acceptance_id, 'acceptance_status', p_acceptance_status, 'message', 'Department pilot acceptance recorded.');
end;
$$;

