CREATE OR REPLACE FUNCTION "public"."record_privileged_role_recertification"("p_actor_id" "uuid", "p_review_id" "uuid", "p_user_id" "uuid", "p_role_name" "text", "p_recertification_status" "text", "p_recertification_rationale" "text" DEFAULT NULL::"text", "p_department_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_recert_id uuid;
  v_rationale text;
begin
  perform public.patch78_service_role_required();
  v_org_id := public.patch78_actor_authorized(p_actor_id);

  if not exists (select 1 from public.identity_role_integrity_reviews where id = p_review_id and organization_id = v_org_id) then
    raise exception 'Access integrity review is not available for this organization.';
  end if;
  if nullif(btrim(coalesce(p_role_name, '')), '') is null then
    raise exception 'Privileged role name is required.';
  end if;
  if p_recertification_status not in ('pending', 'recertified', 'revocation_required', 'deferred', 'blocked') then
    raise exception 'Unsupported privileged role recertification status.';
  end if;

  v_rationale := nullif(btrim(coalesce(p_recertification_rationale, '')), '');
  if p_recertification_status = 'recertified' and v_rationale is null then
    raise exception 'Recertified privileged role requires rationale.';
  end if;

  insert into public.privileged_role_recertifications (
    organization_id,
    review_id,
    user_id,
    role_name,
    department_id,
    recertification_status,
    recertification_rationale,
    recertified_by,
    recertified_at,
    created_by
  ) values (
    v_org_id,
    p_review_id,
    p_user_id,
    btrim(p_role_name),
    p_department_id,
    p_recertification_status,
    v_rationale,
    case when p_recertification_status = 'recertified' then p_actor_id else null end,
    case when p_recertification_status = 'recertified' then now() else null end,
    p_actor_id
  ) returning id into v_recert_id;

  perform public.patch78_refresh_review_counts(p_review_id);

  return jsonb_build_object('id', v_recert_id, 'recertification_status', p_recertification_status, 'message', 'Privileged role recertification evidence recorded.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."record_production_evidence_closure_action"("p_actor_id" "uuid", "p_evidence_id" "text", "p_action_type" "text", "p_action_reason" "text" DEFAULT NULL::"text", "p_action_note" "text" DEFAULT NULL::"text", "p_previous_state" "text" DEFAULT NULL::"text", "p_has_blocker" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_action_id uuid;
  v_next_state text;
  v_reason text := nullif(btrim(coalesce(p_action_reason, '')), '');
  v_note text := nullif(btrim(coalesce(p_action_note, '')), '');
begin
  perform public.patch68_service_role_required();
  v_org_id := public.patch68_actor_authorized(p_actor_id);

  if nullif(btrim(coalesce(p_evidence_id, '')), '') is null then
    raise exception 'Evidence identifier is required.';
  end if;

  if p_action_type not in (
    'add_note',
    'ready_for_review',
    'request_more_evidence',
    'accept_with_limitation',
    'close_as_verified',
    'reopen_with_reason'
  ) then
    raise exception 'Unsupported controlled evidence action: %', p_action_type;
  end if;

  if p_action_type in ('request_more_evidence', 'accept_with_limitation', 'reopen_with_reason') and v_reason is null then
    raise exception 'Reason is required for this controlled evidence action.';
  end if;

  if p_action_type = 'close_as_verified' and coalesce(p_has_blocker, false) then
    raise exception 'Evidence cannot be closed as verified while blockers remain.';
  end if;

  v_next_state := case p_action_type
    when 'add_note' then coalesce(nullif(p_previous_state, ''), 'open')
    when 'ready_for_review' then 'under_review'
    when 'request_more_evidence' then 'evidence_required'
    when 'accept_with_limitation' then 'accepted_with_limitation'
    when 'close_as_verified' then 'closed'
    when 'reopen_with_reason' then 'open'
    else 'open'
  end;

  insert into public.production_evidence_closure_actions (
    organization_id,
    evidence_id,
    action_type,
    action_reason,
    action_note,
    previous_state,
    next_state,
    actor_id,
    metadata
  ) values (
    v_org_id,
    btrim(p_evidence_id),
    p_action_type,
    v_reason,
    v_note,
    nullif(btrim(coalesce(p_previous_state, '')), ''),
    v_next_state,
    p_actor_id,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'evidence_level_closure_only', true,
        'does_not_approve_production_launch', true,
        'executive_review_required_for_limitations', p_action_type = 'accept_with_limitation'
      )
  )
  returning id into v_action_id;

  return jsonb_build_object(
    'id', v_action_id,
    'evidence_id', btrim(p_evidence_id),
    'action_type', p_action_type,
    'previous_state', p_previous_state,
    'next_state', v_next_state,
    'created_at', now(),
    'message', 'Controlled evidence action recorded.'
  );
end;
$$;

COMMENT ON FUNCTION "public"."record_production_evidence_closure_action"("p_actor_id" "uuid", "p_evidence_id" "text", "p_action_type" "text", "p_action_reason" "text", "p_action_note" "text", "p_previous_state" "text", "p_has_blocker" boolean, "p_metadata" "jsonb") IS 'Records a controlled evidence-level action through the authenticated privileged bridge without approving production launch.';

