CREATE OR REPLACE FUNCTION "public"."reject_document_version"("p_document_id" "uuid", "p_version_id" "uuid", "p_actor_id" "uuid", "p_rejection_reason" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_rejection_reason, '')), '') is null then
    raise exception 'PATCH26_REJECTION_REASON_REQUIRED';
  end if;

  select document_status into v_old_status
  from public.controlled_documents
  where id = p_document_id
  for update;

  if not found then
    raise exception 'PATCH26_DOCUMENT_NOT_FOUND';
  end if;

  update public.controlled_documents
  set document_status = 'rejected',
      workflow_stage = 'rejected',
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_document_id;

  perform public.patch26_write_document_event(p_document_id, p_version_id, 'rejected', v_old_status, 'rejected', p_actor_id, p_note, p_rejection_reason);
  return jsonb_build_object('status', 'ok', 'document_id', p_document_id, 'document_status', 'rejected');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reject_evidence_bridge_submission"("p_bridge_link_id" "uuid", "p_collection_request_id" "uuid", "p_evidence_id" "uuid", "p_actor_user_id" "uuid", "p_rejection_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_review_id uuid;
begin
  if nullif(trim(coalesce(p_rejection_reason,'')), '') is null then raise exception 'PATCH33_REJECTION_REASON_REQUIRED'; end if;
  v_review_id := public.review_evidence_bridge_submission(p_bridge_link_id, p_collection_request_id, p_evidence_id, 'rejected', p_actor_user_id, p_rejection_reason);
  update public.evidence_bridge_links set evidence_status = 'rejected', updated_by = p_actor_user_id, updated_at = now() where id = p_bridge_link_id;
  update public.evidence_collection_requests set status = 'rejected' where id = p_collection_request_id;
  perform public.record_evidence_bridge_event('evidence_bridge_review', v_review_id, 'submission_rejected', p_rejection_reason, p_actor_user_id);
  return v_review_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reject_evidence_gate_waiver"("p_waiver_id" "uuid", "p_actor_user_id" "uuid", "p_rejection_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_entity_type text;
  v_entity_id uuid;
begin
  perform public.patch43_service_role_required();
  if not public.patch43_actor_has_authority(p_actor_user_id) then
    raise exception 'Actor is not authorized to reject evidence gate waivers';
  end if;

  update public.evidence_gate_waivers
  set waiver_status = 'rejected',
      status = 'rejected',
      rejected_by = p_actor_user_id,
      rejected_at = now(),
      rejection_reason = p_rejection_reason,
      audit_note = coalesce(audit_note, p_rejection_reason)
  where id = p_waiver_id
  returning coalesce(entity_type, linked_item_type), coalesce(entity_id, linked_item_id)
  into v_entity_type, v_entity_id;

  insert into public.survey_readiness_events(entity_type, entity_id, event_type, event_summary, event_payload, actor_user_id)
  values (v_entity_type, v_entity_id, 'waiver_rejected', p_rejection_reason, jsonb_build_object('waiver_id', p_waiver_id), p_actor_user_id);

  return p_waiver_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reject_runtime_rpc_for_production"("p_rpc_name" "text", "p_actor_user_id" "uuid", "p_rejection_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH31_SERVICE_ROLE_REQUIRED';
  end if;
  if not public.patch31_actor_has_security_authority(p_actor_user_id) then
    raise exception 'PATCH31_SECURITY_AUTHORITY_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_rejection_reason, '')), '') is null then
    raise exception 'PATCH31_REJECTION_REASON_REQUIRED';
  end if;
  update public.runtime_rpc_classifications
  set signoff_status = 'rejected_for_production',
      allowed_frontend_use = false,
      reviewed_by = p_actor_user_id,
      reviewed_at = now(),
      signoff_notes = p_rejection_reason,
      bridge_validation_status = 'rejected',
      production_exception_reason = p_rejection_reason,
      updated_at = now()
  where rpc_name = p_rpc_name;
  if not found then raise exception 'PATCH31_RPC_CLASSIFICATION_NOT_FOUND'; end if;
  perform public.record_runtime_rpc_signoff_event(p_rpc_name, 'rejected', 'Runtime RPC rejected for production.', p_actor_user_id);
  return jsonb_build_object('status','ok','rpc_name',p_rpc_name,'signoff_status','rejected_for_production');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reopen_accreditation_clause_assessment"("p_clause_id" "uuid", "p_actor_user_id" "uuid", "p_reopen_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_assessment_id uuid;
begin
  if nullif(trim(coalesce(p_reopen_reason,'')), '') is null then raise exception 'PATCH32_REOPEN_REASON_REQUIRED'; end if;
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  insert into public.accreditation_clause_assessments (clause_id, assessment_status, readiness_score, evidence_status, assessment_notes, assessed_by)
  values (p_clause_id, 'pending_owner_review', null, 'under_review', p_reopen_reason, p_actor_user_id)
  returning id into v_assessment_id;
  perform public.record_accreditation_traceability_event(p_clause_id, 'accreditation_clause_assessment', v_assessment_id, 'assessment_reopened', p_reopen_reason, p_actor_user_id);
  return v_assessment_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reopen_accreditation_clause_task"("p_task_id" "uuid", "p_actor_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_clause_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then raise exception 'PATCH35_REOPEN_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'PATCH35_REOPEN_REASON_REQUIRED'; end if;
  select clause_id into v_clause_id from public.accreditation_clause_review_tasks where id = p_task_id;
  update public.accreditation_clause_review_tasks set status = 'reopened', outcome_notes = p_reason where id = p_task_id;
  perform public.record_accreditation_workflow_event('review_task', p_task_id, v_clause_id, 'task_reopened', p_reason, p_actor_user_id);
  return jsonb_build_object('status','reopened','task_id',p_task_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reopen_audit_execution_engagement"("p_engagement_id" "uuid", "p_actor_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(p_reason), '') is null then raise exception 'PATCH37_REOPEN_REASON_REQUIRED'; end if;
  update public.audit_execution_engagements set status = 'active', closed_at = null where id = p_engagement_id;
  perform public.record_clinical_governance_event('audit_engagement', p_engagement_id, 'audit_engagement_reopened', p_reason, p_actor_user_id);
  return jsonb_build_object('status','active','engagement_id',p_engagement_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."reopen_capa_with_reason"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_reopen_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  if nullif(trim(coalesce(p_reopen_reason,'')), '') is null then raise exception 'PATCH28_REOPEN_REASON_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'reopened', workflow_stage = 'reopened', reopened_at = now(), reopened_by = p_actor_id, reopen_reason = p_reopen_reason, closure_approved_at = null, closure_approved_by = null, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'reopened', v_old, 'reopened', p_actor_id, p_reopen_reason, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."reopen_evidence_collection_request"("p_collection_request_id" "uuid", "p_actor_user_id" "uuid", "p_reopen_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_bridge_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_has_evidence_bridge_authority(p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_BRIDGE_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(coalesce(p_reopen_reason,'')), '') is null then raise exception 'PATCH33_REOPEN_REASON_REQUIRED'; end if;
  update public.evidence_collection_requests set status = 'open', completed_at = null where id = p_collection_request_id returning bridge_link_id into v_bridge_id;
  if not found then raise exception 'PATCH33_COLLECTION_REQUEST_NOT_FOUND'; end if;
  if v_bridge_id is not null then update public.evidence_bridge_links set evidence_status = 'pending_collection', updated_by = p_actor_user_id, updated_at = now() where id = v_bridge_id; end if;
  perform public.record_evidence_bridge_event('evidence_collection_request', p_collection_request_id, 'collection_request_reopened', p_reopen_reason, p_actor_user_id);
  return jsonb_build_object('status','ok','collection_request_id',p_collection_request_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."reopen_training_assignment_with_reason"("p_assignment_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.training_assignments
  set status = 'assigned', completed_at = null, completion_evidence_id = null
  where id = p_assignment_id;

  if not found then
    raise exception 'PATCH29_ASSIGNMENT_NOT_REOPENABLE';
  end if;

  perform public.log_training_event(
    'training_assignments', p_assignment_id, 'reopened',
    'Assignment reopened for retraining. Reason: ' || p_reason,
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."request_capa_closure"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'closure_requested', workflow_stage = 'closure', closure_requested_at = now(), closure_requested_by = p_actor_id, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'closure_requested', v_old, 'closure_requested', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."request_capa_due_date_extension"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_requested_due_date" "date", "p_extension_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_ext_id uuid; v_due date;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  if nullif(trim(coalesce(p_extension_reason,'')), '') is null then raise exception 'PATCH28_EXTENSION_REASON_REQUIRED'; end if;
  select due_date into v_due from public.capa_action_plans where id = p_capa_id;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  insert into public.capa_due_date_extensions (capa_id, requested_by, current_due_date, requested_due_date, extension_reason) values (p_capa_id, p_actor_id, v_due, p_requested_due_date, p_extension_reason) returning id into v_ext_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'extension_requested', null, 'pending', p_actor_id, p_extension_reason, null);
  return v_ext_id;
end $$;

CREATE OR REPLACE FUNCTION "public"."request_evidence_gate_waiver"("p_entity_type" "text", "p_entity_id" "uuid", "p_waiver_reason" "text", "p_actor_user_id" "uuid", "p_expires_on" "date" DEFAULT NULL::"date") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org uuid;
  v_requirement_id uuid;
  v_waiver_id uuid;
  v_linked_type text;
begin
  perform public.patch43_service_role_required();
  if not public.patch43_actor_has_authority(p_actor_user_id) then
    raise exception 'Actor is not authorized to request evidence gate waivers';
  end if;

  v_org := public.patch43_actor_organization(p_actor_user_id);
  if v_org is null then
    raise exception 'Actor profile is missing organization_id';
  end if;

  v_linked_type := case
    when p_entity_type in ('risk','ovr','audit_finding','compliance','project','milestone','task','approval','capa','control','policy','department')
      then p_entity_type
    else 'task'
  end;

  insert into public.evidence_requirements(
    organization_id, requirement_code, linked_item_type, linked_item_id,
    requirement_title, requirement_description, required_for_gate, owner_id, created_by
  )
  values (
    v_org, 'PATCH43-' || p_entity_type || '-' || p_entity_id::text,
    v_linked_type, p_entity_id,
    'Patch 43 evidence gate waiver requirement',
    'Compatibility requirement created to govern a Patch 43 evidence gate waiver.',
    'audit', p_actor_user_id, p_actor_user_id
  )
  on conflict (organization_id, requirement_code)
  do update set updated_at = now()
  returning id into v_requirement_id;

  insert into public.evidence_gate_waivers(
    organization_id, requirement_id, linked_item_type, linked_item_id, waiver_reason,
    requested_by, status, expiry_date, audit_note, entity_type, entity_id, waiver_status, expires_on
  )
  values (
    v_org, v_requirement_id, v_linked_type, p_entity_id, p_waiver_reason,
    p_actor_user_id, 'requested', p_expires_on, 'Patch 43 evidence gate waiver requested.',
    p_entity_type, p_entity_id, 'pending', p_expires_on
  )
  returning id into v_waiver_id;

  insert into public.survey_readiness_events(entity_type, entity_id, event_type, event_summary, event_payload, actor_user_id)
  values (p_entity_type, p_entity_id, 'waiver_requested', p_waiver_reason, jsonb_build_object('waiver_id', v_waiver_id), p_actor_user_id);

  return v_waiver_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."request_workflow_approval"("p_organization_id" "uuid", "p_workflow_type" "text", "p_linked_item_type" "text", "p_linked_item_id" "uuid", "p_action_type" "text", "p_requested_by" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule_id uuid;
  v_request_id uuid;
  v_required_count integer := 1;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;

  v_rule_id := public.resolve_approval_authority_rule(
    p_organization_id,
    p_workflow_type,
    p_action_type,
    p_linked_item_type,
    nullif(p_payload->>'department_id', '')::uuid,
    nullif(p_payload->>'role_name', ''),
    nullif(p_payload->>'amount', '')::numeric,
    nullif(p_payload->>'risk_level', ''),
    nullif(p_payload->>'severity_level', ''),
    nullif(p_payload->>'criticality_level', ''),
    nullif(p_payload->>'document_type', ''),
    nullif(p_payload->>'escalation_level', '')
  );

  select coalesce(required_approval_count, case when requires_dual_approval then 2 else 1 end)
  into v_required_count
  from public.approval_authority_rules
  where id = v_rule_id;

  insert into public.approval_requests (
    organization_id,
    request_code,
    workflow_type,
    linked_item_type,
    linked_item_id,
    action_type,
    department_id,
    requested_by,
    request_reason,
    required_approval_count,
    authority_rule_id,
    amount,
    risk_level,
    severity_level,
    criticality_level,
    document_type,
    escalation_level,
    due_date,
    escalation_required,
    escalation_level_current,
    escalated_to
  )
  values (
    p_organization_id,
    coalesce(nullif(p_payload->>'request_code', ''), 'APR-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))),
    p_workflow_type,
    p_linked_item_type,
    p_linked_item_id,
    p_action_type,
    nullif(p_payload->>'department_id', '')::uuid,
    p_requested_by,
    nullif(p_payload->>'request_reason', ''),
    coalesce(v_required_count, 1),
    v_rule_id,
    nullif(p_payload->>'amount', '')::numeric,
    nullif(p_payload->>'risk_level', ''),
    nullif(p_payload->>'severity_level', ''),
    nullif(p_payload->>'criticality_level', ''),
    nullif(p_payload->>'document_type', ''),
    nullif(p_payload->>'escalation_level', ''),
    nullif(p_payload->>'due_date', '')::date,
    coalesce((p_payload->>'escalation_required')::boolean, false),
    nullif(p_payload->>'escalation_level', ''),
    nullif(p_payload->>'escalated_to', '')::uuid
  )
  returning id into v_request_id;

  perform public.patch27_write_authority_event(v_request_id, v_rule_id, 'request_created', null, 'pending', p_requested_by, nullif(p_payload->>'request_reason', ''));
  if v_rule_id is not null then
    perform public.patch27_write_authority_event(v_request_id, v_rule_id, 'approver_matched', 'pending', 'pending', p_requested_by, 'Authority rule matched.');
  else
    perform public.patch27_write_authority_event(v_request_id, null, 'no_rule_matched', 'pending', 'pending', p_requested_by, 'No active authority rule matched this request.');
  end if;

  return v_request_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."require_accepted_evidence_before_grc_closure"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  item_type text;
begin
  item_type := case tg_table_name
    when 'compliance_items' then 'compliance_item'
    when 'audit_findings' then 'audit_finding'
    when 'committee_decisions' then 'committee_decision'
    else tg_table_name
  end;

  if coalesce((to_jsonb(new)->>'evidence_required')::boolean, false) = true
     and (to_jsonb(new)->>'status') in ('closed','compliant')
     and not public.has_accepted_evidence(item_type, new.id) then
    raise exception 'Accepted evidence is required before closing this controlled item';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."require_accepted_evidence_before_grc_closure"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."require_accepted_evidence_before_project_closure"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.evidence_required = true
     and new.status = 'closed'
     and not public.has_accepted_evidence('project', new.id) then
    raise exception 'Accepted evidence is required before closing this project';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."require_accepted_evidence_before_project_closure"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."require_accepted_evidence_before_work_closure"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  if new.evidence_required = true
     and new.status in ('approved','closed')
     and not public.has_accepted_evidence(
       case tg_table_name when 'milestones' then 'milestone' when 'tasks' then 'task' else tg_table_name end,
       new.id
     ) then
    raise exception 'Accepted evidence is required before approving or closing this work item';
  end if;
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."require_accepted_evidence_before_work_closure"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

