CREATE OR REPLACE FUNCTION "public"."set_kri_observation_breach_level"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
declare
  k key_risk_indicators%rowtype;
begin
  select * into k from key_risk_indicators where id = new.kri_id;
  new.organization_id := coalesce(new.organization_id, k.organization_id);
  new.breach_level := calculate_kri_breach_level(k.direction, new.value, k.watch_threshold, k.warning_threshold, k.critical_threshold, k.lower_threshold, k.upper_threshold);
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."set_kri_observation_breach_level"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

