end; $$;

CREATE OR REPLACE FUNCTION "public"."start_accreditation_review_cycle"("p_cycle_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_ACCREDITATION_WORKFLOW_AUTHORITY_REQUIRED';
  end if;
  update public.accreditation_review_cycles set status = 'active' where id = p_cycle_id;
  perform public.record_accreditation_workflow_event('review_cycle', p_cycle_id, null, 'review_cycle_started', 'Accreditation review cycle started.', p_actor_user_id);
  return jsonb_build_object('status','started','cycle_id',p_cycle_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."start_audit_execution_engagement"("p_engagement_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  perform public.patch37_service_role_required();
  if not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_AUTHORITY_REQUIRED'; end if;
  update public.audit_execution_engagements set status = 'active' where id = p_engagement_id and status in ('planned','active');
  perform public.record_clinical_governance_event('audit_engagement', p_engagement_id, 'audit_engagement_started', 'Audit execution engagement started.', p_actor_user_id);
  return jsonb_build_object('status','active','engagement_id',p_engagement_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."start_capa_effectiveness_review"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_review_due_date" "date", "p_review_method" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_review_id uuid; v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  insert into public.capa_effectiveness_reviews (capa_id, review_due_date, reviewer_id, review_method) values (p_capa_id, p_review_due_date, p_actor_id, p_review_method) returning id into v_review_id;
  update public.capa_action_plans set capa_status = 'effectiveness_review_pending', workflow_stage = 'effectiveness_review', effectiveness_review_required = true, effectiveness_review_due_date = p_review_due_date, effectiveness_review_status = 'pending', updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'effectiveness_review_started', v_old, 'effectiveness_review_pending', p_actor_id, p_review_method, null);
  return v_review_id;
end $$;

CREATE OR REPLACE FUNCTION "public"."start_document_revision"("p_document_id" "uuid", "p_actor_id" "uuid", "p_revision_reason" "text", "p_change_summary" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
  v_current_version_id uuid;
  v_new_version_id uuid;
  v_next_version integer;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;
  if nullif(trim(coalesce(p_revision_reason, '')), '') is null then
    raise exception 'PATCH26_REVISION_REASON_REQUIRED';
  end if;

  select document_status, current_version_id into v_old_status, v_current_version_id
  from public.controlled_documents
  where id = p_document_id
  for update;

  if not found then
    raise exception 'PATCH26_DOCUMENT_NOT_FOUND';
  end if;

  select coalesce(max(version_number), 0) + 1 into v_next_version
  from public.document_versions
  where document_id = p_document_id;

  insert into public.document_versions (
    document_id,
    version_number,
    version_label,
    revision_reason,
    change_summary,
    prepared_by,
    supersedes_version_id
  )
  values (
    p_document_id,
    v_next_version,
    'v' || v_next_version::text,
    p_revision_reason,
    p_change_summary,
    p_actor_id,
    v_current_version_id
  )
  returning id into v_new_version_id;

  update public.controlled_documents
  set document_status = 'under_revision',
      workflow_stage = 'revision',
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_document_id;

  perform public.patch26_write_document_event(p_document_id, v_new_version_id, 'revision_started', v_old_status, 'under_revision', p_actor_id, p_change_summary, null);
  return v_new_version_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."start_restore_dry_run"("p_scenario_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org uuid;
  v_id uuid;
begin
  select id into v_org from organizations order by created_at limit 1;
  insert into restore_dry_run_jobs (organization_id, title, scenario_name, status, result_summary, started_at)
  values (
    v_org,
    coalesce(nullif(p_scenario_name, ''), 'Restore dry-run'),
    coalesce(nullif(p_scenario_name, ''), 'Restore dry-run'),
    'planned',
    'Dry-run created. Apply migrations in test environment, import latest export package, then document result.',
    now()
  )
  returning id into v_id;

  insert into restore_dry_run_steps (organization_id, dry_run_job_id, step_order, step_name, status)
  values
  (v_org, v_id, 1, 'Create clean test Supabase project', 'pending'),
  (v_org, v_id, 2, 'Apply migrations in order', 'pending'),
  (v_org, v_id, 3, 'Import exported JSON/CSV package', 'pending'),
  (v_org, v_id, 4, 'Compare row counts and dashboard KPIs', 'pending'),
  (v_org, v_id, 5, 'Attach evidence and decision note', 'pending');

  return v_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."start_training_assignment"("p_assignment_id" "uuid", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.training_assignments
  set status = 'in_progress'
  where id = p_assignment_id and status = 'assigned';

  if not found then
    raise exception 'PATCH29_ASSIGNMENT_NOT_STARTABLE';
  end if;

  perform public.log_training_event(
    'training_assignments', p_assignment_id, 'started',
    'Training status updated to in_progress.',
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."submit_accreditation_clause_task"("p_task_id" "uuid", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_clause_id uuid;
  v_assigned_to_user_id uuid;
begin
  perform public.patch35_service_role_required();
  select clause_id, assigned_to_user_id into v_clause_id, v_assigned_to_user_id
  from public.accreditation_clause_review_tasks where id = p_task_id;

  if v_assigned_to_user_id is distinct from p_actor_user_id and not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_TASK_ASSIGNEE_OR_AUTHORITY_REQUIRED';
  end if;

  update public.accreditation_clause_review_tasks
  set status = 'submitted', submitted_at = now(), outcome_notes = coalesce(p_notes, outcome_notes)
  where id = p_task_id;

  perform public.record_accreditation_workflow_event('review_task', p_task_id, v_clause_id, 'task_submitted', coalesce(p_notes, 'Accreditation clause task submitted.'), p_actor_user_id);
  return jsonb_build_object('status','submitted','task_id',p_task_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."submit_capa_action_plan"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = 'action_plan_submitted', workflow_stage = 'review', updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'action_plan_submitted', v_old, 'action_plan_submitted', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."submit_capa_completion"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
