CREATE OR REPLACE FUNCTION "public"."submit_document_for_review"("p_document_id" "uuid", "p_version_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_old_status text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH26_DOCUMENT_SERVICE_ROLE_REQUIRED';
  end if;

  select document_status into v_old_status
  from public.controlled_documents
  where id = p_document_id
  for update;

  if not found then
    raise exception 'PATCH26_DOCUMENT_NOT_FOUND';
  end if;

  update public.controlled_documents
  set document_status = 'under_review',
      workflow_stage = 'review',
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_document_id;

  perform public.patch26_write_document_event(p_document_id, p_version_id, 'submitted_for_review', v_old_status, 'under_review', p_actor_id, p_note, null);
  return jsonb_build_object('status', 'ok', 'document_id', p_document_id, 'document_status', 'under_review');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."submit_evidence_collection_request"("p_collection_request_id" "uuid", "p_submitted_evidence_id" "uuid", "p_actor_user_id" "uuid", "p_submission_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_bridge_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_can_submit_request(p_collection_request_id, p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_OWNER_OR_AUTHORITY_REQUIRED'; end if;
  update public.evidence_collection_requests
  set submitted_evidence_id = p_submitted_evidence_id,
      status = 'submitted',
      completed_at = null
  where id = p_collection_request_id
  returning bridge_link_id into v_bridge_id;
  if not found then raise exception 'PATCH33_COLLECTION_REQUEST_NOT_FOUND'; end if;
  if v_bridge_id is not null then
    update public.evidence_bridge_links set evidence_id = p_submitted_evidence_id, evidence_status = 'pending_review', updated_by = p_actor_user_id, updated_at = now() where id = v_bridge_id;
  end if;
  perform public.record_evidence_bridge_event('evidence_collection_request', p_collection_request_id, 'collection_request_submitted', coalesce(p_submission_note, 'Evidence collection request submitted.'), p_actor_user_id);
  return jsonb_build_object('status','ok','collection_request_id',p_collection_request_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."transfer_accreditation_clause_owner"("p_assignment_id" "uuid", "p_new_owner_user_id" "uuid", "p_new_owner_department_id" "uuid", "p_actor_user_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_clause_id uuid;
  v_reviewer_user_id uuid;
  v_reviewer_department_id uuid;
  v_due_date date;
  v_new_assignment_id uuid;
begin
  perform public.patch35_service_role_required();
  if not public.patch35_actor_has_accreditation_workflow_authority(p_actor_user_id) then
    raise exception 'PATCH35_ACCREDITATION_WORKFLOW_AUTHORITY_REQUIRED';
  end if;
  if nullif(trim(p_reason), '') is null then
    raise exception 'PATCH35_TRANSFER_REASON_REQUIRED';
  end if;

  select clause_id, reviewer_user_id, reviewer_department_id, due_date
  into v_clause_id, v_reviewer_user_id, v_reviewer_department_id, v_due_date
  from public.accreditation_clause_owner_assignments
  where id = p_assignment_id;

  update public.accreditation_clause_owner_assignments
  set active = false, assignment_status = 'transferred'
  where id = p_assignment_id;

  insert into public.accreditation_clause_owner_assignments (
    clause_id, owner_user_id, owner_department_id, reviewer_user_id, reviewer_department_id,
    assigned_by, due_date, notes
  ) values (
    v_clause_id, p_new_owner_user_id, p_new_owner_department_id, v_reviewer_user_id, v_reviewer_department_id,
    p_actor_user_id, v_due_date, p_reason
  )
  returning id into v_new_assignment_id;

  perform public.record_accreditation_workflow_event('owner_assignment', v_new_assignment_id, v_clause_id, 'owner_transferred', p_reason, p_actor_user_id);
  return v_new_assignment_id;
end;
$$;

