CREATE OR REPLACE FUNCTION "public"."unlink_accreditation_clause_entity"("p_clause_id" "uuid", "p_linked_entity_type" "text", "p_linked_entity_id" "uuid", "p_actor_user_id" "uuid", "p_unlink_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH32_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch32_actor_has_accreditation_authority(p_actor_user_id) then raise exception 'PATCH32_ACCREDITATION_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(coalesce(p_unlink_reason,'')), '') is null then raise exception 'PATCH32_UNLINK_REASON_REQUIRED'; end if;
  update public.accreditation_clause_links
  set active = false, link_notes = concat_ws(' | ', link_notes, 'Unlinked: ' || p_unlink_reason)
  where clause_id = p_clause_id and linked_entity_type = p_linked_entity_type and linked_entity_id = p_linked_entity_id;
  if not found then raise exception 'PATCH32_CLAUSE_LINK_NOT_FOUND'; end if;
  perform public.record_accreditation_traceability_event(p_clause_id, p_linked_entity_type, p_linked_entity_id, 'entity_unlinked', p_unlink_reason, p_actor_user_id);
  return jsonb_build_object('status','ok','clause_id',p_clause_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_approval_authority_rule"("p_authority_rule_id" "uuid", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_actor_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_rule public.approval_authority_rules%rowtype;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH27_AUTHORITY_SERVICE_ROLE_REQUIRED';
  end if;

  select * into v_rule
  from public.approval_authority_rules
  where id = p_authority_rule_id
  for update;

  if not found then
    raise exception 'PATCH27_AUTHORITY_RULE_NOT_FOUND';
  end if;

  update public.approval_authority_rules
  set rule_name = coalesce(nullif(p_payload->>'rule_name', ''), rule_name),
      rule_description = coalesce(p_payload->>'rule_description', rule_description),
      linked_item_type = coalesce(nullif(p_payload->>'linked_item_type', ''), linked_item_type),
      department_id = coalesce(nullif(p_payload->>'department_id', '')::uuid, department_id),
      role_name = coalesce(nullif(p_payload->>'role_name', ''), role_name),
      approver_user_id = coalesce(nullif(p_payload->>'approver_user_id', '')::uuid, approver_user_id),
      approver_role = coalesce(nullif(p_payload->>'approver_role', ''), approver_role),
      min_amount = coalesce(nullif(p_payload->>'min_amount', '')::numeric, min_amount),
      max_amount = coalesce(nullif(p_payload->>'max_amount', '')::numeric, max_amount),
      risk_level = coalesce(nullif(p_payload->>'risk_level', ''), risk_level),
      severity_level = coalesce(nullif(p_payload->>'severity_level', ''), severity_level),
      criticality_level = coalesce(nullif(p_payload->>'criticality_level', ''), criticality_level),
      document_type = coalesce(nullif(p_payload->>'document_type', ''), document_type),
      escalation_level = coalesce(nullif(p_payload->>'escalation_level', ''), escalation_level),
      required_approval_count = coalesce(nullif(p_payload->>'required_approval_count', '')::integer, required_approval_count),
      requires_dual_approval = coalesce((p_payload->>'requires_dual_approval')::boolean, requires_dual_approval),
      requires_executive_approval = coalesce((p_payload->>'requires_executive_approval')::boolean, requires_executive_approval),
      allow_self_approval = coalesce((p_payload->>'allow_self_approval')::boolean, allow_self_approval),
      conflict_of_interest_block = coalesce((p_payload->>'conflict_of_interest_block')::boolean, conflict_of_interest_block),
      effective_date = coalesce(nullif(p_payload->>'effective_date', '')::date, effective_date),
      expiry_date = coalesce(nullif(p_payload->>'expiry_date', '')::date, expiry_date),
      updated_by = p_actor_id,
      updated_at = now()
  where id = p_authority_rule_id;

  perform public.patch27_write_authority_event(null, p_authority_rule_id, 'rule_updated', null, null, p_actor_id, 'Authority rule updated.');
  return jsonb_build_object('status', 'ok', 'authority_rule_id', p_authority_rule_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_audit_execution_test_step_status"("p_test_step_id" "uuid", "p_status" "text", "p_actor_user_id" "uuid", "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_assigned uuid;
begin
  perform public.patch37_service_role_required();
  select assigned_to_user_id into v_assigned from public.audit_execution_test_steps where id = p_test_step_id;
  if v_assigned is distinct from p_actor_user_id and not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_STEP_ASSIGNEE_OR_AUTHORITY_REQUIRED'; end if;
  update public.audit_execution_test_steps set status = p_status where id = p_test_step_id;
  perform public.record_clinical_governance_event('audit_test_step', p_test_step_id, 'audit_test_step_status_updated', coalesce(p_notes, 'Audit test step status updated.'), p_actor_user_id);
  return jsonb_build_object('status',p_status,'test_step_id',p_test_step_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."update_backup_restore_operation_status"("p_id" "uuid", "p_status" "text", "p_summary" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH40_HARDENING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.backup_restore_operations
  set operation_status = p_status,
      operation_summary = p_summary,
      last_run_at = now(),
      updated_at = now()
  where id = p_id;

  if not found then raise exception 'PATCH40_OPERATION_NOT_FOUND'; end if;

  perform public.log_production_hardening_event(
    'backup_restore_operations', p_id, 'status_updated',
    'Backup/restore operation status updated to: ' || p_status,
    p_actor_id
  );
end;
$$;

