CREATE OR REPLACE FUNCTION "public"."update_evidence_bridge_status"("p_bridge_link_id" "uuid", "p_evidence_status" "text", "p_freshness_status" "text", "p_actor_user_id" "uuid", "p_update_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_has_evidence_bridge_authority(p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_BRIDGE_AUTHORITY_REQUIRED'; end if;
  update public.evidence_bridge_links
  set evidence_status = p_evidence_status,
      freshness_status = p_freshness_status,
      updated_by = p_actor_user_id,
      updated_at = now()
  where id = p_bridge_link_id;
  if not found then raise exception 'PATCH33_BRIDGE_LINK_NOT_FOUND'; end if;
  perform public.record_evidence_bridge_event('evidence_bridge_link', p_bridge_link_id, 'bridge_status_updated', coalesce(p_update_note, 'Evidence bridge status updated.'), p_actor_user_id);
  return jsonb_build_object('status','ok','bridge_link_id',p_bridge_link_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_executive_governance_board_pack_status"("p_actor_id" "uuid", "p_board_pack_id" "uuid", "p_pack_status" "text", "p_board_review_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_pack record;
  v_open_blockers integer;
  v_notes text;
begin
  perform public.patch79_service_role_required();
  v_org_id := public.patch79_actor_authorized(p_actor_id);

  select * into v_pack
  from public.executive_governance_board_packs
  where id = p_board_pack_id
    and organization_id = v_org_id;

  if v_pack.id is null then
    raise exception 'Board closure pack is not available for this organization.';
  end if;
  if p_pack_status not in ('draft', 'review_required', 'ready_for_board_review', 'accepted_with_limitations', 'blocked', 'deferred') then
    raise exception 'Unsupported board closure pack status.';
  end if;

  v_notes := nullif(btrim(coalesce(p_board_review_notes, v_pack.board_review_notes, '')), '');

  if p_pack_status = 'ready_for_board_review' then
    select count(*)::integer into v_open_blockers
    from public.production_hypercare_items i
    where i.hypercare_window_id = v_pack.hypercare_window_id
      and i.severity in ('high', 'critical')
      and i.item_status in ('open', 'in_progress', 'evidence_required', 'review_required', 'blocked');

    if coalesce(v_open_blockers, 0) > 0 then
      raise exception 'High/critical open items block board pack ready for board review.';
    end if;
  end if;

  if p_pack_status = 'accepted_with_limitations' and v_notes is null then
    raise exception 'Board pack accepted with limitations requires board review notes.';
  end if;

  update public.executive_governance_board_packs
  set
    pack_status = p_pack_status,
    board_review_notes = v_notes,
    reviewed_by = case when p_pack_status in ('ready_for_board_review', 'accepted_with_limitations', 'blocked', 'deferred') then p_actor_id else reviewed_by end,
    reviewed_at = case when p_pack_status in ('ready_for_board_review', 'accepted_with_limitations', 'blocked', 'deferred') then now() else reviewed_at end,
    updated_at = now()
  where id = p_board_pack_id;

  if v_pack.hypercare_window_id is not null then
    update public.production_hypercare_windows
    set board_pack_status = p_pack_status,
        updated_at = now()
    where id = v_pack.hypercare_window_id;
  end if;

  return jsonb_build_object('id', p_board_pack_id, 'pack_status', p_pack_status, 'message', 'Executive monthly governance report and board closure pack status updated.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_facility_biomedical_safety_status"("p_safety_id" "uuid", "p_status" "text", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  update public.facility_biomedical_safety_evidence set status = p_status where id = p_safety_id;
  perform public.record_hospital_governance_event('facility_biomedical_safety_evidence', p_safety_id, 'facility_biomedical_safety_status_updated', 'Facility biomedical safety status updated.', p_actor_user_id); return jsonb_build_object('status','updated','id',p_safety_id,'safety_status',p_status);
end; $$;

CREATE OR REPLACE FUNCTION "public"."update_hospital_adoption_readiness_status"("p_adoption_review_id" "uuid", "p_adoption_status" "text", "p_active_user_count" integer DEFAULT NULL::integer, "p_inactive_user_count" integer DEFAULT NULL::integer, "p_training_incomplete_count" integer DEFAULT NULL::integer, "p_failed_workflow_attempt_count" integer DEFAULT NULL::integer, "p_feedback_required_count" integer DEFAULT NULL::integer, "p_support_needed" boolean DEFAULT NULL::boolean, "p_training_needed" boolean DEFAULT NULL::boolean, "p_adoption_summary" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_pack uuid;
begin
  perform public.patch55_service_role_required();
  if p_adoption_status in ('on_track', 'partial_adoption') and nullif(coalesce(p_evidence_reference, ''), '') is null then raise exception 'Evidence reference is required before marking adoption readiness on track.'; end if;
  update public.hospital_adoption_readiness_reviews
  set adoption_status = p_adoption_status, active_user_count = coalesce(p_active_user_count, active_user_count), inactive_user_count = coalesce(p_inactive_user_count, inactive_user_count), training_incomplete_count = coalesce(p_training_incomplete_count, training_incomplete_count), failed_workflow_attempt_count = coalesce(p_failed_workflow_attempt_count, failed_workflow_attempt_count), feedback_required_count = coalesce(p_feedback_required_count, feedback_required_count), support_needed = coalesce(p_support_needed, support_needed), training_needed = coalesce(p_training_needed, training_needed), adoption_summary = coalesce(p_adoption_summary, adoption_summary), evidence_reference = coalesce(p_evidence_reference, evidence_reference), reviewed_at = now(), updated_at = now()
  where id = p_adoption_review_id
  returning launch_pack_id into v_pack;
  if not found then raise exception 'Hospital adoption readiness review not found: %', p_adoption_review_id; end if;
  perform public.record_hospital_operations_readiness_event(v_pack, null, null, null, p_adoption_review_id, 'adoption_readiness_updated', 'Hospital adoption readiness updated to ' || p_adoption_status, p_actor_user_id, p_evidence_reference);
  return p_adoption_review_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_hospital_clinical_area_status"("p_area_id" "uuid", "p_active" boolean, "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$ begin
  perform public.patch38_service_role_required(); if not public.patch38_actor_has_master_data_authority(p_actor_user_id) then raise exception 'PATCH38_MASTER_DATA_AUTHORITY_REQUIRED'; end if;
  update public.hospital_master_clinical_areas set active = p_active where id = p_area_id;
  perform public.record_unified_work_queue_event('hospital_master_clinical_area', p_area_id, 'hospital_clinical_area_status_updated', 'Hospital clinical area status updated.', p_actor_user_id); return jsonb_build_object('status','updated','id',p_area_id,'active',p_active); end; $$;

