    AS $$ begin
  perform public.patch39_service_role_required(); if not public.patch39_actor_has_hospital_governance_authority(p_actor_user_id) then raise exception 'PATCH39_HOSPITAL_GOVERNANCE_AUTHORITY_REQUIRED'; end if;
  update public.infection_control_surveillance_events set status = p_status where id = p_event_id;
  perform public.record_hospital_governance_event('infection_control_event', p_event_id, 'infection_control_status_updated', 'Infection control event status updated.', p_actor_user_id); return jsonb_build_object('status','updated','id',p_event_id,'event_status',p_status);
end; $$;

CREATE OR REPLACE FUNCTION "public"."update_known_limitation_status"("p_id" "uuid", "p_status" "text", "p_mitigation" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH40_HARDENING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.production_known_limitations
  set limitation_status = p_status,
      mitigation_plan = p_mitigation,
      resolved_at = case when p_status = 'resolved' then now() else resolved_at end
  where id = p_id;

  if not found then raise exception 'PATCH40_LIMITATION_NOT_FOUND'; end if;

  perform public.log_production_hardening_event(
    'production_known_limitations', p_id, 'status_updated',
    'Known limitation status updated to: ' || p_status,
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_live_pilot_evidence_capture_status"("p_evidence_capture_id" "uuid", "p_evidence_status" "text", "p_review_notes" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_run_id uuid; v_step_id uuid; v_title text;
begin
  perform public.patch51_service_role_required();
  if p_evidence_status in ('rejected', 'needs_review') and nullif(coalesce(p_review_notes, ''), '') is null then raise exception 'Review notes are required for rejected or review-needed evidence.'; end if;
  update public.live_pilot_evidence_captures
  set evidence_status = p_evidence_status, review_notes = coalesce(p_review_notes, review_notes)
  where id = p_evidence_capture_id
  returning workflow_run_id, workflow_step_id, evidence_title into v_run_id, v_step_id, v_title;
  if not found then raise exception 'Live pilot evidence capture not found: %', p_evidence_capture_id; end if;
  perform public.record_live_pilot_workflow_event(v_run_id, v_step_id, 'evidence_status_updated', 'Live pilot evidence status updated to ' || p_evidence_status || ': ' || v_title, p_actor_user_id, null);
  return p_evidence_capture_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_live_pilot_execution_issue_status"("p_issue_id" "uuid", "p_issue_status" "text", "p_resolution_summary" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_run_id uuid; v_step_id uuid; v_issue_type text;
begin
  perform public.patch51_service_role_required();
  if p_issue_status in ('resolved', 'accepted_with_limitation') and nullif(coalesce(p_resolution_summary, ''), '') is null then raise exception 'Resolution summary is required before closing a live pilot execution issue.'; end if;
  update public.live_pilot_execution_issues
  set issue_status = p_issue_status, resolution_summary = coalesce(p_resolution_summary, resolution_summary), evidence_reference = coalesce(p_evidence_reference, evidence_reference), updated_at = now()
  where id = p_issue_id
  returning workflow_run_id, workflow_step_id, issue_type into v_run_id, v_step_id, v_issue_type;
  if not found then raise exception 'Live pilot execution issue not found: %', p_issue_id; end if;
  perform public.record_live_pilot_workflow_event(v_run_id, v_step_id, 'execution_issue_status_updated', 'Live pilot execution issue updated to ' || p_issue_status || ': ' || v_issue_type, p_actor_user_id, p_evidence_reference);
  return p_issue_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_live_pilot_issue_status"("p_actor_id" "uuid", "p_issue_id" "uuid", "p_issue_status" "text", "p_retest_status" "text" DEFAULT NULL::"text", "p_retest_evidence_summary" "text" DEFAULT NULL::"text", "p_closure_summary" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_issue_org_id uuid;
  v_session_id uuid;
  v_retest_required boolean;
  v_retest_status text;
begin
  perform public.patch77_service_role_required();
  v_org_id := public.patch77_actor_authorized(p_actor_id);

  select organization_id, pilot_session_id, retest_required
    into v_issue_org_id, v_session_id, v_retest_required
  from public.live_pilot_issues
  where id = p_issue_id;

  if v_issue_org_id is null or v_issue_org_id <> v_org_id then
    raise exception 'Pilot issue is not available for this organization.';
  end if;

  if p_issue_status not in ('open', 'in_progress', 'retest_required', 'closed', 'deferred', 'accepted_limitation') then
    raise exception 'Unsupported pilot issue status.';
  end if;

  v_retest_status := coalesce(p_retest_status, 'not_started');
  if v_retest_status not in ('not_started', 'pending', 'passed', 'failed', 'not_required') then
    raise exception 'Unsupported retest status.';
  end if;

  if p_issue_status = 'closed' and coalesce(v_retest_required, true) = true and v_retest_status not in ('passed', 'not_required') then
    raise exception 'Retest evidence required.';
  end if;

  update public.live_pilot_issues
  set
    issue_status = p_issue_status,
    retest_status = v_retest_status,
    retest_evidence_summary = nullif(btrim(coalesce(p_retest_evidence_summary, '')), ''),
    closure_summary = nullif(btrim(coalesce(p_closure_summary, '')), ''),
    updated_at = now()
  where id = p_issue_id;

  perform public.patch77_refresh_session_counts(v_session_id);

  return jsonb_build_object('id', p_issue_id, 'issue_status', p_issue_status, 'message', 'Pilot issue status updated.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_live_pilot_session_status"("p_actor_id" "uuid", "p_session_id" "uuid", "p_session_status" "text", "p_exit_review_notes" "text" DEFAULT NULL::"text", "p_exit_criteria_met" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_session_org_id uuid;
  v_critical integer;
  v_open integer;
  v_retest integer;
begin
  perform public.patch77_service_role_required();
  v_org_id := public.patch77_actor_authorized(p_actor_id);

  select organization_id into v_session_org_id
  from public.live_pilot_sessions
  where id = p_session_id;

  if v_session_org_id is null or v_session_org_id <> v_org_id then
    raise exception 'Pilot session is not available for this organization.';
  end if;

  if p_session_status not in ('planned', 'active', 'issue_burndown', 'exit_review_required', 'accepted', 'blocked', 'deferred') then
    raise exception 'Unsupported pilot session status.';
  end if;

  perform public.patch77_refresh_session_counts(p_session_id);
  select critical_issue_count, open_issue_count, retest_required_count
    into v_critical, v_open, v_retest
  from public.live_pilot_sessions
  where id = p_session_id;

  if p_session_status = 'accepted' then
    if coalesce(v_critical, 0) > 0 or coalesce(v_open, 0) > 0 then
      raise exception 'Pilot blockers remain.';
    end if;
    if coalesce(v_retest, 0) > 0 then
      raise exception 'Retest evidence required.';
    end if;
    if coalesce(p_exit_criteria_met, false) is not true then
      raise exception 'Pilot exit criteria must be met before acceptance.';
    end if;
  end if;

  update public.live_pilot_sessions
  set
    session_status = p_session_status,
    started_at = case when p_session_status in ('active', 'issue_burndown') and started_at is null then now() else started_at end,
    completed_at = case when p_session_status = 'accepted' then now() else completed_at end,
    exit_review_notes = nullif(btrim(coalesce(p_exit_review_notes, '')), ''),
    exit_criteria_met = coalesce(p_exit_criteria_met, false),
    updated_at = now()
  where id = p_session_id;

  return jsonb_build_object('id', p_session_id, 'session_status', p_session_status, 'message', 'Live pilot session status updated.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_live_pilot_workflow_run_status"("p_workflow_run_id" "uuid", "p_run_status" "text", "p_evidence_summary" "text" DEFAULT NULL::"text", "p_limitation_summary" "text" DEFAULT NULL::"text", "p_blocker_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.patch51_service_role_required();
  if p_run_status in ('passed', 'passed_with_limitations') and nullif(coalesce(p_evidence_summary, ''), '') is null then raise exception 'Evidence summary is required before marking a workflow walkthrough passed.'; end if;
  if p_run_status = 'passed_with_limitations' and nullif(coalesce(p_limitation_summary, ''), '') is null then raise exception 'Limitation summary is required for passed with limitations.'; end if;
  if p_run_status in ('failed', 'blocked') and nullif(coalesce(p_blocker_summary, ''), '') is null then raise exception 'Blocker summary is required for failed or blocked workflow walkthroughs.'; end if;
  update public.live_pilot_workflow_runs
  set run_status = p_run_status, evidence_summary = coalesce(p_evidence_summary, evidence_summary), limitation_summary = coalesce(p_limitation_summary, limitation_summary), blocker_summary = coalesce(p_blocker_summary, blocker_summary), started_at = case when p_run_status = 'in_progress' then now() else started_at end, completed_at = case when p_run_status in ('passed', 'passed_with_limitations', 'failed', 'blocked', 'cancelled') then now() else completed_at end, updated_at = now()
  where id = p_workflow_run_id;
  if not found then raise exception 'Live pilot workflow run not found: %', p_workflow_run_id; end if;
  perform public.record_live_pilot_workflow_event(p_workflow_run_id, null, 'workflow_run_status_updated', 'Live pilot workflow status updated to ' || p_run_status, p_actor_user_id, p_evidence_summary);
  return p_workflow_run_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_live_pilot_workflow_step_status"("p_workflow_step_id" "uuid", "p_step_status" "text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_issue_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_run_id uuid; v_step_label text; v_evidence_required boolean;
begin
  perform public.patch51_service_role_required();
  select workflow_run_id, step_label, evidence_required into v_run_id, v_step_label, v_evidence_required from public.live_pilot_workflow_steps where id = p_workflow_step_id;
  if not found then raise exception 'Live pilot workflow step not found: %', p_workflow_step_id; end if;
  if p_step_status in ('passed', 'passed_with_limitation') and v_evidence_required and nullif(coalesce(p_evidence_reference, ''), '') is null then raise exception 'Evidence reference is required before marking a workflow step passed.'; end if;
  if p_step_status in ('failed', 'blocked') and nullif(coalesce(p_issue_summary, ''), '') is null then raise exception 'Issue summary is required for failed or blocked workflow steps.'; end if;
  update public.live_pilot_workflow_steps
  set step_status = p_step_status, evidence_reference = coalesce(p_evidence_reference, evidence_reference), issue_summary = coalesce(p_issue_summary, issue_summary), completed_at = case when p_step_status in ('passed', 'passed_with_limitation', 'failed', 'blocked', 'not_applicable') then now() else completed_at end
  where id = p_workflow_step_id;
  perform public.record_live_pilot_workflow_event(v_run_id, p_workflow_step_id, 'workflow_step_status_updated', 'Live pilot workflow step updated to ' || p_step_status || ': ' || v_step_label, p_actor_user_id, p_evidence_reference);
  return p_workflow_step_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_navigation_simplification_status"("p_id" "uuid", "p_status" "text", "p_notes" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH40_HARDENING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.navigation_simplification_items
  set simplification_status = p_status,
      risk_notes = p_notes,
      updated_at = now()
  where id = p_id;

  if not found then raise exception 'PATCH40_ROUTE_PROPOSAL_NOT_FOUND'; end if;

  perform public.log_production_hardening_event(
    'navigation_simplification_items', p_id, 'status_updated',
    'Navigation route simplification status updated to: ' || p_status,
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_ovr_rca_status"("p_rca_case_id" "uuid", "p_status" "text", "p_actor_user_id" "uuid", "p_root_cause_summary" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_owner uuid;
begin
  perform public.patch37_service_role_required();
  select owner_user_id into v_owner from public.ovr_rca_cases where id = p_rca_case_id;
  if v_owner is distinct from p_actor_user_id and not public.patch37_actor_has_clinical_governance_authority(p_actor_user_id) then raise exception 'PATCH37_RCA_OWNER_OR_AUTHORITY_REQUIRED'; end if;
  update public.ovr_rca_cases set rca_status = p_status, root_cause_summary = coalesce(p_root_cause_summary, root_cause_summary) where id = p_rca_case_id;
  perform public.record_clinical_governance_event('ovr_rca_case', p_rca_case_id, 'ovr_rca_status_updated', coalesce(p_root_cause_summary, 'OVR RCA status updated.'), p_actor_user_id);
  return jsonb_build_object('status',p_status,'rca_case_id',p_rca_case_id);
end; $$;

CREATE OR REPLACE FUNCTION "public"."update_ovr_workflow"("p_ovr_report_id" "uuid", "p_next_status" "text", "p_note" "text" DEFAULT NULL::"text", "p_supervisor_investigation" "text" DEFAULT NULL::"text", "p_corrective_action" "text" DEFAULT NULL::"text", "p_quality_manager_comments" "text" DEFAULT NULL::"text", "p_confirmed_severity_level" "public"."ovr_severity_level" DEFAULT NULL::"public"."ovr_severity_level", "p_corrective_action_due_date" "date" DEFAULT NULL::"date") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_ovr public.ovr_reports%rowtype;
  v_actor uuid := auth.uid();
begin
  select * into v_ovr
  from public.ovr_reports
  where id = p_ovr_report_id;

  if not found then
    raise exception 'OVR report not found';
  end if;

  if not public.can_access_scope(v_ovr.organization_id, v_ovr.division_id, v_ovr.department_id, v_ovr.unit_id)
     and not public.can_manage_grc() then
    raise exception 'You are not allowed to update this OVR report';
  end if;

  if p_next_status in ('closed', 'quality_closure_review') and not public.can_manage_grc() then
    raise exception 'Only Quality/GRC authorized roles can close or approve closure of OVR reports';
  end if;

  if p_next_status = 'under_quality_review' and coalesce(trim(p_supervisor_investigation), trim(v_ovr.supervisor_investigation), '') = '' then
    raise exception 'Supervisor/HOD investigation is required before Quality review';
  end if;

  if p_next_status in ('action_plan_required', 'corrective_action_in_progress')
     and coalesce(trim(p_corrective_action), trim(v_ovr.corrective_action), '') = '' then
    raise exception 'Corrective action is required for this OVR workflow step';
  end if;

  if p_next_status = 'returned_for_clarification' and coalesce(trim(p_note), '') = '' then
    raise exception 'Return reason is required before returning OVR for clarification';
  end if;

  if p_next_status = 'closed' then
    if coalesce(trim(p_quality_manager_comments), trim(v_ovr.quality_manager_comments), '') = '' then
      raise exception 'Quality closure comments are required before closure';
    end if;

    if not public.can_close_ovr(p_ovr_report_id) then
      raise exception 'OVR cannot be closed until accepted evidence is uploaded or linked corrective project is closed';
    end if;
  end if;

  update public.ovr_reports
  set
    status = p_next_status::public.ovr_status,
    supervisor_investigation = coalesce(nullif(trim(p_supervisor_investigation), ''), supervisor_investigation),
    corrective_action = coalesce(nullif(trim(p_corrective_action), ''), corrective_action),
    quality_manager_comments = coalesce(nullif(trim(p_quality_manager_comments), ''), quality_manager_comments),
    quality_closure_note = case when p_next_status = 'closed' then coalesce(nullif(trim(p_note), ''), quality_closure_note) else quality_closure_note end,
    rejection_reason = case when p_next_status in ('returned_for_clarification', 'rejected') then p_note else rejection_reason end,
    severity_level = coalesce(p_confirmed_severity_level, severity_level),
    final_severity_level = case when p_next_status = 'closed' then coalesce(p_confirmed_severity_level, severity_level) else final_severity_level end,
    corrective_action_due_date = coalesce(p_corrective_action_due_date, corrective_action_due_date),
    supervisor_due_date = case when p_next_status = 'submitted' then current_date + 1 else supervisor_due_date end,
    quality_due_date = case when p_next_status in ('under_quality_review', 'evidence_submitted', 'quality_closure_review') then current_date + 2 else quality_due_date end,
    reviewed_at = case when p_next_status in ('under_quality_review', 'action_plan_required', 'corrective_action_in_progress', 'evidence_submitted', 'quality_closure_review', 'closed') then now() else reviewed_at end,
    closed_by = case when p_next_status = 'closed' then v_actor else closed_by end,
    closed_at = case when p_next_status = 'closed' then now() else closed_at end,
    updated_by = v_actor,
    updated_at = now()
  where id = p_ovr_report_id;

  insert into public.comments (organization_id, ovr_report_id, body, created_by)
  values (
    v_ovr.organization_id,
    p_ovr_report_id,
    concat('OVR workflow changed to ', p_next_status, case when coalesce(trim(p_note), '') <> '' then ': ' || p_note else '' end),
    v_actor
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_pilot_accepted_limitation_status"("p_limitation_id" "uuid", "p_limitation_status" "text", "p_accepted_by" "uuid" DEFAULT NULL::"uuid", "p_mitigation_plan" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_closure_review_id uuid; v_activation_run_id uuid; v_title text;
begin
  perform public.patch52_service_role_required();
  if p_limitation_status = 'accepted' and (p_accepted_by is null or nullif(coalesce(p_mitigation_plan, ''), '') is null or nullif(coalesce(p_evidence_reference, ''), '') is null) then raise exception 'Accepted limitations require approver, mitigation plan, and evidence reference.'; end if;
  update public.pilot_accepted_limitations
  set limitation_status = p_limitation_status, accepted_by = coalesce(p_accepted_by, accepted_by), accepted_at = case when p_limitation_status = 'accepted' then now() else accepted_at end, mitigation_plan = coalesce(p_mitigation_plan, mitigation_plan), evidence_reference = coalesce(p_evidence_reference, evidence_reference), updated_at = now()
  where id = p_limitation_id
  returning closure_review_id, activation_run_id, limitation_title into v_closure_review_id, v_activation_run_id, v_title;
  if not found then raise exception 'Pilot limitation not found: %', p_limitation_id; end if;
  perform public.record_pilot_closure_event(v_closure_review_id, v_activation_run_id, 'limitation_status_updated', 'Pilot limitation status updated to ' || p_limitation_status || ': ' || v_title, p_actor_user_id, p_evidence_reference);
  return p_limitation_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_pilot_closure_review_status"("p_closure_review_id" "uuid", "p_closure_status" "text", "p_decision_summary" "text" DEFAULT NULL::"text", "p_limitation_summary" "text" DEFAULT NULL::"text", "p_blocker_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_activation_run_id uuid;
begin
  perform public.patch52_service_role_required();
  if p_closure_status in ('approved_for_golive', 'approved_with_limitations', 'blocked', 'deferred') and nullif(coalesce(p_decision_summary, ''), '') is null then raise exception 'Decision summary is required for closure decision status.'; end if;
  if p_closure_status = 'approved_with_limitations' and nullif(coalesce(p_limitation_summary, ''), '') is null then raise exception 'Limitation summary is required for approval with limitations.'; end if;
  if p_closure_status = 'blocked' and nullif(coalesce(p_blocker_summary, ''), '') is null then raise exception 'Blocker summary is required when closure is blocked.'; end if;
  update public.pilot_closure_reviews
  set closure_status = p_closure_status, decision_summary = coalesce(p_decision_summary, decision_summary), limitation_summary = coalesce(p_limitation_summary, limitation_summary), blocker_summary = coalesce(p_blocker_summary, blocker_summary), updated_at = now()
  where id = p_closure_review_id
  returning activation_run_id into v_activation_run_id;
  if not found then raise exception 'Pilot closure review not found: %', p_closure_review_id; end if;
  perform public.record_pilot_closure_event(p_closure_review_id, v_activation_run_id, 'closure_review_status_updated', 'Pilot closure status updated to ' || p_closure_status, p_actor_user_id, null);
  return p_closure_review_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_pilot_go_no_go_review_status"("p_review_id" "uuid", "p_status" "text", "p_notes" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
    UPDATE public.pilot_go_no_go_reviews
    SET
        review_status = p_status,
        review_notes = p_notes,
        reviewer_user_id = p_actor_id,
        reviewed_at = now()
    WHERE id = p_review_id;

    PERFORM public.record_pilot_go_no_go_event(p_review_id, 'status_updated', 'Review status updated to ' || p_status, p_actor_id);
END;
$$;

CREATE OR REPLACE FUNCTION "public"."update_pilot_remediation_action_status"("p_remediation_action_id" "uuid", "p_remediation_status" "text", "p_remediation_summary" "text" DEFAULT NULL::"text", "p_risk_acceptance_reason" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_closure_review_id uuid; v_activation_run_id uuid; v_title text;
begin
  perform public.patch52_service_role_required();
  if p_remediation_status = 'completed' and (nullif(coalesce(p_remediation_summary, ''), '') is null or nullif(coalesce(p_evidence_reference, ''), '') is null) then raise exception 'Remediation summary and evidence reference are required before completion.'; end if;
  if p_remediation_status = 'accepted_risk' and nullif(coalesce(p_risk_acceptance_reason, ''), '') is null then raise exception 'Risk acceptance reason is required for accepted risk remediation.'; end if;
  update public.pilot_remediation_actions
  set remediation_status = p_remediation_status, remediation_summary = coalesce(p_remediation_summary, remediation_summary), risk_acceptance_reason = coalesce(p_risk_acceptance_reason, risk_acceptance_reason), evidence_reference = coalesce(p_evidence_reference, evidence_reference), completed_at = case when p_remediation_status in ('completed', 'accepted_risk', 'cancelled') then now() else completed_at end, updated_at = now()
  where id = p_remediation_action_id
  returning closure_review_id, activation_run_id, remediation_title into v_closure_review_id, v_activation_run_id, v_title;
  if not found then raise exception 'Pilot remediation action not found: %', p_remediation_action_id; end if;
  perform public.record_pilot_closure_event(v_closure_review_id, v_activation_run_id, 'remediation_action_status_updated', 'Pilot remediation status updated to ' || p_remediation_status || ': ' || v_title, p_actor_user_id, p_evidence_reference);
  return p_remediation_action_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_adoption_feedback_status"("p_feedback_id" "uuid", "p_feedback_status" "text", "p_adoption_status" "text", "p_feedback_summary" "text" DEFAULT NULL::"text", "p_support_needed" boolean DEFAULT false, "p_training_needed" boolean DEFAULT false, "p_issue_reference" "text" DEFAULT NULL::"text", "p_reviewed_by" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_period_id uuid;
begin
  perform public.patch53_service_role_required();
  if p_feedback_status in ('submitted', 'reviewed', 'action_required', 'closed') and nullif(coalesce(p_feedback_summary, ''), '') is null then raise exception 'Feedback summary is required before updating adoption feedback.'; end if;
  if p_adoption_status in ('low_adoption', 'blocked') and nullif(coalesce(p_issue_reference, ''), '') is null then raise exception 'Issue reference is required for low adoption or blocked departments.'; end if;
  update public.production_adoption_feedback
  set feedback_status = p_feedback_status, adoption_status = p_adoption_status, feedback_summary = coalesce(p_feedback_summary, feedback_summary), support_needed = coalesce(p_support_needed, support_needed), training_needed = coalesce(p_training_needed, training_needed), issue_reference = coalesce(p_issue_reference, issue_reference), submitted_at = case when p_feedback_status = 'submitted' then now() else submitted_at end, reviewed_by = coalesce(p_reviewed_by, reviewed_by), reviewed_at = case when p_feedback_status in ('reviewed', 'action_required', 'closed') then now() else reviewed_at end, updated_at = now()
  where id = p_feedback_id
  returning hypercare_period_id into v_period_id;
  if not found then raise exception 'Production adoption feedback not found: %', p_feedback_id; end if;
  perform public.record_production_hypercare_event(v_period_id, null, null, 'adoption_feedback_status_updated', 'Production adoption feedback updated to ' || p_feedback_status || ' / ' || p_adoption_status, p_actor_user_id, p_issue_reference);
  return p_feedback_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_golive_decision_status"("p_decision_id" "uuid", "p_decision_status" "text", "p_decision_summary" "text" DEFAULT NULL::"text", "p_conditions_summary" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_closure_review_id uuid; v_activation_run_id uuid;
begin
  perform public.patch52_service_role_required();
  if p_decision_status in ('approved', 'approved_with_limitations', 'rejected', 'deferred', 'revoked') and nullif(coalesce(p_decision_summary, ''), '') is null then raise exception 'Decision summary is required for go-live decision status.'; end if;
  if p_decision_status = 'approved_with_limitations' and nullif(coalesce(p_conditions_summary, ''), '') is null then raise exception 'Conditions summary is required for go-live approval with limitations.'; end if;
  update public.production_golive_decisions
  set decision_status = p_decision_status, decision_summary = coalesce(p_decision_summary, decision_summary), conditions_summary = coalesce(p_conditions_summary, conditions_summary), evidence_reference = coalesce(p_evidence_reference, evidence_reference), decision_at = case when p_decision_status in ('approved', 'approved_with_limitations', 'rejected', 'deferred', 'revoked') then now() else decision_at end, decision_by = coalesce(p_actor_user_id, decision_by), updated_at = now()
  where id = p_decision_id
  returning closure_review_id, activation_run_id into v_closure_review_id, v_activation_run_id;
  if not found then raise exception 'Production go-live decision not found: %', p_decision_id; end if;
  perform public.record_pilot_closure_event(v_closure_review_id, v_activation_run_id, 'golive_decision_status_updated', 'Production go-live decision updated to ' || p_decision_status, p_actor_user_id, p_evidence_reference);
  return p_decision_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_hypercare_issue_status"("p_issue_id" "uuid", "p_issue_status" "text", "p_resolution_summary" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_period_id uuid; v_title text;
begin
  perform public.patch53_service_role_required();
  if p_issue_status in ('resolved', 'accepted_risk') and (nullif(coalesce(p_resolution_summary, ''), '') is null or nullif(coalesce(p_evidence_reference, ''), '') is null) then raise exception 'Resolution summary and evidence reference are required before closing or accepting a hypercare issue.'; end if;
  update public.production_hypercare_issues
  set issue_status = p_issue_status, resolution_summary = coalesce(p_resolution_summary, resolution_summary), evidence_reference = coalesce(p_evidence_reference, evidence_reference), resolved_at = case when p_issue_status in ('resolved', 'accepted_risk', 'cancelled') then now() else resolved_at end, updated_at = now()
  where id = p_issue_id
  returning hypercare_period_id, issue_title into v_period_id, v_title;
  if not found then raise exception 'Production hypercare issue not found: %', p_issue_id; end if;
  perform public.record_production_hypercare_event(v_period_id, p_issue_id, null, 'hypercare_issue_status_updated', 'Production hypercare issue updated to ' || p_issue_status || ': ' || v_title, p_actor_user_id, p_evidence_reference);
  return p_issue_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_hypercare_item_status"("p_actor_id" "uuid", "p_item_id" "uuid", "p_item_status" "text", "p_evidence_summary" "text" DEFAULT NULL::"text", "p_closure_summary" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_item record;
  v_evidence text;
  v_closure text;
begin
  perform public.patch79_service_role_required();
  v_org_id := public.patch79_actor_authorized(p_actor_id);

  select * into v_item
  from public.production_hypercare_items
  where id = p_item_id
    and organization_id = v_org_id;

  if v_item.id is null then
    raise exception 'Hypercare governance item is not available for this organization.';
  end if;
  if p_item_status not in ('open', 'in_progress', 'evidence_required', 'review_required', 'closed', 'accepted_limitation', 'deferred', 'blocked') then
    raise exception 'Unsupported hypercare governance item status.';
  end if;

  v_evidence := nullif(btrim(coalesce(p_evidence_summary, v_item.evidence_summary, '')), '');
  v_closure := nullif(btrim(coalesce(p_closure_summary, v_item.closure_summary, '')), '');

  if p_item_status = 'closed' and v_item.severity in ('high', 'critical') and v_closure is null then
    raise exception 'High/critical hypercare governance items cannot close without closure summary.';
  end if;
  if p_item_status = 'closed' and v_item.item_type = 'evidence_pack_gap' and v_evidence is null then
    raise exception 'Evidence pack gaps cannot close without evidence summary.';
  end if;

  update public.production_hypercare_items
  set
    item_status = p_item_status,
    evidence_summary = v_evidence,
    closure_summary = v_closure,
    updated_at = now()
  where id = p_item_id;

  perform public.patch79_refresh_window_counts(v_item.hypercare_window_id);

  return jsonb_build_object('id', p_item_id, 'item_status', p_item_status, 'message', 'Production operations governance item status updated.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_hypercare_period_status"("p_hypercare_period_id" "uuid", "p_hypercare_status" "text", "p_stability_summary" "text" DEFAULT NULL::"text", "p_blocker_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.patch53_service_role_required();
  if p_hypercare_status in ('stable', 'completed') and nullif(coalesce(p_stability_summary, ''), '') is null then raise exception 'Stability summary is required before marking hypercare stable or complete.'; end if;
  if p_hypercare_status in ('at_risk', 'blocked', 'extended') and nullif(coalesce(p_blocker_summary, ''), '') is null then raise exception 'Blocker summary is required for at-risk, blocked, or extended hypercare.'; end if;
  update public.production_hypercare_periods
  set hypercare_status = p_hypercare_status, stability_summary = coalesce(p_stability_summary, stability_summary), blocker_summary = coalesce(p_blocker_summary, blocker_summary), actual_end_date = case when p_hypercare_status in ('stable', 'completed', 'cancelled') then current_date else actual_end_date end, updated_at = now()
  where id = p_hypercare_period_id;
  if not found then raise exception 'Production hypercare period not found: %', p_hypercare_period_id; end if;
  perform public.record_production_hypercare_event(p_hypercare_period_id, null, null, 'hypercare_period_status_updated', 'Production hypercare status updated to ' || p_hypercare_status, p_actor_user_id, null);
  return p_hypercare_period_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_hypercare_window_status"("p_actor_id" "uuid", "p_hypercare_window_id" "uuid", "p_hypercare_status" "text", "p_day_30_status" "text" DEFAULT NULL::"text", "p_day_60_status" "text" DEFAULT NULL::"text", "p_day_90_status" "text" DEFAULT NULL::"text", "p_evidence_pack_status" "text" DEFAULT NULL::"text", "p_board_pack_status" "text" DEFAULT NULL::"text", "p_exit_review_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_org_id uuid;
  v_window record;
  v_day_30 text;
  v_day_60 text;
  v_day_90 text;
  v_evidence_status text;
  v_board_status text;
  v_notes text;
begin
  perform public.patch79_service_role_required();
  v_org_id := public.patch79_actor_authorized(p_actor_id);

  if p_hypercare_status not in ('planned', 'active', 'monitoring', 'exit_review_required', 'blocked', 'deferred', 'closed_with_limitations') then
    raise exception 'Unsupported hypercare status.';
  end if;

  perform public.patch79_refresh_window_counts(p_hypercare_window_id);
  select * into v_window
  from public.production_hypercare_windows
  where id = p_hypercare_window_id
    and organization_id = v_org_id;

  if v_window.id is null then
    raise exception 'Hypercare command center record is not available for this organization.';
  end if;

  v_day_30 := coalesce(p_day_30_status, v_window.day_30_status);
  v_day_60 := coalesce(p_day_60_status, v_window.day_60_status);
  v_day_90 := coalesce(p_day_90_status, v_window.day_90_status);
  v_evidence_status := coalesce(p_evidence_pack_status, v_window.evidence_pack_status);
  v_board_status := coalesce(p_board_pack_status, v_window.board_pack_status);
  v_notes := nullif(btrim(coalesce(p_exit_review_notes, v_window.exit_review_notes, '')), '');

  if v_day_30 not in ('not_started', 'in_progress', 'review_required', 'accepted', 'blocked', 'deferred')
    or v_day_60 not in ('not_started', 'in_progress', 'review_required', 'accepted', 'blocked', 'deferred')
    or v_day_90 not in ('not_started', 'in_progress', 'review_required', 'accepted', 'blocked', 'deferred') then
    raise exception 'Unsupported 30/60/90 operating view status.';
  end if;
  if v_evidence_status not in ('incomplete', 'collecting', 'ready_for_review', 'accepted_with_limitations', 'blocked') then
    raise exception 'Unsupported accreditation/evidence pack tracking status.';
  end if;
  if v_board_status not in ('draft', 'review_required', 'ready_for_board_review', 'accepted_with_limitations', 'blocked', 'deferred') then
    raise exception 'Unsupported board closure pack status.';
  end if;

  if p_hypercare_status = 'exit_review_required' then
    if coalesce(v_window.critical_incident_count, 0) > 0 then
      raise exception 'Critical incidents block hypercare exit review.';
    end if;
    if coalesce(v_window.open_support_issue_count, 0) > 0 and coalesce(v_window.unresolved_limitation_count, 0) = 0 and v_evidence_status <> 'accepted_with_limitations' and v_board_status <> 'accepted_with_limitations' then
      raise exception 'Open support issues block hypercare exit review unless limitations are accepted.';
    end if;
    if v_evidence_status in ('incomplete', 'blocked') then
      raise exception 'Incomplete or blocked evidence pack blocks hypercare exit review.';
    end if;
    if v_board_status in ('draft', 'blocked') then
      raise exception 'Board pack draft or blocked status blocks hypercare exit review.';
    end if;
  end if;

  if p_hypercare_status = 'closed_with_limitations' and v_notes is null then
    raise exception 'Hypercare closure requires exit review notes.';
  end if;

  update public.production_hypercare_windows
  set
    hypercare_status = p_hypercare_status,
    day_30_status = v_day_30,
    day_60_status = v_day_60,
    day_90_status = v_day_90,
    evidence_pack_status = v_evidence_status,
    board_pack_status = v_board_status,
    hypercare_exit_ready = p_hypercare_status = 'exit_review_required',
    exit_review_notes = v_notes,
    reviewed_by = case when p_hypercare_status in ('exit_review_required', 'closed_with_limitations', 'blocked', 'deferred') then p_actor_id else reviewed_by end,
    reviewed_at = case when p_hypercare_status in ('exit_review_required', 'closed_with_limitations', 'blocked', 'deferred') then now() else reviewed_at end,
    updated_at = now()
  where id = p_hypercare_window_id;

  return jsonb_build_object('id', p_hypercare_window_id, 'hypercare_status', p_hypercare_status, 'message', 'Production operations governance hypercare status updated.');
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_operating_cadence_event_status"("p_cadence_event_id" "uuid", "p_event_status" "text", "p_summary" "text" DEFAULT NULL::"text", "p_decisions_summary" "text" DEFAULT NULL::"text", "p_action_summary" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare v_period_id uuid; v_type text;
begin
  perform public.patch53_service_role_required();
  if p_event_status = 'completed' and nullif(coalesce(p_summary, ''), '') is null then raise exception 'Summary is required before completing an operating cadence event.'; end if;
  if p_event_status = 'missed' and nullif(coalesce(p_action_summary, ''), '') is null then raise exception 'Action summary is required for missed operating cadence events.'; end if;
  update public.production_operating_cadence_events
  set event_status = p_event_status, summary = coalesce(p_summary, summary), decisions_summary = coalesce(p_decisions_summary, decisions_summary), action_summary = coalesce(p_action_summary, action_summary), evidence_reference = coalesce(p_evidence_reference, evidence_reference), completed_at = case when p_event_status = 'completed' then now() else completed_at end, updated_at = now()
  where id = p_cadence_event_id
  returning hypercare_period_id, cadence_type into v_period_id, v_type;
  if not found then raise exception 'Production cadence event not found: %', p_cadence_event_id; end if;
  perform public.record_production_hypercare_event(v_period_id, null, p_cadence_event_id, 'cadence_event_status_updated', 'Production cadence event updated to ' || p_event_status || ': ' || v_type, p_actor_user_id, p_evidence_reference);
  return p_cadence_event_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_production_readiness_signoff_status"("p_id" "uuid", "p_status" "text", "p_notes" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH40_HARDENING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.production_readiness_signoffs
  set signoff_status = p_status,
      signoff_notes = p_notes,
      signed_by = p_actor_id,
      signed_at = now(),
      updated_at = now()
  where id = p_id;

  if not found then raise exception 'PATCH40_SIGNOFF_NOT_FOUND'; end if;

  perform public.log_production_hardening_event(
    'production_readiness_signoffs', p_id, 'status_updated',
    'Production readiness signoff status updated to: ' || p_status,
    p_actor_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_real_pilot_master_data_exception_status"("p_exception_id" "uuid", "p_exception_status" "text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_resolution_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_exception_type text;
begin
  perform public.patch50_service_role_required();
  if p_exception_status not in ('open', 'in_review', 'resolved', 'accepted_with_limitation') then
    raise exception 'Invalid real pilot master data exception status: %', p_exception_status;
  end if;
  if p_exception_status in ('resolved', 'accepted_with_limitation') and nullif(coalesce(p_resolution_summary, ''), '') is null then
    raise exception 'Resolution summary is required before closing or accepting a real pilot master data exception.';
  end if;
  if p_exception_status = 'accepted_with_limitation' and nullif(coalesce(p_evidence_reference, ''), '') is null then
    raise exception 'Evidence reference is required for master data exception acceptance with limitation.';
  end if;
  update public.real_pilot_master_data_exceptions
  set exception_status = p_exception_status,
      evidence_reference = coalesce(p_evidence_reference, evidence_reference),
      resolution_summary = coalesce(p_resolution_summary, resolution_summary),
      updated_at = now()
  where id = p_exception_id
  returning activation_run_id, exception_type into v_run_id, v_exception_type;
  if not found then raise exception 'Real pilot master data exception not found: %', p_exception_id; end if;
  perform public.record_real_pilot_onboarding_event(v_run_id, null, 'master_data_exception_status_updated', 'Real pilot master data exception updated to ' || p_exception_status || ': ' || v_exception_type, p_actor_user_id, p_evidence_reference);
  return p_exception_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_real_pilot_onboarding_review_status"("p_review_id" "uuid", "p_review_status" "text", "p_reviewed_by" "uuid" DEFAULT NULL::"uuid", "p_limitation_summary" "text" DEFAULT NULL::"text", "p_blocker_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run_id uuid;
begin
  perform public.patch50_service_role_required();
  if p_review_status not in ('draft', 'in_progress', 'ready_for_review', 'approved', 'approved_with_limitations', 'blocked') then
    raise exception 'Invalid real pilot onboarding review status: %', p_review_status;
  end if;
  if p_review_status in ('approved', 'approved_with_limitations') and nullif(coalesce(p_reviewed_by::text, ''), '') is null then
    raise exception 'Reviewer is required before approving real pilot onboarding.';
  end if;
  if p_review_status = 'approved_with_limitations' and nullif(coalesce(p_limitation_summary, ''), '') is null then
    raise exception 'Limitation summary is required for real pilot onboarding approval with limitations.';
  end if;
  if p_review_status = 'blocked' and nullif(coalesce(p_blocker_summary, ''), '') is null then
    raise exception 'Blocker summary is required for blocked real pilot onboarding.';
  end if;
  update public.real_pilot_onboarding_reviews
  set review_status = p_review_status,
      reviewed_by = coalesce(p_reviewed_by, reviewed_by),
      reviewed_at = case when p_review_status in ('approved', 'approved_with_limitations', 'blocked') then now() else reviewed_at end,
      limitation_summary = coalesce(p_limitation_summary, limitation_summary),
      blocker_summary = coalesce(p_blocker_summary, blocker_summary),
      updated_at = now()
  where id = p_review_id
  returning activation_run_id into v_run_id;
  if not found then raise exception 'Real pilot onboarding review not found: %', p_review_id; end if;
  perform public.record_real_pilot_onboarding_event(v_run_id, p_review_id, 'onboarding_review_status_updated', 'Real pilot onboarding review updated to ' || p_review_status, p_actor_user_id, null);
  return p_review_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_real_pilot_setup_checklist_item_status"("p_checklist_item_id" "uuid", "p_item_status" "text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_issue_summary" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_run_id uuid;
  v_item_label text;
begin
  perform public.patch50_service_role_required();
  if p_item_status not in ('pending', 'ready', 'blocked', 'not_applicable', 'evidence_required') then
    raise exception 'Invalid real pilot setup checklist item status: %', p_item_status;
  end if;
  if p_item_status = 'ready' and nullif(coalesce(p_evidence_reference, ''), '') is null then
    raise exception 'Evidence reference is required before marking a real pilot setup checklist item ready.';
  end if;
  if p_item_status in ('blocked', 'evidence_required') and nullif(coalesce(p_issue_summary, ''), '') is null then
    raise exception 'Issue summary is required for blocked or evidence-required setup checklist items.';
  end if;
  update public.real_pilot_setup_checklist_items
  set item_status = p_item_status,
      evidence_reference = coalesce(p_evidence_reference, evidence_reference),
      issue_summary = coalesce(p_issue_summary, issue_summary),
      updated_at = now()
  where id = p_checklist_item_id
  returning activation_run_id, item_label into v_run_id, v_item_label;
  if not found then raise exception 'Real pilot setup checklist item not found: %', p_checklist_item_id; end if;
  perform public.record_real_pilot_onboarding_event(v_run_id, null, 'setup_checklist_item_status_updated', 'Real pilot setup checklist item updated to ' || p_item_status || ': ' || v_item_label, p_actor_user_id, p_evidence_reference);
  return p_checklist_item_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_runtime_action_review_signoff_status"("p_signoff_id" "uuid", "p_signoff_status" "text", "p_limitation_summary" "text" DEFAULT NULL::"text", "p_evidence_reference" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_action_name text;
begin
  perform public.patch46_service_role_required();

  if p_signoff_status not in ('pending', 'approved', 'approved_with_limitation', 'rejected', 'expired', 'superseded') then
    raise exception 'Invalid runtime access review signoff status: %', p_signoff_status;
  end if;

  if p_signoff_status in ('approved', 'approved_with_limitation', 'rejected')
     and nullif(coalesce(p_evidence_reference, ''), '') is null then
    raise exception 'Closure evidence required for approved, approved-with-limitation, or rejected runtime access review signoff.';
  end if;

  if p_signoff_status = 'approved_with_limitation'
     and nullif(coalesce(p_limitation_summary, ''), '') is null then
    raise exception 'Limitation summary required for approved-with-limitation runtime access review signoff.';
  end if;

  update public.runtime_action_review_signoffs
  set
    signoff_status = p_signoff_status,
    limitation_summary = coalesce(p_limitation_summary, limitation_summary),
    evidence_reference = coalesce(p_evidence_reference, evidence_reference),
    risk_acceptance_required = case
      when p_signoff_status = 'approved_with_limitation' then true
      else risk_acceptance_required
    end,
    signed_off_at = case
      when p_signoff_status in ('approved', 'approved_with_limitation', 'rejected', 'expired', 'superseded') then now()
      else signed_off_at
    end
  where id = p_signoff_id
  returning action_name into v_action_name;

  if v_action_name is null then
    raise exception 'Runtime access review signoff not found: %', p_signoff_id;
  end if;

  perform public.record_runtime_action_review_signoff_event(
    p_signoff_id,
    v_action_name,
    'signoff_status_updated',
    'Runtime access review signoff status updated to ' || p_signoff_status,
    p_actor_user_id
  );

  return p_signoff_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_runtime_action_review_status"("p_action_review_id" "uuid", "p_review_status" "text", "p_review_notes" "text", "p_actor_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
declare
  v_action_name text;
begin
  perform public.patch45_service_role_required();

  update public.runtime_action_reviews
  set review_status = p_review_status,
      review_notes = p_review_notes,
      reviewed_by = p_actor_user_id,
      reviewed_at = now()
  where id = p_action_review_id
  returning action_name into v_action_name;

  perform public.record_runtime_action_review_event(p_action_review_id, v_action_name, 'review_status_updated', 'Runtime action review status updated to ' || p_review_status, p_actor_user_id);
  return p_action_review_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."update_staging_migration_evidence_run_status"("p_run_id" "uuid", "p_run_status" "text", "p_migration_count" integer DEFAULT NULL::integer, "p_migrations_replayed" boolean DEFAULT false, "p_persona_sql_executed" boolean DEFAULT false, "p_rls_check_passed" boolean DEFAULT false, "p_function_check_passed" boolean DEFAULT false, "p_view_check_passed" boolean DEFAULT false, "p_restore_dryrun_passed" boolean DEFAULT false, "p_failure_count" integer DEFAULT 0, "p_evidence_path" "text" DEFAULT NULL::"text", "p_run_notes" "text" DEFAULT NULL::"text", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  perform public.patch47_service_role_required();

  if p_run_status not in ('pending', 'running', 'passed', 'failed', 'blocked', 'evidence_required') then
    raise exception 'Invalid staging evidence run status: %', p_run_status;
  end if;

  if p_run_status = 'passed'
     and not (
       coalesce(p_migrations_replayed, false)
       and coalesce(p_persona_sql_executed, false)
       and coalesce(p_rls_check_passed, false)
       and coalesce(p_function_check_passed, false)
       and coalesce(p_view_check_passed, false)
       and coalesce(p_restore_dryrun_passed, false)
       and coalesce(p_failure_count, 0) = 0
       and nullif(coalesce(p_evidence_path, ''), '') is not null
     ) then
    raise exception 'Passed staging evidence requires migration replay, persona SQL, security checks, restore dry-run, zero failures, and evidence path.';
  end if;

  update public.staging_migration_evidence_runs
  set
    run_status = p_run_status,
    migration_count = p_migration_count,
    migrations_replayed = coalesce(p_migrations_replayed, false),
    persona_sql_executed = coalesce(p_persona_sql_executed, false),
    rls_check_passed = coalesce(p_rls_check_passed, false),
    function_check_passed = coalesce(p_function_check_passed, false),
    view_check_passed = coalesce(p_view_check_passed, false),
    restore_dryrun_passed = coalesce(p_restore_dryrun_passed, false),
    failure_count = coalesce(p_failure_count, 0),
    evidence_path = coalesce(p_evidence_path, evidence_path),
    run_notes = coalesce(p_run_notes, run_notes),
    completed_at = case when p_run_status in ('passed', 'failed', 'blocked', 'evidence_required') then now() else completed_at end
  where id = p_run_id;

  if not found then
    raise exception 'Staging migration evidence run not found: %', p_run_id;
  end if;

  perform public.record_staging_migration_evidence_event(
    p_run_id,
    'run_status_updated',
    'Staging migration/persona evidence run status updated to ' || p_run_status,
    p_evidence_path,
    p_actor_user_id
  );

  return p_run_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v35_attach_updated_at_if_exists"("target_table" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  execute format('drop trigger if exists trg_%I_updated_at on %I', target_table, target_table);
  execute format('create trigger trg_%I_updated_at before update on %I for each row execute function v35_set_updated_at()', target_table, target_table);
exception when undefined_table then
  null;
end;
$$;

COMMENT ON FUNCTION "public"."v35_attach_updated_at_if_exists"("target_table" "text") IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."v35_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."v35_set_updated_at"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."v58_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'public', 'extensions', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

COMMENT ON FUNCTION "public"."v58_touch_updated_at"() IS 'Gate 9R category D: internal trigger/administrative helper; SECURITY INVOKER; fixed search_path; direct browser and service-role EXECUTE denied.';

CREATE OR REPLACE FUNCTION "public"."v64_touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v72_execute_privileged_action"("p_actor_id" "uuid", "p_action" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_result uuid;
  v_target_org uuid;
  v_target_role public.app_role;
  v_target_user uuid;
  v_actor_org uuid;
  v_actor_is_super_admin boolean;
  v_actor_can_manage_roles boolean;
  v_sections text[];
begin
  if auth.role() <> 'service_role' then
    raise exception 'V72_BRIDGE_SERVICE_ROLE_REQUIRED';
  end if;

  if p_actor_id is null or not exists (
    select 1 from public.profiles
    where id = p_actor_id and is_active = true
  ) then
    raise exception 'V72_BRIDGE_ACTIVE_ACTOR_REQUIRED';
  end if;

  if p_action not in (
    'create_board_pack_snapshot',
    'acknowledge_escalation_event',
    'resolve_escalation_event',
    'assign_user_role',
    'deactivate_user_role',
    'update_ovr_workflow',
    'create_ovr_corrective_action_project'
  ) then
    raise exception 'V72_BRIDGE_ACTION_NOT_ALLOWED: %', p_action;
  end if;

  select organization_id into v_actor_org
  from public.profiles
  where id = p_actor_id;

  select exists (
    select 1 from public.user_roles
    where user_id = p_actor_id
      and is_active = true
      and role = 'super_admin'
  ) into v_actor_is_super_admin;

  select exists (
    select 1 from public.user_roles
    where user_id = p_actor_id
      and is_active = true
      and role in ('super_admin', 'executive', 'governance_admin')
  ) into v_actor_can_manage_roles;

  -- Existing workflow functions use auth.uid(). Set it only after validating
  -- that this dispatcher was called with the service role.
  perform set_config('request.jwt.claim.sub', p_actor_id::text, true);
  perform set_config('request.jwt.claim.role', 'authenticated', true);

  if p_action = 'create_board_pack_snapshot' then
    v_target_org := nullif(p_payload->>'organization_id', '')::uuid;
    if v_target_org is null then
      raise exception 'V72_BOARD_PACK_ORGANIZATION_REQUIRED';
    end if;
    if not exists (
      select 1
      from public.user_roles ur
      where ur.user_id = p_actor_id
        and ur.is_active = true
        and ur.role in (
          'super_admin', 'executive', 'governance_admin',
          'auditor', 'compliance_officer'
        )
        and (
          ur.organization_id is null
          or ur.organization_id = v_target_org
          or v_actor_org = v_target_org
        )
    ) then
      raise exception 'V72_BOARD_PACK_NOT_AUTHORIZED';
    end if;

    select coalesce(array_agg(value), array[]::text[])
    into v_sections
    from jsonb_array_elements_text(
      coalesce(
        p_payload->'sections',
        '["summary","department_scorecards","risks","ovr","audit","compliance","backup"]'::jsonb
      )
    ) as section(value);

    v_result := public.create_board_pack_snapshot(
      v_target_org,
      coalesce(nullif(p_payload->>'title', ''), 'Executive Board Pack'),
      nullif(p_payload->>'period_start', '')::date,
      nullif(p_payload->>'period_end', '')::date,
      v_sections
    );
    return jsonb_build_object('id', v_result);
  end if;

  if p_action in ('acknowledge_escalation_event', 'resolve_escalation_event') then
    select organization_id into v_target_org
    from public.escalation_events
    where id = nullif(p_payload->>'event_id', '')::uuid;

    if v_target_org is null then
      raise exception 'V72_ESCALATION_NOT_FOUND';
    end if;
    if not exists (
      select 1
      from public.escalation_events event
      where event.id = (p_payload->>'event_id')::uuid
        and (
          event.owner_id = p_actor_id
          or exists (
            select 1 from public.user_roles ur
            where ur.user_id = p_actor_id
              and ur.is_active = true
              and ur.role in (
                'super_admin', 'executive', 'governance_admin',
                'auditor', 'compliance_officer'
              )
              and (
                ur.organization_id is null
                or ur.organization_id = event.organization_id
                or v_actor_org = event.organization_id
              )
          )
        )
    ) then
      raise exception 'V72_ESCALATION_NOT_AUTHORIZED';
    end if;

    if p_action = 'acknowledge_escalation_event' then
      perform public.acknowledge_escalation_event(
        (p_payload->>'event_id')::uuid,
        nullif(p_payload->>'note', '')
      );
    else
      perform public.resolve_escalation_event(
        (p_payload->>'event_id')::uuid,
        nullif(p_payload->>'note', '')
      );
    end if;
    return jsonb_build_object('updated', true);
  end if;

  if p_action = 'assign_user_role' then
    v_target_user := nullif(p_payload->>'user_id', '')::uuid;
    v_target_role := nullif(p_payload->>'role', '')::public.app_role;
    select organization_id into v_target_org
    from public.profiles
    where id = v_target_user and is_active = true;

    if not v_actor_can_manage_roles then
      raise exception 'V72_ROLE_ADMIN_NOT_AUTHORIZED';
    end if;
    if v_target_org is null then
      raise exception 'V72_ROLE_TARGET_NOT_FOUND';
    end if;
    if v_actor_org is distinct from v_target_org and not exists (
      select 1 from public.user_roles
      where user_id = p_actor_id
        and is_active = true
        and role = 'super_admin'
        and organization_id is null
    ) then
      raise exception 'V72_ROLE_ADMIN_CROSS_ORG_DENIED';
    end if;
    if v_target_role in ('super_admin', 'executive', 'governance_admin')
       and not v_actor_is_super_admin then
      raise exception 'V72_PRIVILEGED_ROLE_REQUIRES_SUPER_ADMIN';
    end if;

    v_result := public.assign_user_role(
      v_target_user,
      v_target_role,
      coalesce(nullif(p_payload->>'scope', '')::public.access_scope, 'assigned_only'),
      coalesce(nullif(p_payload->>'organization_id', '')::uuid, v_target_org),
      nullif(p_payload->>'division_id', '')::uuid,
      nullif(p_payload->>'department_id', '')::uuid,
      nullif(p_payload->>'unit_id', '')::uuid,
      nullif(p_payload->>'reason', '')
    );
    return jsonb_build_object('id', v_result);
  end if;

  if p_action = 'deactivate_user_role' then
    select ur.organization_id, ur.role, ur.user_id
    into v_target_org, v_target_role, v_target_user
    from public.user_roles ur
    where ur.id = nullif(p_payload->>'user_role_id', '')::uuid
      and ur.is_active = true;

    if not v_actor_can_manage_roles then
      raise exception 'V72_ROLE_ADMIN_NOT_AUTHORIZED';
    end if;
    if v_target_user is null then
      raise exception 'V72_ROLE_ASSIGNMENT_NOT_FOUND';
    end if;
    if v_actor_org is distinct from v_target_org and not exists (
      select 1 from public.user_roles
      where user_id = p_actor_id
        and is_active = true
        and role = 'super_admin'
        and organization_id is null
    ) then
      raise exception 'V72_ROLE_ADMIN_CROSS_ORG_DENIED';
    end if;
    if v_target_role in ('super_admin', 'executive', 'governance_admin')
       and not v_actor_is_super_admin then
      raise exception 'V72_PRIVILEGED_ROLE_REQUIRES_SUPER_ADMIN';
    end if;
    if v_target_user = p_actor_id then
      raise exception 'V72_SELF_ROLE_DEACTIVATION_DENIED';
    end if;
    if v_target_role = 'super_admin' and (
      select count(*)
      from public.user_roles
      where is_active = true
        and role = 'super_admin'
        and organization_id is not distinct from v_target_org
    ) <= 1 then
      raise exception 'V72_LAST_SUPER_ADMIN_DEACTIVATION_DENIED';
    end if;

    perform public.deactivate_user_role(
      (p_payload->>'user_role_id')::uuid,
      nullif(p_payload->>'reason', '')
    );
    return jsonb_build_object('updated', true);
  end if;

  if p_action in ('update_ovr_workflow', 'create_ovr_corrective_action_project') then
    select organization_id into v_target_org
    from public.ovr_reports
    where id = nullif(p_payload->>'ovr_report_id', '')::uuid;

    if v_target_org is null then
      raise exception 'V72_OVR_NOT_FOUND';
    end if;
    if v_actor_org is distinct from v_target_org and not v_actor_is_super_admin then
      raise exception 'V72_OVR_CROSS_ORG_DENIED';
    end if;

    if p_action = 'update_ovr_workflow' then
      perform public.update_ovr_workflow(
        (p_payload->>'ovr_report_id')::uuid,
        p_payload->>'next_status',
        nullif(p_payload->>'note', ''),
        nullif(p_payload->>'supervisor_investigation', ''),
        nullif(p_payload->>'corrective_action', ''),
        nullif(p_payload->>'quality_manager_comments', ''),
        nullif(p_payload->>'confirmed_severity_level', '')::public.ovr_severity_level,
        nullif(p_payload->>'corrective_action_due_date', '')::date
      );
      return jsonb_build_object('updated', true);
    end if;

    v_result := public.create_ovr_corrective_action_project(
      (p_payload->>'ovr_report_id')::uuid
    );
    return jsonb_build_object('id', v_result);
  end if;

  raise exception 'V72_BRIDGE_UNREACHABLE_ACTION';
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v98_create_department"("p_actor_id" "uuid", "p_name_en" "text", "p_name_ar" "text" DEFAULT NULL::"text", "p_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor_org uuid;
  v_department_id uuid;
  v_name_en text := nullif(trim(p_name_en), '');
  v_name_ar text := nullif(trim(p_name_ar), '');
  v_code text := upper(nullif(trim(p_code), ''));
begin
  if auth.role() <> 'service_role' then
    raise exception 'V98_DEPARTMENT_SERVICE_ROLE_REQUIRED';
  end if;

  select p.organization_id
    into v_actor_org
  from public.profiles p
  where p.id = p_actor_id
    and p.is_active = true;

  if v_actor_org is null then
    raise exception 'V98_ACTIVE_ACTOR_ORGANIZATION_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role in ('super_admin', 'governance_admin')
      and (
        ur.organization_id is null
        or ur.organization_id = v_actor_org
      )
  ) then
    raise exception 'V98_DEPARTMENT_ADMIN_NOT_AUTHORIZED';
  end if;

  if v_name_en is null or length(v_name_en) > 160 then
    raise exception 'V98_DEPARTMENT_NAME_INVALID';
  end if;

  if v_name_ar is not null and length(v_name_ar) > 160 then
    raise exception 'V98_DEPARTMENT_ARABIC_NAME_INVALID';
  end if;

  if v_code is null
     or length(v_code) < 2
     or length(v_code) > 24
     or v_code !~ '^[A-Z0-9_-]+$' then
    raise exception 'V98_DEPARTMENT_CODE_INVALID';
  end if;

  if exists (
    select 1
    from public.departments d
    where d.organization_id = v_actor_org
      and d.is_active = true
      and upper(trim(d.code)) = v_code
  ) then
    raise exception 'V98_DEPARTMENT_CODE_EXISTS: %', v_code;
  end if;

  if exists (
    select 1
    from public.departments d
    where d.organization_id = v_actor_org
      and d.is_active = true
      and lower(trim(d.name_en)) = lower(v_name_en)
  ) then
    raise exception 'V98_DEPARTMENT_NAME_EXISTS: %', v_name_en;
  end if;

  select d.id
    into v_department_id
  from public.departments d
  where d.organization_id = v_actor_org
    and d.is_active = false
    and (
      upper(trim(d.code)) = v_code
      or lower(trim(d.name_en)) = lower(v_name_en)
    )
  order by
    case when upper(trim(d.code)) = v_code then 0 else 1 end,
    d.created_at,
    d.id
  limit 1;

  if v_department_id is null then
    insert into public.departments (
      organization_id,
      name_en,
      name_ar,
      code,
      is_active
    )
    values (
      v_actor_org,
      v_name_en,
      v_name_ar,
      v_code,
      true
    )
    returning id into v_department_id;
  else
    update public.departments
    set name_en = v_name_en,
        name_ar = v_name_ar,
        code = v_code,
        is_active = true,
        updated_at = now()
    where id = v_department_id;
  end if;

  return jsonb_build_object(
    'id', v_department_id,
    'organization_id', v_actor_org,
    'name_en', v_name_en,
    'name_ar', v_name_ar,
    'code', v_code
  );
end;
$_$;

CREATE OR REPLACE FUNCTION "public"."v98_finalize_created_user"("p_actor_id" "uuid", "p_user_id" "uuid", "p_email" "text", "p_full_name_en" "text", "p_full_name_ar" "text" DEFAULT NULL::"text", "p_department_id" "uuid" DEFAULT NULL::"uuid", "p_role" "public"."app_role" DEFAULT 'employee'::"public"."app_role", "p_scope" "public"."access_scope" DEFAULT 'assigned_only'::"public"."access_scope") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $_$
declare
  v_actor_org uuid;
  v_role_id uuid;
  v_email text := lower(nullif(trim(p_email), ''));
  v_full_name_en text := nullif(trim(p_full_name_en), '');
  v_full_name_ar text := nullif(trim(p_full_name_ar), '');
begin
  if auth.role() <> 'service_role' then
    raise exception 'V98_USER_SERVICE_ROLE_REQUIRED';
  end if;

  select p.organization_id
    into v_actor_org
  from public.profiles p
  where p.id = p_actor_id
    and p.is_active = true;

  if v_actor_org is null then
    raise exception 'V98_ACTIVE_ACTOR_ORGANIZATION_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role = 'super_admin'
      and (
        ur.organization_id is null
        or ur.organization_id = v_actor_org
      )
  ) then
    raise exception 'V98_USER_CREATION_REQUIRES_SUPER_ADMIN';
  end if;

  if p_user_id is null or not exists (
    select 1
    from auth.users u
    where u.id = p_user_id
      and lower(u.email) = v_email
  ) then
    raise exception 'V98_AUTH_USER_MISSING_OR_EMAIL_MISMATCH';
  end if;

  if v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'V98_USER_EMAIL_INVALID';
  end if;

  if v_full_name_en is null or length(v_full_name_en) > 180 then
    raise exception 'V98_USER_NAME_INVALID';
  end if;

  if v_full_name_ar is not null and length(v_full_name_ar) > 180 then
    raise exception 'V98_USER_ARABIC_NAME_INVALID';
  end if;

  if p_department_id is not null and not exists (
    select 1
    from public.departments d
    where d.id = p_department_id
      and d.organization_id = v_actor_org
      and d.is_active = true
  ) then
    raise exception 'V98_USER_DEPARTMENT_INVALID';
  end if;

  if p_scope = 'department' and p_department_id is null then
    raise exception 'V98_DEPARTMENT_SCOPE_REQUIRES_DEPARTMENT';
  end if;

  if p_scope in ('division', 'unit') then
    raise exception 'V98_USER_SCOPE_REQUIRES_DEDICATED_STRUCTURE_SELECTION';
  end if;

  if exists (
    select 1
    from public.profiles p
    where lower(p.email) = v_email
      and p.id <> p_user_id
  ) then
    raise exception 'V98_PROFILE_EMAIL_ALREADY_IN_USE';
  end if;

  insert into public.profiles (
    id,
    organization_id,
    full_name_en,
    full_name_ar,
    email,
    department_id,
    is_active
  )
  values (
    p_user_id,
    v_actor_org,
    v_full_name_en,
    v_full_name_ar,
    v_email,
    p_department_id,
    true
  )
  on conflict (id) do update
  set organization_id = excluded.organization_id,
      full_name_en = excluded.full_name_en,
      full_name_ar = excluded.full_name_ar,
      email = excluded.email,
      department_id = excluded.department_id,
      is_active = true,
      updated_at = now();

  perform set_config('request.jwt.claim.sub', p_actor_id::text, true);
  perform set_config('request.jwt.claim.role', 'authenticated', true);

  v_role_id := public.assign_user_role(
    p_user_id,
    p_role,
    p_scope,
    v_actor_org,
    null,
    case when p_scope = 'department' then p_department_id else null end,
    null,
    'Created through v9.8 secure admin user setup'
  );

  return jsonb_build_object(
    'id', p_user_id,
    'profile_id', p_user_id,
    'role_id', v_role_id,
    'organization_id', v_actor_org,
    'department_id', p_department_id,
    'role', p_role,
    'scope', p_scope
  );
end;
$_$;

CREATE OR REPLACE FUNCTION "public"."v98_initialize_ovr_submission"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status = 'submitted' and new.supervisor_due_date is null then
    new.supervisor_due_date := current_date + 1;
  end if;

  -- Browser-authenticated reporters submit facts only. Workflow decisions,
  -- referrals, verdicts, and closure fields are server-bridge controlled.
  if auth.role() = 'authenticated' then
    new.evidence_required := true;
    new.corrective_action_required := false;
    new.linked_project_id := null;
    new.supervisor_investigation := null;
    new.quality_manager_comments := null;
    new.referred_to_person := null;
    new.referred_to_department := null;
    new.referred_to_date := null;
    new.referred_department_id := null;
    new.referred_user_id := null;
    new.final_verdict := null;
    new.final_verdict_at := null;
    new.final_severity_level := null;
    new.occurrence_confirmed_by_quality := false;
    new.reporter_response := null;
    new.reporter_response_at := null;
    new.dispute_reason := null;
    new.cross_department_notified_at := null;
    new.closed_by := null;
    new.closed_at := null;
    new.quality_closed_by := null;
    new.quality_closed_at := null;
  end if;

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v98_notify_ovr_submission"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if new.status <> 'submitted' then
    return new;
  end if;

  insert into public.notifications (
    organization_id,
    user_id,
    title,
    body,
    link_path
  )
  select
    new.organization_id,
    ur.user_id,
    'OVR manager review required',
    coalesce(new.ovr_number, 'OVR') || ' requires manager review within 24 hours.',
    '/ovr'
  from public.user_roles ur
  where ur.organization_id is not distinct from new.organization_id
    and ur.role = 'department_manager'
    and ur.is_active = true
    and (
      ur.scope = 'global'
      or (
        ur.scope = 'department'
        and ur.department_id is not distinct from new.department_id
      )
    )
    and not exists (
      select 1
      from public.notifications n
      where n.user_id = ur.user_id
        and n.title = 'OVR manager review required'
        and n.body like coalesce(new.ovr_number, 'OVR') || '%'
    );

  return new;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v98_update_ovr_workflow"("p_actor_id" "uuid", "p_ovr_report_id" "uuid", "p_next_status" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_ovr public.ovr_reports%rowtype;
  v_actor_org uuid;
  v_actor_department uuid;
  v_actor_is_quality boolean := false;
  v_actor_is_auditor boolean := false;
  v_actor_is_manager boolean := false;
  v_actor_is_referred_manager boolean := false;
  v_actor_is_reporter boolean := false;
  v_actor_is_referred boolean := false;
  v_note text := nullif(trim(p_payload->>'note'), '');
  v_supervisor_investigation text := nullif(trim(p_payload->>'supervisor_investigation'), '');
  v_corrective_action text := nullif(trim(p_payload->>'corrective_action'), '');
  v_quality_comments text := nullif(trim(p_payload->>'quality_manager_comments'), '');
  v_referred_response text := nullif(trim(p_payload->>'referred_response'), '');
  v_final_verdict text := nullif(trim(p_payload->>'final_verdict'), '');
  v_referred_department_id uuid := nullif(p_payload->>'referred_department_id', '')::uuid;
  v_referred_user_id uuid := nullif(p_payload->>'referred_user_id', '')::uuid;
  v_confirmed_severity public.ovr_severity_level :=
    nullif(p_payload->>'confirmed_severity_level', '')::public.ovr_severity_level;
  v_corrective_due date := nullif(p_payload->>'corrective_action_due_date', '')::date;
begin
  if auth.role() <> 'service_role' then
    raise exception 'V98_OVR_SERVICE_ROLE_REQUIRED';
  end if;

  select *
    into v_ovr
  from public.ovr_reports
  where id = p_ovr_report_id
  for update;

  if not found then
    raise exception 'V98_OVR_NOT_FOUND';
  end if;

  select organization_id, department_id
    into v_actor_org, v_actor_department
  from public.profiles
  where id = p_actor_id
    and is_active = true;

  if v_actor_org is null then
    raise exception 'V98_OVR_ACTIVE_ACTOR_REQUIRED';
  end if;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role in ('super_admin', 'governance_admin', 'compliance_officer')
      and (
        ur.organization_id is null
        or ur.organization_id is not distinct from v_ovr.organization_id
      )
  ) into v_actor_is_quality;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role = 'auditor'
      and (
        ur.organization_id is null
        or ur.organization_id is not distinct from v_ovr.organization_id
      )
  ) into v_actor_is_auditor;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role = 'department_manager'
      and ur.organization_id is not distinct from v_ovr.organization_id
      and (
        ur.scope = 'global'
        or (
          ur.scope = 'department'
          and ur.department_id is not distinct from v_ovr.department_id
        )
      )
  ) into v_actor_is_manager;

  select exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role = 'department_manager'
      and ur.organization_id is not distinct from v_ovr.organization_id
      and (
        ur.scope = 'global'
        or (
          ur.scope = 'department'
          and ur.department_id is not distinct from v_ovr.referred_department_id
        )
      )
  ) into v_actor_is_referred_manager;

  v_actor_is_reporter := v_ovr.reported_by = p_actor_id;
  v_actor_is_referred := v_ovr.referred_user_id = p_actor_id or v_actor_is_referred_manager;

  if v_actor_org is distinct from v_ovr.organization_id and not v_actor_is_quality then
    raise exception 'V98_OVR_CROSS_ORGANIZATION_DENIED';
  end if;

  if v_actor_is_auditor and not v_actor_is_quality then
    raise exception 'V98_OVR_AUDITOR_READ_ONLY';
  end if;

  if p_next_status = 'manager_review' then
    if v_ovr.status not in ('submitted', 'reopened') then
      raise exception 'V98_OVR_INVALID_TRANSITION: % -> manager_review', v_ovr.status;
    end if;
    if not (v_actor_is_manager or v_actor_is_quality) then
      raise exception 'V98_OVR_MANAGER_REVIEW_NOT_AUTHORIZED';
    end if;
    if coalesce(v_supervisor_investigation, nullif(trim(v_ovr.supervisor_investigation), '')) is null then
      raise exception 'V98_OVR_MANAGER_INVESTIGATION_REQUIRED';
    end if;

    update public.ovr_reports
    set status = 'manager_review',
        supervisor_id = p_actor_id,
        supervisor_investigation = coalesce(v_supervisor_investigation, supervisor_investigation),
        supervisor_action_taken = coalesce(v_corrective_action, supervisor_action_taken),
        manager_reviewed_at = now(),
        reviewed_at = now(),
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

    insert into public.notifications (organization_id, user_id, title, body, link_path)
    select
      v_ovr.organization_id,
      ur.user_id,
      'OVR Quality validation required',
      coalesce(v_ovr.ovr_number, 'OVR') || ' completed manager review and requires Quality validation.',
      '/ovr'
    from public.user_roles ur
    where ur.is_active = true
      and ur.role in ('super_admin', 'governance_admin', 'compliance_officer')
      and (
        ur.organization_id is null
        or ur.organization_id is not distinct from v_ovr.organization_id
      );

  elsif p_next_status = 'quality_validation' then
    if v_ovr.status <> 'manager_review' then
      raise exception 'V98_OVR_INVALID_TRANSITION: % -> quality_validation', v_ovr.status;
    end if;
    if not v_actor_is_quality then
      raise exception 'V98_OVR_QUALITY_VALIDATION_NOT_AUTHORIZED';
    end if;
    if v_quality_comments is null then
      raise exception 'V98_OVR_QUALITY_VALIDATION_NOTE_REQUIRED';
    end if;

    update public.ovr_reports
    set status = 'quality_validation',
        quality_reviewer_id = p_actor_id,
        quality_manager_id = p_actor_id,
        quality_manager_comments = v_quality_comments,
        quality_review_notes = v_quality_comments,
        occurrence_confirmed_by_quality = true,
        severity_level = coalesce(v_confirmed_severity, severity_level),
        final_severity_level = coalesce(v_confirmed_severity, final_severity_level),
        quality_validated_at = now(),
        reviewed_at = now(),
        quality_due_date = current_date + 2,
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

  elsif p_next_status = 'referred_party_response' then
    if v_ovr.status <> 'quality_validation' then
      raise exception 'V98_OVR_INVALID_TRANSITION: % -> referred_party_response', v_ovr.status;
    end if;
    if not v_actor_is_quality then
      raise exception 'V98_OVR_REFERRAL_NOT_AUTHORIZED';
    end if;
    if v_ovr.quality_validated_at is null then
      raise exception 'V98_OVR_QUALITY_VALIDATION_REQUIRED_BEFORE_REFERRAL';
    end if;
    if v_referred_department_id is null and v_referred_user_id is null then
      raise exception 'V98_OVR_REFERRAL_TARGET_REQUIRED';
    end if;
    if v_referred_department_id is not null and not exists (
      select 1
      from public.departments d
      where d.id = v_referred_department_id
        and d.organization_id = v_ovr.organization_id
        and d.is_active = true
    ) then
      raise exception 'V98_OVR_REFERRAL_DEPARTMENT_INVALID';
    end if;
    if v_referred_user_id is not null and not exists (
      select 1
      from public.profiles p
      where p.id = v_referred_user_id
        and p.organization_id = v_ovr.organization_id
        and p.is_active = true
        and (
          v_referred_department_id is null
          or p.department_id is not distinct from v_referred_department_id
        )
    ) then
      raise exception 'V98_OVR_REFERRAL_USER_INVALID';
    end if;

    update public.ovr_reports
    set status = 'referred_party_response',
        referred_department_id = v_referred_department_id,
        referred_user_id = v_referred_user_id,
        referred_to_department = (
          select d.name_en from public.departments d where d.id = v_referred_department_id
        ),
        referred_to_person = (
          select p.full_name_en from public.profiles p where p.id = v_referred_user_id
        ),
        referred_to_date = current_date,
        cross_department_notified_at = now(),
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

    insert into public.notifications (organization_id, user_id, title, body, link_path)
    select distinct
      v_ovr.organization_id,
      target.user_id,
      'OVR referral requires response',
      coalesce(v_ovr.ovr_number, 'OVR') || ' was validated by Quality and referred for a controlled response.',
      '/ovr'
    from (
      select v_referred_user_id as user_id
      where v_referred_user_id is not null
      union
      select ur.user_id
      from public.user_roles ur
      where ur.is_active = true
        and ur.role = 'department_manager'
        and ur.organization_id is not distinct from v_ovr.organization_id
        and ur.department_id is not distinct from v_referred_department_id
    ) target
    where target.user_id is not null;

  elsif p_next_status = 'quality_final_review' then
    if v_ovr.status = 'referred_party_response' and v_actor_is_referred then
      if coalesce(v_referred_response, v_corrective_action) is null then
        raise exception 'V98_OVR_REFERRED_RESPONSE_REQUIRED';
      end if;

      update public.ovr_reports
      set status = 'quality_final_review',
          referred_response = coalesce(v_referred_response, v_corrective_action),
          corrective_action = coalesce(v_corrective_action, corrective_action),
          referred_responded_at = now(),
          corrective_action_due_date = coalesce(v_corrective_due, corrective_action_due_date),
          updated_by = p_actor_id,
          updated_at = now()
      where id = p_ovr_report_id;

    elsif v_ovr.status in ('quality_validation', 'quality_final_review', 'reopened', 'escalated')
          and v_actor_is_quality then
      if v_final_verdict is null then
        raise exception 'V98_OVR_FINAL_VERDICT_REQUIRED';
      end if;
      if v_quality_comments is null
         and coalesce(nullif(trim(v_ovr.quality_manager_comments), ''), '') = '' then
        raise exception 'V98_OVR_FINAL_QUALITY_COMMENT_REQUIRED';
      end if;

      update public.ovr_reports
      set status = 'quality_final_review',
          quality_reviewer_id = p_actor_id,
          quality_manager_id = p_actor_id,
          quality_manager_comments = coalesce(v_quality_comments, quality_manager_comments),
          final_verdict = v_final_verdict,
          final_quality_classification = v_final_verdict,
          final_verdict_at = now(),
          quality_closed_by = p_actor_id,
          severity_level = coalesce(v_confirmed_severity, severity_level),
          final_severity_level = coalesce(v_confirmed_severity, final_severity_level, severity_level),
          corrective_action = coalesce(v_corrective_action, corrective_action),
          corrective_action_due_date = coalesce(v_corrective_due, corrective_action_due_date),
          closure_ready_at = now(),
          updated_by = p_actor_id,
          updated_at = now()
      where id = p_ovr_report_id;

      insert into public.notifications (organization_id, user_id, title, body, link_path)
      values (
        v_ovr.organization_id,
        v_ovr.reported_by,
        'OVR final verdict ready',
        coalesce(v_ovr.ovr_number, 'OVR') || ' has a final Quality verdict. Accept or dispute the outcome.',
        '/ovr'
      );
    else
      raise exception 'V98_OVR_FINAL_REVIEW_NOT_AUTHORIZED_OR_INVALID';
    end if;

  elsif p_next_status = 'disputed' then
    if v_ovr.status <> 'quality_final_review' or not v_actor_is_reporter then
      raise exception 'V98_OVR_DISPUTE_NOT_AUTHORIZED_OR_INVALID';
    end if;
    if coalesce(trim(v_ovr.final_verdict), '') = '' then
      raise exception 'V98_OVR_FINAL_VERDICT_REQUIRED_BEFORE_DISPUTE';
    end if;
    if v_note is null then
      raise exception 'V98_OVR_DISPUTE_REASON_REQUIRED';
    end if;

    update public.ovr_reports
    set status = 'disputed',
        reporter_response = 'disputed',
        reporter_response_at = now(),
        dispute_reason = v_note,
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

  elsif p_next_status = 'reopened' then
    if v_ovr.status <> 'disputed' or not v_actor_is_quality then
      raise exception 'V98_OVR_REOPEN_NOT_AUTHORIZED_OR_INVALID';
    end if;

    update public.ovr_reports
    set status = 'reopened',
        reopened_at = now(),
        final_verdict = null,
        final_verdict_at = null,
        reporter_response = null,
        reporter_response_at = null,
        closure_ready_at = null,
        quality_closed_by = null,
        quality_closed_at = null,
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

  elsif p_next_status = 'escalated' then
    if v_ovr.status in ('closed', 'cancelled', 'rejected') then
      raise exception 'V98_OVR_CANNOT_ESCALATE_FINAL_STATUS';
    end if;
    if not (v_actor_is_quality or v_actor_is_manager or v_actor_is_referred_manager) then
      raise exception 'V98_OVR_ESCALATION_NOT_AUTHORIZED';
    end if;
    if v_note is null then
      raise exception 'V98_OVR_ESCALATION_REASON_REQUIRED';
    end if;

    update public.ovr_reports
    set status = 'escalated',
        delay_reason = v_note,
        escalated_at = now(),
        executive_visible = true,
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

  elsif p_next_status = 'rejected' then
    if not v_actor_is_quality then
      raise exception 'V98_OVR_REJECTION_NOT_AUTHORIZED';
    end if;
    if v_note is null then
      raise exception 'V98_OVR_REJECTION_REASON_REQUIRED';
    end if;

    update public.ovr_reports
    set status = 'rejected',
        rejection_reason = v_note,
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

  elsif p_next_status = 'closed' then
    if v_ovr.status <> 'quality_final_review' or not v_actor_is_reporter then
      raise exception 'V98_OVR_REPORTER_ACCEPTANCE_REQUIRED';
    end if;
    if coalesce(trim(v_ovr.final_verdict), '') = '' or v_ovr.final_verdict_at is null then
      raise exception 'V98_OVR_FINAL_VERDICT_REQUIRED_BEFORE_CLOSURE';
    end if;
    if not public.can_close_ovr(p_ovr_report_id) then
      raise exception 'V98_OVR_ACCEPTED_EVIDENCE_OR_CLOSED_ACTION_REQUIRED';
    end if;

    update public.ovr_reports
    set status = 'closed',
        reporter_response = 'accepted',
        reporter_response_at = now(),
        closure_summary = coalesce(v_note, final_verdict),
        quality_closed_at = now(),
        closed_by = p_actor_id,
        closed_at = now(),
        updated_by = p_actor_id,
        updated_at = now()
    where id = p_ovr_report_id;

  else
    raise exception 'V98_OVR_UNSUPPORTED_STATUS: %', p_next_status;
  end if;

  insert into public.comments (
    organization_id,
    ovr_report_id,
    body,
    created_by
  )
  values (
    v_ovr.organization_id,
    p_ovr_report_id,
    concat(
      'OVR workflow changed from ',
      v_ovr.status::text,
      ' to ',
      p_next_status,
      case when v_note is not null then ': ' || v_note else '' end
    ),
    p_actor_id
  );

  return (
    select jsonb_build_object(
      'id', o.id,
      'status', o.status,
      'supervisor_due_date', o.supervisor_due_date,
      'quality_validated_at', o.quality_validated_at,
      'cross_department_notified_at', o.cross_department_notified_at,
      'final_verdict', o.final_verdict,
      'reporter_response', o.reporter_response,
      'closed_at', o.closed_at
    )
    from public.ovr_reports o
    where o.id = p_ovr_report_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v99_assert_scenario_lab_actor"("p_actor_id" "uuid", "p_confirmation" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_organization_id uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'V99_SERVICE_ROLE_REQUIRED';
  end if;

  if p_confirmation is distinct from 'V99_SCENARIO_LAB' then
    raise exception 'V99_EXACT_CONFIRMATION_REQUIRED';
  end if;

  select p.organization_id
    into v_organization_id
  from public.profiles p
  where p.id = p_actor_id
    and p.is_active = true;

  if v_organization_id is null then
    raise exception 'V99_ACTIVE_ACTOR_REQUIRED';
  end if;

  if not exists (
    select 1
    from public.user_roles ur
    where ur.user_id = p_actor_id
      and ur.is_active = true
      and ur.role in ('super_admin', 'governance_admin')
      and (
        ur.organization_id is null
        or ur.organization_id is not distinct from v_organization_id
      )
  ) then
    raise exception 'V99_SCENARIO_ADMIN_REQUIRED';
  end if;

  return v_organization_id;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v99_cleanup_scenarios"("p_actor_id" "uuid", "p_confirmation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_organization_id uuid;
  v_deleted_notifications integer := 0;
  v_deleted_evidence integer := 0;
  v_deleted_controls integer := 0;
  v_deleted_ovrs integer := 0;
  v_deleted_risks integer := 0;
  v_deleted_projects integer := 0;
  v_deleted_roles integer := 0;
  v_deleted_audit_logs integer := 0;
  v_deleted_registry integer := 0;
begin
  perform pg_advisory_xact_lock(hashtext('V99_SCENARIO_LAB'));
  v_organization_id :=
    public.v99_assert_scenario_lab_actor(p_actor_id, p_confirmation);

  delete from public.notifications n
  using public.ovr_reports o, public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'ovr_reports'
    and o.id = r.record_id
    and n.organization_id = v_organization_id
    and o.ovr_number is not null
    and n.body like '%' || o.ovr_number || '%';
  get diagnostics v_deleted_notifications = row_count;

  delete from public.notifications n
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'notifications'
    and n.id = r.record_id;
  get diagnostics v_deleted_registry = row_count;
  v_deleted_notifications := v_deleted_notifications + v_deleted_registry;
  v_deleted_registry := 0;

  delete from public.evidence_files e
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'evidence_files'
    and e.id = r.record_id;
  get diagnostics v_deleted_evidence = row_count;

  delete from public.risk_controls c
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'risk_controls'
    and c.id = r.record_id;
  get diagnostics v_deleted_controls = row_count;

  delete from public.ovr_reports o
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'ovr_reports'
    and o.id = r.record_id;
  get diagnostics v_deleted_ovrs = row_count;

  delete from public.risks risk
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'risks'
    and risk.id = r.record_id;
  get diagnostics v_deleted_risks = row_count;

  delete from public.projects project
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'projects'
    and project.id = r.record_id;
  get diagnostics v_deleted_projects = row_count;

  delete from public.user_roles role_assignment
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and r.record_table = 'user_roles'
    and role_assignment.id = r.record_id;
  get diagnostics v_deleted_roles = row_count;

  delete from public.audit_logs audit
  using public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id
    and audit.record_id = r.record_id;
  get diagnostics v_deleted_audit_logs = row_count;

  delete from public.v99_scenario_lab_records r
  where r.test_dataset_tag = 'V99_SCENARIO_LAB'
    and r.organization_id = v_organization_id;
  get diagnostics v_deleted_registry = row_count;

  return jsonb_build_object(
    'status', 'cleaned',
    'test_dataset_tag', 'V99_SCENARIO_LAB',
    'deleted', jsonb_build_object(
      'notifications', v_deleted_notifications,
      'evidence_files', v_deleted_evidence,
      'risk_controls', v_deleted_controls,
      'ovr_reports', v_deleted_ovrs,
      'risks', v_deleted_risks,
      'projects', v_deleted_projects,
      'temporary_user_roles', v_deleted_roles,
      'audit_logs', v_deleted_audit_logs,
      'registry_rows', v_deleted_registry
    )
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v99_create_ovr_scenario"("p_actor_id" "uuid", "p_organization_id" "uuid", "p_scenario" "text", "p_confirmation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_started_at timestamptz := now();
  v_source_department_id uuid;
  v_referred_department_id uuid;
  v_temporary_role_id uuid;
  v_ovr_id uuid;
  v_ovr_number text;
  v_severity public.ovr_severity_level := 'level_2';
  v_title text;
  v_evidence_id uuid;
begin
  if public.v99_assert_scenario_lab_actor(p_actor_id, p_confirmation)
     is distinct from p_organization_id then
    raise exception 'V99_ACTOR_ORGANIZATION_MISMATCH';
  end if;

  select d.id
    into v_source_department_id
  from public.departments d
  where d.organization_id = p_organization_id
    and d.is_active = true
  order by
    case when upper(trim(d.code)) = 'QUALITY' then 0 else 1 end,
    d.created_at,
    d.id
  limit 1;

  if v_source_department_id is null then
    raise exception 'V99_ACTIVE_DEPARTMENT_REQUIRED';
  end if;

  if p_scenario = 'ovr_high_severity' then
    v_severity := 'sentinel';
  end if;

  case p_scenario
    when 'ovr_same_department' then
      v_title := 'Synthetic same-department operational observation';
    when 'ovr_cross_department' then
      v_title := 'Synthetic cross-department handoff observation';
    when 'ovr_high_severity' then
      v_title := 'Synthetic high-severity escalation drill';
    when 'ovr_returned_clarification' then
      v_title := 'Synthetic report returned for clarification';
    when 'ovr_disputed_reopened' then
      v_title := 'Synthetic disputed and reopened workflow';
    else
      raise exception 'V99_UNSUPPORTED_OVR_SCENARIO: %', p_scenario;
  end case;

  insert into public.ovr_reports (
    organization_id,
    logging_number,
    occurrence_date,
    occurrence_time,
    occurrence_location,
    involved_person_type,
    person_involved_name,
    mrn_or_id_no,
    department_id,
    physical_condition,
    mental_condition,
    pre_occurrence_condition_flags,
    brief_description,
    occurrence_category,
    occurrence_details,
    severity_level,
    corrective_action_required,
    evidence_required,
    status,
    reported_by,
    owner_id,
    created_by,
    updated_by
  )
  values (
    p_organization_id,
    'V99-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10)),
    current_date,
    localtime(0),
    'Synthetic controlled-pilot test location',
    'employee',
    'Synthetic Pilot User - not a patient',
    null,
    v_source_department_id,
    'Synthetic/de-identified test condition only',
    'Synthetic/de-identified test condition only',
    array['alert'],
    '[V99_SCENARIO_LAB] ' || v_title ||
      '. No patient identifiers or confidential OVR narrative.',
    'other',
    jsonb_build_object(
      'test_dataset_tag', 'V99_SCENARIO_LAB',
      'scenario_code', p_scenario,
      'synthetic_only', true,
      'contains_patient_identifiers', false,
      'contains_confidential_ovr_details', false
    ),
    v_severity,
    false,
    true,
    'submitted',
    p_actor_id,
    p_actor_id,
    p_actor_id,
    p_actor_id
  )
  returning id, ovr_number into v_ovr_id, v_ovr_number;

  insert into public.v99_scenario_lab_records (
    test_dataset_tag,
    organization_id,
    scenario_code,
    record_table,
    record_id,
    created_by,
    metadata
  )
  values (
    'V99_SCENARIO_LAB',
    p_organization_id,
    p_scenario,
    'ovr_reports',
    v_ovr_id,
    p_actor_id,
    jsonb_build_object('ovr_number', v_ovr_number)
  )
  on conflict (record_table, record_id) do nothing;

  if p_scenario = 'ovr_returned_clarification' then
    update public.ovr_reports
    set status = 'returned_for_clarification',
        returned_reason = '[V99_SCENARIO_LAB] Synthetic clarification is required.',
        returned_for_clarification_reason =
          '[V99_SCENARIO_LAB] Synthetic clarification is required.',
        updated_by = p_actor_id,
        updated_at = now()
    where id = v_ovr_id;

  elsif p_scenario = 'ovr_same_department' then
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'manager_review',
      jsonb_build_object(
        'supervisor_investigation',
        '[V99_SCENARIO_LAB] Synthetic same-department manager review.'
      )
    );

  elsif p_scenario = 'ovr_high_severity' then
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'manager_review',
      jsonb_build_object(
        'supervisor_investigation',
        '[V99_SCENARIO_LAB] Synthetic high-severity manager review.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_validation',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic Quality validation.',
        'confirmed_severity_level',
        'sentinel'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'escalated',
      jsonb_build_object(
        'note',
        '[V99_SCENARIO_LAB] Synthetic high-severity escalation drill.'
      )
    );

  elsif p_scenario = 'ovr_cross_department' then
    select role_assignment.department_id, role_assignment.id
      into v_referred_department_id, v_temporary_role_id
    from public.user_roles role_assignment
    join public.v99_scenario_lab_records registry
      on registry.record_table = 'user_roles'
     and registry.record_id = role_assignment.id
     and registry.test_dataset_tag = 'V99_SCENARIO_LAB'
    where role_assignment.user_id = p_actor_id
      and role_assignment.organization_id = p_organization_id
      and role_assignment.role = 'department_manager'
      and role_assignment.scope = 'department'
      and role_assignment.is_active = true
      and role_assignment.department_id <> v_source_department_id
    order by role_assignment.assigned_at, role_assignment.id
    limit 1;

    if v_temporary_role_id is null then
      select d.id
        into v_referred_department_id
      from public.departments d
      where d.organization_id = p_organization_id
        and d.is_active = true
        and d.id <> v_source_department_id
        and not exists (
          select 1
          from public.user_roles existing_role
          where existing_role.user_id = p_actor_id
            and existing_role.role = 'department_manager'
            and existing_role.scope = 'department'
            and existing_role.organization_id = p_organization_id
            and existing_role.department_id = d.id
        )
      order by
        case when upper(trim(d.code)) = 'IT' then 0 else 1 end,
        d.created_at,
        d.id
      limit 1;

      if v_referred_department_id is null then
        raise exception 'V99_CROSS_DEPARTMENT_TARGET_REQUIRED';
      end if;

      insert into public.user_roles (
        user_id,
        role,
        scope,
        organization_id,
        department_id,
        is_active,
        assigned_by
      )
      values (
        p_actor_id,
        'department_manager',
        'department',
        p_organization_id,
        v_referred_department_id,
        true,
        p_actor_id
      )
      returning id into v_temporary_role_id;

      insert into public.v99_scenario_lab_records (
        test_dataset_tag,
        organization_id,
        scenario_code,
        record_table,
        record_id,
        created_by,
        metadata
      )
      values (
        'V99_SCENARIO_LAB',
        p_organization_id,
        p_scenario,
        'user_roles',
        v_temporary_role_id,
        p_actor_id,
        jsonb_build_object(
          'purpose',
          'temporary synthetic referred-department persona for lifecycle exercise'
        )
      )
      on conflict (record_table, record_id) do nothing;
    end if;

    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'manager_review',
      jsonb_build_object(
        'supervisor_investigation',
        '[V99_SCENARIO_LAB] Synthetic manager review before Quality referral.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_validation',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic Quality validation before cross-department notification.',
        'confirmed_severity_level',
        'level_2'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'referred_party_response',
      jsonb_build_object(
        'referred_department_id',
        v_referred_department_id
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_final_review',
      jsonb_build_object(
        'referred_response',
        '[V99_SCENARIO_LAB] Synthetic referred-party response.',
        'corrective_action',
        '[V99_SCENARIO_LAB] Synthetic handoff checklist correction.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_final_review',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic final Quality review.',
        'final_verdict',
        'Synthetic test workflow validated; no real incident conclusion.',
        'confirmed_severity_level',
        'level_2'
      )
    );

    insert into public.evidence_files (
      organization_id,
      ovr_report_id,
      file_name,
      file_path,
      file_type,
      file_size,
      description,
      status,
      uploaded_by,
      reviewed_by,
      reviewed_at
    )
    values (
      p_organization_id,
      v_ovr_id,
      'V99_SCENARIO_LAB-cross-department-proof.txt',
      'V99_SCENARIO_LAB/metadata-only/cross-department-proof.txt',
      'text/plain',
      0,
      '[V99_SCENARIO_LAB] Synthetic metadata-only closure proof.',
      'accepted',
      p_actor_id,
      p_actor_id,
      now()
    )
    returning id into v_evidence_id;

    insert into public.v99_scenario_lab_records (
      test_dataset_tag,
      organization_id,
      scenario_code,
      record_table,
      record_id,
      created_by,
      metadata
    )
    values (
      'V99_SCENARIO_LAB',
      p_organization_id,
      p_scenario,
      'evidence_files',
      v_evidence_id,
      p_actor_id,
      jsonb_build_object('metadata_only', true, 'ovr_report_id', v_ovr_id)
    )
    on conflict (record_table, record_id) do nothing;

    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'closed',
      jsonb_build_object(
        'note',
        '[V99_SCENARIO_LAB] Synthetic reporter acceptance and closure.'
      )
    );

  elsif p_scenario = 'ovr_disputed_reopened' then
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'manager_review',
      jsonb_build_object(
        'supervisor_investigation',
        '[V99_SCENARIO_LAB] Synthetic initial manager review.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_validation',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic initial Quality validation.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_final_review',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic initial final review.',
        'final_verdict',
        'Synthetic initial verdict for dispute testing.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'disputed',
      jsonb_build_object(
        'note',
        '[V99_SCENARIO_LAB] Synthetic reporter dispute.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'reopened',
      jsonb_build_object(
        'note',
        '[V99_SCENARIO_LAB] Synthetic Quality reopening.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'manager_review',
      jsonb_build_object(
        'supervisor_investigation',
        '[V99_SCENARIO_LAB] Synthetic manager re-review after reopening.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_validation',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic Quality re-validation.'
      )
    );
    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'quality_final_review',
      jsonb_build_object(
        'quality_manager_comments',
        '[V99_SCENARIO_LAB] Synthetic final review after dispute.',
        'final_verdict',
        'Synthetic revised verdict after controlled dispute review.'
      )
    );

    insert into public.evidence_files (
      organization_id,
      ovr_report_id,
      file_name,
      file_path,
      file_type,
      file_size,
      description,
      status,
      uploaded_by,
      reviewed_by,
      reviewed_at
    )
    values (
      p_organization_id,
      v_ovr_id,
      'V99_SCENARIO_LAB-dispute-reopen-proof.txt',
      'V99_SCENARIO_LAB/metadata-only/dispute-reopen-proof.txt',
      'text/plain',
      0,
      '[V99_SCENARIO_LAB] Synthetic metadata-only evidence after reopening.',
      'accepted',
      p_actor_id,
      p_actor_id,
      now()
    )
    returning id into v_evidence_id;

    insert into public.v99_scenario_lab_records (
      test_dataset_tag,
      organization_id,
      scenario_code,
      record_table,
      record_id,
      created_by,
      metadata
    )
    values (
      'V99_SCENARIO_LAB',
      p_organization_id,
      p_scenario,
      'evidence_files',
      v_evidence_id,
      p_actor_id,
      jsonb_build_object('metadata_only', true, 'ovr_report_id', v_ovr_id)
    )
    on conflict (record_table, record_id) do nothing;

    perform public.v98_update_ovr_workflow(
      p_actor_id,
      v_ovr_id,
      'closed',
      jsonb_build_object(
        'note',
        '[V99_SCENARIO_LAB] Synthetic acceptance after dispute resolution.'
      )
    );
  end if;

  insert into public.v99_scenario_lab_records (
    test_dataset_tag,
    organization_id,
    scenario_code,
    record_table,
    record_id,
    created_by,
    metadata
  )
  select
    'V99_SCENARIO_LAB',
    p_organization_id,
    p_scenario,
    'notifications',
    n.id,
    p_actor_id,
    jsonb_build_object('ovr_number', v_ovr_number)
  from public.notifications n
  where n.organization_id = p_organization_id
    and n.created_at >= v_started_at
    and n.body like '%' || v_ovr_number || '%'
  on conflict (record_table, record_id) do nothing;

  return (
    select jsonb_build_object(
      'scenario', p_scenario,
      'record_type', 'ovr_report',
      'id', o.id,
      'ovr_number', o.ovr_number,
      'status', o.status,
      'quality_validated_at', o.quality_validated_at,
      'cross_department_notified_at', o.cross_department_notified_at,
      'reporter_response', o.reporter_response,
      'test_dataset_tag', o.occurrence_details->>'test_dataset_tag'
    )
    from public.ovr_reports o
    where o.id = v_ovr_id
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v99_create_scenario"("p_actor_id" "uuid", "p_scenario" "text", "p_confirmation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_organization_id uuid;
  v_department_id uuid;
  v_record_id uuid;
  v_parent_id uuid;
  v_results jsonb := '[]'::jsonb;
  v_item jsonb;
  v_scenario text;
begin
  perform pg_advisory_xact_lock(hashtext('V99_SCENARIO_LAB'));
  v_organization_id :=
    public.v99_assert_scenario_lab_actor(p_actor_id, p_confirmation);

  p_scenario := lower(trim(p_scenario));

  if p_scenario in (
    'ovr_same_department',
    'ovr_cross_department',
    'ovr_high_severity',
    'ovr_returned_clarification',
    'ovr_disputed_reopened'
  ) then
    return public.v99_create_ovr_scenario(
      p_actor_id,
      v_organization_id,
      p_scenario,
      p_confirmation
    );
  end if;

  select d.id
    into v_department_id
  from public.departments d
  where d.organization_id = v_organization_id
    and d.is_active = true
  order by
    case when upper(trim(d.code)) in ('GOVCOMP', 'QUALITY') then 0 else 1 end,
    d.created_at,
    d.id
  limit 1;

  if p_scenario = 'risk' then
    insert into public.risks (
      organization_id,
      risk_code,
      title,
      description,
      category,
      department_id,
      owner_id,
      likelihood,
      impact,
      residual_likelihood,
      residual_impact,
      risk_level,
      response_type,
      status,
      next_review_date,
      notes,
      created_by,
      updated_by
    )
    values (
      v_organization_id,
      'V99-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)),
      '[V99_SCENARIO_LAB] Synthetic pilot risk',
      '[V99_SCENARIO_LAB] Synthetic non-confidential risk used only for controlled pilot testing.',
      'operational',
      v_department_id,
      p_actor_id,
      4,
      4,
      2,
      2,
      'high',
      'reduce',
      'open',
      current_date + 30,
      'test_dataset_tag=V99_SCENARIO_LAB',
      p_actor_id,
      p_actor_id
    )
    returning id into v_record_id;

    insert into public.v99_scenario_lab_records (
      test_dataset_tag, organization_id, scenario_code, record_table,
      record_id, created_by, metadata
    )
    values (
      'V99_SCENARIO_LAB', v_organization_id, p_scenario, 'risks',
      v_record_id, p_actor_id, jsonb_build_object('synthetic_only', true)
    );

    return jsonb_build_object(
      'scenario', p_scenario,
      'record_type', 'risk',
      'id', v_record_id,
      'status', 'open',
      'test_dataset_tag', 'V99_SCENARIO_LAB'
    );

  elsif p_scenario = 'control' then
    v_item := public.v99_create_scenario(p_actor_id, 'risk', p_confirmation);
    v_parent_id := (v_item->>'id')::uuid;

    insert into public.risk_controls (
      organization_id,
      risk_id,
      title,
      description,
      control_type,
      frequency,
      effectiveness,
      owner_id,
      evidence_required,
      next_test_date,
      is_active,
      created_by,
      updated_by
    )
    values (
      v_organization_id,
      v_parent_id,
      '[V99_SCENARIO_LAB] Synthetic preventive control',
      '[V99_SCENARIO_LAB] Synthetic control for pilot visibility and workflow checks.',
      'preventive',
      'monthly',
      'effective',
      p_actor_id,
      true,
      current_date + 30,
      true,
      p_actor_id,
      p_actor_id
    )
    returning id into v_record_id;

    insert into public.v99_scenario_lab_records (
      test_dataset_tag, organization_id, scenario_code, record_table,
      record_id, created_by, metadata
    )
    values (
      'V99_SCENARIO_LAB', v_organization_id, p_scenario, 'risk_controls',
      v_record_id, p_actor_id, jsonb_build_object('risk_id', v_parent_id)
    );

    return jsonb_build_object(
      'scenario', p_scenario,
      'record_type', 'risk_control',
      'id', v_record_id,
      'risk_id', v_parent_id,
      'status', 'active',
      'test_dataset_tag', 'V99_SCENARIO_LAB'
    );

  elsif p_scenario = 'project' then
    insert into public.projects (
      organization_id,
      title,
      description,
      category,
      source_type,
      department_id,
      owner_id,
      sponsor_id,
      start_date,
      target_end_date,
      priority,
      risk_level,
      status,
      progress_percent,
      evidence_required,
      closure_approval_required,
      created_by,
      updated_by
    )
    values (
      v_organization_id,
      '[V99_SCENARIO_LAB] Synthetic corrective action',
      '[V99_SCENARIO_LAB] Synthetic project/corrective action for controlled pilot testing.',
      'Controlled Pilot Test',
      'manual',
      v_department_id,
      p_actor_id,
      p_actor_id,
      current_date,
      current_date + 30,
      'high',
      'medium',
      'draft',
      0,
      true,
      true,
      p_actor_id,
      p_actor_id
    )
    returning id into v_record_id;

    insert into public.v99_scenario_lab_records (
      test_dataset_tag, organization_id, scenario_code, record_table,
      record_id, created_by, metadata
    )
    values (
      'V99_SCENARIO_LAB', v_organization_id, p_scenario, 'projects',
      v_record_id, p_actor_id, jsonb_build_object('synthetic_only', true)
    );

    return jsonb_build_object(
      'scenario', p_scenario,
      'record_type', 'project',
      'id', v_record_id,
      'status', 'draft',
      'test_dataset_tag', 'V99_SCENARIO_LAB'
    );

  elsif p_scenario = 'evidence' then
    v_item := public.v99_create_scenario(p_actor_id, 'project', p_confirmation);
    v_parent_id := (v_item->>'id')::uuid;

    insert into public.evidence_files (
      organization_id,
      project_id,
      file_name,
      file_path,
      file_type,
      file_size,
      description,
      status,
      uploaded_by
    )
    values (
      v_organization_id,
      v_parent_id,
      'V99_SCENARIO_LAB-synthetic-evidence.txt',
      'V99_SCENARIO_LAB/metadata-only/synthetic-evidence.txt',
      'text/plain',
      0,
      '[V99_SCENARIO_LAB] Synthetic evidence metadata. No confidential content.',
      'submitted',
      p_actor_id
    )
    returning id into v_record_id;

    insert into public.v99_scenario_lab_records (
      test_dataset_tag, organization_id, scenario_code, record_table,
      record_id, created_by, metadata
    )
    values (
      'V99_SCENARIO_LAB', v_organization_id, p_scenario, 'evidence_files',
      v_record_id, p_actor_id,
      jsonb_build_object('project_id', v_parent_id, 'metadata_only', true)
    );

    return jsonb_build_object(
      'scenario', p_scenario,
      'record_type', 'evidence_file',
      'id', v_record_id,
      'project_id', v_parent_id,
      'status', 'submitted',
      'metadata_only', true,
      'test_dataset_tag', 'V99_SCENARIO_LAB'
    );

  elsif p_scenario = 'full' then
    foreach v_scenario in array array[
      'ovr_same_department',
      'ovr_cross_department',
      'ovr_high_severity',
      'ovr_returned_clarification',
      'ovr_disputed_reopened',
      'risk',
      'control',
      'evidence',
      'project'
    ]
    loop
      v_item := public.v99_create_scenario(
        p_actor_id,
        v_scenario,
        p_confirmation
      );
      v_results := v_results || jsonb_build_array(v_item);
    end loop;

    return jsonb_build_object(
      'scenario', 'full',
      'records', v_results,
      'record_count', jsonb_array_length(v_results),
      'test_dataset_tag', 'V99_SCENARIO_LAB'
    );
  end if;

  raise exception 'V99_UNSUPPORTED_SCENARIO: %', p_scenario;
end;
$$;

CREATE OR REPLACE FUNCTION "public"."v99_scenario_status"("p_actor_id" "uuid", "p_confirmation" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_organization_id uuid;
begin
  v_organization_id :=
    public.v99_assert_scenario_lab_actor(p_actor_id, p_confirmation);

  return jsonb_build_object(
    'test_dataset_tag',
    'V99_SCENARIO_LAB',
    'total_records',
    (
      select count(*)
      from public.v99_scenario_lab_records r
      where r.organization_id = v_organization_id
        and r.test_dataset_tag = 'V99_SCENARIO_LAB'
    ),
    'by_table',
    (
      select coalesce(
        jsonb_object_agg(grouped.record_table, grouped.record_count),
        '{}'::jsonb
      )
      from (
        select r.record_table, count(*) as record_count
        from public.v99_scenario_lab_records r
        where r.organization_id = v_organization_id
          and r.test_dataset_tag = 'V99_SCENARIO_LAB'
        group by r.record_table
        order by r.record_table
      ) grouped
    ),
    'by_scenario',
    (
      select coalesce(
        jsonb_object_agg(grouped.scenario_code, grouped.record_count),
        '{}'::jsonb
      )
      from (
        select r.scenario_code, count(*) as record_count
        from public.v99_scenario_lab_records r
        where r.organization_id = v_organization_id
          and r.test_dataset_tag = 'V99_SCENARIO_LAB'
        group by r.scenario_code
        order by r.scenario_code
      ) grouped
    )
  );
end;
$$;

CREATE OR REPLACE FUNCTION "public"."validate_capa_completion"("p_capa_id" "uuid", "p_actor_id" "uuid", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare v_old text;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH28_CAPA_SERVICE_ROLE_REQUIRED'; end if;
  select capa_status into v_old from public.capa_action_plans where id = p_capa_id for update;
  if not found then raise exception 'PATCH28_CAPA_NOT_FOUND'; end if;
  update public.capa_action_plans set capa_status = case when effectiveness_review_required then 'effectiveness_review_pending' else 'closure_requested' end, workflow_stage = case when effectiveness_review_required then 'effectiveness_review' else 'closure' end, validation_status = 'approved', validated_by = p_actor_id, validated_at = now(), validation_note = p_note, updated_by = p_actor_id, updated_at = now() where id = p_capa_id;
  perform public.patch28_write_capa_event(p_capa_id, null, 'validation_approved', v_old, 'validation_approved', p_actor_id, p_note, null);
  return jsonb_build_object('status','ok','capa_id',p_capa_id);
end $$;

CREATE OR REPLACE FUNCTION "public"."waive_evidence_collection_request"("p_collection_request_id" "uuid", "p_actor_user_id" "uuid", "p_waiver_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
declare
  v_bridge_id uuid;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role' and current_user <> 'service_role' then raise exception 'PATCH33_SERVICE_ROLE_REQUIRED'; end if;
  if not public.patch33_actor_has_evidence_bridge_authority(p_actor_user_id) then raise exception 'PATCH33_EVIDENCE_BRIDGE_AUTHORITY_REQUIRED'; end if;
  if nullif(trim(coalesce(p_waiver_reason,'')), '') is null then raise exception 'PATCH33_WAIVER_REASON_REQUIRED'; end if;
  update public.evidence_collection_requests set status = 'waived', completed_at = now() where id = p_collection_request_id returning bridge_link_id into v_bridge_id;
  if not found then raise exception 'PATCH33_COLLECTION_REQUEST_NOT_FOUND'; end if;
  if v_bridge_id is not null then update public.evidence_bridge_links set evidence_status = 'not_applicable', updated_by = p_actor_user_id, updated_at = now() where id = v_bridge_id; end if;
  perform public.record_evidence_bridge_event('evidence_collection_request', p_collection_request_id, 'collection_request_waived', p_waiver_reason, p_actor_user_id);
  return jsonb_build_object('status','ok','collection_request_id',p_collection_request_id);
end;
$$;

CREATE OR REPLACE FUNCTION "public"."waive_training_assignment_with_reason"("p_assignment_id" "uuid", "p_reason" "text", "p_actor_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), current_user) <> 'service_role'
     and current_user <> 'service_role' then
    raise exception 'PATCH29_TRAINING_SERVICE_ROLE_REQUIRED';
  end if;

  update public.training_assignments
  set status = 'waived'
  where id = p_assignment_id and status in ('assigned', 'in_progress', 'overdue');

  if not found then
    raise exception 'PATCH29_ASSIGNMENT_NOT_WAIVABLE';
  end if;

  perform public.log_training_event(
    'training_assignments', p_assignment_id, 'waived',
    'Assignment waived with reason: ' || p_reason,
    p_actor_id
  );
end;
$$;

