    CONSTRAINT "audit_findings_patch24_status_chk" CHECK (("finding_status" = ANY (ARRAY['draft'::"text", 'issued'::"text", 'management_response_required'::"text", 'management_response_submitted'::"text", 'action_plan_required'::"text", 'action_plan_in_progress'::"text", 'evidence_required'::"text", 'closure_requested'::"text", 'auditor_validation'::"text", 'returned_for_correction'::"text", 'escalated'::"text", 'closed'::"text", 'rejected'::"text", 'cancelled'::"text", 'reopened'::"text"])))
