CREATE TABLE IF NOT EXISTS "public"."identity_role_integrity_findings" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "review_id" "uuid" NOT NULL,
    "finding_type" "text" NOT NULL,
    "severity" "text" DEFAULT 'medium'::"text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "entity_id" "uuid",
    "department_id" "uuid",
    "finding_title" "text" NOT NULL,
    "finding_summary" "text",
    "owner_id" "uuid",
    "due_date" "date",
    "finding_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "resolution_summary" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "identity_role_integrity_findings_finding_status_check" CHECK (("finding_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'resolved'::"text", 'accepted_limitation'::"text", 'deferred'::"text", 'blocked'::"text"]))),
    CONSTRAINT "identity_role_integrity_findings_finding_type_check" CHECK (("finding_type" = ANY (ARRAY['duplicate_role'::"text", 'privileged_role_review'::"text", 'dormant_account'::"text", 'inactive_account'::"text", 'archived_user_access'::"text", 'missing_owner'::"text", 'missing_reviewer'::"text", 'department_accountability_gap'::"text", 'station_accountability_gap'::"text", 'sso_mfa_readiness_gap'::"text", 'access_export_required'::"text", 'data_integrity_gap'::"text"]))),
    CONSTRAINT "identity_role_integrity_findings_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"]))),
    CONSTRAINT "patch78_finding_title_required" CHECK ((NULLIF("btrim"("finding_title"), ''::"text") IS NOT NULL)),
    CONSTRAINT "patch78_high_risk_deferred_guard" CHECK ((("finding_status" <> 'deferred'::"text") OR ("severity" <> ALL (ARRAY['high'::"text", 'critical'::"text"])) OR (NULLIF("btrim"(COALESCE("resolution_summary", ''::"text")), ''::"text") IS NOT NULL)))
);

CREATE TABLE IF NOT EXISTS "public"."identity_role_integrity_reviews" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "review_title" "text" NOT NULL,
    "review_scope" "text" DEFAULT 'hospital_access_integrity'::"text" NOT NULL,
    "review_status" "text" DEFAULT 'in_review'::"text" NOT NULL,
    "duplicate_role_count" integer DEFAULT 0 NOT NULL,
    "privileged_user_count" integer DEFAULT 0 NOT NULL,
    "privileged_pending_recertification_count" integer DEFAULT 0 NOT NULL,
    "dormant_account_count" integer DEFAULT 0 NOT NULL,
    "inactive_account_count" integer DEFAULT 0 NOT NULL,
    "archived_user_access_count" integer DEFAULT 0 NOT NULL,
    "missing_owner_count" integer DEFAULT 0 NOT NULL,
    "missing_reviewer_count" integer DEFAULT 0 NOT NULL,
    "department_accountability_gap_count" integer DEFAULT 0 NOT NULL,
    "station_accountability_gap_count" integer DEFAULT 0 NOT NULL,
    "open_high_risk_finding_count" integer DEFAULT 0 NOT NULL,
    "sso_mfa_readiness_status" "text" DEFAULT 'review_required'::"text" NOT NULL,
    "access_export_status" "text" DEFAULT 'not_ready'::"text" NOT NULL,
    "review_notes" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "identity_role_integrity_revi_department_accountability_ga_check" CHECK (("department_accountability_gap_count" >= 0)),
    CONSTRAINT "identity_role_integrity_revi_open_high_risk_finding_count_check" CHECK (("open_high_risk_finding_count" >= 0)),
    CONSTRAINT "identity_role_integrity_revi_privileged_pending_recertifi_check" CHECK (("privileged_pending_recertification_count" >= 0)),
    CONSTRAINT "identity_role_integrity_revi_station_accountability_gap_c_check" CHECK (("station_accountability_gap_count" >= 0)),
    CONSTRAINT "identity_role_integrity_review_archived_user_access_count_check" CHECK (("archived_user_access_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_access_export_status_check" CHECK (("access_export_status" = ANY (ARRAY['not_ready'::"text", 'ready_for_export'::"text", 'exported_for_review'::"text", 'blocked'::"text"]))),
    CONSTRAINT "identity_role_integrity_reviews_dormant_account_count_check" CHECK (("dormant_account_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_duplicate_role_count_check" CHECK (("duplicate_role_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_inactive_account_count_check" CHECK (("inactive_account_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_missing_owner_count_check" CHECK (("missing_owner_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_missing_reviewer_count_check" CHECK (("missing_reviewer_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_privileged_user_count_check" CHECK (("privileged_user_count" >= 0)),
    CONSTRAINT "identity_role_integrity_reviews_review_status_check" CHECK (("review_status" = ANY (ARRAY['in_review'::"text", 'remediation_required'::"text", 'ready_for_access_integrity_review'::"text", 'accepted_with_limitations'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "identity_role_integrity_reviews_sso_mfa_readiness_status_check" CHECK (("sso_mfa_readiness_status" = ANY (ARRAY['review_required'::"text", 'ready_for_it_review'::"text", 'blocked'::"text", 'not_applicable'::"text"]))),
    CONSTRAINT "patch78_accepted_limitation_guard" CHECK ((("review_status" <> 'accepted_with_limitations'::"text") OR ((NULLIF("btrim"(COALESCE("review_notes", ''::"text")), ''::"text") IS NOT NULL) AND ("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)))),
    CONSTRAINT "patch78_ready_review_guard" CHECK ((("review_status" <> 'ready_for_access_integrity_review'::"text") OR (("open_high_risk_finding_count" = 0) AND ("privileged_pending_recertification_count" = 0) AND ("missing_owner_count" = 0) AND ("missing_reviewer_count" = 0) AND ("access_export_status" = ANY (ARRAY['ready_for_export'::"text", 'exported_for_review'::"text"]))))),
    CONSTRAINT "patch78_review_title_required" CHECK ((NULLIF("btrim"("review_title"), ''::"text") IS NOT NULL))
);

