CREATE TABLE IF NOT EXISTS "public"."live_grc_closure_packets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "packet_code" "text" NOT NULL,
    "requirement_reference" "text",
    "risk_id" "uuid",
    "control_id" "uuid",
    "test_result_id" "uuid",
    "evidence_request_id" "uuid",
    "evidence_review_id" "uuid",
    "capa_id" "uuid",
    "approval_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "closure_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "approved_by" "uuid",
    "approved_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
