    CONSTRAINT "live_grc_closure_packets_check" CHECK ((("closure_status" <> 'closed'::"text") OR (("requirement_reference" IS NOT NULL) AND ("risk_id" IS NOT NULL) AND ("control_id" IS NOT NULL) AND ("test_result_id" IS NOT NULL) AND ("evidence_request_id" IS NOT NULL) AND ("evidence_review_id" IS NOT NULL) AND ("approval_status" = 'approved'::"text")))),
    CONSTRAINT "live_grc_closure_packets_closure_status_check" CHECK (("closure_status" = ANY (ARRAY['open'::"text", 'ready_for_approval'::"text", 'closed'::"text", 'reopened'::"text"])))
);

COMMENT ON TABLE "public"."live_grc_closure_packets" IS 'Patch 3 closure enforcement packet. Closed packets require requirement, risk, control, test, evidence review, and approval.';

