    "current_credential_version" integer NOT NULL,
    "next_credential_version" integer NOT NULL,
    "resulting_credential_state" "text",
    "auth_changed" boolean DEFAULT false NOT NULL,
    "session_revocation_confirmed" boolean DEFAULT false NOT NULL,
    "safe_result" "jsonb",
    "completed_at" timestamp with time zone,
