    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patch83u_credential_operations_check" CHECK (("next_credential_version" = ("current_credential_version" + 1))),
    CONSTRAINT "patch83u_credential_operations_current_credential_version_check" CHECK (("current_credential_version" >= 0)),
    CONSTRAINT "patch83u_credential_operations_operation_status_check" CHECK (("operation_status" = ANY (ARRAY['prepared'::"text", 'in_progress'::"text", 'auth_changed'::"text", 'completed'::"text", 'aborted'::"text", 'recovery_required'::"text", 'session_revocation_review_required'::"text"]))),
    CONSTRAINT "patch83u_credential_operations_operation_type_check" CHECK (("operation_type" = ANY (ARRAY['password_change'::"text", 'admin_reset'::"text"]))),
    CONSTRAINT "patch83u_credential_operations_request_id_check" CHECK ((("length"("request_id") >= 1) AND ("length"("request_id") <= 128) AND ("request_id" ~ '^[A-Za-z0-9._:-]+$'::"text"))),
    CONSTRAINT "patch83u_credential_operations_safe_result_check" CHECK ((("safe_result" IS NULL) OR ("jsonb_typeof"("safe_result") = 'object'::"text")))
);

