CREATE TABLE IF NOT EXISTS "public"."patch83u_runtime_control" (
    "singleton" boolean DEFAULT true NOT NULL,
    "schema_version" "text" DEFAULT '174.2-auth-first'::"text" NOT NULL,
    "enforcement_state" "text" DEFAULT 'disabled'::"text" NOT NULL,
    "prepared_at" timestamp with time zone,
    "prepared_by" "uuid",
    "activated_at" timestamp with time zone,
    "activated_by" "uuid",
    "deactivated_at" timestamp with time zone,
    "deactivated_by" "uuid",
    "activation_reason" "text",
    "last_transition_reason" "text",
    "expected_edge_contract_version" "text" DEFAULT 'patch83u-edge-auth-first-v1'::"text" NOT NULL,
    "expected_frontend_contract_version" "text" DEFAULT 'patch83u-frontend-auth-first-v1'::"text" NOT NULL,
    "compatible_edge_contract_version" "text",
    "compatible_frontend_contract_version" "text",
    "compatibility_attested_at" timestamp with time zone,
    "compatibility_attested_by" "uuid",
    "preflight_hash" "text",
    "designated_super_admin_id" "uuid",
    "last_transition_request_id" "text",
    "state_version" integer DEFAULT 0 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patch83u_runtime_control_enforcement_state_check" CHECK (("enforcement_state" = ANY (ARRAY['disabled'::"text", 'prepared'::"text", 'enforced'::"text", 'emergency_suspended'::"text"]))),
    CONSTRAINT "patch83u_runtime_control_expected_edge_contract_version_check" CHECK (("expected_edge_contract_version" = 'patch83u-edge-auth-first-v1'::"text")),
    CONSTRAINT "patch83u_runtime_control_expected_frontend_contract_versi_check" CHECK (("expected_frontend_contract_version" = 'patch83u-frontend-auth-first-v1'::"text")),
    CONSTRAINT "patch83u_runtime_control_preflight_hash_check" CHECK ((("preflight_hash" IS NULL) OR ("preflight_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "patch83u_runtime_control_schema_version_check" CHECK (("schema_version" = '174.2-auth-first'::"text")),
    CONSTRAINT "patch83u_runtime_control_singleton_check" CHECK ("singleton"),
    CONSTRAINT "patch83u_runtime_control_state_version_check" CHECK (("state_version" >= 0)),
    CONSTRAINT "patch83u_runtime_enforced_contract" CHECK ((("enforcement_state" <> 'enforced'::"text") OR (("activated_at" IS NOT NULL) AND ("activated_by" IS NOT NULL) AND ("compatibility_attested_at" IS NOT NULL) AND ("compatibility_attested_by" = "designated_super_admin_id") AND ("compatible_edge_contract_version" = "expected_edge_contract_version") AND ("compatible_frontend_contract_version" = "expected_frontend_contract_version")))),
    CONSTRAINT "patch83u_runtime_prepared_contract" CHECK ((("enforcement_state" = 'disabled'::"text") OR (("preflight_hash" IS NOT NULL) AND ("designated_super_admin_id" IS NOT NULL) AND ("prepared_at" IS NOT NULL) AND ("prepared_by" IS NOT NULL))))
);

ALTER TABLE ONLY "public"."patch83u_runtime_control" FORCE ROW LEVEL SECURITY;

COMMENT ON TABLE "public"."patch83u_runtime_control" IS 'Patch 83U singleton deployment gate. Direct service-role mutation is revoked; audited exact-confirmation SECURITY DEFINER routines are the only runtime mutation path.';

