    CONSTRAINT "patch83u_runtime_events_request_id_check" CHECK ((("length"("request_id") >= 1) AND ("length"("request_id") <= 128) AND ("request_id" ~ '^[A-Za-z0-9._:-]+$'::"text"))),
    CONSTRAINT "patch83u_runtime_events_resulting_state_check" CHECK (("resulting_state" = ANY (ARRAY['disabled'::"text", 'prepared'::"text", 'enforced'::"text", 'emergency_suspended'::"text"])))
);

