    CONSTRAINT "patch79_evidence_gap_closure_guard" CHECK ((("item_status" <> 'closed'::"text") OR ("item_type" <> 'evidence_pack_gap'::"text") OR (NULLIF("btrim"(COALESCE("evidence_summary", ''::"text")), ''::"text") IS NOT NULL))),
    CONSTRAINT "patch79_high_critical_closure_guard" CHECK ((("item_status" <> 'closed'::"text") OR ("severity" <> ALL (ARRAY['high'::"text", 'critical'::"text"])) OR (NULLIF("btrim"(COALESCE("closure_summary", ''::"text")), ''::"text") IS NOT NULL))),
    CONSTRAINT "patch79_item_title_required" CHECK ((NULLIF("btrim"("item_title"), ''::"text") IS NOT NULL)),
    CONSTRAINT "production_hypercare_items_item_status_check" CHECK (("item_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'evidence_required'::"text", 'review_required'::"text", 'closed'::"text", 'accepted_limitation'::"text", 'deferred'::"text", 'blocked'::"text"]))),
    CONSTRAINT "production_hypercare_items_item_type_check" CHECK (("item_type" = ANY (ARRAY['support_issue'::"text", 'incident_trend'::"text", 'department_launch_health'::"text", 'known_limitation'::"text", 'corrective_action'::"text", 'evidence_pack_gap'::"text", 'board_pack_gap'::"text", 'training_gap'::"text", 'dr_restore_gap'::"text", 'access_review_gap'::"text"]))),
    CONSTRAINT "production_hypercare_items_severity_check" CHECK (("severity" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'critical'::"text"])))
);

