CREATE TABLE IF NOT EXISTS "public"."production_hypercare_windows" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" DEFAULT "public"."current_user_org_id"(),
    "hypercare_title" "text" NOT NULL,
    "hypercare_scope" "text" DEFAULT 'controlled_operations'::"text" NOT NULL,
    "hypercare_status" "text" DEFAULT 'planned'::"text" NOT NULL,
    "day_30_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "day_60_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "day_90_status" "text" DEFAULT 'not_started'::"text" NOT NULL,
    "open_support_issue_count" integer DEFAULT 0 NOT NULL,
    "critical_incident_count" integer DEFAULT 0 NOT NULL,
    "unresolved_limitation_count" integer DEFAULT 0 NOT NULL,
    "corrective_action_open_count" integer DEFAULT 0 NOT NULL,
    "department_launch_gap_count" integer DEFAULT 0 NOT NULL,
    "evidence_pack_status" "text" DEFAULT 'incomplete'::"text" NOT NULL,
    "board_pack_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "hypercare_exit_ready" boolean DEFAULT false NOT NULL,
    "exit_review_notes" "text",
    "created_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patch79_hypercare_close_guard" CHECK ((("hypercare_status" <> 'closed_with_limitations'::"text") OR (("reviewed_by" IS NOT NULL) AND ("reviewed_at" IS NOT NULL)))),
    CONSTRAINT "patch79_hypercare_exit_guard" CHECK ((("hypercare_status" <> 'exit_review_required'::"text") OR (("critical_incident_count" = 0) AND ("evidence_pack_status" <> ALL (ARRAY['incomplete'::"text", 'blocked'::"text"])) AND ("board_pack_status" <> ALL (ARRAY['draft'::"text", 'blocked'::"text"])) AND (("open_support_issue_count" = 0) OR ("unresolved_limitation_count" > 0) OR ("evidence_pack_status" = 'accepted_with_limitations'::"text") OR ("board_pack_status" = 'accepted_with_limitations'::"text"))))),
    CONSTRAINT "patch79_hypercare_title_required" CHECK ((NULLIF("btrim"("hypercare_title"), ''::"text") IS NOT NULL)),
    CONSTRAINT "production_hypercare_windows_board_pack_status_check" CHECK (("board_pack_status" = ANY (ARRAY['draft'::"text", 'review_required'::"text", 'ready_for_board_review'::"text", 'accepted_with_limitations'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "production_hypercare_windows_corrective_action_open_count_check" CHECK (("corrective_action_open_count" >= 0)),
    CONSTRAINT "production_hypercare_windows_critical_incident_count_check" CHECK (("critical_incident_count" >= 0)),
    CONSTRAINT "production_hypercare_windows_day_30_status_check" CHECK (("day_30_status" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'review_required'::"text", 'accepted'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "production_hypercare_windows_day_60_status_check" CHECK (("day_60_status" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'review_required'::"text", 'accepted'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "production_hypercare_windows_day_90_status_check" CHECK (("day_90_status" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'review_required'::"text", 'accepted'::"text", 'blocked'::"text", 'deferred'::"text"]))),
    CONSTRAINT "production_hypercare_windows_department_launch_gap_count_check" CHECK (("department_launch_gap_count" >= 0)),
    CONSTRAINT "production_hypercare_windows_evidence_pack_status_check" CHECK (("evidence_pack_status" = ANY (ARRAY['incomplete'::"text", 'collecting'::"text", 'ready_for_review'::"text", 'accepted_with_limitations'::"text", 'blocked'::"text"]))),
    CONSTRAINT "production_hypercare_windows_hypercare_status_check" CHECK (("hypercare_status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'monitoring'::"text", 'exit_review_required'::"text", 'blocked'::"text", 'deferred'::"text", 'closed_with_limitations'::"text"]))),
    CONSTRAINT "production_hypercare_windows_open_support_issue_count_check" CHECK (("open_support_issue_count" >= 0)),
    CONSTRAINT "production_hypercare_windows_unresolved_limitation_count_check" CHECK (("unresolved_limitation_count" >= 0))
);

