    "division_id" "uuid",
    "department_id" "uuid",
    "unit_id" "uuid",
    "owner_id" "uuid",
    "likelihood" smallint DEFAULT 3 NOT NULL,
    "impact" smallint DEFAULT 3 NOT NULL,
    "inherent_score" integer GENERATED ALWAYS AS (("likelihood" * "impact")) STORED,
    "current_controls_summary" "text",
    "residual_likelihood" smallint DEFAULT 3 NOT NULL,
    "residual_impact" smallint DEFAULT 3 NOT NULL,
    "residual_score" integer GENERATED ALWAYS AS (("residual_likelihood" * "residual_impact")) STORED,
    "risk_level" "public"."risk_level" DEFAULT 'medium'::"public"."risk_level" NOT NULL,
    "response_type" "public"."risk_response_type" DEFAULT 'reduce'::"public"."risk_response_type" NOT NULL,
    "status" "public"."risk_status" DEFAULT 'draft'::"public"."risk_status" NOT NULL,
    "review_frequency" "public"."control_frequency" DEFAULT 'quarterly'::"public"."control_frequency",
    "last_reviewed_at" timestamp with time zone,
    "next_review_date" "date",
    "source_type" "public"."source_type" DEFAULT 'manual'::"public"."source_type" NOT NULL,
    "source_reference_id" "uuid",
    "notes" "text",
    "created_by" "uuid",
    "updated_by" "uuid",
    "closed_by" "uuid",
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "risk_statement" "text",
    "causes" "text",
    "consequences" "text",
    "risk_appetite" "text",
    "appetite_breached" boolean DEFAULT false NOT NULL,
    "target_residual_score" integer,
    "treatment_plan" "text",
    "treatment_owner_id" "uuid",
    "treatment_due_date" "date",
    "inherent_level" "public"."risk_level" DEFAULT 'medium'::"public"."risk_level" NOT NULL,
    "residual_level" "public"."risk_level" DEFAULT 'medium'::"public"."risk_level" NOT NULL,
    "kri_summary" "text",
    "control_gap_summary" "text",
    "assurance_summary" "text",
    "v100_maturity_flag" boolean DEFAULT false NOT NULL,
    "lifecycle_status" "text" DEFAULT 'identified'::"text" NOT NULL,
    "risk_owner_id" "uuid",
    "control_owner_id" "uuid",
    "executive_sponsor_id" "uuid",
    "inherent_likelihood" smallint,
    "inherent_impact" smallint,
    "scoring_method" "text" DEFAULT 'standard_5x5'::"text" NOT NULL,
    "score_last_changed_at" timestamp with time zone,
    "score_last_changed_by" "uuid",
    "appetite_level" "text" DEFAULT 'within_appetite'::"text" NOT NULL,
    "appetite_threshold" integer DEFAULT 12 NOT NULL,
    "appetite_breach_reason" "text",
    "treatment_required" boolean DEFAULT false NOT NULL,
    "treatment_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "treatment_plan_summary" "text",
    "treatment_completed_at" timestamp with time zone,
    "acceptance_required" boolean DEFAULT false NOT NULL,
    "acceptance_status" "text" DEFAULT 'not_required'::"text" NOT NULL,
    "acceptance_requested_by" "uuid",
    "acceptance_requested_at" timestamp with time zone,
    "accepted_by" "uuid",
    "accepted_at" timestamp with time zone,
    "acceptance_expiry_date" "date",
    "acceptance_reason" "text",
    "review_overdue" boolean DEFAULT false NOT NULL,
    "last_reviewed_by" "uuid",
    "closure_requested_at" timestamp with time zone,
    "closure_requested_by" "uuid",
    "closure_approved_by" "uuid",
    "closure_approved_at" timestamp with time zone,
    "closure_reason" "text",
    "closure_evidence_required" boolean DEFAULT true NOT NULL,
    "closure_blocker" "text",
    "escalation_required" boolean DEFAULT false NOT NULL,
    "escalation_level" "text" DEFAULT 'none'::"text" NOT NULL,
    "escalated_at" timestamp with time zone,
    "escalated_to" "uuid",
    "executive_visible" boolean DEFAULT false NOT NULL,
    "executive_visibility_override_reason" "text",
    "duplicate_of_risk_id" "uuid",
    "related_risk_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "repeat_signal_flag" boolean DEFAULT false NOT NULL,
    "source_ovr_id" "uuid",
    "source_audit_finding_id" "uuid",
    "source_compliance_id" "uuid",
    "source_project_id" "uuid",
    "severity_level" "text",
    CONSTRAINT "risks_impact_check" CHECK ((("impact" >= 1) AND ("impact" <= 5))),
    CONSTRAINT "risks_likelihood_check" CHECK ((("likelihood" >= 1) AND ("likelihood" <= 5))),
    CONSTRAINT "risks_patch22_acceptance_status_chk" CHECK (("acceptance_status" = ANY (ARRAY['not_required'::"text", 'required'::"text", 'requested'::"text", 'approved'::"text", 'rejected'::"text", 'expired'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "risks_patch22_appetite_threshold_chk" CHECK ((("appetite_threshold" >= 1) AND ("appetite_threshold" <= 25))),
    CONSTRAINT "risks_patch22_escalation_level_chk" CHECK (("escalation_level" = ANY (ARRAY['none'::"text", 'management'::"text", 'division'::"text", 'executive'::"text", 'board'::"text"]))),
    CONSTRAINT "risks_patch22_inherent_impact_chk" CHECK ((("inherent_impact" IS NULL) OR (("inherent_impact" >= 1) AND ("inherent_impact" <= 5)))),
    CONSTRAINT "risks_patch22_inherent_likelihood_chk" CHECK ((("inherent_likelihood" IS NULL) OR (("inherent_likelihood" >= 1) AND ("inherent_likelihood" <= 5)))),
    CONSTRAINT "risks_patch22_lifecycle_chk" CHECK (("lifecycle_status" = ANY (ARRAY['identified'::"text", 'assessed'::"text", 'treatment_required'::"text", 'treatment_in_progress'::"text", 'acceptance_requested'::"text", 'accepted'::"text", 'monitoring'::"text", 'closure_requested'::"text", 'closed'::"text", 'reopened'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "risks_patch22_treatment_status_chk" CHECK (("treatment_status" = ANY (ARRAY['not_required'::"text", 'required'::"text", 'planned'::"text", 'in_progress'::"text", 'completed'::"text", 'overdue'::"text", 'accepted'::"text"]))),
    CONSTRAINT "risks_residual_impact_check" CHECK ((("residual_impact" >= 1) AND ("residual_impact" <= 5))),
    CONSTRAINT "risks_residual_likelihood_check" CHECK ((("residual_likelihood" >= 1) AND ("residual_likelihood" <= 5))),
    CONSTRAINT "risks_target_residual_score_check" CHECK ((("target_residual_score" IS NULL) OR (("target_residual_score" >= 1) AND ("target_residual_score" <= 25))))
);

