CREATE TABLE IF NOT EXISTS "public"."user_credential_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "user_id" "uuid",
    "provisioning_id" "uuid",
    "actor_id" "uuid",
    "event_type" "text" NOT NULL,
    "credential_version" integer,
    "session_id" "uuid",
    "request_id" "text",
    "event_code" "text",
    "details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patch83u_event_code_safe" CHECK ((("event_code" IS NULL) OR (("length"("event_code") >= 1) AND ("length"("event_code") <= 80) AND ("event_code" ~ '^[A-Z0-9_]+$'::"text")))),
    CONSTRAINT "patch83u_event_request_id_safe" CHECK ((("request_id" IS NULL) OR (("length"("request_id") >= 1) AND ("length"("request_id") <= 128) AND ("request_id" ~ '^[A-Za-z0-9._:-]+$'::"text")))),
    CONSTRAINT "user_credential_events_credential_version_check" CHECK ((("credential_version" IS NULL) OR ("credential_version" >= 0))),
    CONSTRAINT "user_credential_events_details_check" CHECK (("jsonb_typeof"("details") = 'object'::"text")),
    CONSTRAINT "user_credential_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['legacy_state_backfilled'::"text", 'provisioning_claimed'::"text", 'provisioning_failed'::"text", 'provisioning_reconciliation_required'::"text", 'provisioning_reconciled'::"text", 'auth_account_verified'::"text", 'profile_created_invited'::"text", 'password_change_started'::"text", 'password_change_completed'::"text", 'password_change_aborted'::"text", 'existing_password_rotation_scheduled'::"text", 'existing_password_rotation_required'::"text", 'admin_reset_started'::"text", 'admin_reset_completed'::"text", 'admin_reset_aborted'::"text", 'roles_suspended'::"text", 'roles_restored'::"text", 'sessions_revoked'::"text", 'session_revocation_review_required'::"text", 'credential_disabled'::"text", 'credential_reactivation_required'::"text", 'credential_reconciled'::"text"])))
);

ALTER TABLE ONLY "public"."user_credential_events" FORCE ROW LEVEL SECURITY;

COMMENT ON TABLE "public"."user_credential_events" IS 'Patch 83U append-only, non-secret credential and provisioning evidence.';

CREATE TABLE IF NOT EXISTS "public"."user_credential_states" (
    "user_id" "uuid" NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "provisioning_id" "uuid",
    "auth_email" "text" NOT NULL,
    "identity_mode" "text" DEFAULT 'unverified'::"text" NOT NULL,
    "credential_state" "text" DEFAULT 'active'::"text" NOT NULL,
    "requested_lifecycle" "text" DEFAULT 'active'::"text" NOT NULL,
    "credential_version" integer DEFAULT 0 NOT NULL,
    "session_valid_after" timestamp with time zone DEFAULT "to_timestamp"((0)::double precision) NOT NULL,
    "invalidated_session_id" "uuid",
    "role_suspension_id" "uuid",
    "pending_operation_id" "uuid",
    "operation_source" "text",
    "reconciliation_auth_changed" boolean DEFAULT false NOT NULL,
    "pending_session_id" "uuid",
    "pending_credential_version" integer,
    "operation_previous_state" "text",
    "operation_previous_lifecycle" "text",
    "operation_previous_session_valid_after" timestamp with time zone,
    "provisioned_at" timestamp with time zone,
    "password_changed_at" timestamp with time zone,
    "reset_requested_at" timestamp with time zone,
    "password_reset_at" timestamp with time zone,
    "reset_requested_by" "uuid",
    "sessions_revoked_at" timestamp with time zone,
    "reconciliation_checked_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "patch83u_auth_email_canonical" CHECK ((("auth_email" = "lower"("btrim"("auth_email"))) AND ("auth_email" ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'::"text"))),
    CONSTRAINT "patch83u_pending_operation_consistent" CHECK (((("credential_state" = ANY (ARRAY['password_change_in_progress'::"text", 'reset_in_progress'::"text"])) AND ("pending_operation_id" IS NOT NULL) AND ("pending_credential_version" IS NOT NULL) AND ("operation_source" IS NOT NULL)) OR (("credential_state" <> ALL (ARRAY['password_change_in_progress'::"text", 'reset_in_progress'::"text"])) AND ("pending_operation_id" IS NULL) AND ("pending_credential_version" IS NULL) AND ("pending_session_id" IS NULL) AND (("credential_state" = ANY (ARRAY['recovery_required'::"text", 'reconciliation_required'::"text", 'session_revocation_review_required'::"text"])) OR ("operation_source" IS NULL))))),
    CONSTRAINT "patch83u_reconciliation_source_consistent" CHECK ((("reconciliation_auth_changed" = false) OR (("credential_state" = ANY (ARRAY['recovery_required'::"text", 'reconciliation_required'::"text", 'session_revocation_review_required'::"text"])) AND ("operation_source" IS NOT NULL)))),
    CONSTRAINT "user_credential_states_check" CHECK ((("pending_credential_version" IS NULL) OR ("pending_credential_version" > "credential_version"))),
    CONSTRAINT "user_credential_states_credential_state_check" CHECK (("credential_state" = ANY (ARRAY['active'::"text", 'existing_password_rotation_pending'::"text", 'existing_password_change_required'::"text", 'initial_change_required'::"text", 'admin_reset_change_required'::"text", 'reactivation_change_required'::"text", 'password_change_in_progress'::"text", 'reset_in_progress'::"text", 'disabled'::"text", 'recovery_required'::"text", 'reconciliation_required'::"text", 'session_revocation_review_required'::"text"]))),
    CONSTRAINT "user_credential_states_credential_version_check" CHECK (("credential_version" >= 0)),
    CONSTRAINT "user_credential_states_identity_mode_check" CHECK (("identity_mode" = ANY (ARRAY['legacy_verified'::"text", 'employee_id_managed'::"text", 'unverified'::"text"]))),
    CONSTRAINT "user_credential_states_operation_previous_lifecycle_check" CHECK ((("operation_previous_lifecycle" IS NULL) OR ("operation_previous_lifecycle" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'archived'::"text", 'invited'::"text", 'locked'::"text"])))),
    CONSTRAINT "user_credential_states_operation_previous_state_check" CHECK ((("operation_previous_state" IS NULL) OR ("operation_previous_state" = ANY (ARRAY['active'::"text", 'existing_password_rotation_pending'::"text", 'existing_password_change_required'::"text", 'initial_change_required'::"text", 'admin_reset_change_required'::"text", 'reactivation_change_required'::"text", 'disabled'::"text", 'recovery_required'::"text", 'reconciliation_required'::"text", 'session_revocation_review_required'::"text"])))),
    CONSTRAINT "user_credential_states_operation_source_check" CHECK ((("operation_source" IS NULL) OR ("operation_source" = ANY (ARRAY['admin_reset'::"text", 'password_change'::"text"])))),
    CONSTRAINT "user_credential_states_requested_lifecycle_check" CHECK (("requested_lifecycle" = ANY (ARRAY['active'::"text", 'inactive'::"text", 'archived'::"text", 'invited'::"text", 'locked'::"text"])))
);

ALTER TABLE ONLY "public"."user_credential_states" FORCE ROW LEVEL SECURITY;

COMMENT ON TABLE "public"."user_credential_states" IS 'Patch 83U authoritative credential state. Contains no password, password digest, bearer value, refresh value, or session secret.';

COMMENT ON COLUMN "public"."user_credential_states"."identity_mode" IS 'legacy_verified preserves an existing verified Auth email at credential version 0 without rewriting it; employee_id_managed requires the exact Employee-ID Auth alias; unverified is fail-closed.';

COMMENT ON COLUMN "public"."user_credential_states"."password_reset_at" IS 'Completion time of the most recent successfully finalized administrator password reset. Reset requests, failed Auth writes, and aborts never advance this value.';

