CREATE OR REPLACE VIEW "public"."v100_control_test_effectiveness_summary" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "effectiveness",
    "status",
    "test_type",
    "count"(*) AS "test_count",
    "min"("testing_period_start") AS "first_period_start",
    "max"("testing_period_end") AS "last_period_end"
   FROM "public"."control_tests"
  GROUP BY "organization_id", "effectiveness", "status", "test_type";

CREATE OR REPLACE VIEW "public"."v100_overdue_capa_actions" WITH ("security_invoker"='true') AS
 SELECT "cai"."id",
    "cai"."organization_id",
    "cai"."capa_case_id",
    "cai"."action_type",
    "cai"."title",
    "cai"."description",
    "cai"."owner_id",
    "cai"."due_date",
    "cai"."status",
    "cai"."progress_percent",
    "cai"."evidence_required",
    "cai"."evidence_summary",
    "cai"."delay_reason",
    "cai"."completed_by",
    "cai"."completed_at",
    "cai"."created_by",
    "cai"."updated_by",
    "cai"."created_at",
    "cai"."updated_at",
    "cc"."capa_code",
    "cc"."title" AS "capa_title",
    "cc"."severity" AS "capa_severity",
    "cc"."source_module"
   FROM ("public"."capa_action_items" "cai"
     JOIN "public"."capa_cases" "cc" ON (("cc"."id" = "cai"."capa_case_id")))
  WHERE (("cai"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND ("cai"."due_date" IS NOT NULL) AND ("cai"."due_date" < CURRENT_DATE));

CREATE OR REPLACE VIEW "public"."v100_risk_control_capa_dashboard" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "o"."name_en" AS "organization_name",
    "count"(DISTINCT "r"."id") FILTER (WHERE ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"]))) AS "open_risks",
    "count"(DISTINCT "r"."id") FILTER (WHERE (("r"."appetite_breached" = true) AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])))) AS "appetite_breaches",
    "count"(DISTINCT "rc"."id") FILTER (WHERE ("rc"."is_active" = true)) AS "active_controls",
    "count"(DISTINCT "rc"."id") FILTER (WHERE (("rc"."design_effectiveness" = 'ineffective'::"public"."v100_assurance_rating") OR ("rc"."operating_effectiveness" = 'ineffective'::"public"."v100_assurance_rating"))) AS "ineffective_controls",
    "count"(DISTINCT "ct"."id") FILTER (WHERE ("ct"."status" = ANY (ARRAY['failed'::"public"."v100_test_status", 'remediation_required'::"public"."v100_test_status"]))) AS "failed_control_tests",
    "count"(DISTINCT "cc"."id") FILTER (WHERE ("cc"."status" <> ALL (ARRAY['closed'::"public"."v100_capa_case_status", 'cancelled'::"public"."v100_capa_case_status"]))) AS "open_capa_cases",
    "count"(DISTINCT "cai"."id") FILTER (WHERE (("cai"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND ("cai"."due_date" < CURRENT_DATE))) AS "overdue_capa_actions",
    "count"(DISTINCT "co"."id") FILTER (WHERE ("co"."status" = ANY (ARRAY['non_compliant'::"public"."compliance_status", 'expired'::"public"."compliance_status", 'due_soon'::"public"."compliance_status", 'pending_evidence'::"public"."compliance_status"]))) AS "compliance_attention_items",
    "count"(DISTINCT "ae"."id") FILTER (WHERE ("ae"."status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) AS "active_audit_engagements"
   FROM ((((((("public"."organizations" "o"
     LEFT JOIN "public"."risks" "r" ON (("r"."organization_id" = "o"."id")))
     LEFT JOIN "public"."risk_controls" "rc" ON (("rc"."organization_id" = "o"."id")))
     LEFT JOIN "public"."control_tests" "ct" ON (("ct"."organization_id" = "o"."id")))
     LEFT JOIN "public"."capa_cases" "cc" ON (("cc"."organization_id" = "o"."id")))
     LEFT JOIN "public"."capa_action_items" "cai" ON (("cai"."organization_id" = "o"."id")))
     LEFT JOIN "public"."compliance_obligations" "co" ON (("co"."organization_id" = "o"."id")))
     LEFT JOIN "public"."audit_engagements" "ae" ON (("ae"."organization_id" = "o"."id")))
  GROUP BY "o"."id", "o"."name_en";

