CREATE OR REPLACE VIEW "public"."v110_enterprise_grc_maturity_dashboard" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "o"."name_en" AS "organization_name",
    "count"(DISTINCT "pd"."id") FILTER (WHERE ("pd"."status" = ANY (ARRAY['draft'::"public"."v110_policy_status", 'in_review'::"public"."v110_policy_status", 'approved'::"public"."v110_policy_status", 'published'::"public"."v110_policy_status"]))) AS "policy_documents",
    "count"(DISTINCT "pa"."id") FILTER (WHERE ("pa"."status" = ANY (ARRAY['not_started'::"public"."v110_attestation_status", 'overdue'::"public"."v110_attestation_status"]))) AS "pending_policy_attestations",
    "count"(DISTINCT "ta"."id") FILTER (WHERE ("ta"."status" = ANY (ARRAY['not_started'::"public"."v110_training_status", 'in_progress'::"public"."v110_training_status", 'overdue'::"public"."v110_training_status"]))) AS "pending_training_assignments",
    "count"(DISTINCT "vp"."id") FILTER (WHERE ("vp"."risk_rating" = ANY (ARRAY['critical'::"public"."v110_vendor_risk_rating", 'high'::"public"."v110_vendor_risk_rating"]))) AS "high_risk_vendors",
    "count"(DISTINCT "krim"."id") FILTER (WHERE ("krim"."rating" = 'red'::"text")) AS "red_kri_measurements",
    "count"(DISTINCT "rce"."id") FILTER (WHERE ("rce"."status" <> ALL (ARRAY['closed'::"public"."v110_reg_change_status", 'not_applicable'::"public"."v110_reg_change_status"]))) AS "open_regulatory_changes",
    "count"(DISTINCT "ea"."id") FILTER (WHERE (("ea"."status" = ANY (ARRAY['requested'::"public"."v110_exception_status", 'under_review'::"public"."v110_exception_status", 'approved'::"public"."v110_exception_status"])) AND (("ea"."expiry_date" IS NULL) OR ("ea"."expiry_date" >= CURRENT_DATE)))) AS "active_exceptions",
    "count"(DISTINCT "bp"."id") FILTER (WHERE (("bp"."criticality" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])) AND ("bp"."is_active" = true))) AS "critical_business_processes",
    "count"(DISTINCT "bcp"."id") FILTER (WHERE ("bcp"."status" = ANY (ARRAY['draft'::"public"."v110_bcp_status", 'under_review'::"public"."v110_bcp_status", 'failed_test'::"public"."v110_bcp_status"]))) AS "bcp_attention_items",
    "count"(DISTINCT "afu"."id") FILTER (WHERE ("afu"."status" <> ALL (ARRAY['closed'::"public"."v100_issue_status", 'cancelled'::"public"."v100_issue_status"]))) AS "open_audit_followups",
    "count"(DISTINCT "pma"."id") FILTER (WHERE ("pma"."maturity_score" <= 2)) AS "low_maturity_domains"
   FROM ((((((((((("public"."organizations" "o"
     LEFT JOIN "public"."v110_policy_documents" "pd" ON (("pd"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_policy_attestations" "pa" ON (("pa"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_training_assignments" "ta" ON (("ta"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_vendor_profiles" "vp" ON ((("vp"."organization_id" = "o"."id") AND ("vp"."is_active" = true))))
     LEFT JOIN "public"."v110_kri_measurements" "krim" ON (("krim"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_regulatory_change_events" "rce" ON (("rce"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_exception_acceptances" "ea" ON (("ea"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_business_processes" "bp" ON (("bp"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_business_continuity_plans" "bcp" ON (("bcp"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_audit_followup_reviews" "afu" ON (("afu"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v110_program_maturity_assessments" "pma" ON (("pma"."organization_id" = "o"."id")))
  GROUP BY "o"."id", "o"."name_en";

COMMENT ON VIEW "public"."v110_enterprise_grc_maturity_dashboard" IS 'v11.0 security-invoker dashboard summary for controlled pilot UAT and board pack preparation.';

CREATE OR REPLACE VIEW "public"."v110_board_pack_readiness_view" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "organization_name",
        CASE
            WHEN (("pending_policy_attestations" = 0) AND ("pending_training_assignments" = 0) AND ("red_kri_measurements" = 0) AND ("open_regulatory_changes" = 0) AND ("bcp_attention_items" = 0)) THEN 'ready'::"text"
            WHEN (("red_kri_measurements" > 0) OR ("bcp_attention_items" > 0) OR ("high_risk_vendors" > 0)) THEN 'attention_required'::"text"
            ELSE 'draft_ready'::"text"
        END AS "readiness_status",
    "jsonb_build_object"('policy_documents', "policy_documents", 'pending_policy_attestations', "pending_policy_attestations", 'pending_training_assignments', "pending_training_assignments", 'high_risk_vendors', "high_risk_vendors", 'red_kri_measurements', "red_kri_measurements", 'open_regulatory_changes', "open_regulatory_changes", 'active_exceptions', "active_exceptions", 'critical_business_processes', "critical_business_processes", 'bcp_attention_items', "bcp_attention_items", 'open_audit_followups', "open_audit_followups", 'low_maturity_domains', "low_maturity_domains") AS "readiness_metrics"
   FROM "public"."v110_enterprise_grc_maturity_dashboard" "d";

CREATE TABLE IF NOT EXISTS "public"."v110_board_report_snapshots" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "report_period_start" "date" NOT NULL,
    "report_period_end" "date" NOT NULL,
