    CONSTRAINT "v120_data_quality_rules_rule_type_check" CHECK (("rule_type" = ANY (ARRAY['completeness'::"text", 'validity'::"text", 'consistency'::"text", 'timeliness'::"text", 'uniqueness'::"text", 'approval'::"text", 'security'::"text", 'workflow'::"text"]))),
