);

CREATE OR REPLACE VIEW "public"."v120_data_quality_board" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."module_key",
    ("count"("f"."id"))::integer AS "findings_total",
    ("count"("f"."id") FILTER (WHERE ("f"."status" = ANY (ARRAY['new'::"public"."v120_feedback_status", 'triaged'::"public"."v120_feedback_status", 'planned'::"public"."v120_feedback_status", 'in_progress'::"public"."v120_feedback_status"]))))::integer AS "findings_open",
    ("count"("f"."id") FILTER (WHERE ("f"."severity" = 'critical'::"text")))::integer AS "critical_findings",
    ("count"("f"."id") FILTER (WHERE ("f"."severity" = 'high'::"text")))::integer AS "high_findings",
    ("count"("f"."id") FILTER (WHERE (("f"."due_date" IS NOT NULL) AND ("f"."due_date" < CURRENT_DATE) AND ("f"."status" <> ALL (ARRAY['resolved'::"public"."v120_feedback_status", 'closed'::"public"."v120_feedback_status"])))))::integer AS "overdue_findings",
    "max"("f"."detected_at") AS "last_detected_at"
   FROM ("public"."v120_data_quality_rules" "r"
     LEFT JOIN "public"."v120_data_quality_findings" "f" ON ((("f"."rule_id" = "r"."id") AND ("f"."organization_id" = "r"."organization_id"))))
  WHERE ("r"."is_active" = true)
  GROUP BY "r"."organization_id", "r"."module_key";

