CREATE OR REPLACE VIEW "public"."v120_executive_readiness_overview" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    ("count"("rc"."id") FILTER (WHERE ("rc"."release_key" = 'v12.0'::"text")))::integer AS "v120_checks_total",
    ("count"("rc"."id") FILTER (WHERE (("rc"."release_key" = 'v12.0'::"text") AND ("rc"."health" = ANY (ARRAY['excellent'::"public"."v120_health", 'good'::"public"."v120_health"])))))::integer AS "checks_good",
    ("count"("rc"."id") FILTER (WHERE (("rc"."release_key" = 'v12.0'::"text") AND ("rc"."health" = ANY (ARRAY['attention'::"public"."v120_health", 'critical'::"public"."v120_health"])))))::integer AS "checks_attention",
    ("count"("dq"."id") FILTER (WHERE ("dq"."status" <> ALL (ARRAY['resolved'::"public"."v120_feedback_status", 'closed'::"public"."v120_feedback_status"]))))::integer AS "open_data_quality_findings",
    ("count"("pb"."id") FILTER (WHERE ("pb"."status" <> ALL (ARRAY['resolved'::"public"."v120_feedback_status", 'closed'::"public"."v120_feedback_status"]))))::integer AS "open_polish_items",
    ("count"("sla"."id") FILTER (WHERE ("sla"."status" = 'breached'::"public"."v120_sla_status")))::integer AS "breached_sla_events",
    "max"(GREATEST(COALESCE("rc"."updated_at", '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE("dq"."updated_at", '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE("pb"."updated_at", '1970-01-01 00:00:00+00'::timestamp with time zone), COALESCE("sla"."updated_at", '1970-01-01 00:00:00+00'::timestamp with time zone))) AS "last_activity"
   FROM (((("public"."organizations" "o"
     LEFT JOIN "public"."v120_release_readiness_checks" "rc" ON (("rc"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v120_data_quality_findings" "dq" ON (("dq"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v120_polish_backlog" "pb" ON (("pb"."organization_id" = "o"."id")))
     LEFT JOIN "public"."v120_workflow_sla_events" "sla" ON (("sla"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

