CREATE OR REPLACE VIEW "public"."v120_polish_backlog_board" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "module_key",
    "category",
    ("count"(*))::integer AS "item_count",
    ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['new'::"public"."v120_feedback_status", 'triaged'::"public"."v120_feedback_status", 'planned'::"public"."v120_feedback_status", 'in_progress'::"public"."v120_feedback_status"]))))::integer AS "open_count",
    ("count"(*) FILTER (WHERE ("priority" = ANY (ARRAY['critical'::"text", 'high'::"text"]))))::integer AS "high_priority_count",
    ("count"(*) FILTER (WHERE ("status" = 'resolved'::"public"."v120_feedback_status")))::integer AS "resolved_count",
    "max"("updated_at") AS "last_update"
   FROM "public"."v120_polish_backlog"
  GROUP BY "organization_id", "module_key", "category";

