CREATE OR REPLACE VIEW "public"."v35_consolidation_scorecard" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_patch_manifest") AS "patches_registered",
    ( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_patch_manifest"
          WHERE ("consolidation_patch_manifest"."applied_status" = ANY (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"]))) AS "patches_verified",
    ( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_patch_manifest"
          WHERE ("consolidation_patch_manifest"."required" AND ("consolidation_patch_manifest"."applied_status" <> ALL (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"])))) AS "patches_not_verified",
    ( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_defects"
          WHERE ("consolidation_defects"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"]))) AS "open_defects",
    ( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_defects"
          WHERE (("consolidation_defects"."severity" = 'critical'::"public"."v35_severity") AND ("consolidation_defects"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"])))) AS "critical_open_defects",
    ( SELECT "count"(*) AS "count"
           FROM "public"."real_data_repair_queue"
          WHERE ("real_data_repair_queue"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"]))) AS "open_data_repairs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."go_live_sop_steps"
          WHERE ("go_live_sop_steps"."required" AND ("go_live_sop_steps"."status" <> ALL (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"])))) AS "sop_steps_remaining",
    (GREATEST((0)::bigint, LEAST((100)::bigint, (((((100 - (( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_patch_manifest"
          WHERE ("consolidation_patch_manifest"."required" AND ("consolidation_patch_manifest"."applied_status" <> ALL (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"])))) * 4)) - (( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_defects"
          WHERE (("consolidation_defects"."severity" = 'critical'::"public"."v35_severity") AND ("consolidation_defects"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"])))) * 20)) - (( SELECT "count"(*) AS "count"
           FROM "public"."consolidation_defects"
          WHERE (("consolidation_defects"."severity" = 'high'::"public"."v35_severity") AND ("consolidation_defects"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"])))) * 8)) - (( SELECT "count"(*) AS "count"
           FROM "public"."real_data_repair_queue"
          WHERE (("real_data_repair_queue"."severity" = ANY (ARRAY['critical'::"public"."v35_severity", 'high'::"public"."v35_severity"])) AND ("real_data_repair_queue"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"])))) * 6)) - (( SELECT "count"(*) AS "count"
           FROM "public"."go_live_sop_steps"
          WHERE ("go_live_sop_steps"."required" AND ("go_live_sop_steps"."status" <> ALL (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"])))) * 3)))))::integer AS "consolidation_readiness_score";

CREATE OR REPLACE VIEW "public"."v35_data_quality_radar" WITH ("security_invoker"='true') AS
 SELECT "source_area",
    "count"(*) AS "total_issues",
    "count"(*) FILTER (WHERE ("severity" = ANY (ARRAY['critical'::"public"."v35_severity", 'high'::"public"."v35_severity"]))) AS "high_issues",
    "count"(*) FILTER (WHERE ("status" = ANY (ARRAY['closed'::"public"."v35_item_status", 'passed'::"public"."v35_item_status"]))) AS "closed_issues",
    "count"(*) FILTER (WHERE ("status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status", 'passed'::"public"."v35_item_status"]))) AS "open_issues",
        CASE
            WHEN ("count"(*) = 0) THEN (100)::numeric
            ELSE "round"(((100.0 * ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['closed'::"public"."v35_item_status", 'passed'::"public"."v35_item_status"]))))::numeric) / ("count"(*))::numeric), 1)
        END AS "closure_percent"
   FROM "public"."real_data_repair_queue"
  GROUP BY "source_area";

CREATE OR REPLACE VIEW "public"."v35_final_blocker_board" WITH ("security_invoker"='true') AS
 SELECT 'Patch verification'::"text" AS "blocker_area",
    "consolidation_patch_manifest"."patch_version" AS "reference",
    "consolidation_patch_manifest"."patch_name" AS "title",
    ("consolidation_patch_manifest"."applied_status")::"text" AS "status",
        CASE
            WHEN "consolidation_patch_manifest"."required" THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "severity",
    "consolidation_patch_manifest"."verification_note" AS "note"
   FROM "public"."consolidation_patch_manifest"
  WHERE ("consolidation_patch_manifest"."required" AND ("consolidation_patch_manifest"."applied_status" <> ALL (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"])))
UNION ALL
 SELECT 'Consolidation defect'::"text" AS "blocker_area",
    "consolidation_defects"."defect_code" AS "reference",
    "consolidation_defects"."title",
    ("consolidation_defects"."status")::"text" AS "status",
    ("consolidation_defects"."severity")::"text" AS "severity",
    "consolidation_defects"."description" AS "note"
   FROM "public"."consolidation_defects"
  WHERE (("consolidation_defects"."severity" = ANY (ARRAY['critical'::"public"."v35_severity", 'high'::"public"."v35_severity"])) AND ("consolidation_defects"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"])))
UNION ALL
 SELECT 'Data repair'::"text" AS "blocker_area",
    "real_data_repair_queue"."repair_code" AS "reference",
    "real_data_repair_queue"."issue_title" AS "title",
    ("real_data_repair_queue"."status")::"text" AS "status",
    ("real_data_repair_queue"."severity")::"text" AS "severity",
    "real_data_repair_queue"."issue_description" AS "note"
   FROM "public"."real_data_repair_queue"
  WHERE (("real_data_repair_queue"."severity" = ANY (ARRAY['critical'::"public"."v35_severity", 'high'::"public"."v35_severity"])) AND ("real_data_repair_queue"."status" <> ALL (ARRAY['closed'::"public"."v35_item_status", 'deferred'::"public"."v35_item_status"])))
UNION ALL
 SELECT 'Go-live SOP'::"text" AS "blocker_area",
    ("go_live_sop_steps"."step_order")::"text" AS "reference",
    "go_live_sop_steps"."step_title" AS "title",
    ("go_live_sop_steps"."status")::"text" AS "status",
        CASE
            WHEN "go_live_sop_steps"."required" THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "severity",
    "go_live_sop_steps"."step_description" AS "note"
   FROM "public"."go_live_sop_steps"
  WHERE ("go_live_sop_steps"."required" AND ("go_live_sop_steps"."status" <> ALL (ARRAY['passed'::"public"."v35_item_status", 'ready'::"public"."v35_item_status", 'closed'::"public"."v35_item_status"])));

CREATE OR REPLACE VIEW "public"."v35_operator_console" WITH ("security_invoker"='true') AS
 SELECT CURRENT_DATE AS "business_date",
    ( SELECT "v35_consolidation_scorecard"."consolidation_readiness_score"
           FROM "public"."v35_consolidation_scorecard") AS "readiness_score",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v35_final_blocker_board") AS "active_blockers",
    ( SELECT "count"(*) AS "count"
           FROM "public"."cutover_freeze_windows"
          WHERE (("now"() >= "cutover_freeze_windows"."starts_at") AND ("now"() <= "cutover_freeze_windows"."ends_at") AND ("cutover_freeze_windows"."status" = ANY (ARRAY['ready'::"public"."v35_item_status", 'passed'::"public"."v35_item_status", 'in_progress'::"public"."v35_item_status"])))) AS "active_freeze_windows",
    ( SELECT "count"(*) AS "count"
           FROM "public"."production_operator_daily_log"
          WHERE ("production_operator_daily_log"."log_date" = CURRENT_DATE)) AS "today_operator_logs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."pilot_fix_sprints"
          WHERE ("pilot_fix_sprints"."status" = ANY (ARRAY['not_started'::"public"."v35_item_status", 'in_progress'::"public"."v35_item_status", 'blocked'::"public"."v35_item_status"]))) AS "active_fix_sprints";

