CREATE OR REPLACE VIEW "public"."v_access_control_matrix" AS
SELECT
    NULL::"uuid" AS "organization_id",
    NULL::"uuid" AS "user_id",
    NULL::"text" AS "employee_no",
    NULL::"text" AS "full_name_en",
    NULL::"text" AS "full_name_ar",
    NULL::"text" AS "email",
    NULL::"text" AS "job_title",
    NULL::boolean AS "user_active",
    NULL::"text" AS "division_name",
    NULL::"text" AS "department_name",
    NULL::"text" AS "unit_name",
    NULL::bigint AS "active_role_count",
    NULL::"jsonb" AS "roles",
    NULL::bigint AS "owned_open_projects",
    NULL::bigint AS "open_tasks",
    NULL::bigint AS "pending_approvals";

CREATE OR REPLACE VIEW "public"."v_access_control_warnings" WITH ("security_invoker"='true') AS
 WITH "active_roles" AS (
         SELECT "ur"."id",
            "ur"."user_id",
            "ur"."role",
            "ur"."scope",
            "ur"."organization_id",
            "ur"."division_id",
            "ur"."department_id",
            "ur"."unit_id",
            "ur"."is_active",
            "ur"."assigned_by",
            "ur"."assigned_at",
            "p"."full_name_en",
            "p"."email",
            "p"."employee_no",
            "p"."department_id" AS "profile_department_id",
            "p"."unit_id" AS "profile_unit_id"
           FROM ("public"."user_roles" "ur"
             JOIN "public"."profiles" "p" ON (("p"."id" = "ur"."user_id")))
          WHERE ("ur"."is_active" = true)
        )
 SELECT "gen_random_uuid"() AS "id",
    "active_roles"."organization_id",
    "active_roles"."user_id",
    "active_roles"."full_name_en",
    "active_roles"."email",
    'global_sensitive_role'::"text" AS "warning_type",
    'Global role granted. Confirm this user really needs company-wide access.'::"text" AS "warning_message",
    'high'::"public"."risk_level" AS "severity"
   FROM "active_roles"
  WHERE (("active_roles"."scope" = 'global'::"public"."access_scope") AND ("active_roles"."role" = ANY (ARRAY['super_admin'::"public"."app_role", 'executive'::"public"."app_role", 'governance_admin'::"public"."app_role", 'auditor'::"public"."app_role"])))
UNION ALL
 SELECT "gen_random_uuid"() AS "id",
    "active_roles"."organization_id",
    "active_roles"."user_id",
    "active_roles"."full_name_en",
    "active_roles"."email",
    'role_scope_mismatch'::"text" AS "warning_type",
    'Department manager role should normally use department scope.'::"text" AS "warning_message",
    'medium'::"public"."risk_level" AS "severity"
   FROM "active_roles"
  WHERE (("active_roles"."role" = 'department_manager'::"public"."app_role") AND ("active_roles"."scope" <> ALL (ARRAY['department'::"public"."access_scope", 'unit'::"public"."access_scope"])))
UNION ALL
 SELECT "gen_random_uuid"() AS "id",
    "active_roles"."organization_id",
    "active_roles"."user_id",
    "active_roles"."full_name_en",
    "active_roles"."email",
    'employee_with_broad_scope'::"text" AS "warning_type",
    'Employee/viewer role has broad scope. Use assigned_only unless intentionally expanded.'::"text" AS "warning_message",
    'medium'::"public"."risk_level" AS "severity"
   FROM "active_roles"
  WHERE (("active_roles"."role" = ANY (ARRAY['employee'::"public"."app_role", 'viewer'::"public"."app_role"])) AND ("active_roles"."scope" <> ALL (ARRAY['assigned_only'::"public"."access_scope", 'unit'::"public"."access_scope"])))
UNION ALL
 SELECT "gen_random_uuid"() AS "id",
    "active_roles"."organization_id",
    "active_roles"."user_id",
    "active_roles"."full_name_en",
    "active_roles"."email",
    'missing_scope_reference'::"text" AS "warning_type",
    'Scoped role is missing the required division/department/unit reference.'::"text" AS "warning_message",
    'high'::"public"."risk_level" AS "severity"
   FROM "active_roles"
  WHERE ((("active_roles"."scope" = 'division'::"public"."access_scope") AND ("active_roles"."division_id" IS NULL)) OR (("active_roles"."scope" = 'department'::"public"."access_scope") AND ("active_roles"."department_id" IS NULL)) OR (("active_roles"."scope" = 'unit'::"public"."access_scope") AND ("active_roles"."unit_id" IS NULL)));

CREATE OR REPLACE VIEW "public"."v_access_control_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "count"(DISTINCT "p"."id") FILTER (WHERE ("p"."is_active" = true)) AS "active_users",
    "count"(DISTINCT "p"."id") FILTER (WHERE ("p"."is_active" = false)) AS "inactive_users",
    "count"("ur"."id") FILTER (WHERE ("ur"."is_active" = true)) AS "active_role_assignments",
    "count"("ur"."id") FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."scope" = 'global'::"public"."access_scope"))) AS "global_role_assignments",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_access_control_warnings" "w"
          WHERE ("w"."organization_id" = "o"."id")) AS "access_warnings",
    "count"(DISTINCT "p"."id") FILTER (WHERE (("p"."is_active" = true) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."user_roles" "ur2"
          WHERE (("ur2"."user_id" = "p"."id") AND ("ur2"."is_active" = true))))))) AS "active_users_without_roles"
   FROM (("public"."organizations" "o"
     LEFT JOIN "public"."profiles" "p" ON (("p"."organization_id" = "o"."id")))
     LEFT JOIN "public"."user_roles" "ur" ON (("ur"."user_id" = "p"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_accreditation_gap_dashboard" WITH ("security_invoker"='true') AS
 SELECT "gf"."organization_id",
    "s"."code" AS "standard_code",
    "v"."version_label",
    "r"."requirement_code",
    "r"."title_en" AS "requirement_title_en",
    "gf"."severity",
    "gf"."gap_status",
    ("count"(*))::integer AS "gap_count",
    "min"("gf"."due_date") AS "nearest_due_date"
   FROM ((("public"."accreditation_gap_findings" "gf"
     JOIN "public"."accreditation_requirements" "r" ON (("r"."id" = "gf"."requirement_id")))
     JOIN "public"."accreditation_standard_versions" "v" ON (("v"."id" = "r"."standard_version_id")))
     JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "v"."standard_id")))
  GROUP BY "gf"."organization_id", "s"."code", "v"."version_label", "r"."requirement_code", "r"."title_en", "gf"."severity", "gf"."gap_status";

CREATE OR REPLACE VIEW "public"."v_accreditation_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT "s"."code" AS "standard_code",
    "s"."name_en" AS "standard_name_en",
    "s"."name_ar" AS "standard_name_ar",
    "v"."id" AS "standard_version_id",
    "v"."version_label",
    "v"."content_status",
    "v"."approval_status",
    ("count"(DISTINCT "c"."id"))::integer AS "chapter_count",
    ("count"(DISTINCT "r"."id"))::integer AS "requirement_count",
    ("count"(DISTINCT "me"."id"))::integer AS "measurable_element_count",
    ("count"(DISTINCT "ev"."id"))::integer AS "evidence_rule_count",
    ("count"(DISTINCT "gf"."id"))::integer AS "open_gap_count",
    "max"("rs"."generated_at") AS "latest_snapshot_at",
    ( SELECT "rs2"."readiness_score"
           FROM "public"."accreditation_readiness_snapshots" "rs2"
          WHERE ("rs2"."standard_version_id" = "v"."id")
          ORDER BY "rs2"."generated_at" DESC
         LIMIT 1) AS "latest_readiness_score"
   FROM ((((((("public"."accreditation_standards" "s"
     JOIN "public"."accreditation_standard_versions" "v" ON (("v"."standard_id" = "s"."id")))
     LEFT JOIN "public"."accreditation_chapters" "c" ON ((("c"."standard_version_id" = "v"."id") AND "c"."is_active")))
     LEFT JOIN "public"."accreditation_requirements" "r" ON ((("r"."standard_version_id" = "v"."id") AND "r"."is_active")))
     LEFT JOIN "public"."accreditation_measurable_elements" "me" ON ((("me"."requirement_id" = "r"."id") AND "me"."is_active")))
     LEFT JOIN "public"."accreditation_required_evidence" "ev" ON ((("ev"."measurable_element_id" = "me"."id") AND "ev"."is_required")))
     LEFT JOIN "public"."accreditation_gap_findings" "gf" ON ((("gf"."requirement_id" = "r"."id") AND ("gf"."gap_status" <> ALL (ARRAY['closed'::"text", 'deferred'::"text"])))))
     LEFT JOIN "public"."accreditation_readiness_snapshots" "rs" ON (("rs"."standard_version_id" = "v"."id")))
  WHERE "s"."is_active"
  GROUP BY "s"."code", "s"."name_en", "s"."name_ar", "v"."id", "v"."version_label", "v"."content_status", "v"."approval_status";

CREATE OR REPLACE VIEW "public"."v_accreditation_requirement_matrix" WITH ("security_invoker"='true') AS
 SELECT "s"."code" AS "standard_code",
    "v"."version_label",
    "c"."chapter_code",
    "c"."title_en" AS "chapter_title_en",
    "r"."id" AS "requirement_id",
    "r"."requirement_code",
    "r"."title_en" AS "requirement_title_en",
    "r"."title_ar" AS "requirement_title_ar",
    "r"."requirement_type",
    "r"."priority",
    ("count"(DISTINCT "me"."id"))::integer AS "measurable_element_count",
    ("count"(DISTINCT "ev"."id"))::integer AS "evidence_rule_count",
    ("count"(DISTINCT "x"."id"))::integer AS "crosswalk_count"
   FROM (((((("public"."accreditation_standards" "s"
     JOIN "public"."accreditation_standard_versions" "v" ON (("v"."standard_id" = "s"."id")))
     JOIN "public"."accreditation_chapters" "c" ON (("c"."standard_version_id" = "v"."id")))
     JOIN "public"."accreditation_requirements" "r" ON (("r"."chapter_id" = "c"."id")))
     LEFT JOIN "public"."accreditation_measurable_elements" "me" ON ((("me"."requirement_id" = "r"."id") AND "me"."is_active")))
     LEFT JOIN "public"."accreditation_required_evidence" "ev" ON ((("ev"."measurable_element_id" = "me"."id") AND "ev"."is_required")))
     LEFT JOIN "public"."accreditation_crosswalk_mappings" "x" ON (("x"."requirement_id" = "r"."id")))
  GROUP BY "s"."code", "v"."version_label", "c"."chapter_code", "c"."title_en", "r"."id", "r"."requirement_code", "r"."title_en", "r"."title_ar", "r"."requirement_type", "r"."priority";

CREATE OR REPLACE VIEW "public"."v_activity_timeline" WITH ("security_invoker"='true') AS
 SELECT "al"."organization_id",
    'audit_log'::"text" AS "event_source",
    "al"."table_name" AS "item_type",
    "al"."record_id" AS "item_id",
    "al"."action" AS "event_title",
    COALESCE("pr"."full_name_en", 'System'::"text") AS "actor_name_en",
    COALESCE("pr"."full_name_ar", 'النظام'::"text") AS "actor_name_ar",
    "al"."created_at",
    "al"."new_data" AS "payload"
   FROM ("public"."audit_logs" "al"
     LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "al"."actor_id")))
UNION ALL
 SELECT "fn"."organization_id",
    'followup_note'::"text" AS "event_source",
    "fn"."item_type",
    "fn"."item_id",
    "left"("fn"."note", 120) AS "event_title",
    COALESCE("pr"."full_name_en", 'System'::"text") AS "actor_name_en",
    COALESCE("pr"."full_name_ar", 'النظام'::"text") AS "actor_name_ar",
    "fn"."created_at",
    "jsonb_build_object"('followup_date', "fn"."followup_date", 'resolved_at', "fn"."resolved_at") AS "payload"
   FROM ("public"."followup_notes" "fn"
     LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "fn"."created_by")))
UNION ALL
 SELECT "n"."organization_id",
    'notification'::"text" AS "event_source",
    'notification'::"text" AS "item_type",
    "n"."id" AS "item_id",
    "n"."title" AS "event_title",
    COALESCE("pr"."full_name_en", 'System'::"text") AS "actor_name_en",
    COALESCE("pr"."full_name_ar", 'النظام'::"text") AS "actor_name_ar",
    "n"."created_at",
    "jsonb_build_object"('body', "n"."body", 'link_path', "n"."link_path", 'is_read', "n"."is_read") AS "payload"
   FROM ("public"."notifications" "n"
     LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "n"."user_id")));

CREATE OR REPLACE VIEW "public"."v_admin_safety_console" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."organization_id",
    'Safety lock'::"text" AS "area",
    "l"."title" AS "finding",
    "l"."lock_level" AS "severity",
        CASE
            WHEN "l"."is_active" THEN 'open'::"text"
            ELSE 'closed'::"text"
        END AS "status",
    ("l"."description" ||
        CASE
            WHEN "l"."requires_backup" THEN ' Backup required.'::"text"
            ELSE ''::"text"
        END) AS "recommendation",
    'System Admin'::"text" AS "owner",
        CASE "l"."lock_level"
            WHEN 'critical'::"text" THEN 1
            WHEN 'high'::"text" THEN 2
            WHEN 'medium'::"text" THEN 3
            ELSE 4
        END AS "severity_rank"
   FROM "public"."admin_safety_locks" "l"
  WHERE ("l"."is_active" = true)
UNION ALL
 SELECT "c"."id",
    "c"."organization_id",
    'Change request'::"text" AS "area",
    "c"."title" AS "finding",
        CASE
            WHEN ("c"."status" = 'pending'::"text") THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "severity",
    "c"."status",
    COALESCE("c"."description", 'Administrative change requires review.'::"text") AS "recommendation",
    COALESCE("p"."full_name_en", 'Requester'::"text") AS "owner",
        CASE
            WHEN ("c"."status" = 'pending'::"text") THEN 2
            ELSE 3
        END AS "severity_rank"
   FROM ("public"."admin_change_requests" "c"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "c"."requested_by")))
  WHERE ("c"."status" = ANY (ARRAY['pending'::"text", 'approved'::"text"]));

CREATE OR REPLACE VIEW "public"."v_assurance_external_auditor_portal" WITH ("security_invoker"='true') AS
 SELECT "s"."organization_id",
    "p"."package_code",
    "p"."package_title",
    "p"."package_status",
    "s"."auditor_name",
    "s"."auditor_email",
    "s"."access_scope",
    "s"."session_status",
    "s"."starts_at",
    "s"."expires_at",
    "s"."last_accessed_at"
   FROM ("public"."assurance_external_auditor_portal_sessions" "s"
     LEFT JOIN "public"."assurance_external_auditor_packages" "p" ON (("p"."id" = "s"."package_id")));

CREATE OR REPLACE VIEW "public"."v_assurance_gate_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "gate_code",
    "gate_name",
    "gate_area",
    "gate_owner_name",
    "is_critical",
    "gate_status",
    "evidence_required_count",
    "evidence_accepted_count",
    "due_date",
        CASE
            WHEN ("is_critical" AND ("gate_status" <> 'approved'::"text")) THEN 'critical_not_approved'::"text"
            WHEN ("evidence_required_count" > "evidence_accepted_count") THEN 'evidence_gap'::"text"
            WHEN (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("gate_status" <> 'approved'::"text")) THEN 'overdue'::"text"
            ELSE 'normal'::"text"
        END AS "gate_signal"
   FROM "public"."assurance_go_live_gates";

CREATE OR REPLACE VIEW "public"."v_assurance_go_live_summary" WITH ("security_invoker"='true') AS
 SELECT "org"."organization_id",
    COALESCE("g"."critical_gate_count", 0) AS "critical_gate_count",
    COALESCE("g"."critical_gate_not_approved_count", 0) AS "critical_gate_not_approved_count",
    COALESCE("s"."signoff_required_count", 0) AS "signoff_required_count",
    COALESCE("s"."signoff_signed_count", 0) AS "signoff_signed_count",
    COALESCE("r"."restore_exercise_count", 0) AS "restore_exercise_count",
    COALESCE("r"."failed_restore_exercise_count", 0) AS "failed_restore_exercise_count",
    COALESCE("t"."training_campaign_count", 0) AS "training_campaign_count",
    COALESCE("t"."training_overdue_count", 0) AS "training_overdue_count",
    COALESCE("m"."monitoring_check_count", 0) AS "monitoring_check_count",
    COALESCE("m"."monitoring_failed_count", 0) AS "monitoring_failed_count",
    COALESCE("p"."open_auditor_session_count", 0) AS "open_auditor_session_count",
    COALESCE("d"."go_decision_count", 0) AS "go_decision_count"
   FROM (((((((( SELECT "assurance_go_live_gates"."organization_id"
           FROM "public"."assurance_go_live_gates"
        UNION
         SELECT "assurance_go_live_signoffs"."organization_id"
           FROM "public"."assurance_go_live_signoffs"
        UNION
         SELECT "assurance_rollback_restore_exercises"."organization_id"
           FROM "public"."assurance_rollback_restore_exercises"
        UNION
         SELECT "assurance_training_records"."organization_id"
           FROM "public"."assurance_training_records"
        UNION
         SELECT "assurance_monitoring_readiness_checks"."organization_id"
           FROM "public"."assurance_monitoring_readiness_checks"
        UNION
         SELECT "assurance_external_auditor_portal_sessions"."organization_id"
           FROM "public"."assurance_external_auditor_portal_sessions"
        UNION
         SELECT "assurance_production_decisions"."organization_id"
           FROM "public"."assurance_production_decisions") "org"
     LEFT JOIN ( SELECT "assurance_go_live_gates"."organization_id",
            ("count"(*) FILTER (WHERE "assurance_go_live_gates"."is_critical"))::integer AS "critical_gate_count",
            ("count"(*) FILTER (WHERE ("assurance_go_live_gates"."is_critical" AND ("assurance_go_live_gates"."gate_status" <> 'approved'::"text"))))::integer AS "critical_gate_not_approved_count"
           FROM "public"."assurance_go_live_gates"
          GROUP BY "assurance_go_live_gates"."organization_id") "g" ON (("g"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "assurance_go_live_signoffs"."organization_id",
            ("count"(*))::integer AS "signoff_required_count",
            ("count"(*) FILTER (WHERE ("assurance_go_live_signoffs"."signoff_status" = 'signed'::"text")))::integer AS "signoff_signed_count"
           FROM "public"."assurance_go_live_signoffs"
          GROUP BY "assurance_go_live_signoffs"."organization_id") "s" ON (("s"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "assurance_rollback_restore_exercises"."organization_id",
            ("count"(*))::integer AS "restore_exercise_count",
            ("count"(*) FILTER (WHERE ("assurance_rollback_restore_exercises"."exercise_status" = 'failed'::"text")))::integer AS "failed_restore_exercise_count"
           FROM "public"."assurance_rollback_restore_exercises"
          GROUP BY "assurance_rollback_restore_exercises"."organization_id") "r" ON (("r"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "assurance_training_records"."organization_id",
            ("count"(*))::integer AS "training_campaign_count",
            (COALESCE("sum"("assurance_training_records"."overdue_count"), (0)::bigint))::integer AS "training_overdue_count"
           FROM "public"."assurance_training_records"
          GROUP BY "assurance_training_records"."organization_id") "t" ON (("t"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "assurance_monitoring_readiness_checks"."organization_id",
            ("count"(*))::integer AS "monitoring_check_count",
            ("count"(*) FILTER (WHERE ("assurance_monitoring_readiness_checks"."check_status" = 'failed'::"text")))::integer AS "monitoring_failed_count"
           FROM "public"."assurance_monitoring_readiness_checks"
          GROUP BY "assurance_monitoring_readiness_checks"."organization_id") "m" ON (("m"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "assurance_external_auditor_portal_sessions"."organization_id",
            ("count"(*) FILTER (WHERE ("assurance_external_auditor_portal_sessions"."session_status" = ANY (ARRAY['approved'::"text", 'active'::"text"]))))::integer AS "open_auditor_session_count"
           FROM "public"."assurance_external_auditor_portal_sessions"
          GROUP BY "assurance_external_auditor_portal_sessions"."organization_id") "p" ON (("p"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "assurance_production_decisions"."organization_id",
            ("count"(*) FILTER (WHERE ("assurance_production_decisions"."decision_status" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"]))))::integer AS "go_decision_count"
           FROM "public"."assurance_production_decisions"
          GROUP BY "assurance_production_decisions"."organization_id") "d" ON (("d"."organization_id" = "org"."organization_id")));

COMMENT ON VIEW "public"."v_assurance_go_live_summary" IS 'Patch 8 assurance summary; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_assurance_signoff_readiness" WITH ("security_invoker"='true') AS
 SELECT "assurance_go_live_signoffs"."organization_id",
    'signoff'::"text" AS "readiness_type",
    "assurance_go_live_signoffs"."signoff_code" AS "item_code",
    "assurance_go_live_signoffs"."signoff_area" AS "item_area",
    "assurance_go_live_signoffs"."signoff_owner_name" AS "owner_name",
    "assurance_go_live_signoffs"."signoff_status" AS "item_status",
        CASE
            WHEN ("assurance_go_live_signoffs"."signoff_status" = 'signed'::"text") THEN 'ready'::"text"
            WHEN ("assurance_go_live_signoffs"."signoff_status" = 'rejected'::"text") THEN 'blocked'::"text"
            ELSE 'pending'::"text"
        END AS "readiness_signal"
   FROM "public"."assurance_go_live_signoffs"
UNION ALL
 SELECT "assurance_training_records"."organization_id",
    'training'::"text" AS "readiness_type",
    "assurance_training_records"."training_code" AS "item_code",
    "assurance_training_records"."target_role" AS "item_area",
    "assurance_training_records"."owner_name",
    "assurance_training_records"."training_status" AS "item_status",
        CASE
            WHEN ("assurance_training_records"."overdue_count" > 0) THEN 'blocked'::"text"
            WHEN ("assurance_training_records"."training_status" = 'completed'::"text") THEN 'ready'::"text"
            ELSE 'pending'::"text"
        END AS "readiness_signal"
   FROM "public"."assurance_training_records"
UNION ALL
 SELECT "assurance_rollback_restore_exercises"."organization_id",
    'restore'::"text" AS "readiness_type",
    "assurance_rollback_restore_exercises"."exercise_code" AS "item_code",
    "assurance_rollback_restore_exercises"."exercise_type" AS "item_area",
    "assurance_rollback_restore_exercises"."owner_name",
    "assurance_rollback_restore_exercises"."exercise_status" AS "item_status",
        CASE
            WHEN ("assurance_rollback_restore_exercises"."exercise_status" = 'passed'::"text") THEN 'ready'::"text"
            WHEN ("assurance_rollback_restore_exercises"."exercise_status" = 'failed'::"text") THEN 'blocked'::"text"
            ELSE 'pending'::"text"
        END AS "readiness_signal"
   FROM "public"."assurance_rollback_restore_exercises"
UNION ALL
 SELECT "assurance_monitoring_readiness_checks"."organization_id",
    'monitoring'::"text" AS "readiness_type",
    "assurance_monitoring_readiness_checks"."check_code" AS "item_code",
    "assurance_monitoring_readiness_checks"."check_area" AS "item_area",
    "assurance_monitoring_readiness_checks"."alert_owner_name" AS "owner_name",
    "assurance_monitoring_readiness_checks"."check_status" AS "item_status",
        CASE
            WHEN ("assurance_monitoring_readiness_checks"."check_status" = 'tested'::"text") THEN 'ready'::"text"
            WHEN ("assurance_monitoring_readiness_checks"."check_status" = 'failed'::"text") THEN 'blocked'::"text"
            ELSE 'pending'::"text"
        END AS "readiness_signal"
   FROM "public"."assurance_monitoring_readiness_checks";

CREATE OR REPLACE VIEW "public"."v_automation_command_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "count"(DISTINCT "ar"."id") FILTER (WHERE "ar"."is_active") AS "active_rules",
    "count"(DISTINCT "rr"."id") FILTER (WHERE ("rr"."is_active" AND ("rr"."next_due_date" <= (CURRENT_DATE + '7 days'::interval)))) AS "reviews_due_7_days",
    "count"(DISTINCT "rr"."id") FILTER (WHERE ("rr"."is_active" AND ("rr"."next_due_date" < CURRENT_DATE) AND ("rr"."status" <> 'completed'::"public"."review_status"))) AS "overdue_reviews",
    "count"(DISTINCT "ko"."id") FILTER (WHERE (("ko"."breach_level" = ANY (ARRAY['warning'::"public"."breach_level", 'critical'::"public"."breach_level"])) AND ("ko"."observed_at" >= (CURRENT_DATE - '30 days'::interval)))) AS "kri_breaches_30_days",
    "count"(DISTINCT "ko"."id") FILTER (WHERE (("ko"."breach_level" = 'critical'::"public"."breach_level") AND ("ko"."observed_at" >= (CURRENT_DATE - '30 days'::interval)))) AS "critical_kri_breaches_30_days",
    "count"(DISTINCT "eer"."id") FILTER (WHERE ("eer"."is_active" AND "eer"."requires_ceo_visibility")) AS "executive_exception_rules",
    "count"(DISTINCT "al"."id") FILTER (WHERE ("al"."created_at" >= ("now"() - '7 days'::interval))) AS "automation_runs_7_days"
   FROM ((((("public"."organizations" "o"
     LEFT JOIN "public"."automation_rules" "ar" ON (("ar"."organization_id" = "o"."id")))
     LEFT JOIN "public"."recurring_reviews" "rr" ON (("rr"."organization_id" = "o"."id")))
     LEFT JOIN "public"."kri_observations" "ko" ON (("ko"."organization_id" = "o"."id")))
     LEFT JOIN "public"."executive_exception_rules" "eer" ON (("eer"."organization_id" = "o"."id")))
     LEFT JOIN "public"."automation_run_log" "al" ON (("al"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_automation_rule_catalog" WITH ("security_invoker"='true') AS
 SELECT "ar"."id",
    "ar"."organization_id",
    "ar"."rule_code",
    "ar"."title_en",
    "ar"."title_ar",
    "ar"."rule_type",
    "ar"."action_type",
    "ar"."priority",
    "ar"."applies_to_scope",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "ar"."condition_json",
    "ar"."action_json",
    "ar"."is_active",
    "ar"."last_run_at",
    "ar"."run_count",
        CASE
            WHEN ("ar"."last_run_at" IS NULL) THEN 'never_run'::"text"
            WHEN ("ar"."last_run_at" < ("now"() - '7 days'::interval)) THEN 'stale'::"text"
            ELSE 'healthy'::"text"
        END AS "rule_health"
   FROM ("public"."automation_rules" "ar"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "ar"."department_id")));

CREATE OR REPLACE VIEW "public"."v_backup_health_check" WITH ("security_invoker"='true') AS
 WITH "orgs" AS (
         SELECT "organizations"."id",
            "organizations"."name_en",
            "organizations"."name_ar"
           FROM "public"."organizations"
        )
 SELECT "o"."id" AS "organization_id",
    'duplicate_department_codes'::"text" AS "check_key",
    'critical'::"text" AS "severity",
    'organization'::"text" AS "area",
    'Duplicate active department codes'::"text" AS "title_en",
    'رموز أقسام نشطة مكررة'::"text" AS "title_ar",
    'Active department codes must be unique after trimming and lower-casing.'::"text" AS "details_en",
    'يجب ألا تتكرر رموز الأقسام النشطة بعد إزالة الفراغات وتوحيد حالة الأحرف.'::"text" AS "details_ar",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM ( SELECT "lower"(TRIM(BOTH FROM "d"."code")) AS "normalized_code"
                   FROM "public"."departments" "d"
                  WHERE (("d"."organization_id" = "o"."id") AND ("d"."is_active" = true) AND ("d"."code" IS NOT NULL))
                  GROUP BY ("lower"(TRIM(BOTH FROM "d"."code")))
                 HAVING ("count"(*) > 1)) "x"), (0)::bigint))::integer AS "record_count",
    '/admin/import-export'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'duplicate_unit_codes'::"text" AS "check_key",
    'critical'::"text" AS "severity",
    'organization'::"text" AS "area",
    'Duplicate active unit/station codes'::"text" AS "title_en",
    'رموز وحدات/محطات نشطة مكررة'::"text" AS "title_ar",
    'Active unit/station codes must be unique inside the same department.'::"text" AS "details_en",
    'يجب ألا تتكرر رموز الوحدات/المحطات النشطة داخل نفس القسم.'::"text" AS "details_ar",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM ( SELECT "u"."department_id",
                    "lower"(TRIM(BOTH FROM "u"."code")) AS "normalized_code"
                   FROM "public"."units" "u"
                  WHERE (("u"."organization_id" = "o"."id") AND ("u"."is_active" = true) AND ("u"."code" IS NOT NULL))
                  GROUP BY "u"."department_id", ("lower"(TRIM(BOTH FROM "u"."code")))
                 HAVING ("count"(*) > 1)) "x"), (0)::bigint))::integer AS "record_count",
    '/admin/import-export'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'users_missing_department'::"text" AS "check_key",
    'high'::"text" AS "severity",
    'access'::"text" AS "area",
    'Active users missing department'::"text" AS "title_en",
    'مستخدمون نشطون بدون قسم'::"text" AS "title_ar",
    'Active employees should normally be assigned to a department for scoped access and reporting.'::"text" AS "details_en",
    'يجب عادة ربط المستخدمين النشطين بقسم لضبط الصلاحيات والتقارير.'::"text" AS "details_ar",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."profiles" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."is_active" = true) AND ("p"."department_id" IS NULL))), (0)::bigint))::integer AS "record_count",
    '/access-control'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'projects_missing_owner_or_due_date'::"text" AS "check_key",
    'high'::"text" AS "severity",
    'projects'::"text" AS "area",
    'Active projects missing owner or due date'::"text" AS "title_en",
    'مشاريع نشطة بدون مالك أو تاريخ مستهدف'::"text" AS "title_ar",
    'Every active project/action plan needs an owner and target end date.'::"text" AS "details_en",
    'كل مشروع أو خطة عمل نشطة تحتاج إلى مالك وتاريخ انتهاء مستهدف.'::"text" AS "details_ar",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND (("p"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND (("p"."owner_id" IS NULL) OR ("p"."target_end_date" IS NULL)))), (0)::bigint))::integer AS "record_count",
    '/projects'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'overdue_items_without_delay_reason'::"text" AS "check_key",
    'critical'::"text" AS "severity",
    'workflow'::"text" AS "area",
    'Overdue items missing delay reason'::"text" AS "title_en",
    'بنود متأخرة بدون سبب تأخير'::"text" AS "title_ar",
    'Overdue projects, milestones, and tasks must have a delay reason for governance tracking.'::"text" AS "details_en",
    'يجب تسجيل سبب التأخير للمشاريع والمراحل والمهام المتأخرة.'::"text" AS "details_ar",
    (((COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."target_end_date" < CURRENT_DATE) AND (("p"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND (COALESCE(TRIM(BOTH FROM "p"."delay_reason"), ''::"text") = ''::"text"))), (0)::bigint) + COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."milestones" "m"
          WHERE (("m"."organization_id" = "o"."id") AND ("m"."due_date" < CURRENT_DATE) AND (("m"."status")::"text" <> ALL (ARRAY['closed'::"text", 'approved'::"text", 'cancelled'::"text"])) AND (COALESCE(TRIM(BOTH FROM "m"."delay_reason"), ''::"text") = ''::"text"))), (0)::bigint)) + COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE (("t"."organization_id" = "o"."id") AND ("t"."due_date" < CURRENT_DATE) AND (("t"."status")::"text" <> ALL (ARRAY['closed'::"text", 'approved'::"text", 'cancelled'::"text"])) AND (COALESCE(TRIM(BOTH FROM "t"."delay_reason"), ''::"text") = ''::"text"))), (0)::bigint)))::integer AS "record_count",
    '/escalations'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'pending_approvals_older_than_14_days'::"text" AS "check_key",
    'high'::"text" AS "severity",
    'approvals'::"text" AS "area",
    'Pending approvals older than 14 days'::"text" AS "title_en",
    'اعتمادات معلقة لأكثر من 14 يوم'::"text" AS "title_ar",
    'Old pending approvals create execution bottlenecks and accountability risk.'::"text" AS "details_en",
    'الاعتمادات القديمة المعلقة تسبب تعطل التنفيذ ومخاطر في المساءلة.'::"text" AS "details_ar",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."organization_id" = "o"."id") AND (("a"."status")::"text" = 'pending'::"text") AND ("a"."requested_at" < ("now"() - '14 days'::interval)))), (0)::bigint))::integer AS "record_count",
    '/approvals'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'ovr_stuck_quality_review'::"text" AS "check_key",
    'critical'::"text" AS "severity",
    'ovr'::"text" AS "area",
    'OVRs stuck in Quality review'::"text" AS "title_en",
    'بلاغات OVR عالقة لدى الجودة'::"text" AS "title_ar",
    'OVRs under Quality review for more than 7 days need escalation.'::"text" AS "details_en",
    'بلاغات OVR الموجودة تحت مراجعة الجودة لأكثر من 7 أيام تحتاج تصعيد.'::"text" AS "details_ar",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "r"
          WHERE (("r"."organization_id" = "o"."id") AND (("r"."status")::"text" = ANY (ARRAY['submitted_to_quality'::"text", 'under_quality_review'::"text", 'quality_review'::"text"])) AND ("r"."created_at" < ("now"() - '7 days'::interval)))), (0)::bigint))::integer AS "record_count",
    '/ovr'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o"
UNION ALL
 SELECT "o"."id" AS "organization_id",
    'old_browser_backup_packages'::"text" AS "check_key",
    'medium'::"text" AS "severity",
    'backup'::"text" AS "area",
    'No recent browser backup package'::"text" AS "title_en",
    'لا توجد حزمة نسخ احتياطي حديثة من المتصفح'::"text" AS "title_ar",
    'Create an external backup package at least weekly during rollout.'::"text" AS "details_en",
    'يفضل إنشاء حزمة نسخ احتياطي خارجية أسبوعياً أثناء مرحلة الإطلاق.'::"text" AS "details_ar",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."backup_packages" "b"
              WHERE (("b"."organization_id" = "o"."id") AND ("b"."created_at" >= ("now"() - '7 days'::interval)) AND ("b"."status" = 'created'::"text")))) THEN 0
            ELSE 1
        END AS "record_count",
    '/admin/import-export'::"text" AS "action_path",
    "now"() AS "created_at"
   FROM "orgs" "o";

COMMENT ON VIEW "public"."v_backup_health_check" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

CREATE OR REPLACE VIEW "public"."v_backup_restore_drillboard" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."organization_id",
    COALESCE("b"."package_name", ("r"."backup_package_id")::"text", 'No package linked'::"text") AS "backup_package_id",
    "r"."scenario_name",
    "r"."status",
    "r"."started_at",
    "r"."finished_at",
    "r"."result_summary",
    "r"."evidence_file",
    "r"."created_at"
   FROM ("public"."restore_dry_run_jobs" "r"
     LEFT JOIN "public"."backup_packages" "b" ON (("b"."id" = "r"."backup_package_id")));

COMMENT ON VIEW "public"."v_backup_restore_drillboard" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

CREATE OR REPLACE VIEW "public"."v_backup_schedule_readiness" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."organization_id",
    "p"."plan_code",
    "p"."title_en",
    COALESCE("p"."title_ar", "p"."title_en") AS "title_ar",
    "p"."frequency",
    "p"."next_due_at",
    "p"."last_run_at",
    "p"."last_status",
    "p"."retention_days",
    "p"."require_restore_dry_run",
        CASE
            WHEN ("p"."is_active" = false) THEN 'inactive'::"text"
            WHEN ("p"."last_run_at" IS NULL) THEN 'never_run'::"text"
            WHEN (("p"."next_due_at" IS NOT NULL) AND ("p"."next_due_at" < "now"())) THEN 'due_now'::"text"
            WHEN ("p"."last_status" = 'failed'::"public"."backup_run_status") THEN 'failed'::"text"
            WHEN ("p"."require_restore_dry_run" AND (NOT (EXISTS ( SELECT 1
               FROM "public"."restore_dry_run_jobs" "j"
              WHERE (("j"."organization_id" = "p"."organization_id") AND ("j"."created_at" >= ("now"() - '30 days'::interval))))))) THEN 'restore_test_due'::"text"
            ELSE 'healthy'::"text"
        END AS "readiness_status",
    (COALESCE("r"."run_count", (0)::bigint))::integer AS "run_count",
    "r"."last_completed_at"
   FROM ("public"."backup_schedule_plans" "p"
     LEFT JOIN ( SELECT "backup_schedule_runs"."plan_id",
            "count"(*) AS "run_count",
            "max"("backup_schedule_runs"."completed_at") AS "last_completed_at"
           FROM "public"."backup_schedule_runs"
          GROUP BY "backup_schedule_runs"."plan_id") "r" ON (("r"."plan_id" = "p"."id")));

CREATE OR REPLACE VIEW "public"."v_bilingual_dictionary_status" WITH ("security_invoker"='true') AS
 SELECT "key",
    "english_label",
    "arabic_label",
    "category",
    "is_core",
        CASE
            WHEN (COALESCE(TRIM(BOTH FROM "english_label"), ''::"text") = ''::"text") THEN 'missing_en'::"text"
            WHEN (COALESCE(TRIM(BOTH FROM "arabic_label"), ''::"text") = ''::"text") THEN 'missing_ar'::"text"
            WHEN "needs_review" THEN 'needs_review'::"text"
            ELSE 'complete'::"text"
        END AS "status"
   FROM "public"."app_translation_dictionary";

CREATE OR REPLACE VIEW "public"."v_department_scorecard_v2" WITH ("security_invoker"='true') AS
 SELECT "d"."id" AS "department_id",
    "d"."organization_id",
    "d"."name_en" AS "department_name_en",
    COALESCE("d"."name_ar", "d"."name_en") AS "department_name_ar",
    (COALESCE("p"."active_projects", (0)::bigint))::integer AS "active_projects",
    (COALESCE("p"."overdue_projects", (0)::bigint))::integer AS "overdue_projects",
    (COALESCE("t"."overdue_tasks", (0)::bigint))::integer AS "overdue_tasks",
    (COALESCE("r"."critical_risks", (0)::bigint))::integer AS "critical_risks",
    (COALESCE("c"."expiring_compliance", (0)::bigint))::integer AS "expiring_compliance",
    (COALESCE("a"."overdue_audit_findings", (0)::bigint))::integer AS "overdue_audit_findings",
    (COALESCE("o"."major_ovrs", (0)::bigint))::integer AS "major_ovrs",
    (COALESCE("o"."open_ovrs", (0)::bigint))::integer AS "open_ovrs",
    (GREATEST((0)::bigint, (100 - ((((((COALESCE("p"."overdue_projects", (0)::bigint) * 10) + (COALESCE("t"."overdue_tasks", (0)::bigint) * 4)) + (COALESCE("r"."critical_risks", (0)::bigint) * 15)) + (COALESCE("c"."expiring_compliance", (0)::bigint) * 8)) + (COALESCE("a"."overdue_audit_findings", (0)::bigint) * 10)) + (COALESCE("o"."major_ovrs", (0)::bigint) * 12)))))::integer AS "control_score",
        CASE
            WHEN ((COALESCE("r"."critical_risks", (0)::bigint) + COALESCE("o"."major_ovrs", (0)::bigint)) >= 3) THEN 'critical'::"public"."scorecard_signal"
            WHEN (((COALESCE("p"."overdue_projects", (0)::bigint) + COALESCE("a"."overdue_audit_findings", (0)::bigint)) + COALESCE("c"."expiring_compliance", (0)::bigint)) >= 5) THEN 'at_risk'::"public"."scorecard_signal"
            WHEN ((COALESCE("t"."overdue_tasks", (0)::bigint) + COALESCE("o"."open_ovrs", (0)::bigint)) >= 8) THEN 'watch'::"public"."scorecard_signal"
            WHEN ((COALESCE("p"."active_projects", (0)::bigint) + COALESCE("o"."open_ovrs", (0)::bigint)) = 0) THEN 'healthy'::"public"."scorecard_signal"
            ELSE 'healthy'::"public"."scorecard_signal"
        END AS "signal",
    COALESCE("n"."executive_note", ''::"text") AS "latest_executive_note",
    "n"."created_at" AS "latest_note_at"
   FROM ((((((("public"."departments" "d"
     LEFT JOIN ( SELECT "projects"."department_id",
            "count"(*) FILTER (WHERE ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"]))) AS "active_projects",
            "count"(*) FILTER (WHERE (("projects"."target_end_date" < CURRENT_DATE) AND ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))) AS "overdue_projects"
           FROM "public"."projects"
          GROUP BY "projects"."department_id") "p" ON (("p"."department_id" = "d"."id")))
     LEFT JOIN ( SELECT "p_1"."department_id",
            "count"(*) FILTER (WHERE (("t_1"."due_date" < CURRENT_DATE) AND ("t_1"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))) AS "overdue_tasks"
           FROM ("public"."tasks" "t_1"
             JOIN "public"."projects" "p_1" ON (("p_1"."id" = "t_1"."project_id")))
          GROUP BY "p_1"."department_id") "t" ON (("t"."department_id" = "d"."id")))
     LEFT JOIN ( SELECT "risks"."department_id",
            "count"(*) FILTER (WHERE (("risks"."risk_level" = 'critical'::"public"."risk_level") AND ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])))) AS "critical_risks"
           FROM "public"."risks"
          GROUP BY "risks"."department_id") "r" ON (("r"."department_id" = "d"."id")))
     LEFT JOIN ( SELECT "compliance_items"."department_id",
            "count"(*) FILTER (WHERE ((COALESCE("compliance_items"."expiry_date", "compliance_items"."due_date") <= (CURRENT_DATE + '30 days'::interval)) AND ("compliance_items"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])))) AS "expiring_compliance"
           FROM "public"."compliance_items"
          GROUP BY "compliance_items"."department_id") "c" ON (("c"."department_id" = "d"."id")))
     LEFT JOIN ( SELECT "audit_findings"."department_id",
            "count"(*) FILTER (WHERE (("audit_findings"."due_date" < CURRENT_DATE) AND ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))) AS "overdue_audit_findings"
           FROM "public"."audit_findings"
          GROUP BY "audit_findings"."department_id") "a" ON (("a"."department_id" = "d"."id")))
     LEFT JOIN ( SELECT "ovr_reports"."department_id",
            "count"(*) FILTER (WHERE ("ovr_reports"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"]))) AS "open_ovrs",
            "count"(*) FILTER (WHERE (("ovr_reports"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) AND ("ovr_reports"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"])))) AS "major_ovrs"
           FROM "public"."ovr_reports"
          GROUP BY "ovr_reports"."department_id") "o" ON (("o"."department_id" = "d"."id")))
     LEFT JOIN LATERAL ( SELECT "dn"."executive_note",
            "dn"."created_at"
           FROM "public"."department_scorecard_notes" "dn"
          WHERE ("dn"."department_id" = "d"."id")
          ORDER BY "dn"."created_at" DESC
         LIMIT 1) "n" ON (true));

CREATE OR REPLACE VIEW "public"."v_board_pack_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    "name_en" AS "organization_name_en",
    "name_ar" AS "organization_name_ar",
    CURRENT_DATE AS "as_of_date",
    (( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))))::integer AS "active_projects",
    (( SELECT "count"(*) AS "count"
           FROM "public"."risks" "r"
          WHERE (("r"."organization_id" = "o"."id") AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])))))::integer AS "high_open_risks",
    (( SELECT "count"(*) AS "count"
           FROM "public"."compliance_items" "c"
          WHERE (("c"."organization_id" = "o"."id") AND (COALESCE("c"."expiry_date", "c"."due_date") <= (CURRENT_DATE + '30 days'::interval)) AND ("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])))))::integer AS "compliance_due_30_days",
    (( SELECT "count"(*) AS "count"
           FROM "public"."audit_findings" "a"
          WHERE (("a"."organization_id" = "o"."id") AND ("a"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))))::integer AS "open_audit_findings",
    (( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "v"
          WHERE (("v"."organization_id" = "o"."id") AND ("v"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"])))))::integer AS "open_ovrs",
    (( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "ap"
          WHERE (("ap"."organization_id" = "o"."id") AND ("ap"."status" = 'pending'::"public"."approval_status"))))::integer AS "pending_approvals",
    (( SELECT "count"(*) AS "count"
           FROM "public"."evidence_files" "e"
          WHERE (("e"."organization_id" = "o"."id") AND ("e"."status" = ANY (ARRAY['submitted'::"public"."evidence_status", 'needs_revision'::"public"."evidence_status"])))))::integer AS "evidence_reviews",
    (( SELECT "round"("avg"("s"."control_score")) AS "round"
           FROM "public"."v_department_scorecard_v2" "s"
          WHERE ("s"."organization_id" = "o"."id")))::integer AS "avg_department_control_score",
    (( SELECT "count"(*) AS "count"
           FROM "public"."v_department_scorecard_v2" "s"
          WHERE (("s"."organization_id" = "o"."id") AND ("s"."signal" = ANY (ARRAY['critical'::"public"."scorecard_signal", 'at_risk'::"public"."scorecard_signal"])))))::integer AS "departments_at_risk"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_bulk_import_batch_summary" WITH ("security_invoker"='true') AS
 SELECT "b"."id",
    "b"."organization_id",
    "b"."batch_type",
    "b"."source_file_name",
    "b"."status",
    "b"."total_rows",
    "b"."valid_rows",
    "b"."invalid_rows",
    "round"(
        CASE
            WHEN ("b"."total_rows" > 0) THEN ((("b"."valid_rows")::numeric / ("b"."total_rows")::numeric) * (100)::numeric)
            ELSE (0)::numeric
        END, 2) AS "valid_percent",
    "b"."created_at",
    "creator"."full_name_en" AS "created_by_name",
    "approver"."full_name_en" AS "approved_by_name",
    "importer"."full_name_en" AS "imported_by_name"
   FROM ((("public"."bulk_import_batches" "b"
     LEFT JOIN "public"."profiles" "creator" ON (("creator"."id" = "b"."created_by")))
     LEFT JOIN "public"."profiles" "approver" ON (("approver"."id" = "b"."approved_by")))
     LEFT JOIN "public"."profiles" "importer" ON (("importer"."id" = "b"."imported_by")));

CREATE OR REPLACE VIEW "public"."v_committee_action_automation" WITH ("security_invoker"='true') AS
 SELECT "cd"."id",
    "cd"."organization_id",
    "cd"."decision_code",
    "cd"."title",
    "cd"."decision_text",
    "cm"."committee_name",
    "cm"."meeting_date",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "owner"."full_name_en" AS "owner_name_en",
    "owner"."full_name_ar" AS "owner_name_ar",
    "cd"."due_date",
    "cd"."priority",
    "cd"."risk_level",
    "cd"."status",
    GREATEST((CURRENT_DATE - "cd"."due_date"), 0) AS "days_overdue",
        CASE
            WHEN ("cd"."status" = ANY (ARRAY['closed'::"public"."decision_status", 'cancelled'::"public"."decision_status"])) THEN 'closed'::"text"
            WHEN ("cd"."due_date" < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN ("cd"."due_date" <= (CURRENT_DATE + '7 days'::interval)) THEN 'due_soon'::"text"
            WHEN (("cd"."linked_project_id" IS NULL) AND "cd"."evidence_required") THEN 'needs_project_or_evidence'::"text"
            ELSE 'on_track'::"text"
        END AS "automation_signal",
    "cd"."linked_project_id"
   FROM ((("public"."committee_decisions" "cd"
     LEFT JOIN "public"."committee_meetings" "cm" ON (("cm"."id" = "cd"."meeting_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "cd"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "cd"."owner_id")));

CREATE OR REPLACE VIEW "public"."v_consolidated_release_packages" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "release_tag",
    "package_code",
    "title",
    "package_type",
    "status",
    "file_path",
    "checksum_note",
    "owner_label",
    "generated_at",
    "verified_at",
    "created_at",
    "updated_at"
   FROM "public"."consolidated_release_packages";

CREATE OR REPLACE VIEW "public"."v_consolidation_defect_dashboard" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "defect_code",
    "title",
    "area",
    "severity",
    "status",
    "owner_label",
    "found_in_version",
    "target_fix_version",
    "description",
    "resolution_note",
    "created_by",
    "created_at",
    "updated_at",
        CASE
            WHEN ("status" = ANY (ARRAY['closed'::"text", 'cancelled'::"text"])) THEN 0
            WHEN ("severity" = 'critical'::"text") THEN 100
            WHEN ("severity" = 'high'::"text") THEN 70
            WHEN ("severity" = 'medium'::"text") THEN 40
            ELSE 20
        END AS "defect_weight"
   FROM "public"."consolidation_defect_log" "d";

CREATE OR REPLACE VIEW "public"."v_ovr_workflow_queue" WITH ("security_invoker"='true') AS
 SELECT "o"."id",
    "o"."organization_id",
    "o"."ovr_number",
    "left"("o"."brief_description", 160) AS "title",
    "d"."name_en" AS "department_name",
    "pr"."full_name_en" AS "owner_name",
    "o"."occurrence_date",
    "o"."status",
    "o"."severity_level",
        CASE
            WHEN ("o"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'manager_review'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"])) THEN 'manager_review'::"text"
            WHEN ("o"."status" = ANY (ARRAY['quality_validation'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status"])) THEN 'quality_validation'::"text"
            WHEN ("o"."status" = 'referred_party_response'::"public"."ovr_status") THEN 'referred_party_response'::"text"
            WHEN ("o"."status" = ANY (ARRAY['quality_final_review'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])) THEN 'quality_final_review'::"text"
            WHEN ("o"."status" = ANY (ARRAY['disputed'::"public"."ovr_status", 'reopened'::"public"."ovr_status"])) THEN 'dispute_resolution'::"text"
            WHEN ("o"."status" = ANY (ARRAY['escalated'::"public"."ovr_status", 'major_escalation'::"public"."ovr_status"])) THEN 'escalation'::"text"
            ELSE ("o"."status")::"text"
        END AS "workflow_stage",
        CASE
            WHEN ("o"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'manager_review'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"])) THEN COALESCE("o"."supervisor_due_date", ("o"."occurrence_date" + 1))
            WHEN ("o"."status" = ANY (ARRAY['quality_validation'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status"])) THEN COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 3))
            WHEN ("o"."status" = 'referred_party_response'::"public"."ovr_status") THEN COALESCE("o"."corrective_action_due_date", (CURRENT_DATE + 2))
            WHEN ("o"."status" = ANY (ARRAY['quality_final_review'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])) THEN COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 5))
            ELSE NULL::"date"
        END AS "due_date",
        CASE
            WHEN ("o"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'manager_review'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"])) THEN (COALESCE("o"."supervisor_due_date", ("o"."occurrence_date" + 1)) < CURRENT_DATE)
            WHEN ("o"."status" = ANY (ARRAY['quality_validation'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status"])) THEN (COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 3)) < CURRENT_DATE)
            WHEN ("o"."status" = 'referred_party_response'::"public"."ovr_status") THEN (COALESCE("o"."corrective_action_due_date", (CURRENT_DATE + 2)) < CURRENT_DATE)
            WHEN ("o"."status" = ANY (ARRAY['quality_final_review'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])) THEN (COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 5)) < CURRENT_DATE)
            ELSE false
        END AS "is_overdue",
        CASE
            WHEN ("o"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) THEN 'critical'::"public"."risk_level"
            WHEN ("o"."status" = ANY (ARRAY['disputed'::"public"."ovr_status", 'reopened'::"public"."ovr_status", 'escalated'::"public"."ovr_status", 'rejected'::"public"."ovr_status"])) THEN 'high'::"public"."risk_level"
            WHEN ("o"."status" = ANY (ARRAY['referred_party_response'::"public"."ovr_status", 'quality_final_review'::"public"."ovr_status"])) THEN 'high'::"public"."risk_level"
            ELSE 'medium'::"public"."risk_level"
        END AS "risk_level"
   FROM (("public"."ovr_reports" "o"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "o"."department_id")))
     LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "o"."owner_id")))
  WHERE ("o"."status" <> ALL (ARRAY['draft'::"public"."ovr_status", 'closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status", 'rejected'::"public"."ovr_status"]))
  ORDER BY
        CASE
            WHEN ("o"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'manager_review'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"])) THEN (COALESCE("o"."supervisor_due_date", ("o"."occurrence_date" + 1)) < CURRENT_DATE)
            WHEN ("o"."status" = ANY (ARRAY['quality_validation'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status"])) THEN (COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 3)) < CURRENT_DATE)
            WHEN ("o"."status" = 'referred_party_response'::"public"."ovr_status") THEN (COALESCE("o"."corrective_action_due_date", (CURRENT_DATE + 2)) < CURRENT_DATE)
            WHEN ("o"."status" = ANY (ARRAY['quality_final_review'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])) THEN (COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 5)) < CURRENT_DATE)
            ELSE false
        END DESC,
        CASE
            WHEN ("o"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'manager_review'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"])) THEN COALESCE("o"."supervisor_due_date", ("o"."occurrence_date" + 1))
            WHEN ("o"."status" = ANY (ARRAY['quality_validation'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status"])) THEN COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 3))
            WHEN ("o"."status" = 'referred_party_response'::"public"."ovr_status") THEN COALESCE("o"."corrective_action_due_date", (CURRENT_DATE + 2))
            WHEN ("o"."status" = ANY (ARRAY['quality_final_review'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])) THEN COALESCE("o"."quality_due_date", ("o"."occurrence_date" + 5))
            ELSE NULL::"date"
        END;

CREATE OR REPLACE VIEW "public"."v_critical_attention_items" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "item_type",
    "title",
    "department_name",
    "owner_name",
    "due_date",
    "status",
    "risk_level",
    "progress_percent",
    "sort_rank"
   FROM ( SELECT "p"."id",
            "p"."organization_id",
            'project'::"text" AS "item_type",
            "p"."title",
            "d"."name_en" AS "department_name",
            "pr"."full_name_en" AS "owner_name",
            "p"."target_end_date" AS "due_date",
            ("p"."status")::"text" AS "status",
            "p"."risk_level",
            "p"."progress_percent",
                CASE
                    WHEN ("p"."risk_level" = 'critical'::"public"."risk_level") THEN 1
                    WHEN ("p"."risk_level" = 'high'::"public"."risk_level") THEN 2
                    WHEN ("p"."status" = 'delayed'::"public"."project_status") THEN 3
                    ELSE 8
                END AS "sort_rank"
           FROM (("public"."projects" "p"
             LEFT JOIN "public"."departments" "d" ON (("d"."id" = "p"."department_id")))
             LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "p"."owner_id")))
          WHERE (("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])) AND (("p"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])) OR ("p"."status" = ANY (ARRAY['delayed'::"public"."project_status", 'at_risk'::"public"."project_status", 'completed_pending_evidence'::"public"."project_status", 'completed_pending_approval'::"public"."project_status"])) OR (("p"."target_end_date" IS NOT NULL) AND ("p"."target_end_date" < CURRENT_DATE))))
        UNION ALL
         SELECT "r"."id",
            "r"."organization_id",
            'risk'::"text" AS "text",
            "r"."title",
            "d"."name_en",
            "pr"."full_name_en",
            "r"."next_review_date",
            ("r"."status")::"text" AS "status",
            "r"."risk_level",
            NULL::numeric AS "numeric",
                CASE
                    WHEN ("r"."risk_level" = 'critical'::"public"."risk_level") THEN 1
                    WHEN ("r"."risk_level" = 'high'::"public"."risk_level") THEN 2
                    ELSE 8
                END AS "case"
           FROM (("public"."risks" "r"
             LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
             LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "r"."owner_id")))
          WHERE (("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])))
        UNION ALL
         SELECT "c"."id",
            "c"."organization_id",
            'compliance'::"text" AS "text",
            "c"."title",
            "d"."name_en",
            "pr"."full_name_en",
            COALESCE("c"."expiry_date", "c"."due_date") AS "coalesce",
            ("c"."status")::"text" AS "status",
            "c"."risk_level",
            NULL::numeric AS "numeric",
                CASE
                    WHEN (("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + '7 days'::interval))) THEN 1
                    WHEN ("c"."risk_level" = 'critical'::"public"."risk_level") THEN 2
                    ELSE 5
                END AS "case"
           FROM (("public"."compliance_items" "c"
             LEFT JOIN "public"."departments" "d" ON (("d"."id" = "c"."department_id")))
             LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "c"."owner_id")))
          WHERE (("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])) AND (("c"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])) OR (("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + '30 days'::interval))) OR (("c"."due_date" IS NOT NULL) AND ("c"."due_date" < CURRENT_DATE))))
        UNION ALL
         SELECT "af"."id",
            "af"."organization_id",
            'audit_finding'::"text" AS "text",
            "af"."title",
            "d"."name_en",
            "pr"."full_name_en",
            "af"."due_date",
            ("af"."status")::"text" AS "status",
            "af"."risk_level",
            NULL::numeric AS "numeric",
                CASE
                    WHEN (("af"."due_date" IS NOT NULL) AND ("af"."due_date" < CURRENT_DATE)) THEN 1
                    WHEN ("af"."risk_level" = 'critical'::"public"."risk_level") THEN 2
                    ELSE 4
                END AS "case"
           FROM (("public"."audit_findings" "af"
             LEFT JOIN "public"."departments" "d" ON (("d"."id" = "af"."department_id")))
             LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "af"."owner_id")))
          WHERE (("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])) AND (("af"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])) OR (("af"."due_date" IS NOT NULL) AND ("af"."due_date" < CURRENT_DATE))))
        UNION ALL
         SELECT "cd"."id",
            "cd"."organization_id",
            'governance_decision'::"text" AS "text",
            "cd"."title",
            "d"."name_en",
            "pr"."full_name_en",
            "cd"."due_date",
            ("cd"."status")::"text" AS "status",
            "cd"."risk_level",
            NULL::numeric AS "numeric",
                CASE
                    WHEN ("cd"."status" = 'delayed'::"public"."decision_status") THEN 1
                    WHEN ("cd"."priority" = 'critical'::"public"."priority_level") THEN 2
                    ELSE 6
                END AS "case"
           FROM (("public"."committee_decisions" "cd"
             LEFT JOIN "public"."departments" "d" ON (("d"."id" = "cd"."department_id")))
             LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "cd"."owner_id")))
          WHERE (("cd"."status" <> ALL (ARRAY['closed'::"public"."decision_status", 'cancelled'::"public"."decision_status"])) AND (("cd"."priority" = ANY (ARRAY['critical'::"public"."priority_level", 'high'::"public"."priority_level"])) OR ("cd"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])) OR ("cd"."status" = ANY (ARRAY['delayed'::"public"."decision_status", 'pending_evidence'::"public"."decision_status", 'pending_approval'::"public"."decision_status"]))))
        UNION ALL
         SELECT "o"."id",
            "o"."organization_id",
            'ovr'::"text" AS "text",
            ((COALESCE("o"."ovr_number", "o"."logging_number", 'OVR'::"text") || ' - '::"text") || "left"("o"."brief_description", 90)) AS "title",
            "d"."name_en",
            "pr"."full_name_en",
            "q_1"."due_date",
            ("o"."status")::"text" AS "status",
            "q_1"."risk_level",
            NULL::numeric AS "numeric",
                CASE
                    WHEN ("o"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) THEN 1
                    WHEN "q_1"."is_overdue" THEN 2
                    ELSE 4
                END AS "case"
           FROM ((("public"."ovr_reports" "o"
             LEFT JOIN "public"."v_ovr_workflow_queue" "q_1" ON (("q_1"."id" = "o"."id")))
             LEFT JOIN "public"."departments" "d" ON (("d"."id" = "o"."department_id")))
             LEFT JOIN "public"."profiles" "pr" ON (("pr"."id" = "o"."owner_id")))
          WHERE (("o"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"])) AND (("o"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) OR ("q_1"."is_overdue" = true) OR ("o"."status" = ANY (ARRAY['returned_for_clarification'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"]))))) "q"
  ORDER BY "sort_rank", "due_date";

CREATE OR REPLACE VIEW "public"."v_cross_module_relationship_map" WITH ("security_invoker"='true') AS
 SELECT ((('risk-project-'::"text" || ("r"."id")::"text") || '-'::"text") || ("p"."id")::"text") AS "id",
    'Risk'::"text" AS "source_type",
    ("r"."id")::"text" AS "source_id",
    "r"."title" AS "source_title",
    'mitigated_by'::"text" AS "relationship_type",
    'Action plan'::"text" AS "target_type",
    ("p"."id")::"text" AS "target_id",
    "p"."title" AS "target_title",
    ("p"."status")::"text" AS "status",
    ("p"."risk_level")::"text" AS "risk_level",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name"
   FROM (("public"."risks" "r"
     JOIN "public"."projects" "p" ON ((("p"."source_reference_id" = "r"."id") OR ("p"."id" IN ( SELECT "risk_mitigation_actions"."project_id"
           FROM "public"."risk_mitigation_actions"
          WHERE (("risk_mitigation_actions"."risk_id" = "r"."id") AND ("risk_mitigation_actions"."project_id" IS NOT NULL)))))))
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
UNION ALL
 SELECT ((('audit-project-'::"text" || ("af"."id")::"text") || '-'::"text") || ("p"."id")::"text") AS "id",
    'Audit finding'::"text" AS "source_type",
    ("af"."id")::"text" AS "source_id",
    "af"."title" AS "source_title",
    'corrected_by'::"text" AS "relationship_type",
    'Action plan'::"text" AS "target_type",
    ("p"."id")::"text" AS "target_id",
    "p"."title" AS "target_title",
    ("p"."status")::"text" AS "status",
    ("p"."risk_level")::"text" AS "risk_level",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name"
   FROM (("public"."audit_findings" "af"
     JOIN "public"."projects" "p" ON (("p"."id" = "af"."corrective_action_project_id")))
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
UNION ALL
 SELECT ((('compliance-project-'::"text" || ("c"."id")::"text") || '-'::"text") || ("p"."id")::"text") AS "id",
    'Compliance'::"text" AS "source_type",
    ("c"."id")::"text" AS "source_id",
    "c"."title" AS "source_title",
    'remediated_by'::"text" AS "relationship_type",
    'Action plan'::"text" AS "target_type",
    ("p"."id")::"text" AS "target_id",
    "p"."title" AS "target_title",
    ("p"."status")::"text" AS "status",
    ("p"."risk_level")::"text" AS "risk_level",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name"
   FROM (("public"."compliance_items" "c"
     JOIN "public"."projects" "p" ON (("p"."id" = "c"."linked_project_id")))
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
UNION ALL
 SELECT ((('evidence-project-'::"text" || ("e"."id")::"text") || '-'::"text") || ("p"."id")::"text") AS "id",
    'Evidence'::"text" AS "source_type",
    ("e"."id")::"text" AS "source_id",
    "e"."file_name" AS "source_title",
    'supports_closure_of'::"text" AS "relationship_type",
    'Action plan'::"text" AS "target_type",
    ("p"."id")::"text" AS "target_id",
    "p"."title" AS "target_title",
    ("e"."status")::"text" AS "status",
    ("p"."risk_level")::"text" AS "risk_level",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name"
   FROM (("public"."evidence_files" "e"
     JOIN "public"."projects" "p" ON (("p"."id" = "e"."project_id")))
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")));

CREATE OR REPLACE VIEW "public"."v_data_retention_readiness" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "rule_key",
    "title_en",
    "title_ar",
    "target_table",
    "retention_months",
    "status",
    "requires_approval",
    "last_reviewed_at",
    "next_review_date",
        CASE "target_table"
            WHEN 'audit_logs'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."audit_logs" "a"
              WHERE (("a"."organization_id" = "r"."organization_id") AND ("a"."created_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            WHEN 'security_review_events'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."security_review_events" "s"
              WHERE (("s"."organization_id" = "r"."organization_id") AND ("s"."created_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            WHEN 'ovr_reports'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."ovr_reports" "o"
              WHERE (("o"."organization_id" = "r"."organization_id") AND ("o"."created_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            WHEN 'evidence_files'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."evidence_files" "e"
              WHERE (("e"."organization_id" = "r"."organization_id") AND ("e"."created_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            WHEN 'approvals'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."approvals" "ap"
              WHERE (("ap"."organization_id" = "r"."organization_id") AND ("ap"."requested_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            WHEN 'export_logs'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."export_logs" "el"
              WHERE (("el"."organization_id" = "r"."organization_id") AND ("el"."created_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            WHEN 'ui_performance_events'::"text" THEN ( SELECT "count"(*) AS "count"
               FROM "public"."ui_performance_events" "u"
              WHERE (("u"."organization_id" = "r"."organization_id") AND ("u"."created_at" < ("now"() - "make_interval"("months" => "r"."retention_months")))))
            ELSE (0)::bigint
        END AS "records_past_retention"
   FROM "public"."data_retention_rules" "r"
  WHERE ("status" = ANY (ARRAY['active'::"public"."retention_rule_status", 'paused'::"public"."retention_rule_status"]));

COMMENT ON VIEW "public"."v_data_retention_readiness" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

CREATE OR REPLACE VIEW "public"."v_delay_reason_queue" WITH ("security_invoker"='true') AS
 SELECT "p"."organization_id",
    'project'::"text" AS "item_type",
    "p"."id" AS "item_id",
    "p"."title",
    "d"."name_en" AS "department_name",
    "owner"."full_name_en" AS "owner_name",
    "p"."target_end_date" AS "due_date",
    "p"."risk_level",
    ("p"."status")::"text" AS "status",
    'Overdue project missing mandatory delay reason.'::"text" AS "missing_reason"
   FROM (("public"."projects" "p"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "p"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "p"."owner_id")))
  WHERE (("p"."target_end_date" < CURRENT_DATE) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])) AND (COALESCE(TRIM(BOTH FROM "p"."delay_reason"), ''::"text") = ''::"text"))
UNION ALL
 SELECT "m"."organization_id",
    'milestone'::"text" AS "item_type",
    "m"."id" AS "item_id",
    "m"."title",
    "d"."name_en" AS "department_name",
    "owner"."full_name_en" AS "owner_name",
    "m"."due_date",
    "p"."risk_level",
    ("m"."status")::"text" AS "status",
    'Overdue milestone missing mandatory delay reason.'::"text" AS "missing_reason"
   FROM ((("public"."milestones" "m"
     JOIN "public"."projects" "p" ON (("p"."id" = "m"."project_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "p"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "m"."owner_id")))
  WHERE (("m"."due_date" < CURRENT_DATE) AND ("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND (COALESCE(TRIM(BOTH FROM "m"."delay_reason"), ''::"text") = ''::"text"))
UNION ALL
 SELECT "t"."organization_id",
    'task'::"text" AS "item_type",
    "t"."id" AS "item_id",
    "t"."title",
    "d"."name_en" AS "department_name",
    "owner"."full_name_en" AS "owner_name",
    "t"."due_date",
    "p"."risk_level",
    ("t"."status")::"text" AS "status",
    'Overdue task missing mandatory delay reason.'::"text" AS "missing_reason"
   FROM ((("public"."tasks" "t"
     JOIN "public"."projects" "p" ON (("p"."id" = "t"."project_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "p"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = COALESCE("t"."assigned_to", "t"."owner_id"))))
  WHERE (("t"."due_date" < CURRENT_DATE) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND (COALESCE(TRIM(BOTH FROM "t"."delay_reason"), ''::"text") = ''::"text"));

CREATE OR REPLACE VIEW "public"."v_department_execution_summary" WITH ("security_invoker"='true') AS
 SELECT "d"."organization_id",
    "d"."id" AS "department_id",
    "d"."name_en" AS "department_name",
    "count"(DISTINCT "p"."id") FILTER (WHERE ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"]))) AS "active_projects",
    "count"(DISTINCT "p"."id") FILTER (WHERE (("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])) AND ("p"."target_end_date" < CURRENT_DATE))) AS "overdue_projects",
    "count"(DISTINCT "m"."id") FILTER (WHERE (("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND ("m"."due_date" < CURRENT_DATE))) AS "overdue_milestones",
    "count"(DISTINCT "t"."id") FILTER (WHERE (("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND ("t"."due_date" < CURRENT_DATE))) AS "overdue_tasks",
    "count"(DISTINCT "r"."id") FILTER (WHERE (("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = 'critical'::"public"."risk_level"))) AS "critical_risks",
    "count"(DISTINCT "af"."id") FILTER (WHERE (("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])) AND ("af"."due_date" < CURRENT_DATE))) AS "overdue_audit_findings",
    "count"(DISTINCT "c"."id") FILTER (WHERE (("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])) AND ("c"."expiry_date" <= (CURRENT_DATE + '30 days'::interval)))) AS "compliance_expiring_30_days",
    "d"."name_ar" AS "department_name_ar",
    "d"."code" AS "department_code",
    "d"."is_active",
    "d"."archived_at",
    "d"."archived_by",
    "d"."archive_reason",
    "d"."successor_department_id"
   FROM (((((("public"."departments" "d"
     LEFT JOIN "public"."projects" "p" ON (("p"."department_id" = "d"."id")))
     LEFT JOIN "public"."milestones" "m" ON (("m"."project_id" = "p"."id")))
     LEFT JOIN "public"."tasks" "t" ON (("t"."project_id" = "p"."id")))
     LEFT JOIN "public"."risks" "r" ON (("r"."department_id" = "d"."id")))
     LEFT JOIN "public"."audit_findings" "af" ON (("af"."department_id" = "d"."id")))
     LEFT JOIN "public"."compliance_items" "c" ON (("c"."department_id" = "d"."id")))
  GROUP BY "d"."organization_id", "d"."id", "d"."name_en", "d"."name_ar", "d"."code", "d"."is_active", "d"."archived_at", "d"."archived_by", "d"."archive_reason", "d"."successor_department_id";

CREATE OR REPLACE VIEW "public"."v_ovr_risk_indicator_feed" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."organization_id",
    "r"."department_id",
    COALESCE("d"."name_en", 'Company-wide'::"text") AS "department_name",
    "r"."ovr_number",
    "r"."logging_number",
    "r"."occurrence_date",
    "r"."occurrence_category",
    ("r"."severity_level")::"text" AS "severity_level",
    "public"."ovr_severity_weight"(("r"."severity_level")::"text") AS "severity_weight",
    "r"."status",
    "r"."corrective_action_required",
    "r"."linked_project_id",
        CASE
            WHEN (("p"."id" IS NOT NULL) AND ("p"."target_end_date" IS NOT NULL) AND ("p"."target_end_date" < CURRENT_DATE) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"]))) THEN true
            ELSE false
        END AS "corrective_action_overdue",
    "r"."closed_at",
        CASE
            WHEN ("r"."closed_at" IS NOT NULL) THEN "round"((EXTRACT(epoch FROM ("r"."closed_at" - "r"."created_at")) / 86400.0), 1)
            ELSE NULL::numeric
        END AS "closure_days",
    "r"."created_at"
   FROM (("public"."ovr_reports" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN "public"."projects" "p" ON (("p"."id" = "r"."linked_project_id")));

CREATE OR REPLACE VIEW "public"."v_ovr_repeated_category_alerts" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "department_id",
    "department_name",
    "occurrence_category",
    ("count"(*))::integer AS "category_count_30d",
    "max"("severity_weight") AS "max_severity_weight",
        CASE "max"("severity_weight")
            WHEN 8 THEN 'sentinel'::"text"
            WHEN 5 THEN 'level_4'::"text"
            WHEN 3 THEN 'level_3'::"text"
            WHEN 2 THEN 'level_2'::"text"
            ELSE 'level_1'::"text"
        END AS "max_severity_level",
        CASE
            WHEN (("max"("severity_weight") >= 5) OR ("count"(*) >= 5)) THEN 'high'::"public"."risk_level"
            ELSE 'medium'::"public"."risk_level"
        END AS "alert_level"
   FROM "public"."v_ovr_risk_indicator_feed" "f"
  WHERE (("occurrence_date" >= (CURRENT_DATE - '30 days'::interval)) AND ("status" <> 'cancelled'::"public"."ovr_status"))
  GROUP BY "organization_id", "department_id", "department_name", "occurrence_category"
 HAVING ("count"(*) >= 3);

CREATE OR REPLACE VIEW "public"."v_ovr_risk_indicators_by_department" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "v_ovr_risk_indicator_feed"."id",
            "v_ovr_risk_indicator_feed"."organization_id",
            "v_ovr_risk_indicator_feed"."department_id",
            "v_ovr_risk_indicator_feed"."department_name",
            "v_ovr_risk_indicator_feed"."ovr_number",
            "v_ovr_risk_indicator_feed"."logging_number",
            "v_ovr_risk_indicator_feed"."occurrence_date",
            "v_ovr_risk_indicator_feed"."occurrence_category",
            "v_ovr_risk_indicator_feed"."severity_level",
            "v_ovr_risk_indicator_feed"."severity_weight",
            "v_ovr_risk_indicator_feed"."status",
            "v_ovr_risk_indicator_feed"."corrective_action_required",
            "v_ovr_risk_indicator_feed"."linked_project_id",
            "v_ovr_risk_indicator_feed"."corrective_action_overdue",
            "v_ovr_risk_indicator_feed"."closed_at",
            "v_ovr_risk_indicator_feed"."closure_days",
            "v_ovr_risk_indicator_feed"."created_at"
           FROM "public"."v_ovr_risk_indicator_feed"
          WHERE ("v_ovr_risk_indicator_feed"."status" <> 'cancelled'::"public"."ovr_status")
        ), "repeated" AS (
         SELECT "v_ovr_repeated_category_alerts"."organization_id",
            "v_ovr_repeated_category_alerts"."department_id",
            ("count"(*))::integer AS "repeated_category_alerts_30d",
            "string_agg"("v_ovr_repeated_category_alerts"."occurrence_category", ', '::"text" ORDER BY "v_ovr_repeated_category_alerts"."occurrence_category") AS "repeated_categories"
           FROM "public"."v_ovr_repeated_category_alerts"
          GROUP BY "v_ovr_repeated_category_alerts"."organization_id", "v_ovr_repeated_category_alerts"."department_id"
        ), "department_rollup" AS (
         SELECT "b"."organization_id",
            "b"."department_id",
            "max"("b"."department_name") AS "department_name",
            ("count"(*) FILTER (WHERE ("b"."occurrence_date" >= (CURRENT_DATE - '30 days'::interval))))::integer AS "ovr_count_30d",
            ("count"(*) FILTER (WHERE ("b"."occurrence_date" >= (CURRENT_DATE - '90 days'::interval))))::integer AS "ovr_count_90d",
            (COALESCE("sum"("b"."severity_weight") FILTER (WHERE ("b"."occurrence_date" >= (CURRENT_DATE - '30 days'::interval))), (0)::bigint))::integer AS "weighted_score_30d",
            ("count"(*) FILTER (WHERE (("b"."occurrence_date" >= (CURRENT_DATE - '90 days'::interval)) AND ("b"."severity_level" = ANY (ARRAY['level_4'::"text", 'sentinel'::"text"])))))::integer AS "major_or_sentinel_ovrs_90d",
            ("count"(*) FILTER (WHERE ("b"."corrective_action_overdue" = true)))::integer AS "overdue_corrective_actions",
            "round"("avg"("b"."closure_days") FILTER (WHERE ("b"."closure_days" IS NOT NULL)), 1) AS "avg_closure_days"
           FROM "base" "b"
          GROUP BY "b"."organization_id", "b"."department_id"
        )
 SELECT "d"."organization_id",
    "d"."department_id",
    COALESCE("d"."department_name", 'Company-wide'::"text") AS "department_name",
    "d"."ovr_count_30d",
    "d"."ovr_count_90d",
    "d"."weighted_score_30d",
    "d"."major_or_sentinel_ovrs_90d",
    COALESCE("r"."repeated_category_alerts_30d", 0) AS "repeated_category_alerts_30d",
    "r"."repeated_categories",
    "d"."overdue_corrective_actions",
    "d"."avg_closure_days",
    "public"."ovr_signal_level"("d"."weighted_score_30d", "d"."major_or_sentinel_ovrs_90d", COALESCE("r"."repeated_category_alerts_30d", 0), "d"."overdue_corrective_actions") AS "risk_signal_level"
   FROM ("department_rollup" "d"
     LEFT JOIN "repeated" "r" ON ((("r"."organization_id" = "d"."organization_id") AND (NOT ("r"."department_id" IS DISTINCT FROM "d"."department_id")))));

CREATE OR REPLACE VIEW "public"."v_department_risk_heatmap" WITH ("security_invoker"='true') AS
 WITH "base" AS (
         SELECT "d"."organization_id",
            "d"."id" AS "department_id",
            COALESCE("d"."name_en", "d"."name_ar", 'Unassigned'::"text") AS "department_name",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM "public"."projects" "p"
                  WHERE (("p"."department_id" = "d"."id") AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))), (0)::bigint) AS "active_projects",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM "public"."projects" "p"
                  WHERE (("p"."department_id" = "d"."id") AND ("p"."target_end_date" < CURRENT_DATE) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))), (0)::bigint) AS "overdue_projects",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM ("public"."milestones" "m"
                     JOIN "public"."projects" "p" ON (("p"."id" = "m"."project_id")))
                  WHERE (("p"."department_id" = "d"."id") AND ("m"."due_date" < CURRENT_DATE) AND ("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))), (0)::bigint) AS "overdue_milestones",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM ("public"."tasks" "t"
                     JOIN "public"."projects" "p" ON (("p"."id" = "t"."project_id")))
                  WHERE (("p"."department_id" = "d"."id") AND ("t"."due_date" < CURRENT_DATE) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))), (0)::bigint) AS "overdue_tasks",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM "public"."risks" "r"
                  WHERE (("r"."department_id" = "d"."id") AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = 'critical'::"public"."risk_level"))), (0)::bigint) AS "critical_risks",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM "public"."compliance_items" "c"
                  WHERE (("c"."department_id" = "d"."id") AND ("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + '30 days'::interval)) AND ("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])))), (0)::bigint) AS "compliance_expiring_30_days",
            COALESCE(( SELECT "count"(*) AS "count"
                   FROM "public"."audit_findings" "af"
                  WHERE (("af"."department_id" = "d"."id") AND ("af"."due_date" < CURRENT_DATE) AND ("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))), (0)::bigint) AS "overdue_audit_findings",
            COALESCE(( SELECT "oi"."weighted_score_30d"
                   FROM "public"."v_ovr_risk_indicators_by_department" "oi"
                  WHERE ("oi"."department_id" = "d"."id")
                 LIMIT 1), 0) AS "ovr_weighted_score_30d"
           FROM "public"."departments" "d"
          WHERE ("d"."is_active" = true)
        ), "scored" AS (
         SELECT "base"."organization_id",
            "base"."department_id",
            "base"."department_name",
            "base"."active_projects",
            "base"."overdue_projects",
            "base"."overdue_milestones",
            "base"."overdue_tasks",
            "base"."critical_risks",
            "base"."compliance_expiring_30_days",
            "base"."overdue_audit_findings",
            "base"."ovr_weighted_score_30d",
            (LEAST((100)::bigint, ((("base"."overdue_projects" * 20) + ("base"."overdue_milestones" * 7)) + ("base"."overdue_tasks" * 3))))::integer AS "execution_pressure_score",
            (LEAST((100)::bigint, (("base"."critical_risks" * 28) + ("base"."overdue_audit_findings" * 10))))::integer AS "risk_pressure_score",
            (LEAST((100)::bigint, (("base"."compliance_expiring_30_days" * 18) + ("base"."overdue_audit_findings" * 12))))::integer AS "compliance_pressure_score",
            LEAST(100, ("base"."ovr_weighted_score_30d" * 4)) AS "ovr_pressure_score"
           FROM "base"
        )
 SELECT "organization_id",
    "department_id",
    "department_name",
    "active_projects",
    "overdue_projects",
    "overdue_milestones",
    "overdue_tasks",
    "critical_risks",
    "compliance_expiring_30_days",
    "overdue_audit_findings",
    "ovr_weighted_score_30d",
    "execution_pressure_score",
    "risk_pressure_score",
    "compliance_pressure_score",
    "ovr_pressure_score",
    (LEAST((100)::numeric, "round"(((((("execution_pressure_score" + "risk_pressure_score") + "compliance_pressure_score") + "ovr_pressure_score"))::numeric / 4.0))))::integer AS "overall_pressure_score",
        CASE
            WHEN (LEAST((100)::numeric, "round"(((((("execution_pressure_score" + "risk_pressure_score") + "compliance_pressure_score") + "ovr_pressure_score"))::numeric / 4.0))) >= (75)::numeric) THEN 'critical'::"public"."risk_level"
            WHEN (LEAST((100)::numeric, "round"(((((("execution_pressure_score" + "risk_pressure_score") + "compliance_pressure_score") + "ovr_pressure_score"))::numeric / 4.0))) >= (50)::numeric) THEN 'high'::"public"."risk_level"
            WHEN (LEAST((100)::numeric, "round"(((((("execution_pressure_score" + "risk_pressure_score") + "compliance_pressure_score") + "ovr_pressure_score"))::numeric / 4.0))) >= (25)::numeric) THEN 'medium'::"public"."risk_level"
            ELSE 'low'::"public"."risk_level"
        END AS "signal_level"
   FROM "scored";

CREATE OR REPLACE VIEW "public"."v_workflow_blockers" WITH ("security_invoker"='true') AS
 SELECT "p"."organization_id",
    'project'::"text" AS "item_type",
    "p"."id" AS "item_id",
    "p"."title",
    ("p"."status")::"text" AS "status",
    "p"."department_id",
    "p"."owner_id",
    "p"."target_end_date" AS "due_date",
        CASE
            WHEN ("p"."owner_id" IS NULL) THEN 'missing_owner'::"text"
            WHEN ("p"."target_end_date" IS NULL) THEN 'missing_due_date'::"text"
            WHEN (("p"."target_end_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "p"."delay_reason"), ''::"text") = ''::"text")) THEN 'missing_delay_reason'::"text"
            WHEN (("p"."evidence_required" = true) AND (("p"."status")::"text" = ANY (ARRAY['completed_pending_approval'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('project'::"text", "p"."id"))) THEN 'missing_accepted_evidence'::"text"
            ELSE 'attention_required'::"text"
        END AS "blocker_key",
        CASE
            WHEN ("p"."owner_id" IS NULL) THEN 'Project has no owner'::"text"
            WHEN ("p"."target_end_date" IS NULL) THEN 'Project has no target end date'::"text"
            WHEN (("p"."target_end_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "p"."delay_reason"), ''::"text") = ''::"text")) THEN 'Project is overdue without delay reason'::"text"
            WHEN (("p"."evidence_required" = true) AND (("p"."status")::"text" = ANY (ARRAY['completed_pending_approval'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('project'::"text", "p"."id"))) THEN 'Project needs accepted evidence'::"text"
            ELSE 'Project needs attention'::"text"
        END AS "blocker_en",
        CASE
            WHEN ("p"."owner_id" IS NULL) THEN 'المشروع بدون مالك'::"text"
            WHEN ("p"."target_end_date" IS NULL) THEN 'المشروع بدون تاريخ مستهدف'::"text"
            WHEN (("p"."target_end_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "p"."delay_reason"), ''::"text") = ''::"text")) THEN 'المشروع متأخر بدون سبب تأخير'::"text"
            WHEN (("p"."evidence_required" = true) AND (("p"."status")::"text" = ANY (ARRAY['completed_pending_approval'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('project'::"text", "p"."id"))) THEN 'المشروع يحتاج دليل مقبول'::"text"
            ELSE 'المشروع يحتاج متابعة'::"text"
        END AS "blocker_ar",
    "now"() AS "created_at"
   FROM "public"."projects" "p"
  WHERE ((("p"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND (("p"."owner_id" IS NULL) OR ("p"."target_end_date" IS NULL) OR (("p"."target_end_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "p"."delay_reason"), ''::"text") = ''::"text")) OR (("p"."evidence_required" = true) AND (("p"."status")::"text" = ANY (ARRAY['completed_pending_approval'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('project'::"text", "p"."id")))))
UNION ALL
 SELECT "t"."organization_id",
    'task'::"text" AS "item_type",
    "t"."id" AS "item_id",
    "t"."title",
    ("t"."status")::"text" AS "status",
    "p"."department_id",
    COALESCE("t"."assigned_to", "t"."owner_id") AS "owner_id",
    "t"."due_date",
        CASE
            WHEN (COALESCE("t"."assigned_to", "t"."owner_id") IS NULL) THEN 'missing_owner'::"text"
            WHEN ("t"."due_date" IS NULL) THEN 'missing_due_date'::"text"
            WHEN (("t"."due_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "t"."delay_reason"), ''::"text") = ''::"text")) THEN 'missing_delay_reason'::"text"
            WHEN (("t"."evidence_required" = true) AND (("t"."status")::"text" = ANY (ARRAY['approved'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('task'::"text", "t"."id"))) THEN 'missing_accepted_evidence'::"text"
            ELSE 'attention_required'::"text"
        END AS "blocker_key",
        CASE
            WHEN (COALESCE("t"."assigned_to", "t"."owner_id") IS NULL) THEN 'Task has no owner'::"text"
            WHEN ("t"."due_date" IS NULL) THEN 'Task has no due date'::"text"
            WHEN (("t"."due_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "t"."delay_reason"), ''::"text") = ''::"text")) THEN 'Task is overdue without delay reason'::"text"
            WHEN (("t"."evidence_required" = true) AND (("t"."status")::"text" = ANY (ARRAY['approved'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('task'::"text", "t"."id"))) THEN 'Task needs accepted evidence'::"text"
            ELSE 'Task needs attention'::"text"
        END AS "blocker_en",
        CASE
            WHEN (COALESCE("t"."assigned_to", "t"."owner_id") IS NULL) THEN 'المهمة بدون مالك'::"text"
            WHEN ("t"."due_date" IS NULL) THEN 'المهمة بدون تاريخ استحقاق'::"text"
            WHEN (("t"."due_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "t"."delay_reason"), ''::"text") = ''::"text")) THEN 'المهمة متأخرة بدون سبب تأخير'::"text"
            WHEN (("t"."evidence_required" = true) AND (("t"."status")::"text" = ANY (ARRAY['approved'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('task'::"text", "t"."id"))) THEN 'المهمة تحتاج دليل مقبول'::"text"
            ELSE 'المهمة تحتاج متابعة'::"text"
        END AS "blocker_ar",
    "now"() AS "created_at"
   FROM ("public"."tasks" "t"
     JOIN "public"."projects" "p" ON (("p"."id" = "t"."project_id")))
  WHERE ((("t"."status")::"text" <> ALL (ARRAY['closed'::"text", 'approved'::"text", 'cancelled'::"text"])) AND ((COALESCE("t"."assigned_to", "t"."owner_id") IS NULL) OR ("t"."due_date" IS NULL) OR (("t"."due_date" < CURRENT_DATE) AND (COALESCE(TRIM(BOTH FROM "t"."delay_reason"), ''::"text") = ''::"text")) OR (("t"."evidence_required" = true) AND (("t"."status")::"text" = ANY (ARRAY['approved'::"text", 'closed'::"text"])) AND (NOT "public"."grc_has_accepted_evidence"('task'::"text", "t"."id")))));

CREATE OR REPLACE VIEW "public"."v_deployment_readiness_gates" WITH ("security_invoker"='true') AS
 SELECT "h"."organization_id",
    "h"."check_key" AS "gate_key",
    "h"."area" AS "category",
    "h"."severity",
        CASE
            WHEN ("h"."record_count" = 0) THEN 'passed'::"text"
            WHEN ("h"."severity" = 'critical'::"text") THEN 'blocked'::"text"
            ELSE 'warning'::"text"
        END AS "status",
    "h"."title_en",
    "h"."title_ar",
    "h"."details_en",
    "h"."details_ar",
    "h"."record_count",
    "h"."action_path"
   FROM "public"."v_backup_health_check" "h"
UNION ALL
 SELECT "w"."organization_id",
    ('access_'::"text" || "w"."warning_type") AS "gate_key",
    'permissions'::"text" AS "category",
    ("w"."severity")::"text" AS "severity",
        CASE
            WHEN (("w"."severity")::"text" = 'critical'::"text") THEN 'blocked'::"text"
            ELSE 'warning'::"text"
        END AS "status",
    ('Access warning: '::"text" || "w"."warning_type") AS "title_en",
    ('تحذير صلاحيات: '::"text" || "w"."warning_type") AS "title_ar",
    "w"."warning_message" AS "details_en",
    "w"."warning_message" AS "details_ar",
    ("count"(*))::integer AS "record_count",
    '/access-control'::"text" AS "action_path"
   FROM "public"."v_access_control_warnings" "w"
  GROUP BY "w"."organization_id", "w"."warning_type", "w"."warning_message", "w"."severity"
UNION ALL
 SELECT "b"."organization_id",
    ('workflow_'::"text" || "b"."blocker_key") AS "gate_key",
    'workflow'::"text" AS "category",
        CASE
            WHEN ("b"."blocker_key" = ANY (ARRAY['missing_accepted_evidence'::"text", 'missing_delay_reason'::"text"])) THEN 'critical'::"text"
            ELSE 'high'::"text"
        END AS "severity",
        CASE
            WHEN ("b"."blocker_key" = ANY (ARRAY['missing_accepted_evidence'::"text", 'missing_delay_reason'::"text"])) THEN 'blocked'::"text"
            ELSE 'warning'::"text"
        END AS "status",
    "b"."blocker_en" AS "title_en",
    "b"."blocker_ar" AS "title_ar",
    'Workflow blocker requires action before production rollout.'::"text" AS "details_en",
    'مشكلة في سير العمل تحتاج معالجة قبل التشغيل الفعلي.'::"text" AS "details_ar",
    ("count"(*))::integer AS "record_count",
    '/backup-health-check'::"text" AS "action_path"
   FROM "public"."v_workflow_blockers" "b"
  GROUP BY "b"."organization_id", "b"."blocker_key", "b"."blocker_en", "b"."blocker_ar";

CREATE OR REPLACE VIEW "public"."v_document_center_items" WITH ("security_invoker"='true') AS
 SELECT "d"."id",
    "d"."organization_id",
    "d"."document_code",
    "d"."title",
    ("d"."document_type")::"text" AS "document_type",
    "d"."category",
    "d"."version",
    ("d"."status")::"text" AS "status",
    ("d"."risk_level")::"text" AS "risk_level",
    "d"."review_due_date",
    "d"."expiry_date",
    "d"."file_name",
    "d"."file_path",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", ("d"."owner_id")::"text", 'Unassigned'::"text") AS "owner_name",
    "d"."updated_at"
   FROM (("public"."document_center_items" "d"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "d"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "d"."owner_id")))
UNION ALL
 SELECT "p"."id",
    "p"."organization_id",
    "p"."policy_code" AS "document_code",
    "p"."title",
    'policy'::"text" AS "document_type",
    "p"."category",
    "p"."version",
    ("p"."status")::"text" AS "status",
    'medium'::"text" AS "risk_level",
    "p"."review_due_date",
    "p"."expiry_date",
    "p"."file_name",
    "p"."file_path",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", ("p"."owner_id")::"text", 'Unassigned'::"text") AS "owner_name",
    "p"."updated_at"
   FROM (("public"."policies" "p"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "p"."owner_id")));

CREATE OR REPLACE VIEW "public"."v_document_center_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "count"("v".*) AS "total_documents",
    "count"(*) FILTER (WHERE ("v"."status" = ANY (ARRAY['active'::"text", 'approved'::"text"]))) AS "active_documents",
    "count"(*) FILTER (WHERE (("v"."review_due_date" <= (CURRENT_DATE + '30 days'::interval)) AND ("v"."status" <> ALL (ARRAY['archived'::"text", 'cancelled'::"text"])))) AS "review_due_30_days",
    "count"(*) FILTER (WHERE (("v"."expiry_date" IS NOT NULL) AND ("v"."expiry_date" < CURRENT_DATE) AND ("v"."status" <> ALL (ARRAY['archived'::"text", 'cancelled'::"text"])))) AS "expired_documents",
    "count"(*) FILTER (WHERE ("v"."owner_name" = 'Unassigned'::"text")) AS "missing_owner",
    "count"(*) FILTER (WHERE (("v"."file_name" IS NULL) AND ("v"."file_path" IS NULL))) AS "missing_file"
   FROM ("public"."organizations" "o"
     LEFT JOIN "public"."v_document_center_items" "v" ON (("v"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_due_reminder_queue" WITH ("security_invoker"='true') AS
 SELECT "p"."organization_id",
    'project'::"text" AS "item_type",
    "p"."id" AS "item_id",
    "p"."title",
    "p"."owner_id",
    "p"."department_id",
    "p"."target_end_date" AS "due_date",
        CASE
            WHEN ("p"."target_end_date" < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN ("p"."target_end_date" <= (CURRENT_DATE + '3 days'::interval)) THEN 'due_soon'::"text"
            ELSE 'scheduled'::"text"
        END AS "reminder_type",
    ("p"."priority")::"text" AS "priority",
    ("p"."risk_level")::"text" AS "risk_level",
    ("p"."status")::"text" AS "status",
        CASE
            WHEN ("p"."target_end_date" < CURRENT_DATE) THEN (CURRENT_DATE - "p"."target_end_date")
            ELSE 0
        END AS "days_overdue",
    '/projects'::"text" AS "action_path"
   FROM "public"."projects" "p"
  WHERE (("p"."target_end_date" IS NOT NULL) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])) AND ("p"."target_end_date" <= (CURRENT_DATE + '3 days'::interval)))
UNION ALL
 SELECT "m"."organization_id",
    'milestone'::"text" AS "item_type",
    "m"."id" AS "item_id",
    "m"."title",
    "m"."owner_id",
    "p"."department_id",
    "m"."due_date",
        CASE
            WHEN ("m"."due_date" < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN ("m"."due_date" <= (CURRENT_DATE + '3 days'::interval)) THEN 'due_soon'::"text"
            ELSE 'scheduled'::"text"
        END AS "reminder_type",
    ("p"."priority")::"text" AS "priority",
    ("p"."risk_level")::"text" AS "risk_level",
    ("m"."status")::"text" AS "status",
        CASE
            WHEN ("m"."due_date" < CURRENT_DATE) THEN (CURRENT_DATE - "m"."due_date")
            ELSE 0
        END AS "days_overdue",
    '/projects'::"text" AS "action_path"
   FROM ("public"."milestones" "m"
     JOIN "public"."projects" "p" ON (("p"."id" = "m"."project_id")))
  WHERE (("m"."due_date" IS NOT NULL) AND ("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND ("m"."due_date" <= (CURRENT_DATE + '3 days'::interval)))
UNION ALL
 SELECT "t"."organization_id",
    'task'::"text" AS "item_type",
    "t"."id" AS "item_id",
    "t"."title",
    COALESCE("t"."assigned_to", "t"."owner_id") AS "owner_id",
    "p"."department_id",
    "t"."due_date",
        CASE
            WHEN ("t"."due_date" < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN ("t"."due_date" <= (CURRENT_DATE + '3 days'::interval)) THEN 'due_soon'::"text"
            ELSE 'scheduled'::"text"
        END AS "reminder_type",
    ("p"."priority")::"text" AS "priority",
    ("p"."risk_level")::"text" AS "risk_level",
    ("t"."status")::"text" AS "status",
        CASE
            WHEN ("t"."due_date" < CURRENT_DATE) THEN (CURRENT_DATE - "t"."due_date")
            ELSE 0
        END AS "days_overdue",
    '/my-work'::"text" AS "action_path"
   FROM ("public"."tasks" "t"
     JOIN "public"."projects" "p" ON (("p"."id" = "t"."project_id")))
  WHERE (("t"."due_date" IS NOT NULL) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])) AND ("t"."due_date" <= (CURRENT_DATE + '3 days'::interval)))
UNION ALL
 SELECT "o"."organization_id",
    'ovr'::"text" AS "item_type",
    "o"."id" AS "item_id",
    ((COALESCE("o"."ovr_number", 'OVR'::"text") || ' - '::"text") || "left"("o"."brief_description", 80)) AS "title",
    COALESCE("o"."quality_reviewer_id", "o"."supervisor_id", "o"."owner_id") AS "owner_id",
    "o"."department_id",
    COALESCE("o"."quality_due_date", "o"."supervisor_due_date", "o"."corrective_action_due_date") AS "due_date",
        CASE
            WHEN (COALESCE("o"."quality_due_date", "o"."supervisor_due_date", "o"."corrective_action_due_date") < CURRENT_DATE) THEN 'overdue'::"text"
            ELSE 'ovr_followup'::"text"
        END AS "reminder_type",
    'high'::"text" AS "priority",
        CASE
            WHEN ("o"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) THEN 'critical'::"text"
            ELSE 'medium'::"text"
        END AS "risk_level",
    ("o"."status")::"text" AS "status",
        CASE
            WHEN (COALESCE("o"."quality_due_date", "o"."supervisor_due_date", "o"."corrective_action_due_date") < CURRENT_DATE) THEN (CURRENT_DATE - COALESCE("o"."quality_due_date", "o"."supervisor_due_date", "o"."corrective_action_due_date"))
            ELSE 0
        END AS "days_overdue",
    '/ovr'::"text" AS "action_path"
   FROM "public"."ovr_reports" "o"
  WHERE (("o"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status", 'rejected'::"public"."ovr_status"])) AND (COALESCE("o"."quality_due_date", "o"."supervisor_due_date", "o"."corrective_action_due_date") IS NOT NULL) AND (COALESCE("o"."quality_due_date", "o"."supervisor_due_date", "o"."corrective_action_due_date") <= (CURRENT_DATE + '3 days'::interval)))
UNION ALL
 SELECT "a"."organization_id",
    'approval'::"text" AS "item_type",
    "a"."id" AS "item_id",
    COALESCE("a"."request_note", 'Pending approval'::"text") AS "title",
    "a"."approver_id" AS "owner_id",
    NULL::"uuid" AS "department_id",
    ("a"."requested_at")::"date" AS "due_date",
    'pending_approval'::"text" AS "reminder_type",
    'medium'::"text" AS "priority",
    'medium'::"text" AS "risk_level",
    ("a"."status")::"text" AS "status",
    GREATEST((CURRENT_DATE - ("a"."requested_at")::"date"), 0) AS "days_overdue",
    '/approvals'::"text" AS "action_path"
   FROM "public"."approvals" "a"
  WHERE ("a"."status" = 'pending'::"public"."approval_status");

CREATE OR REPLACE VIEW "public"."v_duplicate_active_department_codes" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "lower"(TRIM(BOTH FROM "code")) AS "normalized_code",
    "count"(*) AS "duplicate_count",
    "array_agg"("id" ORDER BY "created_at") AS "department_ids",
    "array_agg"("name_en" ORDER BY "created_at") AS "department_names"
   FROM "public"."departments"
  WHERE (("is_active" = true) AND ("code" IS NOT NULL) AND (TRIM(BOTH FROM "code") <> ''::"text"))
  GROUP BY "organization_id", ("lower"(TRIM(BOTH FROM "code")))
 HAVING ("count"(*) > 1);

CREATE OR REPLACE VIEW "public"."v_duplicate_active_unit_codes" WITH ("security_invoker"='true') AS
 SELECT "department_id",
    "lower"(TRIM(BOTH FROM "code")) AS "normalized_code",
    "count"(*) AS "duplicate_count",
    "array_agg"("id" ORDER BY "created_at") AS "unit_ids",
    "array_agg"("name_en" ORDER BY "created_at") AS "unit_names"
   FROM "public"."units"
  WHERE (("is_active" = true) AND ("code" IS NOT NULL) AND (TRIM(BOTH FROM "code") <> ''::"text"))
  GROUP BY "department_id", ("lower"(TRIM(BOTH FROM "code")))
 HAVING ("count"(*) > 1);

CREATE OR REPLACE VIEW "public"."v_duplicate_profile_emails" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "lower"(TRIM(BOTH FROM "email")) AS "normalized_email",
    "count"(*) AS "duplicate_count",
    "array_agg"("id" ORDER BY "created_at") AS "profile_ids",
    "array_agg"("full_name_en" ORDER BY "created_at") AS "profile_names"
   FROM "public"."profiles"
  WHERE (("email" IS NOT NULL) AND (TRIM(BOTH FROM "email") <> ''::"text"))
  GROUP BY "organization_id", ("lower"(TRIM(BOTH FROM "email")))
 HAVING ("count"(*) > 1);

CREATE OR REPLACE VIEW "public"."v_escalation_center" WITH ("security_invoker"='true') AS
 SELECT "ee"."id",
    "ee"."organization_id",
    "ee"."item_type",
    "ee"."item_id",
    "ee"."title",
    "ee"."escalation_level",
    "ee"."reason",
    "ee"."status",
    "ee"."due_date",
    "ee"."risk_level",
    "ee"."triggered_at",
    "ee"."acknowledged_at",
    "ee"."resolved_at",
    "ee"."resolution_note",
    "d"."name_en" AS "department_name",
    "owner"."full_name_en" AS "owner_name",
    "ack"."full_name_en" AS "acknowledged_by_name",
    "res"."full_name_en" AS "resolved_by_name"
   FROM (((("public"."escalation_events" "ee"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "ee"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "ee"."owner_id")))
     LEFT JOIN "public"."profiles" "ack" ON (("ack"."id" = "ee"."acknowledged_by")))
     LEFT JOIN "public"."profiles" "res" ON (("res"."id" = "ee"."resolved_by")))
  WHERE (("ee"."status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"])) AND ("public"."can_manage_grc"() OR ("ee"."owner_id" = "auth"."uid"())));

CREATE OR REPLACE VIEW "public"."v_evidence_review_queue" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."organization_id",
        CASE
            WHEN ("e"."project_id" IS NOT NULL) THEN 'project'::"text"
            WHEN ("e"."milestone_id" IS NOT NULL) THEN 'milestone'::"text"
            WHEN ("e"."task_id" IS NOT NULL) THEN 'task'::"text"
            WHEN ("e"."risk_id" IS NOT NULL) THEN 'risk'::"text"
            WHEN ("e"."risk_control_id" IS NOT NULL) THEN 'risk_control'::"text"
            WHEN ("e"."compliance_item_id" IS NOT NULL) THEN 'compliance'::"text"
            WHEN ("e"."audit_finding_id" IS NOT NULL) THEN 'audit_finding'::"text"
            WHEN ("e"."policy_id" IS NOT NULL) THEN 'policy'::"text"
            WHEN ("e"."committee_decision_id" IS NOT NULL) THEN 'governance_decision'::"text"
            ELSE 'unknown'::"text"
        END AS "item_type",
    COALESCE("p"."title", "m"."title", "t"."title", "r"."title", "rc"."title", "c"."title", "af"."title", "pol"."title", "cd"."title", 'Untitled item'::"text") AS "item_title",
    "e"."file_name",
    "e"."file_path",
    "e"."description",
    "e"."status",
    "ub"."full_name_en" AS "uploaded_by_name",
    "rv"."full_name_en" AS "reviewed_by_name",
    "e"."created_at"
   FROM ((((((((((("public"."evidence_files" "e"
     LEFT JOIN "public"."projects" "p" ON (("p"."id" = "e"."project_id")))
     LEFT JOIN "public"."milestones" "m" ON (("m"."id" = "e"."milestone_id")))
     LEFT JOIN "public"."tasks" "t" ON (("t"."id" = "e"."task_id")))
     LEFT JOIN "public"."risks" "r" ON (("r"."id" = "e"."risk_id")))
     LEFT JOIN "public"."risk_controls" "rc" ON (("rc"."id" = "e"."risk_control_id")))
     LEFT JOIN "public"."compliance_items" "c" ON (("c"."id" = "e"."compliance_item_id")))
     LEFT JOIN "public"."audit_findings" "af" ON (("af"."id" = "e"."audit_finding_id")))
     LEFT JOIN "public"."policies" "pol" ON (("pol"."id" = "e"."policy_id")))
     LEFT JOIN "public"."committee_decisions" "cd" ON (("cd"."id" = "e"."committee_decision_id")))
     LEFT JOIN "public"."profiles" "ub" ON (("ub"."id" = "e"."uploaded_by")))
     LEFT JOIN "public"."profiles" "rv" ON (("rv"."id" = "e"."reviewed_by")))
  WHERE (("e"."status" = ANY (ARRAY['submitted'::"public"."evidence_status", 'needs_revision'::"public"."evidence_status"])) AND ("public"."can_manage_grc"() OR ("e"."uploaded_by" = "auth"."uid"()) OR ("e"."reviewed_by" = "auth"."uid"())));

CREATE OR REPLACE VIEW "public"."v_evidence_vault_inventory" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."organization_id",
    "e"."file_name",
    "e"."file_path",
    "e"."file_type",
    "e"."file_size",
    "e"."status",
    "e"."created_at",
    "e"."reviewed_at",
    COALESCE("u"."full_name_en", 'Unknown'::"text") AS "uploaded_by_name",
    (COALESCE("rv"."version_count", (0)::bigint))::integer AS "version_count",
    "rv"."latest_version_at",
        CASE
            WHEN ("e"."status" = 'rejected'::"public"."evidence_status") THEN 'attention'::"text"
            WHEN (("e"."reviewed_at" IS NULL) AND ("e"."created_at" < ("now"() - '14 days'::interval))) THEN 'review_overdue'::"text"
            WHEN (COALESCE("rv"."version_count", (0)::bigint) = 0) THEN 'no_version_record'::"text"
            ELSE 'healthy'::"text"
        END AS "vault_status",
        CASE
            WHEN ("e"."ovr_report_id" IS NOT NULL) THEN 'OVR'::"text"
            WHEN ("e"."audit_finding_id" IS NOT NULL) THEN 'Audit'::"text"
            WHEN ("e"."compliance_item_id" IS NOT NULL) THEN 'Compliance'::"text"
            WHEN ("e"."risk_id" IS NOT NULL) THEN 'Risk'::"text"
            WHEN ("e"."project_id" IS NOT NULL) THEN 'Project'::"text"
            WHEN ("e"."milestone_id" IS NOT NULL) THEN 'Milestone'::"text"
            WHEN ("e"."task_id" IS NOT NULL) THEN 'Task'::"text"
            ELSE 'Other'::"text"
        END AS "linked_area"
   FROM (("public"."evidence_files" "e"
     LEFT JOIN "public"."profiles" "u" ON (("u"."id" = "e"."uploaded_by")))
     LEFT JOIN ( SELECT "evidence_file_versions"."evidence_id",
            "count"(*) AS "version_count",
            "max"("evidence_file_versions"."uploaded_at") AS "latest_version_at"
           FROM "public"."evidence_file_versions"
          GROUP BY "evidence_file_versions"."evidence_id") "rv" ON (("rv"."evidence_id" = "e"."id")));

CREATE OR REPLACE VIEW "public"."v_executive_command_stream" WITH ("security_invoker"='true') AS
 SELECT ('project-'::"text" || ("p"."id")::"text") AS "id",
    'Project'::"text" AS "item_type",
    "p"."title",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("p"."status")::"text" AS "status",
    ("p"."risk_level")::"text" AS "risk_level",
    "p"."target_end_date" AS "due_date",
        CASE
            WHEN ("p"."target_end_date" < CURRENT_DATE) THEN 'Project is overdue'::"text"
            WHEN ("p"."risk_level" = 'critical'::"public"."risk_level") THEN 'Critical project requires executive monitoring'::"text"
            ELSE 'High priority project requires attention'::"text"
        END AS "reason",
    '/projects'::"text" AS "action_path",
        CASE
            WHEN ("p"."risk_level" = 'critical'::"public"."risk_level") THEN 1
            ELSE 5
        END AS "sort_rank"
   FROM (("public"."projects" "p"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "p"."owner_id")))
  WHERE (("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])) AND (("p"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])) OR ("p"."target_end_date" < CURRENT_DATE)))
UNION ALL
 SELECT ('risk-'::"text" || ("r"."id")::"text") AS "id",
    'Risk'::"text" AS "item_type",
    "r"."title",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("r"."status")::"text" AS "status",
    ("r"."risk_level")::"text" AS "risk_level",
    "r"."next_review_date" AS "due_date",
        CASE
            WHEN ("r"."next_review_date" < CURRENT_DATE) THEN 'Risk review is overdue'::"text"
            ELSE 'Critical or high risk remains open'::"text"
        END AS "reason",
    '/risks'::"text" AS "action_path",
        CASE
            WHEN ("r"."risk_level" = 'critical'::"public"."risk_level") THEN 2
            ELSE 6
        END AS "sort_rank"
   FROM (("public"."risks" "r"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "r"."owner_id")))
  WHERE (("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"])))
UNION ALL
 SELECT ('compliance-'::"text" || ("c"."id")::"text") AS "id",
    'Compliance'::"text" AS "item_type",
    "c"."title",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("c"."status")::"text" AS "status",
    ("c"."risk_level")::"text" AS "risk_level",
    COALESCE("c"."expiry_date", "c"."due_date") AS "due_date",
    'Compliance item is expired, due soon or missing evidence'::"text" AS "reason",
    '/compliance'::"text" AS "action_path",
    3 AS "sort_rank"
   FROM (("public"."compliance_items" "c"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "c"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "c"."owner_id")))
  WHERE (("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])) AND (("c"."expiry_date" <= (CURRENT_DATE + '30 days'::interval)) OR ("c"."due_date" < CURRENT_DATE) OR ("c"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"]))))
UNION ALL
 SELECT ('audit-'::"text" || ("af"."id")::"text") AS "id",
    'Audit finding'::"text" AS "item_type",
    "af"."title",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("af"."status")::"text" AS "status",
    ("af"."risk_level")::"text" AS "risk_level",
    "af"."due_date",
    'Audit finding remains open or overdue'::"text" AS "reason",
    '/audit'::"text" AS "action_path",
    4 AS "sort_rank"
   FROM (("public"."audit_findings" "af"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "af"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "af"."owner_id")))
  WHERE (("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])) AND (("af"."due_date" < CURRENT_DATE) OR ("af"."risk_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"]))));

CREATE OR REPLACE VIEW "public"."v_global_search_index" WITH ("security_invoker"='true') AS
 SELECT ("p"."id")::"text" AS "id",
    'projects'::"text" AS "source_table",
    'Action plan'::"text" AS "source_type",
    "p"."title",
    COALESCE("p"."description", ''::"text") AS "subtitle",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("p"."status")::"text" AS "status",
    ("p"."risk_level")::"text" AS "risk_level",
    "concat_ws"(' '::"text", "p"."title", "p"."description", "p"."category", "dep"."name_en", "owner"."full_name_en", ("p"."status")::"text", ("p"."risk_level")::"text") AS "search_text",
    '/projects'::"text" AS "action_path",
    "p"."updated_at"
   FROM (("public"."projects" "p"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "p"."owner_id")))
UNION ALL
 SELECT ("r"."id")::"text" AS "id",
    'risks'::"text" AS "source_table",
    'Risk'::"text" AS "source_type",
    "r"."title",
    COALESCE("r"."description", ''::"text") AS "subtitle",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("r"."status")::"text" AS "status",
    ("r"."risk_level")::"text" AS "risk_level",
    "concat_ws"(' '::"text", "r"."risk_code", "r"."title", "r"."description", ("r"."category")::"text", "dep"."name_en", "owner"."full_name_en", ("r"."status")::"text", ("r"."risk_level")::"text") AS "search_text",
    '/risks'::"text" AS "action_path",
    "r"."updated_at"
   FROM (("public"."risks" "r"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "r"."owner_id")))
UNION ALL
 SELECT ("c"."id")::"text" AS "id",
    'compliance_items'::"text" AS "source_table",
    'Compliance'::"text" AS "source_type",
    "c"."title",
    COALESCE("c"."description", ''::"text") AS "subtitle",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("c"."status")::"text" AS "status",
    ("c"."risk_level")::"text" AS "risk_level",
    "concat_ws"(' '::"text", "c"."compliance_code", "c"."title", "c"."description", "c"."regulatory_body", "dep"."name_en", "owner"."full_name_en", ("c"."status")::"text", ("c"."risk_level")::"text") AS "search_text",
    '/compliance'::"text" AS "action_path",
    "c"."updated_at"
   FROM (("public"."compliance_items" "c"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "c"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "c"."owner_id")))
UNION ALL
 SELECT ("af"."id")::"text" AS "id",
    'audit_findings'::"text" AS "source_table",
    'Audit finding'::"text" AS "source_type",
    "af"."title",
    COALESCE("af"."description", ''::"text") AS "subtitle",
    COALESCE("dep"."name_en", 'Company-wide'::"text") AS "department_name",
    COALESCE("owner"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("af"."status")::"text" AS "status",
    ("af"."risk_level")::"text" AS "risk_level",
    "concat_ws"(' '::"text", "af"."finding_code", "af"."audit_title", "af"."title", "af"."description", "af"."root_cause", "af"."recommendation", "dep"."name_en", "owner"."full_name_en", ("af"."status")::"text", ("af"."risk_level")::"text") AS "search_text",
    '/audit'::"text" AS "action_path",
    "af"."updated_at"
   FROM (("public"."audit_findings" "af"
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "af"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "af"."owner_id")))
UNION ALL
 SELECT ("e"."id")::"text" AS "id",
    'evidence_files'::"text" AS "source_table",
    'Evidence'::"text" AS "source_type",
    "e"."file_name" AS "title",
    COALESCE("e"."description", ''::"text") AS "subtitle",
    'Evidence Center'::"text" AS "department_name",
    COALESCE("uploader"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    ("e"."status")::"text" AS "status",
    'medium'::"text" AS "risk_level",
    "concat_ws"(' '::"text", "e"."file_name", "e"."description", ("e"."status")::"text", "uploader"."full_name_en") AS "search_text",
    '/evidence'::"text" AS "action_path",
    "e"."created_at" AS "updated_at"
   FROM ("public"."evidence_files" "e"
     LEFT JOIN "public"."profiles" "uploader" ON (("uploader"."id" = "e"."uploaded_by")))
UNION ALL
 SELECT ("d"."id")::"text" AS "id",
    'documents'::"text" AS "source_table",
    'Document'::"text" AS "source_type",
    "d"."title",
    "concat_ws"(' '::"text", "d"."document_type", "d"."version") AS "subtitle",
    "d"."department_name",
    "d"."owner_name",
    "d"."status",
    "d"."risk_level",
    "concat_ws"(' '::"text", "d"."document_code", "d"."title", "d"."document_type", "d"."category", "d"."department_name", "d"."owner_name", "d"."status", "d"."risk_level") AS "search_text",
    '/documents'::"text" AS "action_path",
    "d"."updated_at"
   FROM "public"."v_document_center_items" "d";

CREATE OR REPLACE VIEW "public"."v_executive_command_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_executive_command_stream" "s"
          WHERE ("s"."risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"]))) AS "critical_now",
    ( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."organization_id" = "o"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))) AS "pending_executive_decisions",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_department_risk_heatmap" "h"
          WHERE (("h"."organization_id" = "o"."id") AND (COALESCE("h"."overall_pressure_score", 0) >= 70))) AS "department_pressure_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_document_center_items" "d"
          WHERE (("d"."organization_id" = "o"."id") AND ("d"."review_due_date" <= (CURRENT_DATE + '30 days'::interval)))) AS "policy_review_due_30_days",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_global_search_index") AS "search_indexed_records",
    GREATEST((0)::bigint, LEAST((100)::bigint, ((100 - (( SELECT "count"(*) AS "count"
           FROM "public"."release_candidate_gates" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'blocked'::"public"."release_gate_status"))) * 25)) - (( SELECT "count"(*) AS "count"
           FROM "public"."release_candidate_gates" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'warning'::"public"."release_gate_status"))) * 8)))) AS "release_readiness_score",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."v_backup_health_check" "b"
              WHERE (("b"."organization_id" = "o"."id") AND ("b"."severity" = 'critical'::"text")))) THEN 'critical'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."v_backup_health_check" "b"
              WHERE (("b"."organization_id" = "o"."id") AND ("b"."severity" = 'warning'::"text")))) THEN 'warning'::"text"
            ELSE 'healthy'::"text"
        END AS "backup_health"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_executive_exception_dashboard" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "exception_code",
    "title_en",
    "title_ar",
    "area",
    "trigger_description_en",
    "trigger_description_ar",
    "severity",
    "response_sla_hours",
    "requires_ceo_visibility",
    "requires_action_plan",
    "is_active",
        CASE
            WHEN ("severity" = 'critical'::"public"."risk_level") THEN 100
            WHEN ("severity" = 'high'::"public"."risk_level") THEN 75
            WHEN ("severity" = 'medium'::"public"."risk_level") THEN 45
            ELSE 25
        END AS "command_weight"
   FROM "public"."executive_exception_rules" "eer"
  WHERE ("is_active" = true);

CREATE OR REPLACE VIEW "public"."v_executive_grc_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    "name_en" AS "organization_name_en",
    "name_ar" AS "organization_name_ar",
    ( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))) AS "active_projects",
    ( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."target_end_date" < CURRENT_DATE) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))) AS "overdue_projects",
    ( SELECT "count"(*) AS "count"
           FROM "public"."milestones" "m"
          WHERE (("m"."organization_id" = "o"."id") AND ("m"."due_date" < CURRENT_DATE) AND ("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))) AS "overdue_milestones",
    ( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE (("t"."organization_id" = "o"."id") AND ("t"."due_date" < CURRENT_DATE) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))) AS "overdue_tasks",
    ( SELECT "count"(*) AS "count"
           FROM "public"."risks" "r"
          WHERE (("r"."organization_id" = "o"."id") AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = 'critical'::"public"."risk_level"))) AS "critical_open_risks",
    ( SELECT "count"(*) AS "count"
           FROM "public"."compliance_items" "c"
          WHERE (("c"."organization_id" = "o"."id") AND ("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + '30 days'::interval)) AND ("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])))) AS "compliance_expiring_30_days",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_findings" "af"
          WHERE (("af"."organization_id" = "o"."id") AND ("af"."due_date" < CURRENT_DATE) AND ("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))) AS "overdue_audit_findings",
    ( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."organization_id" = "o"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))) AS "pending_approvals",
    ( SELECT "count"(*) AS "count"
           FROM "public"."evidence_files" "e"
          WHERE (("e"."organization_id" = "o"."id") AND ("e"."status" = ANY (ARRAY['submitted'::"public"."evidence_status", 'needs_revision'::"public"."evidence_status"])))) AS "pending_evidence_reviews"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_export_dataset_catalog" WITH ("security_invoker"='true') AS
 SELECT "dataset_key",
    "label_en",
    "label_ar",
    "sensitivity",
    "description"
   FROM ( VALUES ('projects'::"text",'Projects & action plans'::"text",'المشاريع وخطط العمل'::"text",'medium'::"text",'Major controlled initiatives, owners, dates, status and risk level'::"text"), ('milestones'::"text",'Milestones'::"text",'المعالم'::"text",'medium'::"text",'Timeline milestones and evidence requirements'::"text"), ('tasks'::"text",'Tasks'::"text",'المهام'::"text",'medium'::"text",'Assigned task-level work and delay reasons'::"text"), ('risks'::"text",'Risk register'::"text",'سجل المخاطر'::"text",'high'::"text",'Inherent/residual risk scoring and owners'::"text"), ('compliance'::"text",'Compliance calendar'::"text",'تقويم الالتزام'::"text",'high'::"text",'Regulatory obligations, expiry dates and owners'::"text"), ('audit_findings'::"text",'Audit findings'::"text",'ملاحظات المراجعة'::"text",'high'::"text",'Audit findings, corrective actions and closure status'::"text"), ('ovr_reports'::"text",'OVR reports'::"text",'بلاغات OVR'::"text",'critical'::"text",'Confidential OVR report metadata'::"text"), ('ovr_risk_indicators'::"text",'OVR risk indicators'::"text",'مؤشرات مخاطر OVR'::"text",'high'::"text",'Department OVR risk signals'::"text"), ('approvals'::"text",'Approvals'::"text",'الموافقات'::"text",'medium'::"text",'Approval workflow rows'::"text"), ('evidence'::"text",'Evidence queue'::"text",'قائمة الأدلة'::"text",'high'::"text",'Evidence review metadata'::"text"), ('escalations'::"text",'Escalations'::"text",'التصعيدات'::"text",'high'::"text",'Open and resolved escalation events'::"text"), ('departments'::"text",'Departments'::"text",'الإدارات'::"text",'low'::"text",'Department master list'::"text"), ('users'::"text",'User access matrix'::"text",'مصفوفة صلاحيات المستخدمين'::"text",'critical'::"text",'User role/access matrix'::"text"), ('kpi_scorecard'::"text",'KPI scorecard'::"text",'بطاقة مؤشرات الأداء'::"text",'medium'::"text",'Executive KPI summary'::"text"), ('department_heatmap'::"text",'Department heatmap'::"text",'الخريطة الحرارية للإدارات'::"text",'medium'::"text",'Department pressure scores'::"text")) "catalog"("dataset_key", "label_en", "label_ar", "sensitivity", "description");

CREATE OR REPLACE VIEW "public"."v_export_center_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    ( SELECT "count"(*) AS "count"
           FROM "public"."custom_report_definitions" "cr"
          WHERE (("cr"."organization_id" = "o"."id") AND ("cr"."is_active" = true))) AS "custom_reports",
    ( SELECT "count"(*) AS "count"
           FROM "public"."data_export_jobs" "dej"
          WHERE (("dej"."organization_id" = "o"."id") AND ("dej"."export_type" = 'dataset'::"public"."export_job_type") AND ("dej"."created_at" >= ("now"() - '30 days'::interval)))) AS "exports_30d",
    ( SELECT "count"(*) AS "count"
           FROM "public"."data_export_jobs" "dej"
          WHERE (("dej"."organization_id" = "o"."id") AND ("dej"."export_type" = 'backup'::"public"."export_job_type") AND ("dej"."created_at" >= ("now"() - '30 days'::interval)))) AS "backups_30d",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_export_dataset_catalog") AS "available_datasets",
    ( SELECT "max"("dej"."created_at") AS "max"
           FROM "public"."data_export_jobs" "dej"
          WHERE (("dej"."organization_id" = "o"."id") AND ("dej"."export_type" = ANY (ARRAY['dataset'::"public"."export_job_type", 'report'::"public"."export_job_type"])))) AS "last_export_at",
    ( SELECT "max"("dej"."created_at") AS "max"
           FROM "public"."data_export_jobs" "dej"
          WHERE (("dej"."organization_id" = "o"."id") AND ("dej"."export_type" = 'backup'::"public"."export_job_type"))) AS "last_backup_at"
   FROM "public"."organizations" "o";

