CREATE OR REPLACE VIEW "public"."v_final_finish_fast_scorecard" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    'v3.0-rc-final-sprint'::"text" AS "release_tag",
    (GREATEST((0)::bigint, LEAST((100)::bigint, ((((100 - ( SELECT ("count"(*) * 18)
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'blocked'::"public"."final_gate_status") AND ("g"."go_live_blocking" = true)))) - ( SELECT ("count"(*) * 8)
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'warning'::"public"."final_gate_status")))) - ( SELECT ("count"(*) * 5)
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = ANY (ARRAY['pending'::"public"."final_gate_status", 'in_progress'::"public"."final_gate_status"])) AND ("g"."go_live_blocking" = true)))) - ( SELECT ("count"(*) * 12)
           FROM "public"."final_acceptance_test_results" "t"
          WHERE (("t"."organization_id" = "o"."id") AND ("t"."status" = ANY (ARRAY['fail'::"public"."final_test_status", 'blocked'::"public"."final_test_status"])) AND ("t"."is_critical" = true)))))))::integer AS "go_live_score",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'blocked'::"public"."final_gate_status"))))::integer AS "blockers",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'warning'::"public"."final_gate_status"))))::integer AS "warnings",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'pass'::"public"."final_gate_status"))))::integer AS "passed",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = ANY (ARRAY['pending'::"public"."final_gate_status", 'in_progress'::"public"."final_gate_status"])))))::integer AS "pending",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."gate_group" = 'migration'::"text") AND ("g"."status" = ANY (ARRAY['blocked'::"public"."final_gate_status", 'warning'::"public"."final_gate_status", 'pending'::"public"."final_gate_status"])))))::integer AS "migration_blocked",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."gate_group" = 'security'::"text") AND ("g"."status" = ANY (ARRAY['blocked'::"public"."final_gate_status", 'warning'::"public"."final_gate_status", 'pending'::"public"."final_gate_status"])))))::integer AS "rls_blocked",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."gate_group" = 'backup'::"text") AND ("g"."status" = ANY (ARRAY['blocked'::"public"."final_gate_status", 'warning'::"public"."final_gate_status", 'pending'::"public"."final_gate_status"])))))::integer AS "backup_blocked",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_release_sprint_items" "g"
          WHERE (("g"."organization_id" = "o"."id") AND ("g"."gate_group" = 'bilingual'::"text") AND ("g"."status" = ANY (ARRAY['blocked'::"public"."final_gate_status", 'warning'::"public"."final_gate_status", 'pending'::"public"."final_gate_status"])))))::integer AS "bilingual_warnings",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_ui_polish_items" "u"
          WHERE (("u"."organization_id" = "o"."id") AND ("u"."severity" = 'critical'::"text") AND ("u"."status" <> ALL (ARRAY['pass'::"public"."final_gate_status", 'not_applicable'::"public"."final_gate_status"])))))::integer AS "open_critical_issues",
    (( SELECT "count"(*) AS "count"
           FROM "public"."final_ui_polish_items" "u"
          WHERE (("u"."organization_id" = "o"."id") AND ("u"."severity" = 'high'::"text") AND ("u"."status" <> ALL (ARRAY['pass'::"public"."final_gate_status", 'not_applicable'::"public"."final_gate_status"])))))::integer AS "open_high_issues",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."final_release_sprint_items" "g"
              WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = 'blocked'::"public"."final_gate_status") AND ("g"."go_live_blocking" = true)))) THEN 'blocked'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."final_release_sprint_items" "g"
              WHERE (("g"."organization_id" = "o"."id") AND ("g"."status" = ANY (ARRAY['warning'::"public"."final_gate_status", 'pending'::"public"."final_gate_status", 'in_progress'::"public"."final_gate_status"])) AND ("g"."go_live_blocking" = true)))) THEN 'conditional'::"text"
            ELSE 'ready'::"text"
        END AS "ready_signal"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_final_go_live_gateboard" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "release_tag",
    "gate_code",
    "gate_group",
    "title",
    "description",
    "owner_label",
    "severity",
    "status",
    "evidence_required",
    "evidence_note",
    "target_date",
    "sequence_no",
    "go_live_blocking",
        CASE
            WHEN ("status" = 'blocked'::"public"."final_gate_status") THEN 100
            WHEN (("status" = 'warning'::"public"."final_gate_status") AND "go_live_blocking") THEN 80
            WHEN ("status" = 'warning'::"public"."final_gate_status") THEN 50
            WHEN (("status" = 'pending'::"public"."final_gate_status") AND "go_live_blocking") THEN 60
            WHEN ("status" = 'in_progress'::"public"."final_gate_status") THEN 30
            ELSE 0
        END AS "gate_weight"
   FROM "public"."final_release_sprint_items";

CREATE OR REPLACE VIEW "public"."v_final_handover_signoffs" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "release_tag",
    "signoff_area",
    "owner_label",
    "status",
    "evidence_note",
    "signed_at",
    "sequence_no",
    "created_at",
    "updated_at"
   FROM "public"."final_handover_signoffs";

CREATE OR REPLACE VIEW "public"."v_final_owner_clearance" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    COALESCE("owner_label", 'Unassigned'::"text") AS "owner_label",
    ("count"(*))::integer AS "total_items",
    ("count"(*) FILTER (WHERE ("status" = 'blocked'::"public"."final_gate_status")))::integer AS "blocked_items",
    ("count"(*) FILTER (WHERE ("status" = 'warning'::"public"."final_gate_status")))::integer AS "warning_items",
    ("count"(*) FILTER (WHERE ("status" = 'pass'::"public"."final_gate_status")))::integer AS "passed_items",
    ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['pending'::"public"."final_gate_status", 'in_progress'::"public"."final_gate_status"]))))::integer AS "pending_items",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("status" = 'blocked'::"public"."final_gate_status")) > 0) THEN 'blocked'::"text"
            WHEN ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['warning'::"public"."final_gate_status", 'pending'::"public"."final_gate_status", 'in_progress'::"public"."final_gate_status"]))) > 0) THEN 'watch'::"text"
            ELSE 'clear'::"text"
        END AS "clearance_signal"
   FROM "public"."final_release_sprint_items"
  GROUP BY "organization_id", COALESCE("owner_label", 'Unassigned'::"text");

CREATE OR REPLACE VIEW "public"."v_ovr_risk_indicator_summary" WITH ("security_invoker"='true') AS
 WITH "feed" AS (
         SELECT "v_ovr_risk_indicator_feed"."id",
            "v_ovr_risk_indicator_feed"."organization_id",
            "v_ovr_risk_indicator_feed"."department_id",
            "v_ovr_risk_indicator_feed"."department_name",
            "v_ovr_risk_indicator_feed"."ovr_number",
            "v_ovr_risk_indicator_feed"."logging_number",
            "v_ovr_risk_indicator_feed"."occurrence_date",
            "v_ovr_risk_indicator_feed"."occurrence_category",
            "v_ovr_risk_indicator_feed"."severity_level",
            "v_ovr_risk_indicator_feed"."severity_weight",
            "v_ovr_risk_indicator_feed"."status",
            "v_ovr_risk_indicator_feed"."corrective_action_required",
            "v_ovr_risk_indicator_feed"."linked_project_id",
            "v_ovr_risk_indicator_feed"."corrective_action_overdue",
            "v_ovr_risk_indicator_feed"."closed_at",
            "v_ovr_risk_indicator_feed"."closure_days",
            "v_ovr_risk_indicator_feed"."created_at"
           FROM "public"."v_ovr_risk_indicator_feed"
          WHERE ("v_ovr_risk_indicator_feed"."status" <> 'cancelled'::"public"."ovr_status")
        ), "repeated" AS (
         SELECT "v_ovr_repeated_category_alerts"."organization_id",
            ("count"(*))::integer AS "repeated_category_alerts_30d"
           FROM "public"."v_ovr_repeated_category_alerts"
          GROUP BY "v_ovr_repeated_category_alerts"."organization_id"
        ), "rollup" AS (
         SELECT "o"."id" AS "organization_id",
            ("count"("f"."id") FILTER (WHERE ("f"."occurrence_date" >= (CURRENT_DATE - '30 days'::interval))))::integer AS "total_ovrs_30d",
            ("count"("f"."id") FILTER (WHERE ("f"."occurrence_date" >= (CURRENT_DATE - '90 days'::interval))))::integer AS "total_ovrs_90d",
            ("count"("f"."id") FILTER (WHERE ("f"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"]))))::integer AS "open_ovrs",
            (COALESCE("sum"("f"."severity_weight") FILTER (WHERE ("f"."occurrence_date" >= (CURRENT_DATE - '30 days'::interval))), (0)::bigint))::integer AS "weighted_score_30d",
            ("count"("f"."id") FILTER (WHERE (("f"."occurrence_date" >= (CURRENT_DATE - '90 days'::interval)) AND ("f"."severity_level" = ANY (ARRAY['level_4'::"text", 'sentinel'::"text"])))))::integer AS "major_or_sentinel_ovrs_90d",
            ("count"("f"."id") FILTER (WHERE ("f"."corrective_action_overdue" = true)))::integer AS "overdue_corrective_actions",
            "round"("avg"("f"."closure_days") FILTER (WHERE ("f"."closure_days" IS NOT NULL)), 1) AS "avg_closure_days"
           FROM ("public"."organizations" "o"
             LEFT JOIN "feed" "f" ON (("f"."organization_id" = "o"."id")))
          GROUP BY "o"."id"
        )
 SELECT "r"."organization_id",
    "r"."total_ovrs_30d",
    "r"."total_ovrs_90d",
    "r"."open_ovrs",
    "r"."weighted_score_30d",
    "r"."major_or_sentinel_ovrs_90d",
    COALESCE("rep"."repeated_category_alerts_30d", 0) AS "repeated_category_alerts_30d",
    "r"."overdue_corrective_actions",
    "r"."avg_closure_days",
    "public"."ovr_signal_level"("r"."weighted_score_30d", "r"."major_or_sentinel_ovrs_90d", COALESCE("rep"."repeated_category_alerts_30d", 0), "r"."overdue_corrective_actions") AS "overall_signal_level"
   FROM ("rollup" "r"
     LEFT JOIN "repeated" "rep" ON (("rep"."organization_id" = "r"."organization_id")));

CREATE OR REPLACE VIEW "public"."v_grc_kpi_scorecard" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    (GREATEST((0)::bigint, LEAST((100)::bigint, ((((100 - COALESCE(( SELECT ("count"(*) * 8)
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."target_end_date" < CURRENT_DATE) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))), (0)::bigint)) - COALESCE(( SELECT ("count"(*) * 3)
           FROM "public"."milestones" "m"
          WHERE (("m"."organization_id" = "o"."id") AND ("m"."due_date" < CURRENT_DATE) AND ("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))), (0)::bigint)) - COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE (("t"."organization_id" = "o"."id") AND ("t"."due_date" < CURRENT_DATE) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))), (0)::bigint)) - COALESCE(( SELECT ("count"(*) * 4)
           FROM "public"."v_delay_reason_queue" "q"
          WHERE ("q"."organization_id" = "o"."id")), (0)::bigint)))))::integer AS "execution_health_score",
    (LEAST((100)::bigint, ((COALESCE(( SELECT ("count"(*) * 14)
           FROM "public"."risks" "r"
          WHERE (("r"."organization_id" = "o"."id") AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."risk_level" = 'critical'::"public"."risk_level"))), (0)::bigint) + COALESCE(( SELECT ("count"(*) * 10)
           FROM "public"."escalation_events" "e"
          WHERE (("e"."organization_id" = "o"."id") AND ("e"."status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"])) AND ("e"."risk_level" = 'critical'::"public"."risk_level"))), (0)::bigint)) + COALESCE(( SELECT ("count"(*) * 10)
           FROM "public"."ovr_reports" "orp"
          WHERE (("orp"."organization_id" = "o"."id") AND ("orp"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) AND ("orp"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"])))), (0)::bigint))))::integer AS "risk_exposure_score",
    (LEAST((100)::bigint, (COALESCE(( SELECT ("count"(*) * 7)
           FROM "public"."compliance_items" "c"
          WHERE (("c"."organization_id" = "o"."id") AND ("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + '30 days'::interval)) AND ("c"."status" <> ALL (ARRAY['closed'::"public"."compliance_status", 'cancelled'::"public"."compliance_status"])))), (0)::bigint) + COALESCE(( SELECT ("count"(*) * 10)
           FROM "public"."audit_findings" "af"
          WHERE (("af"."organization_id" = "o"."id") AND ("af"."due_date" < CURRENT_DATE) AND ("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))), (0)::bigint))))::integer AS "compliance_pressure_score",
    LEAST(100, ((COALESCE(( SELECT "s"."weighted_score_30d"
           FROM "public"."v_ovr_risk_indicator_summary" "s"
          WHERE ("s"."organization_id" = "o"."id")
         LIMIT 1), 0) + COALESCE(( SELECT ("s"."major_or_sentinel_ovrs_90d" * 8)
           FROM "public"."v_ovr_risk_indicator_summary" "s"
          WHERE ("s"."organization_id" = "o"."id")
         LIMIT 1), 0)) + COALESCE(( SELECT ("s"."repeated_category_alerts_30d" * 5)
           FROM "public"."v_ovr_risk_indicator_summary" "s"
          WHERE ("s"."organization_id" = "o"."id")
         LIMIT 1), 0))) AS "ovr_safety_signal_score",
    (GREATEST((0)::bigint, LEAST((100)::bigint, (100 - COALESCE(( SELECT ("count"(*) * 3)
           FROM "public"."evidence_files" "ef"
          WHERE (("ef"."organization_id" = "o"."id") AND ("ef"."status" = ANY (ARRAY['submitted'::"public"."evidence_status", 'needs_revision'::"public"."evidence_status"])))), (0)::bigint)))))::integer AS "evidence_discipline_score",
    (LEAST((100)::bigint, COALESCE(( SELECT ("count"(*) * 5)
           FROM "public"."approvals" "a"
          WHERE (("a"."organization_id" = "o"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))), (0)::bigint)))::integer AS "approval_bottleneck_score"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_i18n_translation_coverage" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "module_key",
    "screen_name",
    "label_group",
    "total_labels",
    "translated_ar",
    "translated_en",
    "rtl_checked",
    "status",
    "reviewer_note",
    "reviewed_by",
    "reviewed_at",
    "created_at",
    "updated_at",
        CASE
            WHEN ("total_labels" = 0) THEN 0
            ELSE ("round"(((100.0 * (LEAST("translated_ar", "translated_en"))::numeric) / ("total_labels")::numeric)))::integer
        END AS "coverage_percent",
    GREATEST(("total_labels" - "translated_ar"), 0) AS "missing_ar_count",
    GREATEST(("total_labels" - "translated_en"), 0) AS "missing_en_count",
        CASE
            WHEN (("total_labels" > 0) AND ("translated_ar" >= "total_labels") AND ("translated_en" >= "total_labels") AND "rtl_checked") THEN 'complete'::"text"
            WHEN ("translated_ar" < "total_labels") THEN 'missing_ar'::"text"
            WHEN ("translated_en" < "total_labels") THEN 'missing_en'::"text"
            ELSE 'needs_rtl_review'::"text"
        END AS "computed_status"
   FROM "public"."i18n_translation_audit" "a";

CREATE OR REPLACE VIEW "public"."v_kri_breach_register" WITH ("security_invoker"='true') AS
 SELECT "ko"."id",
    "ko"."organization_id",
    "ko"."kri_id",
    "kri"."kri_code",
    "kri"."title_en",
    "kri"."title_ar",
    "kri"."category",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "kri"."unit_label",
    "kri"."direction",
    "ko"."observed_at",
    "ko"."value",
    "kri"."watch_threshold",
    "kri"."warning_threshold",
    "kri"."critical_threshold",
    "ko"."breach_level",
    "kri"."owner_id",
    "p"."full_name_en" AS "owner_name_en",
    "p"."full_name_ar" AS "owner_name_ar",
    "ko"."notes"
   FROM ((("public"."kri_observations" "ko"
     JOIN "public"."key_risk_indicators" "kri" ON (("kri"."id" = "ko"."kri_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "kri"."department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "kri"."owner_id")))
  WHERE ("ko"."breach_level" <> 'normal'::"public"."breach_level");

CREATE OR REPLACE VIEW "public"."v_live_grc_capa_queue" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "capa_id",
    "capa_code",
    "source_type",
    "title",
    "owner_name",
    "due_date",
    "capa_status",
        CASE
            WHEN (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("capa_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'overdue'::"text"
            WHEN (("due_date" IS NOT NULL) AND ("due_date" <= (CURRENT_DATE + '14 days'::interval)) AND ("capa_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'due_soon'::"text"
            WHEN ("capa_status" = 'ready_for_retest'::"text") THEN 'ready_for_retest'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."live_grc_capa_register"
  WHERE ("capa_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]));

CREATE OR REPLACE VIEW "public"."v_live_grc_obligation_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "source_authority",
    "obligation_type",
    "obligation_status",
    ("count"(*))::integer AS "obligation_count",
    "min"("next_due_date") AS "nearest_due_date"
   FROM "public"."live_grc_compliance_obligations"
  GROUP BY "organization_id", "source_authority", "obligation_type", "obligation_status";

CREATE OR REPLACE VIEW "public"."v_live_grc_operating_summary" WITH ("security_invoker"='true') AS
 SELECT (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_risk_register"), (0)::bigint))::integer AS "risk_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_risk_register"
          WHERE ("live_grc_risk_register"."risk_status" = ANY (ARRAY['open'::"text", 'under_treatment'::"text"]))), (0)::bigint))::integer AS "active_risk_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_control_register"), (0)::bigint))::integer AS "control_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_control_register"
          WHERE ("live_grc_control_register"."operating_effectiveness" = ANY (ARRAY['ineffective'::"text", 'partially_effective'::"text"]))), (0)::bigint))::integer AS "weak_control_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_compliance_obligations"
          WHERE ("live_grc_compliance_obligations"."obligation_status" = 'active'::"text")), (0)::bigint))::integer AS "active_obligation_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_capa_register"
          WHERE ("live_grc_capa_register"."capa_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))), (0)::bigint))::integer AS "open_capa_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_evidence_requests"
          WHERE ("live_grc_evidence_requests"."request_status" = ANY (ARRAY['requested'::"text", 'rejected'::"text", 'expired'::"text"]))), (0)::bigint))::integer AS "evidence_attention_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."live_grc_closure_packets"
          WHERE ("live_grc_closure_packets"."closure_status" = 'closed'::"text")), (0)::bigint))::integer AS "closed_packet_count";

COMMENT ON VIEW "public"."v_live_grc_operating_summary" IS 'Patch 3 live GRC operating summary filtered through security_invoker and RLS.';

CREATE OR REPLACE VIEW "public"."v_live_grc_risk_control_map" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "risk_id",
    "r"."risk_code",
    "r"."title" AS "risk_title",
    ("r"."residual_likelihood" * "r"."residual_impact") AS "residual_score",
    "r"."risk_status",
    "c"."id" AS "control_id",
    "c"."control_code",
    "c"."title" AS "control_title",
    "c"."design_effectiveness",
    "c"."operating_effectiveness",
    "l"."coverage_type",
    "l"."coverage_strength",
    "c"."next_test_due_date"
   FROM (("public"."live_grc_risk_register" "r"
     LEFT JOIN "public"."live_grc_risk_control_links" "l" ON (("l"."risk_id" = "r"."id")))
     LEFT JOIN "public"."live_grc_control_register" "c" ON (("c"."id" = "l"."control_id")));

CREATE OR REPLACE VIEW "public"."v_load_test_seed_status" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "batch_code",
    "title",
    "target_departments",
    "target_users",
    "target_projects",
    "target_tasks",
    "target_ovr_reports",
    "target_evidence_files",
    "status",
    "last_run_at",
    "duration_ms",
    "performance_note",
    "created_by",
    "created_at",
    "updated_at",
    (((("target_users" + "target_projects") + "target_tasks") + "target_ovr_reports") + "target_evidence_files") AS "target_total_rows",
        CASE
            WHEN (("status" = 'tested'::"text") AND (COALESCE("duration_ms", 999999) <= 3000)) THEN 'healthy'::"text"
            WHEN ("status" = ANY (ARRAY['tested'::"text", 'loaded'::"text"])) THEN 'watch'::"text"
            WHEN ("status" = 'failed'::"text") THEN 'blocked'::"text"
            ELSE 'planned'::"text"
        END AS "performance_signal"
   FROM "public"."load_test_seed_batches" "b";

CREATE OR REPLACE VIEW "public"."v_management_control_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "count"(*) FILTER (WHERE ("ee"."status" = 'open'::"text")) AS "open_escalations",
    "count"(*) FILTER (WHERE ("ee"."status" = 'acknowledged'::"text")) AS "acknowledged_escalations",
    "count"(*) FILTER (WHERE (("ee"."escalation_level" = 'executive'::"text") AND ("ee"."status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"])))) AS "executive_escalations",
    "count"(*) FILTER (WHERE (("ee"."risk_level" = 'critical'::"public"."risk_level") AND ("ee"."status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"])))) AS "critical_escalations",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_delay_reason_queue" "dq"
          WHERE ("dq"."organization_id" = "o"."id")) AS "missing_delay_reasons"
   FROM ("public"."organizations" "o"
     LEFT JOIN "public"."escalation_events" "ee" ON (("ee"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_manager_inbox" WITH ("security_invoker"='true') AS
 SELECT "rq"."organization_id",
    "rq"."department_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "rq"."item_type",
    "rq"."item_id",
    "rq"."title",
    "rq"."owner_id",
    "p"."full_name_en" AS "owner_name_en",
    "p"."full_name_ar" AS "owner_name_ar",
    "rq"."due_date",
    "rq"."reminder_type",
    "rq"."priority",
    "rq"."risk_level",
    "rq"."status",
    "rq"."days_overdue",
    "rq"."action_path"
   FROM (("public"."v_due_reminder_queue" "rq"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "rq"."department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "rq"."owner_id")));

CREATE OR REPLACE VIEW "public"."v_migration_runbook_status" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "sequence_no",
    "migration_file",
    "release_tag",
    "purpose",
    "is_required",
    "verification_query",
    "expected_result",
    "status",
    "verified_at",
    "verified_by",
    "verification_note",
    "created_at",
    "updated_at",
        CASE
            WHEN ("status" = 'verified'::"text") THEN 0
            WHEN ("status" = 'warning'::"text") THEN 40
            WHEN ("status" = 'blocked'::"text") THEN 100
            ELSE 60
        END AS "attention_weight"
   FROM "public"."migration_runbook_entries" "m";

CREATE OR REPLACE VIEW "public"."v_migration_verification_matrix" WITH ("security_invoker"='true') AS
 WITH "latest_run" AS (
         SELECT DISTINCT ON ("migration_verification_runs"."organization_id") "migration_verification_runs"."id",
            "migration_verification_runs"."organization_id"
           FROM "public"."migration_verification_runs"
          ORDER BY "migration_verification_runs"."organization_id", "migration_verification_runs"."created_at" DESC
        ), "latest_items" AS (
         SELECT "i_1"."id",
            "i_1"."run_id",
            "i_1"."organization_id",
            "i_1"."migration_file",
            "i_1"."sequence_no",
            "i_1"."expected",
            "i_1"."verified",
            "i_1"."status",
            "i_1"."verification_note",
            "i_1"."created_at"
           FROM ("public"."migration_verification_items" "i_1"
             JOIN "latest_run" "r_1" ON (("r_1"."id" = "i_1"."run_id")))
        )
 SELECT "r"."sequence_no",
    "r"."migration_file",
    "r"."purpose",
    "r"."required" AS "expected",
    COALESCE("i"."verified", ("r"."sequence_no" < 23)) AS "verified",
        CASE
            WHEN COALESCE("i"."verified", ("r"."sequence_no" < 23)) THEN 'verified'::"text"
            WHEN "r"."required" THEN COALESCE("i"."status", 'pending'::"text")
            ELSE 'warning'::"text"
        END AS "status",
    COALESCE("i"."verification_note",
        CASE
            WHEN ("r"."sequence_no" < 23) THEN 'Migration exists in release order. Confirm applied in Supabase history.'::"text"
            ELSE 'Apply after v1.9 and run preflight.'::"text"
        END) AS "verification_note"
   FROM ("public"."release_migration_order" "r"
     LEFT JOIN "latest_items" "i" ON (("i"."migration_file" = "r"."migration_file")))
  ORDER BY "r"."sequence_no";

CREATE OR REPLACE VIEW "public"."v_module_payload_pressure" WITH ("security_invoker"='true') AS
 SELECT 'projects'::"text" AS "module_key",
    'Projects & Actions'::"text" AS "module_name_en",
    'المشاريع وخطط العمل'::"text" AS "module_name_ar",
    ("count"(*) FILTER (WHERE ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"]))))::integer AS "open_items",
    ("count"(*) FILTER (WHERE (("projects"."target_end_date" < CURRENT_DATE) AND ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))))::integer AS "overdue_items",
    ("count"(*) FILTER (WHERE (("projects"."risk_level" = 'critical'::"public"."risk_level") AND ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))))::integer AS "critical_items",
    (LEAST((100)::bigint, ((("count"(*) FILTER (WHERE ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"]))) * 1) + ("count"(*) FILTER (WHERE (("projects"."target_end_date" < CURRENT_DATE) AND ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))) * 5)) + ("count"(*) FILTER (WHERE (("projects"."risk_level" = 'critical'::"public"."risk_level") AND ("projects"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))) * 7))))::integer AS "pressure_score"
   FROM "public"."projects"
UNION ALL
 SELECT 'tasks'::"text" AS "module_key",
    'Tasks'::"text" AS "module_name_en",
    'المهام'::"text" AS "module_name_ar",
    ("count"(*) FILTER (WHERE ("tasks"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"]))))::integer AS "open_items",
    ("count"(*) FILTER (WHERE (("tasks"."due_date" < CURRENT_DATE) AND ("tasks"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))))::integer AS "overdue_items",
    0 AS "critical_items",
    (LEAST((100)::bigint, (("count"(*) FILTER (WHERE ("tasks"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"]))) * 1) + ("count"(*) FILTER (WHERE (("tasks"."due_date" < CURRENT_DATE) AND ("tasks"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))) * 4))))::integer AS "pressure_score"
   FROM "public"."tasks"
UNION ALL
 SELECT 'risks'::"text" AS "module_key",
    'Risk Register'::"text" AS "module_name_en",
    'سجل المخاطر'::"text" AS "module_name_ar",
    ("count"(*) FILTER (WHERE ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"]))))::integer AS "open_items",
    ("count"(*) FILTER (WHERE (("risks"."next_review_date" < CURRENT_DATE) AND ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])))))::integer AS "overdue_items",
    ("count"(*) FILTER (WHERE (("risks"."risk_level" = 'critical'::"public"."risk_level") AND ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])))))::integer AS "critical_items",
    (LEAST((100)::bigint, ((("count"(*) FILTER (WHERE ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"]))) * 1) + ("count"(*) FILTER (WHERE (("risks"."next_review_date" < CURRENT_DATE) AND ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])))) * 4)) + ("count"(*) FILTER (WHERE (("risks"."risk_level" = 'critical'::"public"."risk_level") AND ("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])))) * 6))))::integer AS "pressure_score"
   FROM "public"."risks"
UNION ALL
 SELECT 'ovr'::"text" AS "module_key",
    'OVR / Incidents'::"text" AS "module_name_en",
    'بلاغات OVR / الحوادث'::"text" AS "module_name_ar",
    ("count"(*) FILTER (WHERE (("ovr_reports"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))))::integer AS "open_items",
    ("count"(*) FILTER (WHERE (("ovr_reports"."created_at" < ("now"() - '7 days'::interval)) AND (("ovr_reports"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])))))::integer AS "overdue_items",
    ("count"(*) FILTER (WHERE ((("ovr_reports"."severity_level")::"text" = ANY (ARRAY['level_4'::"text", 'sentinel'::"text"])) AND (("ovr_reports"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])))))::integer AS "critical_items",
    (LEAST((100)::bigint, ((("count"(*) FILTER (WHERE (("ovr_reports"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) * 2) + ("count"(*) FILTER (WHERE (("ovr_reports"."created_at" < ("now"() - '7 days'::interval)) AND (("ovr_reports"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])))) * 5)) + ("count"(*) FILTER (WHERE ((("ovr_reports"."severity_level")::"text" = ANY (ARRAY['level_4'::"text", 'sentinel'::"text"])) AND (("ovr_reports"."status")::"text" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])))) * 8))))::integer AS "pressure_score"
   FROM "public"."ovr_reports"
UNION ALL
 SELECT 'approvals'::"text" AS "module_key",
    'Approvals'::"text" AS "module_name_en",
    'الموافقات'::"text" AS "module_name_ar",
    ("count"(*) FILTER (WHERE ("approvals"."status" = 'pending'::"public"."approval_status")))::integer AS "open_items",
    ("count"(*) FILTER (WHERE (("approvals"."requested_at" < ("now"() - '7 days'::interval)) AND ("approvals"."status" = 'pending'::"public"."approval_status"))))::integer AS "overdue_items",
    0 AS "critical_items",
    (LEAST((100)::bigint, (("count"(*) FILTER (WHERE ("approvals"."status" = 'pending'::"public"."approval_status")) * 2) + ("count"(*) FILTER (WHERE (("approvals"."requested_at" < ("now"() - '7 days'::interval)) AND ("approvals"."status" = 'pending'::"public"."approval_status"))) * 6))))::integer AS "pressure_score"
   FROM "public"."approvals"
UNION ALL
 SELECT 'audit'::"text" AS "module_key",
    'Audit Follow-up'::"text" AS "module_name_en",
    'متابعة المراجعة'::"text" AS "module_name_ar",
    ("count"(*) FILTER (WHERE ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"]))))::integer AS "open_items",
    ("count"(*) FILTER (WHERE (("audit_findings"."due_date" < CURRENT_DATE) AND ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))))::integer AS "overdue_items",
    ("count"(*) FILTER (WHERE (("audit_findings"."risk_level" = 'critical'::"public"."risk_level") AND ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))))::integer AS "critical_items",
    (LEAST((100)::bigint, ((("count"(*) FILTER (WHERE ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"]))) * 2) + ("count"(*) FILTER (WHERE (("audit_findings"."due_date" < CURRENT_DATE) AND ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))) * 6)) + ("count"(*) FILTER (WHERE (("audit_findings"."risk_level" = 'critical'::"public"."risk_level") AND ("audit_findings"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))) * 8))))::integer AS "pressure_score"
   FROM "public"."audit_findings";

CREATE OR REPLACE VIEW "public"."v_ui_performance_summary" WITH ("security_invoker"='true') AS
 WITH "recent" AS (
         SELECT "ui_performance_events"."id",
            "ui_performance_events"."organization_id",
            "ui_performance_events"."user_id",
            "ui_performance_events"."page_key",
            "ui_performance_events"."event_type",
            "ui_performance_events"."load_ms",
            "ui_performance_events"."viewport_width",
            "ui_performance_events"."viewport_height",
            "ui_performance_events"."device_category",
            "ui_performance_events"."language",
            "ui_performance_events"."details",
            "ui_performance_events"."created_at"
           FROM "public"."ui_performance_events"
          WHERE ("ui_performance_events"."created_at" >= ("now"() - '30 days'::interval))
        ), "scoped" AS (
         SELECT "recent"."organization_id",
            ("count"(*))::integer AS "total_events",
            COALESCE(("round"("avg"("recent"."load_ms")))::integer, 0) AS "avg_load_ms",
            COALESCE(("round"("percentile_cont"((0.95)::double precision) WITHIN GROUP (ORDER BY (("recent"."load_ms")::double precision))))::integer, 0) AS "p95_load_ms",
            ("count"(*) FILTER (WHERE ("recent"."device_category" = ANY (ARRAY['mobile'::"text", 'tablet'::"text"]))))::integer AS "mobile_events",
            ("count"(*) FILTER (WHERE ("recent"."load_ms" >= 2500)))::integer AS "slow_events",
            "max"("recent"."created_at") AS "last_event_at"
           FROM "recent"
          GROUP BY "recent"."organization_id"
        )
 SELECT "scoped"."organization_id",
    "scoped"."total_events",
    "scoped"."avg_load_ms",
    "scoped"."p95_load_ms",
    "scoped"."mobile_events",
    "scoped"."slow_events",
    "scoped"."last_event_at",
    GREATEST(0, LEAST(100, (((100 - ("scoped"."slow_events" * 8)) -
        CASE
            WHEN ("scoped"."p95_load_ms" > 2500) THEN 15
            ELSE 0
        END) -
        CASE
            WHEN ("scoped"."avg_load_ms" > 1200) THEN 8
            ELSE 0
        END))) AS "performance_score"
   FROM "scoped"
UNION ALL
 SELECT ( SELECT "organizations"."id"
           FROM "public"."organizations"
          ORDER BY "organizations"."created_at"
         LIMIT 1) AS "organization_id",
    0 AS "total_events",
    0 AS "avg_load_ms",
    0 AS "p95_load_ms",
    0 AS "mobile_events",
    0 AS "slow_events",
    NULL::timestamp with time zone AS "last_event_at",
    100 AS "performance_score"
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "recent")));

CREATE OR REPLACE VIEW "public"."v_mobile_readiness_gates" WITH ("security_invoker"='true') AS
 SELECT 'responsive_shell'::"text" AS "gate_key",
    'passed'::"text" AS "status",
    'medium'::"text" AS "severity",
    'Responsive shell enabled'::"text" AS "title_en",
    'تفعيل الهيكل المتجاوب'::"text" AS "title_ar",
    'Navigation, cards and forms include responsive CSS rules for smaller screens.'::"text" AS "details_en",
    'تتضمن القائمة والبطاقات والنماذج قواعد CSS متجاوبة للشاشات الصغيرة.'::"text" AS "details_ar",
    0 AS "record_count",
    NULL::"text" AS "action_path"
UNION ALL
 SELECT 'large_open_queues'::"text" AS "gate_key",
        CASE
            WHEN (COALESCE("sum"("v_module_payload_pressure"."open_items"), (0)::bigint) > 300) THEN 'blocked'::"text"
            WHEN (COALESCE("sum"("v_module_payload_pressure"."open_items"), (0)::bigint) > 100) THEN 'warning'::"text"
            ELSE 'passed'::"text"
        END AS "status",
    'high'::"text" AS "severity",
    'Large open queues'::"text" AS "title_en",
    'قوائم مفتوحة كبيرة'::"text" AS "title_ar",
    'High open item volume can slow daily mobile reviews. Use filters and dashboards first.'::"text" AS "details_en",
    'ارتفاع عدد البنود المفتوحة قد يبطئ المراجعة اليومية عبر الجوال. استخدم الفلاتر واللوحات أولاً.'::"text" AS "details_ar",
    (COALESCE("sum"("v_module_payload_pressure"."open_items"), (0)::bigint))::integer AS "record_count",
    '/operations'::"text" AS "action_path"
   FROM "public"."v_module_payload_pressure"
UNION ALL
 SELECT 'slow_browser_signals'::"text" AS "gate_key",
        CASE
            WHEN (COALESCE("sum"("v_ui_performance_summary"."slow_events"), (0)::bigint) > 10) THEN 'blocked'::"text"
            WHEN (COALESCE("sum"("v_ui_performance_summary"."slow_events"), (0)::bigint) > 0) THEN 'warning'::"text"
            ELSE 'passed'::"text"
        END AS "status",
    'medium'::"text" AS "severity",
    'Slow browser signals'::"text" AS "title_en",
    'مؤشرات بطء المتصفح'::"text" AS "title_ar",
    'Recent performance signals are checked for slow page-load experiences.'::"text" AS "details_en",
    'يتم فحص مؤشرات الأداء الأخيرة لرصد تجارب تحميل الصفحات البطيئة.'::"text" AS "details_ar",
    (COALESCE("sum"("v_ui_performance_summary"."slow_events"), (0)::bigint))::integer AS "record_count",
    '/performance'::"text" AS "action_path"
   FROM "public"."v_ui_performance_summary"
UNION ALL
 SELECT 'touch_friendly_controls'::"text" AS "gate_key",
    'passed'::"text" AS "status",
    'low'::"text" AS "severity",
    'Touch-friendly controls'::"text" AS "title_en",
    'أزرار مناسبة للمس'::"text" AS "title_ar",
    'Primary controls use modern button spacing and responsive wrapping.'::"text" AS "details_en",
    'تستخدم الأزرار الرئيسية مسافات حديثة والتفافاً متجاوباً.'::"text" AS "details_ar",
    0 AS "record_count",
    NULL::"text" AS "action_path";

CREATE OR REPLACE VIEW "public"."v_monthly_grc_trend" WITH ("security_invoker"='true') AS
 WITH "months" AS (
         SELECT ("generate_series"(("date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone) - '5 mons'::interval), "date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone), '1 mon'::interval))::"date" AS "month_start"
        ), "org_months" AS (
         SELECT "o"."id" AS "organization_id",
            "m"."month_start"
           FROM ("public"."organizations" "o"
             CROSS JOIN "months" "m")
        )
 SELECT "organization_id",
    "month_start",
    "to_char"(("month_start")::timestamp with time zone, 'Mon'::"text") AS "month_label",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "om"."organization_id") AND (("date_trunc"('month'::"text", "p"."created_at"))::"date" = "om"."month_start"))), (0)::bigint))::integer AS "new_projects",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "om"."organization_id") AND ("p"."closed_at" IS NOT NULL) AND (("date_trunc"('month'::"text", "p"."closed_at"))::"date" = "om"."month_start"))), (0)::bigint))::integer AS "closed_projects",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."risks" "r"
          WHERE (("r"."organization_id" = "om"."organization_id") AND (("date_trunc"('month'::"text", "r"."created_at"))::"date" = "om"."month_start"))), (0)::bigint))::integer AS "new_risks",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."audit_findings" "af"
          WHERE (("af"."organization_id" = "om"."organization_id") AND (("date_trunc"('month'::"text", "af"."created_at"))::"date" = "om"."month_start"))), (0)::bigint))::integer AS "new_audit_findings",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "orp"
          WHERE (("orp"."organization_id" = "om"."organization_id") AND (("date_trunc"('month'::"text", "orp"."created_at"))::"date" = "om"."month_start"))), (0)::bigint))::integer AS "ovr_reports",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "orp"
          WHERE (("orp"."organization_id" = "om"."organization_id") AND (("date_trunc"('month'::"text", "orp"."created_at"))::"date" = "om"."month_start") AND ("orp"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])))), (0)::bigint))::integer AS "major_ovrs"
   FROM "org_months" "om"
  ORDER BY "month_start";

CREATE OR REPLACE VIEW "public"."v_my_open_work" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."organization_id",
    'task'::"text" AS "item_type",
    "t"."title",
    "t"."due_date",
    ("t"."status")::"text" AS "status",
    "t"."progress_percent",
    "t"."owner_id",
    "t"."assigned_to",
    "t"."project_id",
    "t"."milestone_id"
   FROM "public"."tasks" "t"
  WHERE (("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status", 'approved'::"public"."work_status"])) AND (("t"."assigned_to" = "auth"."uid"()) OR ("t"."owner_id" = "auth"."uid"())))
UNION ALL
 SELECT "m"."id",
    "m"."organization_id",
    'milestone'::"text" AS "item_type",
    "m"."title",
    "m"."due_date",
    ("m"."status")::"text" AS "status",
    "m"."progress_percent",
    "m"."owner_id",
    NULL::"uuid" AS "assigned_to",
    "m"."project_id",
    NULL::"uuid" AS "milestone_id"
   FROM "public"."milestones" "m"
  WHERE (("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status", 'approved'::"public"."work_status"])) AND ("m"."owner_id" = "auth"."uid"()));

CREATE OR REPLACE VIEW "public"."v_my_open_work_expanded" WITH ("security_invoker"='true') AS
 SELECT "t"."id",
    "t"."organization_id",
    'task'::"text" AS "item_type",
    "t"."title",
    "t"."due_date",
    ("t"."status")::"text" AS "status",
    "t"."progress_percent",
    "t"."owner_id",
    "t"."assigned_to",
    "t"."project_id",
    "t"."milestone_id",
    "p"."title" AS "project_title",
    "d"."name_en" AS "department_name"
   FROM (("public"."tasks" "t"
     JOIN "public"."projects" "p" ON (("p"."id" = "t"."project_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "p"."department_id")))
  WHERE (("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status", 'approved'::"public"."work_status"])) AND (("t"."assigned_to" = "auth"."uid"()) OR ("t"."owner_id" = "auth"."uid"())))
UNION ALL
 SELECT "m"."id",
    "m"."organization_id",
    'milestone'::"text" AS "item_type",
    "m"."title",
    "m"."due_date",
    ("m"."status")::"text" AS "status",
    "m"."progress_percent",
    "m"."owner_id",
    NULL::"uuid" AS "assigned_to",
    "m"."project_id",
    NULL::"uuid" AS "milestone_id",
    "p"."title" AS "project_title",
    "d"."name_en" AS "department_name"
   FROM (("public"."milestones" "m"
     JOIN "public"."projects" "p" ON (("p"."id" = "m"."project_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "p"."department_id")))
  WHERE (("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status", 'approved'::"public"."work_status"])) AND ("m"."owner_id" = "auth"."uid"()));

CREATE OR REPLACE VIEW "public"."v_notification_digest" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "user_id",
    "full_name_en",
    "full_name_ar",
    "email",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."notifications" "n"
          WHERE (("n"."user_id" = "p"."id") AND ("n"."is_read" = false))), (0)::bigint) AS "unread_notifications",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."v_due_reminder_queue" "rq"
          WHERE (("rq"."owner_id" = "p"."id") AND ("rq"."reminder_type" = 'overdue'::"text"))), (0)::bigint) AS "overdue_assigned_items",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."v_due_reminder_queue" "rq"
          WHERE (("rq"."owner_id" = "p"."id") AND ("rq"."reminder_type" = ANY (ARRAY['due_soon'::"text", 'ovr_followup'::"text"])))), (0)::bigint) AS "due_soon_assigned_items",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."approver_id" = "p"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))), (0)::bigint) AS "pending_approvals",
    COALESCE(( SELECT "max"("n"."created_at") AS "max"
           FROM "public"."notifications" "n"
          WHERE ("n"."user_id" = "p"."id")), "created_at") AS "last_notification_at"
   FROM "public"."profiles" "p"
  WHERE ("is_active" = true);

CREATE OR REPLACE VIEW "public"."v_operational_followup_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."notifications" "n"
          WHERE (("n"."organization_id" = "o"."id") AND ("n"."is_read" = false))), (0)::bigint) AS "unread_notifications",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."organization_id" = "o"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))), (0)::bigint) AS "pending_approvals",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."evidence_files" "e"
          WHERE (("e"."organization_id" = "o"."id") AND ("e"."status" = ANY (ARRAY['submitted'::"public"."evidence_status", 'needs_revision'::"public"."evidence_status"])))), (0)::bigint) AS "pending_evidence_reviews",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."escalation_events" "ee"
          WHERE (("ee"."organization_id" = "o"."id") AND ("ee"."status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"])))), (0)::bigint) AS "active_escalations",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."projects" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."target_end_date" < CURRENT_DATE) AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))), (0)::bigint) AS "overdue_projects",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."milestones" "m"
          WHERE (("m"."organization_id" = "o"."id") AND ("m"."due_date" < CURRENT_DATE) AND ("m"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))), (0)::bigint) AS "overdue_milestones",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE (("t"."organization_id" = "o"."id") AND ("t"."due_date" < CURRENT_DATE) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))), (0)::bigint) AS "overdue_tasks",
    COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "r"
          WHERE (("r"."organization_id" = "o"."id") AND ("r"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status", 'returned_for_clarification'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])))), (0)::bigint) AS "open_ovr_workflow",
    "now"() AS "generated_at"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_ovr_quality_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."organization_id",
    "r"."ovr_number",
    "r"."logging_number",
    "r"."occurrence_date",
    "r"."occurrence_time",
    "r"."occurrence_location",
    "r"."occurrence_category",
    "r"."severity_level",
    "r"."status",
    "r"."corrective_action_required",
    "r"."linked_project_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "owner"."full_name_en" AS "owner_name_en",
    "owner"."full_name_ar" AS "owner_name_ar",
    "reporter"."full_name_en" AS "reporter_name_en",
    "reporter"."full_name_ar" AS "reporter_name_ar",
    "r"."created_at"
   FROM ((("public"."ovr_reports" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "r"."owner_id")))
     LEFT JOIN "public"."profiles" "reporter" ON (("reporter"."id" = "r"."reported_by")))
  WHERE ("r"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"]))
  ORDER BY
        CASE "r"."severity_level"
            WHEN 'sentinel'::"public"."ovr_severity_level" THEN 1
            WHEN 'level_4'::"public"."ovr_severity_level" THEN 2
            WHEN 'level_3'::"public"."ovr_severity_level" THEN 3
            WHEN 'level_2'::"public"."ovr_severity_level" THEN 4
            WHEN 'level_1'::"public"."ovr_severity_level" THEN 5
            ELSE 6
        END, "r"."created_at" DESC;

CREATE OR REPLACE VIEW "public"."v_ovr_risk_attention_items" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "department_id",
    "department_name",
    'ovr_risk_indicator'::"text" AS "item_type",
    ('OVR risk signal: '::"text" || "department_name") AS "title",
    "risk_signal_level",
    "weighted_score_30d",
    "repeated_category_alerts_30d",
    "major_or_sentinel_ovrs_90d",
    "overdue_corrective_actions"
   FROM "public"."v_ovr_risk_indicators_by_department"
  WHERE ("risk_signal_level" = ANY (ARRAY['critical'::"public"."risk_level", 'high'::"public"."risk_level"]));

CREATE OR REPLACE VIEW "public"."v_ovr_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    ("count"("r"."id"))::integer AS "total_reports",
    ("count"("r"."id") FILTER (WHERE ("r"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"]))))::integer AS "open_reports",
    ("count"("r"."id") FILTER (WHERE ("r"."status" = 'under_quality_review'::"public"."ovr_status")))::integer AS "under_quality_review",
    ("count"("r"."id") FILTER (WHERE (("r"."corrective_action_required" = true) AND ("r"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"])))))::integer AS "corrective_actions_required",
    ("count"("r"."id") FILTER (WHERE ("r"."severity_level" = 'sentinel'::"public"."ovr_severity_level")))::integer AS "sentinel_events",
    ("count"("r"."id") FILTER (WHERE ("r"."severity_level" = 'level_1'::"public"."ovr_severity_level")))::integer AS "near_miss_level_1"
   FROM ("public"."organizations" "o"
     LEFT JOIN "public"."ovr_reports" "r" ON (("r"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_ovr_workflow_control_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."organization_id",
    "count"(*) FILTER (WHERE ("o"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'manager_review'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"]))) AS "pending_supervisor_review",
    "count"(*) FILTER (WHERE ("o"."status" = ANY (ARRAY['quality_validation'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status"]))) AS "pending_quality_review",
    "count"(*) FILTER (WHERE ("o"."status" = ANY (ARRAY['returned_for_clarification'::"public"."ovr_status", 'disputed'::"public"."ovr_status", 'reopened'::"public"."ovr_status"]))) AS "returned_for_clarification",
    "count"(*) FILTER (WHERE ("o"."status" = ANY (ARRAY['referred_party_response'::"public"."ovr_status", 'quality_final_review'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"]))) AS "pending_evidence_review",
    "count"(*) FILTER (WHERE (("o"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status", 'rejected'::"public"."ovr_status"])) AND ("o"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])))) AS "major_open_ovrs",
    "count"(*) FILTER (WHERE ("q"."is_overdue" = true)) AS "overdue_ovr_workflow_items"
   FROM ("public"."ovr_reports" "o"
     LEFT JOIN "public"."v_ovr_workflow_queue" "q" ON (("q"."id" = "o"."id")))
  GROUP BY "o"."organization_id";

CREATE OR REPLACE VIEW "public"."v_patch13_evidence_pack_readiness" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "framework_code",
    "department_name",
    ("count"(*))::integer AS "evidence_item_count",
    ("count"(*) FILTER (WHERE ("evidence_status" = 'accepted'::"text")))::integer AS "accepted_count",
    ("count"(*) FILTER (WHERE ("evidence_status" = ANY (ARRAY['needed'::"text", 'rejected'::"text", 'expired'::"text"]))))::integer AS "gap_count",
    "min"("due_date") FILTER (WHERE ("evidence_status" = ANY (ARRAY['needed'::"text", 'rejected'::"text", 'expired'::"text"]))) AS "nearest_gap_due_date",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("evidence_status" = ANY (ARRAY['needed'::"text", 'rejected'::"text", 'expired'::"text"]))) > 0) THEN 'gap_open'::"text"
            WHEN ("count"(*) FILTER (WHERE ("evidence_status" = 'accepted'::"text")) = "count"(*)) THEN 'ready'::"text"
            ELSE 'in_progress'::"text"
        END AS "readiness_signal"
   FROM "public"."patch13_accreditation_evidence_pack_items" "p"
  GROUP BY "organization_id", "framework_code", "department_name";

CREATE OR REPLACE VIEW "public"."v_patch13_failed_retest_queue" WITH ("security_invoker"='true') AS
 SELECT "f"."organization_id",
    "f"."failure_code",
    "f"."failure_title",
    "f"."severity",
    "f"."failure_status",
    "f"."owner_name",
    "f"."due_date",
    "s"."scenario_code",
    "s"."scenario_title",
    "max"("r"."retest_round") AS "latest_retest_round",
    "max"("r"."retested_at") AS "latest_retest_at",
        CASE
            WHEN (("f"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("f"."failure_status" <> ALL (ARRAY['closed'::"text", 'retested_passed'::"text", 'accepted_risk'::"text"]))) THEN 'danger'::"text"
            WHEN (("f"."due_date" IS NOT NULL) AND ("f"."due_date" < CURRENT_DATE) AND ("f"."failure_status" <> ALL (ARRAY['closed'::"text", 'retested_passed'::"text", 'accepted_risk'::"text"]))) THEN 'overdue'::"text"
            WHEN ("f"."failure_status" = 'fixed_pending_retest'::"text") THEN 'retest_ready'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM (("public"."patch13_failed_scenarios" "f"
     JOIN "public"."patch13_role_scenario_scripts" "s" ON (("s"."id" = "f"."scenario_id")))
     LEFT JOIN "public"."patch13_retest_history" "r" ON (("r"."failed_scenario_id" = "f"."id")))
  GROUP BY "f"."organization_id", "f"."failure_code", "f"."failure_title", "f"."severity", "f"."failure_status", "f"."owner_name", "f"."due_date", "s"."scenario_code", "s"."scenario_title";

CREATE OR REPLACE VIEW "public"."v_patch13_role_scenario_queue" WITH ("security_invoker"='true') AS
 SELECT "s"."organization_id",
    "s"."scenario_code",
    "s"."scenario_title",
    "s"."role_key",
    "s"."module_key",
    "s"."accreditation_domain",
    "s"."scenario_status",
    "s"."risk_level",
    "s"."owner_name",
    ("count"(DISTINCT "st"."id"))::integer AS "step_count",
    ("count"(DISTINCT "e"."id"))::integer AS "evidence_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."failure_status" <> ALL (ARRAY['closed'::"text", 'retested_passed'::"text", 'accepted_risk'::"text"]))))::integer AS "open_failure_count",
        CASE
            WHEN ("s"."scenario_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) THEN 'danger'::"text"
            WHEN ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."failure_status" <> ALL (ARRAY['closed'::"text", 'retested_passed'::"text", 'accepted_risk'::"text"]))) > 0) THEN 'warning'::"text"
            WHEN ("s"."scenario_status" = 'passed'::"text") THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ((("public"."patch13_role_scenario_scripts" "s"
     LEFT JOIN "public"."patch13_scenario_steps" "st" ON (("st"."scenario_id" = "s"."id")))
     LEFT JOIN "public"."patch13_evidence_captures" "e" ON (("e"."scenario_id" = "s"."id")))
     LEFT JOIN "public"."patch13_failed_scenarios" "f" ON (("f"."scenario_id" = "s"."id")))
  GROUP BY "s"."organization_id", "s"."scenario_code", "s"."scenario_title", "s"."role_key", "s"."module_key", "s"."accreditation_domain", "s"."scenario_status", "s"."risk_level", "s"."owner_name";

CREATE OR REPLACE VIEW "public"."v_patch13_uat_evidence_summary" WITH ("security_invoker"='true') AS
 SELECT "s"."organization_id",
    ("count"(DISTINCT "s"."id"))::integer AS "scenario_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."scenario_status" = 'passed'::"text")))::integer AS "passed_scenario_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."scenario_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"]))))::integer AS "failed_or_blocked_scenario_count",
    ("count"(DISTINCT "e"."id"))::integer AS "evidence_capture_count",
    ("count"(DISTINCT "e"."id") FILTER (WHERE ("e"."review_status" = 'accepted'::"text")))::integer AS "accepted_evidence_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."failure_status" <> ALL (ARRAY['closed'::"text", 'retested_passed'::"text", 'accepted_risk'::"text"]))))::integer AS "open_failure_count",
    ("count"(DISTINCT "sig"."id") FILTER (WHERE ("sig"."signoff_status" = 'pending'::"text")))::integer AS "pending_signoff_count",
    ("avg"("r"."readiness_score"))::numeric(5,2) AS "average_readiness_score"
   FROM (((("public"."patch13_role_scenario_scripts" "s"
     LEFT JOIN "public"."patch13_evidence_captures" "e" ON (("e"."scenario_id" = "s"."id")))
     LEFT JOIN "public"."patch13_failed_scenarios" "f" ON (("f"."scenario_id" = "s"."id")))
     LEFT JOIN "public"."patch13_signoff_status" "sig" ON (("sig"."organization_id" = "s"."organization_id")))
     LEFT JOIN "public"."patch13_readiness_scores" "r" ON (("r"."organization_id" = "s"."organization_id")))
  GROUP BY "s"."organization_id";

CREATE OR REPLACE VIEW "public"."v_patch14_hardening_queue" WITH ("security_invoker"='true') AS
 SELECT "patch14_client_warning_register"."organization_id",
    'client_warning'::"text" AS "queue_type",
    "patch14_client_warning_register"."warning_code" AS "item_code",
    "patch14_client_warning_register"."warning_title" AS "item_title",
    "patch14_client_warning_register"."warning_status" AS "item_status",
    "patch14_client_warning_register"."severity",
    "patch14_client_warning_register"."owner_name",
    "patch14_client_warning_register"."due_date",
        CASE
            WHEN (("patch14_client_warning_register"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("patch14_client_warning_register"."warning_status" <> ALL (ARRAY['closed'::"text", 'accepted'::"text"]))) THEN 'danger'::"text"
            WHEN ("patch14_client_warning_register"."warning_status" = ANY (ARRAY['open'::"text", 'investigating'::"text"])) THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch14_client_warning_register"
UNION ALL
 SELECT "patch14_v65_warning_closure"."organization_id",
    'v65_warning'::"text" AS "queue_type",
    "patch14_v65_warning_closure"."finding_code" AS "item_code",
    "patch14_v65_warning_closure"."finding_title" AS "item_title",
    "patch14_v65_warning_closure"."closure_status" AS "item_status",
    "patch14_v65_warning_closure"."finding_severity" AS "severity",
    "patch14_v65_warning_closure"."owner_name",
    NULL::"date" AS "due_date",
        CASE
            WHEN ("patch14_v65_warning_closure"."closure_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"])) THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch14_v65_warning_closure"
UNION ALL
 SELECT "patch14_launch_signoffs"."organization_id",
    'launch_signoff'::"text" AS "queue_type",
    "patch14_launch_signoffs"."signoff_code" AS "item_code",
    "patch14_launch_signoffs"."signoff_area" AS "item_title",
    "patch14_launch_signoffs"."signoff_status" AS "item_status",
    'medium'::"text" AS "severity",
    "patch14_launch_signoffs"."signer_name" AS "owner_name",
    "patch14_launch_signoffs"."due_date",
        CASE
            WHEN ("patch14_launch_signoffs"."signoff_status" = 'rejected'::"text") THEN 'danger'::"text"
            WHEN ("patch14_launch_signoffs"."signoff_status" = 'pending'::"text") THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch14_launch_signoffs"
UNION ALL
 SELECT "patch14_post_launch_monitoring_checks"."organization_id",
    'monitoring'::"text" AS "queue_type",
    "patch14_post_launch_monitoring_checks"."check_code" AS "item_code",
    "patch14_post_launch_monitoring_checks"."check_title" AS "item_title",
    "patch14_post_launch_monitoring_checks"."check_status" AS "item_status",
        CASE
            WHEN ("patch14_post_launch_monitoring_checks"."check_status" = 'red'::"text") THEN 'high'::"text"
            WHEN ("patch14_post_launch_monitoring_checks"."check_status" = 'amber'::"text") THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "severity",
    "patch14_post_launch_monitoring_checks"."owner_name",
    NULL::"date" AS "due_date",
        CASE
            WHEN ("patch14_post_launch_monitoring_checks"."check_status" = 'red'::"text") THEN 'danger'::"text"
            WHEN ("patch14_post_launch_monitoring_checks"."check_status" = 'amber'::"text") THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch14_post_launch_monitoring_checks";

CREATE OR REPLACE VIEW "public"."v_patch14_launch_readiness_dashboard" WITH ("security_invoker"='true') AS
 SELECT "g"."organization_id",
    "g"."pack_code",
    "g"."pack_title",
    "g"."pack_status",
    "g"."summary_score",
    "g"."launch_recommendation",
    "g"."board_meeting_date",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'signed'::"text")))::integer AS "signed_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'pending'::"text")))::integer AS "pending_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'rejected'::"text")))::integer AS "rejected_count",
    "max"("d"."decision_status") AS "latest_decision_status",
        CASE
            WHEN ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'rejected'::"text")) > 0) THEN 'danger'::"text"
            WHEN (("g"."launch_recommendation" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"])) AND ("g"."pack_status" = 'approved'::"text") AND ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'pending'::"text")) = 0)) THEN 'ready'::"text"
            WHEN ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'pending'::"text")) > 0) THEN 'warning'::"text"
            ELSE 'normal'::"text"
        END AS "readiness_signal"
   FROM (("public"."patch14_board_go_no_go_pack" "g"
     LEFT JOIN "public"."patch14_launch_signoffs" "s" ON (("s"."organization_id" = "g"."organization_id")))
     LEFT JOIN "public"."patch14_launch_decisions" "d" ON (("d"."organization_id" = "g"."organization_id")))
  GROUP BY "g"."organization_id", "g"."pack_code", "g"."pack_title", "g"."pack_status", "g"."summary_score", "g"."launch_recommendation", "g"."board_meeting_date";

CREATE OR REPLACE VIEW "public"."v_patch14_production_hardening_summary" WITH ("security_invoker"='true') AS
 SELECT COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id", "f"."organization_id", "g"."organization_id", "s"."organization_id", "d"."organization_id", "m"."organization_id") AS "organization_id",
    ("count"(DISTINCT "w"."id") FILTER (WHERE ("w"."warning_status" <> ALL (ARRAY['closed'::"text", 'accepted'::"text"]))))::integer AS "open_client_warning_count",
    ("count"(DISTINCT "v"."id") FILTER (WHERE ("v"."closure_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))))::integer AS "open_v65_warning_count",
    ("count"(DISTINCT "p"."id") FILTER (WHERE ("p"."run_status" = 'passed'::"text")))::integer AS "passed_persona_sql_count",
    ("count"(DISTINCT "b"."id") FILTER (WHERE ("b"."proof_status" = 'passed'::"text")))::integer AS "passed_restore_proof_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."freeze_status" = 'active'::"text")))::integer AS "active_freeze_count",
    ("count"(DISTINCT "g"."id") FILTER (WHERE ("g"."pack_status" = 'approved'::"text")))::integer AS "approved_go_no_go_pack_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'pending'::"text")))::integer AS "pending_launch_signoff_count",
    ("count"(DISTINCT "d"."id") FILTER (WHERE ("d"."decision_status" = ANY (ARRAY['approved_go'::"text", 'approved_conditional_go'::"text"]))))::integer AS "launch_decision_count",
    ("count"(DISTINCT "m"."id") FILTER (WHERE ("m"."check_status" = 'red'::"text")))::integer AS "red_monitoring_check_count"
   FROM (((((((("public"."patch14_client_warning_register" "w"
     FULL JOIN "public"."patch14_v65_warning_closure" "v" ON (("v"."organization_id" = "w"."organization_id")))
     FULL JOIN "public"."patch14_staging_persona_sql_runs" "p" ON (("p"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id"))))
     FULL JOIN "public"."patch14_backup_restore_proof_runs" "b" ON (("b"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id"))))
     FULL JOIN "public"."patch14_change_freeze_records" "f" ON (("f"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id"))))
     FULL JOIN "public"."patch14_board_go_no_go_pack" "g" ON (("g"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id", "f"."organization_id"))))
     FULL JOIN "public"."patch14_launch_signoffs" "s" ON (("s"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id", "f"."organization_id", "g"."organization_id"))))
     FULL JOIN "public"."patch14_launch_decisions" "d" ON (("d"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id", "f"."organization_id", "g"."organization_id", "s"."organization_id"))))
     FULL JOIN "public"."patch14_post_launch_monitoring_checks" "m" ON (("m"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id", "f"."organization_id", "g"."organization_id", "s"."organization_id", "d"."organization_id"))))
  GROUP BY COALESCE("w"."organization_id", "v"."organization_id", "p"."organization_id", "b"."organization_id", "f"."organization_id", "g"."organization_id", "s"."organization_id", "d"."organization_id", "m"."organization_id");

CREATE OR REPLACE VIEW "public"."v_patch15_final_security_closure_summary" WITH ("security_invoker"='true') AS
 SELECT COALESCE("w"."organization_id", "v"."organization_id", "r"."organization_id", "e"."organization_id", "c"."organization_id", "p"."organization_id") AS "organization_id",
    ("count"(DISTINCT "w"."id") FILTER (WHERE ("w"."warning_status" <> ALL (ARRAY['closed'::"text", 'accepted_exception'::"text"]))))::integer AS "open_warning_count",
    ("count"(DISTINCT "w"."id") FILTER (WHERE (("w"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("w"."warning_status" <> ALL (ARRAY['closed'::"text", 'accepted_exception'::"text"])))))::integer AS "high_warning_count",
    ("count"(DISTINCT "v"."id") FILTER (WHERE ("v"."closure_status" <> ALL (ARRAY['closed'::"text", 'accepted_exception'::"text"]))))::integer AS "open_v65_warning_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."review_status" = ANY (ARRAY['pending'::"text", 'needs_bridge'::"text"]))))::integer AS "rpc_review_queue_count",
    ("count"(DISTINCT "e"."id") FILTER (WHERE (("e"."exception_status" = ANY (ARRAY['requested'::"text", 'approved'::"text"])) AND (("e"."expiry_date" IS NULL) OR ("e"."expiry_date" >= CURRENT_DATE)))))::integer AS "active_exception_count",
    ("count"(DISTINCT "c"."id") FILTER (WHERE ("c"."check_status" = ANY (ARRAY['failed'::"text", 'warning'::"text", 'pending'::"text"]))))::integer AS "open_client_check_count",
    ("count"(DISTINCT "p"."id") FILTER (WHERE ("p"."proof_status" = ANY (ARRAY['failed'::"text", 'warning'::"text", 'review_required'::"text", 'pending'::"text"]))))::integer AS "proof_attention_count"
   FROM ((((("public"."patch15_runtime_warning_register" "w"
     FULL JOIN "public"."patch15_v65_warning_closures" "v" ON (("v"."organization_id" = "w"."organization_id")))
     FULL JOIN "public"."patch15_rpc_classification_reviews" "r" ON (("r"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id"))))
     FULL JOIN "public"."patch15_runtime_security_exceptions" "e" ON (("e"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "r"."organization_id"))))
     FULL JOIN "public"."patch15_supabase_client_checks" "c" ON (("c"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "r"."organization_id", "e"."organization_id"))))
     FULL JOIN "public"."patch15_final_hardening_proof_runs" "p" ON (("p"."organization_id" = COALESCE("w"."organization_id", "v"."organization_id", "r"."organization_id", "e"."organization_id", "c"."organization_id"))))
  GROUP BY COALESCE("w"."organization_id", "v"."organization_id", "r"."organization_id", "e"."organization_id", "c"."organization_id", "p"."organization_id");

COMMENT ON VIEW "public"."v_patch15_final_security_closure_summary" IS 'Patch 15 final warning and runtime-security closure summary; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_patch15_rpc_review_queue" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "rpc_name",
    "source_file",
    "source_line",
    "transport",
    "current_classification",
    "approved_classification",
    "review_status",
    "risk_rating",
    "mitigation_plan",
    "reviewer_name",
    "reviewed_at",
        CASE
            WHEN (("risk_rating" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("review_status" = ANY (ARRAY['pending'::"text", 'needs_bridge'::"text"]))) THEN 'high_priority'::"text"
            WHEN ("review_status" = 'needs_bridge'::"text") THEN 'needs_bridge'::"text"
            WHEN ("review_status" = 'pending'::"text") THEN 'pending_review'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch15_rpc_classification_reviews";

CREATE OR REPLACE VIEW "public"."v_patch15_warning_closure_queue" WITH ("security_invoker"='true') AS
 SELECT "patch15_runtime_warning_register"."organization_id",
    "patch15_runtime_warning_register"."warning_code" AS "item_code",
    "patch15_runtime_warning_register"."warning_title" AS "item_title",
    "patch15_runtime_warning_register"."warning_source" AS "item_source",
    "patch15_runtime_warning_register"."severity",
    "patch15_runtime_warning_register"."warning_status" AS "item_status",
    "patch15_runtime_warning_register"."owner_name",
    "patch15_runtime_warning_register"."target_closure_date" AS "due_date",
        CASE
            WHEN (("patch15_runtime_warning_register"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("patch15_runtime_warning_register"."warning_status" <> ALL (ARRAY['closed'::"text", 'accepted_exception'::"text"]))) THEN 'high_priority'::"text"
            WHEN (("patch15_runtime_warning_register"."target_closure_date" IS NOT NULL) AND ("patch15_runtime_warning_register"."target_closure_date" < CURRENT_DATE) AND ("patch15_runtime_warning_register"."warning_status" <> ALL (ARRAY['closed'::"text", 'accepted_exception'::"text"]))) THEN 'overdue'::"text"
            WHEN ("patch15_runtime_warning_register"."warning_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) THEN 'open'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch15_runtime_warning_register"
UNION ALL
 SELECT "patch15_v65_warning_closures"."organization_id",
    "patch15_v65_warning_closures"."finding_issue" AS "item_code",
    "patch15_v65_warning_closures"."finding_file" AS "item_title",
    'v65_audit'::"text" AS "item_source",
    "patch15_v65_warning_closures"."severity",
    "patch15_v65_warning_closures"."closure_status" AS "item_status",
    "patch15_v65_warning_closures"."reviewer_name" AS "owner_name",
    NULL::"date" AS "due_date",
        CASE
            WHEN (("patch15_v65_warning_closures"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("patch15_v65_warning_closures"."closure_status" <> ALL (ARRAY['closed'::"text", 'accepted_exception'::"text"]))) THEN 'high_priority'::"text"
            WHEN ("patch15_v65_warning_closures"."closure_status" = ANY (ARRAY['open'::"text", 'ready_for_retest'::"text"])) THEN 'open'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."patch15_v65_warning_closures";

CREATE OR REPLACE VIEW "public"."v_patch22_executive_risk_escalations" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "risk_id",
    "r"."risk_code",
    "r"."title",
    "r"."risk_level",
    "r"."residual_score",
    "r"."escalation_required",
    "r"."escalation_level",
    "r"."escalated_at",
    "r"."executive_visible",
    "r"."appetite_breached",
    "r"."treatment_status",
    "r"."acceptance_status",
    "r"."next_review_date",
    "d"."name_en" AS "department_name",
    COALESCE("sponsor"."full_name_en", "ro"."full_name_en", "legacy_owner"."full_name_en") AS "executive_owner_name"
   FROM (((("public"."risks" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "sponsor" ON (("sponsor"."id" = "r"."executive_sponsor_id")))
     LEFT JOIN "public"."profiles" "ro" ON (("ro"."id" = "r"."risk_owner_id")))
     LEFT JOIN "public"."profiles" "legacy_owner" ON (("legacy_owner"."id" = "r"."owner_id")))
  WHERE (("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."executive_visible" OR ("r"."escalation_level" = ANY (ARRAY['executive'::"text", 'board'::"text"])) OR ("r"."risk_level" = 'critical'::"public"."risk_level") OR ("r"."residual_score" >= 20)));

CREATE OR REPLACE VIEW "public"."v_patch22_risk_appetite_breaches" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "risk_id",
    "r"."risk_code",
    "r"."title",
    "r"."risk_level",
    "r"."residual_score",
    "r"."appetite_level",
    "r"."appetite_threshold",
    "r"."appetite_breached",
    "r"."appetite_breach_reason",
    "r"."acceptance_status",
    "r"."acceptance_expiry_date",
    "d"."name_en" AS "department_name",
    COALESCE("ro"."full_name_en", "legacy_owner"."full_name_en") AS "risk_owner_name"
   FROM ((("public"."risks" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "ro" ON (("ro"."id" = "r"."risk_owner_id")))
     LEFT JOIN "public"."profiles" "legacy_owner" ON (("legacy_owner"."id" = "r"."owner_id")))
  WHERE (("r"."appetite_breached" = true) AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])));

CREATE OR REPLACE VIEW "public"."v_patch22_risk_closure_blockers" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "risk_id",
    "risk_code",
    "title",
    "risk_level",
    ("status")::"text" AS "status",
    "closure_requested_at",
    "closure_reason",
    "closure_evidence_required",
        CASE
            WHEN ("treatment_required" AND ("treatment_status" <> ALL (ARRAY['completed'::"text", 'accepted'::"text"]))) THEN 'Treatment is required and not complete.'::"text"
            WHEN ("acceptance_required" AND ("acceptance_status" <> 'approved'::"text")) THEN 'Acceptance is required and not approved.'::"text"
            WHEN ("closure_evidence_required" AND (NOT (EXISTS ( SELECT 1
               FROM "public"."evidence_files" "e"
              WHERE (("e"."risk_id" = "r"."id") AND ("e"."status" = 'accepted'::"public"."evidence_status")))))) THEN 'Accepted closure evidence is required.'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."risk_kri_indicators" "k"
              WHERE (("k"."risk_id" = "r"."id") AND ("k"."is_active" = true) AND ("k"."status" = 'critical'::"text")))) THEN 'A critical KRI alert is still active.'::"text"
            WHEN (("next_review_date" IS NOT NULL) AND ("next_review_date" < CURRENT_DATE) AND ("last_reviewed_at" IS NULL)) THEN 'Review is overdue without a documented review.'::"text"
            ELSE NULL::"text"
        END AS "blocker_reason"
   FROM "public"."risks" "r"
  WHERE (("status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND (("closure_requested_at" IS NOT NULL) OR "treatment_required" OR "acceptance_required" OR "closure_evidence_required" OR (EXISTS ( SELECT 1
           FROM "public"."risk_kri_indicators" "k"
          WHERE (("k"."risk_id" = "r"."id") AND ("k"."is_active" = true) AND ("k"."status" = 'critical'::"text"))))));

CREATE OR REPLACE VIEW "public"."v_patch22_risk_kri_alerts" WITH ("security_invoker"='true') AS
 SELECT "k"."organization_id",
    "k"."id" AS "kri_id",
    "k"."risk_id",
    "r"."risk_code",
    "r"."title" AS "risk_title",
    "k"."kri_code",
    "k"."name_en",
    "k"."name_ar",
    "k"."current_value",
    "k"."threshold_warning",
    "k"."threshold_critical",
    "k"."direction",
    "k"."status",
    "k"."measured_at",
    "k"."owner_id",
    "p"."full_name_en" AS "owner_name",
    "r"."risk_level",
    "r"."residual_score"
   FROM (("public"."risk_kri_indicators" "k"
     JOIN "public"."risks" "r" ON (("r"."id" = "k"."risk_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "k"."owner_id")))
  WHERE (("k"."is_active" = true) AND ("k"."status" = ANY (ARRAY['warning'::"text", 'critical'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch22_risk_treatment_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "risk_id",
    "r"."risk_code",
    "r"."title",
    "r"."risk_level",
    "r"."residual_score",
    "r"."treatment_required",
    "r"."treatment_status",
    "r"."treatment_plan_summary",
    "r"."treatment_due_date",
    "r"."treatment_owner_id",
    "tr"."full_name_en" AS "treatment_owner_name",
    (("r"."treatment_due_date" IS NOT NULL) AND ("r"."treatment_due_date" < CURRENT_DATE) AND ("r"."treatment_status" <> ALL (ARRAY['completed'::"text", 'accepted'::"text"]))) AS "treatment_overdue"
   FROM ("public"."risks" "r"
     LEFT JOIN "public"."profiles" "tr" ON (("tr"."id" = "r"."treatment_owner_id")))
  WHERE (("r"."treatment_required" = true) AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])));

CREATE OR REPLACE VIEW "public"."v_patch22_risk_workflow_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "risk_id",
    "r"."risk_code",
    "r"."title",
    "r"."risk_level",
    ("r"."status")::"text" AS "status",
    "r"."lifecycle_status",
    "r"."residual_score",
    "r"."appetite_breached",
    "r"."treatment_required",
    "r"."treatment_status",
    "r"."treatment_due_date",
    "r"."acceptance_required",
    "r"."acceptance_status",
    "r"."next_review_date",
    "r"."review_overdue",
    "r"."closure_requested_at",
    "r"."escalation_required",
    "r"."escalation_level",
    "r"."executive_visible",
    "d"."name_en" AS "department_name",
    COALESCE("ro"."full_name_en", "legacy_owner"."full_name_en") AS "risk_owner_name",
    "tr"."full_name_en" AS "treatment_owner_name",
        CASE
            WHEN (("r"."closure_requested_at" IS NOT NULL) AND ("r"."closure_approved_at" IS NULL)) THEN 'closure_approval'::"text"
            WHEN "r"."escalation_required" THEN 'escalation'::"text"
            WHEN ("r"."appetite_breached" AND ("r"."acceptance_status" <> 'approved'::"text")) THEN 'appetite_acceptance'::"text"
            WHEN ("r"."treatment_required" AND ("r"."treatment_status" <> ALL (ARRAY['completed'::"text", 'accepted'::"text"]))) THEN 'treatment'::"text"
            WHEN (("r"."next_review_date" IS NOT NULL) AND ("r"."next_review_date" < CURRENT_DATE)) THEN 'review_overdue'::"text"
            ELSE 'monitoring'::"text"
        END AS "queue_reason",
    COALESCE("r"."treatment_due_date", "r"."next_review_date", "r"."acceptance_expiry_date") AS "due_date",
    ((("r"."treatment_due_date" IS NOT NULL) AND ("r"."treatment_due_date" < CURRENT_DATE) AND ("r"."treatment_status" <> ALL (ARRAY['completed'::"text", 'accepted'::"text"]))) OR (("r"."next_review_date" IS NOT NULL) AND ("r"."next_review_date" < CURRENT_DATE) AND ("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"]))) OR (("r"."acceptance_expiry_date" IS NOT NULL) AND ("r"."acceptance_expiry_date" <= (CURRENT_DATE + '14 days'::interval)))) AS "is_overdue"
   FROM (((("public"."risks" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "ro" ON (("ro"."id" = "r"."risk_owner_id")))
     LEFT JOIN "public"."profiles" "legacy_owner" ON (("legacy_owner"."id" = "r"."owner_id")))
     LEFT JOIN "public"."profiles" "tr" ON (("tr"."id" = "r"."treatment_owner_id")))
  WHERE (("r"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("r"."escalation_required" OR "r"."appetite_breached" OR ("r"."treatment_required" AND ("r"."treatment_status" <> ALL (ARRAY['completed'::"text", 'accepted'::"text"]))) OR ("r"."acceptance_required" AND ("r"."acceptance_status" <> ALL (ARRAY['approved'::"text", 'not_required'::"text"]))) OR (("r"."next_review_date" IS NOT NULL) AND ("r"."next_review_date" < CURRENT_DATE)) OR (("r"."closure_requested_at" IS NOT NULL) AND ("r"."closure_approved_at" IS NULL))));

CREATE OR REPLACE VIEW "public"."v_patch23_evidence_chain_of_custody" WITH ("security_invoker"='true') AS
 SELECT "ev"."organization_id",
    "ev"."evidence_file_id",
    COALESCE("e"."evidence_code", ('EV-'::"text" || "left"(("ev"."evidence_file_id")::"text", 8))) AS "evidence_code",
    COALESCE("e"."evidence_title", "e"."file_name") AS "evidence_title",
    "ev"."id" AS "event_id",
    "ev"."event_type",
    "ev"."from_status",
    "ev"."to_status",
    "ev"."actor_id",
    "actor"."full_name_en" AS "actor_name",
    "ev"."note",
    "ev"."metadata",
    "ev"."created_at"
   FROM (("public"."evidence_review_events" "ev"
     LEFT JOIN "public"."evidence_files" "e" ON (("e"."id" = "ev"."evidence_file_id")))
     LEFT JOIN "public"."profiles" "actor" ON (("actor"."id" = "ev"."actor_id")));

CREATE OR REPLACE VIEW "public"."v_patch23_evidence_closure_gate_status" WITH ("security_invoker"='true') AS
 WITH "accepted_counts" AS (
         SELECT "er_1"."id" AS "requirement_id",
            ("count"(DISTINCT "e"."id"))::integer AS "accepted_evidence_count"
           FROM (("public"."evidence_requirements" "er_1"
             LEFT JOIN "public"."evidence_links" "el" ON ((("el"."organization_id" = "er_1"."organization_id") AND ("el"."linked_item_type" = "er_1"."linked_item_type") AND ("el"."linked_item_id" = "er_1"."linked_item_id") AND "el"."is_active" AND ((("er_1"."required_for_gate" = 'closure'::"text") AND "el"."required_for_closure") OR (("er_1"."required_for_gate" = 'acceptance'::"text") AND "el"."required_for_acceptance") OR (("er_1"."required_for_gate" = 'approval'::"text") AND "el"."required_for_approval") OR (("er_1"."required_for_gate" = 'treatment'::"text") AND "el"."required_for_treatment") OR ("er_1"."required_for_gate" = ANY (ARRAY['review'::"text", 'audit'::"text", 'regulatory'::"text", 'board_pack'::"text"]))))))
             LEFT JOIN "public"."evidence_files" "e" ON ((("e"."id" = "el"."evidence_file_id") AND (COALESCE("e"."review_status", ("e"."status")::"text") = 'accepted'::"text") AND "e"."is_current_version" AND (("e"."expiry_date" IS NULL) OR ("e"."expiry_date" >= CURRENT_DATE)))))
          WHERE "er_1"."is_active"
          GROUP BY "er_1"."id"
        ), "waivers" AS (
         SELECT "evidence_gate_waivers"."requirement_id",
            "max"("evidence_gate_waivers"."approved_at") AS "approved_at"
           FROM "public"."evidence_gate_waivers"
          WHERE (("evidence_gate_waivers"."status" = 'approved'::"text") AND (("evidence_gate_waivers"."expiry_date" IS NULL) OR ("evidence_gate_waivers"."expiry_date" >= CURRENT_DATE)))
          GROUP BY "evidence_gate_waivers"."requirement_id"
        )
 SELECT "er"."organization_id",
    "er"."id" AS "requirement_id",
    "er"."requirement_code",
    "er"."linked_item_type",
    "er"."linked_item_id",
    "er"."requirement_title",
    "er"."required_for_gate",
    "er"."minimum_accepted_files",
    COALESCE("ac"."accepted_evidence_count", 0) AS "accepted_evidence_count",
    ("w"."requirement_id" IS NOT NULL) AS "waiver_active",
    "w"."approved_at" AS "waiver_approved_at",
    "er"."due_date",
        CASE
            WHEN ("w"."requirement_id" IS NOT NULL) THEN 'waived'::"text"
            WHEN (COALESCE("ac"."accepted_evidence_count", 0) >= "er"."minimum_accepted_files") THEN 'satisfied'::"text"
            WHEN (("er"."due_date" IS NOT NULL) AND ("er"."due_date" < CURRENT_DATE)) THEN 'overdue'::"text"
            WHEN (COALESCE("ac"."accepted_evidence_count", 0) > 0) THEN 'partially_satisfied'::"text"
            ELSE 'pending'::"text"
        END AS "gate_status",
    (("w"."requirement_id" IS NOT NULL) OR (COALESCE("ac"."accepted_evidence_count", 0) >= "er"."minimum_accepted_files")) AS "can_close"
   FROM (("public"."evidence_requirements" "er"
     LEFT JOIN "accepted_counts" "ac" ON (("ac"."requirement_id" = "er"."id")))
     LEFT JOIN "waivers" "w" ON (("w"."requirement_id" = "er"."id")))
  WHERE "er"."is_active";

CREATE OR REPLACE VIEW "public"."v_patch23_evidence_gap_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "requirement_id",
    "requirement_code",
    "linked_item_type",
    "linked_item_id",
    "requirement_title",
    "required_for_gate",
    "minimum_accepted_files",
    "accepted_evidence_count",
    "gate_status",
    "due_date",
    "waiver_active",
    "can_close",
        CASE
            WHEN ("gate_status" = 'overdue'::"text") THEN 'Evidence requirement overdue.'::"text"
            WHEN ("gate_status" = 'pending'::"text") THEN 'No accepted evidence or approved waiver.'::"text"
            WHEN ("gate_status" = 'partially_satisfied'::"text") THEN 'Accepted evidence count is below minimum.'::"text"
            WHEN ("gate_status" = 'waived'::"text") THEN 'Requirement satisfied by approved waiver.'::"text"
            ELSE 'Requirement satisfied.'::"text"
        END AS "gap_reason"
   FROM "public"."v_patch23_evidence_closure_gate_status"
  WHERE ("gate_status" = ANY (ARRAY['pending'::"text", 'partially_satisfied'::"text", 'overdue'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch23_evidence_pack_index" WITH ("security_invoker"='true') AS
 SELECT "el"."organization_id",
    "el"."linked_item_type",
    "el"."linked_item_id",
    "el"."linked_item_title",
    "el"."evidence_file_id",
    COALESCE("e"."evidence_code", ('EV-'::"text" || "left"(("e"."id")::"text", 8))) AS "evidence_code",
    COALESCE("e"."evidence_title", "e"."file_name") AS "evidence_title",
    "e"."file_name",
    "e"."evidence_type",
    "e"."sensitivity_level",
    COALESCE("e"."review_status", ("e"."status")::"text") AS "review_status",
    "e"."reviewer_id",
    "reviewer"."full_name_en" AS "reviewer_name",
    "e"."reviewed_at",
    "el"."is_primary",
    "el"."required_for_closure",
    "el"."required_for_acceptance",
    "el"."required_for_approval",
    "el"."required_for_treatment",
    "el"."linked_at"
   FROM (("public"."evidence_links" "el"
     JOIN "public"."evidence_files" "e" ON (("e"."id" = "el"."evidence_file_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "e"."reviewer_id")))
  WHERE ("el"."is_active" AND "e"."is_current_version");

CREATE OR REPLACE VIEW "public"."v_patch23_evidence_review_queue" WITH ("security_invoker"='true') AS
 SELECT "e"."organization_id",
    "e"."id" AS "evidence_file_id",
    COALESCE("e"."evidence_code", ('EV-'::"text" || "left"(("e"."id")::"text", 8))) AS "evidence_code",
    COALESCE("e"."evidence_title", "e"."file_name") AS "evidence_title",
    "e"."file_name",
    "e"."evidence_type",
    "e"."sensitivity_level",
    "e"."review_status",
    ("e"."status")::"text" AS "legacy_status",
    "e"."review_required",
    "e"."review_due_date",
    "e"."revision_required",
    "e"."revision_due_date",
    "e"."expiry_date",
    "e"."renewal_required",
    "e"."is_current_version",
    "e"."locked_at",
    "e"."uploaded_by",
    "up"."full_name_en" AS "uploaded_by_name",
    "e"."evidence_owner_id",
    "owner"."full_name_en" AS "owner_name",
    "e"."reviewer_id",
    "reviewer"."full_name_en" AS "reviewer_name",
    "e"."created_at",
        CASE
            WHEN (("e"."review_status" = ANY (ARRAY['rejected'::"text", 'needs_revision'::"text"])) OR "e"."revision_required") THEN 'revision_required'::"text"
            WHEN ("e"."review_required" AND ("e"."review_due_date" IS NOT NULL) AND ("e"."review_due_date" < CURRENT_DATE) AND ("e"."review_status" <> ALL (ARRAY['accepted'::"text", 'rejected'::"text"]))) THEN 'review_overdue'::"text"
            WHEN (("e"."expiry_date" IS NOT NULL) AND ("e"."expiry_date" < CURRENT_DATE)) THEN 'expired'::"text"
            WHEN (("e"."expiry_date" IS NOT NULL) AND ("e"."expiry_date" <= (CURRENT_DATE + 30))) THEN 'expiring'::"text"
            WHEN ("e"."review_status" = ANY (ARRAY['submitted'::"text", 'pending_review'::"text"])) THEN 'pending_review'::"text"
            ELSE 'monitor'::"text"
        END AS "queue_reason"
   FROM ((("public"."evidence_files" "e"
     LEFT JOIN "public"."profiles" "up" ON (("up"."id" = "e"."uploaded_by")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "e"."evidence_owner_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "e"."reviewer_id")))
  WHERE ("e"."review_required" AND (("e"."review_status" = ANY (ARRAY['submitted'::"text", 'pending_review'::"text", 'rejected'::"text", 'needs_revision'::"text"])) OR "e"."revision_required" OR (("e"."review_due_date" IS NOT NULL) AND ("e"."review_due_date" < CURRENT_DATE) AND ("e"."review_status" <> 'accepted'::"text")) OR (("e"."expiry_date" IS NOT NULL) AND ("e"."expiry_date" <= (CURRENT_DATE + 30)))));

CREATE OR REPLACE VIEW "public"."v_patch23_sensitive_evidence_register" WITH ("security_invoker"='true') AS
 SELECT "e"."organization_id",
    "e"."id" AS "evidence_file_id",
    COALESCE("e"."evidence_code", ('EV-'::"text" || "left"(("e"."id")::"text", 8))) AS "evidence_code",
    COALESCE("e"."evidence_title", "e"."file_name") AS "evidence_title",
    "e"."file_name",
    "e"."sensitivity_level",
    "e"."classification_reason",
    "e"."review_status",
    "e"."evidence_owner_id",
    "owner"."full_name_en" AS "owner_name",
    "e"."reviewer_id",
    "reviewer"."full_name_en" AS "reviewer_name",
    "e"."expiry_date",
    "e"."renewal_required",
    "e"."renewal_due_date",
    "e"."locked_at",
    "e"."locked_by",
    "locker"."full_name_en" AS "locked_by_name",
    "e"."created_at"
   FROM ((("public"."evidence_files" "e"
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "e"."evidence_owner_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "e"."reviewer_id")))
     LEFT JOIN "public"."profiles" "locker" ON (("locker"."id" = "e"."locked_by")))
  WHERE ("e"."sensitivity_level" = ANY (ARRAY['confidential'::"text", 'highly_sensitive'::"text", 'restricted'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch24_audit_closure_gate_status" WITH ("security_invoker"='true') AS
 WITH "accepted_evidence" AS (
         SELECT "af_1"."id" AS "audit_finding_id",
            ("count"(DISTINCT "ef"."id"))::integer AS "accepted_evidence_count"
           FROM (("public"."audit_findings" "af_1"
             JOIN "public"."evidence_files" "ef" ON (("ef"."organization_id" = "af_1"."organization_id")))
             LEFT JOIN "public"."evidence_links" "el" ON ((("el"."evidence_file_id" = "ef"."id") AND ("el"."is_active" = true))))
          WHERE ((("ef"."audit_finding_id" = "af_1"."id") OR (("el"."linked_item_type" = 'audit_finding'::"text") AND ("el"."linked_item_id" = "af_1"."id"))) AND (COALESCE("ef"."review_status", ("ef"."status")::"text") = 'accepted'::"text") AND (COALESCE("ef"."is_current_version", true) = true) AND (("ef"."expiry_date" IS NULL) OR ("ef"."expiry_date" >= CURRENT_DATE)))
          GROUP BY "af_1"."id"
        ), "active_waivers" AS (
         SELECT "er"."linked_item_id" AS "audit_finding_id",
            ("count"(DISTINCT "egw"."id"))::integer AS "approved_waiver_count",
            "max"("egw"."approved_at") AS "waiver_approved_at"
           FROM ("public"."evidence_requirements" "er"
             JOIN "public"."evidence_gate_waivers" "egw" ON (("egw"."requirement_id" = "er"."id")))
          WHERE (("er"."linked_item_type" = 'audit_finding'::"text") AND ("er"."is_active" = true) AND ("egw"."status" = 'approved'::"text") AND (("egw"."expiry_date" IS NULL) OR ("egw"."expiry_date" >= CURRENT_DATE)))
          GROUP BY "er"."linked_item_id"
        )
 SELECT "af"."organization_id",
    "af"."id" AS "audit_finding_id",
    "af"."finding_code",
    "af"."title",
    "af"."finding_status",
    "af"."workflow_stage",
    "af"."severity_level",
    "af"."evidence_required",
    "af"."minimum_accepted_evidence_count",
    COALESCE("ae"."accepted_evidence_count", 0) AS "accepted_evidence_count",
    COALESCE("aw"."approved_waiver_count", 0) AS "approved_waiver_count",
    "aw"."waiver_approved_at",
        CASE
            WHEN (COALESCE("af"."evidence_required", false) = false) THEN 'not_required'::"text"
            WHEN (COALESCE("ae"."accepted_evidence_count", 0) >= COALESCE("af"."minimum_accepted_evidence_count", 1)) THEN 'satisfied'::"text"
            WHEN (COALESCE("aw"."approved_waiver_count", 0) > 0) THEN 'waived'::"text"
            WHEN (("af"."due_date" IS NOT NULL) AND ("af"."due_date" < CURRENT_DATE)) THEN 'overdue'::"text"
            WHEN (COALESCE("ae"."accepted_evidence_count", 0) > 0) THEN 'partially_satisfied'::"text"
            ELSE 'pending'::"text"
        END AS "evidence_gate_status",
    (((NOT "af"."management_response_required") OR (COALESCE("af"."management_response_status", 'required'::"text") = ANY (ARRAY['accepted'::"text", 'waived'::"text", 'not_required'::"text"]))) AND ((NOT "af"."corrective_action_required") OR (COALESCE("af"."corrective_action_status", 'required'::"text") = ANY (ARRAY['accepted'::"text", 'completed'::"text", 'not_required'::"text"]))) AND ((COALESCE("af"."evidence_required", false) = false) OR (COALESCE("ae"."accepted_evidence_count", 0) >= COALESCE("af"."minimum_accepted_evidence_count", 1)) OR (COALESCE("aw"."approved_waiver_count", 0) > 0))) AS "can_close",
        CASE
            WHEN ("af"."management_response_required" AND (COALESCE("af"."management_response_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'not_required'::"text"]))) THEN 'management_response_not_accepted'::"text"
            WHEN ("af"."corrective_action_required" AND (COALESCE("af"."corrective_action_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'completed'::"text", 'not_required'::"text"]))) THEN 'corrective_action_not_accepted'::"text"
            WHEN ((COALESCE("af"."evidence_required", false) = true) AND (COALESCE("ae"."accepted_evidence_count", 0) < COALESCE("af"."minimum_accepted_evidence_count", 1)) AND (COALESCE("aw"."approved_waiver_count", 0) = 0)) THEN 'accepted_evidence_or_waiver_required'::"text"
            WHEN ("af"."closure_validation_status" = 'blocked'::"text") THEN COALESCE("af"."closure_blocker", 'closure_blocked'::"text")
            ELSE NULL::"text"
        END AS "closure_blocker",
    "af"."closure_requested_at",
    "af"."closure_validation_status"
   FROM (("public"."audit_findings" "af"
     LEFT JOIN "accepted_evidence" "ae" ON (("ae"."audit_finding_id" = "af"."id")))
     LEFT JOIN "active_waivers" "aw" ON (("aw"."audit_finding_id" = "af"."id")));

CREATE OR REPLACE VIEW "public"."v_patch24_audit_closure_pack_index" AS
SELECT
    NULL::"uuid" AS "organization_id",
    NULL::"uuid" AS "audit_finding_id",
    NULL::"text" AS "finding_code",
    NULL::"text" AS "title",
    NULL::"text" AS "audit_title",
    NULL::"text" AS "finding_status",
    NULL::"text" AS "severity_level",
    NULL::"text" AS "management_response_status",
    NULL::"text" AS "corrective_action_status",
    NULL::"text" AS "closure_validation_status",
    NULL::"text" AS "closure_pack_reference",
    NULL::timestamp with time zone AS "closure_pack_generated_at",
    NULL::boolean AS "evidence_required",
    NULL::integer AS "accepted_evidence_count",
    NULL::integer AS "minimum_accepted_evidence_count",
    NULL::integer AS "approved_waiver_count",
    NULL::"text" AS "evidence_gate_status",
    NULL::boolean AS "can_close",
    NULL::"text" AS "closure_blocker",
    NULL::"uuid" AS "closure_validated_by",
    NULL::"text" AS "closure_validator_name",
    NULL::timestamp with time zone AS "closure_validated_at",
    NULL::integer AS "linked_evidence_count";

CREATE OR REPLACE VIEW "public"."v_patch24_audit_executive_escalations" WITH ("security_invoker"='true') AS
 SELECT "af"."organization_id",
    "af"."id" AS "audit_finding_id",
    "af"."finding_code",
    "af"."title",
    "af"."finding_status",
    "af"."severity_level",
    "af"."escalation_required",
    "af"."escalation_level",
    "af"."escalated_at",
    "af"."escalated_to",
    "et"."full_name_en" AS "escalated_to_name",
    "af"."escalation_reason",
    "af"."executive_visible",
    "af"."committee_review_required",
    "af"."committee_review_status",
    "af"."committee_review_note",
    "af"."repeat_finding_flag",
    "af"."systemic_issue_flag",
    "af"."due_date",
    "d"."name_en" AS "department_name",
        CASE
            WHEN "af"."committee_review_required" THEN 'committee_review_required'::"text"
            WHEN "af"."systemic_issue_flag" THEN 'systemic_issue'::"text"
            WHEN "af"."repeat_finding_flag" THEN 'repeat_finding'::"text"
            WHEN (("af"."due_date" IS NOT NULL) AND ("af"."due_date" < CURRENT_DATE)) THEN 'overdue_high_risk'::"text"
            ELSE 'high_or_critical'::"text"
        END AS "escalation_reason_code"
   FROM (("public"."audit_findings" "af"
     LEFT JOIN "public"."profiles" "et" ON (("et"."id" = "af"."escalated_to")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = COALESCE("af"."responsible_department_id", "af"."department_id"))))
  WHERE ("af"."executive_visible" OR "af"."escalation_required" OR "af"."committee_review_required" OR ("af"."severity_level" = ANY (ARRAY['high'::"text", 'critical'::"text"])) OR "af"."repeat_finding_flag" OR "af"."systemic_issue_flag");

CREATE OR REPLACE VIEW "public"."v_patch24_audit_finding_workflow_queue" WITH ("security_invoker"='true') AS
 SELECT "af"."organization_id",
    "af"."id" AS "audit_finding_id",
    "af"."finding_code",
    "af"."audit_title",
    "af"."title",
    "af"."finding_status",
    "af"."workflow_stage",
    "af"."severity_level",
    "af"."management_response_status",
    "af"."corrective_action_status",
    "af"."evidence_gate_status",
    "af"."closure_validation_status",
    "af"."due_date",
    "af"."management_response_due_date",
    "af"."corrective_action_due_date",
    "af"."responsible_department_id",
    "d"."name_en" AS "department_name",
    COALESCE("ro"."full_name_en", "legacy_owner"."full_name_en") AS "responsible_owner_name",
    "ca"."full_name_en" AS "corrective_action_owner_name",
    "am"."full_name_en" AS "audit_manager_name",
    "cg"."accepted_evidence_count",
    "cg"."minimum_accepted_evidence_count",
    "cg"."can_close",
    "cg"."closure_blocker",
        CASE
            WHEN "af"."escalation_required" THEN 'escalation'::"text"
            WHEN ("af"."management_response_required" AND (COALESCE("af"."management_response_status", 'required'::"text") = ANY (ARRAY['required'::"text", 'rejected'::"text", 'overdue'::"text"]))) THEN 'management_response'::"text"
            WHEN ("af"."corrective_action_required" AND (COALESCE("af"."corrective_action_status", 'required'::"text") = ANY (ARRAY['required'::"text", 'rejected'::"text", 'overdue'::"text"]))) THEN 'action_plan'::"text"
            WHEN ("af"."evidence_required" AND (NOT "cg"."can_close")) THEN 'evidence'::"text"
            WHEN (("af"."closure_requested_at" IS NOT NULL) AND (COALESCE("af"."closure_validation_status", 'not_requested'::"text") = ANY (ARRAY['requested'::"text", 'in_validation'::"text"]))) THEN 'auditor_validation'::"text"
            WHEN ("af"."finding_status" = 'returned_for_correction'::"text") THEN 'correction'::"text"
            ELSE 'follow_up'::"text"
        END AS "queue_reason",
    ((("af"."due_date" IS NOT NULL) AND ("af"."due_date" < CURRENT_DATE) AND ("af"."finding_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) OR (("af"."management_response_due_date" IS NOT NULL) AND ("af"."management_response_due_date" < CURRENT_DATE) AND (COALESCE("af"."management_response_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'not_required'::"text"]))) OR (("af"."corrective_action_due_date" IS NOT NULL) AND ("af"."corrective_action_due_date" < CURRENT_DATE) AND (COALESCE("af"."corrective_action_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'completed'::"text", 'not_required'::"text"])))) AS "is_overdue"
   FROM (((((("public"."audit_findings" "af"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = COALESCE("af"."responsible_department_id", "af"."department_id"))))
     LEFT JOIN "public"."profiles" "ro" ON (("ro"."id" = "af"."responsible_owner_id")))
     LEFT JOIN "public"."profiles" "legacy_owner" ON (("legacy_owner"."id" = "af"."owner_id")))
     LEFT JOIN "public"."profiles" "ca" ON (("ca"."id" = "af"."corrective_action_owner_id")))
     LEFT JOIN "public"."profiles" "am" ON (("am"."id" = "af"."audit_manager_id")))
     LEFT JOIN "public"."v_patch24_audit_closure_gate_status" "cg" ON (("cg"."audit_finding_id" = "af"."id")))
  WHERE (("af"."finding_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND ("af"."escalation_required" OR (COALESCE("af"."management_response_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'not_required'::"text"])) OR (COALESCE("af"."corrective_action_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'completed'::"text", 'not_required'::"text"])) OR (NOT COALESCE("cg"."can_close", false)) OR ("af"."closure_requested_at" IS NOT NULL) OR ("af"."finding_status" = ANY (ARRAY['returned_for_correction'::"text", 'reopened'::"text", 'escalated'::"text"]))));

CREATE OR REPLACE VIEW "public"."v_patch24_overdue_audit_findings" WITH ("security_invoker"='true') AS
 SELECT "af"."organization_id",
    "af"."id" AS "audit_finding_id",
    "af"."finding_code",
    "af"."title",
    "af"."finding_status",
    "af"."severity_level",
    "af"."due_date",
    "af"."management_response_due_date",
    "af"."corrective_action_due_date",
    "af"."closure_requested_at",
    "d"."name_en" AS "department_name",
    COALESCE("ro"."full_name_en", "legacy_owner"."full_name_en") AS "responsible_owner_name",
        CASE
            WHEN (("af"."management_response_due_date" IS NOT NULL) AND ("af"."management_response_due_date" < CURRENT_DATE) AND (COALESCE("af"."management_response_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'not_required'::"text"]))) THEN 'management_response_overdue'::"text"
            WHEN (("af"."corrective_action_due_date" IS NOT NULL) AND ("af"."corrective_action_due_date" < CURRENT_DATE) AND (COALESCE("af"."corrective_action_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'completed'::"text", 'not_required'::"text"]))) THEN 'corrective_action_overdue'::"text"
            WHEN (("af"."closure_requested_at" IS NOT NULL) AND (COALESCE("af"."closure_validation_status", 'not_requested'::"text") = ANY (ARRAY['requested'::"text", 'in_validation'::"text"])) AND ("af"."closure_requested_at" < ("now"() - '14 days'::interval))) THEN 'validation_overdue'::"text"
            ELSE 'finding_due_overdue'::"text"
        END AS "overdue_reason",
    GREATEST(COALESCE((CURRENT_DATE - "af"."due_date"), 0), COALESCE((CURRENT_DATE - "af"."management_response_due_date"), 0), COALESCE((CURRENT_DATE - "af"."corrective_action_due_date"), 0)) AS "days_overdue"
   FROM ((("public"."audit_findings" "af"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = COALESCE("af"."responsible_department_id", "af"."department_id"))))
     LEFT JOIN "public"."profiles" "ro" ON (("ro"."id" = "af"."responsible_owner_id")))
     LEFT JOIN "public"."profiles" "legacy_owner" ON (("legacy_owner"."id" = "af"."owner_id")))
  WHERE (("af"."finding_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND ((("af"."due_date" IS NOT NULL) AND ("af"."due_date" < CURRENT_DATE)) OR (("af"."management_response_due_date" IS NOT NULL) AND ("af"."management_response_due_date" < CURRENT_DATE) AND (COALESCE("af"."management_response_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'not_required'::"text"]))) OR (("af"."corrective_action_due_date" IS NOT NULL) AND ("af"."corrective_action_due_date" < CURRENT_DATE) AND (COALESCE("af"."corrective_action_status", 'required'::"text") <> ALL (ARRAY['accepted'::"text", 'completed'::"text", 'not_required'::"text"]))) OR (("af"."closure_requested_at" IS NOT NULL) AND (COALESCE("af"."closure_validation_status", 'not_requested'::"text") = ANY (ARRAY['requested'::"text", 'in_validation'::"text"])) AND ("af"."closure_requested_at" < ("now"() - '14 days'::interval)))));

CREATE OR REPLACE VIEW "public"."v_patch24_repeat_audit_findings" WITH ("security_invoker"='true') AS
 SELECT "af"."organization_id",
    "af"."id" AS "audit_finding_id",
    "af"."finding_code",
    "af"."title",
    "af"."severity_level",
    "af"."root_cause_category",
    "af"."root_cause_summary",
    "af"."repeat_finding_flag",
    "af"."repeat_of_finding_id",
    "parent"."finding_code" AS "repeat_of_finding_code",
    "af"."recurrence_count",
    "af"."recurrence_window_days",
    "af"."systemic_issue_flag",
    "af"."responsible_department_id",
    "d"."name_en" AS "department_name",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."audit_findings" "other"
          WHERE (("other"."organization_id" = "af"."organization_id") AND ("other"."id" <> "af"."id") AND ("other"."finding_status" <> 'cancelled'::"text") AND (NOT (COALESCE("other"."responsible_department_id", "other"."department_id") IS DISTINCT FROM COALESCE("af"."responsible_department_id", "af"."department_id"))) AND ((NOT (NULLIF("other"."root_cause_category", ''::"text") IS DISTINCT FROM NULLIF("af"."root_cause_category", ''::"text"))) OR (NOT ("other"."related_risk_id" IS DISTINCT FROM "af"."related_risk_id")) OR (NOT ("other"."related_compliance_id" IS DISTINCT FROM "af"."related_compliance_id"))) AND ("other"."created_at" >= ("af"."created_at" - (((COALESCE("af"."recurrence_window_days", 365))::"text" || ' days'::"text"))::interval)))) AS "detected_repeat_count"
   FROM (("public"."audit_findings" "af"
     LEFT JOIN "public"."audit_findings" "parent" ON (("parent"."id" = "af"."repeat_of_finding_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = COALESCE("af"."responsible_department_id", "af"."department_id"))))
  WHERE (("af"."repeat_finding_flag" = true) OR ("af"."systemic_issue_flag" = true) OR ("af"."recurrence_count" > 0) OR (EXISTS ( SELECT 1
           FROM "public"."audit_findings" "other"
          WHERE (("other"."organization_id" = "af"."organization_id") AND ("other"."id" <> "af"."id") AND (NOT (COALESCE("other"."responsible_department_id", "other"."department_id") IS DISTINCT FROM COALESCE("af"."responsible_department_id", "af"."department_id"))) AND (NOT (NULLIF("other"."root_cause_category", ''::"text") IS DISTINCT FROM NULLIF("af"."root_cause_category", ''::"text")))))));

CREATE OR REPLACE VIEW "public"."v_patch25_compliance_closure_blockers" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "obligation_id",
    COALESCE("obligation_code", "compliance_code") AS "obligation_code",
    COALESCE("obligation_title", "title") AS "obligation_title",
    "obligation_status",
    "workflow_stage",
    "evidence_required",
    "minimum_accepted_evidence_count",
    "public"."patch25_compliance_accepted_evidence_count"("id") AS "accepted_evidence_count",
    "public"."patch25_compliance_active_waiver_count"("id") AS "approved_waiver_count",
        CASE
            WHEN (COALESCE("evidence_required", false) = false) THEN 'not_required'::"text"
            WHEN ("public"."patch25_compliance_accepted_evidence_count"("id") >= COALESCE("minimum_accepted_evidence_count", 1)) THEN 'satisfied'::"text"
            WHEN ("public"."patch25_compliance_active_waiver_count"("id") > 0) THEN 'waived'::"text"
            WHEN (COALESCE("expiry_date", "renewal_due_date", "due_date") < CURRENT_DATE) THEN 'overdue'::"text"
            WHEN ("public"."patch25_compliance_accepted_evidence_count"("id") > 0) THEN 'partially_satisfied'::"text"
            ELSE 'pending'::"text"
        END AS "evidence_gate_status",
    "public"."patch25_compliance_closure_satisfied"("id") AS "can_close",
        CASE
            WHEN ("obligation_status" = ANY (ARRAY['closed'::"text", 'cancelled'::"text"])) THEN NULL::"text"
            WHEN ((COALESCE("evidence_required", false) = true) AND (NOT "public"."patch25_compliance_closure_satisfied"("id"))) THEN 'accepted_evidence_or_approved_waiver_required'::"text"
            WHEN ("overdue_flag" AND ("closure_requested_at" IS NULL)) THEN 'overdue_obligation_requires_review'::"text"
            WHEN ("escalation_required" AND ("executive_visible" = false)) THEN 'executive_visibility_required'::"text"
            ELSE NULL::"text"
        END AS "blocker_reason",
    "closure_requested_at",
    "closure_blocker"
   FROM "public"."compliance_items" "c"
  WHERE ("obligation_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch25_compliance_evidence_gap_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "obligation_id",
    "obligation_code",
    "obligation_title",
    "obligation_status",
    "workflow_stage",
    "evidence_required",
    "minimum_accepted_evidence_count",
    "accepted_evidence_count",
    "approved_waiver_count",
    "evidence_gate_status",
    "blocker_reason",
    "can_close"
   FROM "public"."v_patch25_compliance_closure_blockers"
  WHERE (("evidence_required" = true) AND ("can_close" = false));

CREATE OR REPLACE VIEW "public"."v_patch25_compliance_obligation_queue" WITH ("security_invoker"='true') AS
 SELECT "c"."organization_id",
    "c"."id" AS "obligation_id",
    COALESCE("c"."obligation_code", "c"."compliance_code") AS "obligation_code",
    COALESCE("c"."obligation_title", "c"."title") AS "obligation_title",
    "c"."obligation_type",
    COALESCE("c"."regulator_name", "c"."regulatory_body") AS "regulator_name",
    "c"."department_id",
    "d"."name_en" AS "department_name",
    "c"."obligation_owner_id",
    "owner"."full_name_en" AS "owner_name",
    "c"."reviewer_id",
    "reviewer"."full_name_en" AS "reviewer_name",
    "c"."risk_level",
    "c"."criticality_level",
    "c"."obligation_status",
    "c"."workflow_stage",
    "c"."expiry_date",
    "c"."renewal_required",
    "c"."renewal_due_date",
    "c"."next_review_date",
    "c"."evidence_required",
    "b"."evidence_gate_status",
    "b"."accepted_evidence_count",
    "b"."minimum_accepted_evidence_count",
    "b"."can_close",
    "b"."blocker_reason",
    "c"."overdue_flag",
    "c"."overdue_days",
    "c"."escalation_required",
    "c"."executive_visible",
        CASE
            WHEN "c"."escalation_required" THEN 'escalation'::"text"
            WHEN "c"."overdue_flag" THEN 'overdue'::"text"
            WHEN ("c"."renewal_required" AND ("c"."renewal_due_date" IS NOT NULL) AND ("c"."renewal_due_date" <= (CURRENT_DATE + 30))) THEN 'renewal'::"text"
            WHEN (("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + 30))) THEN 'due_soon'::"text"
            WHEN ("c"."evidence_required" AND (NOT "b"."can_close")) THEN 'evidence'::"text"
            WHEN (("c"."closure_requested_at" IS NOT NULL) AND ("c"."closure_approved_at" IS NULL)) THEN 'closure_review'::"text"
            ELSE 'monitoring'::"text"
        END AS "queue_reason"
   FROM (((("public"."compliance_items" "c"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "c"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = COALESCE("c"."obligation_owner_id", "c"."owner_id"))))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "c"."reviewer_id")))
     LEFT JOIN "public"."v_patch25_compliance_closure_blockers" "b" ON (("b"."obligation_id" = "c"."id")))
  WHERE (("c"."obligation_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND ("c"."escalation_required" OR "c"."overdue_flag" OR (("c"."expiry_date" IS NOT NULL) AND ("c"."expiry_date" <= (CURRENT_DATE + 30))) OR ("c"."renewal_required" AND ("c"."renewal_due_date" IS NOT NULL) AND ("c"."renewal_due_date" <= (CURRENT_DATE + 30))) OR ("c"."evidence_required" AND (NOT "b"."can_close")) OR (("c"."closure_requested_at" IS NOT NULL) AND ("c"."closure_approved_at" IS NULL))));

CREATE OR REPLACE VIEW "public"."v_patch25_due_soon_obligations" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "obligation_id",
    "obligation_code",
    "obligation_title",
    "obligation_type",
    "regulator_name",
    "department_id",
    "department_name",
    "obligation_owner_id",
    "owner_name",
    "reviewer_id",
    "reviewer_name",
    "risk_level",
    "criticality_level",
    "obligation_status",
    "workflow_stage",
    "expiry_date",
    "renewal_required",
    "renewal_due_date",
    "next_review_date",
    "evidence_required",
    "evidence_gate_status",
    "accepted_evidence_count",
    "minimum_accepted_evidence_count",
    "can_close",
    "blocker_reason",
    "overdue_flag",
    "overdue_days",
    "escalation_required",
    "executive_visible",
    "queue_reason"
   FROM "public"."v_patch25_compliance_obligation_queue"
  WHERE (("queue_reason" = ANY (ARRAY['due_soon'::"text", 'renewal'::"text"])) OR ((COALESCE("expiry_date", "renewal_due_date", "next_review_date") >= CURRENT_DATE) AND (COALESCE("expiry_date", "renewal_due_date", "next_review_date") <= (CURRENT_DATE + 30))));

CREATE OR REPLACE VIEW "public"."v_patch25_executive_compliance_escalations" WITH ("security_invoker"='true') AS
 SELECT "c"."organization_id",
    "c"."id" AS "obligation_id",
    COALESCE("c"."obligation_code", "c"."compliance_code") AS "obligation_code",
    COALESCE("c"."obligation_title", "c"."title") AS "obligation_title",
    "c"."obligation_status",
    "c"."risk_level",
    "c"."criticality_level",
    "c"."escalation_required",
    "c"."escalation_level",
    "c"."escalated_at",
    "c"."escalated_to",
    "escalated"."full_name_en" AS "escalated_to_name",
    "c"."escalation_reason",
    "c"."executive_visible",
    "c"."overdue_flag",
    "c"."overdue_days",
    "c"."expiry_date",
    "c"."renewal_due_date",
    "d"."name_en" AS "department_name",
        CASE
            WHEN ("c"."overdue_flag" AND ("c"."risk_level" = ANY (ARRAY['high'::"public"."risk_level", 'critical'::"public"."risk_level"]))) THEN 'high_risk_overdue'::"text"
            WHEN ("c"."criticality_level" = 'critical'::"text") THEN 'critical_obligation'::"text"
            WHEN ("c"."renewal_required" AND ("c"."renewal_due_date" < CURRENT_DATE)) THEN 'renewal_overdue'::"text"
            ELSE 'executive_visible'::"text"
        END AS "escalation_reason_code"
   FROM (("public"."compliance_items" "c"
     LEFT JOIN "public"."profiles" "escalated" ON (("escalated"."id" = "c"."escalated_to")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "c"."department_id")))
  WHERE ("c"."escalation_required" OR "c"."executive_visible" OR ("c"."risk_level" = ANY (ARRAY['high'::"public"."risk_level", 'critical'::"public"."risk_level"])) OR ("c"."criticality_level" = ANY (ARRAY['high'::"text", 'critical'::"text"])) OR "c"."overdue_flag");

CREATE OR REPLACE VIEW "public"."v_patch25_overdue_obligations" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
