CREATE OR REPLACE VIEW "public"."v_patch26_documents_due_for_review" WITH ("security_invoker"='true') AS
 SELECT "document_id",
    "organization_id",
    "document_code",
    "document_title",
    "document_type",
    "document_category",
    "department_id",
    "department_name",
    "document_owner_id",
    "document_owner_name",
