CREATE OR REPLACE VIEW "public"."v_patch26_staff_acknowledgment_gaps" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "requirement_id",
    "r"."document_id",
    "d"."organization_id",
    "d"."document_code",
    "d"."document_title",
    "r"."version_id",
    COALESCE("r"."user_id", "p"."id") AS "user_id",
    "p"."full_name_en" AS "user_name",
    "r"."department_id",
    "r"."role_name",
    "r"."due_date",
    "r"."required_flag",
        CASE
            WHEN ("a"."id" IS NOT NULL) THEN 'acknowledged'::"text"
            WHEN (("r"."due_date" IS NOT NULL) AND ("r"."due_date" < CURRENT_DATE)) THEN 'overdue'::"text"
            ELSE 'pending'::"text"
        END AS "acknowledgment_status"
   FROM ((("public"."document_acknowledgment_requirements" "r"
     JOIN "public"."controlled_documents" "d" ON (("d"."id" = "r"."document_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "r"."user_id")))
     LEFT JOIN "public"."document_acknowledgments" "a" ON ((("a"."document_id" = "r"."document_id") AND (NOT ("a"."version_id" IS DISTINCT FROM "r"."version_id")) AND ("a"."user_id" = "r"."user_id"))))
  WHERE ((COALESCE("r"."required_flag", true) = true) AND ("r"."user_id" IS NOT NULL) AND ("a"."id" IS NULL));

