CREATE OR REPLACE VIEW "public"."v_patch27_approval_bottlenecks" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "workflow_type",
    "action_type",
    "request_status",
    "count"(*) AS "request_count",
    "min"("requested_at") AS "oldest_requested_at",
    "count"(*) FILTER (WHERE (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE))) AS "overdue_count"
   FROM "public"."approval_requests"
  WHERE ("request_status" = ANY (ARRAY['pending'::"text", 'partially_approved'::"text", 'escalated'::"text"]))
  GROUP BY "organization_id", "workflow_type", "action_type", "request_status";

