     JOIN "public"."capa_action_plans" "c" ON (("c"."id" = "i"."capa_id")))
  WHERE (COALESCE(("i"."status")::"text", ''::"text") <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch28_capa_closure_blockers" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "capa_id",
    "capa_code",
    "capa_title",
    "capa_status",
    (EXISTS ( SELECT 1
           FROM "public"."capa_action_items" "i"
          WHERE (("i"."capa_id" = "c"."id") AND (("i"."status")::"text" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))))) AS "has_incomplete_action_items",
    (COALESCE("evidence_required", false) AND (COALESCE("evidence_gate_status", 'pending'::"text") <> ALL (ARRAY['accepted'::"text", 'satisfied'::"text", 'waived'::"text", 'not_required'::"text"]))) AS "has_evidence_blocker",
    (COALESCE("validation_required", false) AND (COALESCE("validation_status", 'pending'::"text") <> 'approved'::"text")) AS "has_validation_blocker",
    (COALESCE("effectiveness_review_required", false) AND (COALESCE("effectiveness_review_status", 'pending'::"text") <> ALL (ARRAY['passed'::"text", 'effective'::"text"]))) AS "has_effectiveness_blocker",
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM "public"."capa_action_items" "i"
              WHERE (("i"."capa_id" = "c"."id") AND (("i"."status")::"text" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))))) THEN 'incomplete_action_items'::"text"
            WHEN (COALESCE("evidence_required", false) AND (COALESCE("evidence_gate_status", 'pending'::"text") <> ALL (ARRAY['accepted'::"text", 'satisfied'::"text", 'waived'::"text", 'not_required'::"text"]))) THEN 'evidence_gate_not_satisfied'::"text"
            WHEN (COALESCE("validation_required", false) AND (COALESCE("validation_status", 'pending'::"text") <> 'approved'::"text")) THEN 'validation_approval_required'::"text"
            WHEN (COALESCE("effectiveness_review_required", false) AND (COALESCE("effectiveness_review_status", 'pending'::"text") <> ALL (ARRAY['passed'::"text", 'effective'::"text"]))) THEN 'effectiveness_review_not_passed'::"text"
            ELSE NULL::"text"
        END AS "blocker_reason",
    (NOT ((EXISTS ( SELECT 1
           FROM "public"."capa_action_items" "i"
          WHERE (("i"."capa_id" = "c"."id") AND (("i"."status")::"text" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))))) OR (COALESCE("evidence_required", false) AND (COALESCE("evidence_gate_status", 'pending'::"text") <> ALL (ARRAY['accepted'::"text", 'satisfied'::"text", 'waived'::"text", 'not_required'::"text"]))) OR (COALESCE("validation_required", false) AND (COALESCE("validation_status", 'pending'::"text") <> 'approved'::"text")) OR (COALESCE("effectiveness_review_required", false) AND (COALESCE("effectiveness_review_status", 'pending'::"text") <> ALL (ARRAY['passed'::"text", 'effective'::"text"]))))) AS "can_close"
   FROM "public"."capa_action_plans" "c";

