     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "c"."capa_owner_id")))
     LEFT JOIN "public"."profiles" "action_owner" ON (("action_owner"."id" = "c"."action_owner_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "c"."reviewer_id")))
