CREATE OR REPLACE VIEW "public"."v_patch29_accreditation_training_readiness" WITH ("security_invoker"='true') AS
 SELECT "tp"."id" AS "program_id",
    "tp"."title" AS "program_title",
    "tp"."title_ar" AS "program_title_ar",
    "tp"."training_type",
    "tp"."department_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "count"("ta"."id") AS "total_assigned",
    "count"(
        CASE
            WHEN ("ta"."status" = 'completed'::"text") THEN 1
            ELSE NULL::integer
        END) AS "total_completed",
    "count"(
        CASE
            WHEN ("ta"."status" = 'overdue'::"text") THEN 1
            ELSE NULL::integer
        END) AS "total_overdue",
        CASE
            WHEN ("count"("ta"."id") = 0) THEN 0.0
            ELSE "round"(((("count"(
            CASE
                WHEN ("ta"."status" = 'completed'::"text") THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"("ta"."id"))::numeric) * (100)::numeric), 2)
        END AS "completion_rate"
   FROM (("public"."training_programs" "tp"
     LEFT JOIN "public"."training_assignments" "ta" ON (("ta"."program_id" = "tp"."id")))
     LEFT JOIN "public"."departments" "d" ON (("tp"."department_id" = "d"."id")))
  WHERE ("tp"."training_type" = 'accreditation_training'::"text")
  GROUP BY "tp"."id", "tp"."title", "tp"."title_ar", "tp"."training_type", "tp"."department_id", "d"."name_en", "d"."name_ar";

CREATE OR REPLACE VIEW "public"."v_patch29_competency_gap_dashboard" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "user_id",
    "p"."full_name_en" AS "user_name_en",
    "p"."full_name_ar" AS "user_name_ar",
    "ca"."competency_area",
    "ca"."result",
    "ca"."score",
    "ca"."assessed_at",
    "ca"."assessor_user_id",
    "p_assess"."full_name_en" AS "assessor_name_en",
    "p_assess"."full_name_ar" AS "assessor_name_ar"
   FROM (("public"."profiles" "p"
     LEFT JOIN "public"."competency_assessments" "ca" ON (("p"."id" = "ca"."user_id")))
     LEFT JOIN "public"."profiles" "p_assess" ON (("ca"."assessor_user_id" = "p_assess"."id")))
  WHERE (("p"."is_active" = true) AND (("ca"."result" = 'failed'::"text") OR ("ca"."result" = 'needs_retraining'::"text") OR ("ca"."id" IS NULL)));

CREATE OR REPLACE VIEW "public"."v_patch29_training_assignment_queue" WITH ("security_invoker"='true') AS
 SELECT "ta"."id",
    "ta"."program_id",
    "ta"."assigned_to_user_id",
    "ta"."assigned_to_role",
    "ta"."assigned_to_department_id",
    "ta"."due_date",
    "ta"."status",
    "ta"."assigned_at",
    "ta"."assigned_by",
    "ta"."completed_at",
    "ta"."completion_evidence_id",
    "tp"."title" AS "program_title",
    "tp"."title_ar" AS "program_title_ar",
    "tp"."training_type",
    "p_assign"."full_name_en" AS "assigned_user_name_en",
    "p_assign"."full_name_ar" AS "assigned_user_name_ar",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar"
   FROM ((("public"."training_assignments" "ta"
     JOIN "public"."training_programs" "tp" ON (("ta"."program_id" = "tp"."id")))
     LEFT JOIN "public"."profiles" "p_assign" ON (("ta"."assigned_to_user_id" = "p_assign"."id")))
     LEFT JOIN "public"."departments" "d" ON (("ta"."assigned_to_department_id" = "d"."id")));

CREATE OR REPLACE VIEW "public"."v_patch29_overdue_training_assignments" WITH ("security_invoker"='true') AS
 SELECT "id",
    "program_id",
    "assigned_to_user_id",
    "assigned_to_role",
    "assigned_to_department_id",
    "due_date",
    "status",
    "assigned_at",
    "assigned_by",
    "completed_at",
    "completion_evidence_id",
    "program_title",
    "program_title_ar",
    "training_type",
    "assigned_user_name_en",
    "assigned_user_name_ar",
    "department_name_en",
    "department_name_ar"
   FROM "public"."v_patch29_training_assignment_queue"
  WHERE (("status" = ANY (ARRAY['assigned'::"text", 'in_progress'::"text"])) AND ("due_date" < CURRENT_DATE));

CREATE OR REPLACE VIEW "public"."v_patch29_sop_acknowledgment_gap" WITH ("security_invoker"='true') AS
 SELECT "tp"."id" AS "program_id",
    "tp"."title" AS "sop_title",
    "tp"."title_ar" AS "sop_title_ar",
    "tp"."linked_sop_id",
    "p"."id" AS "user_id",
    "p"."full_name_en" AS "user_name_en",
    "p"."full_name_ar" AS "user_name_ar",
    "p"."department_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar"
   FROM (("public"."training_programs" "tp"
     CROSS JOIN "public"."profiles" "p")
     LEFT JOIN "public"."departments" "d" ON (("p"."department_id" = "d"."id")))
  WHERE (("tp"."training_type" = 'sop_acknowledgment'::"text") AND ("tp"."active" = true) AND ("p"."is_active" = true) AND (NOT (EXISTS ( SELECT 1
           FROM ("public"."training_assignments" "ta"
             JOIN "public"."training_acknowledgments" "tk" ON (("tk"."assignment_id" = "ta"."id")))
          WHERE (("ta"."program_id" = "tp"."id") AND ("ta"."assigned_to_user_id" = "p"."id") AND ("ta"."status" = 'completed'::"text"))))));

CREATE OR REPLACE VIEW "public"."v_patch29_training_evidence_index" WITH ("security_invoker"='true') AS
 SELECT "ef"."id" AS "evidence_id",
    "ef"."file_name",
    "ef"."file_path",
    "ef"."created_at" AS "uploaded_at",
    "ta"."id" AS "assignment_id",
    "tp"."title" AS "program_title",
    "tp"."training_type",
    "p"."full_name_en" AS "user_name_en",
    "p"."full_name_ar" AS "user_name_ar"
   FROM ((("public"."evidence_files" "ef"
     JOIN "public"."training_assignments" "ta" ON (("ta"."completion_evidence_id" = "ef"."id")))
     JOIN "public"."training_programs" "tp" ON (("ta"."program_id" = "tp"."id")))
     LEFT JOIN "public"."profiles" "p" ON (("ta"."assigned_to_user_id" = "p"."id")));

CREATE OR REPLACE VIEW "public"."v_patch29_training_executive_summary" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."training_programs"
          WHERE ("training_programs"."active" = true)) AS "active_programs_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."training_assignments"
          WHERE ("training_assignments"."status" = ANY (ARRAY['assigned'::"text", 'in_progress'::"text"]))) AS "pending_assignments_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."training_assignments"
          WHERE ("training_assignments"."status" = 'completed'::"text")) AS "completed_assignments_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch29_overdue_training_assignments") AS "overdue_assignments_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch29_sop_acknowledgment_gap") AS "total_sop_gaps_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch29_competency_gap_dashboard"
          WHERE ("v_patch29_competency_gap_dashboard"."result" IS NOT NULL)) AS "competency_fails_count";

CREATE OR REPLACE VIEW "public"."v_patch29_training_program_register" WITH ("security_invoker"='true') AS
 SELECT "tp"."id",
    "tp"."title",
    "tp"."title_ar",
    "tp"."description",
    "tp"."training_type",
    "tp"."linked_document_id",
    "tp"."linked_sop_id",
    "tp"."linked_compliance_obligation_id",
    "tp"."linked_capa_id",
    "tp"."linked_risk_id",
    "tp"."linked_audit_finding_id",
    "tp"."owner_user_id",
    "tp"."department_id",
    "tp"."active",
    "tp"."created_at",
    "tp"."created_by",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "p"."full_name_en" AS "owner_name_en",
    "p"."full_name_ar" AS "owner_name_ar"
   FROM (("public"."training_programs" "tp"
     LEFT JOIN "public"."departments" "d" ON (("tp"."department_id" = "d"."id")))
     LEFT JOIN "public"."profiles" "p" ON (("tp"."owner_user_id" = "p"."id")));

CREATE OR REPLACE VIEW "public"."v_patch30_accreditation_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT 'CBAHI Accreditation Standards'::"text" AS "standard_set",
    ("count"(*))::integer AS "total_standards",
    ("count"(
        CASE
            WHEN (("status")::"text" = 'compliant'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "compliant_count",
    ("count"(
        CASE
            WHEN (("status")::"text" = ANY (ARRAY['non_compliant'::"text", 'expired'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "non_compliant_count",
        CASE
            WHEN ("count"(*) = 0) THEN 0.0
            ELSE "round"(((("count"(
            CASE
                WHEN (("status")::"text" = 'compliant'::"text") THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "compliance_percentage"
   FROM "public"."compliance_items"
  WHERE ("regulatory_body" ~~* '%CBAHI%'::"text");

CREATE OR REPLACE VIEW "public"."v_patch30_board_pack_truth_snapshot" WITH ("security_invoker"='true') AS
 SELECT "id" AS "snapshot_id",
    "title",
    "captured_at",
    "captured_by",
    "notes",
    (("snapshot_data" ->> 'active_risks_count'::"text"))::integer AS "active_risks",
    (("snapshot_data" ->> 'compliant_items_count'::"text"))::integer AS "compliant_items",
    (("snapshot_data" ->> 'non_compliant_items_count'::"text"))::integer AS "non_compliant_items",
    (("snapshot_data" ->> 'open_audit_findings_count'::"text"))::integer AS "open_audit_findings"
   FROM "public"."executive_truth_snapshots";

CREATE OR REPLACE VIEW "public"."v_patch30_department_grc_scorecard" WITH ("security_invoker"='true') AS
 SELECT "id" AS "department_id",
    "name_en" AS "department_name_en",
    "name_ar" AS "department_name_ar",
    (( SELECT "count"(*) AS "count"
           FROM "public"."risks" "r"
          WHERE (("r"."department_id" = "d"."id") AND (("r"."status")::"text" = ANY (ARRAY['open'::"text", 'under_review'::"text", 'mitigating'::"text", 'monitoring'::"text"])))))::integer AS "open_risks",
    (( SELECT "count"(*) AS "count"
           FROM "public"."compliance_items" "ci"
          WHERE (("ci"."department_id" = "d"."id") AND (("ci"."status")::"text" = ANY (ARRAY['non_compliant'::"text", 'expired'::"text"])))))::integer AS "non_compliant_obligations",
    (( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE (("t"."department_id" = "d"."id") AND (("t"."status")::"text" <> 'completed'::"text") AND ("t"."due_date" < CURRENT_DATE))))::integer AS "overdue_tasks"
   FROM "public"."departments" "d";

CREATE OR REPLACE VIEW "public"."v_patch30_evidence_gap_summary" WITH ("security_invoker"='true') AS
 SELECT 'Compliance'::"text" AS "module_name",
    "compliance_items"."id" AS "item_id",
    "compliance_items"."title" AS "item_title",
    "compliance_items"."department_id",
    "compliance_items"."owner_id" AS "owner_user_id"
   FROM "public"."compliance_items"
  WHERE (("compliance_items"."evidence_required" = true) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."evidence_files" "ef"
          WHERE (("ef"."linked_item_type" = 'compliance_obligation'::"text") AND ("ef"."linked_item_id" = "ef"."id"))))))
UNION ALL
 SELECT 'Audit Finding'::"text" AS "module_name",
    "audit_findings"."id" AS "item_id",
    "audit_findings"."title" AS "item_title",
    "audit_findings"."department_id",
    "audit_findings"."owner_id" AS "owner_user_id"
   FROM "public"."audit_findings"
  WHERE (NOT (EXISTS ( SELECT 1
           FROM "public"."evidence_files" "ef"
          WHERE (("ef"."linked_item_type" = 'audit_finding'::"text") AND ("ef"."linked_item_id" = "ef"."id")))));

CREATE OR REPLACE VIEW "public"."v_patch30_executive_truth_summary" WITH ("security_invoker"='true') AS
 SELECT (( SELECT "count"(*) AS "count"
           FROM "public"."risks"
          WHERE (("risks"."status")::"text" = ANY (ARRAY['open'::"text", 'under_review'::"text", 'mitigating'::"text", 'monitoring'::"text"]))))::integer AS "active_risks_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."compliance_items"
          WHERE (("compliance_items"."status")::"text" = 'compliant'::"text")))::integer AS "compliant_items_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."compliance_items"
          WHERE (("compliance_items"."status")::"text" = ANY (ARRAY['non_compliant'::"text", 'expired'::"text"]))))::integer AS "non_compliant_items_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."audit_findings"
          WHERE (("audit_findings"."status")::"text" = ANY (ARRAY['open'::"text", 'action_plan_submitted'::"text", 'in_progress'::"text", 'evidence_submitted'::"text", 'under_audit_review'::"text", 'rejected'::"text"]))))::integer AS "open_audit_findings_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."approvals"
          WHERE (("approvals"."status")::"text" = 'pending'::"text")))::integer AS "pending_approvals_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."evidence_files"))::integer AS "total_evidence_files_count";

CREATE OR REPLACE VIEW "public"."v_patch30_governance_exception_register" WITH ("security_invoker"='true') AS
 SELECT 'Approval Escalation'::"text" AS "exception_type",
    "id" AS "entity_id",
    COALESCE(NULLIF("request_note", ''::"text"), 'Approval escalation'::"text") AS "summary",
    "requested_by" AS "initiator_user_id",
    "requested_at" AS "logged_at"
   FROM "public"."approvals"
  WHERE (("status")::"text" = 'rejected'::"text");

CREATE OR REPLACE VIEW "public"."v_patch30_module_health_scorecard" WITH ("security_invoker"='true') AS
 SELECT 'Risk'::"text" AS "module_name",
    ("count"(*))::integer AS "total_items",
    ("count"(
        CASE
            WHEN (("risks"."status")::"text" = ANY (ARRAY['mitigated'::"text", 'closed'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "closed_items",
    ("count"(
        CASE
            WHEN (("risks"."status")::"text" = ANY (ARRAY['open'::"text", 'under_review'::"text", 'mitigating'::"text", 'monitoring'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "open_items",
    0 AS "overdue_items",
        CASE
            WHEN ("count"(*) = 0) THEN 100.0
            ELSE "round"(((("count"(
            CASE
                WHEN (("risks"."status")::"text" = ANY (ARRAY['mitigated'::"text", 'closed'::"text"])) THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "health_index"
   FROM "public"."risks"
UNION ALL
 SELECT 'Compliance'::"text" AS "module_name",
    ("count"(*))::integer AS "total_items",
    ("count"(
        CASE
            WHEN (("compliance_items"."status")::"text" = 'compliant'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "closed_items",
    ("count"(
        CASE
            WHEN (("compliance_items"."status")::"text" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'pending_evidence'::"text", 'pending_approval'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "open_items",
    ("count"(
        CASE
            WHEN ((("compliance_items"."status")::"text" = ANY (ARRAY['non_compliant'::"text", 'expired'::"text"])) OR (("compliance_items"."due_date" < CURRENT_DATE) AND (("compliance_items"."status")::"text" <> 'compliant'::"text"))) THEN 1
            ELSE NULL::integer
        END))::integer AS "overdue_items",
        CASE
            WHEN ("count"(*) = 0) THEN 100.0
            ELSE "round"(((("count"(
            CASE
                WHEN (("compliance_items"."status")::"text" = 'compliant'::"text") THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "health_index"
   FROM "public"."compliance_items"
UNION ALL
 SELECT 'Audit'::"text" AS "module_name",
    ("count"(*))::integer AS "total_items",
    ("count"(
        CASE
            WHEN (("audit_findings"."status")::"text" = 'closed'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "closed_items",
    ("count"(
        CASE
            WHEN (("audit_findings"."status")::"text" = ANY (ARRAY['open'::"text", 'action_plan_submitted'::"text", 'in_progress'::"text", 'evidence_submitted'::"text", 'under_audit_review'::"text", 'rejected'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "open_items",
    0 AS "overdue_items",
        CASE
            WHEN ("count"(*) = 0) THEN 100.0
            ELSE "round"(((("count"(
            CASE
                WHEN (("audit_findings"."status")::"text" = 'closed'::"text") THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "health_index"
   FROM "public"."audit_findings";

CREATE OR REPLACE VIEW "public"."v_patch30_open_executive_risk_register" WITH ("security_invoker"='true') AS
 SELECT "r"."id" AS "risk_id",
    "r"."title" AS "risk_title",
    "r"."severity_level",
    "r"."risk_level",
    "r"."status",
    "r"."department_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    (( SELECT "count"(*) AS "count"
           FROM "public"."risk_controls" "rc"
          WHERE ("rc"."risk_id" = "r"."id")))::integer AS "linked_controls_count"
   FROM ("public"."risks" "r"
     LEFT JOIN "public"."departments" "d" ON (("r"."department_id" = "d"."id")))
  WHERE ((("r"."status")::"text" = ANY (ARRAY['open'::"text", 'under_review'::"text", 'mitigating'::"text", 'monitoring'::"text"])) AND ("r"."risk_level" = ANY (ARRAY['high'::"public"."risk_level", 'critical'::"public"."risk_level"])));

CREATE OR REPLACE VIEW "public"."v_patch30_overdue_governance_items" WITH ("security_invoker"='true') AS
 SELECT 'Compliance Item'::"text" AS "item_type",
    "compliance_items"."id" AS "item_id",
    "compliance_items"."title" AS "item_title",
    "compliance_items"."due_date",
    "compliance_items"."department_id",
    "compliance_items"."owner_id" AS "owner_user_id",
    (CURRENT_DATE - "compliance_items"."due_date") AS "days_overdue"
   FROM "public"."compliance_items"
  WHERE ((("compliance_items"."status")::"text" <> 'compliant'::"text") AND ("compliance_items"."due_date" < CURRENT_DATE))
UNION ALL
 SELECT 'Task'::"text" AS "item_type",
    "tasks"."id" AS "item_id",
    "tasks"."title" AS "item_title",
    "tasks"."due_date",
    "tasks"."department_id",
    "tasks"."owner_id" AS "owner_user_id",
    (CURRENT_DATE - "tasks"."due_date") AS "days_overdue"
   FROM "public"."tasks"
  WHERE ((("tasks"."status")::"text" <> 'completed'::"text") AND ("tasks"."due_date" < CURRENT_DATE));

CREATE OR REPLACE VIEW "public"."v_patch30_workflow_bottleneck_summary" WITH ("security_invoker"='true') AS
 SELECT 'Approval'::"text" AS "workflow_type",
    "id" AS "item_id",
    COALESCE(NULLIF("request_note", ''::"text"), 'Approval request'::"text") AS "item_title",
    ("status")::"text" AS "status",
    "requested_at" AS "created_at",
    ((EXTRACT(epoch FROM ("now"() - "requested_at")) / (86400)::numeric))::numeric(10,2) AS "pending_days",
    "approver_id" AS "pending_actor_id"
   FROM "public"."approvals"
  WHERE (("status")::"text" = 'pending'::"text");

CREATE OR REPLACE VIEW "public"."v_patch31_frontend_rpc_signoff_summary" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_classified_rpcs",
    "count"(*) FILTER (WHERE "allowed_frontend_use") AS "allowed_frontend_use_count",
    "count"(*) FILTER (WHERE "requires_authenticated_bridge") AS "requires_authenticated_bridge_count",
    "count"(*) FILTER (WHERE "service_role_only") AS "service_role_only_count",
    "count"(*) FILTER (WHERE ("signoff_status" = 'approved_for_production'::"text")) AS "approved_for_production_count",
    "count"(*) FILTER (WHERE ("signoff_status" = ANY (ARRAY['pending_review'::"text", 'pending_security_review'::"text", 'privileged_admin_review'::"text", 'workflow_runtime_review'::"text"]))) AS "pending_review_count",
    "count"(*) FILTER (WHERE ("signoff_status" = 'rejected_for_production'::"text")) AS "rejected_for_production_count",
    "count"(*) FILTER (WHERE ("bridge_validation_status" = 'authenticated_bridge_present'::"text")) AS "authenticated_bridge_present_count"
   FROM "public"."runtime_rpc_classifications";

CREATE OR REPLACE VIEW "public"."v_patch31_runtime_rpc_classification_register" WITH ("security_invoker"='true') AS
 SELECT "rpc_name",
    "frontend_transport",
    "classification",
    "risk_level",
    "allowed_frontend_use",
    "requires_authenticated_bridge",
    "service_role_only",
    "signoff_status",
    "bridge_validation_status",
    "reviewed_by",
    "reviewed_at",
    "source_file",
    "source_line",
    "signoff_notes",
    "production_exception_reason",
    "updated_at"
   FROM "public"."runtime_rpc_classifications";

CREATE OR REPLACE VIEW "public"."v_patch31_privileged_rpc_review_queue" WITH ("security_invoker"='true') AS
 SELECT "rpc_name",
    "frontend_transport",
    "classification",
    "risk_level",
    "allowed_frontend_use",
    "requires_authenticated_bridge",
    "service_role_only",
    "signoff_status",
    "bridge_validation_status",
    "reviewed_by",
    "reviewed_at",
    "source_file",
    "source_line",
    "signoff_notes",
    "production_exception_reason",
    "updated_at"
   FROM "public"."v_patch31_runtime_rpc_classification_register"
  WHERE (("classification" = 'privileged_admin_review'::"text") OR ("signoff_status" = 'privileged_admin_review'::"text") OR ("risk_level" = ANY (ARRAY['high'::"text", 'critical'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch31_runtime_rpc_exception_register" WITH ("security_invoker"='true') AS
 SELECT "rpc_name",
    "frontend_transport",
    "classification",
    "risk_level",
    "allowed_frontend_use",
    "requires_authenticated_bridge",
    "service_role_only",
    "signoff_status",
    "bridge_validation_status",
    "reviewed_by",
    "reviewed_at",
    "source_file",
    "source_line",
    "signoff_notes",
    "production_exception_reason",
    "updated_at"
   FROM "public"."v_patch31_runtime_rpc_classification_register"
  WHERE (("signoff_status" <> 'approved_for_production'::"text") OR ("production_exception_reason" IS NOT NULL) OR ("bridge_validation_status" = ANY (ARRAY['pending_validation'::"text", 'rejected'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch31_runtime_rpc_production_readiness" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_classified_rpcs",
    "count"(*) FILTER (WHERE ("signoff_status" <> 'approved_for_production'::"text")) AS "unresolved_rpc_count",
    "count"(*) FILTER (WHERE ("service_role_only" AND ("frontend_transport" = 'direct_browser_rpc'::"text"))) AS "direct_service_role_frontend_count",
    "count"(*) FILTER (WHERE ("requires_authenticated_bridge" AND ("frontend_transport" <> 'authenticated_edge_bridge'::"text"))) AS "missing_bridge_count",
    "count"(*) FILTER (WHERE (("risk_level" = ANY (ARRAY['high'::"text", 'critical'::"text"])) AND ("signoff_status" <> 'approved_for_production'::"text"))) AS "high_risk_pending_count",
    (("count"(*) FILTER (WHERE ("service_role_only" AND ("frontend_transport" = 'direct_browser_rpc'::"text"))) = 0) AND ("count"(*) FILTER (WHERE ("signoff_status" = 'rejected_for_production'::"text")) = 0)) AS "production_security_signoff_ready"
   FROM "public"."runtime_rpc_classifications";

CREATE OR REPLACE VIEW "public"."v_patch31_unreviewed_runtime_rpcs" WITH ("security_invoker"='true') AS
 SELECT "rpc_name",
    "frontend_transport",
    "classification",
    "risk_level",
    "allowed_frontend_use",
    "requires_authenticated_bridge",
    "service_role_only",
    "signoff_status",
    "bridge_validation_status",
    "reviewed_by",
    "reviewed_at",
    "source_file",
    "source_line",
    "signoff_notes",
    "production_exception_reason",
    "updated_at"
   FROM "public"."v_patch31_runtime_rpc_classification_register"
  WHERE (("signoff_status" = ANY (ARRAY['pending_review'::"text", 'pending_security_review'::"text"])) OR ("reviewed_at" IS NULL));

CREATE OR REPLACE VIEW "public"."v_patch32_accreditation_clause_register" WITH ("security_invoker"='true') AS
 SELECT "c"."id" AS "clause_id",
    "s"."id" AS "standard_id",
    "s"."framework",
    "s"."standard_code",
    "s"."standard_name",
    "s"."standard_name_ar",
    "s"."version",
    "c"."clause_code",
    "c"."clause_title",
    "c"."clause_title_ar",
    "c"."clause_description",
    "c"."clause_category",
    "c"."department_id",
    COALESCE("d"."name_en", "d"."name_ar") AS "department_name",
    "c"."owner_user_id",
    COALESCE("p"."full_name_en", "p"."full_name_ar", "p"."email") AS "owner_name",
    "c"."criticality",
    "c"."active",
    "c"."created_at"
   FROM ((("public"."accreditation_clauses" "c"
     JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "c"."department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "c"."owner_user_id")))
  WHERE (("s"."active" = true) AND ("c"."active" = true));

CREATE OR REPLACE VIEW "public"."v_patch32_clause_traceability_matrix" WITH ("security_invoker"='true') AS
 SELECT "r"."clause_id",
    "r"."standard_id",
    "r"."framework",
    "r"."standard_code",
    "r"."standard_name",
    "r"."standard_name_ar",
    "r"."version",
    "r"."clause_code",
    "r"."clause_title",
    "r"."clause_title_ar",
    "r"."clause_description",
    "r"."clause_category",
    "r"."department_id",
    "r"."department_name",
    "r"."owner_user_id",
    "r"."owner_name",
    "r"."criticality",
    "r"."active",
    "r"."created_at",
    "count"("l"."id") FILTER (WHERE "l"."active") AS "linked_entity_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'control'::"text") AND "l"."active")) AS "control_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = ANY (ARRAY['sop'::"text", 'document'::"text", 'policy'::"text"])) AND "l"."active")) AS "sop_document_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'evidence'::"text") AND "l"."active")) AS "evidence_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'capa'::"text") AND "l"."active")) AS "capa_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'risk'::"text") AND "l"."active")) AS "risk_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'audit_finding'::"text") AND "l"."active")) AS "audit_finding_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = ANY (ARRAY['training_program'::"text", 'training_assignment'::"text"])) AND "l"."active")) AS "training_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'approval_authority'::"text") AND "l"."active")) AS "approval_authority_link_count"
   FROM ("public"."v_patch32_accreditation_clause_register" "r"
     LEFT JOIN "public"."accreditation_clause_links" "l" ON (("l"."clause_id" = "r"."clause_id")))
  GROUP BY "r"."clause_id", "r"."standard_id", "r"."framework", "r"."standard_code", "r"."standard_name", "r"."standard_name_ar", "r"."version", "r"."clause_code", "r"."clause_title", "r"."clause_title_ar", "r"."clause_description", "r"."clause_category", "r"."department_id", "r"."department_name", "r"."owner_user_id", "r"."owner_name", "r"."criticality", "r"."active", "r"."created_at";

CREATE OR REPLACE VIEW "public"."v_patch32_clause_capa_risk_audit_summary" WITH ("security_invoker"='true') AS
 SELECT "clause_id",
    "standard_id",
    "framework",
    "standard_code",
    "standard_name",
    "standard_name_ar",
    "version",
    "clause_code",
    "clause_title",
    "clause_title_ar",
    "clause_description",
    "clause_category",
    "department_id",
    "department_name",
    "owner_user_id",
    "owner_name",
    "criticality",
    "active",
    "created_at",
    "linked_entity_count",
    "control_link_count",
    "sop_document_link_count",
    "evidence_link_count",
    "capa_link_count",
    "risk_link_count",
    "audit_finding_link_count",
    "training_link_count",
    "approval_authority_link_count",
    ((COALESCE("capa_link_count", (0)::bigint) + COALESCE("risk_link_count", (0)::bigint)) + COALESCE("audit_finding_link_count", (0)::bigint)) AS "issue_link_count",
        CASE
            WHEN (((COALESCE("capa_link_count", (0)::bigint) + COALESCE("risk_link_count", (0)::bigint)) + COALESCE("audit_finding_link_count", (0)::bigint)) > 0) THEN 'issue_links_present'::"text"
            ELSE 'no_issue_links'::"text"
        END AS "issue_traceability_status"
   FROM "public"."v_patch32_clause_traceability_matrix" "m";

CREATE OR REPLACE VIEW "public"."v_patch32_clause_evidence_gap_summary" WITH ("security_invoker"='true') AS
 SELECT "m"."clause_id",
    "m"."standard_id",
    "m"."framework",
    "m"."standard_code",
    "m"."standard_name",
    "m"."standard_name_ar",
    "m"."version",
    "m"."clause_code",
    "m"."clause_title",
    "m"."clause_title_ar",
    "m"."clause_description",
    "m"."clause_category",
    "m"."department_id",
    "m"."department_name",
    "m"."owner_user_id",
    "m"."owner_name",
    "m"."criticality",
    "m"."active",
    "m"."created_at",
    "m"."linked_entity_count",
    "m"."control_link_count",
    "m"."sop_document_link_count",
    "m"."evidence_link_count",
    "m"."capa_link_count",
    "m"."risk_link_count",
    "m"."audit_finding_link_count",
    "m"."training_link_count",
    "m"."approval_authority_link_count",
    "a"."assessment_status",
    "a"."evidence_status",
    "a"."readiness_score",
        CASE
            WHEN (COALESCE("m"."evidence_link_count", (0)::bigint) = 0) THEN 'missing_evidence_link'::"text"
            WHEN (COALESCE("a"."evidence_status", 'missing'::"text") = ANY (ARRAY['missing'::"text", 'partial'::"text", 'outdated'::"text", 'under_review'::"text"])) THEN 'evidence_not_ready'::"text"
            ELSE 'evidence_ready'::"text"
        END AS "evidence_gap_status"
   FROM ("public"."v_patch32_clause_traceability_matrix" "m"
     LEFT JOIN LATERAL ( SELECT "a_1"."id",
            "a_1"."clause_id",
            "a_1"."assessment_status",
            "a_1"."readiness_score",
            "a_1"."evidence_status",
            "a_1"."assessment_notes",
            "a_1"."assessed_by",
            "a_1"."assessed_at"
           FROM "public"."accreditation_clause_assessments" "a_1"
          WHERE ("a_1"."clause_id" = "m"."clause_id")
          ORDER BY "a_1"."assessed_at" DESC
         LIMIT 1) "a" ON (true));

CREATE OR REPLACE VIEW "public"."v_patch32_clause_sop_document_gap_summary" WITH ("security_invoker"='true') AS
 SELECT "clause_id",
    "standard_id",
    "framework",
    "standard_code",
    "standard_name",
    "standard_name_ar",
    "version",
    "clause_code",
    "clause_title",
    "clause_title_ar",
    "clause_description",
    "clause_category",
    "department_id",
    "department_name",
    "owner_user_id",
    "owner_name",
    "criticality",
    "active",
    "created_at",
    "linked_entity_count",
    "control_link_count",
    "sop_document_link_count",
    "evidence_link_count",
    "capa_link_count",
    "risk_link_count",
    "audit_finding_link_count",
    "training_link_count",
    "approval_authority_link_count",
        CASE
            WHEN (COALESCE("sop_document_link_count", (0)::bigint) = 0) THEN 'missing_sop_document_link'::"text"
            ELSE 'sop_document_linked'::"text"
        END AS "sop_document_gap_status"
   FROM "public"."v_patch32_clause_traceability_matrix" "m";

CREATE OR REPLACE VIEW "public"."v_patch32_clause_training_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT "clause_id",
    "standard_id",
    "framework",
    "standard_code",
    "standard_name",
    "standard_name_ar",
    "version",
    "clause_code",
    "clause_title",
    "clause_title_ar",
    "clause_description",
    "clause_category",
    "department_id",
    "department_name",
    "owner_user_id",
    "owner_name",
    "criticality",
    "active",
    "created_at",
    "linked_entity_count",
    "control_link_count",
    "sop_document_link_count",
    "evidence_link_count",
    "capa_link_count",
    "risk_link_count",
    "audit_finding_link_count",
    "training_link_count",
    "approval_authority_link_count",
        CASE
            WHEN (COALESCE("training_link_count", (0)::bigint) = 0) THEN 'training_not_linked'::"text"
            ELSE 'training_linked'::"text"
        END AS "training_readiness_status"
   FROM "public"."v_patch32_clause_traceability_matrix" "m";

CREATE OR REPLACE VIEW "public"."v_patch32_accreditation_exception_register" WITH ("security_invoker"='true') AS
 SELECT "e"."clause_id",
    "e"."standard_id",
    "e"."framework",
    "e"."standard_code",
    "e"."standard_name",
    "e"."standard_name_ar",
    "e"."version",
    "e"."clause_code",
    "e"."clause_title",
    "e"."clause_title_ar",
    "e"."clause_description",
    "e"."clause_category",
    "e"."department_id",
    "e"."department_name",
    "e"."owner_user_id",
    "e"."owner_name",
    "e"."criticality",
    "e"."active",
    "e"."created_at",
    "e"."linked_entity_count",
    "e"."control_link_count",
    "e"."sop_document_link_count",
    "e"."evidence_link_count",
    "e"."capa_link_count",
    "e"."risk_link_count",
    "e"."audit_finding_link_count",
    "e"."training_link_count",
    "e"."approval_authority_link_count",
    "e"."assessment_status",
    "e"."evidence_status",
    "e"."readiness_score",
    "e"."evidence_gap_status",
    "s"."sop_document_gap_status",
    "t"."training_readiness_status",
    "i"."issue_traceability_status"
   FROM ((("public"."v_patch32_clause_evidence_gap_summary" "e"
     JOIN "public"."v_patch32_clause_sop_document_gap_summary" "s" USING ("clause_id"))
     JOIN "public"."v_patch32_clause_training_readiness_summary" "t" USING ("clause_id"))
     JOIN "public"."v_patch32_clause_capa_risk_audit_summary" "i" USING ("clause_id"))
  WHERE (("e"."evidence_gap_status" <> 'evidence_ready'::"text") OR ("s"."sop_document_gap_status" <> 'sop_document_linked'::"text") OR ("t"."training_readiness_status" <> 'training_linked'::"text") OR (COALESCE("e"."assessment_status", 'not_assessed'::"text") = ANY (ARRAY['not_assessed'::"text", 'partial_gap'::"text", 'major_gap'::"text", 'pending_evidence'::"text", 'pending_owner_review'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch32_accreditation_executive_summary" WITH ("security_invoker"='true') AS
 SELECT "e"."framework",
    "count"(*) AS "active_clause_count",
    "avg"(COALESCE("e"."readiness_score", (0)::numeric)) AS "average_readiness_score",
    "count"(*) FILTER (WHERE ("e"."assessment_status" = 'ready'::"text")) AS "ready_clause_count",
    "count"(*) FILTER (WHERE ("e"."evidence_gap_status" <> 'evidence_ready'::"text")) AS "evidence_gap_count",
    "count"(*) FILTER (WHERE ("e"."sop_document_link_count" = 0)) AS "sop_document_gap_count",
    "count"(*) FILTER (WHERE ("e"."training_link_count" = 0)) AS "training_gap_count",
    "count"(*) FILTER (WHERE ("i"."issue_link_count" > 0)) AS "issue_traceability_count"
   FROM ("public"."v_patch32_clause_evidence_gap_summary" "e"
     JOIN "public"."v_patch32_clause_capa_risk_audit_summary" "i" USING ("clause_id"))
  GROUP BY "e"."framework";

CREATE OR REPLACE VIEW "public"."v_patch32_accreditation_review_queue" WITH ("security_invoker"='true') AS
 SELECT "clause_id",
    "standard_id",
    "framework",
    "standard_code",
    "standard_name",
    "standard_name_ar",
    "version",
    "clause_code",
    "clause_title",
    "clause_title_ar",
    "clause_description",
    "clause_category",
    "department_id",
    "department_name",
    "owner_user_id",
    "owner_name",
    "criticality",
    "active",
    "created_at",
    "linked_entity_count",
    "control_link_count",
    "sop_document_link_count",
    "evidence_link_count",
    "capa_link_count",
    "risk_link_count",
    "audit_finding_link_count",
    "training_link_count",
    "approval_authority_link_count",
    "assessment_status",
    "evidence_status",
    "readiness_score",
    "evidence_gap_status",
    "sop_document_gap_status",
    "training_readiness_status",
    "issue_traceability_status"
   FROM "public"."v_patch32_accreditation_exception_register"
  WHERE ((COALESCE("assessment_status", 'not_assessed'::"text") = ANY (ARRAY['not_assessed'::"text", 'partial_gap'::"text", 'major_gap'::"text", 'pending_evidence'::"text", 'pending_owner_review'::"text"])) OR ("criticality" = ANY (ARRAY['critical'::"text", 'high'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch32_department_accreditation_readiness" WITH ("security_invoker"='true') AS
 SELECT "department_id",
    "department_name",
    "count"(*) AS "clause_count",
    "avg"(COALESCE("readiness_score", (0)::numeric)) AS "average_readiness_score",
    "count"(*) FILTER (WHERE ("assessment_status" = 'ready'::"text")) AS "ready_clause_count",
    "count"(*) FILTER (WHERE (("assessment_status" = ANY (ARRAY['partial_gap'::"text", 'major_gap'::"text", 'pending_evidence'::"text", 'pending_owner_review'::"text", 'not_assessed'::"text"])) OR ("assessment_status" IS NULL))) AS "open_gap_count",
    "count"(*) FILTER (WHERE ("evidence_gap_status" <> 'evidence_ready'::"text")) AS "evidence_gap_count"
   FROM "public"."v_patch32_clause_evidence_gap_summary"
  GROUP BY "department_id", "department_name";

CREATE OR REPLACE VIEW "public"."v_patch33_accreditation_live_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT "framework",
    "standard_code",
    "count"(DISTINCT "clause_id") AS "clause_count",
    "count"(*) AS "bridge_link_count",
    "count"(*) FILTER (WHERE (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text"))) AS "accepted_current_evidence_count",
    "count"(*) FILTER (WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])))) AS "evidence_gap_count",
    "avg"(
        CASE
            WHEN (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text")) THEN 100
            ELSE 0
        END) AS "live_evidence_readiness_score"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  GROUP BY "framework", "standard_code";

CREATE OR REPLACE VIEW "public"."v_patch33_capa_training_sop_evidence_dependencies" WITH ("security_invoker"='true') AS
 SELECT "bridge_link_id",
    "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "control_id",
    "evidence_id",
    "document_id",
    "sop_id",
    "linked_entity_type",
    "linked_entity_id",
    "bridge_role",
    "evidence_status",
    "freshness_status",
    "valid_from",
    "valid_until",
    "owner_user_id",
    "owner_name",
    "department_id",
    "department_name",
    "active",
    "updated_at"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  WHERE (("linked_entity_type" = ANY (ARRAY['capa'::"text", 'training_program'::"text", 'training_assignment'::"text", 'sop'::"text", 'document'::"text", 'risk'::"text", 'audit_finding'::"text"])) OR ("bridge_role" = ANY (ARRAY['capa_evidence'::"text", 'training_evidence'::"text", 'sop_evidence'::"text", 'risk_evidence'::"text", 'audit_evidence'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch33_evidence_collection_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."bridge_link_id",
    "r"."clause_id",
    "r"."requested_entity_type",
    "r"."requested_entity_id",
    "r"."request_title",
    "r"."request_description",
    "r"."assigned_to_user_id",
    "r"."assigned_to_department_id",
    "r"."due_date",
    "r"."priority",
    "r"."status",
    "r"."submitted_evidence_id",
    "r"."requested_by",
    "r"."requested_at",
    "r"."completed_at",
    "b"."evidence_status",
    "b"."freshness_status",
    "c"."clause_code",
    "c"."clause_title",
    COALESCE("d"."name_en", "d"."name_ar") AS "assigned_department_name",
    COALESCE("p"."full_name_en", "p"."full_name_ar", "p"."email") AS "assigned_user_name",
        CASE
            WHEN (("r"."due_date" IS NOT NULL) AND ("r"."due_date" < CURRENT_DATE) AND ("r"."status" <> ALL (ARRAY['accepted'::"text", 'cancelled'::"text", 'waived'::"text"]))) THEN true
            ELSE false
        END AS "is_overdue"
   FROM (((("public"."evidence_collection_requests" "r"
     LEFT JOIN "public"."evidence_bridge_links" "b" ON (("b"."id" = "r"."bridge_link_id")))
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "r"."clause_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."assigned_to_department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "r"."assigned_to_user_id")))
  WHERE ("r"."status" <> ALL (ARRAY['accepted'::"text", 'cancelled'::"text", 'waived'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch33_evidence_exception_register" WITH ("security_invoker"='true') AS
 SELECT "bridge_link_id",
    "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "control_id",
    "evidence_id",
    "document_id",
    "sop_id",
    "linked_entity_type",
    "linked_entity_id",
    "bridge_role",
    "evidence_status",
    "freshness_status",
    "valid_from",
    "valid_until",
    "owner_user_id",
    "owner_name",
    "department_id",
    "department_name",
    "active",
    "updated_at"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text"])) OR (("valid_until" IS NOT NULL) AND ("valid_until" < CURRENT_DATE)));

CREATE OR REPLACE VIEW "public"."v_patch33_evidence_review_queue" WITH ("security_invoker"='true') AS
 SELECT "rv"."id",
    "rv"."bridge_link_id",
    "rv"."collection_request_id",
    "rv"."evidence_id",
    "rv"."review_status",
    "rv"."review_notes",
    "rv"."reviewed_by",
    "rv"."reviewed_at",
    "rv"."created_at",
    "r"."request_title",
    "r"."clause_id",
    "c"."clause_code",
    "c"."clause_title",
    "b"."evidence_status",
    "b"."freshness_status"
   FROM ((("public"."evidence_bridge_reviews" "rv"
     LEFT JOIN "public"."evidence_collection_requests" "r" ON (("r"."id" = "rv"."collection_request_id")))
     LEFT JOIN "public"."evidence_bridge_links" "b" ON (("b"."id" = COALESCE("rv"."bridge_link_id", "r"."bridge_link_id"))))
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = COALESCE("r"."clause_id", "b"."clause_id"))))
  WHERE ("rv"."review_status" = ANY (ARRAY['pending_review'::"text", 'needs_rework'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch33_executive_evidence_bridge_summary" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_bridge_links",
    "count"(DISTINCT "clause_id") AS "clauses_with_bridge_links",
    "count"(*) FILTER (WHERE (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text"))) AS "ready_links",
    "count"(*) FILTER (WHERE (("evidence_status" = ANY (ARRAY['missing'::"text", 'pending_collection'::"text", 'pending_review'::"text", 'rejected'::"text", 'stale'::"text", 'expired'::"text"])) OR ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text", 'unknown'::"text"])))) AS "gap_links",
    "count"(*) FILTER (WHERE ("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text"]))) AS "stale_or_expired_links",
    "count"(*) FILTER (WHERE ("linked_entity_type" = ANY (ARRAY['capa'::"text", 'risk'::"text", 'audit_finding'::"text", 'training_program'::"text", 'training_assignment'::"text", 'sop'::"text", 'document'::"text"]))) AS "dependency_links",
    "avg"(
        CASE
            WHEN (("evidence_status" = 'accepted'::"text") AND ("freshness_status" = 'current'::"text")) THEN 100
            ELSE 0
        END) AS "overall_evidence_readiness_score"
   FROM "public"."v_patch33_clause_control_evidence_bridge";

CREATE OR REPLACE VIEW "public"."v_patch33_overdue_evidence_requests" WITH ("security_invoker"='true') AS
 SELECT "id",
    "bridge_link_id",
    "clause_id",
    "requested_entity_type",
    "requested_entity_id",
    "request_title",
    "request_description",
    "assigned_to_user_id",
    "assigned_to_department_id",
    "due_date",
    "priority",
    "status",
    "submitted_evidence_id",
    "requested_by",
    "requested_at",
    "completed_at",
    "evidence_status",
    "freshness_status",
    "clause_code",
    "clause_title",
    "assigned_department_name",
    "assigned_user_name",
    "is_overdue"
   FROM "public"."v_patch33_evidence_collection_queue"
  WHERE ("is_overdue" = true);

CREATE OR REPLACE VIEW "public"."v_patch33_stale_expired_evidence_register" WITH ("security_invoker"='true') AS
 SELECT "bridge_link_id",
    "clause_id",
    "clause_code",
    "clause_title",
    "framework",
    "standard_code",
    "control_id",
    "evidence_id",
    "document_id",
    "sop_id",
    "linked_entity_type",
    "linked_entity_id",
    "bridge_role",
    "evidence_status",
    "freshness_status",
    "valid_from",
    "valid_until",
    "owner_user_id",
    "owner_name",
    "department_id",
    "department_name",
    "active",
    "updated_at"
   FROM "public"."v_patch33_clause_control_evidence_bridge"
  WHERE (("freshness_status" = ANY (ARRAY['stale'::"text", 'expired'::"text"])) OR ("evidence_status" = ANY (ARRAY['stale'::"text", 'expired'::"text"])) OR (("valid_until" IS NOT NULL) AND ("valid_until" < CURRENT_DATE)));

CREATE OR REPLACE VIEW "public"."v_patch35_clause_reviewer_signoff_queue" WITH ("security_invoker"='true') AS
 SELECT "id",
    "cycle_id",
    "clause_id",
    "owner_assignment_id",
    "task_type",
    "assigned_to_user_id",
    "assigned_to_department_id",
    "priority",
    "status",
    "due_date",
    "submitted_at",
    "reviewed_at",
    "reviewed_by",
    "outcome_notes",
    "created_by",
    "created_at",
    "updated_at",
    "framework",
    "standard_code",
    "clause_code",
    "clause_title",
    "criticality",
    "assigned_to_name",
    "assigned_department_name",
    "cycle_name",
    "is_overdue"
   FROM "public"."v_patch35_clause_owner_task_queue"
  WHERE (("task_type" = 'reviewer_signoff'::"text") AND ("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'submitted'::"text", 'under_review'::"text", 'reopened'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch35_overdue_clause_tasks" WITH ("security_invoker"='true') AS
 SELECT "id",
    "cycle_id",
    "clause_id",
    "owner_assignment_id",
    "task_type",
    "assigned_to_user_id",
    "assigned_to_department_id",
    "priority",
    "status",
    "due_date",
    "submitted_at",
    "reviewed_at",
    "reviewed_by",
    "outcome_notes",
    "created_by",
    "created_at",
    "updated_at",
    "framework",
    "standard_code",
    "clause_code",
    "clause_title",
    "criticality",
    "assigned_to_name",
    "assigned_department_name",
    "cycle_name",
    "is_overdue"
   FROM "public"."v_patch35_clause_owner_task_queue"
  WHERE ("is_overdue" = true);

CREATE OR REPLACE VIEW "public"."v_patch35_accreditation_operations_dashboard" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."accreditation_clause_owner_assignments"
          WHERE (("accreditation_clause_owner_assignments"."active" = true) AND ("accreditation_clause_owner_assignments"."assignment_status" = 'active'::"text"))) AS "active_owner_assignment_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."accreditation_review_cycles"
          WHERE ("accreditation_review_cycles"."status" = 'active'::"text")) AS "active_review_cycle_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."accreditation_clause_review_tasks"
          WHERE ("accreditation_clause_review_tasks"."status" <> ALL (ARRAY['approved'::"text", 'waived'::"text", 'cancelled'::"text"]))) AS "open_task_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch35_overdue_clause_tasks") AS "overdue_task_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch35_clause_reviewer_signoff_queue") AS "reviewer_signoff_queue_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch35_clause_blocker_summary"
          WHERE (("v_patch35_clause_blocker_summary"."workflow_blocker_count" > 0) OR ("v_patch35_clause_blocker_summary"."evidence_blocker_count" > 0) OR ("v_patch35_clause_blocker_summary"."open_escalation_count" > 0))) AS "blocked_clause_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."accreditation_clause_signoffs"
          WHERE ("accreditation_clause_signoffs"."signoff_status" = 'signed_off'::"text")) AS "signed_off_clause_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."accreditation_workflow_escalations"
          WHERE ("accreditation_workflow_escalations"."escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text"]))) AS "open_escalation_count";

CREATE OR REPLACE VIEW "public"."v_patch35_active_review_cycles" WITH ("security_invoker"='true') AS
 SELECT "id",
    "cycle_name",
    "cycle_type",
    "starts_on",
    "ends_on",
    "status",
    "created_by",
    "created_at",
    "completed_at",
    "notes"
   FROM "public"."accreditation_review_cycles"
  WHERE ("status" = ANY (ARRAY['draft'::"text", 'active'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch35_clause_owner_register" WITH ("security_invoker"='true') AS
 SELECT "a"."id" AS "owner_assignment_id",
    "a"."clause_id",
    "s"."framework",
    "s"."standard_code",
    "c"."clause_code",
    "c"."clause_title",
    "c"."criticality",
    "a"."owner_user_id",
    COALESCE("owner"."full_name_en", "owner"."full_name_ar", "owner"."email") AS "owner_name",
    "a"."owner_department_id",
    COALESCE("owner_dept"."name_en", "owner_dept"."name_ar") AS "owner_department_name",
    "a"."reviewer_user_id",
    COALESCE("reviewer"."full_name_en", "reviewer"."full_name_ar", "reviewer"."email") AS "reviewer_name",
    "a"."reviewer_department_id",
    COALESCE("reviewer_dept"."name_en", "reviewer_dept"."name_ar") AS "reviewer_department_name",
    "a"."assignment_status",
    "a"."due_date",
    "a"."active",
    "a"."assigned_at",
    "a"."notes"
   FROM (((((("public"."accreditation_clause_owner_assignments" "a"
     JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "a"."clause_id")))
     LEFT JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "a"."owner_user_id")))
     LEFT JOIN "public"."departments" "owner_dept" ON (("owner_dept"."id" = "a"."owner_department_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "a"."reviewer_user_id")))
     LEFT JOIN "public"."departments" "reviewer_dept" ON (("reviewer_dept"."id" = "a"."reviewer_department_id")))
  WHERE ("a"."active" = true);

CREATE OR REPLACE VIEW "public"."v_patch35_clause_signoff_register" WITH ("security_invoker"='true') AS
 SELECT "so"."id",
    "so"."cycle_id",
    "so"."clause_id",
    "so"."task_id",
    "so"."signoff_type",
    "so"."signoff_status",
    "so"."signed_by",
    "so"."signed_at",
    "so"."signoff_notes",
    "so"."created_at",
    "s"."framework",
    "s"."standard_code",
    "c"."clause_code",
    "c"."clause_title",
    COALESCE("signer"."full_name_en", "signer"."full_name_ar", "signer"."email") AS "signed_by_name",
    "rc"."cycle_name"
   FROM (((("public"."accreditation_clause_signoffs" "so"
     JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "so"."clause_id")))
     LEFT JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."profiles" "signer" ON (("signer"."id" = "so"."signed_by")))
     LEFT JOIN "public"."accreditation_review_cycles" "rc" ON (("rc"."id" = "so"."cycle_id")));

CREATE OR REPLACE VIEW "public"."v_patch35_escalation_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."clause_id",
    "e"."task_id",
    "e"."cycle_id",
    "e"."escalation_level",
    "e"."escalation_reason",
    "e"."escalation_status",
    "e"."escalated_to_user_id",
    "e"."escalated_to_department_id",
    "e"."escalated_by",
    "e"."escalated_at",
    "e"."resolved_at",
    "e"."resolution_notes",
    "s"."framework",
    "s"."standard_code",
    "c"."clause_code",
    "c"."clause_title",
    COALESCE("u"."full_name_en", "u"."full_name_ar", "u"."email") AS "escalated_to_name",
    COALESCE("d"."name_en", "d"."name_ar") AS "escalated_to_department_name"
   FROM (((("public"."accreditation_workflow_escalations" "e"
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "e"."clause_id")))
     LEFT JOIN "public"."accreditation_standards" "s" ON (("s"."id" = "c"."standard_id")))
     LEFT JOIN "public"."profiles" "u" ON (("u"."id" = "e"."escalated_to_user_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "e"."escalated_to_department_id")));

CREATE OR REPLACE VIEW "public"."v_patch35_executive_accreditation_workflow_summary" WITH ("security_invoker"='true') AS
 SELECT "active_owner_assignment_count",
    "active_review_cycle_count",
    "open_task_count",
    "overdue_task_count",
    "reviewer_signoff_queue_count",
    "blocked_clause_count",
    "signed_off_clause_count",
    "open_escalation_count",
        CASE
            WHEN (("overdue_task_count" > 0) OR ("open_escalation_count" > 0)) THEN 'attention_required'::"text"
            WHEN ("blocked_clause_count" > 0) THEN 'watch'::"text"
            ELSE 'on_track'::"text"
        END AS "executive_signal"
   FROM "public"."v_patch35_accreditation_operations_dashboard" "d";

CREATE OR REPLACE VIEW "public"."v_patch35_ready_for_survey_review_queue" WITH ("security_invoker"='true') AS
 SELECT "b"."clause_id",
    "b"."framework",
    "b"."standard_code",
    "b"."clause_code",
    "b"."clause_title",
    "b"."workflow_blocker_count",
    "b"."evidence_blocker_count",
    "b"."dependency_link_count",
    "b"."open_escalation_count",
    COALESCE("sr"."signed_off_count", (0)::bigint) AS "signed_off_count"
   FROM ("public"."v_patch35_clause_blocker_summary" "b"
     LEFT JOIN ( SELECT "accreditation_clause_signoffs"."clause_id",
            "count"(*) AS "signed_off_count"
           FROM "public"."accreditation_clause_signoffs"
          WHERE ("accreditation_clause_signoffs"."signoff_status" = 'signed_off'::"text")
          GROUP BY "accreditation_clause_signoffs"."clause_id") "sr" ON (("sr"."clause_id" = "b"."clause_id")))
  WHERE (("b"."workflow_blocker_count" = 0) AND ("b"."evidence_blocker_count" = 0) AND ("b"."open_escalation_count" = 0));

CREATE OR REPLACE VIEW "public"."v_patch37_audit_engagement_register" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"text" AS "engagement_title",
    NULL::"text" AS "engagement_type",
    NULL::"text" AS "scope_summary",
    NULL::"uuid" AS "department_id",
    NULL::"uuid" AS "lead_auditor_user_id",
    NULL::"text" AS "status",
    NULL::"date" AS "starts_on",
    NULL::"date" AS "ends_on",
    NULL::"uuid" AS "created_by",
    NULL::timestamp with time zone AS "created_at",
    NULL::timestamp with time zone AS "closed_at",
    NULL::"text" AS "department_name",
    NULL::"text" AS "lead_auditor_name",
    NULL::bigint AS "program_count",
    NULL::bigint AS "test_step_count",
    NULL::bigint AS "completed_step_count",
    NULL::bigint AS "open_finding_count",
    NULL::bigint AS "pending_signoff_count";

CREATE OR REPLACE VIEW "public"."v_patch37_audit_finding_register" WITH ("security_invoker"='true') AS
 SELECT "f"."id",
    "f"."engagement_id",
    "f"."test_step_id",
    "f"."finding_title",
    "f"."finding_description",
    "f"."severity",
    "f"."finding_status",
    "f"."linked_capa_id",
    "f"."linked_evidence_bridge_link_id",
    "f"."linked_clause_id",
    "f"."owner_user_id",
    "f"."department_id",
    "f"."due_date",
    "f"."created_by",
    "f"."created_at",
    "f"."closed_at",
    "e"."engagement_title",
    "ts"."step_code",
    "ts"."step_title",
    COALESCE("d"."name_en", "d"."name_ar") AS "department_name",
    COALESCE("owner"."full_name_en", "owner"."full_name_ar", "owner"."email") AS "owner_name",
    "c"."clause_code",
    "c"."clause_title",
        CASE
            WHEN (("f"."due_date" IS NOT NULL) AND ("f"."due_date" < CURRENT_DATE) AND ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"]))) THEN true
            ELSE false
        END AS "is_overdue"
   FROM ((((("public"."audit_execution_findings" "f"
     JOIN "public"."audit_execution_engagements" "e" ON (("e"."id" = "f"."engagement_id")))
     LEFT JOIN "public"."audit_execution_test_steps" "ts" ON (("ts"."id" = "f"."test_step_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "f"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "f"."owner_user_id")))
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "f"."linked_clause_id")));

CREATE OR REPLACE VIEW "public"."v_patch37_audit_findings_requiring_capa_or_evidence" WITH ("security_invoker"='true') AS
 SELECT "id",
    "engagement_id",
    "test_step_id",
    "finding_title",
    "finding_description",
    "severity",
    "finding_status",
    "linked_capa_id",
    "linked_evidence_bridge_link_id",
    "linked_clause_id",
    "owner_user_id",
    "department_id",
    "due_date",
    "created_by",
    "created_at",
    "closed_at",
    "engagement_title",
    "step_code",
    "step_title",
    "department_name",
    "owner_name",
    "clause_code",
    "clause_title",
    "is_overdue"
   FROM "public"."v_patch37_audit_finding_register"
  WHERE (("finding_status" = ANY (ARRAY['capa_required'::"text", 'evidence_required'::"text"])) OR ("linked_capa_id" IS NULL) OR ("linked_evidence_bridge_link_id" IS NULL));

CREATE OR REPLACE VIEW "public"."v_patch37_audit_sample_result_register" WITH ("security_invoker"='true') AS
 SELECT "sm"."id" AS "sample_id",
    "sm"."test_step_id",
    "sm"."sample_reference",
    "sm"."sample_description",
    "sm"."sample_date",
    "sm"."sample_status",
    "rs"."id" AS "result_id",
    "rs"."result_status",
    "rs"."result_summary",
    "rs"."evidence_id",
    "rs"."tested_by",
    COALESCE("tester"."full_name_en", "tester"."full_name_ar", "tester"."email") AS "tested_by_name",
    "rs"."tested_at",
    "ts"."step_code",
    "ts"."step_title",
    "pr"."program_title",
    "e"."id" AS "engagement_id",
    "e"."engagement_title"
   FROM ((((("public"."audit_execution_samples" "sm"
     JOIN "public"."audit_execution_test_steps" "ts" ON (("ts"."id" = "sm"."test_step_id")))
     JOIN "public"."audit_execution_programs" "pr" ON (("pr"."id" = "ts"."program_id")))
     JOIN "public"."audit_execution_engagements" "e" ON (("e"."id" = "pr"."engagement_id")))
     LEFT JOIN "public"."audit_execution_results" "rs" ON (("rs"."sample_id" = "sm"."id")))
     LEFT JOIN "public"."profiles" "tester" ON (("tester"."id" = "rs"."tested_by")));

CREATE OR REPLACE VIEW "public"."v_patch37_audit_signoff_queue" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."engagement_id",
    "s"."signoff_type",
    "s"."signoff_status",
    "s"."signed_by",
    "s"."signed_at",
    "s"."signoff_notes",
    "s"."created_at",
    "e"."engagement_title",
    "e"."status" AS "engagement_status",
    COALESCE("signer"."full_name_en", "signer"."full_name_ar", "signer"."email") AS "signed_by_name"
   FROM (("public"."audit_execution_signoffs" "s"
     JOIN "public"."audit_execution_engagements" "e" ON (("e"."id" = "s"."engagement_id")))
     LEFT JOIN "public"."profiles" "signer" ON (("signer"."id" = "s"."signed_by")))
  WHERE ("s"."signoff_status" = ANY (ARRAY['pending'::"text", 'rejected'::"text", 'reopened'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch37_audit_test_step_queue" WITH ("security_invoker"='true') AS
 SELECT "ts"."id",
    "ts"."program_id",
    "ts"."step_code",
    "ts"."step_title",
    "ts"."step_description",
    "ts"."test_type",
    "ts"."expected_evidence",
    "ts"."status",
    "ts"."assigned_to_user_id",
    "ts"."due_date",
    "ts"."created_at",
    "pr"."engagement_id",
    "pr"."program_title",
    "pr"."program_area",
    "pr"."linked_clause_id",
    "c"."clause_code",
    "c"."clause_title",
    "e"."engagement_title",
    "e"."status" AS "engagement_status",
    COALESCE("assignee"."full_name_en", "assignee"."full_name_ar", "assignee"."email") AS "assigned_to_name",
        CASE
            WHEN (("ts"."due_date" IS NOT NULL) AND ("ts"."due_date" < CURRENT_DATE) AND ("ts"."status" <> ALL (ARRAY['completed'::"text", 'not_applicable'::"text", 'waived'::"text"]))) THEN true
            ELSE false
        END AS "is_overdue"
   FROM (((("public"."audit_execution_test_steps" "ts"
     JOIN "public"."audit_execution_programs" "pr" ON (("pr"."id" = "ts"."program_id")))
     JOIN "public"."audit_execution_engagements" "e" ON (("e"."id" = "pr"."engagement_id")))
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "pr"."linked_clause_id")))
     LEFT JOIN "public"."profiles" "assignee" ON (("assignee"."id" = "ts"."assigned_to_user_id")))
  WHERE (("e"."status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])) AND ("ts"."status" <> ALL (ARRAY['completed'::"text", 'not_applicable'::"text", 'waived'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch37_clinical_governance_escalation_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."ovr_id",
    "e"."rca_case_id",
    "e"."audit_finding_id",
    "e"."escalation_level",
    "e"."escalation_reason",
    "e"."escalation_status",
    "e"."escalated_to_user_id",
    "e"."escalated_to_department_id",
    "e"."escalated_by",
    "e"."escalated_at",
    "e"."acknowledged_at",
    "e"."resolved_at",
    "e"."resolution_notes",
    "r"."incident_reference",
    "r"."rca_title",
    "r"."severity" AS "rca_severity",
    "f"."finding_title",
    "f"."severity" AS "finding_severity",
    COALESCE("u"."full_name_en", "u"."full_name_ar", "u"."email") AS "escalated_to_name",
    COALESCE("d"."name_en", "d"."name_ar") AS "escalated_to_department_name"
   FROM (((("public"."clinical_governance_escalations" "e"
     LEFT JOIN "public"."ovr_rca_cases" "r" ON (("r"."id" = "e"."rca_case_id")))
     LEFT JOIN "public"."audit_execution_findings" "f" ON (("f"."id" = "e"."audit_finding_id")))
     LEFT JOIN "public"."profiles" "u" ON (("u"."id" = "e"."escalated_to_user_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "e"."escalated_to_department_id")));

CREATE OR REPLACE VIEW "public"."v_patch37_department_clinical_governance_workload" WITH ("security_invoker"='true') AS
 SELECT "d"."id" AS "department_id",
    COALESCE("d"."name_en", "d"."name_ar") AS "department_name",
    "count"(DISTINCT "e"."id") FILTER (WHERE ("e"."status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) AS "active_audit_engagement_count",
    "count"(DISTINCT "f"."id") FILTER (WHERE ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"]))) AS "open_audit_finding_count",
    "count"(DISTINCT "r"."id") FILTER (WHERE ("r"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"]))) AS "open_rca_case_count",
    "count"(DISTINCT "g"."id") FILTER (WHERE ("g"."escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'action_required'::"text"]))) AS "open_escalation_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."due_date" < CURRENT_DATE) AND ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"])))) + "count"(DISTINCT "r"."id") FILTER (WHERE (("r"."due_date" < CURRENT_DATE) AND ("r"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"]))))) AS "overdue_item_count"
   FROM (((("public"."departments" "d"
     LEFT JOIN "public"."audit_execution_engagements" "e" ON (("e"."department_id" = "d"."id")))
     LEFT JOIN "public"."audit_execution_findings" "f" ON (("f"."department_id" = "d"."id")))
     LEFT JOIN "public"."ovr_rca_cases" "r" ON (("r"."department_id" = "d"."id")))
     LEFT JOIN "public"."clinical_governance_escalations" "g" ON (("g"."escalated_to_department_id" = "d"."id")))
  GROUP BY "d"."id", COALESCE("d"."name_en", "d"."name_ar");

CREATE OR REPLACE VIEW "public"."v_patch37_overdue_audit_ovr_governance_items" WITH ("security_invoker"='true') AS
 SELECT 'audit_test_step'::"text" AS "item_type",
    "audit_execution_test_steps"."id" AS "item_id",
    "audit_execution_test_steps"."step_title" AS "item_title",
    "audit_execution_test_steps"."status" AS "item_status",
    "audit_execution_test_steps"."due_date",
    "audit_execution_test_steps"."assigned_to_user_id" AS "owner_user_id",
    NULL::"uuid" AS "department_id"
   FROM "public"."audit_execution_test_steps"
  WHERE (("audit_execution_test_steps"."due_date" < CURRENT_DATE) AND ("audit_execution_test_steps"."status" <> ALL (ARRAY['completed'::"text", 'not_applicable'::"text", 'waived'::"text"])))
UNION ALL
 SELECT 'audit_finding'::"text" AS "item_type",
    "audit_execution_findings"."id" AS "item_id",
    "audit_execution_findings"."finding_title" AS "item_title",
    "audit_execution_findings"."finding_status" AS "item_status",
    "audit_execution_findings"."due_date",
    "audit_execution_findings"."owner_user_id",
    "audit_execution_findings"."department_id"
   FROM "public"."audit_execution_findings"
  WHERE (("audit_execution_findings"."due_date" < CURRENT_DATE) AND ("audit_execution_findings"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"])))
UNION ALL
 SELECT 'ovr_rca'::"text" AS "item_type",
    "ovr_rca_cases"."id" AS "item_id",
    "ovr_rca_cases"."rca_title" AS "item_title",
    "ovr_rca_cases"."rca_status" AS "item_status",
    "ovr_rca_cases"."due_date",
    "ovr_rca_cases"."owner_user_id",
    "ovr_rca_cases"."department_id"
   FROM "public"."ovr_rca_cases"
  WHERE (("ovr_rca_cases"."due_date" < CURRENT_DATE) AND ("ovr_rca_cases"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch37_executive_clinical_governance_summary" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."audit_execution_engagements"
          WHERE ("audit_execution_engagements"."status" = ANY (ARRAY['active'::"text", 'fieldwork'::"text", 'reporting'::"text"]))) AS "active_audit_engagement_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_execution_test_steps"
          WHERE ("audit_execution_test_steps"."status" = ANY (ARRAY['not_started'::"text", 'in_progress'::"text", 'failed'::"text"]))) AS "open_audit_test_step_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_execution_findings"
          WHERE ("audit_execution_findings"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"]))) AS "open_audit_finding_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."audit_execution_findings"
          WHERE ("audit_execution_findings"."finding_status" = ANY (ARRAY['capa_required'::"text", 'evidence_required'::"text"]))) AS "audit_finding_action_required_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."ovr_rca_cases"
          WHERE ("ovr_rca_cases"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"]))) AS "open_rca_case_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."ovr_rca_cases"
          WHERE (("ovr_rca_cases"."severity" = ANY (ARRAY['critical'::"text", 'sentinel'::"text"])) AND ("ovr_rca_cases"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"])))) AS "severe_rca_case_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."clinical_governance_escalations"
          WHERE ("clinical_governance_escalations"."escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'action_required'::"text"]))) AS "open_escalation_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch37_overdue_audit_ovr_governance_items") AS "overdue_governance_item_count",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."ovr_rca_cases"
              WHERE (("ovr_rca_cases"."severity" = 'sentinel'::"text") AND ("ovr_rca_cases"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"])))) > 0) THEN 'sentinel_attention'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch37_overdue_audit_ovr_governance_items") > 0) THEN 'attention_required'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."clinical_governance_escalations"
              WHERE ("clinical_governance_escalations"."escalation_status" = ANY (ARRAY['open'::"text", 'action_required'::"text"]))) > 0) THEN 'watch'::"text"
            ELSE 'on_track'::"text"
        END AS "executive_signal";

CREATE OR REPLACE VIEW "public"."v_patch37_ovr_capa_evidence_bridge" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."ovr_id",
    "l"."rca_case_id",
    "l"."linked_entity_type",
    "l"."linked_entity_id",
    "l"."link_role",
    "l"."link_status",
    "l"."created_by",
    "l"."created_at",
    "r"."incident_reference",
    "r"."rca_title",
    "r"."rca_status",
    "r"."severity",
    "eb"."evidence_status",
    "eb"."freshness_status",
    "eb"."clause_code",
    "eb"."clause_title"
   FROM (("public"."ovr_capa_evidence_links" "l"
     LEFT JOIN "public"."ovr_rca_cases" "r" ON (("r"."id" = "l"."rca_case_id")))
     LEFT JOIN "public"."v_patch33_clause_control_evidence_bridge" "eb" ON ((("l"."linked_entity_type" = 'evidence_bridge'::"text") AND ("eb"."bridge_link_id" = "l"."linked_entity_id"))));

CREATE OR REPLACE VIEW "public"."v_patch37_ovr_rca_case_register" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"uuid" AS "ovr_id",
    NULL::"text" AS "incident_reference",
    NULL::"text" AS "rca_title",
    NULL::"text" AS "rca_status",
    NULL::"text" AS "severity",
    NULL::"uuid" AS "department_id",
    NULL::"uuid" AS "owner_user_id",
    NULL::"date" AS "due_date",
    NULL::"text" AS "root_cause_summary",
    NULL::"uuid" AS "created_by",
    NULL::timestamp with time zone AS "created_at",
    NULL::timestamp with time zone AS "closed_at",
    NULL::"text" AS "department_name",
    NULL::"text" AS "owner_name",
    NULL::bigint AS "active_link_count",
    NULL::bigint AS "capa_link_count",
    NULL::bigint AS "evidence_bridge_link_count",
    NULL::bigint AS "accreditation_clause_link_count",
    NULL::boolean AS "is_overdue";

CREATE OR REPLACE VIEW "public"."v_patch38_clinical_area_register" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."area_code",
    "a"."area_name",
    "a"."area_name_ar",
    "a"."area_type",
    "a"."department_id",
    "a"."location_id",
    "a"."active",
    "a"."owner_user_id",
    "a"."created_at",
    "a"."created_by",
    "d"."name_en" AS "department_name_en",
    "l"."location_name",
    "p"."full_name_en" AS "owner_name_en"
   FROM ((("public"."hospital_master_clinical_areas" "a"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "a"."department_id")))
     LEFT JOIN "public"."hospital_master_locations" "l" ON (("l"."id" = "a"."location_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "a"."owner_user_id")));

CREATE OR REPLACE VIEW "public"."v_patch38_committee_register" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."committee_code",
    "c"."committee_name",
    "c"."committee_name_ar",
    "c"."committee_type",
    "c"."chair_user_id",
    "c"."department_id",
    "c"."active",
    "c"."created_at",
    "c"."created_by",
    "d"."name_en" AS "department_name_en",
    "chair"."full_name_en" AS "chair_name_en"
   FROM (("public"."hospital_master_committees" "c"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "c"."department_id")))
     LEFT JOIN "public"."profiles" "chair" ON (("chair"."id" = "c"."chair_user_id")));

CREATE OR REPLACE VIEW "public"."v_patch38_unified_work_queue" WITH ("security_invoker"='true') AS
 SELECT 'accreditation'::"text" AS "source_module",
    'accreditation_clause_task'::"text" AS "work_type",
    "t"."id" AS "work_id",
    "t"."task_type" AS "work_title",
    "t"."clause_title" AS "work_description",
    "t"."status" AS "work_status",
    "t"."priority",
    "t"."assigned_to_user_id",
    "t"."assigned_to_department_id" AS "department_id",
    "t"."assigned_department_name" AS "department_name",
    "t"."due_date",
    "t"."created_at",
    "t"."is_overdue",
    ("t"."status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text"])) AS "waiting_for_review",
    ("t"."status" = 'escalated'::"text") AS "is_escalated",
    "t"."clause_id" AS "linked_entity_id",
    'accreditation_clause'::"text" AS "linked_entity_type"
   FROM "public"."v_patch35_clause_owner_task_queue" "t"
UNION ALL
 SELECT 'evidence_bridge'::"text" AS "source_module",
    'evidence_collection_request'::"text" AS "work_type",
    "e"."id" AS "work_id",
    "e"."request_title" AS "work_title",
    "e"."request_description" AS "work_description",
    "e"."status" AS "work_status",
    "e"."priority",
    "e"."assigned_to_user_id",
    "e"."assigned_to_department_id" AS "department_id",
    "e"."assigned_department_name" AS "department_name",
    "e"."due_date",
    "e"."requested_at" AS "created_at",
    "e"."is_overdue",
    ("e"."status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text"])) AS "waiting_for_review",
    false AS "is_escalated",
    "e"."bridge_link_id" AS "linked_entity_id",
    'evidence_bridge'::"text" AS "linked_entity_type"
   FROM "public"."v_patch33_evidence_collection_queue" "e"
UNION ALL
 SELECT 'training'::"text" AS "source_module",
    'training_assignment'::"text" AS "work_type",
    "tr"."id" AS "work_id",
    "tr"."program_title" AS "work_title",
    "tr"."training_type" AS "work_description",
    "tr"."status" AS "work_status",
    NULL::"text" AS "priority",
    "tr"."assigned_to_user_id",
    "tr"."assigned_to_department_id" AS "department_id",
    "tr"."department_name_en" AS "department_name",
    "tr"."due_date",
    "tr"."assigned_at" AS "created_at",
    (("tr"."due_date" < CURRENT_DATE) AND ("tr"."status" = ANY (ARRAY['assigned'::"text", 'in_progress'::"text"]))) AS "is_overdue",
    ("tr"."status" = 'pending_review'::"text") AS "waiting_for_review",
    false AS "is_escalated",
    "tr"."program_id" AS "linked_entity_id",
    'training_program'::"text" AS "linked_entity_type"
   FROM "public"."v_patch29_training_assignment_queue" "tr"
  WHERE ("tr"."status" <> ALL (ARRAY['completed'::"text", 'waived'::"text", 'cancelled'::"text"]))
UNION ALL
 SELECT 'audit'::"text" AS "source_module",
    'audit_test_step'::"text" AS "work_type",
    "a"."id" AS "work_id",
    "a"."step_title" AS "work_title",
    "a"."expected_evidence" AS "work_description",
    "a"."status" AS "work_status",
    NULL::"text" AS "priority",
    "a"."assigned_to_user_id",
    NULL::"uuid" AS "department_id",
    NULL::"text" AS "department_name",
    "a"."due_date",
    "a"."created_at",
    "a"."is_overdue",
    false AS "waiting_for_review",
    false AS "is_escalated",
    "a"."engagement_id" AS "linked_entity_id",
    'audit_engagement'::"text" AS "linked_entity_type"
   FROM "public"."v_patch37_audit_test_step_queue" "a"
UNION ALL
 SELECT 'audit'::"text" AS "source_module",
    'audit_finding'::"text" AS "work_type",
    "f"."id" AS "work_id",
    "f"."finding_title" AS "work_title",
    "f"."finding_description" AS "work_description",
    "f"."finding_status" AS "work_status",
    "f"."severity" AS "priority",
    "f"."owner_user_id" AS "assigned_to_user_id",
    "f"."department_id",
    "f"."department_name",
    "f"."due_date",
    "f"."created_at",
    "f"."is_overdue",
    ("f"."finding_status" = 'under_review'::"text") AS "waiting_for_review",
    false AS "is_escalated",
    "f"."engagement_id" AS "linked_entity_id",
    'audit_engagement'::"text" AS "linked_entity_type"
   FROM "public"."v_patch37_audit_finding_register" "f"
  WHERE ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"]))
UNION ALL
 SELECT 'audit'::"text" AS "source_module",
    'audit_signoff'::"text" AS "work_type",
    "s"."id" AS "work_id",
    "s"."signoff_type" AS "work_title",
    "s"."engagement_title" AS "work_description",
    "s"."signoff_status" AS "work_status",
    NULL::"text" AS "priority",
    "s"."signed_by" AS "assigned_to_user_id",
    NULL::"uuid" AS "department_id",
    NULL::"text" AS "department_name",
    NULL::"date" AS "due_date",
    "s"."created_at",
    false AS "is_overdue",
    true AS "waiting_for_review",
    false AS "is_escalated",
    "s"."engagement_id" AS "linked_entity_id",
    'audit_engagement'::"text" AS "linked_entity_type"
   FROM "public"."v_patch37_audit_signoff_queue" "s"
UNION ALL
 SELECT 'ovr'::"text" AS "source_module",
    'ovr_rca_case'::"text" AS "work_type",
    "r"."id" AS "work_id",
    "r"."rca_title" AS "work_title",
    "r"."root_cause_summary" AS "work_description",
    "r"."rca_status" AS "work_status",
    "r"."severity" AS "priority",
    "r"."owner_user_id" AS "assigned_to_user_id",
    "r"."department_id",
    "r"."department_name",
    "r"."due_date",
    "r"."created_at",
    "r"."is_overdue",
    ("r"."rca_status" = 'awaiting_review'::"text") AS "waiting_for_review",
    false AS "is_escalated",
    "r"."ovr_id" AS "linked_entity_id",
    'ovr'::"text" AS "linked_entity_type"
   FROM "public"."v_patch37_ovr_rca_case_register" "r"
  WHERE ("r"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"]))
UNION ALL
 SELECT 'clinical_governance'::"text" AS "source_module",
    'clinical_governance_escalation'::"text" AS "work_type",
    "g"."id" AS "work_id",
    "g"."escalation_reason" AS "work_title",
    COALESCE("g"."rca_title", "g"."finding_title") AS "work_description",
    "g"."escalation_status" AS "work_status",
    "g"."escalation_level" AS "priority",
    "g"."escalated_to_user_id" AS "assigned_to_user_id",
    "g"."escalated_to_department_id" AS "department_id",
    "g"."escalated_to_department_name" AS "department_name",
    NULL::"date" AS "due_date",
    "g"."escalated_at" AS "created_at",
    false AS "is_overdue",
    false AS "waiting_for_review",
    ("g"."escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'action_required'::"text"])) AS "is_escalated",
    COALESCE("g"."rca_case_id", "g"."audit_finding_id") AS "linked_entity_id",
        CASE
            WHEN ("g"."rca_case_id" IS NOT NULL) THEN 'rca_case'::"text"
            ELSE 'audit_finding'::"text"
        END AS "linked_entity_type"
   FROM "public"."v_patch37_clinical_governance_escalation_register" "g"
  WHERE ("g"."escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'action_required'::"text"]))
UNION ALL
 SELECT 'capa'::"text" AS "source_module",
    'capa_action_item'::"text" AS "work_type",
    "ci"."id" AS "work_id",
    "ci"."action_item_title" AS "work_title",
    "ci"."action_item_description" AS "work_description",
    ("ci"."status")::"text" AS "work_status",
    "ci"."priority_level" AS "priority",
    "ci"."action_owner_id" AS "assigned_to_user_id",
    "ci"."department_id",
    "d"."name_en" AS "department_name",
    "ci"."due_date",
    "ci"."created_at",
    (("ci"."due_date" < CURRENT_DATE) AND (("ci"."status")::"text" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))) AS "is_overdue",
    (("ci"."status")::"text" = 'evidence_required'::"text") AS "waiting_for_review",
    (("ci"."status")::"text" = 'blocked'::"text") AS "is_escalated",
    "ci"."capa_id" AS "linked_entity_id",
    'capa'::"text" AS "linked_entity_type"
   FROM ("public"."capa_action_items" "ci"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "ci"."department_id")))
  WHERE (("ci"."status")::"text" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))
UNION ALL
 SELECT 'document'::"text" AS "source_module",
    'document_acknowledgment'::"text" AS "work_type",
    "req"."id" AS "work_id",
    COALESCE("doc"."document_title", "req"."requirement_scope") AS "work_title",
    "req"."requirement_scope" AS "work_description",
    'pending'::"text" AS "work_status",
    NULL::"text" AS "priority",
    "req"."user_id" AS "assigned_to_user_id",
    "req"."department_id",
    "d"."name_en" AS "department_name",
    "req"."due_date",
    "req"."created_at",
    ("req"."due_date" < CURRENT_DATE) AS "is_overdue",
    false AS "waiting_for_review",
    false AS "is_escalated",
    "req"."document_id" AS "linked_entity_id",
    'document'::"text" AS "linked_entity_type"
   FROM (("public"."document_acknowledgment_requirements" "req"
     LEFT JOIN "public"."controlled_documents" "doc" ON (("doc"."id" = "req"."document_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "req"."department_id")))
  WHERE (("req"."required_flag" = true) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."document_acknowledgments" "ack"
          WHERE (("ack"."document_id" = "req"."document_id") AND ("ack"."user_id" = "req"."user_id"))))))
UNION ALL
 SELECT 'approval'::"text" AS "source_module",
    'approval_request'::"text" AS "work_type",
    "ar"."id" AS "work_id",
    "ar"."action_type" AS "work_title",
    "ar"."request_reason" AS "work_description",
    "ar"."request_status" AS "work_status",
    COALESCE("ar"."criticality_level", "ar"."severity_level", "ar"."risk_level") AS "priority",
    "ar"."escalated_to" AS "assigned_to_user_id",
    "ar"."department_id",
    "d"."name_en" AS "department_name",
    "ar"."due_date",
    "ar"."created_at",
    (("ar"."due_date" < CURRENT_DATE) AND ("ar"."request_status" <> ALL (ARRAY['approved'::"text", 'rejected'::"text", 'cancelled'::"text", 'expired'::"text"]))) AS "is_overdue",
    ("ar"."request_status" = ANY (ARRAY['pending'::"text", 'partially_approved'::"text"])) AS "waiting_for_review",
    "ar"."escalation_required" AS "is_escalated",
    "ar"."linked_item_id" AS "linked_entity_id",
    "ar"."linked_item_type" AS "linked_entity_type"
   FROM ("public"."approval_requests" "ar"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "ar"."department_id")))
  WHERE ("ar"."request_status" <> ALL (ARRAY['approved'::"text", 'rejected'::"text", 'cancelled'::"text", 'expired'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch38_department_work_queue" WITH ("security_invoker"='true') AS
 SELECT "source_module",
    "work_type",
    "work_id",
    "work_title",
    "work_description",
    "work_status",
    "priority",
    "assigned_to_user_id",
    "department_id",
    "department_name",
    "due_date",
    "created_at",
    "is_overdue",
    "waiting_for_review",
    "is_escalated",
    "linked_entity_id",
    "linked_entity_type"
   FROM "public"."v_patch38_unified_work_queue" "q"
  WHERE (("department_id" IN ( SELECT "ur"."department_id"
           FROM "public"."user_roles" "ur"
          WHERE (("ur"."user_id" = "auth"."uid"()) AND ("ur"."is_active" = true) AND ("ur"."department_id" IS NOT NULL)))) OR "public"."has_any_role"(ARRAY['super_admin'::"public"."app_role", 'executive'::"public"."app_role", 'governance_admin'::"public"."app_role", 'auditor'::"public"."app_role", 'compliance_officer'::"public"."app_role", 'department_manager'::"public"."app_role"]));

CREATE OR REPLACE VIEW "public"."v_patch38_department_workload_summary" WITH ("security_invoker"='true') AS
 SELECT "department_id",
    "department_name",
    "count"(*) AS "open_work_count",
    "count"(*) FILTER (WHERE "is_overdue") AS "overdue_work_count",
    "count"(*) FILTER (WHERE "waiting_for_review") AS "waiting_for_review_count",
    "count"(*) FILTER (WHERE "is_escalated") AS "escalated_work_count",
    "min"("due_date") AS "nearest_due_date"
   FROM "public"."v_patch38_unified_work_queue"
  WHERE ("department_id" IS NOT NULL)
  GROUP BY "department_id", "department_name";

CREATE OR REPLACE VIEW "public"."v_patch38_escalated_work_queue" WITH ("security_invoker"='true') AS
 SELECT "source_module",
    "work_type",
    "work_id",
    "work_title",
    "work_description",
    "work_status",
    "priority",
    "assigned_to_user_id",
    "department_id",
    "department_name",
    "due_date",
    "created_at",
    "is_overdue",
    "waiting_for_review",
    "is_escalated",
    "linked_entity_id",
    "linked_entity_type"
   FROM "public"."v_patch38_unified_work_queue"
  WHERE (("is_escalated" = true) OR ("work_status" = ANY (ARRAY['escalated'::"text", 'blocked'::"text", 'action_required'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch38_executive_workload_summary" WITH ("security_invoker"='true') AS
 SELECT "source_module",
    "count"(*) AS "open_work_count",
    "count"(*) FILTER (WHERE "is_overdue") AS "overdue_work_count",
    "count"(*) FILTER (WHERE "waiting_for_review") AS "waiting_for_review_count",
    "count"(*) FILTER (WHERE "is_escalated") AS "escalated_work_count"
   FROM "public"."v_patch38_unified_work_queue"
  GROUP BY "source_module";

