CREATE OR REPLACE VIEW "public"."v_patch38_my_work_queue" WITH ("security_invoker"='true') AS
 SELECT "source_module",
    "work_type",
    "work_id",
    "work_title",
    "work_description",
    "work_status",
    "priority",
    "assigned_to_user_id",
    "department_id",
    "department_name",
    "due_date",
