    "is_overdue",
    "waiting_for_review",
    "is_escalated",
    "linked_entity_id",
    "linked_entity_type"
   FROM "public"."v_patch38_unified_work_queue"
  WHERE ("assigned_to_user_id" = "auth"."uid"());

CREATE OR REPLACE VIEW "public"."v_patch38_overdue_work_queue" WITH ("security_invoker"='true') AS
 SELECT "source_module",
    "work_type",
    "work_id",
    "work_title",
    "work_description",
    "work_status",
    "priority",
    "assigned_to_user_id",
    "department_id",
    "department_name",
    "due_date",
    "created_at",
    "is_overdue",
    "waiting_for_review",
    "is_escalated",
    "linked_entity_id",
    "linked_entity_type"
   FROM "public"."v_patch38_unified_work_queue"
  WHERE ("is_overdue" = true);

CREATE OR REPLACE VIEW "public"."v_patch38_waiting_for_review_queue" WITH ("security_invoker"='true') AS
 SELECT "source_module",
    "work_type",
    "work_id",
    "work_title",
    "work_description",
    "work_status",
    "priority",
    "assigned_to_user_id",
    "department_id",
    "department_name",
    "due_date",
    "created_at",
    "is_overdue",
    "waiting_for_review",
    "is_escalated",
    "linked_entity_id",
    "linked_entity_type"
   FROM "public"."v_patch38_unified_work_queue"
  WHERE ("waiting_for_review" = true);

CREATE OR REPLACE VIEW "public"."v_patch38_governance_operating_summary" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch38_unified_work_queue") AS "open_work_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch38_my_work_queue") AS "my_work_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch38_overdue_work_queue") AS "overdue_work_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch38_escalated_work_queue") AS "escalated_work_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch38_waiting_for_review_queue") AS "waiting_for_review_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch38_master_data_exception_register") AS "master_data_exception_count",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch38_overdue_work_queue") > 0) THEN 'attention_required'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch38_escalated_work_queue") > 0) THEN 'watch'::"text"
            ELSE 'on_track'::"text"
        END AS "executive_signal";

CREATE OR REPLACE VIEW "public"."v_patch38_hospital_location_register" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."location_code",
    "l"."location_name",
    "l"."location_name_ar",
    "l"."location_type",
    "l"."parent_location_id",
    "l"."active",
    "l"."owner_user_id",
    "l"."created_at",
    "l"."created_by",
    "p"."full_name_en" AS "owner_name_en",
    "parent"."location_name" AS "parent_location_name"
   FROM (("public"."hospital_master_locations" "l"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "l"."owner_user_id")))
     LEFT JOIN "public"."hospital_master_locations" "parent" ON (("parent"."id" = "l"."parent_location_id")));

CREATE OR REPLACE VIEW "public"."v_patch38_hospital_service_register" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."service_code",
    "s"."service_name",
    "s"."service_name_ar",
    "s"."service_type",
    "s"."department_id",
    "s"."active",
    "s"."owner_user_id",
    "s"."created_at",
    "s"."created_by",
    "d"."name_en" AS "department_name_en",
    "p"."full_name_en" AS "owner_name_en"
   FROM (("public"."hospital_master_services" "s"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "s"."department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "s"."owner_user_id")));

CREATE OR REPLACE VIEW "public"."v_patch38_job_title_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "job_title_code",
    "job_title_name",
    "job_title_name_ar",
    "staff_category",
    "clinical_role",
    "active",
    "created_at",
    "created_by"
   FROM "public"."hospital_master_job_titles";

CREATE OR REPLACE VIEW "public"."v_patch38_master_data_ownership_register" WITH ("security_invoker"='true') AS
 SELECT "m"."id",
    "m"."owner_entity_type",
    "m"."owner_entity_id",
    "m"."governed_entity_type",
    "m"."governed_entity_id",
    "m"."ownership_role",
    "m"."active",
    "m"."created_at",
    "m"."created_by",
        CASE
            WHEN ("m"."owner_entity_type" = 'department'::"text") THEN "d"."name_en"
            WHEN ("m"."owner_entity_type" = 'location'::"text") THEN "l"."location_name"
            WHEN ("m"."owner_entity_type" = 'service'::"text") THEN "s"."service_name"
            WHEN ("m"."owner_entity_type" = 'clinical_area'::"text") THEN "a"."area_name"
            WHEN ("m"."owner_entity_type" = 'committee'::"text") THEN "c"."committee_name"
            WHEN ("m"."owner_entity_type" = 'job_title'::"text") THEN "jt"."job_title_name"
            WHEN ("m"."owner_entity_type" = 'quality_indicator'::"text") THEN "qi"."indicator_name"
            WHEN ("m"."owner_entity_type" = 'user'::"text") THEN "p"."full_name_en"
            ELSE NULL::"text"
        END AS "owner_entity_name"
   FROM (((((((("public"."hospital_master_ownership_mappings" "m"
     LEFT JOIN "public"."departments" "d" ON ((("m"."owner_entity_type" = 'department'::"text") AND ("d"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."hospital_master_locations" "l" ON ((("m"."owner_entity_type" = 'location'::"text") AND ("l"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."hospital_master_services" "s" ON ((("m"."owner_entity_type" = 'service'::"text") AND ("s"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."hospital_master_clinical_areas" "a" ON ((("m"."owner_entity_type" = 'clinical_area'::"text") AND ("a"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."hospital_master_committees" "c" ON ((("m"."owner_entity_type" = 'committee'::"text") AND ("c"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."hospital_master_job_titles" "jt" ON ((("m"."owner_entity_type" = 'job_title'::"text") AND ("jt"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."hospital_master_quality_indicators" "qi" ON ((("m"."owner_entity_type" = 'quality_indicator'::"text") AND ("qi"."id" = "m"."owner_entity_id"))))
     LEFT JOIN "public"."profiles" "p" ON ((("m"."owner_entity_type" = 'user'::"text") AND ("p"."id" = "m"."owner_entity_id"))));

CREATE OR REPLACE VIEW "public"."v_patch38_quality_indicator_register" WITH ("security_invoker"='true') AS
 SELECT "qi"."id",
    "qi"."indicator_code",
    "qi"."indicator_name",
    "qi"."indicator_name_ar",
    "qi"."indicator_domain",
    "qi"."numerator_definition",
    "qi"."denominator_definition",
    "qi"."target_value",
    "qi"."target_direction",
    "qi"."department_id",
    "qi"."owner_user_id",
    "qi"."active",
    "qi"."created_at",
    "qi"."created_by",
    "d"."name_en" AS "department_name_en",
    "p"."full_name_en" AS "owner_name_en"
   FROM (("public"."hospital_master_quality_indicators" "qi"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "qi"."department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "qi"."owner_user_id")));

CREATE OR REPLACE VIEW "public"."v_patch38_user_workload_summary" WITH ("security_invoker"='true') AS
 SELECT "q"."assigned_to_user_id",
    "p"."full_name_en" AS "assigned_to_name",
    "count"(*) AS "open_work_count",
    "count"(*) FILTER (WHERE "q"."is_overdue") AS "overdue_work_count",
    "min"("q"."due_date") AS "nearest_due_date"
   FROM ("public"."v_patch38_unified_work_queue" "q"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "q"."assigned_to_user_id")))
  WHERE ("q"."assigned_to_user_id" IS NOT NULL)
  GROUP BY "q"."assigned_to_user_id", "p"."full_name_en";

CREATE OR REPLACE VIEW "public"."v_patch39_credentialing_expiry_register" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."practitioner_user_id",
    "c"."practitioner_name",
    "c"."department_id",
    "c"."job_title_id",
    "c"."credential_type",
    "c"."credential_title",
    "c"."credential_status",
    "c"."issued_on",
    "c"."expires_on",
    "c"."due_date",
    "c"."reviewer_user_id",
    "c"."evidence_bridge_link_id",
    "c"."accreditation_clause_id",
    "c"."created_by",
    "c"."created_at",
    "d"."name_en" AS "department_name_en",
    "jt"."job_title_name",
    "reviewer"."full_name_en" AS "reviewer_name_en",
    "ac"."clause_code",
    "ac"."clause_title"
   FROM (((("public"."clinical_credentialing_records" "c"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "c"."department_id")))
     LEFT JOIN "public"."hospital_master_job_titles" "jt" ON (("jt"."id" = "c"."job_title_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "c"."reviewer_user_id")))
     LEFT JOIN "public"."accreditation_clauses" "ac" ON (("ac"."id" = "c"."accreditation_clause_id")))
  WHERE (("c"."credential_status" = ANY (ARRAY['active'::"text", 'pending_review'::"text", 'expired'::"text"])) AND (("c"."expires_on" IS NULL) OR ("c"."expires_on" <= (CURRENT_DATE + '90 days'::interval)) OR ("c"."due_date" <= (CURRENT_DATE + '90 days'::interval))));

CREATE OR REPLACE VIEW "public"."v_patch39_facility_biomedical_safety_register" WITH ("security_invoker"='true') AS
 SELECT "f"."id",
    "f"."safety_item_reference",
    "f"."safety_domain",
    "f"."safety_item_title",
    "f"."department_id",
    "f"."location_id",
    "f"."equipment_reference",
    "f"."status",
    "f"."due_date",
    "f"."last_checked_on",
    "f"."next_check_due",
    "f"."owner_user_id",
    "f"."evidence_bridge_link_id",
    "f"."accreditation_clause_id",
    "f"."created_by",
    "f"."created_at",
    "d"."name_en" AS "department_name_en",
    "l"."location_name",
    "p"."full_name_en" AS "owner_name_en",
    "c"."clause_code",
    "c"."clause_title"
   FROM (((("public"."facility_biomedical_safety_evidence" "f"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "f"."department_id")))
     LEFT JOIN "public"."hospital_master_locations" "l" ON (("l"."id" = "f"."location_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "f"."owner_user_id")))
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "f"."accreditation_clause_id")));

CREATE OR REPLACE VIEW "public"."v_patch39_infection_control_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."event_reference",
    "e"."event_type",
    "e"."event_title",
    "e"."department_id",
    "e"."location_id",
    "e"."service_id",
    "e"."severity",
    "e"."status",
    "e"."observed_on",
    "e"."due_date",
    "e"."owner_user_id",
    "e"."evidence_bridge_link_id",
    "e"."accreditation_clause_id",
    "e"."created_by",
    "e"."created_at",
    "e"."closed_at",
    "d"."name_en" AS "department_name_en",
    "l"."location_name",
    "s"."service_name",
    "p"."full_name_en" AS "owner_name_en",
    "c"."clause_code",
    "c"."clause_title"
   FROM ((((("public"."infection_control_surveillance_events" "e"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "e"."department_id")))
     LEFT JOIN "public"."hospital_master_locations" "l" ON (("l"."id" = "e"."location_id")))
     LEFT JOIN "public"."hospital_master_services" "s" ON (("s"."id" = "e"."service_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "e"."owner_user_id")))
     LEFT JOIN "public"."accreditation_clauses" "c" ON (("c"."id" = "e"."accreditation_clause_id")));

CREATE OR REPLACE VIEW "public"."v_patch39_accreditation_blocker_summary" WITH ("security_invoker"='true') AS
 SELECT "accreditation_clause_id",
    "clause_code",
    "clause_title",
    "count"(*) AS "blocker_count",
    "count"(*) FILTER (WHERE ("blocker_source" = 'infection_control'::"text")) AS "infection_control_blockers",
    "count"(*) FILTER (WHERE ("blocker_source" = 'credentialing'::"text")) AS "credentialing_blockers",
    "count"(*) FILTER (WHERE ("blocker_source" = 'facility_safety'::"text")) AS "facility_safety_blockers"
   FROM ( SELECT "v_patch39_infection_control_register"."accreditation_clause_id",
            "v_patch39_infection_control_register"."clause_code",
            "v_patch39_infection_control_register"."clause_title",
            'infection_control'::"text" AS "blocker_source"
           FROM "public"."v_patch39_infection_control_register"
          WHERE (("v_patch39_infection_control_register"."accreditation_clause_id" IS NOT NULL) AND ("v_patch39_infection_control_register"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'under_review'::"text", 'action_required'::"text"])))
        UNION ALL
         SELECT "v_patch39_credentialing_expiry_register"."accreditation_clause_id",
            "v_patch39_credentialing_expiry_register"."clause_code",
            "v_patch39_credentialing_expiry_register"."clause_title",
            'credentialing'::"text" AS "text"
           FROM "public"."v_patch39_credentialing_expiry_register"
          WHERE (("v_patch39_credentialing_expiry_register"."accreditation_clause_id" IS NOT NULL) AND ("v_patch39_credentialing_expiry_register"."credential_status" = ANY (ARRAY['pending_review'::"text", 'expired'::"text", 'suspended'::"text", 'revoked'::"text"])))
        UNION ALL
         SELECT "v_patch39_facility_biomedical_safety_register"."accreditation_clause_id",
            "v_patch39_facility_biomedical_safety_register"."clause_code",
            "v_patch39_facility_biomedical_safety_register"."clause_title",
            'facility_safety'::"text" AS "text"
           FROM "public"."v_patch39_facility_biomedical_safety_register"
          WHERE (("v_patch39_facility_biomedical_safety_register"."accreditation_clause_id" IS NOT NULL) AND ("v_patch39_facility_biomedical_safety_register"."status" = ANY (ARRAY['open'::"text", 'evidence_required'::"text", 'non_compliant'::"text", 'expired'::"text"])))) "blockers"
  GROUP BY "accreditation_clause_id", "clause_code", "clause_title";

CREATE OR REPLACE VIEW "public"."v_patch39_committee_action_queue" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."meeting_id",
    "a"."committee_id",
    "a"."action_title",
    "a"."action_description",
    "a"."assigned_to_user_id",
    "a"."assigned_to_department_id",
    "a"."priority",
    "a"."status",
    "a"."due_date",
    "a"."linked_entity_type",
    "a"."linked_entity_id",
    "a"."evidence_bridge_link_id",
    "a"."created_by",
    "a"."created_at",
    "a"."completed_at",
    "c"."committee_code",
    "c"."committee_name",
    "assignee"."full_name_en" AS "assigned_to_name",
    "d"."name_en" AS "assigned_department_name"
   FROM ((("public"."hospital_committee_actions" "a"
     LEFT JOIN "public"."hospital_master_committees" "c" ON (("c"."id" = "a"."committee_id")))
     LEFT JOIN "public"."profiles" "assignee" ON (("assignee"."id" = "a"."assigned_to_user_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "a"."assigned_to_department_id")))
  WHERE ("a"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch39_committee_meeting_register" WITH ("security_invoker"='true') AS
 SELECT "m"."id",
    "m"."committee_id",
    "m"."meeting_title",
    "m"."meeting_date",
    "m"."meeting_status",
    "m"."chair_user_id",
    "m"."minutes_document_id",
    "m"."evidence_bridge_link_id",
    "m"."created_by",
    "m"."created_at",
    "c"."committee_code",
    "c"."committee_name",
    "chair"."full_name_en" AS "chair_name_en"
   FROM (("public"."hospital_committee_meetings" "m"
     LEFT JOIN "public"."hospital_master_committees" "c" ON (("c"."id" = "m"."committee_id")))
     LEFT JOIN "public"."profiles" "chair" ON (("chair"."id" = "m"."chair_user_id")));

CREATE OR REPLACE VIEW "public"."v_patch39_quality_indicator_performance" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."indicator_id",
    "r"."indicator_code",
    "r"."indicator_name",
    "r"."department_id",
    "r"."service_id",
    "r"."period_start",
    "r"."period_end",
    "r"."numerator",
    "r"."denominator",
    "r"."result_value",
    "r"."target_value",
    "r"."target_direction",
    "r"."performance_status",
    "r"."owner_user_id",
    "r"."evidence_bridge_link_id",
    "r"."created_at",
