     LEFT JOIN "public"."hospital_master_quality_indicators" "qi" ON (("qi"."id" = "r"."indicator_id")));

CREATE OR REPLACE VIEW "public"."v_patch39_hospital_governance_work_queue" WITH ("security_invoker"='true') AS
 SELECT 'hospital_governance'::"text" AS "source_module",
    'infection_control_event'::"text" AS "work_type",
    "v_patch39_infection_control_register"."id" AS "work_id",
    "v_patch39_infection_control_register"."event_title" AS "work_title",
    "v_patch39_infection_control_register"."event_type" AS "work_description",
    "v_patch39_infection_control_register"."status" AS "work_status",
    "v_patch39_infection_control_register"."severity" AS "priority",
    "v_patch39_infection_control_register"."owner_user_id" AS "assigned_to_user_id",
    "v_patch39_infection_control_register"."department_id",
    "v_patch39_infection_control_register"."department_name_en" AS "department_name",
    "v_patch39_infection_control_register"."due_date",
    "v_patch39_infection_control_register"."created_at",
    (("v_patch39_infection_control_register"."due_date" IS NOT NULL) AND ("v_patch39_infection_control_register"."due_date" < CURRENT_DATE) AND ("v_patch39_infection_control_register"."status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) AS "is_overdue",
    ("v_patch39_infection_control_register"."status" = 'under_review'::"text") AS "waiting_for_review",
    (("v_patch39_infection_control_register"."severity" = 'critical'::"text") OR ("v_patch39_infection_control_register"."status" = 'action_required'::"text")) AS "is_escalated",
    "v_patch39_infection_control_register"."evidence_bridge_link_id" AS "linked_entity_id",
    'evidence_bridge'::"text" AS "linked_entity_type"
   FROM "public"."v_patch39_infection_control_register"
  WHERE ("v_patch39_infection_control_register"."status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))
UNION ALL
 SELECT 'hospital_governance'::"text" AS "source_module",
    'clinical_quality_indicator'::"text" AS "work_type",
    "v_patch39_quality_indicator_performance"."id" AS "work_id",
    "v_patch39_quality_indicator_performance"."indicator_name" AS "work_title",
    "v_patch39_quality_indicator_performance"."indicator_code" AS "work_description",
    "v_patch39_quality_indicator_performance"."performance_status" AS "work_status",
        CASE
            WHEN ("v_patch39_quality_indicator_performance"."performance_status" = 'critical'::"text") THEN 'critical'::"text"
            WHEN ("v_patch39_quality_indicator_performance"."performance_status" = 'off_target'::"text") THEN 'high'::"text"
            WHEN ("v_patch39_quality_indicator_performance"."performance_status" = 'watch'::"text") THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "priority",
    "v_patch39_quality_indicator_performance"."owner_user_id" AS "assigned_to_user_id",
    "v_patch39_quality_indicator_performance"."department_id",
    "v_patch39_quality_indicator_performance"."department_name_en" AS "department_name",
    "v_patch39_quality_indicator_performance"."period_end" AS "due_date",
    "v_patch39_quality_indicator_performance"."created_at",
    false AS "is_overdue",
    ("v_patch39_quality_indicator_performance"."performance_status" = ANY (ARRAY['watch'::"text", 'off_target'::"text", 'critical'::"text"])) AS "waiting_for_review",
    ("v_patch39_quality_indicator_performance"."performance_status" = 'critical'::"text") AS "is_escalated",
    "v_patch39_quality_indicator_performance"."evidence_bridge_link_id" AS "linked_entity_id",
    'evidence_bridge'::"text" AS "linked_entity_type"
   FROM "public"."v_patch39_quality_indicator_performance"
  WHERE ("v_patch39_quality_indicator_performance"."performance_status" = ANY (ARRAY['off_target'::"text", 'watch'::"text", 'critical'::"text", 'not_assessed'::"text"]))
UNION ALL
 SELECT 'hospital_governance'::"text" AS "source_module",
    'committee_action'::"text" AS "work_type",
    "v_patch39_committee_action_queue"."id" AS "work_id",
    "v_patch39_committee_action_queue"."action_title" AS "work_title",
    "v_patch39_committee_action_queue"."action_description" AS "work_description",
    "v_patch39_committee_action_queue"."status" AS "work_status",
    "v_patch39_committee_action_queue"."priority",
    "v_patch39_committee_action_queue"."assigned_to_user_id",
    "v_patch39_committee_action_queue"."assigned_to_department_id" AS "department_id",
    "v_patch39_committee_action_queue"."assigned_department_name" AS "department_name",
    "v_patch39_committee_action_queue"."due_date",
    "v_patch39_committee_action_queue"."created_at",
    (("v_patch39_committee_action_queue"."due_date" IS NOT NULL) AND ("v_patch39_committee_action_queue"."due_date" < CURRENT_DATE) AND ("v_patch39_committee_action_queue"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))) AS "is_overdue",
    ("v_patch39_committee_action_queue"."status" = 'under_review'::"text") AS "waiting_for_review",
    ("v_patch39_committee_action_queue"."status" = 'escalated'::"text") AS "is_escalated",
    "v_patch39_committee_action_queue"."linked_entity_id",
    "v_patch39_committee_action_queue"."linked_entity_type"
   FROM "public"."v_patch39_committee_action_queue"
UNION ALL
 SELECT 'hospital_governance'::"text" AS "source_module",
    'credentialing_record'::"text" AS "work_type",
    "v_patch39_credentialing_expiry_register"."id" AS "work_id",
    "v_patch39_credentialing_expiry_register"."credential_title" AS "work_title",
    "v_patch39_credentialing_expiry_register"."credential_type" AS "work_description",
    "v_patch39_credentialing_expiry_register"."credential_status" AS "work_status",
        CASE
            WHEN ("v_patch39_credentialing_expiry_register"."credential_status" = ANY (ARRAY['expired'::"text", 'suspended'::"text", 'revoked'::"text"])) THEN 'critical'::"text"
            WHEN ("v_patch39_credentialing_expiry_register"."expires_on" <= (CURRENT_DATE + '30 days'::interval)) THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "priority",
    "v_patch39_credentialing_expiry_register"."practitioner_user_id" AS "assigned_to_user_id",
    "v_patch39_credentialing_expiry_register"."department_id",
    "v_patch39_credentialing_expiry_register"."department_name_en" AS "department_name",
    COALESCE("v_patch39_credentialing_expiry_register"."due_date", "v_patch39_credentialing_expiry_register"."expires_on") AS "due_date",
    "v_patch39_credentialing_expiry_register"."created_at",
    ((COALESCE("v_patch39_credentialing_expiry_register"."due_date", "v_patch39_credentialing_expiry_register"."expires_on") IS NOT NULL) AND (COALESCE("v_patch39_credentialing_expiry_register"."due_date", "v_patch39_credentialing_expiry_register"."expires_on") < CURRENT_DATE) AND ("v_patch39_credentialing_expiry_register"."credential_status" <> 'waived'::"text")) AS "is_overdue",
    ("v_patch39_credentialing_expiry_register"."credential_status" = 'pending_review'::"text") AS "waiting_for_review",
    ("v_patch39_credentialing_expiry_register"."credential_status" = ANY (ARRAY['expired'::"text", 'suspended'::"text", 'revoked'::"text"])) AS "is_escalated",
    "v_patch39_credentialing_expiry_register"."evidence_bridge_link_id" AS "linked_entity_id",
    'evidence_bridge'::"text" AS "linked_entity_type"
   FROM "public"."v_patch39_credentialing_expiry_register"
UNION ALL
 SELECT 'hospital_governance'::"text" AS "source_module",
    'facility_biomedical_safety'::"text" AS "work_type",
    "v_patch39_facility_biomedical_safety_register"."id" AS "work_id",
    "v_patch39_facility_biomedical_safety_register"."safety_item_title" AS "work_title",
    "v_patch39_facility_biomedical_safety_register"."safety_domain" AS "work_description",
    "v_patch39_facility_biomedical_safety_register"."status" AS "work_status",
        CASE
            WHEN ("v_patch39_facility_biomedical_safety_register"."status" = ANY (ARRAY['non_compliant'::"text", 'expired'::"text"])) THEN 'critical'::"text"
            WHEN ("v_patch39_facility_biomedical_safety_register"."status" = 'evidence_required'::"text") THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "priority",
    "v_patch39_facility_biomedical_safety_register"."owner_user_id" AS "assigned_to_user_id",
    "v_patch39_facility_biomedical_safety_register"."department_id",
    "v_patch39_facility_biomedical_safety_register"."department_name_en" AS "department_name",
    COALESCE("v_patch39_facility_biomedical_safety_register"."due_date", "v_patch39_facility_biomedical_safety_register"."next_check_due") AS "due_date",
    "v_patch39_facility_biomedical_safety_register"."created_at",
    ((COALESCE("v_patch39_facility_biomedical_safety_register"."due_date", "v_patch39_facility_biomedical_safety_register"."next_check_due") IS NOT NULL) AND (COALESCE("v_patch39_facility_biomedical_safety_register"."due_date", "v_patch39_facility_biomedical_safety_register"."next_check_due") < CURRENT_DATE) AND ("v_patch39_facility_biomedical_safety_register"."status" <> ALL (ARRAY['compliant'::"text", 'cancelled'::"text"]))) AS "is_overdue",
    ("v_patch39_facility_biomedical_safety_register"."status" = 'under_review'::"text") AS "waiting_for_review",
    ("v_patch39_facility_biomedical_safety_register"."status" = ANY (ARRAY['non_compliant'::"text", 'expired'::"text"])) AS "is_escalated",
    "v_patch39_facility_biomedical_safety_register"."evidence_bridge_link_id" AS "linked_entity_id",
    'evidence_bridge'::"text" AS "linked_entity_type"
   FROM "public"."v_patch39_facility_biomedical_safety_register"
  WHERE ("v_patch39_facility_biomedical_safety_register"."status" <> ALL (ARRAY['compliant'::"text", 'cancelled'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch39_department_hospital_governance_scorecard" WITH ("security_invoker"='true') AS
 SELECT "department_id",
    "department_name",
    "count"(*) AS "open_item_count",
    "count"(*) FILTER (WHERE "is_overdue") AS "overdue_item_count",
    "count"(*) FILTER (WHERE ("priority" = ANY (ARRAY['high'::"text", 'critical'::"text"]))) AS "high_priority_item_count",
    "count"(*) FILTER (WHERE "waiting_for_review") AS "waiting_for_review_count",
    "count"(*) FILTER (WHERE "is_escalated") AS "escalated_item_count"
   FROM "public"."v_patch39_hospital_governance_work_queue"
  GROUP BY "department_id", "department_name";

CREATE OR REPLACE VIEW "public"."v_patch39_facility_safety_evidence_gap_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "safety_item_reference",
    "safety_domain",
    "safety_item_title",
    "department_id",
    "location_id",
    "equipment_reference",
    "status",
    "due_date",
    "last_checked_on",
    "next_check_due",
    "owner_user_id",
    "evidence_bridge_link_id",
    "accreditation_clause_id",
    "created_by",
    "created_at",
    "department_name_en",
    "location_name",
    "owner_name_en",
    "clause_code",
    "clause_title"
   FROM "public"."v_patch39_facility_biomedical_safety_register"
  WHERE (("status" = ANY (ARRAY['open'::"text", 'evidence_required'::"text", 'non_compliant'::"text", 'expired'::"text"])) OR ("evidence_bridge_link_id" IS NULL) OR (("next_check_due" IS NOT NULL) AND ("next_check_due" < CURRENT_DATE)));

CREATE OR REPLACE VIEW "public"."v_patch39_infection_control_open_actions" WITH ("security_invoker"='true') AS
 SELECT "id",
    "event_reference",
    "event_type",
