    "department_id",
    "location_id",
    "service_id",
    "severity",
    "status",
    "observed_on",
    "due_date",
    "owner_user_id",
    "evidence_bridge_link_id",
    "accreditation_clause_id",
    "created_by",
    "created_at",
    "closed_at",
    "department_name_en",
