  WHERE (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'under_review'::"text", 'action_required'::"text"])) OR (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))));

CREATE OR REPLACE VIEW "public"."v_patch39_overdue_committee_actions" WITH ("security_invoker"='true') AS
