   FROM "public"."v_patch39_committee_action_queue"
  WHERE (("status" = 'overdue'::"text") OR (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE)));

CREATE OR REPLACE VIEW "public"."v_patch39_quality_indicator_off_target_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "indicator_id",
