   FROM "public"."v_patch39_quality_indicator_performance"
  WHERE ("performance_status" = ANY (ARRAY['off_target'::"text", 'watch'::"text", 'critical'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch39_executive_hospital_quality_summary" WITH ("security_invoker"='true') AS
 SELECT ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch39_infection_control_open_actions") AS "open_infection_control_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch39_quality_indicator_off_target_register") AS "off_target_indicator_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch39_overdue_committee_actions") AS "overdue_committee_action_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch39_credentialing_expiry_register"
          WHERE ("v_patch39_credentialing_expiry_register"."credential_status" = ANY (ARRAY['pending_review'::"text", 'expired'::"text"]))) AS "credentialing_due_or_expired_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch39_facility_safety_evidence_gap_register") AS "facility_safety_gap_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_patch39_accreditation_blocker_summary") AS "accreditation_blocked_clause_count",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch39_hospital_governance_work_queue"
              WHERE (("v_patch39_hospital_governance_work_queue"."priority" = 'critical'::"text") OR "v_patch39_hospital_governance_work_queue"."is_escalated")) > 0) THEN 'critical_attention_required'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_patch39_hospital_governance_work_queue"
              WHERE "v_patch39_hospital_governance_work_queue"."is_overdue") > 0) THEN 'overdue_items_present'::"text"
            ELSE 'operating'::"text"
        END AS "executive_signal";

