  WHERE (("credential_type" = ANY (ARRAY['privilege'::"text", 'competency'::"text", 'scope_of_practice'::"text", 'training_requirement'::"text"])) AND (("credential_status" = ANY (ARRAY['pending_review'::"text", 'expired'::"text", 'suspended'::"text", 'revoked'::"text"])) OR ("evidence_bridge_link_id" IS NULL)));

