CREATE OR REPLACE VIEW "public"."v_patch40_bilingual_readiness_dashboard" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_items",
    ("count"(
        CASE
            WHEN ("readiness_status" = 'ready'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "ready_items",
    ("count"(
        CASE
            WHEN ("readiness_status" = ANY (ARRAY['missing'::"text", 'partial'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "incomplete_items",
    ("count"(
        CASE
            WHEN ("readiness_status" = 'needs_review'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "review_items"
   FROM "public"."bilingual_readiness_items";

CREATE OR REPLACE VIEW "public"."v_patch40_blocking_limitations" WITH ("security_invoker"='true') AS
 SELECT "id",
    "limitation_title",
    "limitation_description",
    "limitation_area",
    "severity",
    "limitation_status",
    "mitigation_plan",
    "owner_user_id",
    "target_resolution_date",
    "created_by",
    "created_at",
    "resolved_at"
   FROM "public"."production_known_limitations"
  WHERE (("limitation_status" = ANY (ARRAY['open'::"text", 'mitigation_in_progress'::"text"])) AND ("severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch40_controlled_pilot_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT "signoff_area",
    "signoff_status",
    "signoff_notes"
   FROM "public"."production_readiness_signoffs"
  WHERE ("signoff_area" = ANY (ARRAY['persona_access'::"text", 'evidence_bridge'::"text", 'accreditation_workflow'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch40_go_no_go_dashboard" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_signoffs",
    ("count"(
        CASE
            WHEN ("signoff_status" = ANY (ARRAY['ready'::"text", 'ready_with_limitations'::"text", 'waived'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "approved_signoffs",
    ("count"(
        CASE
            WHEN ("signoff_status" = 'pending'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "pending_signoffs",
    ("count"(
        CASE
            WHEN ("signoff_status" = ANY (ARRAY['blocked'::"text", 'rejected'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "blocked_signoffs",
        CASE
            WHEN ("count"(*) = 0) THEN 100.0
            ELSE "round"(((("count"(
            CASE
                WHEN ("signoff_status" = ANY (ARRAY['ready'::"text", 'ready_with_limitations'::"text", 'waived'::"text"])) THEN 1
                ELSE NULL::integer
            END))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "readiness_percentage"
   FROM "public"."production_readiness_signoffs";

CREATE OR REPLACE VIEW "public"."v_patch40_executive_production_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT "total_signoffs",
    "approved_signoffs" AS "ready_signoffs",
    "blocked_signoffs",
        CASE
            WHEN ("blocked_signoffs" > 0) THEN 'blocked'::"text"
            WHEN ("pending_signoffs" > 0) THEN 'pending'::"text"
            WHEN ("approved_signoffs" = "total_signoffs") THEN 'ready'::"text"
            ELSE 'ready_with_limitations'::"text"
        END AS "overall_status"
   FROM "public"."v_patch40_go_no_go_dashboard";

CREATE OR REPLACE VIEW "public"."v_patch40_known_limitations_register" WITH ("security_invoker"='true') AS
