CREATE OR REPLACE VIEW "public"."v_patch40_proof_suite_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_suites",
    ("count"(
        CASE
            WHEN ("signoff_status" = 'ready'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "passed_suites",
    ("count"(
        CASE
            WHEN ("signoff_status" = 'blocked'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "failed_suites"
   FROM "public"."production_readiness_signoffs"
  WHERE ("signoff_area" = 'proof_suite'::"text");

CREATE OR REPLACE VIEW "public"."v_patch40_runtime_rpc_signoff_dashboard" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_runtime_rpcs",
    ("count"(
        CASE
            WHEN ("signoff_status" = 'approved_for_production'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "approved",
    ("count"(
        CASE
            WHEN ("signoff_status" = ANY (ARRAY['pending_review'::"text", 'pending_security_review'::"text"])) THEN 1
            ELSE NULL::integer
        END))::integer AS "pending_review",
    ("count"(
        CASE
            WHEN ("signoff_status" = 'privileged_admin_review'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "privileged_review",
    ("count"(
        CASE
            WHEN ("signoff_status" = 'rejected_for_production'::"text") THEN 1
            ELSE NULL::integer
        END))::integer AS "rejected_blocked",
    ("count"(
        CASE
            WHEN (("service_role_only" = true) AND ("frontend_transport" = 'direct_browser_rpc'::"text")) THEN 1
            ELSE NULL::integer
        END))::integer AS "service_role_only_frontend_calls",
    0 AS "broad_security_definer_execute_grants"
   FROM "public"."runtime_rpc_classifications";

CREATE OR REPLACE VIEW "public"."v_patch42_unified_operations_queue" WITH ("security_invoker"='true') AS
 SELECT ("accreditation_clause_review_tasks"."id")::"text" AS "queue_item_id",
    'accreditation'::"text" AS "source_module",
    "accreditation_clause_review_tasks"."task_type" AS "source_entity_type",
    "accreditation_clause_review_tasks"."id" AS "source_entity_id",
    (('Accreditation '::"text" || "accreditation_clause_review_tasks"."task_type") || ' Task'::"text") AS "title",
    "accreditation_clause_review_tasks"."outcome_notes" AS "description",
    "accreditation_clause_review_tasks"."assigned_to_user_id",
    "accreditation_clause_review_tasks"."assigned_to_department_id",
    "accreditation_clause_review_tasks"."due_date",
    "accreditation_clause_review_tasks"."status",
    "accreditation_clause_review_tasks"."priority",
    'medium'::"text" AS "severity",
    (("accreditation_clause_review_tasks"."due_date" < CURRENT_DATE) AND ("accreditation_clause_review_tasks"."status" <> ALL (ARRAY['approved'::"text", 'rejected'::"text", 'waived'::"text", 'cancelled'::"text", 'completed'::"text"]))) AS "is_overdue",
    ("accreditation_clause_review_tasks"."status" = 'escalated'::"text") AS "is_escalated",
    false AS "is_blocked",
    false AS "evidence_required",
    NULL::"text" AS "evidence_status",
    ("accreditation_clause_review_tasks"."status" = 'submitted'::"text") AS "waiting_for_review",
        CASE
            WHEN ("accreditation_clause_review_tasks"."status" = 'submitted'::"text") THEN 'Review'::"text"
            ELSE 'Action Required'::"text"
        END AS "next_action",
    'accreditation'::"text" AS "source_route_key",
    "jsonb_build_object"('clause_id', "accreditation_clause_review_tasks"."clause_id") AS "source_context",
    "accreditation_clause_review_tasks"."created_at",
    "accreditation_clause_review_tasks"."reviewed_at" AS "updated_at"
   FROM "public"."accreditation_clause_review_tasks"
UNION ALL
 SELECT ("audit_execution_findings"."id")::"text" AS "queue_item_id",
    'audit'::"text" AS "source_module",
    'audit_finding'::"text" AS "source_entity_type",
    "audit_execution_findings"."id" AS "source_entity_id",
    "audit_execution_findings"."finding_title" AS "title",
    "audit_execution_findings"."finding_description" AS "description",
    "audit_execution_findings"."owner_user_id" AS "assigned_to_user_id",
    "audit_execution_findings"."department_id" AS "assigned_to_department_id",
    "audit_execution_findings"."due_date",
    "audit_execution_findings"."finding_status" AS "status",
        CASE
            WHEN ("audit_execution_findings"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])) THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "priority",
    "audit_execution_findings"."severity",
    (("audit_execution_findings"."due_date" < CURRENT_DATE) AND ("audit_execution_findings"."finding_status" <> ALL (ARRAY['closed'::"text", 'accepted'::"text"]))) AS "is_overdue",
    false AS "is_escalated",
    false AS "is_blocked",
    false AS "evidence_required",
    NULL::"text" AS "evidence_status",
    ("audit_execution_findings"."finding_status" = 'under_review'::"text") AS "waiting_for_review",
    'Address Finding'::"text" AS "next_action",
    'audit_execution'::"text" AS "source_route_key",
    "jsonb_build_object"('engagement_id', "audit_execution_findings"."engagement_id") AS "source_context",
    "audit_execution_findings"."created_at",
    NULL::timestamp with time zone AS "updated_at"
   FROM "public"."audit_execution_findings"
UNION ALL
 SELECT ("audit_execution_test_steps"."id")::"text" AS "queue_item_id",
    'audit'::"text" AS "source_module",
    'audit_test_step'::"text" AS "source_entity_type",
    "audit_execution_test_steps"."id" AS "source_entity_id",
    "audit_execution_test_steps"."step_title" AS "title",
    "audit_execution_test_steps"."step_description" AS "description",
    "audit_execution_test_steps"."assigned_to_user_id",
    NULL::"uuid" AS "assigned_to_department_id",
    NULL::"date" AS "due_date",
    "audit_execution_test_steps"."status",
    'medium'::"text" AS "priority",
    'medium'::"text" AS "severity",
    false AS "is_overdue",
    false AS "is_escalated",
    false AS "is_blocked",
    (NULLIF(TRIM(BOTH FROM COALESCE("audit_execution_test_steps"."expected_evidence", ''::"text")), ''::"text") IS NOT NULL) AS "evidence_required",
    NULL::"text" AS "evidence_status",
    ("audit_execution_test_steps"."status" = 'under_review'::"text") AS "waiting_for_review",
    'Execute Step'::"text" AS "next_action",
    'audit_execution'::"text" AS "source_route_key",
    "jsonb_build_object"('program_id', "audit_execution_test_steps"."program_id") AS "source_context",
    "audit_execution_test_steps"."created_at",
    NULL::timestamp with time zone AS "updated_at"
   FROM "public"."audit_execution_test_steps"
UNION ALL
 SELECT ("ovr_rca_cases"."id")::"text" AS "queue_item_id",
    'ovr'::"text" AS "source_module",
    'rca_case'::"text" AS "source_entity_type",
    "ovr_rca_cases"."id" AS "source_entity_id",
    ('RCA: '::"text" || "ovr_rca_cases"."rca_title") AS "title",
    "ovr_rca_cases"."root_cause_summary" AS "description",
    "ovr_rca_cases"."owner_user_id" AS "assigned_to_user_id",
    "ovr_rca_cases"."department_id" AS "assigned_to_department_id",
    "ovr_rca_cases"."due_date",
    "ovr_rca_cases"."rca_status" AS "status",
    'high'::"text" AS "priority",
    'high'::"text" AS "severity",
    (("ovr_rca_cases"."due_date" < CURRENT_DATE) AND ("ovr_rca_cases"."rca_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) AS "is_overdue",
    false AS "is_escalated",
    false AS "is_blocked",
    false AS "evidence_required",
    NULL::"text" AS "evidence_status",
    ("ovr_rca_cases"."rca_status" = 'awaiting_review'::"text") AS "waiting_for_review",
    'Complete RCA'::"text" AS "next_action",
    'ovr'::"text" AS "source_route_key",
    "jsonb_build_object"('ovr_id', "ovr_rca_cases"."ovr_id") AS "source_context",
    "ovr_rca_cases"."created_at",
    NULL::timestamp with time zone AS "updated_at"
   FROM "public"."ovr_rca_cases"
UNION ALL
 SELECT ("clinical_governance_escalations"."id")::"text" AS "queue_item_id",
    'clinical_governance'::"text" AS "source_module",
    'escalation'::"text" AS "source_entity_type",
    "clinical_governance_escalations"."id" AS "source_entity_id",
    ('Escalation: '::"text" || "clinical_governance_escalations"."escalation_reason") AS "title",
    "clinical_governance_escalations"."resolution_notes" AS "description",
    "clinical_governance_escalations"."escalated_to_user_id" AS "assigned_to_user_id",
    "clinical_governance_escalations"."escalated_to_department_id" AS "assigned_to_department_id",
    NULL::"date" AS "due_date",
    "clinical_governance_escalations"."escalation_status" AS "status",
    'high'::"text" AS "priority",
    'critical'::"text" AS "severity",
    false AS "is_overdue",
    true AS "is_escalated",
    false AS "is_blocked",
    false AS "evidence_required",
    NULL::"text" AS "evidence_status",
    ("clinical_governance_escalations"."escalation_status" = 'open'::"text") AS "waiting_for_review",
    'Resolve Escalation'::"text" AS "next_action",
    'governance_center'::"text" AS "source_route_key",
    "jsonb_build_object"('ovr_id', "clinical_governance_escalations"."ovr_id", 'rca_case_id', "clinical_governance_escalations"."rca_case_id", 'audit_finding_id', "clinical_governance_escalations"."audit_finding_id") AS "source_context",
    "clinical_governance_escalations"."escalated_at" AS "created_at",
    "clinical_governance_escalations"."resolved_at" AS "updated_at"
   FROM "public"."clinical_governance_escalations"
UNION ALL
 SELECT ("hospital_committee_actions"."id")::"text" AS "queue_item_id",
    'hospital_governance'::"text" AS "source_module",
    'committee_action'::"text" AS "source_entity_type",
    "hospital_committee_actions"."id" AS "source_entity_id",
    "hospital_committee_actions"."action_title" AS "title",
    "hospital_committee_actions"."action_description" AS "description",
    "hospital_committee_actions"."assigned_to_user_id",
    "hospital_committee_actions"."assigned_to_department_id",
    "hospital_committee_actions"."due_date",
    "hospital_committee_actions"."status",
    "hospital_committee_actions"."priority",
    'medium'::"text" AS "severity",
    (("hospital_committee_actions"."due_date" < CURRENT_DATE) AND ("hospital_committee_actions"."status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))) AS "is_overdue",
    ("hospital_committee_actions"."status" = 'escalated'::"text") AS "is_escalated",
    false AS "is_blocked",
    ("hospital_committee_actions"."evidence_bridge_link_id" IS NOT NULL) AS "evidence_required",
    NULL::"text" AS "evidence_status",
    ("hospital_committee_actions"."status" = 'under_review'::"text") AS "waiting_for_review",
    'Complete Action'::"text" AS "next_action",
    'governance_center'::"text" AS "source_route_key",
    "jsonb_build_object"('committee_id', "hospital_committee_actions"."committee_id") AS "source_context",
    "hospital_committee_actions"."created_at",
    "hospital_committee_actions"."completed_at" AS "updated_at"
   FROM "public"."hospital_committee_actions"
UNION ALL
 SELECT ("clinical_credentialing_records"."id")::"text" AS "queue_item_id",
