CREATE OR REPLACE VIEW "public"."v_patch43_queue_evidence_gate_overlay" WITH ("security_invoker"='true') AS
 SELECT "q"."queue_item_id",
    "q"."source_module",
    "q"."source_entity_type",
    "q"."source_entity_id",
    "q"."title",
    "q"."status" AS "work_status",
    "q"."priority",
    "q"."severity",
    "q"."due_date",
    "q"."assigned_to_user_id",
    "q"."assigned_to_department_id",
    "q"."is_overdue",
    "q"."is_escalated",
    "q"."waiting_for_review",
    "q"."next_action" AS "queue_next_action",
    "ev"."gate_status",
    "ev"."accepted_evidence_count",
    "ev"."missing_evidence_count",
    "ev"."rejected_evidence_count",
    "ev"."expired_evidence_count",
    "ev"."superseded_evidence_count",
    "ev"."active_waiver_id",
    "ev"."evaluated_at",
        CASE
            WHEN ("ev"."gate_status" IS NULL) THEN 'Evaluate evidence gate'::"text"
            WHEN ("ev"."gate_status" = 'pass'::"text") THEN COALESCE("q"."next_action", 'Proceed'::"text")
            WHEN ("ev"."gate_status" = 'waived'::"text") THEN COALESCE("q"."next_action", 'Proceed with waiver'::"text")
            ELSE 'Resolve evidence gate before closure'::"text"
        END AS "evidence_gate_next_action"
   FROM ("public"."v_patch42_unified_operations_queue" "q"
     LEFT JOIN LATERAL ( SELECT "e"."id",
            "e"."entity_type",
            "e"."entity_id",
            "e"."gate_rule_id",
            "e"."gate_status",
            "e"."accepted_evidence_count",
            "e"."rejected_evidence_count",
            "e"."expired_evidence_count",
            "e"."superseded_evidence_count",
            "e"."missing_evidence_count",
            "e"."active_waiver_id",
            "e"."evaluated_by",
            "e"."evaluated_at",
            "e"."evaluation_context"
           FROM "public"."evidence_gate_evaluations" "e"
          WHERE (("e"."entity_type" = "q"."source_entity_type") AND ("e"."entity_id" = "q"."source_entity_id"))
          ORDER BY "e"."evaluated_at" DESC
         LIMIT 1) "ev" ON (true))
  WHERE ("q"."status" <> ALL (ARRAY['completed'::"text", 'closed'::"text", 'resolved'::"text", 'cancelled'::"text"]));

