   FROM (("public"."runtime_action_review_events" "e"
     LEFT JOIN "public"."runtime_action_reviews" "r" ON (("r"."id" = "e"."action_review_id")))
     LEFT JOIN "public"."profiles" "actor" ON (("actor"."id" = "e"."actor_user_id")));

COMMENT ON VIEW "public"."v_patch45_access_review_evidence_register" IS 'Patch 180 canonical security-invoker/barrier runtime action audit view.';

CREATE OR REPLACE VIEW "public"."v_patch45_runtime_action_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "action_name",
    "action_transport",
    "module_name",
    "risk_level",
    "classification",
    "review_status",
    "required_access_level",
    "owner_role",
    "review_notes",
    "reviewed_by",
    "reviewed_at",
    "created_by",
    "created_at",
        CASE
            WHEN ("action_transport" = 'direct_browser_rpc'::"text") THEN true
            ELSE false
        END AS "direct_browser_exception",
        CASE
            WHEN ("review_status" = 'rejected'::"text") THEN 'blocked'::"text"
            WHEN (("classification" = 'unknown_requires_review'::"text") OR ("review_status" = 'pending_review'::"text")) THEN 'needs_review'::"text"
            WHEN (("risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("review_status" <> 'approved'::"text")) THEN 'needs_limited_approval'::"text"
            ELSE 'reviewed'::"text"
        END AS "authorization_signal"
   FROM "public"."runtime_action_reviews" "r";

CREATE OR REPLACE VIEW "public"."v_patch45_direct_browser_rpc_exception_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "action_name",
    "action_transport",
    "module_name",
    "risk_level",
    "classification",
    "review_status",
    "required_access_level",
    "owner_role",
    "review_notes",
    "reviewed_by",
    "reviewed_at",
    "created_by",
    "created_at",
    "direct_browser_exception",
    "authorization_signal"
   FROM "public"."v_patch45_runtime_action_register"
  WHERE ("action_transport" = 'direct_browser_rpc'::"text");

CREATE OR REPLACE VIEW "public"."v_patch45_privileged_runtime_action_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "action_name",
    "action_transport",
    "module_name",
    "risk_level",
    "classification",
    "review_status",
    "required_access_level",
    "owner_role",
    "review_notes",
    "reviewed_by",
    "reviewed_at",
    "created_by",
    "created_at",
    "direct_browser_exception",
    "authorization_signal"
   FROM "public"."v_patch45_runtime_action_register"
  WHERE (("classification" = ANY (ARRAY['privileged_admin'::"text", 'user_management'::"text"])) OR ("risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch45_runtime_authorization_summary" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "runtime_action_total",
    "count"(*) FILTER (WHERE ("classification" <> 'unknown_requires_review'::"text")) AS "classified_action_count",
    "count"(*) FILTER (WHERE ("classification" = 'unknown_requires_review'::"text")) AS "unknown_requires_review_count",
    "count"(*) FILTER (WHERE ("review_status" = 'pending_review'::"text")) AS "pending_review_count",
    "count"(*) FILTER (WHERE (("classification" = ANY (ARRAY['privileged_admin'::"text", 'user_management'::"text"])) OR ("risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"])))) AS "privileged_action_count",
    "count"(*) FILTER (WHERE ("action_transport" = 'direct_browser_rpc'::"text")) AS "direct_browser_rpc_exception_count",
    "count"(*) FILTER (WHERE ("review_status" = 'approved'::"text")) AS "approved_count",
    "count"(*) FILTER (WHERE ("review_status" = 'approved_with_limitation'::"text")) AS "approved_with_limitation_count",
    "count"(*) FILTER (WHERE ("review_status" = 'rejected'::"text")) AS "rejected_count",
    0 AS "service_role_only_frontend_calls",
    0 AS "broad_security_definer_execute_grants",
        CASE
            WHEN ("count"(*) FILTER (WHERE ("review_status" = 'rejected'::"text")) > 0) THEN 'blocked'::"text"
            WHEN ("count"(*) FILTER (WHERE (("classification" = 'unknown_requires_review'::"text") OR ("review_status" = 'pending_review'::"text"))) > 0) THEN 'needs_access_review'::"text"
            WHEN ("count"(*) FILTER (WHERE ("action_transport" = 'direct_browser_rpc'::"text")) > 0) THEN 'approved_with_monitored_exception'::"text"
            ELSE 'ready'::"text"
        END AS "production_security_signal",
        CASE
            WHEN ("count"(*) FILTER (WHERE (("classification" = 'unknown_requires_review'::"text") OR ("review_status" = 'pending_review'::"text"))) > 0) THEN 'Complete runtime action owner review and signoff.'::"text"
            WHEN ("count"(*) FILTER (WHERE ("action_transport" = 'direct_browser_rpc'::"text")) > 0) THEN 'Monitor direct browser RPC exception under RLS/security-invoker proof.'::"text"
            ELSE 'Runtime action review is complete.'::"text"
        END AS "next_action_required"
   FROM "public"."runtime_action_reviews";

CREATE OR REPLACE VIEW "public"."v_patch45_production_security_readiness_overlay" WITH ("security_invoker"='true') AS
 SELECT "runtime_action_total",
    "classified_action_count",
    "unknown_requires_review_count",
    "pending_review_count",
    "privileged_action_count",
    "direct_browser_rpc_exception_count",
    "approved_count",
    "approved_with_limitation_count",
    "rejected_count",
    "service_role_only_frontend_calls",
    "broad_security_definer_execute_grants",
    "production_security_signal",
    "next_action_required",
        CASE
            WHEN (("broad_security_definer_execute_grants" > 0) OR ("service_role_only_frontend_calls" > 0)) THEN 'blocked'::"text"
            ELSE "production_security_signal"
        END AS "readiness_status"
   FROM "public"."v_patch45_runtime_authorization_summary" "s";

