CREATE OR REPLACE VIEW "public"."v_patch46_runtime_access_review_register" WITH ("security_invoker"='true') AS
 WITH "latest_signoff" AS (
         SELECT DISTINCT ON ("s_1"."action_name") "s_1"."id",
            "s_1"."action_name",
            "s_1"."reviewer_role",
            "s_1"."reviewer_user_id",
            "s_1"."signoff_status",
            "s_1"."risk_acceptance_required",
            "s_1"."limitation_summary",
            "s_1"."evidence_reference",
            "s_1"."due_at",
            "s_1"."signed_off_at",
            "s_1"."created_by",
            "s_1"."created_at"
           FROM "public"."runtime_action_review_signoffs" "s_1"
          WHERE ("s_1"."signoff_status" <> 'superseded'::"text")
          ORDER BY "s_1"."action_name", "s_1"."created_at" DESC
        )
 SELECT "r"."action_name",
    "r"."action_transport",
    "r"."module_name",
    "r"."risk_level",
    "r"."classification",
    "r"."review_status" AS "classification_review_status",
    "r"."required_access_level",
    "r"."owner_role",
    ("r"."action_transport" = 'direct_browser_rpc'::"text") AS "direct_browser_exception",
    "s"."id" AS "signoff_id",
    COALESCE("s"."reviewer_role", "r"."owner_role", 'Runtime Security Reviewer'::"text") AS "reviewer_role",
    "s"."reviewer_user_id",
    COALESCE("s"."signoff_status", 'pending'::"text") AS "signoff_status",
    COALESCE("s"."risk_acceptance_required", (("r"."risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"])) OR ("r"."action_transport" = 'direct_browser_rpc'::"text"))) AS "risk_acceptance_required",
    "s"."limitation_summary",
    "s"."evidence_reference",
    "s"."due_at",
    "s"."signed_off_at",
    "s"."created_at",
    ((COALESCE("s"."signoff_status", 'pending'::"text") = 'pending'::"text") AND ("s"."due_at" IS NOT NULL) AND ("s"."due_at" < "now"())) AS "is_overdue",
        CASE
            WHEN ("s"."id" IS NULL) THEN 'missing access-review signoff'::"text"
            WHEN ("s"."signoff_status" = 'rejected'::"text") THEN 'runtime action signoff rejected'::"text"
            WHEN (("s"."signoff_status" = 'pending'::"text") AND ("s"."due_at" IS NOT NULL) AND ("s"."due_at" < "now"())) THEN 'runtime action signoff overdue'::"text"
            WHEN (("s"."signoff_status" = 'pending'::"text") AND ("r"."risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"]))) THEN 'high-risk runtime action pending signoff'::"text"
            WHEN (("s"."signoff_status" = 'approved_with_limitation'::"text") AND (NULLIF("s"."limitation_summary", ''::"text") IS NULL)) THEN 'approved with limitation requires limitation summary'::"text"
            WHEN (("s"."signoff_status" = ANY (ARRAY['approved'::"text", 'approved_with_limitation'::"text"])) AND (NULLIF("s"."evidence_reference", ''::"text") IS NULL)) THEN 'closure evidence required'::"text"
            ELSE NULL::"text"
        END AS "blocker_reason"
   FROM ("public"."runtime_action_reviews" "r"
     LEFT JOIN "latest_signoff" "s" ON (("s"."action_name" = "r"."action_name")));

CREATE OR REPLACE VIEW "public"."v_patch46_overdue_runtime_access_reviews" WITH ("security_invoker"='true') AS
 SELECT "action_name",
