CREATE OR REPLACE VIEW "public"."v_patch46_runtime_access_review_summary" WITH ("security_invoker"='true') AS
 WITH "register" AS (
         SELECT "v_patch46_runtime_access_review_register"."action_name",
            "v_patch46_runtime_access_review_register"."action_transport",
            "v_patch46_runtime_access_review_register"."module_name",
            "v_patch46_runtime_access_review_register"."risk_level",
            "v_patch46_runtime_access_review_register"."classification",
            "v_patch46_runtime_access_review_register"."classification_review_status",
            "v_patch46_runtime_access_review_register"."required_access_level",
            "v_patch46_runtime_access_review_register"."owner_role",
            "v_patch46_runtime_access_review_register"."direct_browser_exception",
            "v_patch46_runtime_access_review_register"."signoff_id",
            "v_patch46_runtime_access_review_register"."reviewer_role",
            "v_patch46_runtime_access_review_register"."reviewer_user_id",
            "v_patch46_runtime_access_review_register"."signoff_status",
            "v_patch46_runtime_access_review_register"."risk_acceptance_required",
            "v_patch46_runtime_access_review_register"."limitation_summary",
            "v_patch46_runtime_access_review_register"."evidence_reference",
            "v_patch46_runtime_access_review_register"."due_at",
            "v_patch46_runtime_access_review_register"."signed_off_at",
            "v_patch46_runtime_access_review_register"."created_at",
            "v_patch46_runtime_access_review_register"."is_overdue",
            "v_patch46_runtime_access_review_register"."blocker_reason"
           FROM "public"."v_patch46_runtime_access_review_register"
        ), "summary" AS (
         SELECT ("count"(*))::integer AS "total_runtime_actions",
            ("count"(*) FILTER (WHERE ("register"."signoff_status" = 'approved'::"text")))::integer AS "approved_signoffs",
            ("count"(*) FILTER (WHERE ("register"."signoff_status" = 'pending'::"text")))::integer AS "pending_signoffs",
            ("count"(*) FILTER (WHERE (("register"."signoff_status" = 'pending'::"text") AND "register"."is_overdue")))::integer AS "overdue_signoffs",
            ("count"(*) FILTER (WHERE ("register"."signoff_status" = 'rejected'::"text")))::integer AS "rejected_signoffs",
            ("count"(*) FILTER (WHERE ("register"."signoff_status" = 'approved_with_limitation'::"text")))::integer AS "approved_with_limitation_signoffs",
            ("count"(*) FILTER (WHERE "register"."direct_browser_exception"))::integer AS "direct_browser_rpc_exception_count",
            ("count"(*) FILTER (WHERE ("register"."direct_browser_exception" AND ("register"."signoff_status" = 'pending'::"text"))))::integer AS "direct_browser_rpc_exception_pending_count",
            ("count"(*) FILTER (WHERE "register"."risk_acceptance_required"))::integer AS "risk_acceptance_required_count",
            ("count"(*) FILTER (WHERE (("register"."signoff_status" = 'pending'::"text") AND ("register"."risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"])))))::integer AS "pending_high_risk_signoffs",
            ("count"(*) FILTER (WHERE (("register"."blocker_reason" IS NOT NULL) OR ("register"."signoff_status" = ANY (ARRAY['rejected'::"text", 'expired'::"text"])))))::integer AS "blocker_count"
           FROM "register"
        )
 SELECT "total_runtime_actions",
    "approved_signoffs",
    "pending_signoffs",
    "overdue_signoffs",
    "rejected_signoffs",
    "approved_with_limitation_signoffs",
    "direct_browser_rpc_exception_count",
    "direct_browser_rpc_exception_pending_count",
    "risk_acceptance_required_count",
    "pending_high_risk_signoffs",
    "blocker_count",
        CASE
            WHEN ("total_runtime_actions" = 0) THEN 'pending_review'::"text"
            WHEN (("rejected_signoffs" > 0) OR ("overdue_signoffs" > 0)) THEN 'blocked'::"text"
            WHEN (("pending_high_risk_signoffs" > 0) OR ("pending_signoffs" > 0)) THEN 'pending_review'::"text"
            WHEN (("approved_with_limitation_signoffs" > 0) OR ("risk_acceptance_required_count" > 0)) THEN 'ready_with_limitations'::"text"
            ELSE 'ready'::"text"
        END AS "access_review_readiness_status"
   FROM "summary";

CREATE OR REPLACE VIEW "public"."v_patch46_production_readiness_access_review_overlay" WITH ("security_invoker"='true') AS
 SELECT "total_runtime_actions",
    "approved_signoffs",
    "pending_signoffs",
    "overdue_signoffs",
    "rejected_signoffs",
    "approved_with_limitation_signoffs",
    "direct_browser_rpc_exception_count",
    "direct_browser_rpc_exception_pending_count",
    "risk_acceptance_required_count",
    "pending_high_risk_signoffs",
    "blocker_count",
    "access_review_readiness_status",
        CASE
            WHEN ("access_review_readiness_status" = 'ready'::"text") THEN 'Runtime access review signoffs are closed.'::"text"
            WHEN ("access_review_readiness_status" = 'ready_with_limitations'::"text") THEN 'Review approved-with-limitation actions and risk acceptance evidence before production.'::"text"
            WHEN ("access_review_readiness_status" = 'blocked'::"text") THEN 'Resolve rejected or overdue runtime access signoffs before production.'::"text"
            ELSE 'Complete pending runtime access review signoffs, starting with critical and high-risk actions.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch46_runtime_access_review_summary";

