CREATE OR REPLACE VIEW "public"."v_patch47_staging_migration_evidence_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "run_label",
    "run_status",
    "environment_type",
    "migration_count",
    "migrations_replayed",
    "persona_sql_executed",
    "rls_check_passed",
    "function_check_passed",
    "view_check_passed",
    "restore_dryrun_passed",
    "failure_count",
    "evidence_path",
    "run_notes",
    "started_at",
    "completed_at",
    "created_by",
    "created_at",
        CASE
            WHEN (("run_status" = 'passed'::"text") AND "migrations_replayed" AND "persona_sql_executed" AND "rls_check_passed" AND "function_check_passed" AND "view_check_passed" AND "restore_dryrun_passed" AND ("failure_count" = 0)) THEN 'ready'::"text"
            WHEN (("run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) OR ("failure_count" > 0)) THEN 'blocked'::"text"
            ELSE 'evidence_required'::"text"
        END AS "staging_evidence_readiness_status"
   FROM "public"."staging_migration_evidence_runs" "r";

CREATE OR REPLACE VIEW "public"."v_patch47_latest_staging_migration_evidence" WITH ("security_invoker"='true') AS
 SELECT "id",
    "run_label",
