    "migration_count",
    "migrations_replayed",
    "persona_sql_executed",
    "rls_check_passed",
    "function_check_passed",
    "view_check_passed",
    "restore_dryrun_passed",
    "failure_count",
    "evidence_path",
    "run_notes",
    "started_at",
    "completed_at",
    "created_by",
    "created_at",
    "staging_evidence_readiness_status"
   FROM "public"."v_patch47_staging_migration_evidence_register"
  ORDER BY COALESCE("completed_at", "created_at") DESC
 LIMIT 1;

CREATE OR REPLACE VIEW "public"."v_patch47_staging_evidence_summary" WITH ("security_invoker"='true') AS
 WITH "latest" AS (
         SELECT "v_patch47_latest_staging_migration_evidence"."id",
            "v_patch47_latest_staging_migration_evidence"."run_label",
            "v_patch47_latest_staging_migration_evidence"."run_status",
            "v_patch47_latest_staging_migration_evidence"."environment_type",
            "v_patch47_latest_staging_migration_evidence"."migration_count",
            "v_patch47_latest_staging_migration_evidence"."migrations_replayed",
            "v_patch47_latest_staging_migration_evidence"."persona_sql_executed",
            "v_patch47_latest_staging_migration_evidence"."rls_check_passed",
            "v_patch47_latest_staging_migration_evidence"."function_check_passed",
            "v_patch47_latest_staging_migration_evidence"."view_check_passed",
            "v_patch47_latest_staging_migration_evidence"."restore_dryrun_passed",
            "v_patch47_latest_staging_migration_evidence"."failure_count",
            "v_patch47_latest_staging_migration_evidence"."evidence_path",
            "v_patch47_latest_staging_migration_evidence"."run_notes",
            "v_patch47_latest_staging_migration_evidence"."started_at",
            "v_patch47_latest_staging_migration_evidence"."completed_at",
            "v_patch47_latest_staging_migration_evidence"."created_by",
            "v_patch47_latest_staging_migration_evidence"."created_at",
            "v_patch47_latest_staging_migration_evidence"."staging_evidence_readiness_status"
           FROM "public"."v_patch47_latest_staging_migration_evidence"
        ), "counts" AS (
         SELECT ("count"(*))::integer AS "evidence_run_count",
            ("count"(*) FILTER (WHERE ("staging_migration_evidence_runs"."run_status" = 'passed'::"text")))::integer AS "passed_run_count",
            ("count"(*) FILTER (WHERE ("staging_migration_evidence_runs"."run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"]))))::integer AS "blocked_run_count",
            ("count"(*) FILTER (WHERE ("staging_migration_evidence_runs"."run_status" = ANY (ARRAY['pending'::"text", 'running'::"text", 'evidence_required'::"text"]))))::integer AS "evidence_required_run_count"
           FROM "public"."staging_migration_evidence_runs"
        )
 SELECT "c"."evidence_run_count",
    "c"."passed_run_count",
    "c"."blocked_run_count",
    "c"."evidence_required_run_count",
    "l"."id" AS "latest_run_id",
    "l"."run_label" AS "latest_run_label",
    COALESCE("l"."environment_type", 'local_clean'::"text") AS "latest_environment_type",
    COALESCE("l"."run_status", 'evidence_required'::"text") AS "latest_run_status",
    COALESCE("l"."migration_count", 0) AS "latest_migration_count",
    COALESCE("l"."migrations_replayed", false) AS "migrations_replayed",
    COALESCE("l"."persona_sql_executed", false) AS "persona_sql_executed",
    COALESCE("l"."rls_check_passed", false) AS "rls_check_passed",
    COALESCE("l"."function_check_passed", false) AS "function_check_passed",
    COALESCE("l"."view_check_passed", false) AS "view_check_passed",
    COALESCE("l"."restore_dryrun_passed", false) AS "restore_dryrun_passed",
    COALESCE("l"."failure_count", 0) AS "failure_count",
    "l"."evidence_path",
    "l"."run_notes",
    "l"."completed_at",
        CASE
            WHEN ("l"."staging_evidence_readiness_status" = 'ready'::"text") THEN 'ready'::"text"
            WHEN ((COALESCE("l"."run_status", 'evidence_required'::"text") = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) OR (COALESCE("l"."failure_count", 0) > 0)) THEN 'blocked'::"text"
            ELSE 'evidence_required'::"text"
        END AS "staging_evidence_readiness_status"
   FROM ("counts" "c"
     LEFT JOIN "latest" "l" ON (true));

CREATE OR REPLACE VIEW "public"."v_patch47_production_readiness_staging_overlay" WITH ("security_invoker"='true') AS
 SELECT "evidence_run_count",
    "passed_run_count",
    "blocked_run_count",
    "evidence_required_run_count",
    "latest_run_id",
    "latest_run_label",
    "latest_environment_type",
    "latest_run_status",
    "latest_migration_count",
    "migrations_replayed",
    "persona_sql_executed",
    "rls_check_passed",
    "function_check_passed",
    "view_check_passed",
    "restore_dryrun_passed",
    "failure_count",
    "evidence_path",
    "run_notes",
    "completed_at",
    "staging_evidence_readiness_status",
        CASE
            WHEN ("staging_evidence_readiness_status" = 'ready'::"text") THEN 'Staging migration replay and persona SQL evidence are complete.'::"text"
            WHEN ("staging_evidence_readiness_status" = 'blocked'::"text") THEN 'Resolve failed or blocked staging evidence run before production readiness signoff.'::"text"
            ELSE 'Run local-clean or staging migration/persona SQL evidence capture before production readiness signoff.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch47_staging_evidence_summary";

CREATE OR REPLACE VIEW "public"."v_patch47_staging_persona_sql_evidence" WITH ("security_invoker"='true') AS
 SELECT "id",
    "run_label",
    "environment_type",
    "run_status",
    "persona_sql_executed",
    "evidence_path",
    "run_notes",
    "completed_at",
        CASE
            WHEN ("persona_sql_executed" AND ("run_status" = 'passed'::"text")) THEN 'ready'::"text"
            WHEN ("run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) THEN 'blocked'::"text"
            ELSE 'evidence_required'::"text"
        END AS "persona_sql_status"
   FROM "public"."staging_migration_evidence_runs";

CREATE OR REPLACE VIEW "public"."v_patch47_staging_security_blockers" WITH ("security_invoker"='true') AS
 SELECT "id",
    "run_label",
    "environment_type",
    "run_status",
    "failure_count",
    "evidence_path",
    "run_notes",
    "created_at",
        CASE
            WHEN (NOT "migrations_replayed") THEN 'migration replay evidence required'::"text"
            WHEN (NOT "persona_sql_executed") THEN 'persona SQL execution evidence required'::"text"
            WHEN (NOT "rls_check_passed") THEN 'RLS strict proof evidence required'::"text"
            WHEN (NOT "function_check_passed") THEN 'function grant proof evidence required'::"text"
            WHEN (NOT "view_check_passed") THEN 'view security proof evidence required'::"text"
            WHEN (NOT "restore_dryrun_passed") THEN 'restore dry-run evidence required'::"text"
            WHEN ("failure_count" > 0) THEN 'staging evidence run contains failures'::"text"
            WHEN ("run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) THEN 'staging evidence run blocked or failed'::"text"
            ELSE NULL::"text"
        END AS "blocker_reason"
   FROM "public"."staging_migration_evidence_runs"
  WHERE (("run_status" <> 'passed'::"text") OR ("failure_count" > 0) OR (NOT "migrations_replayed") OR (NOT "persona_sql_executed") OR (NOT "rls_check_passed") OR (NOT "function_check_passed") OR (NOT "view_check_passed") OR (NOT "restore_dryrun_passed"));

CREATE OR REPLACE VIEW "public"."v_patch49_controlled_pilot_activation_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "run_label",
    "pilot_scope",
    "activation_status",
    "target_start_date",
    "target_end_date",
    "executive_sponsor_user_id",
    "readiness_summary",
    "limitation_summary",
    "created_by",
    "created_at",
    "updated_at",
        CASE
            WHEN ("activation_status" = ANY (ARRAY['approved'::"text", 'completed'::"text"])) THEN 'ready'::"text"
            WHEN ("activation_status" = 'approved_with_limitations'::"text") THEN 'ready_with_limitations'::"text"
            WHEN ("activation_status" = 'blocked'::"text") THEN 'blocked'::"text"
            WHEN ("activation_status" = ANY (ARRAY['planning'::"text", 'ready_for_review'::"text", 'paused'::"text"])) THEN 'planning'::"text"
            ELSE 'evidence_required'::"text"
        END AS "pilot_readiness_status"
   FROM "public"."controlled_pilot_activation_runs" "r";

CREATE OR REPLACE VIEW "public"."v_patch49_department_pilot_readiness_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "department_id",
    "department_name",
    "owner_user_id",
    "pilot_status",
    "required_participant_count",
    "confirmed_participant_count",
    "missing_owner_reason",
    "limitation_summary",
    "created_by",
    "created_at",
    ("owner_user_id" IS NULL) AS "missing_owner",
    GREATEST(("required_participant_count" - "confirmed_participant_count"), 0) AS "participant_gap",
        CASE
            WHEN ("pilot_status" = 'blocked'::"text") THEN 'department pilot area blocked'::"text"
            WHEN ("owner_user_id" IS NULL) THEN COALESCE(NULLIF("missing_owner_reason", ''::"text"), 'department owner required'::"text")
            WHEN ("required_participant_count" > "confirmed_participant_count") THEN 'participant coverage incomplete'::"text"
            WHEN ("pilot_status" = 'pending'::"text") THEN 'department readiness signoff pending'::"text"
            ELSE NULL::"text"
        END AS "readiness_blocker_reason"
   FROM "public"."controlled_pilot_departments" "d";

CREATE OR REPLACE VIEW "public"."v_patch49_department_signoff_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "department_pilot_id",
    "department_name",
    "signoff_role",
    "signoff_status",
    "signer_user_id",
    "due_at",
    "signed_off_at",
    "evidence_reference",
    "limitation_summary",
    "rejection_reason",
    "created_by",
    "created_at",
    (("signoff_status" = 'pending'::"text") AND ("due_at" IS NOT NULL) AND ("due_at" < "now"())) AS "is_overdue",
        CASE
            WHEN ("signoff_status" = 'rejected'::"text") THEN COALESCE(NULLIF("rejection_reason", ''::"text"), 'department signoff rejected'::"text")
            WHEN (("signoff_status" = 'pending'::"text") AND ("due_at" IS NOT NULL) AND ("due_at" < "now"())) THEN 'department signoff overdue'::"text"
            WHEN ("signoff_status" = 'pending'::"text") THEN 'department signoff pending'::"text"
            WHEN (("signoff_status" = 'approved_with_limitation'::"text") AND (NULLIF("limitation_summary", ''::"text") IS NULL)) THEN 'limitation summary required'::"text"
            WHEN (("signoff_status" = ANY (ARRAY['approved'::"text", 'approved_with_limitation'::"text"])) AND (NULLIF("evidence_reference", ''::"text") IS NULL)) THEN 'signoff evidence required'::"text"
            ELSE NULL::"text"
        END AS "signoff_blocker_reason"
   FROM "public"."controlled_pilot_department_signoffs" "s";

CREATE OR REPLACE VIEW "public"."v_patch49_pilot_participant_coverage" WITH ("security_invoker"='true') AS
 SELECT "p"."activation_run_id",
    "p"."department_pilot_id",
    COALESCE("d"."department_name", 'Unassigned department'::"text") AS "department_name",
    ("count"(*))::integer AS "participant_count",
    ("count"(*) FILTER (WHERE ("p"."participation_status" = 'confirmed'::"text")))::integer AS "confirmed_participant_count",
    ("count"(*) FILTER (WHERE ("p"."participation_status" = ANY (ARRAY['pending'::"text", 'needs_training'::"text"]))))::integer AS "pending_participant_count",
    ("count"(*) FILTER (WHERE ("p"."training_required" AND (NOT "p"."training_confirmed"))))::integer AS "training_required_count",
    ("count"(*) FILTER (WHERE ("p"."participation_status" = ANY (ARRAY['declined'::"text", 'inactive'::"text"]))))::integer AS "unavailable_participant_count"
   FROM ("public"."controlled_pilot_participants" "p"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "p"."department_pilot_id")))
  GROUP BY "p"."activation_run_id", "p"."department_pilot_id", COALESCE("d"."department_name", 'Unassigned department'::"text");

CREATE OR REPLACE VIEW "public"."v_patch49_controlled_pilot_blockers" WITH ("security_invoker"='true') AS
 SELECT "v_patch49_department_pilot_readiness_register"."activation_run_id",
    "v_patch49_department_pilot_readiness_register"."department_name",
    'missing_owner'::"text" AS "blocker_type",
    "v_patch49_department_pilot_readiness_register"."readiness_blocker_reason" AS "blocker_reason",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch49_department_pilot_readiness_register"
  WHERE ("v_patch49_department_pilot_readiness_register"."missing_owner" AND ("v_patch49_department_pilot_readiness_register"."pilot_status" <> 'not_in_scope'::"text"))
UNION ALL
 SELECT "v_patch49_department_pilot_readiness_register"."activation_run_id",
    "v_patch49_department_pilot_readiness_register"."department_name",
    'department_blocked'::"text" AS "blocker_type",
    "v_patch49_department_pilot_readiness_register"."readiness_blocker_reason" AS "blocker_reason",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch49_department_pilot_readiness_register"
  WHERE ("v_patch49_department_pilot_readiness_register"."pilot_status" = 'blocked'::"text")
UNION ALL
 SELECT "v_patch49_department_signoff_register"."activation_run_id",
    "v_patch49_department_signoff_register"."department_name",
    'signoff_required'::"text" AS "blocker_type",
    "v_patch49_department_signoff_register"."signoff_blocker_reason" AS "blocker_reason",
    "v_patch49_department_signoff_register"."evidence_reference"
   FROM "public"."v_patch49_department_signoff_register"
  WHERE ("v_patch49_department_signoff_register"."signoff_blocker_reason" IS NOT NULL)
UNION ALL
 SELECT "v_patch49_pilot_participant_coverage"."activation_run_id",
    "v_patch49_pilot_participant_coverage"."department_name",
    'participant_training'::"text" AS "blocker_type",
    'participant training confirmation required'::"text" AS "blocker_reason",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch49_pilot_participant_coverage"
  WHERE ("v_patch49_pilot_participant_coverage"."training_required_count" > 0);

CREATE OR REPLACE VIEW "public"."v_patch49_controlled_pilot_go_no_go_summary" WITH ("security_invoker"='true') AS
 WITH "latest" AS (
         SELECT "controlled_pilot_activation_runs"."id",
            "controlled_pilot_activation_runs"."run_label",
            "controlled_pilot_activation_runs"."pilot_scope",
            "controlled_pilot_activation_runs"."activation_status",
            "controlled_pilot_activation_runs"."target_start_date",
            "controlled_pilot_activation_runs"."target_end_date",
            "controlled_pilot_activation_runs"."executive_sponsor_user_id",
            "controlled_pilot_activation_runs"."readiness_summary",
            "controlled_pilot_activation_runs"."limitation_summary",
            "controlled_pilot_activation_runs"."created_by",
            "controlled_pilot_activation_runs"."created_at",
            "controlled_pilot_activation_runs"."updated_at"
           FROM "public"."controlled_pilot_activation_runs"
          ORDER BY "controlled_pilot_activation_runs"."updated_at" DESC, "controlled_pilot_activation_runs"."created_at" DESC
         LIMIT 1
        ), "dept" AS (
         SELECT ("count"(*))::integer AS "departments_in_scope",
            ("count"(*) FILTER (WHERE ("controlled_pilot_departments"."pilot_status" = ANY (ARRAY['ready'::"text", 'ready_with_limitations'::"text"]))))::integer AS "departments_ready",
            ("count"(*) FILTER (WHERE ("controlled_pilot_departments"."pilot_status" = 'blocked'::"text")))::integer AS "departments_blocked",
            ("count"(*) FILTER (WHERE (("controlled_pilot_departments"."owner_user_id" IS NULL) AND ("controlled_pilot_departments"."pilot_status" <> 'not_in_scope'::"text"))))::integer AS "missing_department_owners"
           FROM "public"."controlled_pilot_departments"
          WHERE (("controlled_pilot_departments"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest")) AND ("controlled_pilot_departments"."pilot_status" <> 'not_in_scope'::"text"))
        ), "signoffs" AS (
         SELECT ("count"(*) FILTER (WHERE ("controlled_pilot_department_signoffs"."signoff_status" = 'pending'::"text")))::integer AS "pending_signoffs",
            ("count"(*) FILTER (WHERE (("controlled_pilot_department_signoffs"."signoff_status" = 'overdue'::"text") OR (("controlled_pilot_department_signoffs"."signoff_status" = 'pending'::"text") AND ("controlled_pilot_department_signoffs"."due_at" IS NOT NULL) AND ("controlled_pilot_department_signoffs"."due_at" < "now"())))))::integer AS "overdue_signoffs",
            ("count"(*) FILTER (WHERE ("controlled_pilot_department_signoffs"."signoff_status" = 'rejected'::"text")))::integer AS "rejected_signoffs",
            ("count"(*) FILTER (WHERE ("controlled_pilot_department_signoffs"."signoff_status" = 'approved_with_limitation'::"text")))::integer AS "approved_with_limitation_signoffs"
           FROM "public"."controlled_pilot_department_signoffs"
          WHERE ("controlled_pilot_department_signoffs"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        ), "participants" AS (
         SELECT ("count"(*))::integer AS "participant_count",
            ("count"(*) FILTER (WHERE ("controlled_pilot_participants"."participation_status" = 'confirmed'::"text")))::integer AS "confirmed_participants",
            ("count"(*) FILTER (WHERE ("controlled_pilot_participants"."training_required" AND (NOT "controlled_pilot_participants"."training_confirmed"))))::integer AS "training_required_participants"
           FROM "public"."controlled_pilot_participants"
          WHERE ("controlled_pilot_participants"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        ), "blockers" AS (
         SELECT ("count"(*))::integer AS "blocker_count"
           FROM "public"."v_patch49_controlled_pilot_blockers"
          WHERE ("v_patch49_controlled_pilot_blockers"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        )
 SELECT ( SELECT "latest"."id"
           FROM "latest") AS "activation_run_id",
    COALESCE(( SELECT "latest"."run_label"
           FROM "latest"), 'No controlled pilot activation run recorded'::"text") AS "run_label",
    COALESCE(( SELECT "latest"."activation_status"
           FROM "latest"), 'planning'::"text") AS "activation_status",
    COALESCE(( SELECT "latest"."pilot_scope"
           FROM "latest"), 'controlled_internal_pilot'::"text") AS "pilot_scope",
    COALESCE(( SELECT "dept"."departments_in_scope"
           FROM "dept"), 0) AS "departments_in_scope",
    COALESCE(( SELECT "dept"."departments_ready"
           FROM "dept"), 0) AS "departments_ready",
    COALESCE(( SELECT "dept"."departments_blocked"
           FROM "dept"), 0) AS "departments_blocked",
    COALESCE(( SELECT "dept"."missing_department_owners"
           FROM "dept"), 0) AS "missing_department_owners",
    COALESCE(( SELECT "signoffs"."pending_signoffs"
           FROM "signoffs"), 0) AS "pending_signoffs",
    COALESCE(( SELECT "signoffs"."overdue_signoffs"
           FROM "signoffs"), 0) AS "overdue_signoffs",
    COALESCE(( SELECT "signoffs"."rejected_signoffs"
           FROM "signoffs"), 0) AS "rejected_signoffs",
    COALESCE(( SELECT "signoffs"."approved_with_limitation_signoffs"
           FROM "signoffs"), 0) AS "approved_with_limitation_signoffs",
    COALESCE(( SELECT "participants"."participant_count"
           FROM "participants"), 0) AS "participant_count",
    COALESCE(( SELECT "participants"."confirmed_participants"
           FROM "participants"), 0) AS "confirmed_participants",
    COALESCE(( SELECT "participants"."training_required_participants"
           FROM "participants"), 0) AS "training_required_participants",
    COALESCE(( SELECT "blockers"."blocker_count"
           FROM "blockers"), 0) AS "blocker_count",
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "latest"))) THEN 'evidence_required'::"text"
            WHEN ((COALESCE(( SELECT "blockers"."blocker_count"
               FROM "blockers"), 0) > 0) OR (COALESCE(( SELECT "dept"."departments_blocked"
               FROM "dept"), 0) > 0) OR (COALESCE(( SELECT "signoffs"."rejected_signoffs"
               FROM "signoffs"), 0) > 0) OR (COALESCE(( SELECT "signoffs"."overdue_signoffs"
               FROM "signoffs"), 0) > 0)) THEN 'blocked'::"text"
            WHEN ((COALESCE(( SELECT "signoffs"."pending_signoffs"
               FROM "signoffs"), 0) > 0) OR (COALESCE(( SELECT "dept"."missing_department_owners"
               FROM "dept"), 0) > 0) OR (( SELECT "latest"."activation_status"
               FROM "latest") = ANY (ARRAY['planning'::"text", 'ready_for_review'::"text", 'paused'::"text"]))) THEN 'planning'::"text"
            WHEN ((COALESCE(( SELECT "signoffs"."approved_with_limitation_signoffs"
               FROM "signoffs"), 0) > 0) OR (( SELECT "latest"."activation_status"
               FROM "latest") = 'approved_with_limitations'::"text")) THEN 'ready_with_limitations'::"text"
            WHEN (( SELECT "latest"."activation_status"
               FROM "latest") = ANY (ARRAY['approved'::"text", 'completed'::"text"])) THEN 'ready'::"text"
            ELSE 'evidence_required'::"text"
        END AS "pilot_readiness_status";

CREATE OR REPLACE VIEW "public"."v_patch49_missing_department_owner_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "department_id",
    "department_name",
    "owner_user_id",
    "pilot_status",
    "required_participant_count",
    "confirmed_participant_count",
    "missing_owner_reason",
    "limitation_summary",
    "created_by",
    "created_at",
    "missing_owner",
    "participant_gap",
    "readiness_blocker_reason"
   FROM "public"."v_patch49_department_pilot_readiness_register"
  WHERE ("missing_owner" AND ("pilot_status" <> 'not_in_scope'::"text"));

CREATE OR REPLACE VIEW "public"."v_patch49_overdue_department_signoff_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "department_pilot_id",
    "department_name",
    "signoff_role",
    "signoff_status",
    "signer_user_id",
    "due_at",
    "signed_off_at",
    "evidence_reference",
    "limitation_summary",
    "rejection_reason",
    "created_by",
    "created_at",
    "is_overdue",
    "signoff_blocker_reason"
   FROM "public"."v_patch49_department_signoff_register"
  WHERE (("signoff_status" = 'overdue'::"text") OR "is_overdue");

CREATE OR REPLACE VIEW "public"."v_patch49_production_readiness_pilot_activation_overlay" WITH ("security_invoker"='true') AS
 SELECT "activation_run_id",
    "run_label",
    "activation_status",
    "pilot_scope",
    "departments_in_scope",
    "departments_ready",
    "departments_blocked",
    "missing_department_owners",
    "pending_signoffs",
    "overdue_signoffs",
    "rejected_signoffs",
    "approved_with_limitation_signoffs",
    "participant_count",
    "confirmed_participants",
    "training_required_participants",
    "blocker_count",
    "pilot_readiness_status",
        CASE
            WHEN ("pilot_readiness_status" = 'ready'::"text") THEN 'Controlled pilot can proceed within approved scope.'::"text"
            WHEN ("pilot_readiness_status" = 'ready_with_limitations'::"text") THEN 'Controlled pilot can proceed only with documented limitations and monitoring.'::"text"
            WHEN ("pilot_readiness_status" = 'blocked'::"text") THEN 'Resolve blocked departments, rejected signoffs, or overdue approvals before pilot launch.'::"text"
            WHEN ("pilot_readiness_status" = 'planning'::"text") THEN 'Complete department owners, participant coverage, and readiness signoffs.'::"text"
            ELSE 'Create a controlled pilot activation run and collect department readiness evidence.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch49_controlled_pilot_go_no_go_summary";

CREATE OR REPLACE VIEW "public"."v_patch4_audit_engagement_dashboard" WITH ("security_invoker"='true') AS
 SELECT "e"."organization_id",
    "e"."engagement_code",
    "e"."title",
    "e"."engagement_type",
    "e"."engagement_status",
    "e"."lead_auditor_name",
    "e"."target_report_date",
    ("count"(DISTINCT "f"."id"))::integer AS "finding_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))))::integer AS "open_finding_count",
    ("count"(DISTINCT "wp"."id"))::integer AS "workpaper_count",
    ("count"(DISTINCT "er"."id"))::integer AS "evidence_request_count"
   FROM ((("public"."patch4_audit_engagements" "e"
     LEFT JOIN "public"."patch4_audit_findings" "f" ON (("f"."engagement_id" = "e"."id")))
     LEFT JOIN "public"."patch4_audit_workpapers" "wp" ON (("wp"."engagement_id" = "e"."id")))
     LEFT JOIN "public"."patch4_audit_evidence_requests" "er" ON (("er"."engagement_id" = "e"."id")))
  GROUP BY "e"."organization_id", "e"."engagement_code", "e"."title", "e"."engagement_type", "e"."engagement_status", "e"."lead_auditor_name", "e"."target_report_date";

CREATE OR REPLACE VIEW "public"."v_patch4_audit_evidence_governance_summary" WITH ("security_invoker"='true') AS
 WITH "orgs" AS (
         SELECT "patch4_audit_engagements"."organization_id"
           FROM "public"."patch4_audit_engagements"
        UNION
         SELECT "patch4_audit_findings"."organization_id"
           FROM "public"."patch4_audit_findings"
        UNION
         SELECT "patch4_evidence_versions"."organization_id"
           FROM "public"."patch4_evidence_versions"
        UNION
         SELECT "patch4_production_governance_gates"."organization_id"
           FROM "public"."patch4_production_governance_gates"
        UNION
         SELECT "patch4_immutable_audit_events"."organization_id"
           FROM "public"."patch4_immutable_audit_events"
        )
 SELECT "organization_id",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_audit_engagements" "e"
          WHERE ("e"."organization_id" = "orgs"."organization_id")), (0)::bigint))::integer AS "engagement_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_audit_findings" "f"
          WHERE (("f"."organization_id" = "orgs"."organization_id") AND ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"])))), (0)::bigint))::integer AS "open_finding_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_evidence_versions" "ev"
          WHERE ("ev"."organization_id" = "orgs"."organization_id")), (0)::bigint))::integer AS "evidence_version_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_evidence_integrity_hashes" "ih"
          WHERE (("ih"."organization_id" = "orgs"."organization_id") AND ("ih"."integrity_status" = 'verified'::"text"))), (0)::bigint))::integer AS "verified_hash_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_immutable_audit_events" "ae"
          WHERE ("ae"."organization_id" = "orgs"."organization_id")), (0)::bigint))::integer AS "immutable_event_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_external_auditor_access_sessions" "s"
          WHERE (("s"."organization_id" = "orgs"."organization_id") AND ("s"."access_status" = ANY (ARRAY['approved'::"text", 'active'::"text"])))), (0)::bigint))::integer AS "active_auditor_session_count",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."patch4_production_governance_gates" "g"
          WHERE (("g"."organization_id" = "orgs"."organization_id") AND "g"."is_critical" AND ("g"."gate_status" <> 'approved'::"text"))), (0)::bigint))::integer AS "critical_gate_not_approved_count"
   FROM "orgs";

COMMENT ON VIEW "public"."v_patch4_audit_evidence_governance_summary" IS 'Patch 4 executive summary for audit, evidence integrity, external auditor access, and production governance.';

CREATE OR REPLACE VIEW "public"."v_patch4_evidence_integrity_index" WITH ("security_invoker"='true') AS
 SELECT "ev"."organization_id",
    "ev"."source_type",
    "ev"."evidence_code",
    "ev"."evidence_title",
    "ev"."version_no",
    "ev"."version_status",
    "ih"."hash_algorithm",
    "ih"."integrity_status",
    "ih"."verified_at",
    "ih"."chain_hash",
    ("count"("ae"."id"))::integer AS "related_event_count"
   FROM (("public"."patch4_evidence_versions" "ev"
     LEFT JOIN "public"."patch4_evidence_integrity_hashes" "ih" ON (("ih"."evidence_version_id" = "ev"."id")))
     LEFT JOIN "public"."patch4_immutable_audit_events" "ae" ON ((("ae"."source_type" = 'evidence_version'::"text") AND ("ae"."source_id" = "ev"."id"))))
  GROUP BY "ev"."organization_id", "ev"."source_type", "ev"."evidence_code", "ev"."evidence_title", "ev"."version_no", "ev"."version_status", "ih"."hash_algorithm", "ih"."integrity_status", "ih"."verified_at", "ih"."chain_hash";

CREATE OR REPLACE VIEW "public"."v_patch4_production_governance_gate_dashboard" WITH ("security_invoker"='true') AS
 SELECT "g"."organization_id",
    "g"."gate_code",
    "g"."gate_name",
    "g"."gate_area",
    "g"."is_critical",
    "g"."gate_status",
    "g"."owner_name",
    "g"."due_date",
    ("count"("ge"."id"))::integer AS "evidence_item_count",
    ("count"("ge"."id") FILTER (WHERE ("ge"."evidence_status" = 'accepted'::"text")))::integer AS "accepted_evidence_count"
   FROM ("public"."patch4_production_governance_gates" "g"
     LEFT JOIN "public"."patch4_production_gate_evidence" "ge" ON (("ge"."gate_id" = "g"."id")))
  GROUP BY "g"."organization_id", "g"."gate_code", "g"."gate_name", "g"."gate_area", "g"."is_critical", "g"."gate_status", "g"."owner_name", "g"."due_date";

CREATE OR REPLACE VIEW "public"."v_patch50_department_setup_checklist_register" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."activation_run_id",
    "c"."department_pilot_id",
    "c"."checklist_area",
    "c"."item_label",
    "c"."item_status",
    "c"."owner_user_id",
    "c"."due_at",
    "c"."evidence_reference",
    "c"."issue_summary",
    "c"."created_by",
    "c"."created_at",
    "c"."updated_at",
    "d"."department_name",
    "d"."owner_user_id" AS "department_owner_user_id",
    (("c"."item_status" = 'pending'::"text") AND ("c"."due_at" IS NOT NULL) AND ("c"."due_at" < "now"())) AS "is_overdue",
        CASE
            WHEN ("c"."item_status" = 'blocked'::"text") THEN COALESCE(NULLIF("c"."issue_summary", ''::"text"), 'setup item blocked'::"text")
            WHEN ("c"."item_status" = 'evidence_required'::"text") THEN COALESCE(NULLIF("c"."issue_summary", ''::"text"), 'setup evidence required'::"text")
            WHEN (("c"."owner_user_id" IS NULL) AND ("c"."item_status" <> ALL (ARRAY['ready'::"text", 'not_applicable'::"text"]))) THEN 'setup item owner required'::"text"
            WHEN ("c"."item_status" = 'pending'::"text") THEN 'setup item pending'::"text"
            ELSE NULL::"text"
        END AS "checklist_gap_reason"
   FROM ("public"."real_pilot_setup_checklist_items" "c"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "c"."department_pilot_id")));

CREATE OR REPLACE VIEW "public"."v_patch50_pilot_participant_setup_gap_register" WITH ("security_invoker"='true') AS
 SELECT "p"."activation_run_id",
    "p"."department_pilot_id",
    "p"."id" AS "participant_id",
    COALESCE("d"."department_name", 'Unassigned department'::"text") AS "department_name",
    "p"."display_name",
    "p"."participant_role",
    "p"."participation_status",
    "p"."training_required",
    "p"."training_confirmed",
        CASE
            WHEN ("p"."participation_status" = ANY (ARRAY['declined'::"text", 'inactive'::"text"])) THEN 'inactive_or_unknown_user'::"text"
            WHEN ("p"."participation_status" = 'needs_training'::"text") THEN 'training_not_confirmed'::"text"
            WHEN ("p"."participation_status" = 'pending'::"text") THEN 'participant_not_confirmed'::"text"
            ELSE 'participant_not_confirmed'::"text"
        END AS "gap_type",
        CASE
            WHEN ("p"."participation_status" = ANY (ARRAY['declined'::"text", 'inactive'::"text"])) THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "severity",
        CASE
            WHEN ("p"."participation_status" = ANY (ARRAY['declined'::"text", 'inactive'::"text"])) THEN 'Pilot participant is unavailable or inactive.'::"text"
            WHEN ("p"."participation_status" = 'needs_training'::"text") THEN 'Pilot participant requires training confirmation.'::"text"
            ELSE 'Pilot participant confirmation is pending.'::"text"
        END AS "gap_summary"
   FROM ("public"."controlled_pilot_participants" "p"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "p"."department_pilot_id")))
  WHERE ("p"."participation_status" = ANY (ARRAY['pending'::"text", 'declined'::"text", 'inactive'::"text", 'needs_training'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch50_inactive_or_unconfirmed_participant_register" WITH ("security_invoker"='true') AS
 SELECT "activation_run_id",
    "department_pilot_id",
    "participant_id",
    "department_name",
    "display_name",
    "participant_role",
    "participation_status",
    "training_required",
    "training_confirmed",
    "gap_type",
    "severity",
    "gap_summary"
   FROM "public"."v_patch50_pilot_participant_setup_gap_register"
  WHERE ("participation_status" = ANY (ARRAY['pending'::"text", 'declined'::"text", 'inactive'::"text", 'needs_training'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch50_missing_department_owner_register" WITH ("security_invoker"='true') AS
 SELECT "activation_run_id",
    "id" AS "department_pilot_id",
    "department_name",
    'missing_department_owner'::"text" AS "gap_type",
    'high'::"text" AS "severity",
    COALESCE(NULLIF("missing_owner_reason", ''::"text"), 'Department owner must be assigned before pilot launch.'::"text") AS "gap_summary"
   FROM "public"."controlled_pilot_departments" "d"
  WHERE (("owner_user_id" IS NULL) AND ("pilot_status" <> 'not_in_scope'::"text"));

CREATE OR REPLACE VIEW "public"."v_patch50_pilot_role_assignment_gap_register" WITH ("security_invoker"='true') AS
 SELECT "p"."activation_run_id",
    "p"."department_pilot_id",
    "p"."id" AS "participant_id",
    COALESCE("d"."department_name", 'Unassigned department'::"text") AS "department_name",
    "p"."display_name",
    "p"."participant_role",
    'missing_participant_role'::"text" AS "gap_type",
    'medium'::"text" AS "severity",
    'Pilot participant role assignment requires review.'::"text" AS "gap_summary"
   FROM ("public"."controlled_pilot_participants" "p"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "p"."department_pilot_id")))
  WHERE (NULLIF("p"."participant_role", ''::"text") IS NULL);

CREATE OR REPLACE VIEW "public"."v_patch50_pilot_signoff_assignment_gap_register" WITH ("security_invoker"='true') AS
 SELECT "activation_run_id",
    "department_pilot_id",
    "id" AS "signoff_id",
    "department_name",
    "signoff_role",
    "signoff_status",
    "signer_user_id",
    "due_at",
        CASE
            WHEN (("signer_user_id" IS NULL) AND ("signoff_status" <> 'not_required'::"text")) THEN 'signoff_owner_missing'::"text"
            WHEN (("signoff_status" = 'overdue'::"text") OR (("signoff_status" = 'pending'::"text") AND ("due_at" IS NOT NULL) AND ("due_at" < "now"()))) THEN 'signoff_overdue'::"text"
            ELSE 'signoff_pending'::"text"
        END AS "gap_type",
        CASE
            WHEN (("signoff_status" = 'overdue'::"text") OR (("signoff_status" = 'pending'::"text") AND ("due_at" IS NOT NULL) AND ("due_at" < "now"()))) THEN 'high'::"text"
            ELSE 'medium'::"text"
        END AS "severity",
        CASE
            WHEN (("signer_user_id" IS NULL) AND ("signoff_status" <> 'not_required'::"text")) THEN 'Department signoff owner is missing.'::"text"
            WHEN (("signoff_status" = 'overdue'::"text") OR (("signoff_status" = 'pending'::"text") AND ("due_at" IS NOT NULL) AND ("due_at" < "now"()))) THEN 'Department signoff is overdue.'::"text"
            ELSE 'Department signoff is pending.'::"text"
        END AS "gap_summary"
   FROM "public"."controlled_pilot_department_signoffs" "s"
  WHERE (("signoff_status" = ANY (ARRAY['pending'::"text", 'overdue'::"text"])) OR (("signer_user_id" IS NULL) AND ("signoff_status" <> 'not_required'::"text")));

CREATE OR REPLACE VIEW "public"."v_patch50_pilot_training_gap_register" WITH ("security_invoker"='true') AS
 SELECT "p"."activation_run_id",
    "p"."department_pilot_id",
    "p"."id" AS "participant_id",
    COALESCE("d"."department_name", 'Unassigned department'::"text") AS "department_name",
    "p"."display_name",
    "p"."participant_role",
    'training_not_confirmed'::"text" AS "gap_type",
    'medium'::"text" AS "severity",
    'Required pilot training is not confirmed.'::"text" AS "gap_summary"
   FROM ("public"."controlled_pilot_participants" "p"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "p"."department_pilot_id")))
  WHERE (("p"."training_required" = true) AND ("p"."training_confirmed" = false));

CREATE OR REPLACE VIEW "public"."v_patch50_real_pilot_master_data_exception_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."activation_run_id",
    "e"."department_pilot_id",
    "e"."participant_id",
    "e"."exception_type",
    "e"."severity",
    "e"."exception_status",
    "e"."exception_summary",
    "e"."assigned_to",
    "e"."evidence_reference",
    "e"."resolution_summary",
    "e"."created_by",
    "e"."created_at",
    "e"."updated_at",
    "d"."department_name",
    "p"."display_name" AS "participant_name",
    (("e"."exception_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("e"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"]))) AS "is_launch_blocker"
   FROM (("public"."real_pilot_master_data_exceptions" "e"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "e"."department_pilot_id")))
     LEFT JOIN "public"."controlled_pilot_participants" "p" ON (("p"."id" = "e"."participant_id")));

CREATE OR REPLACE VIEW "public"."v_patch50_real_pilot_launch_blocker_register" WITH ("security_invoker"='true') AS
 SELECT "v_patch50_missing_department_owner_register"."activation_run_id",
    "v_patch50_missing_department_owner_register"."department_pilot_id",
    NULL::"uuid" AS "participant_id",
    "v_patch50_missing_department_owner_register"."department_name",
    "v_patch50_missing_department_owner_register"."gap_type" AS "blocker_type",
    "v_patch50_missing_department_owner_register"."severity",
    "v_patch50_missing_department_owner_register"."gap_summary" AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch50_missing_department_owner_register"
UNION ALL
 SELECT "v_patch49_department_pilot_readiness_register"."activation_run_id",
    "v_patch49_department_pilot_readiness_register"."id" AS "department_pilot_id",
    NULL::"uuid" AS "participant_id",
    "v_patch49_department_pilot_readiness_register"."department_name",
    'department_blocked'::"text" AS "blocker_type",
