    COALESCE(NULLIF("v_patch49_department_pilot_readiness_register"."readiness_blocker_reason", ''::"text"), 'Department is blocked for pilot launch.'::"text") AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch49_department_pilot_readiness_register"
  WHERE ("v_patch49_department_pilot_readiness_register"."pilot_status" = 'blocked'::"text")
UNION ALL
 SELECT "v_patch50_pilot_participant_setup_gap_register"."activation_run_id",
