    "v_patch50_pilot_participant_setup_gap_register"."participant_id",
    "v_patch50_pilot_participant_setup_gap_register"."department_name",
    "v_patch50_pilot_participant_setup_gap_register"."gap_type" AS "blocker_type",
    "v_patch50_pilot_participant_setup_gap_register"."severity",
    "v_patch50_pilot_participant_setup_gap_register"."gap_summary" AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch50_pilot_participant_setup_gap_register"
UNION ALL
 SELECT "v_patch50_pilot_role_assignment_gap_register"."activation_run_id",
    "v_patch50_pilot_role_assignment_gap_register"."department_pilot_id",
    "v_patch50_pilot_role_assignment_gap_register"."participant_id",
    "v_patch50_pilot_role_assignment_gap_register"."department_name",
    "v_patch50_pilot_role_assignment_gap_register"."gap_type" AS "blocker_type",
    "v_patch50_pilot_role_assignment_gap_register"."severity",
    "v_patch50_pilot_role_assignment_gap_register"."gap_summary" AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch50_pilot_role_assignment_gap_register"
UNION ALL
 SELECT "v_patch50_pilot_training_gap_register"."activation_run_id",
    "v_patch50_pilot_training_gap_register"."department_pilot_id",
    "v_patch50_pilot_training_gap_register"."participant_id",
    "v_patch50_pilot_training_gap_register"."department_name",
    "v_patch50_pilot_training_gap_register"."gap_type" AS "blocker_type",
    "v_patch50_pilot_training_gap_register"."severity",
    "v_patch50_pilot_training_gap_register"."gap_summary" AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch50_pilot_training_gap_register"
UNION ALL
 SELECT "v_patch50_pilot_signoff_assignment_gap_register"."activation_run_id",
    "v_patch50_pilot_signoff_assignment_gap_register"."department_pilot_id",
    NULL::"uuid" AS "participant_id",
    "v_patch50_pilot_signoff_assignment_gap_register"."department_name",
    "v_patch50_pilot_signoff_assignment_gap_register"."gap_type" AS "blocker_type",
    "v_patch50_pilot_signoff_assignment_gap_register"."severity",
    "v_patch50_pilot_signoff_assignment_gap_register"."gap_summary" AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch50_pilot_signoff_assignment_gap_register"
UNION ALL
 SELECT "v_patch50_real_pilot_master_data_exception_register"."activation_run_id",
    "v_patch50_real_pilot_master_data_exception_register"."department_pilot_id",
    "v_patch50_real_pilot_master_data_exception_register"."participant_id",
    COALESCE("v_patch50_real_pilot_master_data_exception_register"."department_name", 'Unassigned department'::"text") AS "department_name",
    "v_patch50_real_pilot_master_data_exception_register"."exception_type" AS "blocker_type",
    "v_patch50_real_pilot_master_data_exception_register"."severity",
    "v_patch50_real_pilot_master_data_exception_register"."exception_summary" AS "blocker_summary",
    "v_patch50_real_pilot_master_data_exception_register"."evidence_reference"
   FROM "public"."v_patch50_real_pilot_master_data_exception_register"
  WHERE (("v_patch50_real_pilot_master_data_exception_register"."exception_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("v_patch50_real_pilot_master_data_exception_register"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch50_real_pilot_setup_summary" WITH ("security_invoker"='true') AS
 WITH "latest" AS (
         SELECT "controlled_pilot_activation_runs"."id",
            "controlled_pilot_activation_runs"."run_label",
            "controlled_pilot_activation_runs"."pilot_scope",
            "controlled_pilot_activation_runs"."activation_status",
            "controlled_pilot_activation_runs"."target_start_date",
            "controlled_pilot_activation_runs"."target_end_date",
            "controlled_pilot_activation_runs"."executive_sponsor_user_id",
            "controlled_pilot_activation_runs"."readiness_summary",
            "controlled_pilot_activation_runs"."limitation_summary",
            "controlled_pilot_activation_runs"."created_by",
            "controlled_pilot_activation_runs"."created_at",
            "controlled_pilot_activation_runs"."updated_at"
           FROM "public"."controlled_pilot_activation_runs"
          ORDER BY "controlled_pilot_activation_runs"."updated_at" DESC, "controlled_pilot_activation_runs"."created_at" DESC
         LIMIT 1
        ), "dept" AS (
         SELECT ("count"(*) FILTER (WHERE ("controlled_pilot_departments"."pilot_status" <> 'not_in_scope'::"text")))::integer AS "departments_in_scope",
            ("count"(*) FILTER (WHERE (("controlled_pilot_departments"."owner_user_id" IS NULL) AND ("controlled_pilot_departments"."pilot_status" <> 'not_in_scope'::"text"))))::integer AS "departments_missing_owners",
            ("count"(*) FILTER (WHERE ("controlled_pilot_departments"."pilot_status" = 'blocked'::"text")))::integer AS "departments_blocked",
            (COALESCE("sum"("controlled_pilot_departments"."required_participant_count") FILTER (WHERE ("controlled_pilot_departments"."pilot_status" <> 'not_in_scope'::"text")), (0)::bigint))::integer AS "required_participants",
            (COALESCE("sum"("controlled_pilot_departments"."confirmed_participant_count") FILTER (WHERE ("controlled_pilot_departments"."pilot_status" <> 'not_in_scope'::"text")), (0)::bigint))::integer AS "department_confirmed_participants"
           FROM "public"."controlled_pilot_departments"
          WHERE ("controlled_pilot_departments"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        ), "participants" AS (
         SELECT ("count"(*))::integer AS "participant_count",
            ("count"(*) FILTER (WHERE ("controlled_pilot_participants"."participation_status" = 'confirmed'::"text")))::integer AS "confirmed_participants",
            ("count"(*) FILTER (WHERE ("controlled_pilot_participants"."participation_status" = ANY (ARRAY['pending'::"text", 'declined'::"text", 'inactive'::"text", 'needs_training'::"text"]))))::integer AS "participant_gap_count",
            ("count"(*) FILTER (WHERE ("controlled_pilot_participants"."training_required" AND (NOT "controlled_pilot_participants"."training_confirmed"))))::integer AS "training_gap_count"
           FROM "public"."controlled_pilot_participants"
          WHERE ("controlled_pilot_participants"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        ), "signoffs" AS (
         SELECT ("count"(*) FILTER (WHERE ("controlled_pilot_department_signoffs"."signoff_status" = 'pending'::"text")))::integer AS "pending_signoffs",
            ("count"(*) FILTER (WHERE (("controlled_pilot_department_signoffs"."signoff_status" = 'overdue'::"text") OR (("controlled_pilot_department_signoffs"."signoff_status" = 'pending'::"text") AND ("controlled_pilot_department_signoffs"."due_at" IS NOT NULL) AND ("controlled_pilot_department_signoffs"."due_at" < "now"())))))::integer AS "overdue_signoffs",
            ("count"(*) FILTER (WHERE (("controlled_pilot_department_signoffs"."signer_user_id" IS NULL) AND ("controlled_pilot_department_signoffs"."signoff_status" <> 'not_required'::"text"))))::integer AS "missing_signoff_owners"
           FROM "public"."controlled_pilot_department_signoffs"
          WHERE ("controlled_pilot_department_signoffs"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        ), "exceptions" AS (
         SELECT ("count"(*) FILTER (WHERE ("real_pilot_master_data_exceptions"."exception_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"]))))::integer AS "open_exception_count",
            ("count"(*) FILTER (WHERE (("real_pilot_master_data_exceptions"."exception_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("real_pilot_master_data_exceptions"."severity" = 'critical'::"text"))))::integer AS "critical_exception_count",
            ("count"(*) FILTER (WHERE (("real_pilot_master_data_exceptions"."exception_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("real_pilot_master_data_exceptions"."severity" = 'high'::"text"))))::integer AS "high_exception_count",
            ("count"(*) FILTER (WHERE ("real_pilot_master_data_exceptions"."exception_status" = 'accepted_with_limitation'::"text")))::integer AS "limitation_exception_count"
           FROM "public"."real_pilot_master_data_exceptions"
          WHERE ("real_pilot_master_data_exceptions"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        ), "blockers" AS (
         SELECT ("count"(*))::integer AS "launch_blocker_count"
           FROM "public"."v_patch50_real_pilot_launch_blocker_register"
          WHERE ("v_patch50_real_pilot_launch_blocker_register"."activation_run_id" = ( SELECT "latest"."id"
                   FROM "latest"))
        )
 SELECT ( SELECT "latest"."id"
           FROM "latest") AS "activation_run_id",
    COALESCE(( SELECT "latest"."run_label"
           FROM "latest"), 'No controlled pilot activation run recorded'::"text") AS "run_label",
    COALESCE(( SELECT "latest"."activation_status"
           FROM "latest"), 'planning'::"text") AS "activation_status",
    COALESCE(( SELECT "dept"."departments_in_scope"
           FROM "dept"), 0) AS "departments_in_scope",
    COALESCE(( SELECT "dept"."departments_missing_owners"
           FROM "dept"), 0) AS "departments_missing_owners",
    COALESCE(( SELECT "dept"."departments_blocked"
           FROM "dept"), 0) AS "departments_blocked",
    COALESCE(( SELECT "dept"."required_participants"
           FROM "dept"), 0) AS "required_participants",
    GREATEST(COALESCE(( SELECT "participants"."confirmed_participants"
           FROM "participants"), 0), COALESCE(( SELECT "dept"."department_confirmed_participants"
           FROM "dept"), 0)) AS "confirmed_participants",
    COALESCE(( SELECT "participants"."participant_count"
           FROM "participants"), 0) AS "participant_count",
    COALESCE(( SELECT "participants"."participant_gap_count"
           FROM "participants"), 0) AS "participant_gap_count",
    COALESCE(( SELECT "participants"."training_gap_count"
           FROM "participants"), 0) AS "training_gap_count",
    COALESCE(( SELECT "signoffs"."pending_signoffs"
           FROM "signoffs"), 0) AS "pending_signoffs",
    COALESCE(( SELECT "signoffs"."overdue_signoffs"
           FROM "signoffs"), 0) AS "overdue_signoffs",
    COALESCE(( SELECT "signoffs"."missing_signoff_owners"
           FROM "signoffs"), 0) AS "missing_signoff_owners",
    COALESCE(( SELECT "exceptions"."open_exception_count"
           FROM "exceptions"), 0) AS "open_exception_count",
    COALESCE(( SELECT "exceptions"."critical_exception_count"
           FROM "exceptions"), 0) AS "critical_exception_count",
    COALESCE(( SELECT "exceptions"."high_exception_count"
           FROM "exceptions"), 0) AS "high_exception_count",
    COALESCE(( SELECT "exceptions"."limitation_exception_count"
           FROM "exceptions"), 0) AS "limitation_exception_count",
    COALESCE(( SELECT "blockers"."launch_blocker_count"
           FROM "blockers"), 0) AS "launch_blocker_count",
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "latest"))) THEN (0)::numeric
            WHEN (GREATEST(COALESCE(( SELECT "dept"."required_participants"
               FROM "dept"), 0), COALESCE(( SELECT "participants"."participant_count"
               FROM "participants"), 0)) = 0) THEN (0)::numeric
            ELSE "round"((((GREATEST(COALESCE(( SELECT "participants"."confirmed_participants"
               FROM "participants"), 0), COALESCE(( SELECT "dept"."department_confirmed_participants"
               FROM "dept"), 0)))::numeric / (GREATEST(COALESCE(( SELECT "dept"."required_participants"
               FROM "dept"), 0), COALESCE(( SELECT "participants"."participant_count"
               FROM "participants"), 0), 1))::numeric) * (100)::numeric), 1)
        END AS "participant_coverage_percentage",
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "latest"))) THEN 'evidence_required'::"text"
            WHEN ((COALESCE(( SELECT "blockers"."launch_blocker_count"
               FROM "blockers"), 0) > 0) OR (COALESCE(( SELECT "exceptions"."critical_exception_count"
               FROM "exceptions"), 0) > 0) OR (COALESCE(( SELECT "exceptions"."high_exception_count"
               FROM "exceptions"), 0) > 0) OR (COALESCE(( SELECT "dept"."departments_blocked"
               FROM "dept"), 0) > 0) OR (COALESCE(( SELECT "signoffs"."overdue_signoffs"
               FROM "signoffs"), 0) > 0)) THEN 'blocked'::"text"
            WHEN ((COALESCE(( SELECT "dept"."departments_missing_owners"
               FROM "dept"), 0) > 0) OR (COALESCE(( SELECT "participants"."participant_gap_count"
               FROM "participants"), 0) > 0) OR (COALESCE(( SELECT "participants"."training_gap_count"
               FROM "participants"), 0) > 0) OR (COALESCE(( SELECT "signoffs"."pending_signoffs"
               FROM "signoffs"), 0) > 0) OR (COALESCE(( SELECT "signoffs"."missing_signoff_owners"
               FROM "signoffs"), 0) > 0)) THEN 'in_progress'::"text"
            WHEN ((COALESCE(( SELECT "exceptions"."limitation_exception_count"
               FROM "exceptions"), 0) > 0) OR (( SELECT "latest"."activation_status"
               FROM "latest") = 'approved_with_limitations'::"text")) THEN 'ready_with_limitations'::"text"
            WHEN (( SELECT "latest"."activation_status"
               FROM "latest") = ANY (ARRAY['approved'::"text", 'completed'::"text"])) THEN 'ready'::"text"
            ELSE 'evidence_required'::"text"
        END AS "setup_readiness_status";

CREATE OR REPLACE VIEW "public"."v_patch50_production_readiness_real_pilot_setup_overlay" WITH ("security_invoker"='true') AS
 SELECT "activation_run_id",
    "run_label",
    "activation_status",
    "departments_in_scope",
    "departments_missing_owners",
    "departments_blocked",
    "required_participants",
    "confirmed_participants",
    "participant_count",
    "participant_gap_count",
    "training_gap_count",
    "pending_signoffs",
    "overdue_signoffs",
    "missing_signoff_owners",
    "open_exception_count",
    "critical_exception_count",
    "high_exception_count",
    "limitation_exception_count",
    "launch_blocker_count",
    "participant_coverage_percentage",
    "setup_readiness_status",
        CASE
            WHEN ("setup_readiness_status" = 'ready'::"text") THEN 'Real pilot setup is complete for the approved scope.'::"text"
            WHEN ("setup_readiness_status" = 'ready_with_limitations'::"text") THEN 'Real pilot setup can proceed only with documented limitations and monitoring.'::"text"
            WHEN ("setup_readiness_status" = 'blocked'::"text") THEN 'Resolve owners, blocked departments, overdue signoffs, training gaps, or high-risk exceptions before launch.'::"text"
            WHEN ("setup_readiness_status" = 'in_progress'::"text") THEN 'Complete missing owners, participant mapping, role assignment, training confirmation, and signoff coverage.'::"text"
            ELSE 'Create a controlled pilot run and complete real department, user, role, training, and signoff setup.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch50_real_pilot_setup_summary";

CREATE OR REPLACE VIEW "public"."v_patch50_real_pilot_onboarding_review_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "review_label",
    "review_status",
    "reviewed_by",
    "reviewed_at",
    "limitation_summary",
    "blocker_summary",
    "created_by",
    "created_at",
    "updated_at",
        CASE
            WHEN ("review_status" = 'approved'::"text") THEN 'ready'::"text"
            WHEN ("review_status" = 'approved_with_limitations'::"text") THEN 'ready_with_limitations'::"text"
            WHEN ("review_status" = 'blocked'::"text") THEN 'blocked'::"text"
            WHEN ("review_status" = ANY (ARRAY['draft'::"text", 'in_progress'::"text", 'ready_for_review'::"text"])) THEN 'in_progress'::"text"
            ELSE 'evidence_required'::"text"
        END AS "setup_status"
   FROM "public"."real_pilot_onboarding_reviews" "r";

CREATE OR REPLACE VIEW "public"."v_patch51_live_pilot_workflow_run_register" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."activation_run_id",
    "r"."workflow_key",
    "r"."workflow_label",
    "r"."run_status",
    "r"."department_pilot_id",
    "r"."owner_user_id",
    "r"."scheduled_at",
    "r"."started_at",
    "r"."completed_at",
    "r"."evidence_summary",
    "r"."limitation_summary",
    "r"."blocker_summary",
    "r"."created_by",
    "r"."created_at",
    "r"."updated_at",
    "d"."department_name",
    ("r"."run_status" = ANY (ARRAY['not_started'::"text", 'scheduled'::"text", 'in_progress'::"text"])) AS "is_pending_walkthrough",
    ("r"."run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) AS "is_failed_or_blocked"
   FROM ("public"."live_pilot_workflow_runs" "r"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "r"."department_pilot_id")));

CREATE OR REPLACE VIEW "public"."v_patch51_failed_workflow_walkthrough_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "workflow_key",
    "workflow_label",
    "run_status",
    "department_pilot_id",
    "owner_user_id",
    "scheduled_at",
    "started_at",
    "completed_at",
    "evidence_summary",
    "limitation_summary",
    "blocker_summary",
    "created_by",
    "created_at",
    "updated_at",
    "department_name",
    "is_pending_walkthrough",
    "is_failed_or_blocked"
   FROM "public"."v_patch51_live_pilot_workflow_run_register"
  WHERE ("run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch51_live_pilot_evidence_capture_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."workflow_run_id",
    "e"."workflow_step_id",
    "e"."evidence_type",
    "e"."evidence_title",
    "e"."evidence_reference",
    "e"."captured_by",
    "e"."captured_at",
    "e"."evidence_status",
    "e"."review_notes",
    "e"."created_at",
    "r"."workflow_key",
    "r"."workflow_label",
    ("e"."evidence_status" = ANY (ARRAY['rejected'::"text", 'needs_review'::"text"])) AS "evidence_needs_attention"
   FROM ("public"."live_pilot_evidence_captures" "e"
     JOIN "public"."live_pilot_workflow_runs" "r" ON (("r"."id" = "e"."workflow_run_id")));

CREATE OR REPLACE VIEW "public"."v_patch51_live_pilot_execution_issue_register" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."workflow_run_id",
    "i"."workflow_step_id",
    "i"."issue_type",
    "i"."severity",
    "i"."issue_status",
    "i"."issue_summary",
    "i"."assigned_to",
    "i"."due_at",
    "i"."resolution_summary",
    "i"."evidence_reference",
    "i"."created_by",
    "i"."created_at",
    "i"."updated_at",
    "r"."workflow_key",
    "r"."workflow_label",
    (("i"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("i"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"]))) AS "is_launch_blocker"
   FROM ("public"."live_pilot_execution_issues" "i"
     LEFT JOIN "public"."live_pilot_workflow_runs" "r" ON (("r"."id" = "i"."workflow_run_id")));

CREATE OR REPLACE VIEW "public"."v_patch51_live_pilot_workflow_step_register" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."workflow_run_id",
    "s"."step_order",
    "s"."step_key",
    "s"."step_label",
    "s"."step_status",
    "s"."responsible_role",
    "s"."responsible_user_id",
    "s"."evidence_required",
    "s"."evidence_reference",
    "s"."issue_summary",
    "s"."completed_at",
    "s"."created_at",
    "r"."workflow_key",
    "r"."workflow_label",
    ("s"."evidence_required" AND (NULLIF("s"."evidence_reference", ''::"text") IS NULL) AND ("s"."step_status" <> 'not_applicable'::"text")) AS "missing_required_evidence",
    ("s"."step_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) AS "is_failed_or_blocked"
   FROM ("public"."live_pilot_workflow_steps" "s"
     JOIN "public"."live_pilot_workflow_runs" "r" ON (("r"."id" = "s"."workflow_run_id")));

CREATE OR REPLACE VIEW "public"."v_patch51_missing_workflow_evidence_register" WITH ("security_invoker"='true') AS
 SELECT "v_patch51_live_pilot_workflow_step_register"."workflow_run_id",
    "v_patch51_live_pilot_workflow_step_register"."id" AS "workflow_step_id",
    "v_patch51_live_pilot_workflow_step_register"."workflow_key",
    "v_patch51_live_pilot_workflow_step_register"."workflow_label",
    "v_patch51_live_pilot_workflow_step_register"."step_key",
    "v_patch51_live_pilot_workflow_step_register"."step_label",
    'missing_evidence'::"text" AS "blocker_type",
    'Required walkthrough evidence has not been captured.'::"text" AS "blocker_summary"
   FROM "public"."v_patch51_live_pilot_workflow_step_register"
  WHERE "v_patch51_live_pilot_workflow_step_register"."missing_required_evidence"
UNION ALL
 SELECT "v_patch51_live_pilot_evidence_capture_register"."workflow_run_id",
    "v_patch51_live_pilot_evidence_capture_register"."workflow_step_id",
    "v_patch51_live_pilot_evidence_capture_register"."workflow_key",
    "v_patch51_live_pilot_evidence_capture_register"."workflow_label",
    "v_patch51_live_pilot_evidence_capture_register"."evidence_type" AS "step_key",
    "v_patch51_live_pilot_evidence_capture_register"."evidence_title" AS "step_label",
    "v_patch51_live_pilot_evidence_capture_register"."evidence_status" AS "blocker_type",
    'Captured evidence requires review or was rejected.'::"text" AS "blocker_summary"
   FROM "public"."v_patch51_live_pilot_evidence_capture_register"
  WHERE "v_patch51_live_pilot_evidence_capture_register"."evidence_needs_attention";

CREATE OR REPLACE VIEW "public"."v_patch51_workflow_execution_blocker_register" WITH ("security_invoker"='true') AS
 SELECT "v_patch51_live_pilot_workflow_run_register"."id" AS "workflow_run_id",
    NULL::"uuid" AS "workflow_step_id",
    "v_patch51_live_pilot_workflow_run_register"."workflow_key",
    "v_patch51_live_pilot_workflow_run_register"."workflow_label",
    'workflow_walkthrough'::"text" AS "blocker_area",
    "v_patch51_live_pilot_workflow_run_register"."run_status" AS "blocker_type",
    COALESCE("v_patch51_live_pilot_workflow_run_register"."blocker_summary", 'Workflow walkthrough is failed, blocked, or incomplete.'::"text") AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch51_live_pilot_workflow_run_register"
  WHERE ("v_patch51_live_pilot_workflow_run_register"."run_status" = ANY (ARRAY['not_started'::"text", 'scheduled'::"text", 'in_progress'::"text", 'failed'::"text", 'blocked'::"text"]))
UNION ALL
 SELECT "v_patch51_live_pilot_workflow_step_register"."workflow_run_id",
    "v_patch51_live_pilot_workflow_step_register"."id" AS "workflow_step_id",
    "v_patch51_live_pilot_workflow_step_register"."workflow_key",
    "v_patch51_live_pilot_workflow_step_register"."workflow_label",
    'workflow_step'::"text" AS "blocker_area",
    "v_patch51_live_pilot_workflow_step_register"."step_status" AS "blocker_type",
    COALESCE("v_patch51_live_pilot_workflow_step_register"."issue_summary", 'Workflow step is failed, blocked, or missing evidence.'::"text") AS "blocker_summary",
    "v_patch51_live_pilot_workflow_step_register"."evidence_reference"
   FROM "public"."v_patch51_live_pilot_workflow_step_register"
  WHERE (("v_patch51_live_pilot_workflow_step_register"."step_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) OR "v_patch51_live_pilot_workflow_step_register"."missing_required_evidence")
UNION ALL
 SELECT "v_patch51_live_pilot_evidence_capture_register"."workflow_run_id",
    "v_patch51_live_pilot_evidence_capture_register"."workflow_step_id",
    "v_patch51_live_pilot_evidence_capture_register"."workflow_key",
    "v_patch51_live_pilot_evidence_capture_register"."workflow_label",
    'evidence'::"text" AS "blocker_area",
    "v_patch51_live_pilot_evidence_capture_register"."evidence_status" AS "blocker_type",
    'Captured evidence requires review or was rejected.'::"text" AS "blocker_summary",
    "v_patch51_live_pilot_evidence_capture_register"."evidence_reference"
   FROM "public"."v_patch51_live_pilot_evidence_capture_register"
  WHERE "v_patch51_live_pilot_evidence_capture_register"."evidence_needs_attention"
UNION ALL
 SELECT "v_patch51_live_pilot_execution_issue_register"."workflow_run_id",
    "v_patch51_live_pilot_execution_issue_register"."workflow_step_id",
    "v_patch51_live_pilot_execution_issue_register"."workflow_key",
    "v_patch51_live_pilot_execution_issue_register"."workflow_label",
    'execution_issue'::"text" AS "blocker_area",
    "v_patch51_live_pilot_execution_issue_register"."issue_type" AS "blocker_type",
    "v_patch51_live_pilot_execution_issue_register"."issue_summary" AS "blocker_summary",
    "v_patch51_live_pilot_execution_issue_register"."evidence_reference"
   FROM "public"."v_patch51_live_pilot_execution_issue_register"
  WHERE (("v_patch51_live_pilot_execution_issue_register"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("v_patch51_live_pilot_execution_issue_register"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch51_live_pilot_workflow_summary" WITH ("security_invoker"='true') AS
 WITH "runs" AS (
         SELECT ("count"(*))::integer AS "critical_workflows_total",
            ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = ANY (ARRAY['passed'::"text", 'passed_with_limitations'::"text", 'failed'::"text", 'blocked'::"text", 'cancelled'::"text"]))))::integer AS "workflows_completed",
            ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = 'passed'::"text")))::integer AS "workflows_passed",
            ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = 'passed_with_limitations'::"text")))::integer AS "workflows_passed_with_limitations",
            ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = 'failed'::"text")))::integer AS "workflows_failed",
            ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = 'blocked'::"text")))::integer AS "workflows_blocked",
            ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = ANY (ARRAY['not_started'::"text", 'scheduled'::"text", 'in_progress'::"text"]))))::integer AS "workflows_pending"
           FROM "public"."live_pilot_workflow_runs"
        ), "evidence" AS (
         SELECT ("count"(*))::integer AS "missing_evidence_count"
           FROM "public"."v_patch51_missing_workflow_evidence_register"
        ), "issues" AS (
         SELECT ("count"(*) FILTER (WHERE (("live_pilot_execution_issues"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("live_pilot_execution_issues"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))))::integer AS "open_high_critical_issues"
           FROM "public"."live_pilot_execution_issues"
        ), "attention" AS (
         SELECT ("count"(*) FILTER (WHERE ("live_pilot_evidence_captures"."evidence_status" = ANY (ARRAY['rejected'::"text", 'needs_review'::"text"]))))::integer AS "evidence_needing_review"
           FROM "public"."live_pilot_evidence_captures"
        ), "blockers" AS (
         SELECT ("count"(*))::integer AS "workflow_blocker_count"
           FROM "public"."v_patch51_workflow_execution_blocker_register"
        )
 SELECT COALESCE(( SELECT "runs"."critical_workflows_total"
           FROM "runs"), 0) AS "critical_workflows_total",
    COALESCE(( SELECT "runs"."workflows_completed"
           FROM "runs"), 0) AS "workflows_completed",
    COALESCE(( SELECT "runs"."workflows_passed"
           FROM "runs"), 0) AS "workflows_passed",
    COALESCE(( SELECT "runs"."workflows_passed_with_limitations"
           FROM "runs"), 0) AS "workflows_passed_with_limitations",
    COALESCE(( SELECT "runs"."workflows_failed"
           FROM "runs"), 0) AS "workflows_failed",
    COALESCE(( SELECT "runs"."workflows_blocked"
           FROM "runs"), 0) AS "workflows_blocked",
    COALESCE(( SELECT "runs"."workflows_pending"
           FROM "runs"), 0) AS "workflows_pending",
    COALESCE(( SELECT "evidence"."missing_evidence_count"
           FROM "evidence"), 0) AS "missing_evidence_count",
    COALESCE(( SELECT "issues"."open_high_critical_issues"
           FROM "issues"), 0) AS "open_high_critical_issues",
    COALESCE(( SELECT "attention"."evidence_needing_review"
           FROM "attention"), 0) AS "evidence_needing_review",
    COALESCE(( SELECT "blockers"."workflow_blocker_count"
           FROM "blockers"), 0) AS "workflow_blocker_count",
        CASE
            WHEN (COALESCE(( SELECT "runs"."critical_workflows_total"
               FROM "runs"), 0) = 0) THEN 'evidence_required'::"text"
            WHEN ((COALESCE(( SELECT "blockers"."workflow_blocker_count"
               FROM "blockers"), 0) > 0) OR (COALESCE(( SELECT "issues"."open_high_critical_issues"
               FROM "issues"), 0) > 0)) THEN 'blocked'::"text"
            WHEN ((COALESCE(( SELECT "runs"."workflows_pending"
               FROM "runs"), 0) > 0) OR (COALESCE(( SELECT "evidence"."missing_evidence_count"
               FROM "evidence"), 0) > 0) OR (COALESCE(( SELECT "attention"."evidence_needing_review"
               FROM "attention"), 0) > 0)) THEN 'in_progress'::"text"
            WHEN (COALESCE(( SELECT "runs"."workflows_passed_with_limitations"
               FROM "runs"), 0) > 0) THEN 'ready_with_limitations'::"text"
            WHEN (COALESCE(( SELECT "runs"."workflows_passed"
               FROM "runs"), 0) = COALESCE(( SELECT "runs"."critical_workflows_total"
               FROM "runs"), 0)) THEN 'ready'::"text"
            ELSE 'evidence_required'::"text"
        END AS "live_execution_readiness_status";

CREATE OR REPLACE VIEW "public"."v_patch51_pending_workflow_walkthrough_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "workflow_key",
    "workflow_label",
    "run_status",
    "department_pilot_id",
    "owner_user_id",
    "scheduled_at",
    "started_at",
    "completed_at",
    "evidence_summary",
    "limitation_summary",
    "blocker_summary",
    "created_by",
    "created_at",
    "updated_at",
    "department_name",
    "is_pending_walkthrough",
    "is_failed_or_blocked"
   FROM "public"."v_patch51_live_pilot_workflow_run_register"
  WHERE ("run_status" = ANY (ARRAY['not_started'::"text", 'scheduled'::"text", 'in_progress'::"text"]));

CREATE OR REPLACE VIEW "public"."v_patch51_production_readiness_live_pilot_execution_overlay" WITH ("security_invoker"='true') AS
 SELECT "critical_workflows_total",
    "workflows_completed",
    "workflows_passed",
    "workflows_passed_with_limitations",
    "workflows_failed",
    "workflows_blocked",
    "workflows_pending",
    "missing_evidence_count",
    "open_high_critical_issues",
    "evidence_needing_review",
    "workflow_blocker_count",
    "live_execution_readiness_status",
        CASE
            WHEN ("live_execution_readiness_status" = 'ready'::"text") THEN 'All recorded live pilot workflow walkthroughs passed with accepted evidence.'::"text"
            WHEN ("live_execution_readiness_status" = 'ready_with_limitations'::"text") THEN 'Live pilot workflows can proceed with documented limitations and monitoring.'::"text"
            WHEN ("live_execution_readiness_status" = 'blocked'::"text") THEN 'Resolve failed walkthroughs, blocked steps, missing evidence, or high-risk execution issues before approval.'::"text"
            WHEN ("live_execution_readiness_status" = 'in_progress'::"text") THEN 'Complete pending workflow walkthroughs and evidence review.'::"text"
            ELSE 'Record live workflow walkthroughs and capture evidence before pilot approval.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch51_live_pilot_workflow_summary";

CREATE OR REPLACE VIEW "public"."v_patch52_accepted_limitation_register" WITH ("security_invoker"='true') AS
 SELECT "l"."id",
    "l"."closure_review_id",
    "l"."activation_run_id",
    "l"."limitation_title",
    "l"."limitation_status",
    "l"."severity",
    "l"."accepted_by",
    "l"."accepted_at",
    "l"."expires_at",
    "l"."mitigation_plan",
    "l"."evidence_reference",
    "l"."created_by",
    "l"."created_at",
    "l"."updated_at",
    "c"."closure_label",
    (("l"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])) AND ("l"."limitation_status" = 'accepted'::"text")) AS "is_high_critical_accepted",
    ("l"."limitation_status" = 'pending_review'::"text") AS "is_pending_review",
    (("l"."limitation_status" = 'accepted'::"text") AND ("l"."expires_at" IS NOT NULL) AND ("l"."expires_at" <= ("now"() + '30 days'::interval))) AS "is_expiring"
   FROM ("public"."pilot_accepted_limitations" "l"
     LEFT JOIN "public"."pilot_closure_reviews" "c" ON (("c"."id" = "l"."closure_review_id")));

CREATE OR REPLACE VIEW "public"."v_patch52_expiring_limitation_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "closure_review_id",
    "activation_run_id",
    "limitation_title",
    "limitation_status",
    "severity",
    "accepted_by",
    "accepted_at",
    "expires_at",
    "mitigation_plan",
    "evidence_reference",
    "created_by",
    "created_at",
    "updated_at",
    "closure_label",
    "is_high_critical_accepted",
    "is_pending_review",
    "is_expiring"
   FROM "public"."v_patch52_accepted_limitation_register"
  WHERE ("is_expiring" OR ("limitation_status" = 'expired'::"text"));

CREATE OR REPLACE VIEW "public"."v_patch52_missing_golive_decision_register" WITH ("security_invoker"='true') AS
 SELECT "id" AS "closure_review_id",
    "activation_run_id",
    "closure_label",
    'missing_golive_decision'::"text" AS "blocker_type",
    'A production go-live decision is still required for this pilot closure review.'::"text" AS "blocker_summary"
   FROM "public"."pilot_closure_reviews" "c"
  WHERE (("closure_status" = ANY (ARRAY['in_review'::"text", 'ready_for_decision'::"text", 'approved_for_golive'::"text", 'approved_with_limitations'::"text"])) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."production_golive_decisions" "d"
          WHERE (("d"."closure_review_id" = "c"."id") AND ("d"."decision_status" = ANY (ARRAY['approved'::"text", 'approved_with_limitations'::"text", 'rejected'::"text", 'deferred'::"text"])))))));

CREATE OR REPLACE VIEW "public"."v_patch52_pilot_remediation_action_register" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."closure_review_id",
    "r"."activation_run_id",
    "r"."source_issue_id",
    "r"."source_workflow_run_id",
    "r"."remediation_title",
    "r"."remediation_status",
    "r"."severity",
    "r"."owner_user_id",
    "r"."due_at",
    "r"."completed_at",
    "r"."evidence_reference",
    "r"."remediation_summary",
    "r"."risk_acceptance_reason",
    "r"."created_by",
    "r"."created_at",
    "r"."updated_at",
    "c"."closure_label",
    (("r"."remediation_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) AND ("r"."due_at" IS NOT NULL) AND ("r"."due_at" < "now"())) AS "is_overdue",
    (("r"."remediation_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) AND ("r"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"]))) AS "is_high_critical_open"
   FROM ("public"."pilot_remediation_actions" "r"
     LEFT JOIN "public"."pilot_closure_reviews" "c" ON (("c"."id" = "r"."closure_review_id")));

CREATE OR REPLACE VIEW "public"."v_patch52_open_high_critical_remediation_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "closure_review_id",
    "activation_run_id",
    "source_issue_id",
    "source_workflow_run_id",
    "remediation_title",
    "remediation_status",
    "severity",
    "owner_user_id",
    "due_at",
    "completed_at",
    "evidence_reference",
    "remediation_summary",
    "risk_acceptance_reason",
    "created_by",
    "created_at",
    "updated_at",
    "closure_label",
    "is_overdue",
    "is_high_critical_open"
   FROM "public"."v_patch52_pilot_remediation_action_register"
  WHERE "is_high_critical_open";

CREATE OR REPLACE VIEW "public"."v_patch52_overdue_remediation_action_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "closure_review_id",
    "activation_run_id",
    "source_issue_id",
    "source_workflow_run_id",
    "remediation_title",
    "remediation_status",
    "severity",
    "owner_user_id",
    "due_at",
    "completed_at",
    "evidence_reference",
    "remediation_summary",
    "risk_acceptance_reason",
    "created_by",
    "created_at",
    "updated_at",
    "closure_label",
    "is_overdue",
    "is_high_critical_open"
   FROM "public"."v_patch52_pilot_remediation_action_register"
  WHERE (("remediation_status" = 'overdue'::"text") OR "is_overdue");

CREATE OR REPLACE VIEW "public"."v_patch52_pilot_closure_review_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "closure_label",
    "closure_status",
    "executive_sponsor_user_id",
    "quality_owner_user_id",
    "audit_owner_user_id",
    "it_owner_user_id",
    "target_golive_date",
    "decision_summary",
    "limitation_summary",
    "blocker_summary",
    "created_by",
    "created_at",
    "updated_at",
    ("closure_status" = ANY (ARRAY['in_review'::"text", 'ready_for_decision'::"text"])) AS "needs_decision",
    ("closure_status" = ANY (ARRAY['blocked'::"text", 'deferred'::"text"])) AS "is_blocked_or_deferred"
   FROM "public"."pilot_closure_reviews" "c";

CREATE OR REPLACE VIEW "public"."v_patch52_production_golive_decision_register" WITH ("security_invoker"='true') AS
 SELECT "d"."id",
    "d"."closure_review_id",
    "d"."activation_run_id",
    "d"."decision_status",
    "d"."decision_level",
    "d"."decision_by",
    "d"."decision_at",
    "d"."decision_summary",
    "d"."conditions_summary",
    "d"."evidence_reference",
    "d"."created_by",
    "d"."created_at",
    "d"."updated_at",
    "c"."closure_label",
    ("d"."decision_status" = ANY (ARRAY['pending'::"text", 'deferred'::"text"])) AS "needs_decision",
    ("d"."decision_status" = ANY (ARRAY['rejected'::"text", 'deferred'::"text", 'revoked'::"text"])) AS "is_blocking_decision"
   FROM ("public"."production_golive_decisions" "d"
     LEFT JOIN "public"."pilot_closure_reviews" "c" ON (("c"."id" = "d"."closure_review_id")));

CREATE OR REPLACE VIEW "public"."v_patch52_pilot_closure_blocker_register" WITH ("security_invoker"='true') AS
 SELECT "v_patch52_pilot_closure_review_register"."id" AS "closure_review_id",
    "v_patch52_pilot_closure_review_register"."activation_run_id",
    "v_patch52_pilot_closure_review_register"."closure_label",
    'closure_review'::"text" AS "blocker_area",
    "v_patch52_pilot_closure_review_register"."closure_status" AS "blocker_type",
    COALESCE("v_patch52_pilot_closure_review_register"."blocker_summary", 'Pilot closure review is blocked, deferred, or still in review.'::"text") AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch52_pilot_closure_review_register"
  WHERE ("v_patch52_pilot_closure_review_register"."closure_status" = ANY (ARRAY['in_review'::"text", 'blocked'::"text", 'deferred'::"text"]))
UNION ALL
 SELECT "v_patch52_pilot_remediation_action_register"."closure_review_id",
    "v_patch52_pilot_remediation_action_register"."activation_run_id",
    "v_patch52_pilot_remediation_action_register"."closure_label",
    'remediation'::"text" AS "blocker_area",
    "v_patch52_pilot_remediation_action_register"."remediation_status" AS "blocker_type",
    "v_patch52_pilot_remediation_action_register"."remediation_title" AS "blocker_summary",
    "v_patch52_pilot_remediation_action_register"."evidence_reference"
   FROM "public"."v_patch52_pilot_remediation_action_register"
  WHERE (("v_patch52_pilot_remediation_action_register"."remediation_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) OR "v_patch52_pilot_remediation_action_register"."is_high_critical_open")
UNION ALL
 SELECT "v_patch52_accepted_limitation_register"."closure_review_id",
    "v_patch52_accepted_limitation_register"."activation_run_id",
    "v_patch52_accepted_limitation_register"."closure_label",
    'accepted_limitation'::"text" AS "blocker_area",
    "v_patch52_accepted_limitation_register"."limitation_status" AS "blocker_type",
    "v_patch52_accepted_limitation_register"."limitation_title" AS "blocker_summary",
    "v_patch52_accepted_limitation_register"."evidence_reference"
   FROM "public"."v_patch52_accepted_limitation_register"
  WHERE (("v_patch52_accepted_limitation_register"."limitation_status" = ANY (ARRAY['pending_review'::"text", 'expired'::"text"])) OR "v_patch52_accepted_limitation_register"."is_high_critical_accepted")
UNION ALL
 SELECT "v_patch52_production_golive_decision_register"."closure_review_id",
    "v_patch52_production_golive_decision_register"."activation_run_id",
    "v_patch52_production_golive_decision_register"."closure_label",
    'go_live_decision'::"text" AS "blocker_area",
    "v_patch52_production_golive_decision_register"."decision_status" AS "blocker_type",
    COALESCE("v_patch52_production_golive_decision_register"."decision_summary", 'Production go-live decision is pending, rejected, deferred, or revoked.'::"text") AS "blocker_summary",
    "v_patch52_production_golive_decision_register"."evidence_reference"
   FROM "public"."v_patch52_production_golive_decision_register"
  WHERE ("v_patch52_production_golive_decision_register"."decision_status" = ANY (ARRAY['pending'::"text", 'rejected'::"text", 'deferred'::"text", 'revoked'::"text"]))
UNION ALL
 SELECT "v_patch52_missing_golive_decision_register"."closure_review_id",
    "v_patch52_missing_golive_decision_register"."activation_run_id",
    "v_patch52_missing_golive_decision_register"."closure_label",
    'go_live_decision'::"text" AS "blocker_area",
    "v_patch52_missing_golive_decision_register"."blocker_type",
    "v_patch52_missing_golive_decision_register"."blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch52_missing_golive_decision_register"
UNION ALL
 SELECT NULL::"uuid" AS "closure_review_id",
    NULL::"uuid" AS "activation_run_id",
    "v_patch51_failed_workflow_walkthrough_register"."workflow_label" AS "closure_label",
    'live_workflow'::"text" AS "blocker_area",
    "v_patch51_failed_workflow_walkthrough_register"."run_status" AS "blocker_type",
    COALESCE("v_patch51_failed_workflow_walkthrough_register"."blocker_summary", 'A live pilot workflow failed or is blocked.'::"text") AS "blocker_summary",
    "v_patch51_failed_workflow_walkthrough_register"."evidence_summary" AS "evidence_reference"
   FROM "public"."v_patch51_failed_workflow_walkthrough_register"
UNION ALL
 SELECT NULL::"uuid" AS "closure_review_id",
    NULL::"uuid" AS "activation_run_id",
    "v_patch51_missing_workflow_evidence_register"."workflow_label" AS "closure_label",
    'workflow_evidence'::"text" AS "blocker_area",
    "v_patch51_missing_workflow_evidence_register"."blocker_type",
    "v_patch51_missing_workflow_evidence_register"."blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch51_missing_workflow_evidence_register"
UNION ALL
 SELECT NULL::"uuid" AS "closure_review_id",
    NULL::"uuid" AS "activation_run_id",
    "v_patch51_live_pilot_execution_issue_register"."workflow_label" AS "closure_label",
    'live_issue'::"text" AS "blocker_area",
    "v_patch51_live_pilot_execution_issue_register"."issue_type" AS "blocker_type",
    "v_patch51_live_pilot_execution_issue_register"."issue_summary" AS "blocker_summary",
    "v_patch51_live_pilot_execution_issue_register"."evidence_reference"
   FROM "public"."v_patch51_live_pilot_execution_issue_register"
  WHERE (("v_patch51_live_pilot_execution_issue_register"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("v_patch51_live_pilot_execution_issue_register"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])));

CREATE OR REPLACE VIEW "public"."v_patch52_pilot_closure_summary" WITH ("security_invoker"='true') AS
 WITH "closures" AS (
         SELECT ("count"(*))::integer AS "closure_review_total",
            ("count"(*) FILTER (WHERE ("pilot_closure_reviews"."closure_status" = 'in_review'::"text")))::integer AS "closure_reviews_in_review",
            ("count"(*) FILTER (WHERE ("pilot_closure_reviews"."closure_status" = 'ready_for_decision'::"text")))::integer AS "closure_reviews_ready_for_decision",
            ("count"(*) FILTER (WHERE ("pilot_closure_reviews"."closure_status" = ANY (ARRAY['blocked'::"text", 'deferred'::"text"]))))::integer AS "blocked_or_deferred_closures",
            ("count"(*) FILTER (WHERE ("pilot_closure_reviews"."closure_status" = 'approved_with_limitations'::"text")))::integer AS "closure_reviews_approved_with_limitations"
           FROM "public"."pilot_closure_reviews"
        ), "remediation" AS (
         SELECT ("count"(*) FILTER (WHERE ("pilot_remediation_actions"."remediation_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"]))))::integer AS "open_remediation_actions",
            ("count"(*) FILTER (WHERE (("pilot_remediation_actions"."remediation_status" = 'overdue'::"text") OR (("pilot_remediation_actions"."remediation_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("pilot_remediation_actions"."due_at" IS NOT NULL) AND ("pilot_remediation_actions"."due_at" < "now"())))))::integer AS "overdue_remediation_actions",
            ("count"(*) FILTER (WHERE (("pilot_remediation_actions"."remediation_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) AND ("pilot_remediation_actions"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))))::integer AS "high_critical_remediation_actions"
           FROM "public"."pilot_remediation_actions"
        ), "limitations" AS (
         SELECT ("count"(*) FILTER (WHERE ("pilot_accepted_limitations"."limitation_status" = 'accepted'::"text")))::integer AS "accepted_limitations",
            ("count"(*) FILTER (WHERE (("pilot_accepted_limitations"."limitation_status" = 'accepted'::"text") AND ("pilot_accepted_limitations"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))))::integer AS "high_critical_accepted_limitations",
            ("count"(*) FILTER (WHERE ("pilot_accepted_limitations"."limitation_status" = 'pending_review'::"text")))::integer AS "pending_limitation_reviews",
            ("count"(*) FILTER (WHERE (("pilot_accepted_limitations"."limitation_status" = 'expired'::"text") OR (("pilot_accepted_limitations"."limitation_status" = 'accepted'::"text") AND ("pilot_accepted_limitations"."expires_at" IS NOT NULL) AND ("pilot_accepted_limitations"."expires_at" <= ("now"() + '30 days'::interval))))))::integer AS "expiring_limitations"
           FROM "public"."pilot_accepted_limitations"
        ), "decisions" AS (
         SELECT ("count"(*) FILTER (WHERE ("production_golive_decisions"."decision_status" = 'pending'::"text")))::integer AS "pending_golive_decisions",
            ("count"(*) FILTER (WHERE ("production_golive_decisions"."decision_status" = ANY (ARRAY['rejected'::"text", 'deferred'::"text", 'revoked'::"text"]))))::integer AS "rejected_or_deferred_decisions",
            ("count"(*) FILTER (WHERE ("production_golive_decisions"."decision_status" = 'approved'::"text")))::integer AS "approved_golive_decisions",
            ("count"(*) FILTER (WHERE ("production_golive_decisions"."decision_status" = 'approved_with_limitations'::"text")))::integer AS "approved_with_limitations_decisions"
           FROM "public"."production_golive_decisions"
        ), "missing_decisions" AS (
         SELECT ("count"(*))::integer AS "missing_golive_decisions"
           FROM "public"."v_patch52_missing_golive_decision_register"
        ), "live_workflows" AS (
         SELECT ("count"(*) FILTER (WHERE ("live_pilot_workflow_runs"."run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"]))))::integer AS "failed_or_blocked_workflows"
           FROM "public"."live_pilot_workflow_runs"
        ), "live_evidence" AS (
         SELECT ("count"(*))::integer AS "missing_workflow_evidence_count"
           FROM "public"."v_patch51_missing_workflow_evidence_register"
        ), "live_issues" AS (
         SELECT ("count"(*) FILTER (WHERE (("live_pilot_execution_issues"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("live_pilot_execution_issues"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))))::integer AS "open_high_critical_live_issues"
           FROM "public"."live_pilot_execution_issues"
        )
 SELECT COALESCE(( SELECT "closures"."closure_review_total"
           FROM "closures"), 0) AS "closure_review_total",
    COALESCE(( SELECT "closures"."closure_reviews_in_review"
           FROM "closures"), 0) AS "closure_reviews_in_review",
    COALESCE(( SELECT "closures"."closure_reviews_ready_for_decision"
           FROM "closures"), 0) AS "closure_reviews_ready_for_decision",
    COALESCE(( SELECT "closures"."blocked_or_deferred_closures"
           FROM "closures"), 0) AS "blocked_or_deferred_closures",
    COALESCE(( SELECT "closures"."closure_reviews_approved_with_limitations"
           FROM "closures"), 0) AS "closure_reviews_approved_with_limitations",
    COALESCE(( SELECT "remediation"."open_remediation_actions"
           FROM "remediation"), 0) AS "open_remediation_actions",
    COALESCE(( SELECT "remediation"."overdue_remediation_actions"
           FROM "remediation"), 0) AS "overdue_remediation_actions",
    COALESCE(( SELECT "remediation"."high_critical_remediation_actions"
           FROM "remediation"), 0) AS "high_critical_remediation_actions",
    COALESCE(( SELECT "limitations"."accepted_limitations"
           FROM "limitations"), 0) AS "accepted_limitations",
    COALESCE(( SELECT "limitations"."high_critical_accepted_limitations"
           FROM "limitations"), 0) AS "high_critical_accepted_limitations",
    COALESCE(( SELECT "limitations"."pending_limitation_reviews"
           FROM "limitations"), 0) AS "pending_limitation_reviews",
    COALESCE(( SELECT "limitations"."expiring_limitations"
           FROM "limitations"), 0) AS "expiring_limitations",
    COALESCE(( SELECT "decisions"."pending_golive_decisions"
           FROM "decisions"), 0) AS "pending_golive_decisions",
    COALESCE(( SELECT "decisions"."rejected_or_deferred_decisions"
           FROM "decisions"), 0) AS "rejected_or_deferred_decisions",
    COALESCE(( SELECT "decisions"."approved_golive_decisions"
           FROM "decisions"), 0) AS "approved_golive_decisions",
    COALESCE(( SELECT "decisions"."approved_with_limitations_decisions"
           FROM "decisions"), 0) AS "approved_with_limitations_decisions",
    COALESCE(( SELECT "missing_decisions"."missing_golive_decisions"
           FROM "missing_decisions"), 0) AS "missing_golive_decisions",
    COALESCE(( SELECT "live_workflows"."failed_or_blocked_workflows"
           FROM "live_workflows"), 0) AS "failed_or_blocked_workflows",
    COALESCE(( SELECT "live_evidence"."missing_workflow_evidence_count"
           FROM "live_evidence"), 0) AS "missing_workflow_evidence_count",
    COALESCE(( SELECT "live_issues"."open_high_critical_live_issues"
           FROM "live_issues"), 0) AS "open_high_critical_live_issues",
        CASE
            WHEN (COALESCE(( SELECT "closures"."closure_review_total"
               FROM "closures"), 0) = 0) THEN 'evidence_required'::"text"
            WHEN ((COALESCE(( SELECT "closures"."blocked_or_deferred_closures"
               FROM "closures"), 0) > 0) OR (COALESCE(( SELECT "remediation"."overdue_remediation_actions"
               FROM "remediation"), 0) > 0) OR (COALESCE(( SELECT "remediation"."high_critical_remediation_actions"
               FROM "remediation"), 0) > 0) OR (COALESCE(( SELECT "decisions"."rejected_or_deferred_decisions"
               FROM "decisions"), 0) > 0) OR (COALESCE(( SELECT "live_workflows"."failed_or_blocked_workflows"
               FROM "live_workflows"), 0) > 0) OR (COALESCE(( SELECT "live_evidence"."missing_workflow_evidence_count"
               FROM "live_evidence"), 0) > 0) OR (COALESCE(( SELECT "live_issues"."open_high_critical_live_issues"
               FROM "live_issues"), 0) > 0)) THEN 'blocked'::"text"
            WHEN ((COALESCE(( SELECT "decisions"."pending_golive_decisions"
               FROM "decisions"), 0) > 0) OR (COALESCE(( SELECT "missing_decisions"."missing_golive_decisions"
               FROM "missing_decisions"), 0) > 0) OR (COALESCE(( SELECT "closures"."closure_reviews_in_review"
               FROM "closures"), 0) > 0) OR (COALESCE(( SELECT "closures"."closure_reviews_ready_for_decision"
               FROM "closures"), 0) > 0) OR (COALESCE(( SELECT "remediation"."open_remediation_actions"
               FROM "remediation"), 0) > 0) OR (COALESCE(( SELECT "limitations"."pending_limitation_reviews"
               FROM "limitations"), 0) > 0)) THEN 'in_review'::"text"
            WHEN ((COALESCE(( SELECT "decisions"."approved_with_limitations_decisions"
               FROM "decisions"), 0) > 0) OR (COALESCE(( SELECT "closures"."closure_reviews_approved_with_limitations"
               FROM "closures"), 0) > 0) OR (COALESCE(( SELECT "limitations"."accepted_limitations"
               FROM "limitations"), 0) > 0)) THEN 'ready_with_limitations'::"text"
            WHEN (COALESCE(( SELECT "decisions"."approved_golive_decisions"
               FROM "decisions"), 0) > 0) THEN 'ready'::"text"
            ELSE 'evidence_required'::"text"
        END AS "production_golive_readiness_status";

CREATE OR REPLACE VIEW "public"."v_patch52_production_readiness_golive_decision_overlay" WITH ("security_invoker"='true') AS
 SELECT "closure_review_total",
    "closure_reviews_in_review",
    "closure_reviews_ready_for_decision",
    "blocked_or_deferred_closures",
    "closure_reviews_approved_with_limitations",
    "open_remediation_actions",
    "overdue_remediation_actions",
    "high_critical_remediation_actions",
    "accepted_limitations",
    "high_critical_accepted_limitations",
    "pending_limitation_reviews",
    "expiring_limitations",
    "pending_golive_decisions",
    "rejected_or_deferred_decisions",
    "approved_golive_decisions",
    "approved_with_limitations_decisions",
    "missing_golive_decisions",
    "failed_or_blocked_workflows",
    "missing_workflow_evidence_count",
    "open_high_critical_live_issues",
    "production_golive_readiness_status",
        CASE
            WHEN ("production_golive_readiness_status" = 'ready'::"text") THEN 'Production go-live is approved with no open closure blockers recorded.'::"text"
            WHEN ("production_golive_readiness_status" = 'ready_with_limitations'::"text") THEN 'Production go-live may proceed only with documented accepted limitations and monitoring.'::"text"
            WHEN ("production_golive_readiness_status" = 'blocked'::"text") THEN 'Resolve open high-risk remediation, failed workflows, missing evidence, or blocked decisions before go-live.'::"text"
            WHEN ("production_golive_readiness_status" = 'in_review'::"text") THEN 'Complete closure review, remediation tracking, limitation review, and go-live decisions.'::"text"
            ELSE 'Create a pilot closure review and record executive go-live decision evidence.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch52_pilot_closure_summary";

CREATE OR REPLACE VIEW "public"."v_patch53_department_adoption_feedback_register" WITH ("security_invoker"='true') AS
 SELECT "f"."id",
    "f"."hypercare_period_id",
    "f"."department_pilot_id",
    "f"."feedback_status",
    "f"."adoption_status",
    "f"."submitted_by",
    "f"."submitted_at",
    "f"."feedback_summary",
    "f"."support_needed",
    "f"."training_needed",
    "f"."issue_reference",
    "f"."reviewed_by",
    "f"."reviewed_at",
    "f"."created_by",
    "f"."created_at",
    "f"."updated_at",
    "p"."hypercare_label",
    "d"."department_name",
    ("f"."feedback_status" = 'pending'::"text") AS "is_missing_feedback",
    ("f"."adoption_status" = ANY (ARRAY['low_adoption'::"text", 'blocked'::"text"])) AS "is_low_adoption"
   FROM (("public"."production_adoption_feedback" "f"
     LEFT JOIN "public"."production_hypercare_periods" "p" ON (("p"."id" = "f"."hypercare_period_id")))
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "f"."department_pilot_id")));

CREATE OR REPLACE VIEW "public"."v_patch53_hypercare_issue_register" WITH ("security_invoker"='true') AS
 SELECT "i"."id",
    "i"."hypercare_period_id",
    "i"."source_workflow_run_id",
    "i"."source_execution_issue_id",
    "i"."issue_title",
    "i"."issue_type",
    "i"."issue_status",
    "i"."severity",
    "i"."department_pilot_id",
    "i"."owner_user_id",
    "i"."due_at",
    "i"."resolved_at",
    "i"."resolution_summary",
    "i"."evidence_reference",
    "i"."created_by",
    "i"."created_at",
    "i"."updated_at",
    "p"."hypercare_label",
    (("i"."issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) AND ("i"."due_at" IS NOT NULL) AND ("i"."due_at" < "now"())) AS "is_overdue",
    (("i"."issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) AND ("i"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"]))) AS "is_high_critical_open"
   FROM ("public"."production_hypercare_issues" "i"
     LEFT JOIN "public"."production_hypercare_periods" "p" ON (("p"."id" = "i"."hypercare_period_id")));

CREATE OR REPLACE VIEW "public"."v_patch53_hypercare_period_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "activation_run_id",
    "closure_review_id",
    "golive_decision_id",
    "hypercare_label",
    "hypercare_status",
    "start_date",
    "target_end_date",
    "actual_end_date",
    "executive_owner_user_id",
    "operational_owner_user_id",
    "quality_owner_user_id",
    "it_owner_user_id",
    "stability_summary",
    "blocker_summary",
    "created_by",
    "created_at",
    "updated_at",
    GREATEST(COALESCE(("target_end_date" - CURRENT_DATE), 0), 0) AS "days_remaining",
    ("hypercare_status" = 'active'::"text") AS "is_active_hypercare",
    ("hypercare_status" = ANY (ARRAY['at_risk'::"text", 'blocked'::"text", 'extended'::"text"])) AS "is_at_risk_or_blocked"
   FROM "public"."production_hypercare_periods" "p";

CREATE OR REPLACE VIEW "public"."v_patch53_low_adoption_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "hypercare_period_id",
    "department_pilot_id",
    "feedback_status",
    "adoption_status",
    "submitted_by",
    "submitted_at",
    "feedback_summary",
    "support_needed",
    "training_needed",
    "issue_reference",
    "reviewed_by",
    "reviewed_at",
    "created_by",
    "created_at",
    "updated_at",
    "hypercare_label",
    "department_name",
    "is_missing_feedback",
    "is_low_adoption"
   FROM "public"."v_patch53_department_adoption_feedback_register"
  WHERE ("is_low_adoption" OR "support_needed" OR "training_needed");

CREATE OR REPLACE VIEW "public"."v_patch53_operating_cadence_event_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."hypercare_period_id",
    "e"."cadence_type",
    "e"."event_status",
    "e"."scheduled_at",
    "e"."completed_at",
    "e"."owner_user_id",
    "e"."summary",
    "e"."decisions_summary",
    "e"."action_summary",
    "e"."evidence_reference",
    "e"."created_by",
    "e"."created_at",
    "e"."updated_at",
    "p"."hypercare_label",
    (("e"."event_status" = 'missed'::"text") OR (("e"."event_status" = 'scheduled'::"text") AND ("e"."scheduled_at" IS NOT NULL) AND ("e"."scheduled_at" < "now"()))) AS "is_missed_or_overdue"
   FROM ("public"."production_operating_cadence_events" "e"
     LEFT JOIN "public"."production_hypercare_periods" "p" ON (("p"."id" = "e"."hypercare_period_id")));

CREATE OR REPLACE VIEW "public"."v_patch53_missed_operating_cadence_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "hypercare_period_id",
    "cadence_type",
    "event_status",
    "scheduled_at",
    "completed_at",
    "owner_user_id",
    "summary",
    "decisions_summary",
    "action_summary",
    "evidence_reference",
    "created_by",
    "created_at",
    "updated_at",
    "hypercare_label",
    "is_missed_or_overdue"
   FROM "public"."v_patch53_operating_cadence_event_register"
  WHERE "is_missed_or_overdue";

CREATE OR REPLACE VIEW "public"."v_patch53_missing_department_feedback_register" WITH ("security_invoker"='true') AS
 SELECT "v_patch53_department_adoption_feedback_register"."id",
    "v_patch53_department_adoption_feedback_register"."hypercare_period_id",
    "v_patch53_department_adoption_feedback_register"."department_pilot_id",
    "v_patch53_department_adoption_feedback_register"."feedback_status",
    "v_patch53_department_adoption_feedback_register"."adoption_status",
    "v_patch53_department_adoption_feedback_register"."submitted_by",
    "v_patch53_department_adoption_feedback_register"."submitted_at",
    "v_patch53_department_adoption_feedback_register"."feedback_summary",
    "v_patch53_department_adoption_feedback_register"."support_needed",
    "v_patch53_department_adoption_feedback_register"."training_needed",
    "v_patch53_department_adoption_feedback_register"."issue_reference",
    "v_patch53_department_adoption_feedback_register"."reviewed_by",
    "v_patch53_department_adoption_feedback_register"."reviewed_at",
    "v_patch53_department_adoption_feedback_register"."created_by",
    "v_patch53_department_adoption_feedback_register"."created_at",
    "v_patch53_department_adoption_feedback_register"."updated_at",
    "v_patch53_department_adoption_feedback_register"."hypercare_label",
    "v_patch53_department_adoption_feedback_register"."department_name",
    "v_patch53_department_adoption_feedback_register"."is_missing_feedback",
    "v_patch53_department_adoption_feedback_register"."is_low_adoption"
   FROM "public"."v_patch53_department_adoption_feedback_register"
  WHERE "v_patch53_department_adoption_feedback_register"."is_missing_feedback"
UNION ALL
 SELECT "p"."id",
    "p"."id" AS "hypercare_period_id",
    "d"."id" AS "department_pilot_id",
    'pending'::"text" AS "feedback_status",
    'not_assessed'::"text" AS "adoption_status",
    NULL::"uuid" AS "submitted_by",
    NULL::timestamp with time zone AS "submitted_at",
    NULL::"text" AS "feedback_summary",
    false AS "support_needed",
    false AS "training_needed",
    NULL::"text" AS "issue_reference",
    NULL::"uuid" AS "reviewed_by",
    NULL::timestamp with time zone AS "reviewed_at",
    NULL::"uuid" AS "created_by",
    "p"."created_at",
    "p"."updated_at",
    "p"."hypercare_label",
    "d"."department_name",
    true AS "is_missing_feedback",
    false AS "is_low_adoption"
   FROM ("public"."production_hypercare_periods" "p"
     JOIN "public"."controlled_pilot_departments" "d" ON ((("d"."activation_run_id" = "p"."activation_run_id") AND ("d"."pilot_status" <> 'not_in_scope'::"text"))))
  WHERE (("p"."hypercare_status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'at_risk'::"text", 'blocked'::"text", 'extended'::"text"])) AND (NOT (EXISTS ( SELECT 1
           FROM "public"."production_adoption_feedback" "f"
          WHERE (("f"."hypercare_period_id" = "p"."id") AND ("f"."department_pilot_id" = "d"."id"))))));

CREATE OR REPLACE VIEW "public"."v_patch53_hypercare_blocker_register" WITH ("security_invoker"='true') AS
 SELECT "v_patch53_hypercare_period_register"."id" AS "hypercare_period_id",
    "v_patch53_hypercare_period_register"."hypercare_label",
    'hypercare_period'::"text" AS "blocker_area",
    "v_patch53_hypercare_period_register"."hypercare_status" AS "blocker_type",
    COALESCE("v_patch53_hypercare_period_register"."blocker_summary", 'Hypercare period is at risk, blocked, extended, or still active.'::"text") AS "blocker_summary",
    NULL::"text" AS "evidence_reference"
   FROM "public"."v_patch53_hypercare_period_register"
  WHERE ("v_patch53_hypercare_period_register"."hypercare_status" = ANY (ARRAY['active'::"text", 'at_risk'::"text", 'blocked'::"text", 'extended'::"text"]))
UNION ALL
 SELECT "v_patch53_hypercare_issue_register"."hypercare_period_id",
    "v_patch53_hypercare_issue_register"."hypercare_label",
    'hypercare_issue'::"text" AS "blocker_area",
    "v_patch53_hypercare_issue_register"."issue_status" AS "blocker_type",
    "v_patch53_hypercare_issue_register"."issue_title" AS "blocker_summary",
    "v_patch53_hypercare_issue_register"."evidence_reference"
   FROM "public"."v_patch53_hypercare_issue_register"
  WHERE (("v_patch53_hypercare_issue_register"."issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) OR "v_patch53_hypercare_issue_register"."is_high_critical_open")
UNION ALL
 SELECT "v_patch53_missed_operating_cadence_register"."hypercare_period_id",
    "v_patch53_missed_operating_cadence_register"."hypercare_label",
    'operating_cadence'::"text" AS "blocker_area",
    "v_patch53_missed_operating_cadence_register"."event_status" AS "blocker_type",
    COALESCE("v_patch53_missed_operating_cadence_register"."summary", ("v_patch53_missed_operating_cadence_register"."cadence_type" || ' is missed or overdue.'::"text")) AS "blocker_summary",
    "v_patch53_missed_operating_cadence_register"."evidence_reference"
   FROM "public"."v_patch53_missed_operating_cadence_register"
UNION ALL
 SELECT "v_patch53_missing_department_feedback_register"."hypercare_period_id",
    "v_patch53_missing_department_feedback_register"."hypercare_label",
    'department_feedback'::"text" AS "blocker_area",
    "v_patch53_missing_department_feedback_register"."feedback_status" AS "blocker_type",
    (COALESCE("v_patch53_missing_department_feedback_register"."department_name", 'Department'::"text") || ' feedback is pending or missing.'::"text") AS "blocker_summary",
    "v_patch53_missing_department_feedback_register"."issue_reference" AS "evidence_reference"
   FROM "public"."v_patch53_missing_department_feedback_register"
UNION ALL
 SELECT "v_patch53_low_adoption_register"."hypercare_period_id",
    "v_patch53_low_adoption_register"."hypercare_label",
    'adoption_feedback'::"text" AS "blocker_area",
    "v_patch53_low_adoption_register"."adoption_status" AS "blocker_type",
    (COALESCE("v_patch53_low_adoption_register"."department_name", 'Department'::"text") || ' requires adoption, support, or training follow-up.'::"text") AS "blocker_summary",
    "v_patch53_low_adoption_register"."issue_reference" AS "evidence_reference"
   FROM "public"."v_patch53_low_adoption_register"
UNION ALL
 SELECT NULL::"uuid" AS "hypercare_period_id",
    "v_patch51_live_pilot_execution_issue_register"."workflow_label" AS "hypercare_label",
    'live_pilot_issue'::"text" AS "blocker_area",
    "v_patch51_live_pilot_execution_issue_register"."issue_type" AS "blocker_type",
    "v_patch51_live_pilot_execution_issue_register"."issue_summary" AS "blocker_summary",
    "v_patch51_live_pilot_execution_issue_register"."evidence_reference"
   FROM "public"."v_patch51_live_pilot_execution_issue_register"
  WHERE (("v_patch51_live_pilot_execution_issue_register"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("v_patch51_live_pilot_execution_issue_register"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))
UNION ALL
 SELECT NULL::"uuid" AS "hypercare_period_id",
    "v_patch52_open_high_critical_remediation_register"."closure_label" AS "hypercare_label",
    'pilot_remediation'::"text" AS "blocker_area",
    "v_patch52_open_high_critical_remediation_register"."remediation_status" AS "blocker_type",
    "v_patch52_open_high_critical_remediation_register"."remediation_title" AS "blocker_summary",
    "v_patch52_open_high_critical_remediation_register"."evidence_reference"
   FROM "public"."v_patch52_open_high_critical_remediation_register";

CREATE OR REPLACE VIEW "public"."v_patch53_hypercare_stability_summary" WITH ("security_invoker"='true') AS
 WITH "periods" AS (
         SELECT ("count"(*))::integer AS "hypercare_period_total",
            ("count"(*) FILTER (WHERE ("production_hypercare_periods"."hypercare_status" = 'active'::"text")))::integer AS "active_hypercare_periods",
            ("count"(*) FILTER (WHERE ("production_hypercare_periods"."hypercare_status" = ANY (ARRAY['at_risk'::"text", 'blocked'::"text", 'extended'::"text"]))))::integer AS "at_risk_or_blocked_periods",
            "min"(GREATEST(COALESCE(("production_hypercare_periods"."target_end_date" - CURRENT_DATE), 0), 0)) FILTER (WHERE ("production_hypercare_periods"."hypercare_status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'at_risk'::"text", 'blocked'::"text", 'extended'::"text"]))) AS "days_remaining"
           FROM "public"."production_hypercare_periods"
        ), "issues" AS (
         SELECT ("count"(*) FILTER (WHERE ("production_hypercare_issues"."issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"]))))::integer AS "open_hypercare_issues",
            ("count"(*) FILTER (WHERE (("production_hypercare_issues"."issue_status" = 'overdue'::"text") OR (("production_hypercare_issues"."issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("production_hypercare_issues"."due_at" IS NOT NULL) AND ("production_hypercare_issues"."due_at" < "now"())))))::integer AS "overdue_hypercare_issues",
            ("count"(*) FILTER (WHERE (("production_hypercare_issues"."issue_status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'overdue'::"text"])) AND ("production_hypercare_issues"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))))::integer AS "high_critical_hypercare_issues"
           FROM "public"."production_hypercare_issues"
        ), "cadence" AS (
         SELECT ("count"(*) FILTER (WHERE (("production_operating_cadence_events"."event_status" = 'missed'::"text") OR (("production_operating_cadence_events"."event_status" = 'scheduled'::"text") AND ("production_operating_cadence_events"."scheduled_at" IS NOT NULL) AND ("production_operating_cadence_events"."scheduled_at" < "now"())))))::integer AS "missed_cadence_events"
           FROM "public"."production_operating_cadence_events"
        ), "feedback" AS (
         SELECT ("count"(*) FILTER (WHERE ("production_adoption_feedback"."feedback_status" = 'pending'::"text")))::integer AS "departments_missing_feedback",
            ("count"(*) FILTER (WHERE ("production_adoption_feedback"."adoption_status" = ANY (ARRAY['low_adoption'::"text", 'blocked'::"text"]))))::integer AS "low_adoption_departments",
            ("count"(*) FILTER (WHERE "production_adoption_feedback"."support_needed"))::integer AS "support_needed_feedback_count",
            ("count"(*) FILTER (WHERE "production_adoption_feedback"."training_needed"))::integer AS "training_needed_feedback_count"
           FROM "public"."production_adoption_feedback"
        ), "missing_feedback" AS (
         SELECT ("count"(*))::integer AS "computed_missing_feedback_count"
           FROM "public"."v_patch53_missing_department_feedback_register"
        ), "live_issues" AS (
         SELECT ("count"(*) FILTER (WHERE (("live_pilot_execution_issues"."issue_status" = ANY (ARRAY['open'::"text", 'in_review'::"text"])) AND ("live_pilot_execution_issues"."severity" = ANY (ARRAY['high'::"text", 'critical'::"text"])))))::integer AS "inherited_unresolved_live_pilot_issues"
           FROM "public"."live_pilot_execution_issues"
        ), "remediation" AS (
         SELECT ("count"(*))::integer AS "inherited_high_critical_remediation_count"
           FROM "public"."v_patch52_open_high_critical_remediation_register"
        ), "blockers" AS (
         SELECT ("count"(*))::integer AS "hypercare_blocker_count"
           FROM "public"."v_patch53_hypercare_blocker_register"
        )
 SELECT COALESCE(( SELECT "periods"."hypercare_period_total"
           FROM "periods"), 0) AS "hypercare_period_total",
    COALESCE(( SELECT "periods"."active_hypercare_periods"
           FROM "periods"), 0) AS "active_hypercare_periods",
    COALESCE(( SELECT "periods"."at_risk_or_blocked_periods"
           FROM "periods"), 0) AS "at_risk_or_blocked_periods",
    COALESCE(( SELECT "periods"."days_remaining"
           FROM "periods"), 0) AS "days_remaining",
    COALESCE(( SELECT "issues"."open_hypercare_issues"
           FROM "issues"), 0) AS "open_hypercare_issues",
    COALESCE(( SELECT "issues"."overdue_hypercare_issues"
           FROM "issues"), 0) AS "overdue_hypercare_issues",
    COALESCE(( SELECT "issues"."high_critical_hypercare_issues"
           FROM "issues"), 0) AS "high_critical_hypercare_issues",
    COALESCE(( SELECT "cadence"."missed_cadence_events"
           FROM "cadence"), 0) AS "missed_cadence_events",
    GREATEST(COALESCE(( SELECT "feedback"."departments_missing_feedback"
           FROM "feedback"), 0), COALESCE(( SELECT "missing_feedback"."computed_missing_feedback_count"
           FROM "missing_feedback"), 0)) AS "departments_missing_feedback",
    COALESCE(( SELECT "feedback"."low_adoption_departments"
           FROM "feedback"), 0) AS "low_adoption_departments",
    COALESCE(( SELECT "feedback"."support_needed_feedback_count"
           FROM "feedback"), 0) AS "support_needed_feedback_count",
    COALESCE(( SELECT "feedback"."training_needed_feedback_count"
           FROM "feedback"), 0) AS "training_needed_feedback_count",
    COALESCE(( SELECT "live_issues"."inherited_unresolved_live_pilot_issues"
           FROM "live_issues"), 0) AS "inherited_unresolved_live_pilot_issues",
    COALESCE(( SELECT "remediation"."inherited_high_critical_remediation_count"
           FROM "remediation"), 0) AS "inherited_high_critical_remediation_count",
    COALESCE(( SELECT "blockers"."hypercare_blocker_count"
           FROM "blockers"), 0) AS "hypercare_blocker_count",
        CASE
            WHEN (COALESCE(( SELECT "periods"."hypercare_period_total"
               FROM "periods"), 0) = 0) THEN 'evidence_required'::"text"
            WHEN ((COALESCE(( SELECT "periods"."at_risk_or_blocked_periods"
               FROM "periods"), 0) > 0) OR (COALESCE(( SELECT "issues"."high_critical_hypercare_issues"
               FROM "issues"), 0) > 0) OR (COALESCE(( SELECT "issues"."overdue_hypercare_issues"
               FROM "issues"), 0) > 0) OR (COALESCE(( SELECT "cadence"."missed_cadence_events"
               FROM "cadence"), 0) > 0) OR (COALESCE(( SELECT "live_issues"."inherited_unresolved_live_pilot_issues"
               FROM "live_issues"), 0) > 0) OR (COALESCE(( SELECT "remediation"."inherited_high_critical_remediation_count"
               FROM "remediation"), 0) > 0)) THEN 'blocked'::"text"
            WHEN ((COALESCE(( SELECT "issues"."open_hypercare_issues"
               FROM "issues"), 0) > 0) OR (GREATEST(COALESCE(( SELECT "feedback"."departments_missing_feedback"
               FROM "feedback"), 0), COALESCE(( SELECT "missing_feedback"."computed_missing_feedback_count"
               FROM "missing_feedback"), 0)) > 0) OR (COALESCE(( SELECT "feedback"."low_adoption_departments"
               FROM "feedback"), 0) > 0) OR (COALESCE(( SELECT "feedback"."support_needed_feedback_count"
               FROM "feedback"), 0) > 0) OR (COALESCE(( SELECT "feedback"."training_needed_feedback_count"
               FROM "feedback"), 0) > 0)) THEN 'at_risk'::"text"
            WHEN (COALESCE(( SELECT "periods"."active_hypercare_periods"
               FROM "periods"), 0) > 0) THEN 'in_progress'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."production_hypercare_periods"
              WHERE ("production_hypercare_periods"."hypercare_status" = 'stable'::"text"))) THEN 'stable_with_limitations'::"text"
            WHEN (EXISTS ( SELECT 1
               FROM "public"."production_hypercare_periods"
              WHERE ("production_hypercare_periods"."hypercare_status" = 'completed'::"text"))) THEN 'stable'::"text"
            ELSE 'evidence_required'::"text"
        END AS "production_stability_status";

CREATE OR REPLACE VIEW "public"."v_patch53_open_high_critical_hypercare_issue_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "hypercare_period_id",
    "source_workflow_run_id",
    "source_execution_issue_id",
    "issue_title",
    "issue_type",
    "issue_status",
    "severity",
    "department_pilot_id",
    "owner_user_id",
    "due_at",
    "resolved_at",
    "resolution_summary",
    "evidence_reference",
    "created_by",
    "created_at",
    "updated_at",
    "hypercare_label",
    "is_overdue",
    "is_high_critical_open"
   FROM "public"."v_patch53_hypercare_issue_register"
  WHERE "is_high_critical_open";

CREATE OR REPLACE VIEW "public"."v_patch53_overdue_hypercare_issue_register" WITH ("security_invoker"='true') AS
 SELECT "id",
    "hypercare_period_id",
    "source_workflow_run_id",
    "source_execution_issue_id",
    "issue_title",
    "issue_type",
    "issue_status",
    "severity",
    "department_pilot_id",
    "owner_user_id",
    "due_at",
    "resolved_at",
    "resolution_summary",
    "evidence_reference",
    "created_by",
    "created_at",
    "updated_at",
    "hypercare_label",
    "is_overdue",
    "is_high_critical_open"
   FROM "public"."v_patch53_hypercare_issue_register"
  WHERE (("issue_status" = 'overdue'::"text") OR "is_overdue");

CREATE OR REPLACE VIEW "public"."v_patch53_production_readiness_hypercare_overlay" WITH ("security_invoker"='true') AS
 SELECT "hypercare_period_total",
    "active_hypercare_periods",
    "at_risk_or_blocked_periods",
    "days_remaining",
    "open_hypercare_issues",
    "overdue_hypercare_issues",
    "high_critical_hypercare_issues",
    "missed_cadence_events",
    "departments_missing_feedback",
    "low_adoption_departments",
    "support_needed_feedback_count",
    "training_needed_feedback_count",
    "inherited_unresolved_live_pilot_issues",
    "inherited_high_critical_remediation_count",
    "hypercare_blocker_count",
    "production_stability_status",
        CASE
            WHEN ("production_stability_status" = 'stable'::"text") THEN 'Production hypercare is complete with no open stability blockers recorded.'::"text"
            WHEN ("production_stability_status" = 'stable_with_limitations'::"text") THEN 'Production is stable with documented monitoring and follow-up limitations.'::"text"
            WHEN ("production_stability_status" = 'blocked'::"text") THEN 'Resolve high-risk issues, SLA breaches, missed cadence, or inherited blockers before hypercare closure.'::"text"
            WHEN ("production_stability_status" = 'at_risk'::"text") THEN 'Triage open issues, adoption gaps, feedback gaps, and support needs in the operating cadence.'::"text"
            WHEN ("production_stability_status" = 'in_progress'::"text") THEN 'Continue the active hypercare cadence until stability evidence is complete.'::"text"
            ELSE 'Create a production hypercare period and begin operating cadence evidence capture.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch53_hypercare_stability_summary";

CREATE OR REPLACE VIEW "public"."v_patch55_department_adoption_readiness_register" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."launch_pack_id",
    "r"."controlled_pilot_department_id",
    "r"."adoption_status",
    "r"."active_user_count",
    "r"."inactive_user_count",
    "r"."training_incomplete_count",
    "r"."failed_workflow_attempt_count",
    "r"."feedback_required_count",
    "r"."support_needed",
    "r"."training_needed",
    "r"."adoption_summary",
    "r"."owner_user_id",
    "r"."evidence_reference",
    "r"."reviewed_at",
    "r"."created_by",
    "r"."created_at",
    "r"."updated_at",
    "p"."launch_label",
    "p"."controlled_pilot_department_id" AS "pack_department_pilot_id",
    COALESCE("d"."department_name", "p"."launch_label") AS "department_name",
    (("r"."adoption_status" = ANY (ARRAY['low_adoption'::"text", 'blocked'::"text"])) OR ("r"."inactive_user_count" > 0) OR ("r"."training_incomplete_count" > 0) OR ("r"."failed_workflow_attempt_count" > 0) OR ("r"."feedback_required_count" > 0) OR "r"."support_needed" OR "r"."training_needed") AS "has_adoption_blocker"
   FROM (("public"."hospital_adoption_readiness_reviews" "r"
     LEFT JOIN "public"."hospital_department_launch_packs" "p" ON (("p"."id" = "r"."launch_pack_id")))
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = COALESCE("r"."controlled_pilot_department_id", "p"."controlled_pilot_department_id"))));

CREATE OR REPLACE VIEW "public"."v_patch55_department_launch_checklist_register" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."launch_pack_id",
    "c"."checklist_key",
    "c"."checklist_status",
    "c"."owner_user_id",
    "c"."due_at",
    "c"."completed_at",
    "c"."evidence_reference",
    "c"."notes",
    "c"."created_by",
    "c"."created_at",
    "c"."updated_at",
    "p"."launch_label",
    "p"."controlled_pilot_department_id",
    COALESCE("d"."department_name", "p"."launch_label") AS "department_name",
    ("c"."checklist_status" = ANY (ARRAY['pending'::"text", 'evidence_required'::"text", 'blocked'::"text"])) AS "is_incomplete_required"
   FROM (("public"."hospital_department_launch_checklist_items" "c"
     LEFT JOIN "public"."hospital_department_launch_packs" "p" ON (("p"."id" = "c"."launch_pack_id")))
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "p"."controlled_pilot_department_id")));

CREATE OR REPLACE VIEW "public"."v_patch55_department_launch_pack_register" WITH ("security_invoker"='true') AS
 SELECT "p"."id",
    "p"."controlled_pilot_department_id",
    "p"."department_id",
    "p"."launch_label",
    "p"."launch_status",
    "p"."department_owner_user_id",
