    "p"."support_owner_user_id",
    "p"."target_launch_date",
    "p"."actual_launch_date",
    "p"."readiness_summary",
    "p"."blocker_summary",
    "p"."evidence_reference",
    "p"."created_by",
    "p"."created_at",
    "p"."updated_at",
    "d"."department_name",
    ("p"."department_owner_user_id" IS NULL) AS "missing_department_owner",
    ("p"."support_owner_user_id" IS NULL) AS "missing_support_owner",
    (("p"."launch_status" = ANY (ARRAY['ready'::"text", 'ready_with_limitations'::"text"])) AND ("p"."department_owner_user_id" IS NOT NULL) AND ("p"."support_owner_user_id" IS NOT NULL)) AS "appears_ready_by_status"
   FROM ("public"."hospital_department_launch_packs" "p"
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = "p"."controlled_pilot_department_id")));

CREATE OR REPLACE VIEW "public"."v_patch55_department_support_readiness_register" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."launch_pack_id",
    "s"."controlled_pilot_department_id",
    "s"."support_status",
    "s"."support_owner_user_id",
    "s"."escalation_owner_user_id",
