    (("s"."support_status" = ANY (ARRAY['pending'::"text", 'blocked'::"text"])) OR ("s"."support_owner_user_id" IS NULL) OR ("s"."critical_support_issue_count" > 0)) AS "has_support_blocker"
   FROM (("public"."hospital_support_readiness_records" "s"
     LEFT JOIN "public"."hospital_department_launch_packs" "p" ON (("p"."id" = "s"."launch_pack_id")))
