CREATE OR REPLACE VIEW "public"."v_patch55_policy_attestation_readiness_register" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."launch_pack_id",
    "a"."controlled_pilot_department_id",
    "a"."policy_title",
    "a"."policy_category",
    "a"."attestation_status",
    "a"."required_for_role",
    "a"."required_attestation_count",
    "a"."completed_attestation_count",
    "a"."due_at",
    "a"."evidence_reference",
    "a"."owner_user_id",
    "a"."notes",
    "a"."created_by",
    "a"."created_at",
    "a"."updated_at",
