    "p"."controlled_pilot_department_id" AS "pack_department_pilot_id",
    COALESCE("d"."department_name", "p"."launch_label") AS "department_name",
    (("a"."attestation_status" = ANY (ARRAY['pending'::"text", 'partially_attested'::"text", 'overdue'::"text", 'blocked'::"text"])) OR ("a"."required_attestation_count" > "a"."completed_attestation_count")) AS "has_attestation_gap"
   FROM (("public"."hospital_policy_attestation_readiness" "a"
     LEFT JOIN "public"."hospital_department_launch_packs" "p" ON (("p"."id" = "a"."launch_pack_id")))
     LEFT JOIN "public"."controlled_pilot_departments" "d" ON (("d"."id" = COALESCE("a"."controlled_pilot_department_id", "p"."controlled_pilot_department_id"))));

