CREATE OR REPLACE VIEW "public"."v_patch55_department_launch_blocker_register" WITH ("security_invoker"='true') AS
 SELECT "p"."id" AS "launch_pack_id",
    "p"."controlled_pilot_department_id",
    COALESCE("p"."department_name", "p"."launch_label") AS "department_name",
    'launch_status'::"text" AS "blocker_type",
        CASE
            WHEN ("p"."launch_status" = 'blocked'::"text") THEN COALESCE("p"."blocker_summary", 'Department launch is blocked.'::"text")
            WHEN ("p"."department_owner_user_id" IS NULL) THEN 'Department launch owner is required.'::"text"
            WHEN ("p"."support_owner_user_id" IS NULL) THEN 'Support owner and escalation path are required.'::"text"
            ELSE 'Department launch evidence is required.'::"text"
        END AS "blocker_reason",
    "p"."evidence_reference"
   FROM "public"."v_patch55_department_launch_pack_register" "p"
  WHERE (("p"."launch_status" = ANY (ARRAY['draft'::"text", 'in_progress'::"text", 'ready_for_review'::"text", 'blocked'::"text"])) OR ("p"."department_owner_user_id" IS NULL) OR ("p"."support_owner_user_id" IS NULL))
UNION ALL
 SELECT "v_patch55_incomplete_launch_checklist_register"."launch_pack_id",
    "v_patch55_incomplete_launch_checklist_register"."controlled_pilot_department_id",
    "v_patch55_incomplete_launch_checklist_register"."department_name",
    "v_patch55_incomplete_launch_checklist_register"."checklist_key" AS "blocker_type",
    ('Launch checklist item is incomplete: '::"text" || "v_patch55_incomplete_launch_checklist_register"."checklist_key") AS "blocker_reason",
    "v_patch55_incomplete_launch_checklist_register"."evidence_reference"
   FROM "public"."v_patch55_incomplete_launch_checklist_register"
UNION ALL
 SELECT "v_patch55_support_readiness_blocker_register"."launch_pack_id",
    COALESCE("v_patch55_support_readiness_blocker_register"."controlled_pilot_department_id", "v_patch55_support_readiness_blocker_register"."pack_department_pilot_id") AS "controlled_pilot_department_id",
    "v_patch55_support_readiness_blocker_register"."department_name",
    'support_readiness'::"text" AS "blocker_type",
        CASE
            WHEN ("v_patch55_support_readiness_blocker_register"."support_owner_user_id" IS NULL) THEN 'Support owner is required.'::"text"
            WHEN ("v_patch55_support_readiness_blocker_register"."support_status" = ANY (ARRAY['pending'::"text", 'blocked'::"text"])) THEN 'Support readiness is pending or blocked.'::"text"
            WHEN ("v_patch55_support_readiness_blocker_register"."critical_support_issue_count" > 0) THEN 'Critical support issues remain open.'::"text"
            ELSE 'Support readiness evidence is required.'::"text"
        END AS "blocker_reason",
    "v_patch55_support_readiness_blocker_register"."evidence_reference"
   FROM "public"."v_patch55_support_readiness_blocker_register"
UNION ALL
 SELECT "v_patch55_missing_policy_attestation_register"."launch_pack_id",
    COALESCE("v_patch55_missing_policy_attestation_register"."controlled_pilot_department_id", "v_patch55_missing_policy_attestation_register"."pack_department_pilot_id") AS "controlled_pilot_department_id",
    "v_patch55_missing_policy_attestation_register"."department_name",
    'policy_attestation'::"text" AS "blocker_type",
    ('Policy or SOP attestation is incomplete for '::"text" || "v_patch55_missing_policy_attestation_register"."policy_title") AS "blocker_reason",
    "v_patch55_missing_policy_attestation_register"."evidence_reference"
   FROM "public"."v_patch55_missing_policy_attestation_register"
UNION ALL
 SELECT "v_patch55_low_adoption_department_register"."launch_pack_id",
    COALESCE("v_patch55_low_adoption_department_register"."controlled_pilot_department_id", "v_patch55_low_adoption_department_register"."pack_department_pilot_id") AS "controlled_pilot_department_id",
    "v_patch55_low_adoption_department_register"."department_name",
    'adoption_readiness'::"text" AS "blocker_type",
        CASE
            WHEN ("v_patch55_low_adoption_department_register"."adoption_status" = ANY (ARRAY['low_adoption'::"text", 'blocked'::"text"])) THEN 'Department adoption is low or blocked.'::"text"
            WHEN ("v_patch55_low_adoption_department_register"."inactive_user_count" > 0) THEN 'Inactive users remain in department launch scope.'::"text"
            WHEN ("v_patch55_low_adoption_department_register"."training_incomplete_count" > 0) THEN 'Training remains incomplete.'::"text"
            WHEN ("v_patch55_low_adoption_department_register"."failed_workflow_attempt_count" > 0) THEN 'Failed workflow attempts require follow-up.'::"text"
            ELSE 'Department adoption follow-up is required.'::"text"
        END AS "blocker_reason",
    "v_patch55_low_adoption_department_register"."evidence_reference"
   FROM "public"."v_patch55_low_adoption_department_register"
UNION ALL
 SELECT NULL::"uuid" AS "launch_pack_id",
    NULL::"uuid" AS "controlled_pilot_department_id",
    COALESCE("v_patch52_pilot_closure_blocker_register"."blocker_area", 'Pilot closure'::"text") AS "department_name",
    'pilot_closure'::"text" AS "blocker_type",
    "v_patch52_pilot_closure_blocker_register"."blocker_summary" AS "blocker_reason",
    "v_patch52_pilot_closure_blocker_register"."evidence_reference"
   FROM "public"."v_patch52_pilot_closure_blocker_register"
  WHERE ("v_patch52_pilot_closure_blocker_register"."blocker_type" = ANY (ARRAY['high'::"text", 'critical'::"text", 'blocked'::"text", 'overdue'::"text"]))
UNION ALL
 SELECT NULL::"uuid" AS "launch_pack_id",
    NULL::"uuid" AS "controlled_pilot_department_id",
    COALESCE("v_patch53_hypercare_blocker_register"."blocker_area", 'Hypercare'::"text") AS "department_name",
    'hypercare'::"text" AS "blocker_type",
    "v_patch53_hypercare_blocker_register"."blocker_summary" AS "blocker_reason",
    "v_patch53_hypercare_blocker_register"."evidence_reference"
   FROM "public"."v_patch53_hypercare_blocker_register";

CREATE OR REPLACE VIEW "public"."v_patch55_hospital_operations_readiness_summary" WITH ("security_invoker"='true') AS
 WITH "packs" AS (
         SELECT ("count"(*))::integer AS "total_department_launch_packs",
            ("count"(*) FILTER (WHERE (("hospital_department_launch_packs"."launch_status" = 'ready'::"text") AND ("hospital_department_launch_packs"."department_owner_user_id" IS NOT NULL) AND ("hospital_department_launch_packs"."support_owner_user_id" IS NOT NULL))))::integer AS "ready_departments",
            ("count"(*) FILTER (WHERE ("hospital_department_launch_packs"."launch_status" = 'ready_with_limitations'::"text")))::integer AS "ready_with_limitations_departments",
            ("count"(*) FILTER (WHERE ("hospital_department_launch_packs"."launch_status" = 'blocked'::"text")))::integer AS "blocked_departments",
            ("count"(*) FILTER (WHERE (("hospital_department_launch_packs"."launch_status" = ANY (ARRAY['draft'::"text", 'in_progress'::"text", 'ready_for_review'::"text"])) OR ("hospital_department_launch_packs"."department_owner_user_id" IS NULL) OR ("hospital_department_launch_packs"."support_owner_user_id" IS NULL))))::integer AS "evidence_required_departments",
            ("count"(*) FILTER (WHERE ("hospital_department_launch_packs"."department_owner_user_id" IS NULL)))::integer AS "missing_owner_count"
           FROM "public"."hospital_department_launch_packs"
        ), "checklist" AS (
         SELECT ("count"(*))::integer AS "incomplete_launch_checklist_items"
           FROM "public"."v_patch55_incomplete_launch_checklist_register"
        ), "support" AS (
         SELECT ("count"(*))::integer AS "support_readiness_blockers",
            (COALESCE("sum"("v_patch55_support_readiness_blocker_register"."critical_support_issue_count"), (0)::bigint))::integer AS "critical_support_issues"
           FROM "public"."v_patch55_support_readiness_blocker_register"
        ), "policy" AS (
         SELECT ("count"(*))::integer AS "policy_attestation_gaps"
           FROM "public"."v_patch55_missing_policy_attestation_register"
        ), "adoption" AS (
         SELECT ("count"(*))::integer AS "low_adoption_departments",
            (COALESCE("sum"("v_patch55_low_adoption_department_register"."inactive_user_count"), (0)::bigint))::integer AS "inactive_users",
            (COALESCE("sum"("v_patch55_low_adoption_department_register"."training_incomplete_count"), (0)::bigint))::integer AS "training_incomplete_count",
            (COALESCE("sum"("v_patch55_low_adoption_department_register"."failed_workflow_attempt_count"), (0)::bigint))::integer AS "failed_workflow_attempt_count"
           FROM "public"."v_patch55_low_adoption_department_register"
        ), "blockers" AS (
         SELECT ("count"(*))::integer AS "department_launch_blocker_count"
           FROM "public"."v_patch55_department_launch_blocker_register"
        )
 SELECT COALESCE(( SELECT "packs"."total_department_launch_packs"
           FROM "packs"), 0) AS "total_department_launch_packs",
    COALESCE(( SELECT "packs"."ready_departments"
           FROM "packs"), 0) AS "ready_departments",
    COALESCE(( SELECT "packs"."ready_with_limitations_departments"
           FROM "packs"), 0) AS "ready_with_limitations_departments",
    COALESCE(( SELECT "packs"."blocked_departments"
           FROM "packs"), 0) AS "blocked_departments",
    COALESCE(( SELECT "packs"."evidence_required_departments"
           FROM "packs"), 0) AS "evidence_required_departments",
    COALESCE(( SELECT "checklist"."incomplete_launch_checklist_items"
           FROM "checklist"), 0) AS "incomplete_launch_checklist_items",
    COALESCE(( SELECT "packs"."missing_owner_count"
           FROM "packs"), 0) AS "missing_owner_count",
    COALESCE(( SELECT "support"."support_readiness_blockers"
           FROM "support"), 0) AS "support_readiness_blockers",
    COALESCE(( SELECT "policy"."policy_attestation_gaps"
           FROM "policy"), 0) AS "policy_attestation_gaps",
    COALESCE(( SELECT "adoption"."low_adoption_departments"
           FROM "adoption"), 0) AS "low_adoption_departments",
    COALESCE(( SELECT "adoption"."inactive_users"
           FROM "adoption"), 0) AS "inactive_users",
    COALESCE(( SELECT "adoption"."training_incomplete_count"
           FROM "adoption"), 0) AS "training_incomplete_count",
    COALESCE(( SELECT "adoption"."failed_workflow_attempt_count"
           FROM "adoption"), 0) AS "failed_workflow_attempt_count",
    COALESCE(( SELECT "support"."critical_support_issues"
           FROM "support"), 0) AS "critical_support_issues",
    COALESCE(( SELECT "blockers"."department_launch_blocker_count"
           FROM "blockers"), 0) AS "department_launch_blocker_count",
        CASE
            WHEN (COALESCE(( SELECT "packs"."total_department_launch_packs"
               FROM "packs"), 0) = 0) THEN 'evidence_required'::"text"
            WHEN ((COALESCE(( SELECT "blockers"."department_launch_blocker_count"
               FROM "blockers"), 0) > 0) OR (COALESCE(( SELECT "packs"."blocked_departments"
               FROM "packs"), 0) > 0) OR (COALESCE(( SELECT "support"."critical_support_issues"
               FROM "support"), 0) > 0) OR (COALESCE(( SELECT "adoption"."low_adoption_departments"
               FROM "adoption"), 0) > 0)) THEN 'blocked'::"text"
            WHEN ((COALESCE(( SELECT "packs"."evidence_required_departments"
               FROM "packs"), 0) > 0) OR (COALESCE(( SELECT "checklist"."incomplete_launch_checklist_items"
               FROM "checklist"), 0) > 0) OR (COALESCE(( SELECT "support"."support_readiness_blockers"
               FROM "support"), 0) > 0) OR (COALESCE(( SELECT "policy"."policy_attestation_gaps"
               FROM "policy"), 0) > 0) OR (COALESCE(( SELECT "adoption"."training_incomplete_count"
               FROM "adoption"), 0) > 0)) THEN 'evidence_required'::"text"
            WHEN (COALESCE(( SELECT "packs"."ready_with_limitations_departments"
               FROM "packs"), 0) > 0) THEN 'ready_with_limitations'::"text"
            WHEN (COALESCE(( SELECT "packs"."ready_departments"
               FROM "packs"), 0) = COALESCE(( SELECT "packs"."total_department_launch_packs"
               FROM "packs"), 0)) THEN 'ready'::"text"
            ELSE 'in_progress'::"text"
        END AS "hospital_operations_readiness_status";

CREATE OR REPLACE VIEW "public"."v_patch55_production_readiness_hospital_operations_overlay" WITH ("security_invoker"='true') AS
 SELECT "total_department_launch_packs",
    "ready_departments",
    "ready_with_limitations_departments",
    "blocked_departments",
    "evidence_required_departments",
    "incomplete_launch_checklist_items",
    "missing_owner_count",
    "support_readiness_blockers",
    "policy_attestation_gaps",
    "low_adoption_departments",
    "inactive_users",
    "training_incomplete_count",
    "failed_workflow_attempt_count",
    "critical_support_issues",
    "department_launch_blocker_count",
    "hospital_operations_readiness_status",
        CASE
            WHEN ("hospital_operations_readiness_status" = 'ready'::"text") THEN 'All department launch packs are ready with required owners, support paths, checklist evidence, training, attestations, and signoffs recorded.'::"text"
            WHEN ("hospital_operations_readiness_status" = 'ready_with_limitations'::"text") THEN 'Hospital operations are ready with documented limitations that require executive review.'::"text"
            WHEN ("hospital_operations_readiness_status" = 'blocked'::"text") THEN 'Resolve blocked departments, critical support issues, low adoption, or inherited launch blockers before hospital-wide rollout.'::"text"
            WHEN ("hospital_operations_readiness_status" = 'evidence_required'::"text") THEN 'Record department owners, checklist evidence, training, policy/SOP attestations, signoffs, and support readiness before hospital-wide rollout.'::"text"
            ELSE 'Continue department launch preparation and close remaining readiness actions.'::"text"
        END AS "next_action_required"
   FROM "public"."v_patch55_hospital_operations_readiness_summary";

CREATE OR REPLACE VIEW "public"."v_pending_approvals_expanded" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."organization_id",
        CASE
            WHEN ("a"."project_id" IS NOT NULL) THEN 'project'::"text"
            WHEN ("a"."milestone_id" IS NOT NULL) THEN 'milestone'::"text"
            WHEN ("a"."task_id" IS NOT NULL) THEN 'task'::"text"
            WHEN ("a"."evidence_id" IS NOT NULL) THEN 'evidence'::"text"
            WHEN ("a"."risk_id" IS NOT NULL) THEN 'risk'::"text"
            WHEN ("a"."compliance_item_id" IS NOT NULL) THEN 'compliance'::"text"
            WHEN ("a"."audit_finding_id" IS NOT NULL) THEN 'audit_finding'::"text"
            WHEN ("a"."policy_id" IS NOT NULL) THEN 'policy'::"text"
            WHEN ("a"."committee_decision_id" IS NOT NULL) THEN 'governance_decision'::"text"
            ELSE 'unknown'::"text"
        END AS "item_type",
    COALESCE("p"."title", "m"."title", "t"."title", "e"."file_name", "r"."title", "c"."title", "af"."title", "pol"."title", "cd"."title", 'Untitled item'::"text") AS "item_title",
    "rb"."full_name_en" AS "requested_by_name",
    "ap"."full_name_en" AS "approver_name",
    "a"."status",
    "a"."request_note",
    "a"."decision_note",
    "a"."requested_at",
    "a"."decided_at"
   FROM ((((((((((("public"."approvals" "a"
     LEFT JOIN "public"."projects" "p" ON (("p"."id" = "a"."project_id")))
     LEFT JOIN "public"."milestones" "m" ON (("m"."id" = "a"."milestone_id")))
     LEFT JOIN "public"."tasks" "t" ON (("t"."id" = "a"."task_id")))
     LEFT JOIN "public"."evidence_files" "e" ON (("e"."id" = "a"."evidence_id")))
     LEFT JOIN "public"."risks" "r" ON (("r"."id" = "a"."risk_id")))
     LEFT JOIN "public"."compliance_items" "c" ON (("c"."id" = "a"."compliance_item_id")))
     LEFT JOIN "public"."audit_findings" "af" ON (("af"."id" = "a"."audit_finding_id")))
     LEFT JOIN "public"."policies" "pol" ON (("pol"."id" = "a"."policy_id")))
     LEFT JOIN "public"."committee_decisions" "cd" ON (("cd"."id" = "a"."committee_decision_id")))
     LEFT JOIN "public"."profiles" "rb" ON (("rb"."id" = "a"."requested_by")))
     LEFT JOIN "public"."profiles" "ap" ON (("ap"."id" = "a"."approver_id")))
  WHERE (("a"."status" = 'pending'::"public"."approval_status") AND (("a"."approver_id" = "auth"."uid"()) OR "public"."can_manage_grc"()));

CREATE OR REPLACE VIEW "public"."v_permission_test_personas" WITH ("security_invoker"='true') AS
 SELECT "persona_key",
    "role_name",
    "scope_name",
    "expected_visibility_en",
    "expected_visibility_ar",
    "must_block_en",
    "must_block_ar",
    "test_steps_en",
    "test_steps_ar",
    "risk_level"
   FROM ( VALUES ('executive_global'::"text",'executive'::"text",'global'::"text",'All dashboards, critical risks, major OVRs, approvals and executive reports.'::"text",'كل اللوحات والمخاطر الحرجة وبلاغات OVR الكبرى والموافقات والتقارير التنفيذية.'::"text",'Direct database administration and Quality-only OVR closure unless Quality role is also granted.'::"text",'إدارة قاعدة البيانات المباشرة وإغلاق OVR الخاص بالجودة ما لم تمنح له صلاحية الجودة.'::"text",'Login, open executive pages, confirm visibility, then try restricted closure actions.'::"text",'سجل الدخول وافتح الصفحات التنفيذية ثم جرّب إجراءات الإغلاق المقيدة.'::"text",'high'::"text"), ('governance_admin_global'::"text",'governance_admin'::"text",'global'::"text",'GRC workflows, risk, compliance, audit follow-up, projects, escalations and reports.'::"text",'مسارات الحوكمة والمخاطر والالتزام والمراجعة والمشاريع والتصعيدات والتقارير.'::"text",'System-level user management unless also super admin.'::"text",'إدارة المستخدمين على مستوى النظام ما لم يكن مديراً عاماً أيضاً.'::"text",'Verify GRC management access and restricted admin actions.'::"text",'تحقق من إدارة GRC ومنع الإجراءات الإدارية المقيدة.'::"text",'high'::"text"), ('department_manager_department'::"text",'department_manager'::"text",'department'::"text",'Own department projects, tasks, OVRs, evidence requests and follow-up queues.'::"text",'مشاريع ومهام وبلاغات OVR وطلبات الأدلة وقوائم المتابعة الخاصة بالإدارة.'::"text",'Other departments, access control, audit closure and Quality-only OVR closure.'::"text",'الإدارات الأخرى، الصلاحيات، إغلاق المراجعة، وإغلاق OVR الخاص بالجودة.'::"text",'Use two department managers and verify cross-department data isolation.'::"text",'استخدم مديرين من إدارتين وتحقق من عزل البيانات.'::"text",'critical'::"text"), ('quality_manager_global'::"text",'compliance_officer'::"text",'global'::"text",'OVR queues, Quality review, closure controls, OVR risk indicators and evidence review.'::"text",'قوائم OVR ومراجعة الجودة وضوابط الإغلاق ومؤشرات مخاطر OVR ومراجعة الأدلة.'::"text",'Unrelated access-control administration and non-quality approval chains.'::"text",'إدارة الصلاحيات غير المرتبطة ومسارات الموافقات غير الخاصة بالجودة.'::"text",'Submit, return, require action, review evidence and close test OVRs.'::"text",'قدّم وأعد واطلب إجراء وراجع الدليل وأغلق بلاغات اختبارية.'::"text",'critical'::"text"), ('auditor_global'::"text",'auditor'::"text",'global'::"text",'Audit findings, evidence review, closure approval and audit reports.'::"text",'ملاحظات المراجعة ومراجعة الأدلة واعتماد الإغلاق وتقارير المراجعة.'::"text",'Department self-closure and unrelated HR/user admin actions.'::"text",'إغلاق الإدارات الذاتي وإجراءات الموارد البشرية/المستخدمين غير المرتبطة.'::"text",'Create finding, reject weak evidence, approve valid closure.'::"text",'أنشئ ملاحظة وارفض الدليل الضعيف واعتمد الإغلاق الصحيح.'::"text",'high'::"text"), ('employee_assigned_only'::"text",'employee'::"text",'assigned_only'::"text",'My Work, assigned evidence requests, comments and own OVR submissions.'::"text",'أعمالي وطلبات الأدلة المسندة والتعليقات وبلاغات OVR الخاصة به.'::"text",'Executive data, unrelated projects, other employees, access control and approvals.'::"text",'البيانات التنفيذية والمشاريع غير المرتبطة والموظفين الآخرين والصلاحيات والموافقات.'::"text",'Login, search for unrelated data and confirm no results are visible.'::"text",'سجل الدخول وابحث عن بيانات غير مرتبطة وتأكد من عدم ظهورها.'::"text",'critical'::"text")) "p"("persona_key", "role_name", "scope_name", "expected_visibility_en", "expected_visibility_ar", "must_block_en", "must_block_ar", "test_steps_en", "test_steps_ar", "risk_level");

