CREATE OR REPLACE VIEW "public"."v_production_backup_strategy_status" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "strategy_code",
    "title",
    "backup_type",
    "frequency",
    "owner_label",
    "retention_days",
    "includes_storage_files",
    "includes_auth_users",
    "requires_restore_dry_run",
    "status",
    "last_success_at",
    "next_due_date",
    "notes",
    "created_at",
    "updated_at",
        CASE
            WHEN ("status" <> ALL (ARRAY['active'::"text", 'approved'::"text"])) THEN 'not_active'::"text"
            WHEN (("next_due_date" IS NOT NULL) AND ("next_due_date" < CURRENT_DATE)) THEN 'overdue'::"text"
            WHEN ("requires_restore_dry_run" AND (NOT (EXISTS ( SELECT 1
               FROM "public"."backup_restore_verifications" "v"
              WHERE (("v"."organization_id" = "s"."organization_id") AND (("v"."backup_strategy_id" = "s"."id") OR ("v"."backup_strategy_id" IS NULL)) AND ("v"."status" = 'passed'::"text") AND ("v"."finished_at" >= ("now"() - '90 days'::interval))))))) THEN 'restore_test_needed'::"text"
            ELSE 'ok'::"text"
        END AS "backup_signal"
   FROM "public"."production_backup_strategies" "s";

CREATE OR REPLACE VIEW "public"."v_production_cutover_checklist" WITH ("security_invoker"='true') AS
 SELECT "c"."id",
    "c"."organization_id",
    "c"."phase",
    "c"."item",
    "c"."status",
    "c"."owner",
    COALESCE("p"."full_name_en", "c"."owner", 'Unassigned'::"text") AS "owner_name",
    "c"."evidence",
    "c"."notes",
    "c"."sort_order",
    "c"."updated_at"
   FROM ("public"."production_cutover_checklist" "c"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "c"."owner_id")));

CREATE OR REPLACE VIEW "public"."v_production_go_no_go_decision_queue" WITH ("security_invoker"='true') AS
 SELECT "d"."organization_id",
    "d"."id",
    "d"."cycle_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "d"."decision_code",
    "d"."decision_type",
    "d"."decision_status",
    "d"."decided_by_name",
    "d"."decided_at",
    "d"."decision_evidence_url",
        CASE
            WHEN ("d"."decision_status" = 'no_go'::"text") THEN 'danger'::"text"
            WHEN ("d"."decision_status" = ANY (ARRAY['pending'::"text", 'deferred'::"text"])) THEN 'warning'::"text"
            WHEN ("d"."decision_status" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"])) THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "decision_signal"
   FROM ("public"."production_go_no_go_decisions" "d"
     JOIN "public"."production_go_no_go_cycles" "c" ON (("c"."id" = "d"."cycle_id")));

CREATE OR REPLACE VIEW "public"."v_production_go_no_go_evidence_queue" WITH ("security_invoker"='true') AS
 SELECT "c"."organization_id",
    "c"."id" AS "cycle_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "c"."decision_status",
    COALESCE("p"."pending_persona_runs", 0) AS "pending_persona_runs",
    COALESCE("r"."pending_restore_proofs", 0) AS "pending_restore_proofs",
    COALESCE("a"."pending_access_reviews", 0) AS "pending_access_reviews",
    COALESCE("conf"."pending_confidentiality_checks", 0) AS "pending_confidentiality_checks",
    COALESCE("d"."pending_decisions", 0) AS "pending_decisions",
        CASE
            WHEN ((COALESCE("p"."failed_persona_runs", 0) > 0) OR (COALESCE("r"."failed_restore_proofs", 0) > 0) OR (COALESCE("a"."failed_access_reviews", 0) > 0) OR (COALESCE("conf"."failed_confidentiality_checks", 0) > 0)) THEN 'danger'::"text"
            WHEN ((COALESCE("p"."pending_persona_runs", 0) > 0) OR (COALESCE("r"."pending_restore_proofs", 0) > 0) OR (COALESCE("a"."pending_access_reviews", 0) > 0) OR (COALESCE("conf"."pending_confidentiality_checks", 0) > 0) OR (COALESCE("d"."pending_decisions", 0) > 0)) THEN 'warning'::"text"
            WHEN ("c"."decision_status" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"])) THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "readiness_signal"
   FROM ((((("public"."production_go_no_go_cycles" "c"
     LEFT JOIN ( SELECT "production_go_no_go_staging_persona_runs"."cycle_id",
            ("count"(*) FILTER (WHERE ("production_go_no_go_staging_persona_runs"."run_status" = ANY (ARRAY['pending'::"text", 'running'::"text"]))))::integer AS "pending_persona_runs",
            ("count"(*) FILTER (WHERE ("production_go_no_go_staging_persona_runs"."run_status" = 'failed'::"text")))::integer AS "failed_persona_runs"
           FROM "public"."production_go_no_go_staging_persona_runs"
          GROUP BY "production_go_no_go_staging_persona_runs"."cycle_id") "p" ON (("p"."cycle_id" = "c"."id")))
     LEFT JOIN ( SELECT "production_go_no_go_restore_rollback_proofs"."cycle_id",
            ("count"(*) FILTER (WHERE ("production_go_no_go_restore_rollback_proofs"."proof_status" = 'pending'::"text")))::integer AS "pending_restore_proofs",
            ("count"(*) FILTER (WHERE ("production_go_no_go_restore_rollback_proofs"."proof_status" = 'failed'::"text")))::integer AS "failed_restore_proofs"
           FROM "public"."production_go_no_go_restore_rollback_proofs"
          GROUP BY "production_go_no_go_restore_rollback_proofs"."cycle_id") "r" ON (("r"."cycle_id" = "c"."id")))
     LEFT JOIN ( SELECT "production_go_no_go_access_reviews"."cycle_id",
            ("count"(*) FILTER (WHERE ("production_go_no_go_access_reviews"."review_status" = ANY (ARRAY['pending'::"text", 'in_review'::"text"]))))::integer AS "pending_access_reviews",
            ("count"(*) FILTER (WHERE ("production_go_no_go_access_reviews"."review_status" = 'failed'::"text")))::integer AS "failed_access_reviews"
           FROM "public"."production_go_no_go_access_reviews"
          GROUP BY "production_go_no_go_access_reviews"."cycle_id") "a" ON (("a"."cycle_id" = "c"."id")))
     LEFT JOIN ( SELECT "production_go_no_go_confidentiality_checks"."cycle_id",
            ("count"(*) FILTER (WHERE ("production_go_no_go_confidentiality_checks"."check_status" = 'pending'::"text")))::integer AS "pending_confidentiality_checks",
            ("count"(*) FILTER (WHERE ("production_go_no_go_confidentiality_checks"."check_status" = 'failed'::"text")))::integer AS "failed_confidentiality_checks"
           FROM "public"."production_go_no_go_confidentiality_checks"
          GROUP BY "production_go_no_go_confidentiality_checks"."cycle_id") "conf" ON (("conf"."cycle_id" = "c"."id")))
     LEFT JOIN ( SELECT "production_go_no_go_decisions"."cycle_id",
            ("count"(*) FILTER (WHERE ("production_go_no_go_decisions"."decision_status" = 'pending'::"text")))::integer AS "pending_decisions"
           FROM "public"."production_go_no_go_decisions"
          GROUP BY "production_go_no_go_decisions"."cycle_id") "d" ON (("d"."cycle_id" = "c"."id")));

CREATE OR REPLACE VIEW "public"."v_production_go_no_go_monitoring_dashboard" WITH ("security_invoker"='true') AS
 SELECT "m"."organization_id",
    "m"."cycle_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "m"."monitoring_area",
    "m"."check_frequency",
    "m"."check_status",
    "m"."owner_name",
    "m"."latest_checked_at",
    "m"."evidence_url",
        CASE
            WHEN ("m"."check_status" = 'red'::"text") THEN 'danger'::"text"
            WHEN ("m"."check_status" = 'amber'::"text") THEN 'warning'::"text"
            WHEN ("m"."check_status" = ANY (ARRAY['green'::"text", 'resolved'::"text"])) THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "monitoring_signal"
   FROM ("public"."production_go_no_go_launch_monitoring_checks" "m"
     JOIN "public"."production_go_no_go_cycles" "c" ON (("c"."id" = "m"."cycle_id")));

CREATE OR REPLACE VIEW "public"."v_production_go_no_go_summary" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    ("count"(*))::integer AS "cycle_count",
    ("count"(*) FILTER (WHERE ("decision_status" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"]))))::integer AS "go_ready_cycles",
    ("count"(*) FILTER (WHERE ("decision_status" = ANY (ARRAY['no_go'::"text", 'deferred'::"text"]))))::integer AS "blocked_or_deferred_cycles",
    (COALESCE("round"("avg"("readiness_score"), 2), (0)::numeric))::numeric(5,2) AS "avg_readiness_score",
    "max"("target_launch_at") AS "latest_target_launch_at"
   FROM "public"."production_go_no_go_cycles" "c"
  GROUP BY "organization_id";

CREATE OR REPLACE VIEW "public"."v_professional_audit_queue" WITH ("security_invoker"='true') AS
 SELECT "e"."organization_id",
    "e"."engagement_code",
    "e"."engagement_title",
    "e"."audit_domain",
    "e"."risk_rating",
    "e"."engagement_stage",
    "e"."lead_auditor_name",
    "e"."auditee_owner_name",
    "e"."target_report_date",
    ("count"(DISTINCT "p"."id"))::integer AS "program_count",
    ("count"(DISTINCT "rn"."id") FILTER (WHERE ("rn"."note_status" = ANY (ARRAY['open'::"text", 'responded'::"text"]))))::integer AS "open_review_note_count",
        CASE
            WHEN (("e"."target_report_date" IS NOT NULL) AND ("e"."target_report_date" < CURRENT_DATE) AND ("e"."engagement_stage" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'overdue'::"text"
            WHEN ("e"."risk_rating" = ANY (ARRAY['critical'::"text", 'high'::"text"])) THEN 'high_risk'::"text"
            WHEN ("count"(DISTINCT "rn"."id") FILTER (WHERE ("rn"."note_status" = ANY (ARRAY['open'::"text", 'responded'::"text"]))) > 0) THEN 'review_notes_open'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM (("public"."professional_audit_engagement_workbench" "e"
     LEFT JOIN "public"."professional_audit_workpaper_programs" "p" ON (("p"."engagement_id" = "e"."id")))
     LEFT JOIN "public"."professional_audit_review_notes" "rn" ON (("rn"."engagement_id" = "e"."id")))
  GROUP BY "e"."organization_id", "e"."engagement_code", "e"."engagement_title", "e"."audit_domain", "e"."risk_rating", "e"."engagement_stage", "e"."lead_auditor_name", "e"."auditee_owner_name", "e"."target_report_date";

CREATE OR REPLACE VIEW "public"."v_professional_issue_capa_queue" WITH ("security_invoker"='true') AS
 SELECT "i"."organization_id",
    "i"."issue_code",
    "i"."issue_title",
    "i"."issue_source",
    "i"."severity",
    "i"."issue_status",
    "i"."owner_name",
    "i"."due_date",
    ("count"("c"."id"))::integer AS "capa_count",
    ("count"("c"."id") FILTER (WHERE ("c"."retest_status" = 'failed'::"text")))::integer AS "failed_retest_count",
        CASE
            WHEN (("i"."severity" = 'critical'::"text") AND ("i"."issue_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'critical_open'::"text"
            WHEN (("i"."due_date" IS NOT NULL) AND ("i"."due_date" < CURRENT_DATE) AND ("i"."issue_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'overdue'::"text"
            WHEN ("count"("c"."id") FILTER (WHERE ("c"."retest_status" = 'failed'::"text")) > 0) THEN 'failed_retest'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."professional_issue_management" "i"
     LEFT JOIN "public"."professional_capa_retest_closure" "c" ON (("c"."issue_id" = "i"."id")))
  GROUP BY "i"."organization_id", "i"."issue_code", "i"."issue_title", "i"."issue_source", "i"."severity", "i"."issue_status", "i"."owner_name", "i"."due_date";

CREATE OR REPLACE VIEW "public"."v_professional_risk_compliance_queue" WITH ("security_invoker"='true') AS
 SELECT "professional_risk_assessments"."organization_id",
    'risk'::"text" AS "queue_type",
    "professional_risk_assessments"."risk_code" AS "item_code",
    "professional_risk_assessments"."risk_title" AS "item_title",
    "professional_risk_assessments"."appetite_status" AS "item_status",
    "professional_risk_assessments"."risk_owner_name" AS "owner_name",
    "professional_risk_assessments"."next_review_date" AS "due_date",
        CASE
            WHEN ("professional_risk_assessments"."appetite_status" = 'breached'::"text") THEN 'danger'::"text"
            WHEN ("professional_risk_assessments"."next_review_date" < CURRENT_DATE) THEN 'overdue'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."professional_risk_assessments"
UNION ALL
 SELECT "professional_control_test_cycles"."organization_id",
    'control_test'::"text" AS "queue_type",
    "professional_control_test_cycles"."control_code" AS "item_code",
    "professional_control_test_cycles"."control_title" AS "item_title",
    "professional_control_test_cycles"."test_status" AS "item_status",
    "professional_control_test_cycles"."tester_name" AS "owner_name",
    "professional_control_test_cycles"."planned_test_date" AS "due_date",
        CASE
            WHEN ("professional_control_test_cycles"."test_status" = 'failed'::"text") THEN 'danger'::"text"
            WHEN (("professional_control_test_cycles"."planned_test_date" < CURRENT_DATE) AND ("professional_control_test_cycles"."test_status" = ANY (ARRAY['planned'::"text", 'in_progress'::"text"]))) THEN 'overdue'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."professional_control_test_cycles"
UNION ALL
 SELECT "professional_compliance_obligation_workbench"."organization_id",
    'obligation'::"text" AS "queue_type",
    "professional_compliance_obligation_workbench"."obligation_code" AS "item_code",
    "professional_compliance_obligation_workbench"."obligation_title" AS "item_title",
    "professional_compliance_obligation_workbench"."obligation_status" AS "item_status",
    "professional_compliance_obligation_workbench"."owner_name",
    "professional_compliance_obligation_workbench"."next_review_date" AS "due_date",
        CASE
            WHEN ("professional_compliance_obligation_workbench"."obligation_status" = 'breached'::"text") THEN 'danger'::"text"
            WHEN (("professional_compliance_obligation_workbench"."next_review_date" < CURRENT_DATE) AND ("professional_compliance_obligation_workbench"."obligation_status" = ANY (ARRAY['active'::"text", 'under_review'::"text"]))) THEN 'overdue'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."professional_compliance_obligation_workbench";

CREATE OR REPLACE VIEW "public"."v_professional_workbench_summary" WITH ("security_invoker"='true') AS
 SELECT "org"."organization_id",
    (COALESCE("a"."audit_engagement_count", (0)::bigint))::integer AS "audit_engagement_count",
    (COALESCE("a"."open_review_note_count", (0)::bigint))::integer AS "open_review_note_count",
    (COALESCE("r"."risk_assessment_count", (0)::bigint))::integer AS "risk_assessment_count",
    (COALESCE("r"."appetite_breach_count", (0)::bigint))::integer AS "appetite_breach_count",
    (COALESCE("c"."control_test_count", (0)::bigint))::integer AS "control_test_count",
    (COALESCE("c"."failed_control_test_count", (0)::bigint))::integer AS "failed_control_test_count",
    (COALESCE("o"."obligation_count", (0)::bigint))::integer AS "obligation_count",
    (COALESCE("o"."breached_obligation_count", (0)::bigint))::integer AS "breached_obligation_count",
    (COALESCE("i"."open_issue_count", (0)::bigint))::integer AS "open_issue_count",
    (COALESCE("i"."overdue_issue_count", (0)::bigint))::integer AS "overdue_issue_count",
    (COALESCE("cap"."open_capa_count", (0)::bigint))::integer AS "open_capa_count"
   FROM ((((((( SELECT "professional_audit_engagement_workbench"."organization_id"
           FROM "public"."professional_audit_engagement_workbench"
        UNION
         SELECT "professional_risk_assessments"."organization_id"
           FROM "public"."professional_risk_assessments"
        UNION
         SELECT "professional_control_test_cycles"."organization_id"
           FROM "public"."professional_control_test_cycles"
        UNION
         SELECT "professional_compliance_obligation_workbench"."organization_id"
           FROM "public"."professional_compliance_obligation_workbench"
        UNION
         SELECT "professional_issue_management"."organization_id"
           FROM "public"."professional_issue_management"
        UNION
         SELECT "professional_capa_retest_closure"."organization_id"
           FROM "public"."professional_capa_retest_closure") "org"
     LEFT JOIN ( SELECT "e"."organization_id",
            "count"(DISTINCT "e"."id") AS "audit_engagement_count",
            "count"(DISTINCT "rn"."id") FILTER (WHERE ("rn"."note_status" = ANY (ARRAY['open'::"text", 'responded'::"text"]))) AS "open_review_note_count"
           FROM ("public"."professional_audit_engagement_workbench" "e"
             LEFT JOIN "public"."professional_audit_review_notes" "rn" ON (("rn"."engagement_id" = "e"."id")))
          GROUP BY "e"."organization_id") "a" ON (("a"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "professional_risk_assessments"."organization_id",
            "count"(*) AS "risk_assessment_count",
            "count"(*) FILTER (WHERE ("professional_risk_assessments"."appetite_status" = 'breached'::"text")) AS "appetite_breach_count"
           FROM "public"."professional_risk_assessments"
          GROUP BY "professional_risk_assessments"."organization_id") "r" ON (("r"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "professional_control_test_cycles"."organization_id",
            "count"(*) AS "control_test_count",
            "count"(*) FILTER (WHERE ("professional_control_test_cycles"."test_status" = 'failed'::"text")) AS "failed_control_test_count"
           FROM "public"."professional_control_test_cycles"
          GROUP BY "professional_control_test_cycles"."organization_id") "c" ON (("c"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "professional_compliance_obligation_workbench"."organization_id",
            "count"(*) AS "obligation_count",
            "count"(*) FILTER (WHERE ("professional_compliance_obligation_workbench"."obligation_status" = 'breached'::"text")) AS "breached_obligation_count"
           FROM "public"."professional_compliance_obligation_workbench"
          GROUP BY "professional_compliance_obligation_workbench"."organization_id") "o" ON (("o"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "professional_issue_management"."organization_id",
            "count"(*) FILTER (WHERE ("professional_issue_management"."issue_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) AS "open_issue_count",
            "count"(*) FILTER (WHERE (("professional_issue_management"."due_date" < CURRENT_DATE) AND ("professional_issue_management"."issue_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"])))) AS "overdue_issue_count"
           FROM "public"."professional_issue_management"
          GROUP BY "professional_issue_management"."organization_id") "i" ON (("i"."organization_id" = "org"."organization_id")))
     LEFT JOIN ( SELECT "professional_capa_retest_closure"."organization_id",
            "count"(*) FILTER (WHERE ("professional_capa_retest_closure"."closure_status" <> ALL (ARRAY['closed'::"text", 'approved'::"text"]))) AS "open_capa_count"
           FROM "public"."professional_capa_retest_closure"
          GROUP BY "professional_capa_retest_closure"."organization_id") "cap" ON (("cap"."organization_id" = "org"."organization_id")));

COMMENT ON VIEW "public"."v_professional_workbench_summary" IS 'Patch 7 consolidated professional GRC workbench summary; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_qa_readiness_summary" WITH ("security_invoker"='true') AS
 WITH "orgs" AS (
         SELECT "organizations"."id"
           FROM "public"."organizations"
        ), "gate_counts" AS (
         SELECT "v_deployment_readiness_gates"."organization_id",
            ("count"(*))::integer AS "total_gates",
            ("count"(*) FILTER (WHERE ("v_deployment_readiness_gates"."status" = 'passed'::"text")))::integer AS "passed_gates",
            ("count"(*) FILTER (WHERE ("v_deployment_readiness_gates"."status" = 'warning'::"text")))::integer AS "warning_gates",
            ("count"(*) FILTER (WHERE ("v_deployment_readiness_gates"."status" = 'blocked'::"text")))::integer AS "blocked_gates",
            ("count"(*) FILTER (WHERE (("v_deployment_readiness_gates"."severity" = 'critical'::"text") AND ("v_deployment_readiness_gates"."status" <> 'passed'::"text"))))::integer AS "critical_blockers",
            ("count"(*) FILTER (WHERE (("v_deployment_readiness_gates"."severity" = 'high'::"text") AND ("v_deployment_readiness_gates"."status" <> 'passed'::"text"))))::integer AS "high_blockers"
           FROM "public"."v_deployment_readiness_gates"
          GROUP BY "v_deployment_readiness_gates"."organization_id"
        ), "access_counts" AS (
         SELECT "v_access_control_warnings"."organization_id",
            ("count"(*))::integer AS "permission_warnings"
           FROM "public"."v_access_control_warnings"
          GROUP BY "v_access_control_warnings"."organization_id"
        ), "workflow_counts" AS (
         SELECT "v_workflow_blockers"."organization_id",
            ("count"(*))::integer AS "workflow_blockers"
           FROM "public"."v_workflow_blockers"
          GROUP BY "v_workflow_blockers"."organization_id"
        ), "run_counts" AS (
         SELECT "qa_test_runs"."organization_id",
            ("count"(*) FILTER (WHERE ("qa_test_runs"."status" = 'in_progress'::"public"."qa_run_status")))::integer AS "active_test_runs",
            ("count"(*) FILTER (WHERE ("qa_test_runs"."status" = 'completed'::"public"."qa_run_status")))::integer AS "completed_test_runs",
            "max"("qa_test_runs"."started_at") AS "last_test_run_at"
           FROM "public"."qa_test_runs"
          GROUP BY "qa_test_runs"."organization_id"
        ), "result_counts" AS (
         SELECT "qa_test_results"."organization_id",
            ("count"(*) FILTER (WHERE ("qa_test_results"."result_status" = ANY (ARRAY['failed'::"public"."qa_result_status", 'blocked'::"public"."qa_result_status"]))))::integer AS "failed_test_results"
           FROM "public"."qa_test_results"
          GROUP BY "qa_test_results"."organization_id"
        )
 SELECT "o"."id" AS "organization_id",
    COALESCE("g"."total_gates", 0) AS "total_gates",
    COALESCE("g"."passed_gates", 0) AS "passed_gates",
    COALESCE("g"."warning_gates", 0) AS "warning_gates",
    COALESCE("g"."blocked_gates", 0) AS "blocked_gates",
    COALESCE("g"."critical_blockers", 0) AS "critical_blockers",
    COALESCE("g"."high_blockers", 0) AS "high_blockers",
    COALESCE("a"."permission_warnings", 0) AS "permission_warnings",
    COALESCE("w"."workflow_blockers", 0) AS "workflow_blockers",
    COALESCE("r"."active_test_runs", 0) AS "active_test_runs",
    COALESCE("r"."completed_test_runs", 0) AS "completed_test_runs",
    COALESCE("rc"."failed_test_results", 0) AS "failed_test_results",
    GREATEST(0, LEAST(100, (((100 - (COALESCE("g"."blocked_gates", 0) * 12)) - (COALESCE("g"."warning_gates", 0) * 5)) - (COALESCE("rc"."failed_test_results", 0) * 4)))) AS "readiness_score",
    "r"."last_test_run_at"
   FROM ((((("orgs" "o"
     LEFT JOIN "gate_counts" "g" ON (("g"."organization_id" = "o"."id")))
     LEFT JOIN "access_counts" "a" ON (("a"."organization_id" = "o"."id")))
     LEFT JOIN "workflow_counts" "w" ON (("w"."organization_id" = "o"."id")))
     LEFT JOIN "run_counts" "r" ON (("r"."organization_id" = "o"."id")))
     LEFT JOIN "result_counts" "rc" ON (("rc"."organization_id" = "o"."id")));

CREATE OR REPLACE VIEW "public"."v_qa_test_case_library" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "category",
    "test_key",
    "title_en",
    "title_ar",
    "description_en",
    "description_ar",
    "expected_result_en",
    "expected_result_ar",
    ("priority")::"text" AS "priority",
    "test_type",
    "is_active",
    "created_at",
    "updated_at"
   FROM "public"."qa_test_cases";

CREATE OR REPLACE VIEW "public"."v_qa_test_runs_summary" AS
SELECT
    NULL::"uuid" AS "id",
    NULL::"uuid" AS "organization_id",
    NULL::"text" AS "title",
    NULL::"text" AS "scope",
    NULL::"text" AS "status",
    NULL::timestamp with time zone AS "started_at",
    NULL::timestamp with time zone AS "completed_at",
    NULL::integer AS "total_cases",
    NULL::integer AS "passed_cases",
    NULL::integer AS "failed_cases",
    NULL::integer AS "blocked_cases";

CREATE OR REPLACE VIEW "public"."v_quality_accreditation_operating_summary" WITH ("security_invoker"='true') AS
 SELECT COALESCE("req"."organization_id", "ind"."organization_id", "tr"."organization_id", "rca"."organization_id", "pack"."organization_id") AS "organization_id",
    ("count"(DISTINCT "req"."id"))::integer AS "requirement_operation_count",
    ("count"(DISTINCT "req"."id") FILTER (WHERE ("req"."readiness_status" = ANY (ARRAY['ready'::"text", 'evidence_submitted'::"text"]))))::integer AS "ready_requirement_count",
    ("count"(DISTINCT "score"."id") FILTER (WHERE ("score"."score_status" = ANY (ARRAY['partially_met'::"text", 'not_met'::"text"]))))::integer AS "gap_score_count",
    ("count"(DISTINCT "ind"."id"))::integer AS "indicator_count",
    ("count"(DISTINCT "meas"."id") FILTER (WHERE ("meas"."measurement_status" = ANY (ARRAY['submitted'::"text", 'validated'::"text", 'published'::"text"]))))::integer AS "submitted_measurement_count",
    ("count"(DISTINCT "tr"."id") FILTER (WHERE ("tr"."tracer_status" = ANY (ARRAY['planned'::"text", 'in_progress'::"text", 'follow_up'::"text"]))))::integer AS "active_tracer_count",
    ("count"(DISTINCT "obs"."id") FILTER (WHERE ("obs"."observation_status" = ANY (ARRAY['open'::"text", 'requires_capa'::"text"]))))::integer AS "open_observation_count",
    ("count"(DISTINCT "rca"."id") FILTER (WHERE ("rca"."case_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))))::integer AS "open_rca_capa_count",
    ("count"(DISTINCT "pack"."id") FILTER (WHERE ("pack"."pack_status" = ANY (ARRAY['building'::"text", 'review'::"text", 'rejected'::"text"]))))::integer AS "evidence_pack_attention_count"
   FROM ((((((("public"."quality_accreditation_requirement_operations" "req"
     FULL JOIN "public"."quality_indicator_definitions" "ind" ON (("ind"."organization_id" = "req"."organization_id")))
     FULL JOIN "public"."quality_tracer_rounds" "tr" ON (("tr"."organization_id" = COALESCE("req"."organization_id", "ind"."organization_id"))))
     FULL JOIN "public"."quality_rca_capa_cases" "rca" ON (("rca"."organization_id" = COALESCE("req"."organization_id", "ind"."organization_id", "tr"."organization_id"))))
     FULL JOIN "public"."quality_survey_evidence_packs" "pack" ON (("pack"."organization_id" = COALESCE("req"."organization_id", "ind"."organization_id", "tr"."organization_id", "rca"."organization_id"))))
     LEFT JOIN "public"."quality_accreditation_element_scores" "score" ON (("score"."requirement_operation_id" = "req"."id")))
     LEFT JOIN "public"."quality_indicator_measurements" "meas" ON (("meas"."indicator_id" = "ind"."id")))
     LEFT JOIN "public"."quality_tracer_observations" "obs" ON (("obs"."tracer_round_id" = "tr"."id")))
  GROUP BY COALESCE("req"."organization_id", "ind"."organization_id", "tr"."organization_id", "rca"."organization_id", "pack"."organization_id");

COMMENT ON VIEW "public"."v_quality_accreditation_operating_summary" IS 'Patch 6 quality/accreditation operating summary; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_quality_accreditation_requirement_dashboard" WITH ("security_invoker"='true') AS
 SELECT "req"."organization_id",
    "req"."standard_code",
    "req"."chapter_code",
    "req"."requirement_reference",
    "req"."requirement_title",
    "req"."department_name",
    "req"."owner_name",
    "req"."applicability_status",
    "req"."readiness_status",
    "req"."target_survey_date",
    ("count"("score"."id"))::integer AS "scoring_count",
    ("count"("score"."id") FILTER (WHERE ("score"."score_status" = ANY (ARRAY['partially_met'::"text", 'not_met'::"text"]))))::integer AS "gap_count",
    ("count"("score"."id") FILTER (WHERE ("score"."evidence_status" = ANY (ARRAY['submitted'::"text", 'accepted'::"text"]))))::integer AS "evidence_submitted_count",
    "max"("score"."scored_at") AS "last_scored_at"
   FROM ("public"."quality_accreditation_requirement_operations" "req"
     LEFT JOIN "public"."quality_accreditation_element_scores" "score" ON (("score"."requirement_operation_id" = "req"."id")))
  GROUP BY "req"."organization_id", "req"."standard_code", "req"."chapter_code", "req"."requirement_reference", "req"."requirement_title", "req"."department_name", "req"."owner_name", "req"."applicability_status", "req"."readiness_status", "req"."target_survey_date";

CREATE OR REPLACE VIEW "public"."v_quality_indicator_dashboard" WITH ("security_invoker"='true') AS
 SELECT "def"."organization_id",
    "def"."indicator_code",
    "def"."indicator_name",
    "def"."indicator_domain",
    "def"."owner_name",
    "def"."target_direction",
    "def"."target_value",
    "latest"."measured_value",
    "latest"."measurement_status",
    "latest"."period_end",
        CASE
            WHEN ("latest"."measured_value" IS NULL) THEN 'not_measured'::"text"
            WHEN (("def"."target_direction" = 'higher_is_better'::"text") AND ("def"."target_value" IS NOT NULL) AND ("latest"."measured_value" >= "def"."target_value")) THEN 'on_target'::"text"
            WHEN (("def"."target_direction" = 'lower_is_better'::"text") AND ("def"."target_value" IS NOT NULL) AND ("latest"."measured_value" <= "def"."target_value")) THEN 'on_target'::"text"
            WHEN (("def"."warning_value" IS NOT NULL) AND ("def"."target_direction" = 'higher_is_better'::"text") AND ("latest"."measured_value" >= "def"."warning_value")) THEN 'watch'::"text"
            WHEN (("def"."warning_value" IS NOT NULL) AND ("def"."target_direction" = 'lower_is_better'::"text") AND ("latest"."measured_value" <= "def"."warning_value")) THEN 'watch'::"text"
            ELSE 'off_target'::"text"
        END AS "performance_signal"
   FROM ("public"."quality_indicator_definitions" "def"
     LEFT JOIN LATERAL ( SELECT "m"."measured_value",
            "m"."measurement_status",
            "m"."period_end"
           FROM "public"."quality_indicator_measurements" "m"
          WHERE ("m"."indicator_id" = "def"."id")
          ORDER BY "m"."period_end" DESC, "m"."created_at" DESC
         LIMIT 1) "latest" ON (true));

CREATE OR REPLACE VIEW "public"."v_quality_rca_capa_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "case_code",
    "source_type",
    "source_reference",
    "case_title",
    "department_name",
    "case_status",
    "severity",
    "effectiveness_status",
    "owner_name",
    "due_date",
        CASE
            WHEN (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("case_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))) THEN 'overdue'::"text"
            WHEN (("severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("case_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))) THEN 'high_priority'::"text"
            WHEN (("due_date" IS NOT NULL) AND ("due_date" <= (CURRENT_DATE + '7 days'::interval)) AND ("case_status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))) THEN 'due_soon'::"text"
            ELSE 'normal'::"text"
        END AS "case_signal"
   FROM "public"."quality_rca_capa_cases";

CREATE OR REPLACE VIEW "public"."v_quality_tracer_round_dashboard" WITH ("security_invoker"='true') AS
 SELECT "tr"."organization_id",
    "tr"."tracer_code",
    "tr"."tracer_title",
    "tr"."tracer_type",
    "tr"."department_name",
    "tr"."tracer_status",
    "tr"."round_date",
    "tr"."lead_reviewer_name",
    ("count"("obs"."id"))::integer AS "observation_count",
    ("count"("obs"."id") FILTER (WHERE ("obs"."observation_status" = ANY (ARRAY['open'::"text", 'requires_capa'::"text"]))))::integer AS "open_observation_count",
    ("count"("obs"."id") FILTER (WHERE (("obs"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("obs"."observation_status" = ANY (ARRAY['open'::"text", 'requires_capa'::"text"])))))::integer AS "high_risk_observation_count"
   FROM ("public"."quality_tracer_rounds" "tr"
     LEFT JOIN "public"."quality_tracer_observations" "obs" ON (("obs"."tracer_round_id" = "tr"."id")))
  GROUP BY "tr"."organization_id", "tr"."tracer_code", "tr"."tracer_title", "tr"."tracer_type", "tr"."department_name", "tr"."tracer_status", "tr"."round_date", "tr"."lead_reviewer_name";

CREATE OR REPLACE VIEW "public"."v_radar_control_profile" WITH ("security_invoker"='true') AS
 WITH "s" AS (
         SELECT "v_grc_kpi_scorecard"."organization_id",
            "v_grc_kpi_scorecard"."execution_health_score",
            "v_grc_kpi_scorecard"."risk_exposure_score",
            "v_grc_kpi_scorecard"."compliance_pressure_score",
            "v_grc_kpi_scorecard"."ovr_safety_signal_score",
            "v_grc_kpi_scorecard"."evidence_discipline_score",
            "v_grc_kpi_scorecard"."approval_bottleneck_score"
           FROM "public"."v_grc_kpi_scorecard"
        ), "summary" AS (
         SELECT "s"."organization_id",
            "s"."execution_health_score",
            GREATEST(0, (100 - "s"."risk_exposure_score")) AS "risk_control_score",
            GREATEST(0, (100 - "s"."compliance_pressure_score")) AS "compliance_control_score",
            GREATEST((0)::bigint, (100 - LEAST((100)::bigint, COALESCE(( SELECT ("count"(*) * 10)
                   FROM "public"."audit_findings" "af"
                  WHERE (("af"."organization_id" = "s"."organization_id") AND ("af"."due_date" < CURRENT_DATE) AND ("af"."status" <> ALL (ARRAY['closed'::"public"."audit_finding_status", 'cancelled'::"public"."audit_finding_status"])))), (0)::bigint)))) AS "audit_closure_score",
            GREATEST(0, (100 - "s"."ovr_safety_signal_score")) AS "ovr_safety_score",
            "s"."evidence_discipline_score"
           FROM "s"
        )
 SELECT "summary"."organization_id",
    'execution'::"text" AS "dimension_key",
    'Execution'::"text" AS "dimension_label_en",
    'التنفيذ'::"text" AS "dimension_label_ar",
    "summary"."execution_health_score" AS "score"
   FROM "summary"
UNION ALL
 SELECT "summary"."organization_id",
    'risk'::"text" AS "dimension_key",
    'Risk control'::"text" AS "dimension_label_en",
    'ضبط المخاطر'::"text" AS "dimension_label_ar",
    "summary"."risk_control_score" AS "score"
   FROM "summary"
UNION ALL
 SELECT "summary"."organization_id",
    'compliance'::"text" AS "dimension_key",
    'Compliance'::"text" AS "dimension_label_en",
    'الالتزام'::"text" AS "dimension_label_ar",
    "summary"."compliance_control_score" AS "score"
   FROM "summary"
UNION ALL
 SELECT "summary"."organization_id",
    'audit'::"text" AS "dimension_key",
    'Audit closure'::"text" AS "dimension_label_en",
    'إغلاق المراجعة'::"text" AS "dimension_label_ar",
    ("summary"."audit_closure_score")::integer AS "score"
   FROM "summary"
UNION ALL
 SELECT "summary"."organization_id",
    'ovr'::"text" AS "dimension_key",
    'OVR safety'::"text" AS "dimension_label_en",
    'سلامة OVR'::"text" AS "dimension_label_ar",
    "summary"."ovr_safety_score" AS "score"
   FROM "summary"
UNION ALL
 SELECT "summary"."organization_id",
    'evidence'::"text" AS "dimension_key",
    'Evidence discipline'::"text" AS "dimension_label_en",
    'انضباط الأدلة'::"text" AS "dimension_label_ar",
    "summary"."evidence_discipline_score" AS "score"
   FROM "summary";

CREATE OR REPLACE VIEW "public"."v_real_action_queue" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "execution_item_id",
    "module_key",
    "source_type",
    "source_code",
    "item_title",
    "execution_status",
    "priority",
    "owner_name",
    "reviewer_name",
    "approver_name",
    "due_date",
        CASE
            WHEN (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("execution_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'overdue'::"text"
            WHEN ("priority" = ANY (ARRAY['critical'::"text", 'high'::"text"])) THEN 'high_priority'::"text"
            WHEN ("execution_status" = 'changes_requested'::"text") THEN 'changes_requested'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."real_workflow_execution_items"
  WHERE ("execution_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text", 'rejected'::"text"]));

COMMENT ON VIEW "public"."v_real_action_queue" IS 'Patch 12 executable daily action queue.';

CREATE OR REPLACE VIEW "public"."v_real_control_evidence_map" WITH ("security_invoker"='true') AS
 SELECT "ctl"."organization_id",
    "ctl"."control_code",
    "ctl"."control_name",
    "ctl"."control_domain",
    "ctl"."control_owner_name",
    "ctl"."owner_department_code",
    "ctl"."evidence_taxonomy_code",
    "ev"."taxonomy_name" AS "evidence_taxonomy_name",
    "ctl"."linked_requirement_code",
    "ctl"."is_key_control",
        CASE
            WHEN ("ctl"."evidence_taxonomy_code" IS NULL) THEN 'missing_evidence_taxonomy'::"text"
            WHEN ("ctl"."linked_requirement_code" IS NULL) THEN 'missing_requirement_link'::"text"
            WHEN ("ctl"."control_owner_name" IS NULL) THEN 'missing_owner'::"text"
            ELSE 'mapped'::"text"
        END AS "mapping_signal"
   FROM ("public"."real_control_library" "ctl"
     LEFT JOIN "public"."real_evidence_taxonomy" "ev" ON ((("ev"."organization_id" = "ctl"."organization_id") AND ("ev"."taxonomy_code" = "ctl"."evidence_taxonomy_code"))));

CREATE OR REPLACE VIEW "public"."v_real_data_activation_queue" WITH ("security_invoker"='true') AS
 SELECT "d"."organization_id",
    "p"."program_code",
    "p"."program_name",
    "p"."activation_scope",
    "p"."activation_stage",
    "d"."dataset_code",
    "d"."dataset_name",
    "d"."dataset_domain",
    "d"."target_module",
    "d"."dataset_status",
    "d"."expected_record_count",
    "d"."loaded_record_count",
    "d"."rejected_record_count",
    "d"."owner_name",
    "d"."due_date",
        CASE
            WHEN (("d"."dataset_status" = 'failed'::"text") OR (COALESCE("d"."rejected_record_count", 0) > 0)) THEN 'danger'::"text"
            WHEN (("d"."due_date" IS NOT NULL) AND ("d"."due_date" < CURRENT_DATE) AND ("d"."dataset_status" <> ALL (ARRAY['loaded'::"text", 'reconciled'::"text", 'signed_off'::"text"]))) THEN 'overdue'::"text"
            WHEN ("d"."minimum_required" AND ("d"."dataset_status" = ANY (ARRAY['not_started'::"text", 'source_received'::"text"]))) THEN 'required'::"text"
            WHEN ("d"."dataset_status" = ANY (ARRAY['approved'::"text", 'loaded'::"text", 'reconciled'::"text", 'signed_off'::"text"])) THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."real_data_dataset_catalog" "d"
     JOIN "public"."real_data_activation_programs" "p" ON (("p"."id" = "d"."program_id")));

CREATE OR REPLACE VIEW "public"."v_real_data_activation_summary" WITH ("security_invoker"='true', "security_barrier"='true') AS
 SELECT "p"."organization_id",
    ("count"(DISTINCT "p"."id"))::integer AS "program_count",
    ("count"(DISTINCT "p"."id") FILTER (WHERE ("p"."activation_stage" = ANY (ARRAY['validation'::"text", 'mapping'::"text", 'approval'::"text"]))))::integer AS "active_program_count",
    ("count"(DISTINCT "d"."id"))::integer AS "dataset_count",
    ("count"(DISTINCT "d"."id") FILTER (WHERE ("d"."dataset_status" = ANY (ARRAY['approved'::"text", 'loaded'::"text", 'reconciled'::"text", 'signed_off'::"text"]))))::integer AS "ready_dataset_count",
    ("count"(DISTINCT "f"."id"))::integer AS "source_file_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."license_status" = 'blocked'::"text") OR ("f"."validation_status" = ANY (ARRAY['failed'::"text", 'rejected'::"text"])))))::integer AS "blocked_source_count",
    ("count"(DISTINCT "vr"."id") FILTER (WHERE (("vr"."result_status" = 'open'::"text") AND ("vr"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))))::integer AS "high_open_validation_count",
    ("count"(DISTINCT "a"."id") FILTER (WHERE ("a"."approval_status" = 'pending'::"text")))::integer AS "pending_approval_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = ANY (ARRAY['pending'::"text", 'conditional_approval'::"text"]))))::integer AS "pending_signoff_count"
   FROM ((((("public"."real_data_activation_programs" "p"
     LEFT JOIN "public"."real_data_dataset_catalog" "d" ON (("d"."program_id" = "p"."id")))
     LEFT JOIN "public"."real_data_source_files" "f" ON (("f"."program_id" = "p"."id")))
     LEFT JOIN "public"."real_data_validation_results" "vr" ON ((("vr"."organization_id" = "p"."organization_id") AND ("vr"."dataset_id" = "d"."id"))))
     LEFT JOIN "public"."real_data_load_approvals" "a" ON (("a"."program_id" = "p"."id")))
     LEFT JOIN "public"."real_data_readiness_signoffs" "s" ON (("s"."program_id" = "p"."id")))
  GROUP BY "p"."organization_id";

COMMENT ON VIEW "public"."v_real_data_activation_summary" IS 'Patch 179 canonical security-invoker/barrier organization summary. Underlying RLS controls lifecycle and organization visibility.';

CREATE OR REPLACE VIEW "public"."v_real_data_approval_queue" WITH ("security_invoker"='true') AS
 SELECT "a"."organization_id",
    "p"."program_code",
    "d"."dataset_code",
    "d"."dataset_name",
    "a"."approval_stage",
    "a"."approval_status",
    "a"."approver_role",
    "a"."approver_name",
    "a"."decided_at",
        CASE
            WHEN ("a"."approval_status" = 'rejected'::"text") THEN 'danger'::"text"
            WHEN ("a"."approval_status" = 'changes_requested'::"text") THEN 'warning'::"text"
            WHEN ("a"."approval_status" = 'approved'::"text") THEN 'ready'::"text"
            ELSE 'pending'::"text"
        END AS "queue_signal"
   FROM (("public"."real_data_load_approvals" "a"
     LEFT JOIN "public"."real_data_dataset_catalog" "d" ON (("d"."id" = "a"."dataset_id")))
     LEFT JOIN "public"."real_data_activation_programs" "p" ON (("p"."id" = "a"."program_id")));

CREATE OR REPLACE VIEW "public"."v_real_data_cutover_readiness" WITH ("security_invoker"='true') AS
 SELECT "p"."organization_id",
    "p"."program_code",
    "p"."program_name",
    "p"."activation_stage",
    ("count"(DISTINCT "d"."id"))::integer AS "dataset_count",
    ("count"(DISTINCT "d"."id") FILTER (WHERE ("d"."dataset_status" = ANY (ARRAY['approved'::"text", 'loaded'::"text", 'reconciled'::"text", 'signed_off'::"text"]))))::integer AS "ready_dataset_count",
    ("count"(DISTINCT "vr"."id") FILTER (WHERE (("vr"."result_status" = 'open'::"text") AND ("vr"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))))::integer AS "blocking_validation_count",
    ("count"(DISTINCT "a"."id") FILTER (WHERE ("a"."approval_status" = 'pending'::"text")))::integer AS "pending_approval_count",
    ("count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'approved'::"text")))::integer AS "approved_signoff_count",
    ("count"(DISTINCT "s"."id"))::integer AS "signoff_count",
        CASE
            WHEN ("count"(DISTINCT "vr"."id") FILTER (WHERE (("vr"."result_status" = 'open'::"text") AND ("vr"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))) > 0) THEN 'blocked'::"text"
            WHEN ("count"(DISTINCT "a"."id") FILTER (WHERE ("a"."approval_status" = 'pending'::"text")) > 0) THEN 'approval_pending'::"text"
            WHEN (("count"(DISTINCT "d"."id") > 0) AND ("count"(DISTINCT "d"."id") = "count"(DISTINCT "d"."id") FILTER (WHERE ("d"."dataset_status" = ANY (ARRAY['approved'::"text", 'loaded'::"text", 'reconciled'::"text", 'signed_off'::"text"]))))) THEN 'ready'::"text"
            ELSE 'in_progress'::"text"
        END AS "readiness_signal"
   FROM (((("public"."real_data_activation_programs" "p"
     LEFT JOIN "public"."real_data_dataset_catalog" "d" ON (("d"."program_id" = "p"."id")))
     LEFT JOIN "public"."real_data_validation_results" "vr" ON (("vr"."dataset_id" = "d"."id")))
     LEFT JOIN "public"."real_data_load_approvals" "a" ON (("a"."program_id" = "p"."id")))
     LEFT JOIN "public"."real_data_readiness_signoffs" "s" ON (("s"."program_id" = "p"."id")))
  GROUP BY "p"."organization_id", "p"."program_code", "p"."program_name", "p"."activation_stage";

CREATE OR REPLACE VIEW "public"."v_real_data_import_quality_queue" WITH ("security_invoker"='true') AS
 SELECT "b"."organization_id",
    "b"."batch_code",
    "b"."source_domain",
    "b"."source_name",
    "b"."batch_status",
    "b"."content_license_status",
    "b"."uploaded_by_name",
    "b"."record_count",
    "b"."error_count",
    ("count"("v"."id") FILTER (WHERE ("v"."result_status" = 'failed'::"text")))::integer AS "failed_rule_count",
    ("count"("v"."id") FILTER (WHERE ("v"."result_status" = 'warning'::"text")))::integer AS "warning_rule_count",
        CASE
            WHEN ("b"."content_license_status" = 'rejected_unlicensed'::"text") THEN 'blocked_unlicensed'::"text"
            WHEN (("b"."error_count" > 0) OR ("count"("v"."id") FILTER (WHERE ("v"."result_status" = 'failed'::"text")) > 0)) THEN 'validation_failed'::"text"
            WHEN ("b"."content_license_status" = 'pending_owner_confirmation'::"text") THEN 'license_review'::"text"
            WHEN ("b"."batch_status" = ANY (ARRAY['ready_for_review'::"text", 'approved'::"text"])) THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."real_data_activation_import_batches" "b"
     LEFT JOIN "public"."real_data_activation_validation_results" "v" ON (("v"."batch_id" = "b"."id")))
  GROUP BY "b"."organization_id", "b"."batch_code", "b"."source_domain", "b"."source_name", "b"."batch_status", "b"."content_license_status", "b"."uploaded_by_name", "b"."record_count", "b"."error_count";

COMMENT ON VIEW "public"."v_real_data_import_quality_queue" IS 'Patch 10 real-data import quality queue; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_real_data_validation_queue" WITH ("security_invoker"='true') AS
 SELECT "vr"."organization_id",
    "p"."program_code",
    "d"."dataset_code",
    "d"."dataset_name",
    "vr"."severity",
    "vr"."result_status",
    "vr"."finding_title",
    "vr"."remediation_owner_name",
    "vr"."remediation_due_date",
        CASE
            WHEN (("vr"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("vr"."result_status" = 'open'::"text")) THEN 'danger'::"text"
            WHEN (("vr"."remediation_due_date" IS NOT NULL) AND ("vr"."remediation_due_date" < CURRENT_DATE) AND ("vr"."result_status" = 'open'::"text")) THEN 'overdue'::"text"
            WHEN ("vr"."result_status" = 'resolved'::"text") THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM (("public"."real_data_validation_results" "vr"
     LEFT JOIN "public"."real_data_dataset_catalog" "d" ON (("d"."id" = "vr"."dataset_id")))
     LEFT JOIN "public"."real_data_activation_programs" "p" ON (("p"."id" = "d"."program_id")));

CREATE OR REPLACE VIEW "public"."v_real_evidence_review_queue" WITH ("security_invoker"='true') AS
 SELECT "e"."organization_id",
    "e"."id" AS "evidence_submission_id",
    "i"."item_title",
    "e"."requirement_code",
    "e"."evidence_taxonomy_code",
    "e"."evidence_title",
    "e"."submitted_by_name",
    "e"."evidence_status",
    "e"."confidentiality_level",
    "e"."review_due_date",
        CASE
            WHEN ("e"."evidence_status" = 'rejected'::"text") THEN 'rejected'::"text"
            WHEN (("e"."review_due_date" IS NOT NULL) AND ("e"."review_due_date" < CURRENT_DATE) AND ("e"."evidence_status" <> ALL (ARRAY['accepted'::"text", 'withdrawn'::"text"]))) THEN 'overdue_review'::"text"
            WHEN ("e"."confidentiality_level" = ANY (ARRAY['restricted'::"text", 'patient_sensitive'::"text"])) THEN 'sensitive_review'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."real_evidence_submissions" "e"
     LEFT JOIN "public"."real_workflow_execution_items" "i" ON (("i"."id" = "e"."execution_item_id")))
  WHERE ("e"."evidence_status" <> ALL (ARRAY['accepted'::"text", 'withdrawn'::"text"]));

CREATE OR REPLACE VIEW "public"."v_real_gap_capa_queue" WITH ("security_invoker"='true') AS
 SELECT "g"."organization_id",
    "g"."gap_code",
    "g"."gap_title",
    "g"."requirement_code",
    "g"."department_code",
    "g"."closure_status",
    "g"."owner_name",
    "g"."due_date",
    ("count"("c"."id"))::integer AS "capa_count",
    ("count"("r"."id") FILTER (WHERE ("r"."retest_result" = 'failed'::"text")))::integer AS "failed_retest_count",
        CASE
            WHEN (("g"."due_date" IS NOT NULL) AND ("g"."due_date" < CURRENT_DATE) AND ("g"."closure_status" <> ALL (ARRAY['closed'::"text", 'rejected'::"text"]))) THEN 'overdue'::"text"
            WHEN ("count"("r"."id") FILTER (WHERE ("r"."retest_result" = 'failed'::"text")) > 0) THEN 'failed_retest'::"text"
            WHEN ("g"."closure_status" = ANY (ARRAY['open'::"text", 'assigned'::"text"])) THEN 'open'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM (("public"."real_gap_closure_actions" "g"
     LEFT JOIN "public"."real_capa_issuance_records" "c" ON (("c"."gap_closure_id" = "g"."id")))
     LEFT JOIN "public"."real_capa_retests" "r" ON (("r"."capa_id" = "c"."id")))
  GROUP BY "g"."organization_id", "g"."gap_code", "g"."gap_title", "g"."requirement_code", "g"."department_code", "g"."closure_status", "g"."owner_name", "g"."due_date";

CREATE OR REPLACE VIEW "public"."v_real_management_response_queue" WITH ("security_invoker"='true') AS
 SELECT "mr"."organization_id",
    "mr"."response_code",
    COALESCE("f"."finding_code", "mr"."finding_code") AS "finding_code",
    COALESCE("f"."finding_title", "mr"."finding_code", 'Management response'::"text") AS "finding_title",
    "mr"."response_owner_name",
    "mr"."response_status",
    "mr"."target_date",
    "f"."severity",
        CASE
            WHEN (("mr"."target_date" IS NOT NULL) AND ("mr"."target_date" < CURRENT_DATE) AND ("mr"."response_status" <> ALL (ARRAY['accepted'::"text", 'closed'::"text"]))) THEN 'overdue'::"text"
            WHEN ("f"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) THEN 'high_severity'::"text"
            WHEN ("mr"."response_status" = 'rejected'::"text") THEN 'rejected'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."real_management_responses" "mr"
     LEFT JOIN "public"."real_audit_finding_generation" "f" ON ((("f"."finding_code" = "mr"."finding_code") AND ("f"."organization_id" = "mr"."organization_id"))));

CREATE OR REPLACE VIEW "public"."v_real_master_data_coverage" WITH ("security_invoker"='true') AS
 SELECT "real_department_master"."organization_id",
    'department'::"text" AS "master_data_type",
    "real_department_master"."department_code" AS "item_code",
    "real_department_master"."department_name" AS "item_name",
    "real_department_master"."accreditation_scope" AS "item_status"
   FROM "public"."real_department_master"
UNION ALL
 SELECT "real_committee_master"."organization_id",
    'committee'::"text" AS "master_data_type",
    "real_committee_master"."committee_code" AS "item_code",
    "real_committee_master"."committee_name" AS "item_name",
        CASE
            WHEN "real_committee_master"."is_active" THEN 'active'::"text"
            ELSE 'inactive'::"text"
        END AS "item_status"
   FROM "public"."real_committee_master"
UNION ALL
 SELECT "real_evidence_taxonomy"."organization_id",
    'evidence_taxonomy'::"text" AS "master_data_type",
    "real_evidence_taxonomy"."taxonomy_code" AS "item_code",
    "real_evidence_taxonomy"."taxonomy_name" AS "item_name",
    "real_evidence_taxonomy"."confidentiality_level" AS "item_status"
   FROM "public"."real_evidence_taxonomy"
UNION ALL
 SELECT "real_document_register"."organization_id",
    'document'::"text" AS "master_data_type",
    "real_document_register"."document_code" AS "item_code",
    "real_document_register"."document_title" AS "item_name",
    "real_document_register"."approval_status" AS "item_status"
   FROM "public"."real_document_register"
UNION ALL
 SELECT "real_control_library"."organization_id",
    'control'::"text" AS "master_data_type",
    "real_control_library"."control_code" AS "item_code",
    "real_control_library"."control_name" AS "item_name",
        CASE
            WHEN "real_control_library"."is_key_control" THEN 'key_control'::"text"
            ELSE 'standard_control'::"text"
        END AS "item_status"
   FROM "public"."real_control_library";

CREATE OR REPLACE VIEW "public"."v_real_standards_master_summary" WITH ("security_invoker"='true') AS
 SELECT COALESCE("l"."organization_id", "d"."organization_id", "c"."organization_id", "e"."organization_id", "ctl"."organization_id") AS "organization_id",
    ("count"(DISTINCT "l"."id"))::integer AS "standards_library_count",
    ("count"(DISTINCT "l"."id") FILTER (WHERE "l"."license_verified"))::integer AS "license_verified_count",
    ("count"(DISTINCT "r"."id"))::integer AS "requirement_count",
    ("count"(DISTINCT "m"."id"))::integer AS "measurable_element_count",
    ("count"(DISTINCT "d"."id"))::integer AS "department_count",
    ("count"(DISTINCT "c"."id"))::integer AS "committee_count",
    ("count"(DISTINCT "e"."id"))::integer AS "evidence_taxonomy_count",
    ("count"(DISTINCT "doc"."id"))::integer AS "document_count",
    ("count"(DISTINCT "ctl"."id"))::integer AS "control_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."applicability_status" = 'pending'::"text")))::integer AS "pending_applicability_count"
   FROM (((((((("public"."real_standard_libraries" "l"
     FULL JOIN "public"."real_department_master" "d" ON (("d"."organization_id" = "l"."organization_id")))
     FULL JOIN "public"."real_committee_master" "c" ON (("c"."organization_id" = COALESCE("l"."organization_id", "d"."organization_id"))))
     FULL JOIN "public"."real_evidence_taxonomy" "e" ON (("e"."organization_id" = COALESCE("l"."organization_id", "d"."organization_id", "c"."organization_id"))))
     FULL JOIN "public"."real_control_library" "ctl" ON (("ctl"."organization_id" = COALESCE("l"."organization_id", "d"."organization_id", "c"."organization_id", "e"."organization_id"))))
     LEFT JOIN "public"."real_standard_versions" "v" ON (("v"."library_id" = "l"."id")))
     LEFT JOIN "public"."real_standard_requirements" "r" ON (("r"."version_id" = "v"."id")))
     LEFT JOIN "public"."real_measurable_elements" "m" ON (("m"."requirement_id" = "r"."id")))
     LEFT JOIN "public"."real_document_register" "doc" ON (("doc"."organization_id" = COALESCE("l"."organization_id", "d"."organization_id", "c"."organization_id", "e"."organization_id", "ctl"."organization_id"))))
  GROUP BY COALESCE("l"."organization_id", "d"."organization_id", "c"."organization_id", "e"."organization_id", "ctl"."organization_id");

CREATE OR REPLACE VIEW "public"."v_real_standards_readiness_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "l"."framework_code",
    "v"."version_label",
    "r"."chapter_code",
    "r"."requirement_code",
    "r"."requirement_title",
    "r"."applicability_status",
    "r"."responsible_department_name",
    "r"."priority",
    ("count"("m"."id"))::integer AS "measurable_element_count",
    ("count"("m"."id") FILTER (WHERE ("m"."score_status" = ANY (ARRAY['not_scored'::"text", 'not_met'::"text", 'partially_met'::"text"]))))::integer AS "open_element_count",
        CASE
            WHEN ("r"."applicability_status" = 'pending'::"text") THEN 'pending_applicability'::"text"
            WHEN ("count"("m"."id") FILTER (WHERE ("m"."score_status" = 'not_met'::"text")) > 0) THEN 'not_met'::"text"
            WHEN ("count"("m"."id") FILTER (WHERE ("m"."score_status" = 'partially_met'::"text")) > 0) THEN 'partially_met'::"text"
            WHEN ("count"("m"."id") = 0) THEN 'mapping_needed'::"text"
            ELSE 'ready'::"text"
        END AS "readiness_signal"
   FROM ((("public"."real_standard_requirements" "r"
     JOIN "public"."real_standard_versions" "v" ON (("v"."id" = "r"."version_id")))
     JOIN "public"."real_standard_libraries" "l" ON (("l"."id" = "v"."library_id")))
     LEFT JOIN "public"."real_measurable_elements" "m" ON (("m"."requirement_id" = "r"."id")))
  GROUP BY "r"."organization_id", "l"."framework_code", "v"."version_label", "r"."chapter_code", "r"."requirement_code", "r"."requirement_title", "r"."applicability_status", "r"."responsible_department_name", "r"."priority";

COMMENT ON VIEW "public"."v_real_standards_readiness_queue" IS 'Patch 11 requirement readiness queue using licensed owner-loaded metadata and measurable element status.';

CREATE OR REPLACE VIEW "public"."v_real_uat_evidence_pack_readiness" WITH ("security_invoker"='true') AS
 SELECT "ep"."organization_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "ep"."pack_code",
    "ep"."pack_title",
    "ep"."accreditation_scope",
    "ep"."pack_status",
    "ep"."required_artifact_count",
    "ep"."accepted_artifact_count",
    "ep"."open_gap_count",
    "ep"."owner_name",
    "ep"."target_review_date",
        CASE
            WHEN ("ep"."open_gap_count" > 0) THEN 'warning'::"text"
            WHEN (("ep"."required_artifact_count" > 0) AND ("ep"."accepted_artifact_count" >= "ep"."required_artifact_count") AND ("ep"."pack_status" = ANY (ARRAY['review_ready'::"text", 'accepted'::"text"]))) THEN 'ready'::"text"
            WHEN (("ep"."target_review_date" IS NOT NULL) AND ("ep"."target_review_date" < CURRENT_DATE) AND ("ep"."pack_status" <> ALL (ARRAY['accepted'::"text", 'archived'::"text"]))) THEN 'overdue'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."real_uat_accreditation_evidence_packages" "ep"
     LEFT JOIN "public"."real_uat_execution_cycles" "c" ON (("c"."id" = "ep"."cycle_id")));

CREATE OR REPLACE VIEW "public"."v_real_uat_execution_summary" WITH ("security_invoker"='true') AS
 SELECT "c"."organization_id",
    ("count"(DISTINCT "c"."id"))::integer AS "cycle_count",
    ("count"(DISTINCT "c"."id") FILTER (WHERE ("c"."cycle_status" = ANY (ARRAY['planned'::"text", 'in_progress'::"text", 'evidence_review'::"text", 'retest'::"text"]))))::integer AS "active_cycle_count",
    ("count"(DISTINCT "s"."id"))::integer AS "script_count",
    ("count"(DISTINCT "r"."id"))::integer AS "run_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."run_status" = 'passed'::"text")))::integer AS "passed_run_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text", 'retest_required'::"text"]))))::integer AS "failed_or_blocked_run_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."finding_status" <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'closed'::"text"]))))::integer AS "open_finding_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("f"."finding_status" <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'closed'::"text"])))))::integer AS "high_open_finding_count",
    ("count"(DISTINCT "p"."id") FILTER (WHERE ("p"."proof_status" = 'passed'::"text")))::integer AS "passed_sql_proof_count",
    ("count"(DISTINCT "so"."id") FILTER (WHERE ("so"."signoff_status" = 'signed'::"text")))::integer AS "signed_area_count",
    ("count"(DISTINCT "ep"."id") FILTER (WHERE ("ep"."pack_status" = ANY (ARRAY['review_ready'::"text", 'accepted'::"text"]))))::integer AS "ready_evidence_pack_count"
   FROM (((((("public"."real_uat_execution_cycles" "c"
     LEFT JOIN "public"."real_uat_execution_scripts" "s" ON (("s"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."real_uat_execution_runs" "r" ON (("r"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."real_uat_execution_findings" "f" ON (("f"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."real_uat_execution_sql_proofs" "p" ON (("p"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."real_uat_execution_signoffs" "so" ON (("so"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."real_uat_accreditation_evidence_packages" "ep" ON (("ep"."cycle_id" = "c"."id")))
  GROUP BY "c"."organization_id";

COMMENT ON VIEW "public"."v_real_uat_execution_summary" IS 'Patch 17 summary for real UAT execution, findings, SQL proofs, signoffs, and evidence pack readiness.';

CREATE OR REPLACE VIEW "public"."v_real_uat_finding_retest_queue" WITH ("security_invoker"='true') AS
 SELECT "f"."organization_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "f"."finding_code",
    "f"."finding_title",
    "f"."severity",
    "f"."finding_status",
    "f"."owner_name",
    "f"."due_date",
    ("count"("rt"."id"))::integer AS "retest_count",
    ("count"("rt"."id") FILTER (WHERE ("rt"."retest_status" = 'passed'::"text")))::integer AS "passed_retest_count",
    ("count"("rt"."id") FILTER (WHERE ("rt"."retest_status" = 'failed'::"text")))::integer AS "failed_retest_count",
        CASE
            WHEN (("f"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("f"."finding_status" <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'closed'::"text"]))) THEN 'danger'::"text"
            WHEN (("f"."due_date" IS NOT NULL) AND ("f"."due_date" < CURRENT_DATE) AND ("f"."finding_status" <> ALL (ARRAY['accepted'::"text", 'waived'::"text", 'closed'::"text"]))) THEN 'overdue'::"text"
            WHEN ("f"."finding_status" = ANY (ARRAY['fixed'::"text", 'ready_for_retest'::"text"])) THEN 'retest_ready'::"text"
            WHEN ("f"."finding_status" = ANY (ARRAY['accepted'::"text", 'closed'::"text"])) THEN 'ready'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM (("public"."real_uat_execution_findings" "f"
     LEFT JOIN "public"."real_uat_execution_cycles" "c" ON (("c"."id" = "f"."cycle_id")))
     LEFT JOIN "public"."real_uat_execution_retests" "rt" ON (("rt"."finding_id" = "f"."id")))
  GROUP BY "f"."organization_id", "c"."cycle_code", "c"."cycle_name", "f"."finding_code", "f"."finding_title", "f"."severity", "f"."finding_status", "f"."owner_name", "f"."due_date";

CREATE OR REPLACE VIEW "public"."v_real_uat_run_queue" WITH ("security_invoker"='true') AS
 SELECT "c"."organization_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "c"."cycle_status",
    "c"."environment_name",
    "s"."script_code",
    "s"."script_title",
    "s"."module_key",
    "s"."test_priority",
    "p"."persona_group",
    "p"."persona_name",
    "r"."run_code",
    "r"."run_status",
    "r"."evidence_review_status",
    "r"."executed_by_name",
    "r"."execution_finished_at",
        CASE
            WHEN ("r"."run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"])) THEN 'danger'::"text"
            WHEN ("r"."run_status" = 'retest_required'::"text") THEN 'warning'::"text"
            WHEN ("r"."evidence_review_status" = ANY (ARRAY['rejected'::"text", 'needs_more_evidence'::"text"])) THEN 'warning'::"text"
            WHEN (("r"."run_status" = 'passed'::"text") AND ("r"."evidence_review_status" = 'accepted'::"text")) THEN 'ready'::"text"
            WHEN (("c"."target_finish_date" IS NOT NULL) AND ("c"."target_finish_date" < CURRENT_DATE) AND ("r"."run_status" <> ALL (ARRAY['passed'::"text", 'cancelled'::"text"]))) THEN 'overdue'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ((("public"."real_uat_execution_cycles" "c"
     JOIN "public"."real_uat_execution_scripts" "s" ON (("s"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."real_uat_execution_personas" "p" ON (("p"."id" = "s"."persona_id")))
     LEFT JOIN "public"."real_uat_execution_runs" "r" ON ((("r"."script_id" = "s"."id") AND ("r"."cycle_id" = "c"."id"))));

CREATE OR REPLACE VIEW "public"."v_real_uat_signoff_readiness" WITH ("security_invoker"='true') AS
 SELECT "so"."organization_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "so"."signoff_area",
    "so"."signer_name",
    "so"."signer_title",
    "so"."signoff_status",
    "so"."signed_at",
        CASE
            WHEN ("so"."signoff_status" = 'signed'::"text") THEN 'ready'::"text"
            WHEN ("so"."signoff_status" = 'conditional'::"text") THEN 'warning'::"text"
            WHEN ("so"."signoff_status" = 'rejected'::"text") THEN 'danger'::"text"
            ELSE 'pending'::"text"
        END AS "queue_signal"
   FROM ("public"."real_uat_execution_signoffs" "so"
     JOIN "public"."real_uat_execution_cycles" "c" ON (("c"."id" = "so"."cycle_id")));

CREATE OR REPLACE VIEW "public"."v_real_workflow_execution_summary" WITH ("security_invoker"='true') AS
 SELECT "i"."organization_id",
    ("count"(DISTINCT "i"."id"))::integer AS "execution_item_count",
    ("count"(DISTINCT "i"."id") FILTER (WHERE ("i"."execution_status" = ANY (ARRAY['open'::"text", 'submitted'::"text", 'under_review'::"text", 'changes_requested'::"text", 'overdue'::"text"]))))::integer AS "active_item_count",
    ("count"(DISTINCT "i"."id") FILTER (WHERE (("i"."execution_status" = 'overdue'::"text") OR (("i"."due_date" IS NOT NULL) AND ("i"."due_date" < CURRENT_DATE) AND ("i"."execution_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text", 'approved'::"text", 'rejected'::"text"]))))))::integer AS "overdue_item_count",
    ("count"(DISTINCT "ev"."id") FILTER (WHERE ("ev"."evidence_status" = ANY (ARRAY['submitted'::"text", 'under_review'::"text", 'rejected'::"text"]))))::integer AS "evidence_attention_count",
    ("count"(DISTINCT "gap"."id") FILTER (WHERE ("gap"."closure_status" <> ALL (ARRAY['closed'::"text", 'rejected'::"text"]))))::integer AS "open_gap_count",
    ("count"(DISTINCT "capa"."id") FILTER (WHERE ("capa"."capa_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))))::integer AS "open_capa_count",
    ("count"(DISTINCT "ex"."id") FILTER (WHERE ("ex"."approval_status" = ANY (ARRAY['requested'::"text", 'under_review'::"text"]))))::integer AS "pending_exception_count",
    ("count"(DISTINCT "mr"."id") FILTER (WHERE ("mr"."response_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'overdue'::"text"]))))::integer AS "management_response_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))))::integer AS "open_finding_count"
   FROM (((((("public"."real_workflow_execution_items" "i"
     LEFT JOIN "public"."real_evidence_submissions" "ev" ON (("ev"."execution_item_id" = "i"."id")))
     LEFT JOIN "public"."real_gap_closure_actions" "gap" ON (("gap"."execution_item_id" = "i"."id")))
     LEFT JOIN "public"."real_capa_issuance_records" "capa" ON (("capa"."gap_closure_id" = "gap"."id")))
     LEFT JOIN "public"."real_exception_approvals" "ex" ON (("ex"."execution_item_id" = "i"."id")))
     LEFT JOIN "public"."real_management_responses" "mr" ON (("mr"."execution_item_id" = "i"."id")))
     LEFT JOIN "public"."real_audit_finding_generation" "f" ON (("f"."execution_item_id" = "i"."id")))
  GROUP BY "i"."organization_id";

CREATE OR REPLACE VIEW "public"."v_recurring_review_queue" WITH ("security_invoker"='true') AS
 SELECT "rr"."id",
    "rr"."organization_id",
    "rr"."review_code",
    "rr"."title_en",
    "rr"."title_ar",
    "rr"."area",
    "rr"."linked_record_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "owner"."full_name_en" AS "owner_name_en",
    "owner"."full_name_ar" AS "owner_name_ar",
    "reviewer"."full_name_en" AS "reviewer_name_en",
    "reviewer"."full_name_ar" AS "reviewer_name_ar",
    "rr"."frequency",
    "rr"."next_due_date",
    "rr"."reminder_days_before",
        CASE
            WHEN ("rr"."status" = 'completed'::"public"."review_status") THEN 'completed'::"public"."review_status"
            WHEN ("rr"."next_due_date" < CURRENT_DATE) THEN 'overdue'::"public"."review_status"
            WHEN ("rr"."next_due_date" <= CURRENT_DATE) THEN 'due'::"public"."review_status"
            WHEN ("rr"."next_due_date" <= (CURRENT_DATE + (("rr"."reminder_days_before" || ' days'::"text"))::interval)) THEN 'due_soon'::"public"."review_status"
            ELSE "rr"."status"
        END AS "computed_status",
    GREATEST((CURRENT_DATE - "rr"."next_due_date"), 0) AS "days_overdue",
    "rr"."last_completed_at",
    "rr"."notes"
   FROM ((("public"."recurring_reviews" "rr"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "rr"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "rr"."owner_id")))
     LEFT JOIN "public"."profiles" "reviewer" ON (("reviewer"."id" = "rr"."reviewer_id")))
  WHERE ("rr"."is_active" = true);

CREATE OR REPLACE VIEW "public"."v_release_candidate_gates" WITH ("security_invoker"='true') AS
 SELECT "g"."id",
    "g"."organization_id",
    "g"."gate_area",
    "g"."gate_name",
    "g"."severity",
    "g"."status",
    "g"."owner",
    "g"."owner_id",
    "g"."evidence_required",
    "g"."evidence_reference",
    "g"."notes",
    "g"."target_date",
    "g"."resolved_by",
    "g"."resolved_at",
    "g"."created_at",
    "g"."updated_at",
    COALESCE("owner"."full_name_en", "g"."owner", 'Unassigned'::"text") AS "owner_name",
        CASE "g"."severity"
            WHEN 'blocker'::"public"."release_gate_severity" THEN 1
            WHEN 'warning'::"public"."release_gate_severity" THEN 2
            ELSE 3
        END AS "severity_rank"
   FROM ("public"."release_candidate_gates" "g"
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "g"."owner_id")));

CREATE OR REPLACE VIEW "public"."v_release_factory_checks" WITH ("security_invoker"='true') AS
 SELECT "id",
    "organization_id",
    "release_tag",
    "check_code",
    "check_group",
    "title",
    "description",
    "owner_label",
    "status",
    "severity",
    "evidence_required",
    "evidence_note",
    "sequence_no",
    "created_at",
    "updated_at"
   FROM "public"."release_factory_checks";

CREATE OR REPLACE VIEW "public"."v_release_factory_scorecard" WITH ("security_invoker"='true') AS
 WITH "orgs" AS (
         SELECT "organizations"."id" AS "organization_id"
           FROM "public"."organizations"
         LIMIT 1
        ), "checks" AS (
         SELECT "release_factory_checks"."organization_id",
            "count"(*) AS "total_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'passed'::"text")) AS "passed_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'blocked'::"text")) AS "blocked_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'warning'::"text")) AS "warning_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"]))) AS "pending_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'migration'::"text")) AS "migration_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'security'::"text")) AS "rls_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'backup'::"text")) AS "backup_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'bilingual'::"text")) AS "bilingual_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'ui'::"text")) AS "ui_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'handover'::"text")) AS "handover_checks"
           FROM "public"."release_factory_checks"
          GROUP BY "release_factory_checks"."organization_id"
        )
 SELECT "o"."organization_id",
    'v3.2-final-release-factory'::"text" AS "release_tag",
    COALESCE("c"."total_checks", (0)::bigint) AS "total_checks",
    COALESCE("c"."passed_checks", (0)::bigint) AS "passed_checks",
    COALESCE("c"."blocked_checks", (0)::bigint) AS "blocked_checks",
    COALESCE("c"."warning_checks", (0)::bigint) AS "warning_checks",
    COALESCE("c"."pending_checks", (0)::bigint) AS "pending_checks",
    COALESCE("c"."migration_checks", (0)::bigint) AS "migration_checks",
    COALESCE("c"."rls_checks", (0)::bigint) AS "rls_checks",
    COALESCE("c"."backup_checks", (0)::bigint) AS "backup_checks",
    COALESCE("c"."bilingual_checks", (0)::bigint) AS "bilingual_checks",
    COALESCE("c"."ui_checks", (0)::bigint) AS "ui_checks",
    COALESCE("c"."handover_checks", (0)::bigint) AS "handover_checks",
        CASE
            WHEN (COALESCE("c"."total_checks", (0)::bigint) = 0) THEN 0
            ELSE (GREATEST((0)::numeric, LEAST((100)::numeric, "round"((((((COALESCE("c"."passed_checks", (0)::bigint))::numeric * 100.0) + ((COALESCE("c"."warning_checks", (0)::bigint))::numeric * 50.0)) + ((COALESCE("c"."accepted_risk_checks", (0)::bigint))::numeric * 70.0)) / (NULLIF("c"."total_checks", 0))::numeric)))))::integer
        END AS "final_score",
        CASE
            WHEN (COALESCE("c"."blocked_checks", (0)::bigint) > 0) THEN 'blocked'::"text"
            WHEN ((COALESCE("c"."warning_checks", (0)::bigint) > 0) OR (COALESCE("c"."pending_checks", (0)::bigint) > 0)) THEN 'conditional'::"text"
            ELSE 'go'::"text"
        END AS "ready_signal"
   FROM ("orgs" "o"
     LEFT JOIN ( SELECT "release_factory_checks"."organization_id",
            "count"(*) AS "total_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'passed'::"text")) AS "passed_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'blocked'::"text")) AS "blocked_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'warning'::"text")) AS "warning_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"]))) AS "pending_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."status" = 'accepted_risk'::"text")) AS "accepted_risk_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'migration'::"text")) AS "migration_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'security'::"text")) AS "rls_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'backup'::"text")) AS "backup_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'bilingual'::"text")) AS "bilingual_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'ui'::"text")) AS "ui_checks",
            "count"(*) FILTER (WHERE ("release_factory_checks"."check_group" = 'handover'::"text")) AS "handover_checks"
           FROM "public"."release_factory_checks"
          GROUP BY "release_factory_checks"."organization_id") "c" ON (("c"."organization_id" = "o"."organization_id")));

CREATE OR REPLACE VIEW "public"."v_release_migration_order" WITH ("security_invoker"='true') AS
 SELECT "id",
    "version_label",
    "migration_file",
    "sequence_no",
    "purpose",
    "required",
    "created_at"
   FROM "public"."release_migration_order"
  ORDER BY "sequence_no";

CREATE OR REPLACE VIEW "public"."v_report_builder_catalog" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."organization_id",
    "r"."template_code",
    "r"."title_en",
    COALESCE("r"."title_ar", "r"."title_en") AS "title_ar",
    "r"."description_en",
    COALESCE("r"."description_ar", "r"."description_en") AS "description_ar",
    "r"."source_view",
    "r"."default_columns",
    "r"."default_filters",
    "r"."output_formats",
    "r"."is_system",
    "r"."is_active",
    "r"."updated_at",
    (COALESCE("rr"."run_count", (0)::bigint))::integer AS "run_count",
    "rr"."last_generated_at"
   FROM ("public"."report_builder_templates" "r"
     LEFT JOIN ( SELECT "report_runs"."template_id",
            "count"(*) AS "run_count",
            "max"("report_runs"."generated_at") AS "last_generated_at"
           FROM "public"."report_runs"
          GROUP BY "report_runs"."template_id") "rr" ON (("rr"."template_id" = "r"."id")));

CREATE OR REPLACE VIEW "public"."v_restore_verification_status" WITH ("security_invoker"='true') AS
 SELECT "v"."id",
    "v"."organization_id",
    "v"."backup_strategy_id",
    "v"."verification_code",
    "v"."scenario_name",
    "v"."status",
    "v"."started_at",
    "v"."finished_at",
    "v"."row_count_match",
    "v"."storage_files_checked",
    "v"."auth_users_checked",
    "v"."evidence_note",
    "v"."failure_note",
    "v"."created_by",
    "v"."created_at",
    "v"."updated_at",
    "s"."strategy_code",
    "s"."title" AS "strategy_title",
        CASE
            WHEN (("v"."status" = 'passed'::"text") AND COALESCE("v"."row_count_match", false)) THEN 'verified'::"text"
            WHEN ("v"."status" = 'failed'::"text") THEN 'failed'::"text"
            WHEN ("v"."status" = 'blocked'::"text") THEN 'blocked'::"text"
            ELSE 'needs_work'::"text"
        END AS "verification_signal"
   FROM ("public"."backup_restore_verifications" "v"
     LEFT JOIN "public"."production_backup_strategies" "s" ON (("s"."id" = "v"."backup_strategy_id")));

CREATE OR REPLACE VIEW "public"."v_risk_appetite_dashboard" WITH ("security_invoker"='true') AS
 WITH "risk_counts" AS (
         SELECT "risks"."organization_id",
            "risks"."category",
            "count"(*) FILTER (WHERE (("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("risks"."risk_level" = 'critical'::"public"."risk_level"))) AS "critical_open_risks",
            "count"(*) FILTER (WHERE (("risks"."status" <> ALL (ARRAY['closed'::"public"."risk_status", 'cancelled'::"public"."risk_status"])) AND ("risks"."risk_level" = 'high'::"public"."risk_level"))) AS "high_open_risks",
            COALESCE("max"("risks"."residual_score"), 0) AS "max_residual_score",
            (COALESCE("avg"("risks"."residual_score"), (0)::numeric))::numeric(10,2) AS "avg_residual_score"
           FROM "public"."risks"
          GROUP BY "risks"."organization_id", "risks"."category"
        )
 SELECT "ras"."id",
    "ras"."organization_id",
    "ras"."appetite_code",
    "ras"."title_en",
    "ras"."title_ar",
    "ras"."category",
    "ras"."max_residual_score",
    "ras"."max_critical_risks",
    "ras"."max_high_risks",
    COALESCE("rc"."critical_open_risks", (0)::bigint) AS "critical_open_risks",
    COALESCE("rc"."high_open_risks", (0)::bigint) AS "high_open_risks",
    COALESCE("rc"."max_residual_score", 0) AS "actual_max_residual_score",
    COALESCE("rc"."avg_residual_score", (0)::numeric) AS "actual_avg_residual_score",
        CASE
            WHEN (COALESCE("rc"."critical_open_risks", (0)::bigint) > "ras"."max_critical_risks") THEN 'critical'::"text"
            WHEN (COALESCE("rc"."max_residual_score", 0) > "ras"."max_residual_score") THEN 'warning'::"text"
            WHEN (COALESCE("rc"."high_open_risks", (0)::bigint) > "ras"."max_high_risks") THEN 'watch'::"text"
            ELSE 'normal'::"text"
        END AS "appetite_status",
    "ras"."review_due_date",
    "ras"."is_active"
   FROM ("public"."risk_appetite_statements" "ras"
     LEFT JOIN "risk_counts" "rc" ON ((("rc"."organization_id" = "ras"."organization_id") AND ("rc"."category" = "ras"."category"))))
  WHERE ("ras"."is_active" = true);

CREATE OR REPLACE VIEW "public"."v_rls_persona_lab" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."organization_id",
    "s"."persona_code",
    "s"."persona_name_en",
    "s"."persona_name_ar",
    "s"."role_name",
    "s"."access_scope",
    "s"."test_area",
    "s"."allowed_expectation",
    "s"."denied_expectation",
    "s"."is_critical",
    "s"."is_active",
    "s"."sort_order",
    "s"."created_at",
    "s"."updated_at",
    "latest"."result" AS "latest_result",
    "latest"."tested_at" AS "latest_tested_at",
    "latest"."evidence_note" AS "latest_evidence_note",
    "latest"."failure_note" AS "latest_failure_note",
        CASE
            WHEN ("latest"."result" IS NULL) THEN 'not_tested'::"text"
            WHEN ("latest"."result" = 'pass'::"text") THEN 'passed'::"text"
            WHEN ("latest"."result" = 'warning'::"text") THEN 'warning'::"text"
            WHEN ("latest"."result" = 'fail'::"text") THEN 'failed'::"text"
            ELSE 'pending'::"text"
        END AS "persona_status"
   FROM ("public"."rls_persona_scenarios" "s"
     LEFT JOIN LATERAL ( SELECT "r"."id",
            "r"."organization_id",
            "r"."scenario_id",
            "r"."tested_by",
            "r"."tested_at",
            "r"."result",
            "r"."evidence_note",
            "r"."failure_note",
            "r"."created_at"
           FROM "public"."rls_persona_test_runs" "r"
          WHERE ("r"."scenario_id" = "s"."id")
          ORDER BY "r"."tested_at" DESC
         LIMIT 1) "latest" ON (true));

COMMENT ON VIEW "public"."v_rls_persona_lab" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

CREATE OR REPLACE VIEW "public"."v_rollout_data_health_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    "name_en" AS "organization_name_en",
    ( SELECT "count"(*) AS "count"
           FROM "public"."divisions" "d"
          WHERE (("d"."organization_id" = "o"."id") AND ("d"."is_active" = true))) AS "active_divisions",
    ( SELECT "count"(*) AS "count"
           FROM "public"."departments" "d"
          WHERE (("d"."organization_id" = "o"."id") AND ("d"."is_active" = true))) AS "active_departments",
    ( SELECT "count"(*) AS "count"
           FROM "public"."units" "u"
          WHERE (("u"."organization_id" = "o"."id") AND ("u"."is_active" = true))) AS "active_units",
    ( SELECT "count"(*) AS "count"
           FROM "public"."profiles" "p"
          WHERE (("p"."organization_id" = "o"."id") AND ("p"."is_active" = true))) AS "active_profiles",
    ( SELECT "count"(*) AS "count"
           FROM "public"."bulk_import_batches" "b"
          WHERE (("b"."organization_id" = "o"."id") AND ("b"."status" = ANY (ARRAY['uploaded'::"public"."bulk_import_status", 'validated'::"public"."bulk_import_status", 'validated_with_errors'::"public"."bulk_import_status", 'approved_for_import'::"public"."bulk_import_status"])))) AS "open_import_batches",
    ( SELECT COALESCE("sum"("b"."invalid_rows"), (0)::bigint) AS "coalesce"
           FROM "public"."bulk_import_batches" "b"
          WHERE (("b"."organization_id" = "o"."id") AND ("b"."status" = ANY (ARRAY['uploaded'::"public"."bulk_import_status", 'validated_with_errors'::"public"."bulk_import_status"])))) AS "unresolved_import_errors",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_duplicate_active_department_codes" "dd"
          WHERE ("dd"."organization_id" = "o"."id")) AS "duplicate_department_code_groups",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v_duplicate_profile_emails" "pe"
          WHERE ("pe"."organization_id" = "o"."id")) AS "duplicate_profile_email_groups"
   FROM "public"."organizations" "o";

CREATE OR REPLACE VIEW "public"."v_runtime_workflow_action_queue" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "action_request_id",
    "source_module",
    "source_type",
    "requested_action",
    "request_status",
    "priority",
    "requester_name",
    "assigned_reviewer_name",
    "due_at",
        CASE
            WHEN (("due_at" IS NOT NULL) AND ("due_at" < "now"()) AND ("request_status" <> ALL (ARRAY['executed'::"text", 'cancelled'::"text", 'rejected'::"text"]))) THEN 'overdue'::"text"
            WHEN ("priority" = ANY (ARRAY['critical'::"text", 'high'::"text"])) THEN 'high_priority'::"text"
            WHEN ("request_status" = 'failed'::"text") THEN 'failed'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."runtime_workflow_action_requests"
  WHERE ("request_status" <> ALL (ARRAY['executed'::"text", 'cancelled'::"text"]));

COMMENT ON VIEW "public"."v_runtime_workflow_action_queue" IS 'Patch 9 action queue; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_runtime_workflow_action_summary" WITH ("security_invoker"='true') AS
 SELECT COALESCE("r"."organization_id", "e"."organization_id", "o"."organization_id") AS "organization_id",
    ("count"(DISTINCT "r"."id"))::integer AS "action_request_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."request_status" = ANY (ARRAY['submitted'::"text", 'in_review'::"text"]))))::integer AS "active_request_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE (("r"."priority" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("r"."request_status" <> ALL (ARRAY['executed'::"text", 'cancelled'::"text", 'rejected'::"text"])))))::integer AS "high_priority_request_count",
    ("count"(DISTINCT "e"."id") FILTER (WHERE ("e"."exception_status" = 'open'::"text")))::integer AS "open_exception_count",
    ("count"(DISTINCT "o"."id") FILTER (WHERE ("o"."delivery_status" = ANY (ARRAY['pending'::"text", 'retrying'::"text", 'failed'::"text"]))))::integer AS "pending_outbox_count",
    ("count"(DISTINCT "b"."id") FILTER (WHERE ("b"."operation_status" = ANY (ARRAY['queued'::"text", 'running'::"text", 'partial_failure'::"text"]))))::integer AS "active_bulk_operation_count"
   FROM ((("public"."runtime_workflow_action_requests" "r"
     FULL JOIN "public"."runtime_workflow_exceptions" "e" ON (("e"."organization_id" = "r"."organization_id")))
     FULL JOIN "public"."runtime_workflow_integration_outbox" "o" ON (("o"."organization_id" = COALESCE("r"."organization_id", "e"."organization_id"))))
     LEFT JOIN "public"."runtime_workflow_bulk_operations" "b" ON (("b"."organization_id" = COALESCE("r"."organization_id", "e"."organization_id", "o"."organization_id"))))
  GROUP BY COALESCE("r"."organization_id", "e"."organization_id", "o"."organization_id");

CREATE OR REPLACE VIEW "public"."v_runtime_workflow_exception_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "exception_code",
    "source_module",
    "exception_type",
    "severity",
    "exception_status",
    "owner_name",
    "due_date",
        CASE
            WHEN (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("exception_status" = 'open'::"text")) THEN 'overdue'::"text"
            WHEN (("severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("exception_status" = 'open'::"text")) THEN 'high_attention'::"text"
            WHEN ("exception_status" = 'resolved'::"text") THEN 'resolved'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."runtime_workflow_exceptions";

CREATE OR REPLACE VIEW "public"."v_runtime_workflow_notification_outbox" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "outbox_id",
    "event_code",
    "event_type",
    "source_module",
    "target_system",
    "delivery_status",
    "retry_count",
    "last_error",
    "created_at",
    "sent_at",
        CASE
            WHEN ("delivery_status" = 'failed'::"text") THEN 'failed'::"text"
            WHEN ("delivery_status" = 'retrying'::"text") THEN 'retrying'::"text"
            WHEN (("delivery_status" = 'pending'::"text") AND ("created_at" < ("now"() - '02:00:00'::interval))) THEN 'stale_pending'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."runtime_workflow_integration_outbox";

CREATE OR REPLACE VIEW "public"."v_scenario_matrix" WITH ("security_invoker"='true') AS
 SELECT "s"."id",
    "s"."organization_id",
    "s"."scenario_code",
    "s"."title_en",
    COALESCE("s"."title_ar", "s"."title_en") AS "title_ar",
    "s"."category",
    "s"."probability",
    "s"."impact",
    "s"."exposure_score",
    "s"."estimated_financial_impact",
    "s"."mitigation_summary",
    "s"."trigger_indicators",
    COALESCE("p"."full_name_en", 'Unassigned'::"text") AS "owner_name",
    "s"."status",
        CASE
            WHEN ("s"."exposure_score" >= 20) THEN 'critical'::"text"
            WHEN ("s"."exposure_score" >= 12) THEN 'high'::"text"
            WHEN ("s"."exposure_score" >= 6) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "exposure_level",
    "s"."updated_at"
   FROM ("public"."risk_scenarios" "s"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "s"."owner_id")));

CREATE OR REPLACE VIEW "public"."v_security_access_findings" WITH ("security_invoker"='true') AS
 WITH "role_counts" AS (
         SELECT COALESCE("ur"."organization_id", "p"."organization_id") AS "organization_id",
            "count"(*) FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."role" = ANY (ARRAY['super_admin'::"public"."app_role", 'executive'::"public"."app_role", 'governance_admin'::"public"."app_role"])) AND ("ur"."scope" = 'global'::"public"."access_scope"))) AS "sensitive_global_roles",
            "count"(*) FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."role" = ANY (ARRAY['employee'::"public"."app_role", 'viewer'::"public"."app_role"])) AND ("ur"."scope" = ANY (ARRAY['global'::"public"."access_scope", 'division'::"public"."access_scope"])))) AS "broad_limited_roles",
            "count"(*) FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."scope" = 'department'::"public"."access_scope") AND ("ur"."department_id" IS NULL))) AS "missing_department_scope",
            "count"(*) FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."assigned_at" < ("now"() - '180 days'::interval)) AND ("ur"."role" = ANY (ARRAY['super_admin'::"public"."app_role", 'executive'::"public"."app_role", 'governance_admin'::"public"."app_role"])))) AS "stale_sensitive_roles"
           FROM ("public"."user_roles" "ur"
             LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "ur"."user_id")))
          GROUP BY COALESCE("ur"."organization_id", "p"."organization_id")
        )
 SELECT "role_counts"."organization_id",
    'sensitive_global_roles'::"text" AS "finding_key",
        CASE
            WHEN ("role_counts"."sensitive_global_roles" > 5) THEN 'critical'::"text"
            WHEN ("role_counts"."sensitive_global_roles" > 0) THEN 'high'::"text"
            ELSE 'low'::"text"
        END AS "severity",
    'Sensitive global roles require review'::"text" AS "title_en",
    'الأدوار الحساسة بنطاق عام تحتاج مراجعة'::"text" AS "title_ar",
    'Super admin, executive and governance admin roles should have owner, expiry and quarterly review evidence.'::"text" AS "details_en",
    'يجب أن يكون لأدوار مدير النظام والتنفيذي ومسؤول الحوكمة مسؤول وتاريخ انتهاء ودليل مراجعة ربع سنوي.'::"text" AS "details_ar",
    "role_counts"."sensitive_global_roles" AS "record_count",
    '/access-control'::"text" AS "action_path"
   FROM "role_counts"
UNION ALL
 SELECT "role_counts"."organization_id",
    'broad_limited_roles'::"text" AS "finding_key",
        CASE
            WHEN ("role_counts"."broad_limited_roles" > 0) THEN 'high'::"text"
            ELSE 'low'::"text"
        END AS "severity",
    'Broad scope assigned to limited roles'::"text" AS "title_en",
    'نطاق واسع لأدوار محدودة'::"text" AS "title_ar",
    'Employees/viewers should not have global or division access unless approved as an exception.'::"text" AS "details_en",
    'يجب ألا يحصل الموظفون أو المشاهدون على صلاحية عامة أو على مستوى قطاع إلا كاستثناء معتمد.'::"text" AS "details_ar",
    "role_counts"."broad_limited_roles" AS "record_count",
    '/access-control'::"text" AS "action_path"
   FROM "role_counts"
UNION ALL
 SELECT "role_counts"."organization_id",
    'missing_department_scope'::"text" AS "finding_key",
        CASE
            WHEN ("role_counts"."missing_department_scope" > 0) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "severity",
    'Scoped roles missing department references'::"text" AS "title_en",
    'أدوار محددة النطاق بدون إدارة مرتبطة'::"text" AS "title_ar",
    'Department-scoped roles must reference the department so RLS and dashboards remain accurate.'::"text" AS "details_en",
    'يجب أن ترتبط الأدوار ذات نطاق الإدارة بالإدارة لضمان دقة الصلاحيات واللوحات.'::"text" AS "details_ar",
    "role_counts"."missing_department_scope" AS "record_count",
    '/access-control'::"text" AS "action_path"
   FROM "role_counts"
UNION ALL
 SELECT "role_counts"."organization_id",
    'stale_sensitive_roles'::"text" AS "finding_key",
        CASE
            WHEN ("role_counts"."stale_sensitive_roles" > 0) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "severity",
    'Sensitive roles older than review window'::"text" AS "title_en",
    'أدوار حساسة أقدم من فترة المراجعة'::"text" AS "title_ar",
    'Sensitive access older than 180 days should be re-certified before full rollout.'::"text" AS "details_en",
    'الصلاحيات الحساسة الأقدم من 180 يوماً يجب إعادة اعتمادها قبل التشغيل الكامل.'::"text" AS "details_ar",
    "role_counts"."stale_sensitive_roles" AS "record_count",
    '/security'::"text" AS "action_path"
   FROM "role_counts";

CREATE OR REPLACE VIEW "public"."v_security_governance_summary" WITH ("security_invoker"='true') AS
 WITH "orgs" AS (
         SELECT "organizations"."id" AS "organization_id"
           FROM "public"."organizations"
          WHERE ("organizations"."is_active" = true)
        ), "access_findings" AS (
         SELECT "v_security_access_findings"."organization_id",
            "sum"("v_security_access_findings"."record_count") AS "total_findings"
           FROM "public"."v_security_access_findings"
          WHERE ("v_security_access_findings"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text", 'medium'::"text"]))
          GROUP BY "v_security_access_findings"."organization_id"
        ), "sensitive_roles" AS (
         SELECT COALESCE("ur"."organization_id", "p"."organization_id") AS "organization_id",
            "count"(*) FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."role" = ANY (ARRAY['super_admin'::"public"."app_role", 'executive'::"public"."app_role", 'governance_admin'::"public"."app_role"])))) AS "active_sensitive_roles",
            "count"(*) FILTER (WHERE (("ur"."is_active" = true) AND ("ur"."scope" = 'global'::"public"."access_scope") AND ("ur"."assigned_at" < ("now"() - '180 days'::interval)))) AS "stale_global_roles"
           FROM ("public"."user_roles" "ur"
             LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "ur"."user_id")))
          GROUP BY COALESCE("ur"."organization_id", "p"."organization_id")
        ), "retention" AS (
         SELECT "v_data_retention_readiness"."organization_id",
            "count"(*) FILTER (WHERE ("v_data_retention_readiness"."status" = 'active'::"public"."retention_rule_status")) AS "retention_rules_active",
            COALESCE("sum"("v_data_retention_readiness"."records_past_retention"), (0)::numeric) AS "pending_retention_actions"
           FROM "public"."v_data_retention_readiness"
          GROUP BY "v_data_retention_readiness"."organization_id"
        ), "events" AS (
         SELECT "security_review_events"."organization_id",
            "count"(*) FILTER (WHERE ("security_review_events"."resolved_at" IS NULL)) AS "pending_security_reviews",
            "count"(*) FILTER (WHERE (("security_review_events"."severity" = ANY (ARRAY['critical'::"public"."security_event_severity", 'high'::"public"."security_event_severity"])) AND ("security_review_events"."created_at" >= ("now"() - '30 days'::interval)))) AS "high_risk_audit_events_30d",
            "max"("security_review_events"."created_at") AS "last_review_at"
           FROM "public"."security_review_events"
          GROUP BY "security_review_events"."organization_id"
        )
 SELECT "o"."organization_id",
    (GREATEST((0)::numeric, LEAST((100)::numeric, ((((((100)::numeric - (COALESCE("af"."total_findings", (0)::numeric) * (4)::numeric)) - ((COALESCE("sr"."stale_global_roles", (0)::bigint) * 5))::numeric) - ((COALESCE("ev"."high_risk_audit_events_30d", (0)::bigint) * 6))::numeric) - (
        CASE
            WHEN (COALESCE("rt"."retention_rules_active", (0)::bigint) = 0) THEN 15
            ELSE 0
        END)::numeric) - LEAST(COALESCE("rt"."pending_retention_actions", (0)::numeric), (10)::numeric)))))::integer AS "security_score",
    COALESCE("sr"."active_sensitive_roles", (0)::bigint) AS "active_sensitive_roles",
    COALESCE("sr"."stale_global_roles", (0)::bigint) AS "stale_global_roles",
    COALESCE("af"."total_findings", (0)::numeric) AS "unresolved_access_warnings",
    COALESCE("ev"."pending_security_reviews", (0)::bigint) AS "pending_security_reviews",
    COALESCE("ev"."high_risk_audit_events_30d", (0)::bigint) AS "high_risk_audit_events_30d",
    COALESCE("rt"."retention_rules_active", (0)::bigint) AS "retention_rules_active",
    COALESCE("rt"."pending_retention_actions", (0)::numeric) AS "pending_retention_actions",
    "ev"."last_review_at"
   FROM (((("orgs" "o"
     LEFT JOIN "access_findings" "af" ON (("af"."organization_id" = "o"."organization_id")))
     LEFT JOIN "sensitive_roles" "sr" ON (("sr"."organization_id" = "o"."organization_id")))
     LEFT JOIN "retention" "rt" ON (("rt"."organization_id" = "o"."organization_id")))
     LEFT JOIN "events" "ev" ON (("ev"."organization_id" = "o"."organization_id")));

CREATE OR REPLACE VIEW "public"."v_sensitive_activity_timeline" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."organization_id",
    "e"."activity_type",
    ("e"."severity")::"text" AS "severity",
    "p"."full_name_en" AS "actor_name",
    "e"."summary_en",
    COALESCE("e"."summary_ar", "e"."summary_en") AS "summary_ar",
    "e"."source_table",
    "e"."source_record_id",
    "e"."created_at"
   FROM ("public"."security_review_events" "e"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "e"."actor_id")))
UNION ALL
 SELECT "a"."id",
    "a"."organization_id",
    'audit_log'::"text" AS "activity_type",
        CASE
            WHEN (("a"."action" ~~* '%delete%'::"text") OR ("a"."action" ~~* '%role%'::"text")) THEN 'high'::"text"
            WHEN (("a"."action" ~~* '%approve%'::"text") OR ("a"."action" ~~* '%close%'::"text")) THEN 'medium'::"text"
            ELSE 'low'::"text"
        END AS "severity",
    "p"."full_name_en" AS "actor_name",
    "concat"('Audit action: ', "a"."action", ' on ', "a"."table_name") AS "summary_en",
    "concat"('إجراء تدقيق: ', "a"."action", ' على ', "a"."table_name") AS "summary_ar",
    "a"."table_name" AS "source_table",
    "a"."record_id" AS "source_record_id",
    "a"."created_at"
   FROM ("public"."audit_logs" "a"
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "a"."actor_id")))
  WHERE ("a"."created_at" >= ("now"() - '30 days'::interval));

CREATE OR REPLACE VIEW "public"."v_setup_readiness_checklist" WITH ("security_invoker"='true') AS
 WITH "org" AS (
         SELECT "organizations"."id" AS "organization_id"
           FROM "public"."organizations"
          WHERE ("organizations"."is_active" = true)
         LIMIT 1
        ), "counts" AS (
         SELECT "o"."organization_id",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."divisions" "d"
                  WHERE (("d"."organization_id" = "o"."organization_id") AND ("d"."is_active" = true))) AS "active_divisions",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."departments" "d"
                  WHERE (("d"."organization_id" = "o"."organization_id") AND ("d"."is_active" = true))) AS "active_departments",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."units" "u"
                  WHERE (("u"."organization_id" = "o"."organization_id") AND ("u"."is_active" = true))) AS "active_units",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."profiles" "p"
                  WHERE (("p"."organization_id" = "o"."organization_id") AND ("p"."is_active" = true))) AS "active_users",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."user_roles" "ur"
                  WHERE (("ur"."organization_id" = "o"."organization_id") AND ("ur"."is_active" = true))) AS "active_roles",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."user_roles" "ur"
                  WHERE (("ur"."organization_id" = "o"."organization_id") AND ("ur"."is_active" = true) AND ("ur"."role" = 'super_admin'::"public"."app_role"))) AS "super_admins",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."user_roles" "ur"
                  WHERE (("ur"."organization_id" = "o"."organization_id") AND ("ur"."is_active" = true) AND ("ur"."role" = 'governance_admin'::"public"."app_role"))) AS "governance_admins",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."user_roles" "ur"
                  WHERE (("ur"."organization_id" = "o"."organization_id") AND ("ur"."is_active" = true) AND ("ur"."role" = ANY (ARRAY['compliance_officer'::"public"."app_role", 'auditor'::"public"."app_role"])))) AS "control_reviewers",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."projects" "p"
                  WHERE (("p"."organization_id" = "o"."organization_id") AND ("p"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])) AND ("p"."owner_id" IS NULL))) AS "projects_missing_owner",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."tasks" "t"
                  WHERE (("t"."organization_id" = "o"."organization_id") AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'cancelled'::"public"."work_status", 'approved'::"public"."work_status"])) AND ("t"."due_date" IS NULL))) AS "tasks_missing_due_date",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."ovr_reports" "r"
                  WHERE (("r"."organization_id" = "o"."organization_id") AND ("r"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status", 'under_quality_review'::"public"."ovr_status", 'action_plan_required'::"public"."ovr_status", 'corrective_action_in_progress'::"public"."ovr_status", 'evidence_submitted'::"public"."ovr_status"])))) AS "open_ovrs",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."backup_packages" "b"
                  WHERE (("b"."organization_id" = "o"."organization_id") AND ("b"."created_at" >= ("now"() - '14 days'::interval)))) AS "recent_backups",
            ( SELECT "count"(*) AS "count"
                   FROM "public"."custom_report_definitions" "cr"
                  WHERE (("cr"."organization_id" = "o"."organization_id") AND ("cr"."is_active" = true))) AS "active_reports"
           FROM "org" "o"
        )
 SELECT 'organization_structure'::"text" AS "check_key",
    'Organization structure'::"text" AS "title_en",
    'الهيكل التنظيمي'::"text" AS "title_ar",
    'Divisions, departments and units/stations are ready for assignment.'::"text" AS "description_en",
    'تم تجهيز القطاعات والإدارات والوحدات/المحطات للتكليف.'::"text" AS "description_ar",
    'organization'::"text" AS "area",
        CASE
            WHEN ("counts"."active_departments" >= 50) THEN 'good'::"text"
            WHEN ("counts"."active_departments" >= 10) THEN 'warning'::"text"
            ELSE 'critical'::"text"
        END AS "severity",
    ("counts"."active_departments")::integer AS "current_count",
    50 AS "target_count",
    ("counts"."active_departments" >= 50) AS "is_complete",
    'Import all departments and unit/station codes before full rollout.'::"text" AS "action_hint_en",
    'استورد جميع الإدارات وأكواد الوحدات/المحطات قبل التشغيل الكامل.'::"text" AS "action_hint_ar"
   FROM "counts"
UNION ALL
 SELECT 'active_users'::"text" AS "check_key",
    'Active users'::"text" AS "title_en",
    'المستخدمون النشطون'::"text" AS "title_ar",
    'Employees have profiles ready for role assignment.'::"text" AS "description_en",
    'الموظفون لديهم ملفات جاهزة لتعيين الصلاحيات.'::"text" AS "description_ar",
    'users'::"text" AS "area",
        CASE
            WHEN ("counts"."active_users" >= 1000) THEN 'good'::"text"
            WHEN ("counts"."active_users" >= 100) THEN 'warning'::"text"
            ELSE 'critical'::"text"
        END AS "severity",
    ("counts"."active_users")::integer AS "current_count",
    1000 AS "target_count",
    ("counts"."active_users" >= 1000) AS "is_complete",
    'Import employees in waves, then review access warnings.'::"text" AS "action_hint_en",
    'استورد الموظفين على دفعات ثم راجع تنبيهات الصلاحيات.'::"text" AS "action_hint_ar"
   FROM "counts"
UNION ALL
 SELECT 'critical_roles'::"text" AS "check_key",
    'Critical admin/control roles'::"text" AS "title_en",
    'أدوار التحكم الحرجة'::"text" AS "title_ar",
    'Super Admin, Governance Admin and control reviewers are assigned.'::"text" AS "description_en",
    'تم تعيين المسؤول العام ومسؤول الحوكمة ومراجعي التحكم.'::"text" AS "description_ar",
    'users'::"text" AS "area",
        CASE
            WHEN (("counts"."super_admins" >= 1) AND ("counts"."governance_admins" >= 1) AND ("counts"."control_reviewers" >= 1)) THEN 'good'::"text"
            ELSE 'critical'::"text"
        END AS "severity",
    ((("counts"."super_admins" + "counts"."governance_admins") + "counts"."control_reviewers"))::integer AS "current_count",
    3 AS "target_count",
    (("counts"."super_admins" >= 1) AND ("counts"."governance_admins" >= 1) AND ("counts"."control_reviewers" >= 1)) AS "is_complete",
    'Assign at least one Super Admin, Governance Admin and Quality/Audit reviewer.'::"text" AS "action_hint_en",
    'عيّن على الأقل مسؤولاً عاماً ومسؤول حوكمة ومراجع جودة/مراجعة.'::"text" AS "action_hint_ar"
   FROM "counts"
UNION ALL
 SELECT 'workflow_ownership'::"text" AS "check_key",
    'Workflow ownership'::"text" AS "title_en",
    'ملكية سير العمل'::"text" AS "title_ar",
    'Active projects and tasks have owners and due dates.'::"text" AS "description_en",
    'المشاريع والمهام النشطة لها مسؤولون وتواريخ استحقاق.'::"text" AS "description_ar",
    'workflow'::"text" AS "area",
        CASE
            WHEN (("counts"."projects_missing_owner" = 0) AND ("counts"."tasks_missing_due_date" = 0)) THEN 'good'::"text"
            WHEN (("counts"."projects_missing_owner" <= 5) AND ("counts"."tasks_missing_due_date" <= 10)) THEN 'warning'::"text"
            ELSE 'critical'::"text"
        END AS "severity",
    (("counts"."projects_missing_owner" + "counts"."tasks_missing_due_date"))::integer AS "current_count",
    0 AS "target_count",
    (("counts"."projects_missing_owner" = 0) AND ("counts"."tasks_missing_due_date" = 0)) AS "is_complete",
    'Fix missing owners and due dates before department launch.'::"text" AS "action_hint_en",
    'عالج غياب المسؤولين وتواريخ الاستحقاق قبل إطلاق الإدارات.'::"text" AS "action_hint_ar"
   FROM "counts"
UNION ALL
 SELECT 'ovr_operational'::"text" AS "check_key",
    'OVR operational readiness'::"text" AS "title_en",
    'جاهزية تشغيل OVR'::"text" AS "title_ar",
    'OVR reports can be investigated, reviewed by Quality and closed with evidence.'::"text" AS "description_en",
    'يمكن التحقيق في بلاغات OVR ومراجعتها من الجودة وإغلاقها بالأدلة.'::"text" AS "description_ar",
    'ovr'::"text" AS "area",
        CASE
            WHEN ("counts"."open_ovrs" = 0) THEN 'good'::"text"
            WHEN ("counts"."open_ovrs" <= 20) THEN 'warning'::"text"
            ELSE 'critical'::"text"
        END AS "severity",
    ("counts"."open_ovrs")::integer AS "current_count",
    0 AS "target_count",
    ("counts"."open_ovrs" = 0) AS "is_complete",
    'Train Quality and department managers before enabling wide OVR submission.'::"text" AS "action_hint_en",
    'درّب الجودة ومديري الإدارات قبل تفعيل تقديم OVR على نطاق واسع.'::"text" AS "action_hint_ar"
   FROM "counts"
UNION ALL
 SELECT 'backup_readiness'::"text" AS "check_key",
    'Backup/export readiness'::"text" AS "title_en",
    'جاهزية النسخ والتصدير'::"text" AS "title_ar",
    'A recent backup/export package exists before rollout changes.'::"text" AS "description_en",
    'توجد نسخة تصدير حديثة قبل تغييرات التشغيل.'::"text" AS "description_ar",
    'backup'::"text" AS "area",
        CASE
            WHEN ("counts"."recent_backups" >= 1) THEN 'good'::"text"
            ELSE 'warning'::"text"
        END AS "severity",
    ("counts"."recent_backups")::integer AS "current_count",
    1 AS "target_count",
    ("counts"."recent_backups" >= 1) AS "is_complete",
    'Create an export package before large imports, migrations or permission changes.'::"text" AS "action_hint_en",
    'أنشئ حزمة تصدير قبل الاستيرادات الكبيرة أو الترحيلات أو تغييرات الصلاحيات.'::"text" AS "action_hint_ar"
   FROM "counts"
UNION ALL
 SELECT 'custom_reports'::"text" AS "check_key",
    'Custom report templates'::"text" AS "title_en",
    'قوالب التقارير المخصصة'::"text" AS "title_ar",
    'Executive and department report definitions are available.'::"text" AS "description_en",
    'تتوفر تعريفات تقارير تنفيذية وتقارير للإدارات.'::"text" AS "description_ar",
    'reports'::"text" AS "area",
        CASE
            WHEN ("counts"."active_reports" >= 4) THEN 'good'::"text"
            WHEN ("counts"."active_reports" >= 1) THEN 'warning'::"text"
            ELSE 'critical'::"text"
        END AS "severity",
    ("counts"."active_reports")::integer AS "current_count",
    4 AS "target_count",
    ("counts"."active_reports" >= 4) AS "is_complete",
    'Create executive, OVR, department and audit/compliance report packs.'::"text" AS "action_hint_en",
    'أنشئ حزم تقارير تنفيذية وOVR والإدارات والمراجعة/الالتزام.'::"text" AS "action_hint_ar"
   FROM "counts";

COMMENT ON VIEW "public"."v_setup_readiness_checklist" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

CREATE OR REPLACE VIEW "public"."v_staging_validation_checks" WITH ("security_invoker"='true') AS
 SELECT "ch"."id",
    "ch"."organization_id",
    "ch"."cycle_id",
    "ch"."check_area",
    "ch"."check_code",
    "ch"."check_title",
    "ch"."status",
    "ch"."severity",
    "ch"."owner_label",
    "ch"."evidence_note",
    "ch"."result_note",
    "ch"."sort_order",
    "ch"."created_at",
    "ch"."updated_at",
    "c"."cycle_code",
    "c"."title" AS "cycle_title",
    "c"."environment_name",
    "c"."status" AS "cycle_status",
        CASE
            WHEN ("ch"."status" = 'blocked'::"text") THEN 100
            WHEN ("ch"."status" = 'warning'::"text") THEN 60
            WHEN ("ch"."status" = 'pending'::"text") THEN 30
            WHEN ("ch"."status" = 'pass'::"text") THEN 0
            ELSE 10
        END AS "attention_weight"
   FROM ("public"."staging_validation_check_results" "ch"
     LEFT JOIN "public"."staging_validation_cycles" "c" ON (("c"."id" = "ch"."cycle_id")));

CREATE OR REPLACE VIEW "public"."v_staging_validation_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    COALESCE("max"("c"."created_at"), "now"()) AS "last_cycle_created_at",
    "count"(DISTINCT "c"."id") AS "cycles",
    "count"("ch"."id") FILTER (WHERE ("ch"."status" = 'blocked'::"text")) AS "blocked_checks",
    "count"("ch"."id") FILTER (WHERE ("ch"."status" = 'warning'::"text")) AS "warning_checks",
    "count"("ch"."id") FILTER (WHERE ("ch"."status" = 'pass'::"text")) AS "passed_checks",
    "count"("ch"."id") FILTER (WHERE ("ch"."status" = 'pending'::"text")) AS "pending_checks",
        CASE
            WHEN ("count"("ch"."id") = 0) THEN 0
            ELSE ("round"(((100.0 * ("count"("ch"."id") FILTER (WHERE ("ch"."status" = 'pass'::"text")))::numeric) / ("count"("ch"."id"))::numeric)))::integer
        END AS "staging_readiness_score",
    "count"("cd"."id") FILTER (WHERE (("cd"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("cd"."severity" = 'critical'::"text"))) AS "critical_open_defects",
    "count"("cd"."id") FILTER (WHERE (("cd"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("cd"."severity" = 'high'::"text"))) AS "high_open_defects"
   FROM ((("public"."organizations" "o"
     LEFT JOIN "public"."staging_validation_cycles" "c" ON (("c"."organization_id" = "o"."id")))
     LEFT JOIN "public"."staging_validation_check_results" "ch" ON ((("ch"."organization_id" = "o"."id") AND (("ch"."cycle_id" = "c"."id") OR ("c"."id" IS NULL)))))
     LEFT JOIN "public"."consolidation_defect_log" "cd" ON (("cd"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_uat_findings_queue" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "finding_code",
    "finding_title",
    "severity",
    "finding_status",
    "owner_name",
    "due_date",
        CASE
            WHEN (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("finding_status" = ANY (ARRAY['open'::"text", 'assigned'::"text"]))) THEN 'overdue'::"text"
            WHEN (("severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("finding_status" = ANY (ARRAY['open'::"text", 'assigned'::"text"]))) THEN 'high_attention'::"text"
            WHEN ("finding_status" = 'retest_passed'::"text") THEN 'ready_to_close'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM "public"."uat_readiness_findings"
  WHERE ("finding_status" <> 'cancelled'::"text");

CREATE OR REPLACE VIEW "public"."v_uat_readiness_dashboard" WITH ("security_invoker"='true') AS
 SELECT "c"."organization_id",
    "c"."cycle_code",
    "c"."cycle_name",
    "c"."cycle_status",
    "c"."planned_end_date",
    ("count"(DISTINCT "s"."id"))::integer AS "scenario_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."run_status" = 'passed'::"text")))::integer AS "passed_run_count",
    ("count"(DISTINCT "r"."id") FILTER (WHERE ("r"."run_status" = ANY (ARRAY['failed'::"text", 'blocked'::"text", 'retest_required'::"text"]))))::integer AS "failed_or_blocked_run_count",
    ("count"(DISTINCT "f"."id") FILTER (WHERE ("f"."finding_status" = ANY (ARRAY['open'::"text", 'assigned'::"text"]))))::integer AS "open_finding_count",
        CASE
            WHEN (("c"."planned_end_date" IS NOT NULL) AND ("c"."planned_end_date" < CURRENT_DATE) AND ("c"."cycle_status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"]))) THEN 'overdue_cycle'::"text"
            WHEN ("count"(DISTINCT "f"."id") FILTER (WHERE (("f"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])) AND ("f"."finding_status" = ANY (ARRAY['open'::"text", 'assigned'::"text"])))) > 0) THEN 'high_findings'::"text"
            WHEN ("c"."cycle_status" = 'completed'::"text") THEN 'complete'::"text"
            ELSE 'normal'::"text"
        END AS "readiness_signal"
   FROM ((("public"."uat_readiness_cycles" "c"
     LEFT JOIN "public"."uat_readiness_scenarios" "s" ON (("s"."cycle_id" = "c"."id")))
     LEFT JOIN "public"."uat_readiness_runs" "r" ON (("r"."scenario_id" = "s"."id")))
     LEFT JOIN "public"."uat_readiness_findings" "f" ON (("f"."run_id" = "r"."id")))
  GROUP BY "c"."organization_id", "c"."cycle_code", "c"."cycle_name", "c"."cycle_status", "c"."planned_end_date";

COMMENT ON VIEW "public"."v_uat_readiness_dashboard" IS 'Patch 10 UAT readiness dashboard; security_invoker keeps RLS active.';

CREATE OR REPLACE VIEW "public"."v_ultra_release_summary" WITH ("security_invoker"='true') AS
 SELECT "id" AS "organization_id",
    (GREATEST((0)::bigint, LEAST((100)::bigint, ((((100 - (( SELECT "count"(*) AS "count"
           FROM "public"."production_cutover_checklist" "c"
          WHERE (("c"."organization_id" = "o"."id") AND ("c"."status" = 'blocked'::"text"))) * 18)) - (( SELECT "count"(*) AS "count"
           FROM "public"."production_cutover_checklist" "c"
          WHERE (("c"."organization_id" = "o"."id") AND ("c"."status" = 'warning'::"text"))) * 6)) -
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "public"."restore_dry_run_jobs" "r"
              WHERE (("r"."organization_id" = "o"."id") AND ("r"."status" = 'passed'::"text"))))) THEN 12
            ELSE 0
        END) -
        CASE
            WHEN (NOT (EXISTS ( SELECT 1
               FROM "public"."backup_packages" "b"
              WHERE (("b"."organization_id" = "o"."id") AND ("b"."created_at" >= ("now"() - '30 days'::interval)))))) THEN 8
            ELSE 0
        END))))::integer AS "release_score",
    (( SELECT "count"(*) AS "count"
           FROM "public"."production_cutover_checklist" "c"
          WHERE (("c"."organization_id" = "o"."id") AND ("c"."status" = 'blocked'::"text"))))::integer AS "blocker_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."production_cutover_checklist" "c"
          WHERE (("c"."organization_id" = "o"."id") AND ("c"."status" = 'warning'::"text"))))::integer AS "warning_count",
    ( SELECT "max"("b"."created_at") AS "max"
           FROM "public"."backup_packages" "b"
          WHERE ("b"."organization_id" = "o"."id")) AS "last_backup_at",
    ( SELECT "max"("r"."finished_at") AS "max"
           FROM "public"."restore_dry_run_jobs" "r"
          WHERE (("r"."organization_id" = "o"."id") AND ("r"."status" = 'passed'::"text"))) AS "last_restore_dry_run_at",
    (( SELECT "count"(*) AS "count"
           FROM "public"."release_migration_order"
          WHERE ("release_migration_order"."required" = true)))::integer AS "migrations_expected",
    (( SELECT "count"(*) AS "count"
           FROM "public"."release_migration_order"
          WHERE (("release_migration_order"."required" = true) AND ("release_migration_order"."sequence_no" < 23))))::integer AS "migrations_verified",
    (( SELECT
                CASE
                    WHEN ("count"(*) = 0) THEN (100)::numeric
                    ELSE "round"(((100.0 * ("count"(*) FILTER (WHERE ((COALESCE(TRIM(BOTH FROM "app_translation_dictionary"."english_label"), ''::"text") <> ''::"text") AND (COALESCE(TRIM(BOTH FROM "app_translation_dictionary"."arabic_label"), ''::"text") <> ''::"text") AND ("app_translation_dictionary"."needs_review" = false))))::numeric) / ("count"(*))::numeric))
                END AS "round"
           FROM "public"."app_translation_dictionary"))::integer AS "translation_coverage",
    (( SELECT "count"(*) AS "count"
           FROM "public"."admin_safety_locks" "l"
          WHERE (("l"."organization_id" = "o"."id") AND ("l"."is_active" = true))))::integer AS "admin_locks_active"
   FROM "public"."organizations" "o";

COMMENT ON VIEW "public"."v_ultra_release_summary" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

