    NULL::"text" AS "full_name_en",
    NULL::"text" AS "full_name_ar",
    NULL::"text" AS "email",
    NULL::"text" AS "phone",
    NULL::"text" AS "job_title",
    NULL::"text" AS "user_type",
    NULL::"text" AS "user_status",
    NULL::boolean AS "is_active",
    NULL::timestamp with time zone AS "created_at",
    NULL::timestamp with time zone AS "updated_at",
    NULL::timestamp with time zone AS "last_login_at",
    NULL::timestamp with time zone AS "last_reviewed_at",
    NULL::timestamp with time zone AS "deactivated_at",
    NULL::"uuid" AS "deactivated_by",
    NULL::"text" AS "deactivation_reason",
    NULL::"uuid" AS "division_id",
    NULL::"text" AS "division_name",
    NULL::"uuid" AS "department_id",
    NULL::"text" AS "department_code",
    NULL::"text" AS "department_name",
    NULL::"text" AS "department_name_ar",
    NULL::"uuid" AS "unit_id",
    NULL::"text" AS "unit_name",
    NULL::integer AS "active_role_count",
    NULL::"jsonb" AS "roles",
    NULL::integer AS "linked_project_count",
    NULL::integer AS "linked_task_count",
    NULL::integer AS "linked_approval_count",
    NULL::integer AS "linked_evidence_count",
    NULL::integer AS "open_project_count",
