CREATE OR REPLACE VIEW "public"."v_user_management_summary" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    ("count"("p"."id"))::integer AS "total_users",
    ("count"("p"."id") FILTER (WHERE (COALESCE("p"."user_status", 'active'::"text") = 'active'::"text")))::integer AS "active_users",
    ("count"("p"."id") FILTER (WHERE (COALESCE("p"."user_status", 'active'::"text") = 'inactive'::"text")))::integer AS "inactive_users",
    ("count"("p"."id") FILTER (WHERE (COALESCE("p"."user_status", 'active'::"text") = 'archived'::"text")))::integer AS "archived_users",
    ("count"("p"."id") FILTER (WHERE (COALESCE("p"."user_status", 'active'::"text") = 'invited'::"text")))::integer AS "invited_users",
    ("count"("p"."id") FILTER (WHERE (COALESCE("p"."user_status", 'active'::"text") = 'locked'::"text")))::integer AS "locked_users",
    ("count"("p"."id") FILTER (WHERE (("p"."department_id" IS NULL) AND (COALESCE("p"."user_status", 'active'::"text") <> 'archived'::"text"))))::integer AS "missing_department_users",
    ("count"("p"."id") FILTER (WHERE ((COALESCE("p"."user_status", 'active'::"text") <> 'archived'::"text") AND (NOT (EXISTS ( SELECT 1
           FROM "public"."user_roles" "ur"
          WHERE (("ur"."user_id" = "p"."id") AND ("ur"."is_active" = true))))))))::integer AS "missing_role_users",
    ("count"("p"."id") FILTER (WHERE ((COALESCE("p"."user_status", 'active'::"text") = 'invited'::"text") OR ("p"."department_id" IS NULL) OR (NOT (EXISTS ( SELECT 1
           FROM "public"."user_roles" "ur"
          WHERE (("ur"."user_id" = "p"."id") AND ("ur"."is_active" = true))))))))::integer AS "pending_setup_users"
   FROM ("public"."organizations" "o"
     LEFT JOIN "public"."profiles" "p" ON (("p"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_user_profile_completeness" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id" AS "user_id",
    "email",
    "full_name_en",
    "full_name_ar",
    "employee_no",
    "job_title",
    "department_id",
    COALESCE("user_status", 'active'::"text") AS "user_status",
    (("full_name_en" IS NOT NULL) AND (TRIM(BOTH FROM "full_name_en") <> ''::"text")) AS "has_english_name",
    (("email" IS NOT NULL) AND (TRIM(BOTH FROM "email") <> ''::"text")) AS "has_email",
    ("department_id" IS NOT NULL) AS "has_department",
    (EXISTS ( SELECT 1
           FROM "public"."user_roles" "ur"
          WHERE (("ur"."user_id" = "p"."id") AND ("ur"."is_active" = true)))) AS "has_active_role",
    (("full_name_en" IS NOT NULL) AND (TRIM(BOTH FROM "full_name_en") <> ''::"text") AND (("email" IS NOT NULL) AND (TRIM(BOTH FROM "email") <> ''::"text")) AND ("department_id" IS NOT NULL) AND (EXISTS ( SELECT 1
           FROM "public"."user_roles" "ur"
          WHERE (("ur"."user_id" = "p"."id") AND ("ur"."is_active" = true))))) AS "profile_complete"
   FROM "public"."profiles" "p";

CREATE OR REPLACE VIEW "public"."v_v31_final_controls" WITH ("security_invoker"='true') AS
 SELECT "id",
    "control_code",
    "control_group",
    "title",
    "description",
    "owner_label",
    "severity",
    "status",
    "evidence_required",
    "evidence_note",
    "go_live_blocking",
    "last_reviewed_at",
    "reviewed_by",
    "review_note",
    "created_at",
    "updated_at",
        CASE "severity"
            WHEN 'critical'::"text" THEN 1
            WHEN 'high'::"text" THEN 2
            WHEN 'medium'::"text" THEN 3
            ELSE 4
        END AS "severity_rank",
        CASE "status"
            WHEN 'blocked'::"text" THEN 1
            WHEN 'warning'::"text" THEN 2
            WHEN 'pending'::"text" THEN 3
            WHEN 'accepted_risk'::"text" THEN 4
            ELSE 5
        END AS "status_rank"
   FROM "public"."final_go_live_controls" "c";

CREATE OR REPLACE VIEW "public"."v_v31_go_live_scorecard" WITH ("security_invoker"='true') AS
 WITH "control_stats" AS (
         SELECT "count"(*) FILTER (WHERE ("final_go_live_controls"."go_live_blocking" AND ("final_go_live_controls"."status" = 'blocked'::"text"))) AS "blocking_items",
            "count"(*) FILTER (WHERE ("final_go_live_controls"."status" = ANY (ARRAY['warning'::"text", 'pending'::"text"]))) AS "warning_items",
            "count"(*) FILTER (WHERE ("final_go_live_controls"."status" = ANY (ARRAY['pass'::"text", 'accepted_risk'::"text"]))) AS "passed_items",
            "count"(*) FILTER (WHERE ("final_go_live_controls"."status" = 'pending'::"text")) AS "pending_items",
            "count"(*) AS "total_controls"
           FROM "public"."final_go_live_controls"
        ), "module_stats" AS (
         SELECT "count"(*) FILTER (WHERE ("module_release_readiness"."status" = 'ready'::"text")) AS "modules_ready",
            "count"(*) AS "modules_total"
           FROM "public"."module_release_readiness"
        ), "support_stats" AS (
         SELECT "count"(*) FILTER (WHERE ("production_support_handover"."status" = 'ready'::"text")) AS "support_owners_ready",
            "count"(*) AS "support_owners_total"
           FROM "public"."production_support_handover"
        ), "pilot_stats" AS (
         SELECT "count"(*) FILTER (WHERE ("pilot_rollout_acceptance"."status" = 'accepted'::"text")) AS "pilot_accepted",
            "count"(*) AS "pilot_total"
           FROM "public"."pilot_rollout_acceptance"
        )
 SELECT
        CASE
            WHEN ("cs"."blocking_items" > 0) THEN 'blocked'::"text"
            WHEN (("cs"."warning_items" > 0) OR ("ms"."modules_ready" < "ms"."modules_total") OR ("ss"."support_owners_ready" < "ss"."support_owners_total")) THEN 'conditional'::"text"
            ELSE 'go'::"text"
        END AS "readiness_signal",
    "cs"."blocking_items",
    "cs"."warning_items",
    "cs"."passed_items",
    "cs"."pending_items",
    "ms"."modules_ready",
    "ms"."modules_total",
    "ss"."support_owners_ready",
    "ss"."support_owners_total",
    (LEAST((100)::numeric, GREATEST((0)::numeric, "round"((((((((("cs"."passed_items")::numeric * (2)::numeric) + (("ms"."modules_ready")::numeric * (2)::numeric)) + (("ss"."support_owners_ready")::numeric * 1.5)) + (("ps"."pilot_accepted")::numeric * (2)::numeric)) - (("cs"."blocking_items")::numeric * (3)::numeric)) / GREATEST(((((("cs"."total_controls")::numeric * (2)::numeric) + (("ms"."modules_total")::numeric * (2)::numeric)) + (("ss"."support_owners_total")::numeric * 1.5)) + (("ps"."pilot_total")::numeric * (2)::numeric)), (1)::numeric)) * (100)::numeric)))))::integer AS "go_live_score"
   FROM ((("control_stats" "cs"
     CROSS JOIN "module_stats" "ms")
     CROSS JOIN "support_stats" "ss")
     CROSS JOIN "pilot_stats" "ps");

CREATE OR REPLACE VIEW "public"."v_v31_module_readiness" WITH ("security_invoker"='true') AS
 SELECT "id",
