        CASE "status"
            WHEN 'blocked'::"text" THEN 1
            WHEN 'needs_review'::"text" THEN 2
            WHEN 'pilot_only'::"text" THEN 3
            ELSE 4
        END AS "status_rank"
   FROM "public"."module_release_readiness" "m";

