    "created_at",
    "updated_at"
   FROM "public"."production_proof_gates";

CREATE OR REPLACE VIEW "public"."v_v33_production_proof_scorecard" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    'v3.3-production-proof'::"text" AS "release_tag",
    (GREATEST((0)::bigint, LEAST((100)::bigint, (((100 - (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = 'blocked'::"text") THEN 1
            ELSE 0
        END), (0)::bigint) * 18)) - (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = 'warning'::"text") THEN 1
            ELSE 0
        END), (0)::bigint) * 7)) - (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"])) THEN 1
            ELSE 0
        END), (0)::bigint) * 4)))))::integer AS "proof_score",
        CASE
            WHEN (COALESCE("sum"(
            CASE
                WHEN (("g"."status" = 'blocked'::"text") AND ("g"."severity" = 'hard_gate'::"text")) THEN 1
                ELSE 0
            END), (0)::bigint) > 0) THEN 'blocked'::"text"
            WHEN (COALESCE("sum"(
            CASE
                WHEN ("g"."status" = ANY (ARRAY['warning'::"text", 'pending'::"text", 'in_progress'::"text"])) THEN 1
                ELSE 0
            END), (0)::bigint) > 0) THEN 'conditional'::"text"
            ELSE 'go'::"text"
        END AS "go_live_signal",
    ("count"("g"."id"))::integer AS "total_gates",
    (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = 'passed'::"text") THEN 1
            ELSE 0
        END), (0)::bigint))::integer AS "passed_gates",
    (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = 'blocked'::"text") THEN 1
            ELSE 0
        END), (0)::bigint))::integer AS "blocked_gates",
    (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = 'warning'::"text") THEN 1
            ELSE 0
        END), (0)::bigint))::integer AS "warning_gates",
    (COALESCE("sum"(
        CASE
            WHEN ("g"."status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text"])) THEN 1
            ELSE 0
        END), (0)::bigint))::integer AS "pending_gates",
    (COALESCE("sum"(
        CASE
            WHEN ("g"."severity" = 'hard_gate'::"text") THEN 1
            ELSE 0
        END), (0)::bigint))::integer AS "hard_gates",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."production_release_artifacts" "a"
          WHERE (("a"."organization_id" = "o"."id") AND ("a"."status" = ANY (ARRAY['generated'::"text", 'verified'::"text", 'approved'::"text"])))) AS "consolidated_artifacts",
    ( SELECT ("count"(*))::integer AS "count"
           FROM "public"."production_pilot_waves" "w"
          WHERE (("w"."organization_id" = "o"."id") AND ("w"."status" = ANY (ARRAY['ready'::"text", 'accepted'::"text"])))) AS "pilot_wave_ready",
    (COALESCE("sum"(
        CASE
            WHEN (("g"."status" = 'blocked'::"text") AND ("g"."severity" = 'hard_gate'::"text")) THEN 1
            ELSE 0
        END), (0)::bigint))::integer AS "unsafe_to_launch"
   FROM ("public"."organizations" "o"
     LEFT JOIN "public"."production_proof_gates" "g" ON (("g"."organization_id" = "o"."id")))
  GROUP BY "o"."id";

CREATE OR REPLACE VIEW "public"."v_v34_company_rollout_readiness" WITH ("security_invoker"='true') AS
 SELECT "o"."id" AS "organization_id",
    "o"."name_en" AS "organization_name_en",
    "count"(DISTINCT "pw"."id") AS "pilot_waves",
    "count"(DISTINCT "pw"."id") FILTER (WHERE ("pw"."status" = 'completed'::"public"."pilot_wave_status")) AS "completed_waves",
    "count"(DISTINCT "pi"."id") FILTER (WHERE ("pi"."status" <> ALL (ARRAY['resolved'::"public"."pilot_issue_status", 'closed'::"public"."pilot_issue_status", 'accepted_risk'::"public"."pilot_issue_status"]))) AS "open_pilot_issues",
    "count"(DISTINCT "pi"."id") FILTER (WHERE (("pi"."severity" = 'critical'::"public"."pilot_issue_severity") AND ("pi"."status" <> ALL (ARRAY['resolved'::"public"."pilot_issue_status", 'closed'::"public"."pilot_issue_status", 'accepted_risk'::"public"."pilot_issue_status"])))) AS "critical_pilot_issues",
    "count"(DISTINCT "rdic"."id") FILTER (WHERE ("rdic"."status" = ANY (ARRAY['ready'::"public"."import_readiness_status", 'imported'::"public"."import_readiness_status"]))) AS "ready_import_areas",
    "count"(DISTINCT "rdic"."id") AS "total_import_areas",
    "count"(DISTINCT "glr"."id") FILTER (WHERE ("glr"."result" = ANY (ARRAY['passed'::"text", 'accepted'::"text"]))) AS "passed_rehearsals",
    "count"(DISTINCT "glr"."id") AS "total_rehearsals",
        CASE
            WHEN ("count"(DISTINCT "pi"."id") FILTER (WHERE (("pi"."severity" = 'critical'::"public"."pilot_issue_severity") AND ("pi"."status" <> ALL (ARRAY['resolved'::"public"."pilot_issue_status", 'closed'::"public"."pilot_issue_status", 'accepted_risk'::"public"."pilot_issue_status"])))) > 0) THEN 'blocked'::"text"
            WHEN ("count"(DISTINCT "rdic"."id") = 0) THEN 'not_ready'::"text"
            WHEN ("count"(DISTINCT "rdic"."id") FILTER (WHERE ("rdic"."status" = ANY (ARRAY['ready'::"public"."import_readiness_status", 'imported'::"public"."import_readiness_status"]))) < "count"(DISTINCT "rdic"."id")) THEN 'warning'::"text"
            WHEN ("count"(DISTINCT "glr"."id") FILTER (WHERE ("glr"."result" = ANY (ARRAY['passed'::"text", 'accepted'::"text"]))) = 0) THEN 'warning'::"text"
            ELSE 'pilot_ready'::"text"
        END AS "rollout_signal"
   FROM (((("public"."organizations" "o"
     LEFT JOIN "public"."pilot_waves" "pw" ON (("pw"."organization_id" = "o"."id")))
     LEFT JOIN "public"."pilot_issues" "pi" ON (("pi"."organization_id" = "o"."id")))
     LEFT JOIN "public"."real_data_import_controls" "rdic" ON (("rdic"."organization_id" = "o"."id")))
     LEFT JOIN "public"."go_live_rehearsals" "glr" ON (("glr"."organization_id" = "o"."id")))
  GROUP BY "o"."id", "o"."name_en";

CREATE OR REPLACE VIEW "public"."v_v34_go_live_rehearsal_readiness" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "id",
    "rehearsal_name",
    "rehearsal_date",
    "result",
    "backup_verified",
    "restore_dry_run_verified",
    "rls_verified",
    "ovr_workflow_verified",
    "export_verified",
    "rollback_plan_verified",
    (((((
        CASE
            WHEN "backup_verified" THEN 1
            ELSE 0
        END +
        CASE
            WHEN "restore_dry_run_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "rls_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "ovr_workflow_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "export_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "rollback_plan_verified" THEN 1
            ELSE 0
        END) AS "verified_steps",
    "round"(((((((((
        CASE
            WHEN "backup_verified" THEN 1
            ELSE 0
        END +
        CASE
            WHEN "restore_dry_run_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "rls_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "ovr_workflow_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "export_verified" THEN 1
            ELSE 0
        END) +
        CASE
            WHEN "rollback_plan_verified" THEN 1
            ELSE 0
        END))::numeric / (6)::numeric) * (100)::numeric), 2) AS "rehearsal_score",
    "notes"
   FROM "public"."go_live_rehearsals";

CREATE OR REPLACE VIEW "public"."v_v34_pilot_issue_board" WITH ("security_invoker"='true') AS
 SELECT "pi"."organization_id",
    "pi"."id",
    "pi"."title",
    "pi"."module_area",
    "pi"."severity",
    "pi"."status",
    "pi"."due_date",
    "pi"."created_at",
    "pi"."resolved_at",
    "pw"."wave_name",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "assignee"."full_name_en" AS "assigned_to_name",
    "reporter"."full_name_en" AS "reported_by_name",
        CASE
            WHEN ("pi"."status" = ANY (ARRAY['resolved'::"public"."pilot_issue_status", 'closed'::"public"."pilot_issue_status", 'accepted_risk'::"public"."pilot_issue_status"])) THEN 'closed'::"text"
            WHEN ("pi"."severity" = 'critical'::"public"."pilot_issue_severity") THEN 'critical'::"text"
            WHEN (("pi"."due_date" IS NOT NULL) AND ("pi"."due_date" < CURRENT_DATE)) THEN 'overdue'::"text"
            WHEN ("pi"."severity" = 'high'::"public"."pilot_issue_severity") THEN 'high'::"text"
            ELSE 'normal'::"text"
        END AS "board_signal"
   FROM (((("public"."pilot_issues" "pi"
     LEFT JOIN "public"."pilot_waves" "pw" ON (("pw"."id" = "pi"."pilot_wave_id")))
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "pi"."department_id")))
     LEFT JOIN "public"."profiles" "assignee" ON (("assignee"."id" = "pi"."assigned_to")))
     LEFT JOIN "public"."profiles" "reporter" ON (("reporter"."id" = "pi"."reported_by")));

CREATE OR REPLACE VIEW "public"."v_v34_pilot_wave_summary" WITH ("security_invoker"='true') AS
 SELECT "pw"."organization_id",
    "pw"."id" AS "pilot_wave_id",
    "pw"."wave_name",
    "pw"."wave_order",
    "pw"."status",
    "pw"."start_date",
    "pw"."end_date",
    "pw"."target_departments",
    "pw"."target_users",
    "pw"."readiness_score",
    "count"(DISTINCT "pwd"."department_id") FILTER (WHERE ("pwd"."included" = true)) AS "included_departments",
    "count"(DISTINCT "pp"."user_id") AS "participants",
    "count"(DISTINCT "pp"."user_id") FILTER (WHERE ("pp"."training_completed" = true)) AS "trained_users",
    "count"(DISTINCT "pp"."user_id") FILTER (WHERE ("pp"."rls_verified" = true)) AS "rls_verified_users",
    "count"(DISTINCT "pi"."id") FILTER (WHERE ("pi"."status" <> ALL (ARRAY['resolved'::"public"."pilot_issue_status", 'closed'::"public"."pilot_issue_status"]))) AS "open_issues",
    "count"(DISTINCT "pi"."id") FILTER (WHERE (("pi"."severity" = 'critical'::"public"."pilot_issue_severity") AND ("pi"."status" <> ALL (ARRAY['resolved'::"public"."pilot_issue_status", 'closed'::"public"."pilot_issue_status"])))) AS "critical_open_issues",
    "count"(DISTINCT "ps"."id") FILTER (WHERE (("ps"."required" = true) AND ("ps"."approved" = true))) AS "approved_signoffs",
    "count"(DISTINCT "ps"."id") FILTER (WHERE ("ps"."required" = true)) AS "required_signoffs"
   FROM (((("public"."pilot_waves" "pw"
     LEFT JOIN "public"."pilot_wave_departments" "pwd" ON (("pwd"."pilot_wave_id" = "pw"."id")))
     LEFT JOIN "public"."pilot_participants" "pp" ON (("pp"."pilot_wave_id" = "pw"."id")))
     LEFT JOIN "public"."pilot_issues" "pi" ON (("pi"."pilot_wave_id" = "pw"."id")))
     LEFT JOIN "public"."pilot_signoffs" "ps" ON (("ps"."pilot_wave_id" = "pw"."id")))
  GROUP BY "pw"."organization_id", "pw"."id", "pw"."wave_name", "pw"."wave_order", "pw"."status", "pw"."start_date", "pw"."end_date", "pw"."target_departments", "pw"."target_users", "pw"."readiness_score";

CREATE OR REPLACE VIEW "public"."v_v34_real_data_import_readiness" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "import_area",
    "status",
    "expected_rows",
    "validated_rows",
    "rejected_rows",
    "duplicate_warnings",
    "missing_required_warnings",
        CASE
            WHEN ("status" = 'blocked'::"public"."import_readiness_status") THEN 'blocked'::"text"
            WHEN ("expected_rows" = 0) THEN 'not_measured'::"text"
            WHEN (("rejected_rows" > 0) OR ("duplicate_warnings" > 0) OR ("missing_required_warnings" > 0)) THEN 'warning'::"text"
            WHEN (("validated_rows" >= "expected_rows") AND ("status" = ANY (ARRAY['ready'::"public"."import_readiness_status", 'imported'::"public"."import_readiness_status"]))) THEN 'ready'::"text"
            ELSE 'in_progress'::"text"
        END AS "readiness_signal",
    "round"(
        CASE
            WHEN ("expected_rows" = 0) THEN (0)::numeric
            ELSE ((("validated_rows")::numeric / (GREATEST("expected_rows", 1))::numeric) * (100)::numeric)
        END, 2) AS "validation_percent",
    "last_validated_at",
    "imported_at",
    "rollback_available",
    "notes"
   FROM "public"."real_data_import_controls";

CREATE OR REPLACE VIEW "public"."v_v38_final_readiness_scorecard" WITH ("security_invoker"='true') AS
 WITH "validation" AS (
         SELECT "count"(*) AS "total",
            "count"(*) FILTER (WHERE ("final_validation_runs"."status" = 'passed'::"text")) AS "passed",
            "count"(*) FILTER (WHERE ("final_validation_runs"."status" = ANY (ARRAY['failed'::"text", 'blocked'::"text"]))) AS "failed_or_blocked",
            COALESCE("avg"("final_validation_runs"."score"), (0)::numeric) AS "avg_score"
           FROM "public"."final_validation_runs"
        ), "evidence" AS (
         SELECT "count"(*) FILTER (WHERE ("production_evidence_registry"."required_for_go_live" = true)) AS "required_total",
            "count"(*) FILTER (WHERE (("production_evidence_registry"."required_for_go_live" = true) AND ("production_evidence_registry"."status" = 'accepted'::"text"))) AS "accepted_total",
            "count"(*) FILTER (WHERE (("production_evidence_registry"."required_for_go_live" = true) AND ("production_evidence_registry"."status" = ANY (ARRAY['missing'::"text", 'rejected'::"text"])))) AS "missing_or_rejected"
           FROM "public"."production_evidence_registry"
        ), "signoffs" AS (
         SELECT "count"(*) FILTER (WHERE ("final_pilot_signoff_matrix"."required_status" = 'required'::"text")) AS "required_total",
            "count"(*) FILTER (WHERE (("final_pilot_signoff_matrix"."required_status" = 'required'::"text") AND ("final_pilot_signoff_matrix"."decision" = ANY (ARRAY['accepted'::"text", 'accepted_with_notes'::"text"])))) AS "accepted_total",
            "count"(*) FILTER (WHERE (("final_pilot_signoff_matrix"."required_status" = 'required'::"text") AND ("final_pilot_signoff_matrix"."decision" = 'rejected'::"text"))) AS "rejected_total"
           FROM "public"."final_pilot_signoff_matrix"
        ), "stops" AS (
         SELECT "count"(*) FILTER (WHERE (("final_go_live_stop_rules"."is_active" = true) AND ("final_go_live_stop_rules"."status" = 'triggered'::"text") AND ("final_go_live_stop_rules"."severity" = 'blocker'::"text"))) AS "active_blockers",
            "count"(*) FILTER (WHERE (("final_go_live_stop_rules"."is_active" = true) AND ("final_go_live_stop_rules"."status" = 'triggered'::"text") AND ("final_go_live_stop_rules"."severity" = 'major'::"text"))) AS "active_major"
           FROM "public"."final_go_live_stop_rules"
        )
 SELECT "round"((((
        CASE
            WHEN ("validation"."total" = 0) THEN (0)::numeric
            ELSE ((("validation"."passed")::numeric / ("validation"."total")::numeric) * (30)::numeric)
        END +
        CASE
            WHEN ("evidence"."required_total" = 0) THEN (0)::numeric
            ELSE ((("evidence"."accepted_total")::numeric / ("evidence"."required_total")::numeric) * (25)::numeric)
        END) +
        CASE
            WHEN ("signoffs"."required_total" = 0) THEN (0)::numeric
            ELSE ((("signoffs"."accepted_total")::numeric / ("signoffs"."required_total")::numeric) * (25)::numeric)
        END) + (
        CASE
            WHEN ("stops"."active_blockers" = 0) THEN 20
            ELSE 0
        END)::numeric), 2) AS "readiness_score",
    "validation"."total" AS "validation_checks",
    "validation"."passed" AS "validation_passed",
    "validation"."failed_or_blocked" AS "validation_failed_or_blocked",
    "round"("validation"."avg_score", 2) AS "average_validation_score",
    "evidence"."required_total" AS "required_evidence",
    "evidence"."accepted_total" AS "accepted_evidence",
    "evidence"."missing_or_rejected" AS "missing_or_rejected_evidence",
    "signoffs"."required_total" AS "required_signoffs",
    "signoffs"."accepted_total" AS "accepted_signoffs",
    "signoffs"."rejected_total" AS "rejected_signoffs",
    "stops"."active_blockers",
    "stops"."active_major",
        CASE
            WHEN ("stops"."active_blockers" > 0) THEN 'blocked'::"text"
            WHEN (("validation"."failed_or_blocked" > 0) OR ("evidence"."missing_or_rejected" > 0) OR ("signoffs"."rejected_total" > 0)) THEN 'not_ready'::"text"
            WHEN ((((
            CASE
                WHEN ("validation"."total" = 0) THEN (0)::numeric
                ELSE ((("validation"."passed")::numeric / ("validation"."total")::numeric) * (30)::numeric)
            END +
            CASE
                WHEN ("evidence"."required_total" = 0) THEN (0)::numeric
                ELSE ((("evidence"."accepted_total")::numeric / ("evidence"."required_total")::numeric) * (25)::numeric)
            END) +
            CASE
                WHEN ("signoffs"."required_total" = 0) THEN (0)::numeric
                ELSE ((("signoffs"."accepted_total")::numeric / ("signoffs"."required_total")::numeric) * (25)::numeric)
            END) + (
            CASE
                WHEN ("stops"."active_blockers" = 0) THEN 20
                ELSE 0
            END)::numeric) >= (90)::numeric) THEN 'ready_for_pilot_or_go_live'::"text"
            ELSE 'needs_work'::"text"
        END AS "readiness_status"
   FROM "validation",
    "evidence",
    "signoffs",
    "stops";

COMMENT ON VIEW "public"."v_v38_final_readiness_scorecard" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v42_release_candidate_scorecard" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_controls",
    "count"(*) FILTER (WHERE ("status" = 'pass'::"text")) AS "passed_controls",
    "count"(*) FILTER (WHERE ("status" = 'warning'::"text")) AS "warning_controls",
    "count"(*) FILTER (WHERE ("status" = 'blocked'::"text")) AS "blocked_controls",
    "count"(*) FILTER (WHERE ("required_for_pilot" AND ("status" = 'pass'::"text"))) AS "pilot_passed_controls",
    "count"(*) FILTER (WHERE "required_for_pilot") AS "pilot_required_controls",
    "count"(*) FILTER (WHERE ("required_for_production" AND ("status" = 'pass'::"text"))) AS "production_passed_controls",
    "count"(*) FILTER (WHERE "required_for_production") AS "production_required_controls",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("status" = 'pass'::"text")))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "overall_score",
        CASE
            WHEN ("count"(*) FILTER (WHERE "required_for_pilot") = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("required_for_pilot" AND ("status" = 'pass'::"text"))))::numeric / ("count"(*) FILTER (WHERE "required_for_pilot"))::numeric) * (100)::numeric), 2)
        END AS "pilot_score",
        CASE
            WHEN ("count"(*) FILTER (WHERE "required_for_production") = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("required_for_production" AND ("status" = 'pass'::"text"))))::numeric / ("count"(*) FILTER (WHERE "required_for_production"))::numeric) * (100)::numeric), 2)
        END AS "production_score"
   FROM "public"."release_candidate_controls";

COMMENT ON VIEW "public"."v_v42_release_candidate_scorecard" IS 'Patch 183 dependent security-invoker view. Browser rows remain constrained by hardened base-table RLS; anon access revoked.';

CREATE OR REPLACE VIEW "public"."v_v42_rls_persona_matrix" WITH ("security_invoker"='true') AS
 SELECT "persona_code",
    "persona_name_en",
    "persona_name_ar",
    "role_name",
    "scope_name",
    "expected_behavior",
    "count"(*) AS "test_count",
    "count"(*) FILTER (WHERE "is_hard_stop") AS "hard_stop_count",
    "string_agg"(DISTINCT "target_module", ', '::"text" ORDER BY "target_module") AS "modules"
   FROM "public"."rls_persona_test_cases"
  GROUP BY "persona_code", "persona_name_en", "persona_name_ar", "role_name", "scope_name", "expected_behavior"
  ORDER BY "persona_code", "expected_behavior";

