CREATE OR REPLACE VIEW "public"."v_v42_rls_test_case_queue" WITH ("security_invoker"='true') AS
 SELECT "tc"."id",
    "tc"."persona_code",
    "tc"."persona_name_en",
    "tc"."role_name",
    "tc"."scope_name",
    "tc"."test_code",
    "tc"."test_name_en",
    "tc"."expected_behavior",
    "tc"."target_module",
    "tc"."priority",
    "tc"."is_hard_stop",
    COALESCE("last_run"."result", 'pending'::"text") AS "last_result",
    "last_run"."tested_at" AS "last_tested_at"
   FROM ("public"."rls_persona_test_cases" "tc"
     LEFT JOIN LATERAL ( SELECT "r"."result",
            "r"."tested_at"
           FROM "public"."rls_persona_test_runs" "r"
          WHERE ("r"."test_case_id" = "tc"."id")
          ORDER BY "r"."created_at" DESC
         LIMIT 1) "last_run" ON (true))
  ORDER BY "tc"."is_hard_stop" DESC, "tc"."priority", "tc"."persona_code", "tc"."test_code";

