CREATE OR REPLACE VIEW "public"."v_v42_rls_readiness_summary" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_test_cases",
    "count"(*) FILTER (WHERE ("last_result" = 'pass'::"text")) AS "passed_cases",
    "count"(*) FILTER (WHERE ("last_result" = 'failed'::"text")) AS "failed_cases",
    "count"(*) FILTER (WHERE ("last_result" = 'pending'::"text")) AS "pending_cases",
    "count"(*) FILTER (WHERE ("is_hard_stop" AND ("last_result" = 'failed'::"text"))) AS "failed_hard_stops",
    "count"(*) FILTER (WHERE ("is_hard_stop" AND ("last_result" = 'pending'::"text"))) AS "pending_hard_stops",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("last_result" = 'pass'::"text")))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "rls_test_score"
   FROM "public"."v_v42_rls_test_case_queue";

CREATE OR REPLACE VIEW "public"."v_v42_supabase_install_status" WITH ("security_invoker"='true') AS
 SELECT "item_type",
