    "count"(*) FILTER (WHERE ("status" = 'missing'::"text")) AS "missing_items",
    "count"(*) FILTER (WHERE ("status" = 'warning'::"text")) AS "warning_items",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("status" = 'verified'::"text")))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "verification_score"
   FROM "public"."supabase_install_verification_items"
