CREATE OR REPLACE VIEW "public"."v_v46_ovr_production_queue" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "ovr_report_id",
    "r"."ovr_number",
    "r"."occurrence_date",
    "r"."occurrence_location",
    "r"."occurrence_category",
    "r"."status",
    "r"."severity_level",
    COALESCE("r"."final_severity_level", "r"."severity_level") AS "confirmed_severity_level",
    "r"."department_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "r"."supervisor_id",
    "r"."quality_reviewer_id",
    "r"."quality_manager_id",
    "r"."corrective_action_required",
    "r"."evidence_required",
    "r"."linked_project_id",
    "r"."rca_required",
    "r"."clinical_escalation_required",
    "r"."executive_visible",
    "r"."patient_safety_flag",
    "r"."occurrence_confirmed_by_quality",
    (( SELECT "count"(*) AS "count"
           FROM "public"."evidence_files" "e"
          WHERE (("e"."ovr_report_id" = "r"."id") AND ("e"."status" = 'accepted'::"public"."evidence_status"))))::integer AS "accepted_evidence_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."ovr_production_checklist_results" "c"
          WHERE (("c"."ovr_report_id" = "r"."id") AND ("c"."result_status" = 'failed'::"text"))))::integer AS "failed_checklist_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."ovr_production_checklist_results" "c"
          WHERE (("c"."ovr_report_id" = "r"."id") AND ("c"."result_status" = 'pending'::"text"))))::integer AS "pending_checklist_count",
        CASE
            WHEN ("r"."status" = 'closed'::"public"."ovr_status") THEN 'closed'::"text"
            WHEN (("r"."severity_level" = ANY (ARRAY['level_4'::"public"."ovr_severity_level", 'sentinel'::"public"."ovr_severity_level"])) AND ("r"."quality_manager_id" IS NULL)) THEN 'needs_quality_manager'::"text"
            WHEN ("r"."evidence_required" AND (NOT (EXISTS ( SELECT 1
               FROM "public"."evidence_files" "e"
              WHERE (("e"."ovr_report_id" = "r"."id") AND ("e"."status" = 'accepted'::"public"."evidence_status")))))) THEN 'needs_accepted_evidence'::"text"
            WHEN (("r"."status" = 'returned_for_clarification'::"public"."ovr_status") AND (COALESCE(NULLIF(TRIM(BOTH FROM "r"."returned_for_clarification_reason"), ''::"text"), ''::"text") = ''::"text")) THEN 'needs_return_reason'::"text"
            WHEN ("r"."status" = ANY (ARRAY['submitted'::"public"."ovr_status", 'under_supervisor_review'::"public"."ovr_status"])) THEN 'needs_supervisor_hod_review'::"text"
            WHEN ("r"."status" = ANY (ARRAY['under_quality_review'::"public"."ovr_status", 'quality_closure_review'::"public"."ovr_status"])) THEN 'needs_quality_review'::"text"
            ELSE 'in_progress'::"text"
        END AS "production_blocker"
   FROM ("public"."ovr_reports" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")));

CREATE OR REPLACE VIEW "public"."v_v46_ovr_risk_calibration" WITH ("security_invoker"='true') AS
 SELECT "r"."organization_id",
    "r"."id" AS "ovr_report_id",
    "r"."ovr_number",
    "r"."department_id",
    "d"."name_en" AS "department_name_en",
    "d"."name_ar" AS "department_name_ar",
    "r"."occurrence_category",
    "r"."severity_level",
    COALESCE("rule"."severity_weight", (
        CASE "r"."severity_level"
            WHEN 'level_1'::"public"."ovr_severity_level" THEN 1
            WHEN 'level_2'::"public"."ovr_severity_level" THEN 2
            WHEN 'level_3'::"public"."ovr_severity_level" THEN 3
            WHEN 'level_4'::"public"."ovr_severity_level" THEN 5
            WHEN 'sentinel'::"public"."ovr_severity_level" THEN 8
            ELSE 1
        END)::numeric) AS "severity_weight",
    (( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "r2"
          WHERE (("r2"."organization_id" = "r"."organization_id") AND (COALESCE("r2"."department_id", '00000000-0000-0000-0000-000000000000'::"uuid") = COALESCE("r"."department_id", '00000000-0000-0000-0000-000000000000'::"uuid")) AND ("r2"."occurrence_category" = "r"."occurrence_category") AND ("r2"."occurrence_date" >= (COALESCE("r"."occurrence_date", CURRENT_DATE) - '30 days'::interval)) AND ("r2"."occurrence_date" <= COALESCE("r"."occurrence_date", CURRENT_DATE)))))::integer AS "recurrence_30d",
    GREATEST(0, COALESCE((CURRENT_DATE - "r"."occurrence_date"), 0)) AS "age_days",
    (((COALESCE("rule"."severity_weight", (
        CASE "r"."severity_level"
            WHEN 'level_1'::"public"."ovr_severity_level" THEN 1
            WHEN 'level_2'::"public"."ovr_severity_level" THEN 2
            WHEN 'level_3'::"public"."ovr_severity_level" THEN 3
            WHEN 'level_4'::"public"."ovr_severity_level" THEN 5
            WHEN 'sentinel'::"public"."ovr_severity_level" THEN 8
            ELSE 1
        END)::numeric) + LEAST((10)::numeric, ((( SELECT "count"(*) AS "count"
           FROM "public"."ovr_reports" "r2"
          WHERE (("r2"."organization_id" = "r"."organization_id") AND (COALESCE("r2"."department_id", '00000000-0000-0000-0000-000000000000'::"uuid") = COALESCE("r"."department_id", '00000000-0000-0000-0000-000000000000'::"uuid")) AND ("r2"."occurrence_category" = "r"."occurrence_category") AND ("r2"."occurrence_date" >= (COALESCE("r"."occurrence_date", CURRENT_DATE) - '30 days'::interval)) AND ("r2"."occurrence_date" <= COALESCE("r"."occurrence_date", CURRENT_DATE)))))::numeric * COALESCE("rule"."recurrence_weight", (1)::numeric)))) +
        CASE
            WHEN (("r"."status" <> ALL (ARRAY['closed'::"public"."ovr_status", 'cancelled'::"public"."ovr_status"])) AND ("r"."occurrence_date" < (CURRENT_DATE - '7 days'::interval))) THEN COALESCE("rule"."closure_delay_weight", (1)::numeric)
            ELSE (0)::numeric
        END))::numeric(10,2) AS "calibrated_risk_score",
        CASE
            WHEN (("r"."severity_level" = 'sentinel'::"public"."ovr_severity_level") OR ("r"."severity_level" = 'level_4'::"public"."ovr_severity_level")) THEN true
            WHEN "rule"."critical_trigger" THEN true
            ELSE false
        END AS "executive_alert_recommended",
    "rule"."rule_code" AS "matching_rule_code"
   FROM (("public"."ovr_reports" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN LATERAL ( SELECT "rr"."id",
            "rr"."organization_id",
            "rr"."rule_code",
            "rr"."rule_name_en",
            "rr"."rule_name_ar",
            "rr"."occurrence_category",
            "rr"."severity_level",
            "rr"."recurrence_window_days",
            "rr"."recurrence_threshold",
            "rr"."severity_weight",
            "rr"."recurrence_weight",
            "rr"."closure_delay_weight",
            "rr"."critical_trigger",
            "rr"."executive_alert",
            "rr"."recommended_action_en",
            "rr"."recommended_action_ar",
            "rr"."is_active",
            "rr"."created_at",
            "rr"."updated_at"
           FROM "public"."ovr_risk_calibration_rules" "rr"
          WHERE (("rr"."is_active" = true) AND (("rr"."organization_id" = "r"."organization_id") OR ("rr"."organization_id" IS NULL)) AND (("rr"."occurrence_category" IS NULL) OR ("rr"."occurrence_category" = "r"."occurrence_category")) AND (("rr"."severity_level" IS NULL) OR ("rr"."severity_level" = "r"."severity_level")))
          ORDER BY ("rr"."organization_id" IS NOT NULL) DESC, ("rr"."occurrence_category" IS NOT NULL) DESC, ("rr"."severity_level" IS NOT NULL) DESC
         LIMIT 1) "rule" ON (true));

CREATE OR REPLACE VIEW "public"."v_v46_production_hardening_scorecard" WITH ("security_invoker"='true') AS
 SELECT COALESCE(( SELECT "v_v46_language_rtl_readiness"."readiness_percent"
           FROM "public"."v_v46_language_rtl_readiness"
          WHERE ("v_v46_language_rtl_readiness"."area" = 'i18n'::"text")), (0)::numeric) AS "i18n_readiness_percent",
    COALESCE(( SELECT "v_v46_language_rtl_readiness"."readiness_percent"
           FROM "public"."v_v46_language_rtl_readiness"
          WHERE ("v_v46_language_rtl_readiness"."area" = 'rtl'::"text")), (0)::numeric) AS "rtl_readiness_percent",
    (( SELECT "count"(*) AS "count"
           FROM "public"."v_v46_ovr_production_queue"
          WHERE ("v_v46_ovr_production_queue"."production_blocker" <> ALL (ARRAY['closed'::"text", 'in_progress'::"text"]))))::integer AS "ovr_blockers",
    (( SELECT "count"(*) AS "count"
           FROM "public"."v_v46_ovr_risk_calibration"
          WHERE ("v_v46_ovr_risk_calibration"."executive_alert_recommended" = true)))::integer AS "executive_ovr_alerts",
    "round"(((((COALESCE(( SELECT "v_v46_language_rtl_readiness"."readiness_percent"
           FROM "public"."v_v46_language_rtl_readiness"
          WHERE ("v_v46_language_rtl_readiness"."area" = 'i18n'::"text")), (0)::numeric) * 0.25) + (COALESCE(( SELECT "v_v46_language_rtl_readiness"."readiness_percent"
           FROM "public"."v_v46_language_rtl_readiness"
          WHERE ("v_v46_language_rtl_readiness"."area" = 'rtl'::"text")), (0)::numeric) * 0.25)) + ((
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v_v46_ovr_production_queue"
              WHERE ("v_v46_ovr_production_queue"."production_blocker" <> ALL (ARRAY['closed'::"text", 'in_progress'::"text"]))) = 0) THEN 100
            ELSE 70
        END)::numeric * 0.30)) + ((
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."ovr_risk_calibration_rules"
              WHERE ("ovr_risk_calibration_rules"."is_active" = true)) >= 5) THEN 100
            ELSE 70
        END)::numeric * 0.20)), 2) AS "v46_readiness_percent";

COMMENT ON VIEW "public"."v_v46_production_hardening_scorecard" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v50_backup_restore_scorecard" WITH ("security_invoker"='true') AS
