CREATE OR REPLACE VIEW "public"."v_v58_audit_trail_scorecard" WITH ("security_invoker"='true') AS
 SELECT (COALESCE("count"(*), (0)::bigint))::integer AS "total_controls",
    (COALESCE("count"(*) FILTER (WHERE ("status" = 'verified'::"text")), (0)::bigint))::integer AS "verified_controls",
    (COALESCE("count"(*) FILTER (WHERE (("status" = 'gap_found'::"text") AND ("required_for_production" = true))), (0)::bigint))::integer AS "production_gaps",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."audit_trail_samples_v58"
          WHERE ("audit_trail_samples_v58"."result" = 'failed'::"text")), (0)::bigint))::integer AS "failed_samples",
        CASE
            WHEN (COALESCE("count"(*) FILTER (WHERE (("status" = 'gap_found'::"text") AND ("required_for_production" = true))), (0)::bigint) > 0) THEN 40
            WHEN ("count"(*) = 0) THEN 25
            ELSE LEAST(100, ("round"(((100.0 * ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['verified'::"text", 'waived'::"text", 'not_applicable'::"text"]))))::numeric) / (GREATEST("count"(*), (1)::bigint))::numeric)))::integer)
        END AS "audit_trail_score"
   FROM "public"."audit_trail_controls_v58";

CREATE OR REPLACE VIEW "public"."v_v58_pilot_readiness_scorecard" WITH ("security_invoker"='true') AS
 SELECT (COALESCE("count"(*), (0)::bigint))::integer AS "pilot_runs",
    (COALESCE("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['active'::"text", 'completed'::"text"]))), (0)::bigint))::integer AS "active_or_completed_runs",
    (COALESCE("count"(*) FILTER (WHERE ("go_no_go" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"]))), (0)::bigint))::integer AS "go_ready_runs",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."pilot_feedback_items"
          WHERE (("pilot_feedback_items"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("pilot_feedback_items"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))), (0)::bigint))::integer AS "high_open_feedback",
        CASE
            WHEN (COALESCE(( SELECT "count"(*) AS "count"
               FROM "public"."pilot_feedback_items"
              WHERE (("pilot_feedback_items"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("pilot_feedback_items"."severity" = 'critical'::"text"))), (0)::bigint) > 0) THEN 45
            WHEN (COALESCE("count"(*) FILTER (WHERE ("go_no_go" = ANY (ARRAY['go'::"text", 'conditional_go'::"text"]))), (0)::bigint) > 0) THEN 90
            WHEN (COALESCE("count"(*), (0)::bigint) > 0) THEN 70
            ELSE 25
        END AS "readiness_score"
   FROM "public"."pilot_execution_runs";

