            WHEN (COALESCE("sum"("blocker_count"), (0)::bigint) > 0) THEN 60
            WHEN ((COALESCE("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['ready'::"text", 'active'::"text", 'completed'::"text"]))), (0)::bigint) = COALESCE("count"(*), (0)::bigint)) AND ("count"(*) > 0)) THEN 95
