CREATE OR REPLACE VIEW "public"."v_v58_security_review_scorecard" WITH ("security_invoker"='true') AS
 SELECT (COALESCE("count"(*), (0)::bigint))::integer AS "total_checks",
    (COALESCE("count"(*) FILTER (WHERE ("status" = 'passed'::"text")), (0)::bigint))::integer AS "passed_checks",
    (COALESCE("count"(*) FILTER (WHERE (("status" = 'failed'::"text") AND ("risk_level" = ANY (ARRAY['critical'::"text", 'high'::"text"])))), (0)::bigint))::integer AS "high_failed_checks",
    (COALESCE(( SELECT "count"(*) AS "count"
           FROM "public"."access_security_findings_v58"
          WHERE (("access_security_findings_v58"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("access_security_findings_v58"."severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))), (0)::bigint))::integer AS "high_open_findings",
        CASE
            WHEN (COALESCE("count"(*) FILTER (WHERE (("status" = 'failed'::"text") AND ("risk_level" = 'critical'::"text"))), (0)::bigint) > 0) THEN 30
            WHEN (COALESCE(( SELECT "count"(*) AS "count"
               FROM "public"."access_security_findings_v58"
              WHERE (("access_security_findings_v58"."status" = ANY (ARRAY['open'::"text", 'in_progress'::"text"])) AND ("access_security_findings_v58"."severity" = 'critical'::"text"))), (0)::bigint) > 0) THEN 35
            WHEN ("count"(*) = 0) THEN 25
            ELSE LEAST(100, ("round"(((100.0 * ("count"(*) FILTER (WHERE ("status" = ANY (ARRAY['passed'::"text", 'waived'::"text"]))))::numeric) / (GREATEST("count"(*), (1)::bigint))::numeric)))::integer)
        END AS "security_score"
   FROM "public"."security_review_checks_v58";

CREATE OR REPLACE VIEW "public"."v_v58_overall_production_readiness" WITH ("security_invoker"='true') AS
 SELECT "p"."readiness_score" AS "pilot_score",
    "r"."rollout_score",
    "s"."security_score",
    "a"."audit_trail_score",
    ("round"(((((("p"."readiness_score" + "r"."rollout_score") + "s"."security_score") + "a"."audit_trail_score"))::numeric / 4.0)))::integer AS "overall_score",
        CASE
            WHEN ("s"."security_score" < 75) THEN 'security_review_required'::"text"
            WHEN ("a"."audit_trail_score" < 75) THEN 'audit_trail_review_required'::"text"
            WHEN ("p"."readiness_score" < 75) THEN 'pilot_not_ready'::"text"
            WHEN ("r"."rollout_score" < 75) THEN 'rollout_not_ready'::"text"
            ELSE 'ready_for_controlled_rollout'::"text"
        END AS "decision"
   FROM ((("public"."v_v58_pilot_readiness_scorecard" "p"
     CROSS JOIN "public"."v_v58_rollout_readiness_scorecard" "r")
     CROSS JOIN "public"."v_v58_security_review_scorecard" "s")
     CROSS JOIN "public"."v_v58_audit_trail_scorecard" "a");

COMMENT ON VIEW "public"."v_v58_overall_production_readiness" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v59_latest_phase_results" AS
SELECT
    NULL::integer AS "phase_number",
    NULL::"text" AS "phase_code",
    NULL::"text" AS "title_en",
    NULL::integer AS "results_recorded",
    NULL::integer AS "passed_results",
    NULL::integer AS "failed_results",
    NULL::"text" AS "phase_status";

COMMENT ON VIEW "public"."v_v59_latest_phase_results" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v59_mock_data_findings_summary" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_findings",
    ("count"(*) FILTER (WHERE ("production_blocking" = true)))::integer AS "production_blocking_findings",
    ("count"(*) FILTER (WHERE ("status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"]))))::integer AS "open_findings",
    ("count"(*) FILTER (WHERE (("production_blocking" = true) AND ("status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"])))))::integer AS "open_production_blockers",
        CASE
            WHEN ("count"(*) FILTER (WHERE (("production_blocking" = true) AND ("status" <> ALL (ARRAY['closed'::"text", 'accepted_risk'::"text"])))) = 0) THEN 'ready'::"text"
            ELSE 'blocked'::"text"
        END AS "no_mock_status"
   FROM "public"."no_mock_audit_findings";

CREATE OR REPLACE VIEW "public"."v_v59_phase_test_scorecard" AS
SELECT
    NULL::integer AS "phase_number",
    NULL::"text" AS "phase_code",
    NULL::"text" AS "title_en",
    NULL::"text" AS "title_ar",
    NULL::"text" AS "command_text",
    NULL::integer AS "test_cases",
    NULL::boolean AS "is_required_for_pilot",
    NULL::boolean AS "is_required_for_production";

COMMENT ON VIEW "public"."v_v59_phase_test_scorecard" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v59_production_data_readiness" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_requirements",
    ("count"(*) FILTER (WHERE ("current_status" = ANY (ARRAY['verified'::"text", 'done'::"text", 'passed'::"text"]))))::integer AS "verified_requirements",
    ("count"(*) FILTER (WHERE ("current_status" = ANY (ARRAY['blocked'::"text", 'failed'::"text"]))))::integer AS "blocked_requirements",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("current_status" = ANY (ARRAY['verified'::"text", 'done'::"text", 'passed'::"text"]))))::numeric / ("count"(*))::numeric) * (100)::numeric), 1)
        END AS "readiness_percent"
   FROM "public"."production_data_switchovers";

COMMENT ON VIEW "public"."v_v59_production_data_readiness" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v60_empty_state_readiness" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_checks",
    "count"(*) FILTER (WHERE ("checked_status" = 'passed'::"text")) AS "passed_checks",
    "count"(*) FILTER (WHERE ("checked_status" <> 'passed'::"text")) AS "open_checks",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("checked_status" = 'passed'::"text")))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "readiness_percent"
   FROM "public"."production_empty_state_checks";

COMMENT ON VIEW "public"."v_v60_empty_state_readiness" IS 'Patch 182 protected legacy evidence view: service-role/protected-RPC read only; browser access revoked.';

CREATE OR REPLACE VIEW "public"."v_v60_latest_no_mock_audit" WITH ("security_invoker"='true') AS
 SELECT "id",
