    "critical_findings",
    "high_findings",
    "medium_findings",
    "files_with_findings",
    "report_path",
    "passed",
    "created_by",
    "created_at"
   FROM "public"."no_mock_audit_runs"
  ORDER BY "created_at" DESC
 LIMIT 1;

CREATE OR REPLACE VIEW "public"."v_v60_no_mock_control_scorecard" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_controls",
    "count"(*) FILTER (WHERE ("current_status" = "required_status")) AS "passed_controls",
    "count"(*) FILTER (WHERE (("current_status" <> "required_status") AND ("severity" = 'critical'::"text"))) AS "critical_open_controls",
    "count"(*) FILTER (WHERE (("current_status" <> "required_status") AND ("severity" = 'high'::"text"))) AS "high_open_controls",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("current_status" = "required_status")))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "readiness_percent"
   FROM "public"."production_data_controls";

CREATE OR REPLACE VIEW "public"."v_v62_demo_boundary_scorecard" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_checks",
    ("count"(*) FILTER (WHERE ("current_state" = "expected_state")))::integer AS "passed_checks",
    ("count"(*) FILTER (WHERE (("current_state" <> "expected_state") AND ("severity" = ANY (ARRAY['critical'::"text", 'high'::"text"])))))::integer AS "blocking_checks",
    ("count"(*) FILTER (WHERE ("current_state" = 'unverified'::"text")))::integer AS "unverified_checks"
   FROM "public"."v62_demo_data_boundary_checks";

CREATE OR REPLACE VIEW "public"."v_v62_real_data_layer_scorecard" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_controls",
    ("count"(*) FILTER (WHERE ("status" = 'passed'::"text")))::integer AS "passed_controls",
    ("count"(*) FILTER (WHERE ("status" = 'unverified'::"text")))::integer AS "unverified_controls",
    ("count"(*) FILTER (WHERE ("required_for_production" AND ("status" <> 'passed'::"text"))))::integer AS "production_open_controls",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("status" = 'passed'::"text")))::numeric / ("count"(*))::numeric) * (100)::numeric), 2)
        END AS "readiness_percent"
   FROM "public"."v62_production_data_layer_controls";

CREATE OR REPLACE VIEW "public"."v_v63_auth_route_protection_scorecard" WITH ("security_invoker"='true') AS
 SELECT ("count"(*))::integer AS "total_controls",
    ("count"(*) FILTER (WHERE ("evidence_status" = 'verified'::"text")))::integer AS "verified_controls",
    ("count"(*) FILTER (WHERE ("evidence_status" = 'unverified'::"text")))::integer AS "unverified_controls",
        CASE
            WHEN ("count"(*) = 0) THEN (0)::numeric
            ELSE "round"(((("count"(*) FILTER (WHERE ("evidence_status" = 'verified'::"text")))::numeric / ("count"(*))::numeric) * (100)::numeric), 1)
        END AS "verified_percent"
   FROM "public"."auth_route_protection_controls";

CREATE OR REPLACE VIEW "public"."v_v64_security_control_scorecard" WITH ("security_invoker"='true') AS
 SELECT "count"(*) AS "total_controls",
    "count"(*) FILTER (WHERE "required") AS "required_controls",
    "count"(*) FILTER (WHERE ("status" = 'passed'::"text")) AS "passed_controls",
    "count"(*) FILTER (WHERE ("status" = 'failed'::"text")) AS "failed_controls",
    "count"(*) FILTER (WHERE ("status" = 'unverified'::"text")) AS "unverified_controls",
    "round"(
        CASE
            WHEN ("count"(*) FILTER (WHERE "required") = 0) THEN (0)::numeric
            ELSE ((100.0 * ("count"(*) FILTER (WHERE ("required" AND ("status" = 'passed'::"text"))))::numeric) / ("count"(*) FILTER (WHERE "required"))::numeric)
        END, 1) AS "required_pass_percent"
   FROM "public"."v64_security_control_catalog";

CREATE OR REPLACE VIEW "public"."v_v64_database_security_readiness" WITH ("security_invoker"='true') AS
 SELECT "now"() AS "generated_at",
    ( SELECT "v_v64_security_control_scorecard"."total_controls"
           FROM "public"."v_v64_security_control_scorecard") AS "total_controls",
    ( SELECT "v_v64_security_control_scorecard"."required_pass_percent"
           FROM "public"."v_v64_security_control_scorecard") AS "required_pass_percent",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v64_persona_test_cases"
          WHERE ("v64_persona_test_cases"."status" = 'passed'::"text")) AS "passed_persona_tests",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v64_persona_test_cases"
          WHERE ("v64_persona_test_cases"."status" = 'failed'::"text")) AS "failed_persona_tests",
    ( SELECT "count"(*) AS "count"
           FROM "public"."v64_persona_test_cases"
          WHERE ("v64_persona_test_cases"."status" = 'unverified'::"text")) AS "unverified_persona_tests",
        CASE
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v64_persona_test_cases"
              WHERE ("v64_persona_test_cases"."status" = 'failed'::"text")) > 0) THEN 'failed'::"text"
            WHEN (( SELECT "count"(*) AS "count"
               FROM "public"."v64_persona_test_cases"
              WHERE ("v64_persona_test_cases"."status" = 'unverified'::"text")) > 0) THEN 'unverified'::"text"
            WHEN (( SELECT "v_v64_security_control_scorecard"."required_pass_percent"
               FROM "public"."v_v64_security_control_scorecard") >= (95)::numeric) THEN 'ready_for_controlled_pilot'::"text"
            ELSE 'needs_evidence'::"text"
        END AS "readiness_status";

CREATE OR REPLACE VIEW "public"."v_v64_persona_test_matrix" WITH ("security_invoker"='true') AS
 SELECT "persona",
    "count"(*) AS "tests",
    "count"(*) FILTER (WHERE "is_negative") AS "negative_tests",
    "count"(*) FILTER (WHERE ("status" = 'passed'::"text")) AS "passed",
    "count"(*) FILTER (WHERE ("status" = 'failed'::"text")) AS "failed",
    "count"(*) FILTER (WHERE ("status" = 'unverified'::"text")) AS "unverified"
   FROM "public"."v64_persona_test_cases"
  GROUP BY "persona"
  ORDER BY "persona";

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_actions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid" NOT NULL,
    "step_id" "uuid",
    "assignment_id" "uuid",
    "actor_id" "uuid",
    "actor_name" "text",
    "action_type" "text" NOT NULL,
    "from_status" "text",
    "to_status" "text",
    "action_comment" "text",
    "action_payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_actions_action_type_check" CHECK (("action_type" = ANY (ARRAY['create'::"text", 'submit'::"text", 'review'::"text", 'approve'::"text", 'reject'::"text", 'request_changes'::"text", 'comment'::"text", 'attach'::"text", 'delegate'::"text", 'escalate'::"text", 'cancel'::"text", 'close'::"text", 'reopen'::"text", 'system_sla'::"text"])))
);

COMMENT ON TABLE "public"."workflow_kernel_actions" IS 'Patch 5 immutable-style workflow activity and approval history log.';

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_instances" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "template_id" "uuid",
    "current_step_id" "uuid",
    "module_key" "text" NOT NULL,
    "source_type" "text" NOT NULL,
    "source_id" "uuid",
    "source_code" "text",
    "workflow_title" "text" NOT NULL,
    "workflow_status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "requester_id" "uuid",
    "requester_name" "text",
    "owner_id" "uuid",
    "owner_name" "text",
    "due_date" "date",
    "submitted_at" timestamp with time zone,
    "closed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_instances_priority_check" CHECK (("priority" = ANY (ARRAY['critical'::"text", 'high'::"text", 'normal'::"text", 'low'::"text"]))),
    CONSTRAINT "workflow_kernel_instances_workflow_status_check" CHECK (("workflow_status" = ANY (ARRAY['draft'::"text", 'submitted'::"text", 'in_review'::"text", 'changes_requested'::"text", 'approved'::"text", 'rejected'::"text", 'closed'::"text", 'cancelled'::"text", 'overdue'::"text"])))
);

COMMENT ON TABLE "public"."workflow_kernel_instances" IS 'Patch 5 live workflow instances with owner, status, priority, due date, and source module linkage.';

CREATE OR REPLACE VIEW "public"."v_workflow_kernel_activity_log" WITH ("security_invoker"='true') AS
 SELECT "a"."organization_id",
    "a"."instance_id",
    "i"."module_key",
    "i"."source_type",
    "i"."source_code",
    "i"."workflow_title",
    "a"."actor_name",
    "a"."action_type",
    "a"."from_status",
    "a"."to_status",
    "a"."action_comment",
    "a"."created_at"
   FROM ("public"."workflow_kernel_actions" "a"
     JOIN "public"."workflow_kernel_instances" "i" ON (("i"."id" = "a"."instance_id")));

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_template_steps" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "template_id" "uuid" NOT NULL,
    "step_code" "text" NOT NULL,
    "step_name" "text" NOT NULL,
    "step_type" "text" DEFAULT 'review'::"text" NOT NULL,
    "sort_order" integer DEFAULT 0 NOT NULL,
    "required_role" "text",
    "default_assignee_id" "uuid",
    "default_assignee_name" "text",
    "sla_hours" integer,
    "requires_comment" boolean DEFAULT false NOT NULL,
    "requires_attachment" boolean DEFAULT false NOT NULL,
    "can_delegate" boolean DEFAULT true NOT NULL,
    "is_terminal" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_template_steps_step_type_check" CHECK (("step_type" = ANY (ARRAY['submit'::"text", 'review'::"text", 'approve'::"text", 'acknowledge'::"text", 'evidence'::"text", 'retest'::"text", 'closure'::"text"])))
);

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_templates" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "workflow_code" "text" NOT NULL,
    "module_key" "text" NOT NULL,
    "workflow_name" "text" NOT NULL,
    "workflow_description" "text",
    "default_priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "default_sla_hours" integer,
    "is_active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_templates_default_priority_check" CHECK (("default_priority" = ANY (ARRAY['critical'::"text", 'high'::"text", 'normal'::"text", 'low'::"text"])))
);

COMMENT ON TABLE "public"."workflow_kernel_templates" IS 'Patch 5 shared workflow template registry across GRC, accreditation, quality, audit, compliance, evidence, and CAPA modules.';

CREATE OR REPLACE VIEW "public"."v_workflow_kernel_module_coverage" WITH ("security_invoker"='true') AS
 SELECT "t"."organization_id",
    "t"."module_key",
    ("count"(DISTINCT "t"."id"))::integer AS "template_count",
    ("count"(DISTINCT "s"."id"))::integer AS "step_count",
    ("count"(DISTINCT "i"."id"))::integer AS "instance_count",
    ("count"(DISTINCT "i"."id") FILTER (WHERE ("i"."workflow_status" = ANY (ARRAY['submitted'::"text", 'in_review'::"text", 'changes_requested'::"text", 'overdue'::"text"]))))::integer AS "active_instance_count"
   FROM (("public"."workflow_kernel_templates" "t"
     LEFT JOIN "public"."workflow_kernel_template_steps" "s" ON (("s"."template_id" = "t"."id")))
     LEFT JOIN "public"."workflow_kernel_instances" "i" ON (("i"."template_id" = "t"."id")))
  GROUP BY "t"."organization_id", "t"."module_key";

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_assignments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid" NOT NULL,
    "step_id" "uuid",
    "assignee_id" "uuid",
    "assignee_name" "text",
    "assignment_role" "text" DEFAULT 'reviewer'::"text" NOT NULL,
    "assignment_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "due_date" "date",
    "completed_at" timestamp with time zone,
    "delegated_from_assignment_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_assignments_assignment_role_check" CHECK (("assignment_role" = ANY (ARRAY['owner'::"text", 'reviewer'::"text", 'approver'::"text", 'observer'::"text", 'delegate'::"text"]))),
    CONSTRAINT "workflow_kernel_assignments_assignment_status_check" CHECK (("assignment_status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text", 'completed'::"text", 'delegated'::"text", 'cancelled'::"text", 'overdue'::"text"])))
);

CREATE OR REPLACE VIEW "public"."v_workflow_kernel_queue" WITH ("security_invoker"='true') AS
 SELECT "i"."organization_id",
    "i"."id" AS "workflow_id",
    "i"."module_key",
    "i"."source_type",
    "i"."source_code",
    "i"."workflow_title",
    "i"."workflow_status",
    "i"."priority",
    "i"."owner_name",
    "i"."due_date" AS "workflow_due_date",
    "a"."id" AS "assignment_id",
    "a"."assignee_name",
    "a"."assignment_role",
    "a"."assignment_status",
    "a"."due_date" AS "assignment_due_date",
        CASE
            WHEN ((COALESCE("a"."due_date", "i"."due_date") IS NOT NULL) AND (COALESCE("a"."due_date", "i"."due_date") < CURRENT_DATE) AND ("i"."workflow_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'overdue'::"text"
            WHEN ((COALESCE("a"."due_date", "i"."due_date") IS NOT NULL) AND (COALESCE("a"."due_date", "i"."due_date") <= (CURRENT_DATE + '7 days'::interval)) AND ("i"."workflow_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text"]))) THEN 'due_soon'::"text"
            WHEN ("i"."priority" = ANY (ARRAY['critical'::"text", 'high'::"text"])) THEN 'high_priority'::"text"
            ELSE 'normal'::"text"
        END AS "queue_signal"
   FROM ("public"."workflow_kernel_instances" "i"
     LEFT JOIN "public"."workflow_kernel_assignments" "a" ON ((("a"."instance_id" = "i"."id") AND ("a"."assignment_status" <> ALL (ARRAY['completed'::"text", 'cancelled'::"text"])))))
  WHERE ("i"."workflow_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text", 'rejected'::"text"]));

CREATE OR REPLACE VIEW "public"."v_workflow_kernel_sla_dashboard" WITH ("security_invoker"='true') AS
 SELECT "organization_id",
    "module_key",
    "workflow_status",
    ("count"(*))::integer AS "workflow_count",
    ("count"(*) FILTER (WHERE (("due_date" IS NOT NULL) AND ("due_date" < CURRENT_DATE) AND ("workflow_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text", 'approved'::"text", 'rejected'::"text"])))))::integer AS "overdue_count",
    ("count"(*) FILTER (WHERE (("due_date" IS NOT NULL) AND (("due_date" >= CURRENT_DATE) AND ("due_date" <= (CURRENT_DATE + '7 days'::interval))))))::integer AS "due_soon_count",
    "min"("due_date") AS "nearest_due_date"
   FROM "public"."workflow_kernel_instances" "i"
  GROUP BY "organization_id", "module_key", "workflow_status";

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid" NOT NULL,
    "step_id" "uuid",
    "attached_by" "uuid",
    "attachment_title" "text" NOT NULL,
    "attachment_url" "text",
    "evidence_id" "uuid",
    "attachment_status" "text" DEFAULT 'submitted'::"text" NOT NULL,
    "review_notes" "text",
    "reviewed_by" "uuid",
    "reviewed_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_attachments_attachment_status_check" CHECK (("attachment_status" = ANY (ARRAY['submitted'::"text", 'accepted'::"text", 'rejected'::"text", 'expired'::"text", 'withdrawn'::"text"])))
);

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_escalations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid" NOT NULL,
    "assignment_id" "uuid",
    "escalation_level" integer DEFAULT 1 NOT NULL,
    "escalation_reason" "text" NOT NULL,
    "escalated_to_id" "uuid",
    "escalated_to_name" "text",
    "escalation_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "escalated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    CONSTRAINT "workflow_kernel_escalations_escalation_status_check" CHECK (("escalation_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'resolved'::"text", 'cancelled'::"text"])))
);

CREATE OR REPLACE VIEW "public"."v_workflow_kernel_summary" WITH ("security_invoker"='true') AS
 SELECT "i"."organization_id",
    ("count"(DISTINCT "i"."id"))::integer AS "workflow_count",
    ("count"(DISTINCT "i"."id") FILTER (WHERE ("i"."workflow_status" = ANY (ARRAY['submitted'::"text", 'in_review'::"text", 'changes_requested'::"text", 'overdue'::"text"]))))::integer AS "active_workflow_count",
    ("count"(DISTINCT "i"."id") FILTER (WHERE (("i"."workflow_status" = 'overdue'::"text") OR (("i"."due_date" IS NOT NULL) AND ("i"."due_date" < CURRENT_DATE) AND ("i"."workflow_status" <> ALL (ARRAY['closed'::"text", 'cancelled'::"text", 'approved'::"text", 'rejected'::"text"]))))))::integer AS "overdue_workflow_count",
    ("count"(DISTINCT "a"."id") FILTER (WHERE ("a"."assignment_status" = ANY (ARRAY['pending'::"text", 'in_progress'::"text", 'overdue'::"text"]))))::integer AS "open_assignment_count",
    ("count"(DISTINCT "e"."id") FILTER (WHERE ("e"."escalation_status" = 'open'::"text")))::integer AS "open_escalation_count",
    ("count"(DISTINCT "att"."id") FILTER (WHERE ("att"."attachment_status" = ANY (ARRAY['submitted'::"text", 'rejected'::"text", 'expired'::"text"]))))::integer AS "evidence_attention_count",
    ("count"(DISTINCT "i"."module_key"))::integer AS "module_count"
   FROM ((("public"."workflow_kernel_instances" "i"
     LEFT JOIN "public"."workflow_kernel_assignments" "a" ON (("a"."instance_id" = "i"."id")))
     LEFT JOIN "public"."workflow_kernel_escalations" "e" ON (("e"."instance_id" = "i"."id")))
     LEFT JOIN "public"."workflow_kernel_attachments" "att" ON (("att"."instance_id" = "i"."id")))
  GROUP BY "i"."organization_id";

COMMENT ON VIEW "public"."v_workflow_kernel_summary" IS 'Patch 5 workflow kernel summary; security_invoker keeps RLS active.';

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_comments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid" NOT NULL,
    "step_id" "uuid",
    "author_id" "uuid",
    "author_name" "text",
    "comment_body" "text" NOT NULL,
    "comment_visibility" "text" DEFAULT 'internal'::"text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_comments_comment_visibility_check" CHECK (("comment_visibility" = ANY (ARRAY['internal'::"text", 'reviewers'::"text", 'auditors'::"text", 'external_read_only'::"text"])))
);

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_notifications" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid",
    "assignment_id" "uuid",
    "recipient_id" "uuid",
    "recipient_name" "text",
    "channel" "text" DEFAULT 'in_app'::"text" NOT NULL,
    "notification_type" "text" DEFAULT 'assignment'::"text" NOT NULL,
    "notification_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "sent_at" timestamp with time zone,
    "read_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_notifications_channel_check" CHECK (("channel" = ANY (ARRAY['in_app'::"text", 'email'::"text", 'sms'::"text", 'teams'::"text", 'system'::"text"]))),
    CONSTRAINT "workflow_kernel_notifications_notification_status_check" CHECK (("notification_status" = ANY (ARRAY['pending'::"text", 'sent'::"text", 'failed'::"text", 'cancelled'::"text", 'read'::"text"]))),
    CONSTRAINT "workflow_kernel_notifications_notification_type_check" CHECK (("notification_type" = ANY (ARRAY['assignment'::"text", 'sla_due_soon'::"text", 'overdue'::"text", 'escalation'::"text", 'approval_needed'::"text", 'changes_requested'::"text", 'closed'::"text"])))
);

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_raci" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "template_id" "uuid",
    "module_key" "text" NOT NULL,
    "source_type" "text",
    "actor_id" "uuid",
    "actor_name" "text",
    "role_type" "text" NOT NULL,
    "is_default" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "workflow_kernel_raci_role_type_check" CHECK (("role_type" = ANY (ARRAY['responsible'::"text", 'accountable'::"text", 'consulted'::"text", 'informed'::"text"])))
);

CREATE TABLE IF NOT EXISTS "public"."workflow_kernel_sla_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "organization_id" "uuid" NOT NULL,
    "instance_id" "uuid" NOT NULL,
    "assignment_id" "uuid",
    "event_type" "text" NOT NULL,
    "event_status" "text" DEFAULT 'open'::"text" NOT NULL,
    "triggered_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "resolved_at" timestamp with time zone,
    "notes" "text",
    CONSTRAINT "workflow_kernel_sla_events_event_status_check" CHECK (("event_status" = ANY (ARRAY['open'::"text", 'acknowledged'::"text", 'resolved'::"text", 'cancelled'::"text"]))),
    CONSTRAINT "workflow_kernel_sla_events_event_type_check" CHECK (("event_type" = ANY (ARRAY['due_soon'::"text", 'overdue'::"text", 'escalated'::"text", 'resolved'::"text", 'paused'::"text", 'resumed'::"text"])))
);

COMMENT ON TABLE "public"."workflow_kernel_sla_events" IS 'Patch 5 SLA and escalation signal log for due soon, overdue, escalated, and resolved events.';

