CREATE OR REPLACE VIEW "public"."v_access_control_matrix" WITH ("security_invoker"='true') AS
 SELECT "p"."organization_id",
    "p"."id" AS "user_id",
    "p"."employee_no",
    "p"."full_name_en",
    "p"."full_name_ar",
    "p"."email",
    "p"."job_title",
    "p"."is_active" AS "user_active",
    "d"."name_en" AS "division_name",
    "dep"."name_en" AS "department_name",
    "u"."name_en" AS "unit_name",
    COALESCE("count"("ur"."id") FILTER (WHERE ("ur"."is_active" = true)), (0)::bigint) AS "active_role_count",
    COALESCE("jsonb_agg"("jsonb_build_object"('user_role_id', "ur"."id", 'role', "ur"."role", 'scope', "ur"."scope", 'organization_id', "ur"."organization_id", 'division_id', "ur"."division_id", 'department_id', "ur"."department_id", 'unit_id', "ur"."unit_id", 'is_active', "ur"."is_active", 'assigned_at', "ur"."assigned_at") ORDER BY ("ur"."role")::"text") FILTER (WHERE ("ur"."id" IS NOT NULL)), '[]'::"jsonb") AS "roles",
    ( SELECT "count"(*) AS "count"
           FROM "public"."projects" "pr"
          WHERE (("pr"."owner_id" = "p"."id") AND ("pr"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))) AS "owned_open_projects",
    ( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE ((("t"."owner_id" = "p"."id") OR ("t"."assigned_to" = "p"."id")) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))) AS "open_tasks",
    ( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."approver_id" = "p"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))) AS "pending_approvals"
   FROM (((("public"."profiles" "p"
     LEFT JOIN "public"."divisions" "d" ON (("d"."id" = "p"."division_id")))
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
     LEFT JOIN "public"."units" "u" ON (("u"."id" = "p"."unit_id")))
     LEFT JOIN "public"."user_roles" "ur" ON (("ur"."user_id" = "p"."id")))
  GROUP BY "p"."id", "d"."name_en", "dep"."name_en", "u"."name_en";

CREATE OR REPLACE VIEW "public"."v_patch24_audit_closure_pack_index" WITH ("security_invoker"='true') AS
 SELECT "af"."organization_id",
    "af"."id" AS "audit_finding_id",
    "af"."finding_code",
    "af"."title",
    "af"."audit_title",
    "af"."finding_status",
    "af"."severity_level",
    "af"."management_response_status",
    "af"."corrective_action_status",
    "af"."closure_validation_status",
    "af"."closure_pack_reference",
    "af"."closure_pack_generated_at",
    "cg"."evidence_required",
    "cg"."accepted_evidence_count",
    "cg"."minimum_accepted_evidence_count",
    "cg"."approved_waiver_count",
    "cg"."evidence_gate_status",
    "cg"."can_close",
    "cg"."closure_blocker",
    "af"."closure_validated_by",
    "validator"."full_name_en" AS "closure_validator_name",
    "af"."closure_validated_at",
    ("count"("ep"."evidence_file_id"))::integer AS "linked_evidence_count"
   FROM ((("public"."audit_findings" "af"
     LEFT JOIN "public"."v_patch24_audit_closure_gate_status" "cg" ON (("cg"."audit_finding_id" = "af"."id")))
     LEFT JOIN "public"."v_patch23_evidence_pack_index" "ep" ON ((("ep"."linked_item_type" = 'audit_finding'::"text") AND ("ep"."linked_item_id" = "af"."id"))))
     LEFT JOIN "public"."profiles" "validator" ON (("validator"."id" = "af"."closure_validated_by")))
  GROUP BY "af"."organization_id", "af"."id", "cg"."evidence_required", "cg"."accepted_evidence_count", "cg"."minimum_accepted_evidence_count", "cg"."approved_waiver_count", "cg"."evidence_gate_status", "cg"."can_close", "cg"."closure_blocker", "validator"."full_name_en";

CREATE OR REPLACE VIEW "public"."v_patch37_audit_engagement_register" WITH ("security_invoker"='true') AS
 SELECT "e"."id",
    "e"."engagement_title",
    "e"."engagement_type",
    "e"."scope_summary",
    "e"."department_id",
    "e"."lead_auditor_user_id",
    "e"."status",
    "e"."starts_on",
    "e"."ends_on",
    "e"."created_by",
    "e"."created_at",
    "e"."closed_at",
    COALESCE("d"."name_en", "d"."name_ar") AS "department_name",
    COALESCE("p"."full_name_en", "p"."full_name_ar", "p"."email") AS "lead_auditor_name",
    "count"(DISTINCT "pr"."id") AS "program_count",
    "count"(DISTINCT "ts"."id") AS "test_step_count",
    "count"(DISTINCT "ts"."id") FILTER (WHERE ("ts"."status" = 'completed'::"text")) AS "completed_step_count",
    "count"(DISTINCT "f"."id") FILTER (WHERE ("f"."finding_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text"]))) AS "open_finding_count",
    "count"(DISTINCT "s"."id") FILTER (WHERE ("s"."signoff_status" = 'pending'::"text")) AS "pending_signoff_count"
   FROM (((((("public"."audit_execution_engagements" "e"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "e"."department_id")))
     LEFT JOIN "public"."profiles" "p" ON (("p"."id" = "e"."lead_auditor_user_id")))
     LEFT JOIN "public"."audit_execution_programs" "pr" ON (("pr"."engagement_id" = "e"."id")))
     LEFT JOIN "public"."audit_execution_test_steps" "ts" ON (("ts"."program_id" = "pr"."id")))
     LEFT JOIN "public"."audit_execution_findings" "f" ON (("f"."engagement_id" = "e"."id")))
     LEFT JOIN "public"."audit_execution_signoffs" "s" ON (("s"."engagement_id" = "e"."id")))
  GROUP BY "e"."id", COALESCE("d"."name_en", "d"."name_ar"), COALESCE("p"."full_name_en", "p"."full_name_ar", "p"."email");

CREATE OR REPLACE VIEW "public"."v_patch37_ovr_rca_case_register" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."ovr_id",
    "r"."incident_reference",
    "r"."rca_title",
    "r"."rca_status",
    "r"."severity",
    "r"."department_id",
    "r"."owner_user_id",
    "r"."due_date",
    "r"."root_cause_summary",
    "r"."created_by",
    "r"."created_at",
    "r"."closed_at",
    COALESCE("d"."name_en", "d"."name_ar") AS "department_name",
    COALESCE("owner"."full_name_en", "owner"."full_name_ar", "owner"."email") AS "owner_name",
    "count"("l"."id") FILTER (WHERE ("l"."link_status" = ANY (ARRAY['active'::"text", 'accepted'::"text"]))) AS "active_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'capa'::"text") AND ("l"."link_status" = ANY (ARRAY['active'::"text", 'accepted'::"text"])))) AS "capa_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'evidence_bridge'::"text") AND ("l"."link_status" = ANY (ARRAY['active'::"text", 'accepted'::"text"])))) AS "evidence_bridge_link_count",
    "count"("l"."id") FILTER (WHERE (("l"."linked_entity_type" = 'accreditation_clause'::"text") AND ("l"."link_status" = ANY (ARRAY['active'::"text", 'accepted'::"text"])))) AS "accreditation_clause_link_count",
        CASE
            WHEN (("r"."due_date" IS NOT NULL) AND ("r"."due_date" < CURRENT_DATE) AND ("r"."rca_status" <> ALL (ARRAY['closed'::"text", 'waived'::"text", 'cancelled'::"text"]))) THEN true
            ELSE false
        END AS "is_overdue"
   FROM ((("public"."ovr_rca_cases" "r"
     LEFT JOIN "public"."departments" "d" ON (("d"."id" = "r"."department_id")))
     LEFT JOIN "public"."profiles" "owner" ON (("owner"."id" = "r"."owner_user_id")))
     LEFT JOIN "public"."ovr_capa_evidence_links" "l" ON (("l"."rca_case_id" = "r"."id")))
  GROUP BY "r"."id", COALESCE("d"."name_en", "d"."name_ar"), COALESCE("owner"."full_name_en", "owner"."full_name_ar", "owner"."email");

CREATE OR REPLACE VIEW "public"."v_qa_test_runs_summary" WITH ("security_invoker"='true') AS
 SELECT "r"."id",
    "r"."organization_id",
    "r"."title",
    "r"."scope",
    ("r"."status")::"text" AS "status",
    "r"."started_at",
    "r"."completed_at",
    ("count"("res"."id"))::integer AS "total_cases",
    ("count"("res"."id") FILTER (WHERE ("res"."result_status" = 'passed'::"public"."qa_result_status")))::integer AS "passed_cases",
    ("count"("res"."id") FILTER (WHERE ("res"."result_status" = 'failed'::"public"."qa_result_status")))::integer AS "failed_cases",
    ("count"("res"."id") FILTER (WHERE ("res"."result_status" = 'blocked'::"public"."qa_result_status")))::integer AS "blocked_cases"
   FROM ("public"."qa_test_runs" "r"
     LEFT JOIN "public"."qa_test_results" "res" ON (("res"."run_id" = "r"."id")))
  GROUP BY "r"."id";

CREATE OR REPLACE VIEW "public"."v_user_management_roster" WITH ("security_invoker"='true') AS
 SELECT "p"."organization_id",
    "p"."id" AS "user_id",
    "p"."employee_no",
    "p"."full_name_en",
    "p"."full_name_ar",
    "p"."email",
    "p"."phone",
    "p"."job_title",
    COALESCE("p"."user_type", 'employee'::"text") AS "user_type",
    COALESCE("p"."user_status", 'active'::"text") AS "user_status",
    "p"."is_active",
    "p"."created_at",
    "p"."updated_at",
    "p"."last_login_at",
    "p"."last_reviewed_at",
    "p"."deactivated_at",
    "p"."deactivated_by",
    "p"."deactivation_reason",
    "p"."division_id",
    "div"."name_en" AS "division_name",
    "p"."department_id",
    "dep"."code" AS "department_code",
    "dep"."name_en" AS "department_name",
    "dep"."name_ar" AS "department_name_ar",
    "p"."unit_id",
    "unit"."name_en" AS "unit_name",
    (COALESCE("count"("ur"."id") FILTER (WHERE ("ur"."is_active" = true)), (0)::bigint))::integer AS "active_role_count",
    COALESCE("jsonb_agg"("jsonb_build_object"('user_role_id', "ur"."id", 'role', "ur"."role", 'scope', "ur"."scope", 'organization_id', "ur"."organization_id", 'department_id', "ur"."department_id", 'is_active', "ur"."is_active", 'assigned_at', "ur"."assigned_at") ORDER BY ("ur"."role")::"text") FILTER (WHERE ("ur"."id" IS NOT NULL)), '[]'::"jsonb") AS "roles",
    (( SELECT "count"(*) AS "count"
           FROM "public"."projects" "pr"
          WHERE (("pr"."owner_id" = "p"."id") OR ("pr"."sponsor_id" = "p"."id"))))::integer AS "linked_project_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE (("t"."owner_id" = "p"."id") OR ("t"."assigned_to" = "p"."id"))))::integer AS "linked_task_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."requested_by" = "p"."id") OR ("a"."approver_id" = "p"."id"))))::integer AS "linked_approval_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."evidence_files" "e"
          WHERE (("e"."uploaded_by" = "p"."id") OR ("e"."reviewed_by" = "p"."id"))))::integer AS "linked_evidence_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."projects" "pr"
          WHERE ((("pr"."owner_id" = "p"."id") OR ("pr"."sponsor_id" = "p"."id")) AND ("pr"."status" <> ALL (ARRAY['closed'::"public"."project_status", 'cancelled'::"public"."project_status"])))))::integer AS "open_project_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."tasks" "t"
          WHERE ((("t"."owner_id" = "p"."id") OR ("t"."assigned_to" = "p"."id")) AND ("t"."status" <> ALL (ARRAY['closed'::"public"."work_status", 'approved'::"public"."work_status", 'cancelled'::"public"."work_status"])))))::integer AS "open_task_count",
    (( SELECT "count"(*) AS "count"
           FROM "public"."approvals" "a"
          WHERE (("a"."approver_id" = "p"."id") AND ("a"."status" = 'pending'::"public"."approval_status"))))::integer AS "pending_approval_count"
   FROM (((("public"."profiles" "p"
     LEFT JOIN "public"."divisions" "div" ON (("div"."id" = "p"."division_id")))
     LEFT JOIN "public"."departments" "dep" ON (("dep"."id" = "p"."department_id")))
     LEFT JOIN "public"."units" "unit" ON (("unit"."id" = "p"."unit_id")))
     LEFT JOIN "public"."user_roles" "ur" ON (("ur"."user_id" = "p"."id")))
  GROUP BY "p"."id", "div"."name_en", "dep"."code", "dep"."name_en", "dep"."name_ar", "unit"."name_en";

CREATE OR REPLACE VIEW "public"."v_v50_restore_dryrun_queue" WITH ("security_invoker"='true') AS
 SELECT "j"."id",
    "j"."job_code",
    "j"."title_en",
    "j"."title_ar",
    "j"."restore_environment",
    "j"."planned_date",
    "j"."result",
    "j"."owner_name",
    "j"."approver_name",
    "count"("s"."id") AS "total_steps",
    "count"("s"."id") FILTER (WHERE ("s"."status" = 'passed'::"public"."v50_control_status")) AS "passed_steps",
    "count"("s"."id") FILTER (WHERE ("s"."status" = 'blocked'::"public"."v50_control_status")) AS "blocked_steps",
    "j"."created_at",
    "j"."updated_at"
   FROM ("public"."v50_restore_dryrun_jobs" "j"
     LEFT JOIN "public"."v50_restore_dryrun_steps" "s" ON (("s"."job_id" = "j"."id")))
  GROUP BY "j"."id"
  ORDER BY "j"."planned_date", "j"."created_at" DESC;

CREATE OR REPLACE VIEW "public"."v_v59_latest_phase_results" WITH ("security_invoker"='true') AS
 WITH "latest_run" AS (
         SELECT "phased_auto_test_runs"."id"
           FROM "public"."phased_auto_test_runs"
          ORDER BY "phased_auto_test_runs"."started_at" DESC
         LIMIT 1
        )
 SELECT "p"."phase_number",
    "p"."phase_code",
    "p"."title_en",
    (COALESCE("count"("r"."id"), (0)::bigint))::integer AS "results_recorded",
    (COALESCE("count"("r"."id") FILTER (WHERE ("r"."result_status" = 'passed'::"text")), (0)::bigint))::integer AS "passed_results",
    (COALESCE("count"("r"."id") FILTER (WHERE ("r"."result_status" = 'failed'::"text")), (0)::bigint))::integer AS "failed_results",
        CASE
            WHEN ("count"("r"."id") = 0) THEN 'not_run'::"text"
            WHEN ("count"("r"."id") FILTER (WHERE ("r"."result_status" = 'failed'::"text")) > 0) THEN 'failed'::"text"
            ELSE 'passed'::"text"
        END AS "phase_status"
   FROM ("public"."phased_auto_test_phases" "p"
     LEFT JOIN "public"."phased_auto_test_results" "r" ON ((("r"."phase_id" = "p"."id") AND ("r"."run_id" IN ( SELECT "latest_run"."id"
           FROM "latest_run")))))
  GROUP BY "p"."id"
  ORDER BY "p"."phase_number";

CREATE OR REPLACE VIEW "public"."v_v59_phase_test_scorecard" WITH ("security_invoker"='true') AS
 SELECT "p"."phase_number",
    "p"."phase_code",
    "p"."title_en",
    "p"."title_ar",
    "p"."command_text",
    ("count"("c"."id"))::integer AS "test_cases",
    "p"."is_required_for_pilot",
    "p"."is_required_for_production"
   FROM ("public"."phased_auto_test_phases" "p"
     LEFT JOIN "public"."phased_auto_test_cases" "c" ON ((("c"."phase_id" = "p"."id") AND ("c"."is_active" = true))))
  GROUP BY "p"."id"
  ORDER BY "p"."phase_number";

