CREATE POLICY "Authenticated can manage own report definitions" ON "public"."report_definitions" TO "authenticated" USING ((("created_by" = "auth"."uid"()) OR ("is_system" = true))) WITH CHECK ((("created_by" = "auth"."uid"()) OR ("is_system" = false)));

