CREATE POLICY "ovr_reports_read_related" ON "public"."ovr_reports" FOR SELECT TO "authenticated" USING ((("reported_by" = "auth"."uid"()) OR ("owner_id" = "auth"."uid"()) OR ("supervisor_id" = "auth"."uid"()) OR ("quality_reviewer_id" = "auth"."uid"()) OR ("quality_manager_id" = "auth"."uid"()) OR ("referred_user_id" = "auth"."uid"()) OR (EXISTS ( SELECT 1
