  WHERE (("ur"."user_id" = "auth"."uid"()) AND ("ur"."is_active" = true) AND ("ur"."role" = 'department_manager'::"public"."app_role") AND (NOT ("ur"."organization_id" IS DISTINCT FROM "ovr_reports"."organization_id")) AND (("ur"."scope" = 'global'::"public"."access_scope") OR (("ur"."scope" = 'department'::"public"."access_scope") AND ((NOT ("ur"."department_id" IS DISTINCT FROM "ovr_reports"."department_id")) OR (NOT ("ur"."department_id" IS DISTINCT FROM "ovr_reports"."referred_department_id")))))))) OR (EXISTS ( SELECT 1
   FROM "public"."user_roles" "ur"
  WHERE (("ur"."user_id" = "auth"."uid"()) AND ("ur"."is_active" = true) AND ("ur"."role" = ANY (ARRAY['super_admin'::"public"."app_role", 'executive'::"public"."app_role", 'governance_admin'::"public"."app_role", 'auditor'::"public"."app_role", 'compliance_officer'::"public"."app_role"])) AND (("ur"."organization_id" IS NULL) OR (NOT ("ur"."organization_id" IS DISTINCT FROM "ovr_reports"."organization_id"))))))));

