-- Approved immutable structural seed. It contains no person, tenant, or hosted
-- environment identifier and keeps an empty bootstrap fail-closed.
INSERT INTO "public"."patch83u_runtime_control" (
  "singleton", "schema_version", "enforcement_state",
  "expected_edge_contract_version", "expected_frontend_contract_version",
  "compatible_edge_contract_version", "compatible_frontend_contract_version",
  "state_version", "created_at", "updated_at"
) VALUES (
  true, '174.2-auth-first', 'disabled',
  'patch83u-edge-auth-first-v1', 'patch83u-frontend-auth-first-v1',
  NULL, NULL,
  0, TIMESTAMPTZ '1970-01-01 00:00:00+00', TIMESTAMPTZ '1970-01-01 00:00:00+00'
);

DO $gate11_validate$
DECLARE
  actual_tables integer;
  actual_views integer;
  actual_functions integer;
  actual_policies integer;
BEGIN
  SELECT count(*) INTO actual_tables FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p');
  SELECT count(*) INTO actual_views FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m');
  SELECT count(*) INTO actual_functions FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public';
  SELECT count(*) INTO actual_policies FROM pg_policy p JOIN pg_class c ON c.oid=p.polrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public';
  IF actual_tables <> 607 OR actual_views <> 528
     OR actual_functions <> 530 OR actual_policies <> 1978 THEN
    RAISE EXCEPTION 'GATE11_BASELINE_OBJECT_COUNT_MISMATCH tables=% views=% functions=% policies=%', actual_tables, actual_views, actual_functions, actual_policies;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.patch83u_runtime_control
    WHERE singleton AND enforcement_state='disabled' AND state_version=0
      AND compatible_edge_contract_version IS NULL
      AND compatible_frontend_contract_version IS NULL
      AND designated_super_admin_id IS NULL
  ) THEN
    RAISE EXCEPTION 'GATE11_RUNTIME_STRUCTURAL_SEED_INVALID';
  END IF;
END
$gate11_validate$;

COMMIT;
